INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-triplet-sum-to-zero',
  'Triplet Sum to Zero',
  'medium',
  'Triplet Sum to Zero

Problem Statement

Given an array of unsorted integers, find **all unique triplets** that sum to zero. The solution must not contain duplicate triplets.

Examples',
  '',
  '[{"input":"[-3, 0, 1, 2, -1, 1, -2]","output":"[[-3, 1, 2], [-2, 0, 2], [-2, 1, 1], [-1, 0, 1]]"},{"input":"[-5, 2, -1, -2, 3]","output":"[[-5, 2, 3], [-2, -1, 3]]"},{"input":"[0, 0, 0]","output":"[[0, 0, 0]]"}]'::jsonb,
  'search_triplets',
  E'def search_triplets(arr):\n    # TODO: implement using sort + two pointers\n    pass\n\n# Expected: [[-3, 1, 2], [-2, 0, 2], [-2, 1, 1], [-1, 0, 1]]\n# Expected: [[-5, 2, 3], [-2, -1, 3]]\n# Expected: [[0, 0, 0]]',
  E'def search_triplets(arr):\n    arr.sort()\n    triplets = []\n    for i in range(len(arr) - 2):\n        if i > 0 and arr[i] == arr[i - 1]:\n            continue  # skip duplicate for i\n        left, right = i + 1, len(arr) - 1\n        while left < right:\n            total = arr[i] + arr[left] + arr[right]\n            if total == 0:\n                triplets.append([arr[i], arr[left], arr[right]])\n                left += 1\n                right -= 1\n                while left < right and arr[left] == arr[left - 1]:\n                    left += 1\n                while left < right and arr[right] == arr[right + 1]:\n                    right -= 1\n            elif total < 0:\n                left += 1\n            else:\n                right -= 1\n    return triplets\n\n# Expected: [[-3, 1, 2], [-2, 0, 2], [-2, 1, 1], [-1, 0, 1]]\n# Expected: [[-5, 2, 3], [-2, -1, 3]]\n# Expected: [[0, 0, 0]]',
  E'class Solution {\n    public Object searchTriplets(int[] arr) {\n        // Your code here\n        return null;\n    }\n}',
  E'// Required imports: java.util.List, java.util.ArrayList, java.util.Arrays\nclass Solution {\n    public static List<List<Integer>> searchTriplets(int[] arr) {\n        Arrays.sort(arr);\n        List<List<Integer>> triplets = new ArrayList<>();\n        for (int i = 0; i < arr.length - 2; i++) {\n            if (i > 0 && arr[i] == arr[i - 1]) {\n                continue; // skip duplicate for i\n            }\n            int left = i + 1;\n            int right = arr.length - 1;\n            while (left < right) {\n                int total = arr[i] + arr[left] + arr[right];\n                if (total == 0) {\n                    triplets.add(Arrays.asList(arr[i], arr[left], arr[right]));\n                    left++;\n                    right--;\n                    while (left < right && arr[left] == arr[left - 1]) {\n                        left++;\n                    }\n                    while (left < right && arr[right] == arr[right + 1]) {\n                        right--;\n                    }\n                } else if (total < 0) {\n                    left++;\n                } else {\n                    right--;\n                }\n            }\n        }\n        return triplets;\n    }\n}',
  E'/**\n * @param {any} arr\n * @return {any}\n */\nfunction searchTriplets(arr) {\n    // Your code here\n}',
  E'function searchTriplets(arr) {\n    arr.sort((a, b) => a - b);\n    const triplets = [];\n    for (let i = 0; i < arr.length - 2; i++) {\n        if (i > 0 && arr[i] === arr[i - 1]) {\n            continue; // skip duplicate for i\n        }\n        let left = i + 1;\n        let right = arr.length - 1;\n        while (left < right) {\n            const total = arr[i] + arr[left] + arr[right];\n            if (total === 0) {\n                triplets.push([arr[i], arr[left], arr[right]]);\n                left++;\n                right--;\n                while (left < right && arr[left] === arr[left - 1]) {\n                    left++;\n                }\n                while (left < right && arr[right] === arr[right + 1]) {\n                    right--;\n                }\n            } else if (total < 0) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n    }\n    return triplets;\n}',
  ARRAY['two-pointers'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'apple-ict3', 'linkedin-swe'],
  'two-pointers',
  '[{"input":"search_triplets([-3, 0, 1, 2, -1, 1, -2])","expected_output":"[[-3, 1, 2], [-2, 0, 2], [-2, 1, 1], [-1, 0, 1]]"},{"input":"search_triplets([-5, 2, -1, -2, 3])","expected_output":"[[-5, 2, 3], [-2, -1, 3]]"},{"input":"search_triplets([0, 0, 0])","expected_output":"[[0, 0, 0]]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
  description = EXCLUDED.description,
  constraints = EXCLUDED.constraints,
  examples = EXCLUDED.examples,
  function_name = EXCLUDED.function_name,
  starter_code_python = EXCLUDED.starter_code_python,
  solution_code_python = EXCLUDED.solution_code_python,
  starter_code_java = EXCLUDED.starter_code_java,
