INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-linked-list-cycle',
  'Linked List Cycle',
  'easy',
  'Linked List Cycle Detection

Problem Statement

Given the head of a singly linked list, determine whether the list contains a **cycle**. A cycle exists if some node''s `next` pointer points back to a previously visited node.

We represent the linked list with a `ListNode` class and build it from an array plus a `cycle_pos` parameter indicating which index the tail connects back to (`-1` means no cycle).

Examples',
  '',
  '[{"input":"nodes = [1, 2, 3, 4, 5, 6], cycle_pos = 2","output":"True","explanation":"Node 6 points back to node at index 2 (value 3), forming a cycle."},{"input":"nodes = [2, 4, 6, 8], cycle_pos = -1","output":"False","explanation":"The list ends normally with no cycle."},{"input":"nodes = [1, 2], cycle_pos = 0","output":"True","explanation":"Node 2 points back to head (index 0)."}]'::jsonb,
  'build_list',
  E'class ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef build_list(values, cycle_pos):\n    if not values:\n        return None\n    head = ListNode(values[0])\n    current = head\n    nodes = [head]\n    for v in values[1:]:\n        node = ListNode(v)\n        current.next = node\n        current = node\n        nodes.append(node)\n    if cycle_pos >= 0:\n        current.next = nodes[cycle_pos]\n    return head\n\ndef has_cycle(head):\n    # TODO: implement using fast & slow pointers\n    pass',
  E'class ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef build_list(values, cycle_pos):\n    if not values:\n        return None\n    head = ListNode(values[0])\n    current = head\n    nodes = [head]\n    for v in values[1:]:\n        node = ListNode(v)\n        current.next = node\n        current = node\n        nodes.append(node)\n    if cycle_pos >= 0:\n        current.next = nodes[cycle_pos]\n    return head\n\ndef has_cycle(head):\n    slow, fast = head, head\n    while fast is not None and fast.next is not None:\n        slow = slow.next\n        fast = fast.next.next\n        if slow == fast:\n            return True\n    return False',
  E'class Solution {\n    public Object buildList(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static class ListNode {\n        int val;\n        ListNode next;\n\n        ListNode(int val) {\n            this.val = val;\n            this.next = null;\n        }\n    }\n\n    // Helper function, not part of the problem to translate, but needed for context\n    public static ListNode buildList(int[] values, int cyclePos) {\n        if (values == null || values.length == 0) {\n            return null;\n        }\n        ListNode head = new ListNode(values[0]);\n        ListNode current = head;\n        ListNode[] nodes = new ListNode[values.length];\n        nodes[0] = head;\n        for (int i = 1; i < values.length; i++) {\n            ListNode node = new ListNode(values[i]);\n            current.next = node;\n            current = node;\n            nodes[i] = node;\n        }\n        if (cyclePos >= 0 && cyclePos < values.length) {\n            current.next = nodes[cyclePos];\n        }\n        return head;\n    }\n\n    public static boolean hasCycle(ListNode head) {\n        ListNode slow = head;\n        ListNode fast = head;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) {\n                return true;\n            }\n        }\n        return false;\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildList(val) {\n    // Your code here\n}',
  E'class ListNode {\n    constructor(val = 0) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\n// Helper function, not part of the problem to translate, but needed for context\nfunction buildList(values, cyclePos) {\n    if (!values || values.length === 0) {\n        return null;\n    }\n    const head = new ListNode(values[0]);\n    let current = head;\n    const nodes = [head];\n    for (let i = 1; i < values.length; i++) {\n        const node = new ListNode(values[i]);\n        current.next = node;\n        current = node;\n        nodes.push(node);\n    }\n    if (cyclePos >= 0 && cyclePos < values.length) {\n        current.next = nodes[cyclePos];\n    }\n    return head;\n}\n\nfunction hasCycle(head) {\n    let slow = head;\n    let fast = head;\n    while (fast !== null && fast.next !== null) {\n        slow = slow.next;\n        fast = fast.next.next;\n        if (slow === fast) {\n            return true;\n        }\n    }\n    return false;\n}',
