INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-find-cycle-length',
  'Find Cycle Length',
  'easy',
  'Find the Cycle Length

Problem Statement

Given the head of a linked list that **contains a cycle**, find the **length** of the cycle (the number of nodes in the loop).

Examples',
  '',
  '[{"input":"nodes = [1, 2, 3, 4, 5, 6], cycle_pos = 2","output":"4","explanation":"The cycle is 3 -> 4 -> 5 -> 6 -> 3, which has 4 nodes."},{"input":"nodes = [1, 2, 3], cycle_pos = 0","output":"3","explanation":"The cycle is 1 -> 2 -> 3 -> 1, which has 3 nodes."},{"input":"nodes = [10, 20], cycle_pos = 0","output":"2","explanation":"10 -> 20 -> 10 has 2 nodes in the cycle."}]'::jsonb,
  'build_list',
  E'class ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef build_list(values, cycle_pos):\n    if not values:\n        return None\n    head = ListNode(values[0])\n    current = head\n    nodes = [head]\n    for v in values[1:]:\n        node = ListNode(v)\n        current.next = node\n        current = node\n        nodes.append(node)\n    if cycle_pos >= 0:\n        current.next = nodes[cycle_pos]\n    return head\n\ndef find_cycle_length(head):\n    # TODO: detect cycle, then count its length\n    pass',
  E'class ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef build_list(values, cycle_pos):\n    if not values:\n        return None\n    head = ListNode(values[0])\n    current = head\n    nodes = [head]\n    for v in values[1:]:\n        node = ListNode(v)\n        current.next = node\n        current = node\n        nodes.append(node)\n    if cycle_pos >= 0:\n        current.next = nodes[cycle_pos]\n    return head\n\ndef find_cycle_length(head):\n    slow, fast = head, head\n    while fast is not None and fast.next is not None:\n        slow = slow.next\n        fast = fast.next.next\n        if slow == fast:\n            # Count the cycle length\n            current = slow\n            length = 0\n            while True:\n                current = current.next\n                length += 1\n                if current == slow:\n                    break\n            return length\n    return 0',
  E'class Solution {\n    public Object buildList(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static class ListNode {\n        int val;\n        ListNode next;\n\n        ListNode(int val) {\n            this.val = val;\n            this.next = null;\n        }\n    }\n\n    // Helper function, not part of the problem to translate, but needed for context\n    public static ListNode buildList(int[] values, int cyclePos) {\n        if (values == null || values.length == 0) {\n            return null;\n        }\n        ListNode head = new ListNode(values[0]);\n        ListNode current = head;\n        ListNode[] nodes = new ListNode[values.length];\n        nodes[0] = head;\n        for (int i = 1; i < values.length; i++) {\n            ListNode node = new ListNode(values[i]);\n            current.next = node;\n            current = node;\n            nodes[i] = node;\n        }\n        if (cyclePos >= 0 && cyclePos < values.length) {\n            current.next = nodes[cyclePos];\n        }\n        return head;\n    }\n\n    public static int findCycleLength(ListNode head) {\n        ListNode slow = head;\n        ListNode fast = head;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) {\n                // Count the cycle length\n                ListNode current = slow;\n                int length = 0;\n                do {\n                    current = current.next;\n                    length++;\n                } while (current != slow);\n                return length;\n            }\n        }\n        return 0;\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildList(val) {\n    // Your code here\n}',
  E'class ListNode {\n    constructor(val = 0) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\n// Helper function, not part of the problem to translate, but needed for context\nfunction buildList(values, cyclePos) {\n    if (!values || values.length === 0) {\n        return null;\n    }\n    const head = new ListNode(values[0]);\n    let current = head;\n    const nodes = [head];\n    for (let i = 1; i < values.length; i++) {\n        const node = new ListNode(values[i]);\n        current.next = node;\n        current = node;\n        nodes.push(node);\n    }\n    if (cyclePos >= 0 && cyclePos < values.length) {\n        current.next = nodes[cyclePos];\n    }\n    return head;\n}\n\nfunction findCycleLength(head) {\n    let slow = head;\n    let fast = head;\n    while (fast !== null && fast.next !== null) {\n        slow = slow.next;\n        fast = fast.next.next;\n        if (slow === fast) {\n            // Count the cycle length\n            let current = slow;\n            let length = 0;\n            do {\n                current = current.next;\n                length++;\n            } while (current !== slow);\n            return length;\n        }\n    }\n    return 0;\n}',
  ARRAY['fast-slow-pointers'],
