INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-find-cycle-start',
  'Find Cycle Start',
  'medium',
  'Find the Start of the Cycle

Problem Statement

Given the head of a linked list that contains a cycle, find the **node where the cycle begins** and return its value.

Examples',
  '',
  '[{"input":"nodes = [1, 2, 3, 4, 5, 6], cycle_pos = 2","output":"3","explanation":"The cycle starts at the node with value 3 (index 2)."},{"input":"nodes = [1, 2, 3], cycle_pos = 0","output":"1","explanation":"The tail connects back to the head."},{"input":"nodes = [10, 20, 30, 40], cycle_pos = 1","output":"20","explanation":"The cycle starts at node with value 20."}]'::jsonb,
  'build_list',
  E'class ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef build_list(values, cycle_pos):\n    if not values:\n        return None\n    head = ListNode(values[0])\n    current = head\n    nodes = [head]\n    for v in values[1:]:\n        node = ListNode(v)\n        current.next = node\n        current = node\n        nodes.append(node)\n    if cycle_pos >= 0:\n        current.next = nodes[cycle_pos]\n    return head\n\ndef find_cycle_start(head):\n    # TODO: find and return the value of the node where the cycle starts\n    pass',
  E'class ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef build_list(values, cycle_pos):\n    if not values:\n        return None\n    head = ListNode(values[0])\n    current = head\n    nodes = [head]\n    for v in values[1:]:\n        node = ListNode(v)\n        current.next = node\n        current = node\n        nodes.append(node)\n    if cycle_pos >= 0:\n        current.next = nodes[cycle_pos]\n    return head\n\ndef find_cycle_start(head):\n    slow, fast = head, head\n    cycle_length = 0\n    while fast is not None and fast.next is not None:\n        slow = slow.next\n        fast = fast.next.next\n        if slow == fast:\n            # Calculate cycle length\n            current = slow\n            while True:\n                current = current.next\n                cycle_length += 1\n                if current == slow:\n                    break\n            break\n    # Move pointer2 cycle_length steps ahead\n    pointer1, pointer2 = head, head\n    for _ in range(cycle_length):\n        pointer2 = pointer2.next\n    # Move both until they meet\n    while pointer1 != pointer2:\n        pointer1 = pointer1.next\n        pointer2 = pointer2.next\n    return pointer1.val',
  E'class Solution {\n    public Object buildList(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static class ListNode {\n        public int val;\n        public ListNode next;\n\n        public ListNode(int val) {\n            this.val = val;\n            this.next = null;\n        }\n    }\n\n    public static ListNode buildList(List<Integer> values, int cyclePos) {\n        if (values == null || values.isEmpty()) {\n            return null;\n        }\n        ListNode head = new ListNode(values.get(0));\n        ListNode current = head;\n        List<ListNode> nodes = new ArrayList<>();\n        nodes.add(head);\n\n        for (int i = 1; i < values.size(); i++) {\n            ListNode node = new ListNode(values.get(i));\n            current.next = node;\n            current = node;\n            nodes.add(node);\n        }\n\n        if (cyclePos >= 0) {\n            current.next = nodes.get(cyclePos);\n        }\n        return head;\n    }\n\n    public static int findCycleStart(ListNode head) {\n        ListNode slow = head;\n        ListNode fast = head;\n        int cycleLength = 0;\n\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) {\n                // Calculate cycle length\n                ListNode current = slow;\n                do {\n                    current = current.next;\n                    cycleLength++;\n                } while (current != slow);\n                break;\n            }\n        }\n\n        // If no cycle found, return a sentinel value or throw an exception\n        // Based on problem description, a cycle is expected.\n        if (cycleLength == 0) {\n            // This case means no cycle was found. The problem implies a cycle exists.\n            // If head is null or a single node with no cycle, this might happen.\n            // For this problem, we assume a cycle exists if the loop completes.\n            return -1; // Or throw an exception\n        }\n\n        // Move pointer2 cycle_length steps ahead\n        ListNode pointer1 = head;\n        ListNode pointer2 = head;\n        for (int i = 0; i < cycleLength; i++) {\n            pointer2 = pointer2.next;\n        }\n\n        // Move both until they meet\n        while (pointer1 != pointer2) {\n            pointer1 = pointer1.next;\n            pointer2 = pointer2.next;\n        }\n        return pointer1.val;\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildList(val) {\n    // Your code here\n}',
  E'class ListNode {\n    constructor(val = 0) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction buildList(values, cyclePos) {\n    if (!values || values.length === 0) {\n        return null;\n    }\n    let head = new ListNode(values[0]);\n    let current = head;\n    let nodes = [head];\n    for (let i = 1; i < values.length; i++) {\n        let node = new ListNode(values[i]);\n        current.next = node;\n        current = node;\n        nodes.push(node);\n    }\n    if (cyclePos >= 0) {\n        current.next = nodes[cyclePos];\n    }\n    return head;\n}\n\nfunction findCycleStart(head) {\n    let slow = head;\n    let fast = head;\n    let cycleLength = 0;\n\n    while (fast !== null && fast.next !== null) {\n        slow = slow.next;\n        fast = fast.next.next;\n        if (slow === fast) {\n            // Calculate cycle length\n            let current = slow;\n            do {\n                current = current.next;\n                cycleLength++;\n            } while (current !== slow);\n            break;\n        }\n    }\n\n    if (cycleLength === 0) {\n        return -1; // No cycle found\n    }\n\n    // Move pointer2 cycle_length steps ahead\n    let pointer1 = head;\n    let pointer2 = head;\n    for (let i = 0; i < cycleLength; i++) {\n        pointer2 = pointer2.next;\n    }\n\n    // Move both until they meet\n    while (pointer1 !== pointer2) {\n        pointer1 = pointer1.next;\n        pointer2 = pointer2.next;\n    }\n    return pointer1.val;\n}',
  ARRAY['fast-slow-pointers'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2'],
  'fast-slow-pointers',
  '[]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
