INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-happy-number',
  'Happy Number',
  'medium',
  'Happy Number

Problem Statement

A number is called **happy** if, starting with the number itself, you repeatedly replace it with the sum of the squares of its digits, and the process eventually reaches **1**. If the process loops endlessly in a cycle that does not include 1, the number is **unhappy**.

Write a function that returns `True` if the given number is happy, `False` otherwise.

Examples',
  '',
  '[{"input":"23","output":"True","explanation":"2² + 3² = 13 -> 1² + 3² = 10 -> 1² + 0² = 1  (reached 1!)"},{"input":"12","output":"False","explanation":"The sequence eventually enters a cycle that never reaches 1."},{"input":"1","output":"True"}]'::jsonb,
  'is_happy_number',
  E'def is_happy_number(num):\n    # TODO: implement using fast & slow pointers on digit square sums\n    pass',
  E'def is_happy_number(num):\n    def digit_square_sum(n):\n        total = 0\n        while n > 0:\n            digit = n % 10\n            total += digit * digit\n            n //= 10\n        return total\n\n    slow = num\n    fast = num\n    while True:\n        slow = digit_square_sum(slow)\n        fast = digit_square_sum(digit_square_sum(fast))\n        if slow == fast:\n            break\n    return slow == 1',
  E'class Solution {\n    public Object isHappyNumber(Object num) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // None\n\n    public static boolean isHappyNumber(int num) {\n        int slow = num;\n        int fast = num;\n        while (true) {\n            slow = digitSquareSum(slow);\n            fast = digitSquareSum(digitSquareSum(fast));\n            if (slow == fast) {\n                break;\n            }\n        }\n        return slow == 1;\n    }\n\n    private static int digitSquareSum(int n) {\n        int total = 0;\n        while (n > 0) {\n            int digit = n % 10;\n            total += digit * digit;\n            n /= 10;\n        }\n        return total;\n    }\n}',
  E'/**\n * @param {any} num\n * @return {any}\n */\nfunction isHappyNumber(num) {\n    // Your code here\n}',
  E'function isHappyNumber(num) {\n    function digitSquareSum(n) {\n        let total = 0;\n        while (n > 0) {\n            let digit = n % 10;\n            total += digit * digit;\n            n = Math.floor(n / 10);\n        }\n        return total;\n    }\n\n    let slow = num;\n    let fast = num;\n    while (true) {\n        slow = digitSquareSum(slow);\n        fast = digitSquareSum(digitSquareSum(fast));\n        if (slow === fast) {\n            break;\n        }\n    }\n    return slow === 1;\n}',
  ARRAY['fast-slow-pointers'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2'],
  'fast-slow-pointers',
  '[{"input":"is_happy_number(23)","expected_output":"True"},{"input":"is_happy_number(12)","expected_output":"False"},{"input":"is_happy_number(1)","expected_output":"True"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
