INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-max-sum-subarray-size-k',
  'Maximum Sum Subarray of Size K',
  'easy',
  'Maximum Sum Subarray of Size K

Problem Statement

Given an array of positive integers and a number `k`, find the **maximum sum** of any contiguous subarray of size `k`.

Examples',
  '',
  '[{"input":"arr = [2, 1, 5, 1, 3, 2], k = 3","output":"9","explanation":"Subarray [5, 1, 3] has the maximum sum of 9."},{"input":"arr = [2, 3, 4, 1, 5], k = 2","output":"7","explanation":"Subarray [3, 4] has the maximum sum of 7."},{"input":"arr = [1, 1, 1, 1], k = 2","output":"2"}]'::jsonb,
  'max_sub_array_of_size_k',
  E'def max_sub_array_of_size_k(k, arr):\n    # TODO: implement using fixed-size sliding window\n    pass',
  E'def max_sub_array_of_size_k(k, arr):\n    max_sum = 0\n    window_sum = 0\n    window_start = 0\n    for window_end in range(len(arr)):\n        window_sum += arr[window_end]\n        if window_end >= k - 1:\n            max_sum = max(max_sum, window_sum)\n            window_sum -= arr[window_start]\n            window_start += 1\n    return max_sum',
  E'class Solution {\n    public Object maxSubArrayOfSizeK(int k, int[] arr) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // None\n\n    public static int maxSubArrayOfSizeK(int k, int[] arr) {\n        int maxSum = 0;\n        int windowSum = 0;\n        int windowStart = 0;\n        for (int windowEnd = 0; windowEnd < arr.length; windowEnd++) {\n            windowSum += arr[windowEnd];\n            if (windowEnd >= k - 1) {\n                maxSum = Math.max(maxSum, windowSum);\n                windowSum -= arr[windowStart];\n                windowStart++;\n            }\n        }\n        return maxSum;\n    }\n}',
  E'/**\n * @param {any, any} k, arr\n * @return {any}\n */\nfunction maxSubArrayOfSizeK(k, arr) {\n    // Your code here\n}',
  E'function maxSubArrayOfSizeK(k, arr) {\n    let maxSum = 0;\n    let windowSum = 0;\n    let windowStart = 0;\n    for (let windowEnd = 0; windowEnd < arr.length; windowEnd++) {\n        windowSum += arr[windowEnd];\n        if (windowEnd >= k - 1) {\n            maxSum = Math.max(maxSum, windowSum);\n            windowSum -= arr[windowStart];\n            windowStart++;\n        }\n    }\n    return maxSum;\n}',
  ARRAY['sliding-window'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2', 'databricks-swe'],
  'sliding-window',
