INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-longest-substring-k-distinct',
  'Longest Substring with K Distinct Characters',
  'medium',
  'Longest Substring with K Distinct Characters

Problem Statement

Given a string, find the length of the **longest substring** that contains at most **K distinct characters**.

Examples',
  '',
  '[{"input":"s = \"araaci\", k = 2","output":"4","explanation":"\"araa\" has at most 2 distinct characters."},{"input":"s = \"araaci\", k = 1","output":"2","explanation":"\"aa\" is the longest with 1 distinct character."},{"input":"s = \"cbbebi\", k = 3","output":"5","explanation":"\"cbbeb\" or \"bbebi\" both have 3 distinct characters and length 5."}]'::jsonb,
  'longest_substring_k_distinct',
  E'def longest_substring_k_distinct(s, k):\n    # TODO: implement using sliding window + hash map\n    pass',
  E'def longest_substring_k_distinct(s, k):\n    char_freq = {}\n    max_length = 0\n    window_start = 0\n    for window_end in range(len(s)):\n        right_char = s[window_end]\n        char_freq[right_char] = char_freq.get(right_char, 0) + 1\n        while len(char_freq) > k:\n            left_char = s[window_start]\n            char_freq[left_char] -= 1\n            if char_freq[left_char] == 0:\n                del char_freq[left_char]\n            window_start += 1\n        max_length = max(max_length, window_end - window_start + 1)\n    return max_length',
  E'class Solution {\n    public Object longestSubstringKDistinct(String s, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.HashMap; // Required import\nimport java.util.Map;     // Required import\n\nclass Solution {\n    public static int longestSubstringKDistinct(String s, int k) {\n        Map<Character, Integer> charFreq = new HashMap<>();\n        int maxLength = 0;\n        int windowStart = 0;\n        for (int windowEnd = 0; windowEnd < s.length(); windowEnd++) {\n            char rightChar = s.charAt(windowEnd);\n            charFreq.put(rightChar, charFreq.getOrDefault(rightChar, 0) + 1);\n            while (charFreq.size() > k) {\n                char leftChar = s.charAt(windowStart);\n                charFreq.put(leftChar, charFreq.get(leftChar) - 1);\n                if (charFreq.get(leftChar) == 0) {\n                    charFreq.remove(leftChar);\n                }\n                windowStart++;\n            }\n            maxLength = Math.max(maxLength, windowEnd - windowStart + 1);\n        }\n        return maxLength;\n    }\n}',
  E'/**\n * @param {any, any} s, k\n * @return {any}\n */\nfunction longestSubstringKDistinct(s, k) {\n    // Your code here\n}',
  E'function longestSubstringKDistinct(s, k) {\n    let charFreq = new Map();\n    let maxLength = 0;\n    let windowStart = 0;\n    for (let windowEnd = 0; windowEnd < s.length; windowEnd++) {\n        let rightChar = s[windowEnd];\n        charFreq.set(rightChar, (charFreq.get(rightChar) || 0) + 1);\n        while (charFreq.size > k) {\n            let leftChar = s[windowStart];\n            charFreq.set(leftChar, charFreq.get(leftChar) - 1);\n            if (charFreq.get(leftChar) === 0) {\n                charFreq.delete(leftChar);\n            }\n            windowStart++;\n        }\n        maxLength = Math.max(maxLength, windowEnd - windowStart + 1);\n    }\n    return maxLength;\n}',
  ARRAY['sliding-window'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2', 'databricks-swe'],
  'sliding-window',
  '[{"input":"longest_substring_k_distinct(\"araaci\", 2)","expected_output":"4"},{"input":"longest_substring_k_distinct(\"araaci\", 1)","expected_output":"2"},{"input":"longest_substring_k_distinct(\"cbbebi\", 3)","expected_output":"5"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
