INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-fruits-into-baskets',
  'Fruits Into Baskets',
  'medium',
  'Fruits Into Baskets

Problem Statement

You are visiting a farm with a single row of fruit trees. Each tree produces one type of fruit (represented by an integer). You have **two baskets**, and each basket can hold only **one type** of fruit. Starting from any tree, you pick exactly one fruit from each tree moving right. You stop when you have to pick a third type of fruit.

Find the **maximum number of fruits** you can collect.

This is equivalent to finding the **longest subarray with at most 2 distinct elements**.

Examples',
  '',
  '[{"input":"fruits = [''A'', ''B'', ''C'', ''A'', ''C'']","output":"3","explanation":"Starting from index 2: [''C'', ''A'', ''C''] — 2 types, 3 fruits."},{"input":"fruits = [''A'', ''B'', ''C'', ''B'', ''B'', ''C'']","output":"5","explanation":"Starting from index 1: [''B'', ''C'', ''B'', ''B'', ''C''] — 2 types, 5 fruits."},{"input":"fruits = [''A'', ''A'', ''A'']","output":"3"}]'::jsonb,
  'fruits_into_baskets',
  E'def fruits_into_baskets(fruits):\n    # TODO: implement — longest subarray with at most 2 distinct values\n    pass',
  E'def fruits_into_baskets(fruits):\n    freq = {}\n    max_fruits = 0\n    window_start = 0\n    for window_end in range(len(fruits)):\n        right = fruits[window_end]\n        freq[right] = freq.get(right, 0) + 1\n        while len(freq) > 2:\n            left = fruits[window_start]\n            freq[left] -= 1\n            if freq[left] == 0:\n                del freq[left]\n            window_start += 1\n        max_fruits = max(max_fruits, window_end - window_start + 1)\n    return max_fruits',
  E'class Solution {\n    public Object fruitsIntoBaskets(Object fruits) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.HashMap; // Required import\nimport java.util.Map;     // Required import\n\nclass Solution {\n    public static int fruitsIntoBaskets(int[] fruits) {\n        Map<Integer, Integer> freq = new HashMap<>();\n        int maxFruits = 0;\n        int windowStart = 0;\n        for (int windowEnd = 0; windowEnd < fruits.length; windowEnd++) {\n            int right = fruits[windowEnd];\n            freq.put(right, freq.getOrDefault(right, 0) + 1);\n            while (freq.size() > 2) {\n                int left = fruits[windowStart];\n                freq.put(left, freq.get(left) - 1);\n                if (freq.get(left) == 0) {\n                    freq.remove(left);\n                }\n                windowStart++;\n            }\n            maxFruits = Math.max(maxFruits, windowEnd - windowStart + 1);\n        }\n        return maxFruits;\n    }\n}',
  E'/**\n * @param {any} fruits\n * @return {any}\n */\nfunction fruitsIntoBaskets(fruits) {\n    // Your code here\n}',
  E'function fruitsIntoBaskets(fruits) {\n    let freq = new Map();\n    let maxFruits = 0;\n    let windowStart = 0;\n    for (let windowEnd = 0; windowEnd < fruits.length; windowEnd++) {\n        let right = fruits[windowEnd];\n        freq.set(right, (freq.get(right) || 0) + 1);\n        while (freq.size > 2) {\n            let left = fruits[windowStart];\n            freq.set(left, freq.get(left) - 1);\n            if (freq.get(left) === 0) {\n                freq.delete(left);\n            }\n            windowStart++;\n        }\n        maxFruits = Math.max(maxFruits, windowEnd - windowStart + 1);\n    }\n    return maxFruits;\n}',
  ARRAY['sliding-window'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2', 'databricks-swe'],
  'sliding-window',
  '[{"input":"fruits_into_baskets([''A'', ''B'', ''C'', ''A'', ''C''])","expected_output":"3"},{"input":"fruits_into_baskets([''A'', ''B'', ''C'', ''B'', ''B'', ''C''])","expected_output":"5"},{"input":"fruits_into_baskets([''A'', ''A'', ''A''])","expected_output":"3"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
