INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-longest-substring-no-repeat',
  'Longest Substring Without Repeating Characters',
  'medium',
  'Longest Substring Without Repeating Characters

Problem Statement

Given a string, find the length of the **longest substring** that has **no repeating characters**.

Examples',
  '',
  '[{"input":"\"aabccbb\"","output":"3","explanation":"\"abc\" is the longest substring without repeats."},{"input":"\"abbbb\"","output":"2","explanation":"\"ab\" is the longest."},{"input":"\"abccde\"","output":"3","explanation":"\"cde\" (or \"abc\") has length 3."}]'::jsonb,
  'non_repeat_substring',
  E'def non_repeat_substring(s):\n    # TODO: implement using sliding window + last-seen map\n    pass',
  E'def non_repeat_substring(s):\n    char_index = {}\n    max_length = 0\n    window_start = 0\n    for window_end in range(len(s)):\n        right_char = s[window_end]\n        if right_char in char_index:\n            # Move window_start to just past the previous occurrence\n            # but never move it backwards\n            window_start = max(window_start, char_index[right_char] + 1)\n        char_index[right_char] = window_end\n        max_length = max(max_length, window_end - window_start + 1)\n    return max_length',
  E'class Solution {\n    public Object nonRepeatSubstring(String s) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.HashMap; // Required import\nimport java.util.Map;     // Required import\n\nclass Solution {\n    public static int nonRepeatSubstring(String s) {\n        Map<Character, Integer> charIndex = new HashMap<>();\n        int maxLength = 0;\n        int windowStart = 0;\n        for (int windowEnd = 0; windowEnd < s.length(); windowEnd++) {\n            char rightChar = s.charAt(windowEnd);\n            if (charIndex.containsKey(rightChar)) {\n                // Move window_start to just past the previous occurrence\n                // but never move it backwards\n                windowStart = Math.max(windowStart, charIndex.get(rightChar) + 1);\n            }\n            charIndex.put(rightChar, windowEnd);\n            maxLength = Math.max(maxLength, windowEnd - windowStart + 1);\n        }\n        return maxLength;\n    }\n}',
  E'/**\n * @param {any} s\n * @return {any}\n */\nfunction nonRepeatSubstring(s) {\n    // Your code here\n}',
  E'function nonRepeatSubstring(s) {\n    let charIndex = new Map();\n    let maxLength = 0;\n    let windowStart = 0;\n    for (let windowEnd = 0; windowEnd < s.length; windowEnd++) {\n        let rightChar = s[windowEnd];\n        if (charIndex.has(rightChar)) {\n            // Move window_start to just past the previous occurrence\n            // but never move it backwards\n            windowStart = Math.max(windowStart, charIndex.get(rightChar) + 1);\n        }\n        charIndex.set(rightChar, windowEnd);\n        maxLength = Math.max(maxLength, windowEnd - windowStart + 1);\n    }\n    return maxLength;\n}',
  ARRAY['sliding-window'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2', 'databricks-swe'],
  'sliding-window',
