INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-merge-intervals',
  'Merge Intervals',
  'easy',
  'Merge Intervals

Problem Statement

Given a list of intervals, **merge all overlapping intervals** and return the list of merged intervals.

Examples',
  '',
  '[{"input":"[[1,4], [2,5], [7,9]]","output":"[[1,5], [7,9]]","explanation":"[1,4] and [2,5] overlap, merging to [1,5]."},{"input":"[[6,7], [2,4], [5,9]]","output":"[[2,4], [5,9]]","explanation":"After sorting: [2,4], [5,9], [6,7]. [5,9] and [6,7] overlap -> [5,9]."},{"input":"[[1,4], [2,6], [3,5]]","output":"[[1,6]]","explanation":"All three overlap into one merged interval."}]'::jsonb,
  'merge',
  E'def merge(intervals):\n    # TODO: merge overlapping intervals\n    pass',
  E'def merge(intervals):\n    if len(intervals) < 2:\n        return intervals\n    intervals.sort(key=lambda x: x[0])\n    merged = [intervals[0]]\n    for i in range(1, len(intervals)):\n        if intervals[i][0] <= merged[-1][1]:\n            merged[-1][1] = max(merged[-1][1], intervals[i][1])\n        else:\n            merged.append(intervals[i])\n    return merged',
  E'class Solution {\n    public Object merge(int[] intervals) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayList;   // Required import\nimport java.util.Arrays;      // Required import\nimport java.util.Comparator;  // Required import\nimport java.util.List;        // Required import\n\nclass Solution {\n    public static int[][] merge(int[][] intervals) {\n        if (intervals.length < 2) {\n            return intervals;\n        }\n\n        // Sort intervals by their start times\n        Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));\n\n        List<int[]> merged = new ArrayList<>();\n        merged.add(intervals[0]);\n\n        for (int i = 1; i < intervals.length; i++) {\n            int[] currentInterval = intervals[i];\n            int[] lastMergedInterval = merged.get(merged.size() - 1);\n\n            // If current interval overlaps with the last merged interval\n            if (currentInterval[0] <= lastMergedInterval[1]) {\n                lastMergedInterval[1] = Math.max(lastMergedInterval[1], currentInterval[1]);\n            } else {\n                // No overlap, add the current interval\n                merged.add(currentInterval);\n            }\n        }\n\n        return merged.toArray(new int[merged.size()][]);\n    }\n}',
  E'/**\n * @param {any} intervals\n * @return {any}\n */\nfunction merge(intervals) {\n    // Your code here\n}',
  E'function merge(intervals) {\n    if (intervals.length < 2) {\n        return intervals;\n    }\n\n    // Sort intervals by their start times\n    intervals.sort((a, b) => a[0] - b[0]);\n\n    let merged = [intervals[0]];\n\n    for (let i = 1; i < intervals.length; i++) {\n        let currentInterval = intervals[i];\n        let lastMergedInterval = merged[merged.length - 1];\n\n        // If current interval overlaps with the last merged interval\n        if (currentInterval[0] <= lastMergedInterval[1]) {\n            lastMergedInterval[1] = Math.max(lastMergedInterval[1], currentInterval[1]);\n        } else {\n            // No overlap, add the current interval\n            merged.push(currentInterval);\n        }\n    }\n\n    return merged;\n}',
  ARRAY['merge-intervals'],
  ARRAY['google-l4', 'meta-e4', 'uber-sde2', 'airbnb-swe', 'linkedin-swe'],
  'merge-intervals',
  '[{"input":"merge([[1,4], [2,5], [7,9]])","expected_output":"[[1,5], [7,9]]"},{"input":"merge([[6,7], [2,4], [5,9]])","expected_output":"[[2,4], [5,9]]"},{"input":"merge([[1,4], [2,6], [3,5]])","expected_output":"[[1,6]]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
