INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-insert-interval',
  'Insert Interval',
  'easy',
  'Insert Interval

Problem Statement

Given a list of **non-overlapping** intervals sorted by start time and a **new interval**, insert the new interval and merge if necessary. Return the resulting list of non-overlapping intervals.

Examples',
  '',
  '[{"input":"intervals = [[1,3], [5,7], [8,12]], new = [4,6]","output":"[[1,3], [4,7], [8,12]]","explanation":"[4,6] overlaps with [5,7], merging to [4,7]."},{"input":"intervals = [[1,3], [5,7], [8,12]], new = [4,10]","output":"[[1,3], [4,12]]","explanation":"[4,10] overlaps with [5,7] and [8,12]."},{"input":"intervals = [[2,3], [5,7]], new = [1,4]","output":"[[1,4], [5,7]]"}]'::jsonb,
  'insert',
  E'def insert(intervals, new_interval):\n    # TODO: insert and merge the new interval\n    pass',
  E'def insert(intervals, new_interval):\n    merged = []\n    i = 0\n    n = len(intervals)\n    # Add all intervals before the new interval\n    while i < n and intervals[i][1] < new_interval[0]:\n        merged.append(intervals[i])\n        i += 1\n    # Merge overlapping intervals with new_interval\n    while i < n and intervals[i][0] <= new_interval[1]:\n        new_interval[0] = min(new_interval[0], intervals[i][0])\n        new_interval[1] = max(new_interval[1], intervals[i][1])\n        i += 1\n    merged.append(new_interval)\n    # Add remaining intervals\n    while i < n:\n        merged.append(intervals[i])\n        i += 1\n    return merged',
  E'class Solution {\n    public Object insert(int[] intervals, Object new_interval) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.List;\n    // import java.util.Arrays;\n\n    public static int[][] insert(int[][] intervals, int[] newInterval) {\n        List<int[]> merged = new ArrayList<>();\n        int i = 0;\n        int n = intervals.length;\n\n        // Add all intervals before the new interval\n        while (i < n && intervals[i][1] < newInterval[0]) {\n            merged.add(intervals[i]);\n            i++;\n        }\n\n        // Merge overlapping intervals with newInterval\n        while (i < n && intervals[i][0] <= newInterval[1]) {\n            newInterval[0] = Math.min(newInterval[0], intervals[i][0]);\n            newInterval[1] = Math.max(newInterval[1], intervals[i][1]);\n            i++;\n        }\n        merged.add(newInterval);\n\n        // Add remaining intervals\n        while (i < n) {\n            merged.add(intervals[i]);\n            i++;\n        }\n\n        return merged.toArray(new int[merged.size()][]);\n    }\n}',
  E'/**\n * @param {any, any} intervals, new_interval\n * @return {any}\n */\nfunction insert(intervals, new_interval) {\n    // Your code here\n}',
  E'function insert(intervals, newInterval) {\n    const merged = [];\n    let i = 0;\n    const n = intervals.length;\n\n    // Add all intervals before the new interval\n    while (i < n && intervals[i][1] < newInterval[0]) {\n        merged.push(intervals[i]);\n        i++;\n    }\n\n    // Merge overlapping intervals with newInterval\n    while (i < n && intervals[i][0] <= newInterval[1]) {\n        newInterval[0] = Math.min(newInterval[0], intervals[i][0]);\n        newInterval[1] = Math.max(newInterval[1], intervals[i][1]);\n        i++;\n    }\n    merged.push(newInterval);\n\n    // Add remaining intervals\n    while (i < n) {\n        merged.push(intervals[i]);\n        i++;\n    }\n\n    return merged;\n}',
  ARRAY['merge-intervals'],
  ARRAY['google-l4', 'meta-e4', 'uber-sde2', 'airbnb-swe', 'linkedin-swe'],
  'merge-intervals',
  '[{"input":"insert([[1,3], [5,7], [8,12]], [4,6])","expected_output":"[[1,3], [4,7], [8,12]]"},{"input":"insert([[1,3], [5,7], [8,12]], [4,10])","expected_output":"[[1,3], [4,12]]"},{"input":"insert([[2,3], [5,7]], [1,4])","expected_output":"[[1,4], [5,7]]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
