INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-intervals-intersection',
  'Intervals Intersection',
  'medium',
  'Intervals Intersection

Problem Statement

Given two lists of intervals, each list is **pairwise non-overlapping** and sorted by start time. Find the **intersection** of these two lists — all intervals that are common to both.

Examples',
  '',
  '[{"input":"a = [[1,3], [5,6], [7,9]], b = [[2,3], [5,7]]","output":"[[2,3], [5,6], [7,7]]"},{"input":"a = [[1,3], [5,7], [9,12]], b = [[5,10]]","output":"[[5,7], [9,10]]"},{"input":"a = [[1,2]], b = [[3,4]]","output":"[]","explanation":"No overlap."}]'::jsonb,
  'intervals_intersection',
  E'def intervals_intersection(a, b):\n    # TODO: find intersection of two sorted interval lists\n    pass\n\n# Expected: [[2,3], [5,6], [7,7]]\n# Expected: [[5,7], [9,10]]\n# Expected: []',
  E'def intervals_intersection(a, b):\n    result = []\n    i, j = 0, 0\n    while i < len(a) and j < len(b):\n        # Check if there is an overlap\n        start = max(a[i][0], b[j][0])\n        end = min(a[i][1], b[j][1])\n        if start <= end:\n            result.append([start, end])\n        # Move the pointer with the smaller end\n        if a[i][1] < b[j][1]:\n            i += 1\n        else:\n            j += 1\n    return result\n\n# Expected: [[2,3], [5,6], [7,7]]\n# Expected: [[5,7], [9,10]]\n# Expected: []',
  E'class Solution {\n    public Object intervalsIntersection(Object a, Object b) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.List;\n    // import java.util.Arrays;\n\n    public static int[][] intervalsIntersection(int[][] a, int[][] b) {\n        List<int[]> result = new ArrayList<>();\n        int i = 0, j = 0;\n\n        while (i < a.length && j < b.length) {\n            // Check if there is an overlap\n            int start = Math.max(a[i][0], b[j][0]);\n            int end = Math.min(a[i][1], b[j][1]);\n\n            if (start <= end) {\n                result.add(new int[]{start, end});\n            }\n\n            // Move the pointer with the smaller end\n            if (a[i][1] < b[j][1]) {\n                i++;\n            } else {\n                j++;\n            }\n        }\n        return result.toArray(new int[result.size()][]);\n    }\n}',
  E'/**\n * @param {any, any} a, b\n * @return {any}\n */\nfunction intervalsIntersection(a, b) {\n    // Your code here\n}',
  E'function intervalsIntersection(a, b) {\n    const result = [];\n    let i = 0, j = 0;\n\n    while (i < a.length && j < b.length) {\n        // Check if there is an overlap\n        const start = Math.max(a[i][0], b[j][0]);\n        const end = Math.min(a[i][1], b[j][1]);\n\n        if (start <= end) {\n            result.push([start, end]);\n        }\n\n        // Move the pointer with the smaller end\n        if (a[i][1] < b[j][1]) {\n            i++;\n        } else {\n            j++;\n        }\n    }\n    return result;\n}',
  ARRAY['merge-intervals'],
  ARRAY['google-l4', 'meta-e4', 'uber-sde2', 'airbnb-swe', 'linkedin-swe'],
  'merge-intervals',
  '[{"input":"intervals_intersection([[1,3],[5,6],[7,9]], [[2,3],[5,7]])","expected_output":"[[2,3], [5,6], [7,7]]"},{"input":"intervals_intersection([[1,3],[5,7],[9,12]], [[5,10]])","expected_output":"[[5,7], [9,10]]"},{"input":"intervals_intersection([[1,2]], [[3,4]])","expected_output":"[]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
