INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-conflicting-appointments',
  'Conflicting Appointments',
  'medium',
  'Conflicting Appointments

Problem Statement

Given an array of appointment time slots where each slot is `[start, end]`, determine if a person can **attend all appointments** without any conflicts. Return `True` if there are no overlaps, `False` otherwise.

Examples',
  '',
  '[{"input":"[[1,4], [2,5], [7,9]]","output":"False","explanation":"[1,4] and [2,5] overlap."},{"input":"[[6,7], [2,4], [8,12]]","output":"True","explanation":"After sorting: [2,4], [6,7], [8,12] — no overlaps."},{"input":"[[4,5], [2,3], [3,6]]","output":"False","explanation":"[4,5] and [3,6] overlap."}]'::jsonb,
  'can_attend_all',
  E'def can_attend_all(appointments):\n    # TODO: check if all appointments are conflict-free\n    pass',
  E'def can_attend_all(appointments):\n    appointments.sort(key=lambda x: x[0])\n    for i in range(1, len(appointments)):\n        if appointments[i][0] < appointments[i - 1][1]:\n            return False\n    return True',
  E'class Solution {\n    public Object canAttendAll(Object appointments) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.Arrays;\n    // import java.util.Comparator;\n\n    public static boolean canAttendAll(int[][] appointments) {\n        if (appointments == null || appointments.length == 0) {\n            return true;\n        }\n\n        // Sort appointments by start time\n        Arrays.sort(appointments, (a1, a2) -> Integer.compare(a1[0], a2[0]));\n\n        for (int i = 1; i < appointments.length; i++) {\n            // Check for overlap\n            if (appointments[i][0] < appointments[i - 1][1]) {\n                return false;\n            }\n        }\n        return true;\n    }\n}',
  E'/**\n * @param {any} appointments\n * @return {any}\n */\nfunction canAttendAll(appointments) {\n    // Your code here\n}',
  E'function canAttendAll(appointments) {\n    if (!appointments || appointments.length === 0) {\n        return true;\n    }\n\n    // Sort appointments by start time\n    appointments.sort((a, b) => a[0] - b[0]);\n\n    for (let i = 1; i < appointments.length; i++) {\n        // Check for overlap\n        if (appointments[i][0] < appointments[i - 1][1]) {\n            return false;\n        }\n    }\n    return true;\n}',
  ARRAY['merge-intervals'],
  ARRAY['google-l4', 'meta-e4', 'uber-sde2', 'airbnb-swe', 'linkedin-swe'],
  'merge-intervals',
  '[{"input":"can_attend_all([[1,4], [2,5], [7,9]])","expected_output":"False"},{"input":"can_attend_all([[6,7], [2,4], [8,12]])","expected_output":"True"},{"input":"can_attend_all([[4,5], [2,3], [3,6]])","expected_output":"False"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
