INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-minimum-meeting-rooms',
  'Minimum Meeting Rooms',
  'medium',
  'Minimum Meeting Rooms

Problem Statement

Given a list of meeting time intervals `[start, end]`, find the **minimum number of meeting rooms** required so that no two overlapping meetings share a room.

Examples',
  '',
  '[{"input":"[[1,4], [2,5], [7,9]]","output":"2","explanation":"Meetings [1,4] and [2,5] overlap, needing 2 rooms."},{"input":"[[6,7], [2,4], [8,12]]","output":"1","explanation":"No meetings overlap after sorting."},{"input":"[[1,4], [2,3], [3,6]]","output":"2","explanation":"[1,4] and [2,3] overlap. [3,6] starts when [2,3] ends, so only 2 rooms needed max."}]'::jsonb,
  'min_meeting_rooms',
  E'def min_meeting_rooms(meetings):\n    # TODO: find minimum number of meeting rooms needed\n    pass',
  E'def min_meeting_rooms(meetings):\n    if not meetings:\n        return 0\n    starts = sorted([m[0] for m in meetings])\n    ends = sorted([m[1] for m in meetings])\n    rooms = 0\n    max_rooms = 0\n    s, e = 0, 0\n    while s < len(starts):\n        if starts[s] < ends[e]:\n            rooms += 1\n            max_rooms = max(max_rooms, rooms)\n            s += 1\n        else:\n            rooms -= 1\n            e += 1\n    return max_rooms',
  E'class Solution {\n    public Object minMeetingRooms(Object meetings) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.Arrays;\n    // import java.util.Comparator;\n\n    public static int minMeetingRooms(int[][] meetings) {\n        if (meetings == null || meetings.length == 0) {\n            return 0;\n        }\n\n        int[] starts = new int[meetings.length];\n        int[] ends = new int[meetings.length];\n\n        for (int i = 0; i < meetings.length; i++) {\n            starts[i] = meetings[i][0];\n            ends[i] = meetings[i][1];\n        }\n\n        Arrays.sort(starts);\n        Arrays.sort(ends);\n\n        int rooms = 0;\n        int maxRooms = 0;\n        int s = 0, e = 0;\n\n        while (s < starts.length) {\n            if (starts[s] < ends[e]) {\n                rooms++;\n                maxRooms = Math.max(maxRooms, rooms);\n                s++;\n            } else {\n                rooms--;\n                e++;\n            }\n        }\n        return maxRooms;\n    }\n}',
  E'/**\n * @param {any} meetings\n * @return {any}\n */\nfunction minMeetingRooms(meetings) {\n    // Your code here\n}',
  E'function minMeetingRooms(meetings) {\n    if (!meetings || meetings.length === 0) {\n        return 0;\n    }\n\n    const starts = meetings.map(m => m[0]).sort((a, b) => a - b);\n    const ends = meetings.map(m => m[1]).sort((a, b) => a - b);\n\n    let rooms = 0;\n    let maxRooms = 0;\n    let s = 0, e = 0;\n\n    while (s < starts.length) {\n        if (starts[s] < ends[e]) {\n            rooms++;\n            maxRooms = Math.max(maxRooms, rooms);\n            s++;\n        } else {\n            rooms--;\n            e++;\n        }\n    }\n    return maxRooms;\n}',
  ARRAY['merge-intervals'],
  ARRAY['google-l4', 'meta-e4', 'uber-sde2', 'airbnb-swe', 'linkedin-swe'],
  'merge-intervals',
  '[{"input":"min_meeting_rooms([[1,4], [2,5], [7,9]])","expected_output":"2"},{"input":"min_meeting_rooms([[6,7], [2,4], [8,12]])","expected_output":"1"},{"input":"min_meeting_rooms([[1,4], [2,3], [3,6]])","expected_output":"2"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
  description = EXCLUDED.description,
  constraints = EXCLUDED.constraints,
