INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-cyclic-sort',
  'Cyclic Sort',
  'easy',
  'Cyclic Sort

Problem Statement

Given an array containing `n` distinct numbers from the range **[1, n]**, sort the array **in-place** using the cyclic sort technique. Each number should end up at index `number - 1`.

Examples',
  '',
  '[{"input":"[3, 1, 5, 4, 2]","output":"[1, 2, 3, 4, 5]"},{"input":"[2, 6, 4, 3, 1, 5]","output":"[1, 2, 3, 4, 5, 6]"},{"input":"[1, 2, 3]","output":"[1, 2, 3]   (already sorted)"}]'::jsonb,
  'cyclic_sort',
  E'def cyclic_sort(nums):\n    # TODO: sort using cyclic sort\n    pass\n\narr1 = [3, 1, 5, 4, 2]\ncyclic_sort(arr1)\narr2 = [2, 6, 4, 3, 1, 5]\ncyclic_sort(arr2)\narr3 = [1, 2, 3]\ncyclic_sort(arr3)',
  E'def cyclic_sort(nums):\n    i = 0\n    while i < len(nums):\n        correct = nums[i] - 1\n        if nums[i] != nums[correct]:\n            nums[i], nums[correct] = nums[correct], nums[i]\n        else:\n            i += 1\n\narr1 = [3, 1, 5, 4, 2]\ncyclic_sort(arr1)\narr2 = [2, 6, 4, 3, 1, 5]\ncyclic_sort(arr2)\narr3 = [1, 2, 3]\ncyclic_sort(arr3)',
  E'class Solution {\n    public Object cyclicSort(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static void cyclicSort(int[] nums) {\n        int i = 0;\n        while (i < nums.length) {\n            int correct = nums[i] - 1; // Correct index for the number nums[i]\n            if (nums[i] != nums[correct]) { // If the number is not at its correct position\n                // Swap nums[i] and nums[correct]\n                int temp = nums[i];\n                nums[i] = nums[correct];\n                nums[correct] = temp;\n            } else { // If the number is already at its correct position\n                i++;\n            }\n        }\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction cyclicSort(nums) {\n    // Your code here\n}',
  E'function cyclicSort(nums) {\n    let i = 0;\n    while (i < nums.length) {\n        const correct = nums[i] - 1; // Correct index for the number nums[i]\n        if (nums[i] !== nums[correct]) { // If the number is not at its correct position\n            // Swap nums[i] and nums[correct]\n            [nums[i], nums[correct]] = [nums[correct], nums[i]];\n        } else { // If the number is already at its correct position\n            i++;\n        }\n    }\n}',
  ARRAY['cyclic-sort', 'sorting'],
  ARRAY['google-l4', 'amazon-sde2', 'microsoft-sde2'],
  'cyclic-sort',
  '[]'::jsonb,
  '[]'::jsonb
