INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-find-missing-number',
  'Find the Missing Number',
  'easy',
  'Find the Missing Number

Problem Statement

Given an array containing `n` distinct numbers from the range **[0, n]**, find the one number that is **missing** from the array.

Examples',
  '',
  '[{"input":"[4, 0, 3, 1]","output":"2"},{"input":"[8, 3, 5, 2, 4, 6, 0, 1]","output":"7"},{"input":"[0, 1, 2]","output":"3"}]'::jsonb,
  'find_missing_number',
  E'def find_missing_number(nums):\n    # TODO: use cyclic sort to find the missing number\n    pass',
  E'def find_missing_number(nums):\n    n = len(nums)\n    i = 0\n    while i < n:\n        val = nums[i]\n        if val < n and val != i:\n            nums[i], nums[val] = nums[val], nums[i]\n        else:\n            i += 1\n    for i in range(n):\n        if nums[i] != i:\n            return i\n    return n',
  E'class Solution {\n    public Object findMissingNumber(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int findMissingNumber(int[] nums) {\n        int n = nums.length;\n        int i = 0;\n        while (i < n) {\n            int val = nums[i];\n            // Place val at its correct index `val`, if val is within [0, n-1]\n            // and not already at its correct place.\n            if (val < n && val != i) {\n                int temp = nums[i];\n                nums[i] = nums[val];\n                nums[val] = temp;\n            } else {\n                i++;\n            }\n        }\n\n        for (i = 0; i < n; i++) {\n            if (nums[i] != i) {\n                return i;\n            }\n        }\n        return n; // All numbers from 0 to n-1 are present, so n is missing\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction findMissingNumber(nums) {\n    // Your code here\n}',
  E'function findMissingNumber(nums) {\n    const n = nums.length;\n    let i = 0;\n    while (i < n) {\n        const val = nums[i];\n        // Place val at its correct index `val`, if val is within [0, n-1]\n        // and not already at its correct place.\n        if (val < n && val !== i) {\n            [nums[i], nums[val]] = [nums[val], nums[i]];\n        } else {\n            i++;\n        }\n    }\n\n    for (i = 0; i < n; i++) {\n        if (nums[i] !== i) {\n            return i;\n        }\n    }\n    return n; // All numbers from 0 to n-1 are present, so n is missing\n}',
  ARRAY['cyclic-sort', 'sorting'],
  ARRAY['google-l4', 'amazon-sde2', 'microsoft-sde2'],
  'cyclic-sort',
  '[{"input":"find_missing_number([4, 0, 3, 1])","expected_output":"2"},{"input":"find_missing_number([8, 3, 5, 2, 4, 6, 0, 1])","expected_output":"7"},{"input":"find_missing_number([0, 1, 2])","expected_output":"3"}]'::jsonb,
  '[]'::jsonb
