INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-find-all-missing-numbers',
  'Find All Missing Numbers',
  'medium',
  'Find All Missing Numbers

Problem Statement

Given an array of `n` integers where each integer is in the range **[1, n]** (some numbers may appear **twice** and some may be **missing**), find all the numbers from 1 to n that are **missing** from the array.

Examples',
  '',
  '[{"input":"[2, 3, 1, 8, 2, 3, 5, 1]","output":"[4, 6, 7]"},{"input":"[2, 4, 1, 2]","output":"[3]"},{"input":"[1, 1]","output":"[2]"}]'::jsonb,
  'find_all_missing',
  E'def find_all_missing(nums):\n    # TODO: use cyclic sort to find all missing numbers\n    pass',
  E'def find_all_missing(nums):\n    i = 0\n    while i < len(nums):\n        correct = nums[i] - 1\n        if nums[i] != nums[correct]:\n            nums[i], nums[correct] = nums[correct], nums[i]\n        else:\n            i += 1\n    missing = []\n    for i in range(len(nums)):\n        if nums[i] != i + 1:\n            missing.append(i + 1)\n    return missing',
  E'class Solution {\n    public Object findAllMissing(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.List;\n\n    public static List<Integer> findAllMissing(int[] nums) {\n        int i = 0;\n        while (i < nums.length) {\n            int correct = nums[i] - 1; // Correct index for the number nums[i]\n            if (nums[i] != nums[correct]) { // If the number is not at its correct position\n                // Swap nums[i] and nums[correct]\n                int temp = nums[i];\n                nums[i] = nums[correct];\n                nums[correct] = temp;\n            } else { // If the number is already at its correct position\n                i++;\n            }\n        }\n\n        List<Integer> missing = new ArrayList<>();\n        for (i = 0; i < nums.length; i++) {\n            if (nums[i] != i + 1) {\n                missing.add(i + 1);\n            }\n        }\n        return missing;\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction findAllMissing(nums) {\n    // Your code here\n}',
  E'function findAllMissing(nums) {\n    let i = 0;\n    while (i < nums.length) {\n        const correct = nums[i] - 1; // Correct index for the number nums[i]\n        if (nums[i] !== nums[correct]) { // If the number is not at its correct position\n            // Swap nums[i] and nums[correct]\n            [nums[i], nums[correct]] = [nums[correct], nums[i]];\n        } else { // If the number is already at its correct position\n            i++;\n        }\n    }\n\n    const missing = [];\n    for (i = 0; i < nums.length; i++) {\n        if (nums[i] !== i + 1) {\n            missing.push(i + 1);\n        }\n    }\n    return missing;\n}',
  ARRAY['cyclic-sort', 'sorting'],
  ARRAY['google-l4', 'amazon-sde2', 'microsoft-sde2'],
  'cyclic-sort',
  '[{"input":"find_all_missing([2, 3, 1, 8, 2, 3, 5, 1])","expected_output":"[4, 6, 7]"},{"input":"find_all_missing([2, 4, 1, 2])","expected_output":"[3]"},{"input":"find_all_missing([1, 1])","expected_output":"[2]"}]'::jsonb,
  '[]'::jsonb
