INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-find-duplicate-number',
  'Find the Duplicate Number',
  'medium',
  'Find the Duplicate Number

Problem Statement

Given an array containing `n + 1` numbers from the range **[1, n]**, find the one number that is **duplicated**. You must not modify the original array and should use only constant extra space.

However, for learning the cyclic sort approach, we will allow in-place modification.

Examples',
  '',
  '[{"input":"[1, 4, 4, 3, 2]","output":"4"},{"input":"[2, 1, 3, 3, 5, 4]","output":"3"},{"input":"[2, 2, 1]","output":"2"}]'::jsonb,
  'find_duplicate',
  E'def find_duplicate(nums):\n    # TODO: use cyclic sort to find the duplicate\n    pass',
  E'def find_duplicate(nums):\n    i = 0\n    while i < len(nums):\n        if nums[i] != i + 1:\n            correct = nums[i] - 1\n            if nums[i] != nums[correct]:\n                nums[i], nums[correct] = nums[correct], nums[i]\n            else:\n                return nums[i]\n        else:\n            i += 1\n    return -1',
  E'class Solution {\n    public Object findDuplicate(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int findDuplicate(int[] nums) {\n        int i = 0;\n        while (i < nums.length) {\n            if (nums[i] != i + 1) { // If current number is not in its correct place\n                int correct = nums[i] - 1; // Calculate its correct index\n                if (nums[i] != nums[correct]) { // If the number at its correct index is different\n                    // Swap nums[i] and nums[correct]\n                    int temp = nums[i];\n                    nums[i] = nums[correct];\n                    nums[correct] = temp;\n                } else { // If nums[i] is already at nums[correct], then nums[i] is the duplicate\n                    return nums[i];\n                }\n            } else { // Current number is in its correct place, move to next\n                i++;\n            }\n        }\n        return -1; // Should not reach here if there\'s exactly one duplicate\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction findDuplicate(nums) {\n    // Your code here\n}',
  E'function findDuplicate(nums) {\n    let i = 0;\n    while (i < nums.length) {\n        if (nums[i] !== i + 1) { // If current number is not in its correct place\n            const correct = nums[i] - 1; // Calculate its correct index\n            if (nums[i] !== nums[correct]) { // If the number at its correct index is different\n                // Swap nums[i] and nums[correct]\n                [nums[i], nums[correct]] = [nums[correct], nums[i]];\n            } else { // If nums[i] is already at nums[correct], then nums[i] is the duplicate\n                return nums[i];\n            }\n        } else { // Current number is in its correct place, move to next\n            i++;\n        }\n    }\n    return -1; // Should not reach here if there\'s exactly one duplicate\n}',
  ARRAY['cyclic-sort', 'sorting'],
  ARRAY['google-l4', 'amazon-sde2', 'microsoft-sde2'],
  'cyclic-sort',
  '[{"input":"find_duplicate([1, 4, 4, 3, 2])","expected_output":"4"},{"input":"find_duplicate([2, 1, 3, 3, 5, 4])","expected_output":"3"},{"input":"find_duplicate([2, 2, 1])","expected_output":"2"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
