INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-reverse-linked-list',
  'Reverse a Linked List',
  'easy',
  'Reverse a Linked List

Problem Statement

Given the head of a singly linked list, reverse the entire list and return the new head.

Examples',
  '',
  '[{"input":"1 -> 2 -> 3 -> 4 -> 5 -> None","output":"5 -> 4 -> 3 -> 2 -> 1 -> None"},{"input":"10 -> 20 -> 30 -> None","output":"30 -> 20 -> 10 -> None"},{"input":"7 -> None","output":"7 -> None"}]'::jsonb,
  'build_list',
  E'class ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef build_list(values):\n    if not values:\n        return None\n    head = ListNode(values[0])\n    curr = head\n    for v in values[1:]:\n        curr.next = ListNode(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef reverse(head):\n    # TODO: reverse the linked list in-place\n    pass',
  E'class ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef build_list(values):\n    if not values:\n        return None\n    head = ListNode(values[0])\n    curr = head\n    for v in values[1:]:\n        curr.next = ListNode(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef reverse(head):\n    prev = None\n    current = head\n    while current:\n        next_node = current.next\n        current.next = prev\n        prev = current\n        current = next_node\n    return prev',
  E'class Solution {\n    public Object buildList(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n            this.next = null;\n        }\n    }\n\n    public static ListNode buildList(int[] values) {\n        if (values == null || values.length == 0) {\n            return null;\n        }\n        ListNode head = new ListNode(values[0]);\n        ListNode curr = head;\n        for (int i = 1; i < values.length; i++) {\n            curr.next = new ListNode(values[i]);\n            curr = curr.next;\n        }\n        return head;\n    }\n\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.List;\n\n    public static List<Integer> toList(ListNode head) {\n        List<Integer> result = new ArrayList<>();\n        while (head != null) {\n            result.add(head.val);\n            head = head.next;\n        }\n        return result;\n    }\n\n    public static ListNode reverse(ListNode head) {\n        ListNode prev = null;\n        ListNode current = head;\n        while (current != null) {\n            ListNode nextNode = current.next;\n            current.next = prev;\n            prev = current;\n            current = nextNode;\n        }\n        return prev;\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildList(val) {\n    // Your code here\n}',
  E'class ListNode {\n    constructor(val = 0) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction buildList(values) {\n    if (!values || values.length === 0) {\n        return null;\n    }\n    const head = new ListNode(values[0]);\n    let curr = head;\n    for (let i = 1; i < values.length; i++) {\n        curr.next = new ListNode(values[i]);\n        curr = curr.next;\n    }\n    return head;\n}\n\nfunction toList(head) {\n    const result = [];\n    while (head) {\n        result.push(head.val);\n        head = head.next;\n    }\n    return result;\n}\n\nfunction reverse(head) {\n    let prev = null;\n    let current = head;\n    while (current) {\n        const nextNode = current.next;\n        current.next = prev;\n        prev = current;\n        current = nextNode;\n    }\n    return prev;\n}',
