INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-reverse-sub-list',
  'Reverse a Sub-list',
  'easy',
  'Reverse a Sub-list

Problem Statement

Given the head of a linked list and two positions `p` and `q` (1-indexed), reverse the nodes from position `p` to position `q` and return the modified list.

Examples',
  '',
  '[{"input":"1 -> 2 -> 3 -> 4 -> 5, p=2, q=4","output":"1 -> 4 -> 3 -> 2 -> 5","explanation":"Nodes at positions 2,3,4 are reversed."},{"input":"1 -> 2 -> 3, p=1, q=3","output":"3 -> 2 -> 1","explanation":"Entire list reversed."},{"input":"10 -> 20 -> 30 -> 40 -> 50, p=2, q=3","output":"10 -> 30 -> 20 -> 40 -> 50"}]'::jsonb,
  'build_list',
  E'class ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef build_list(values):\n    if not values:\n        return None\n    head = ListNode(values[0])\n    curr = head\n    for v in values[1:]:\n        curr.next = ListNode(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef reverse_sub_list(head, p, q):\n    # TODO: reverse nodes from position p to q\n    pass',
  E'class ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef build_list(values):\n    if not values:\n        return None\n    head = ListNode(values[0])\n    curr = head\n    for v in values[1:]:\n        curr.next = ListNode(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef reverse_sub_list(head, p, q):\n    if p == q:\n        return head\n    dummy = ListNode(0)\n    dummy.next = head\n    prev = dummy\n    # Move prev to node before position p\n    for _ in range(p - 1):\n        prev = prev.next\n    # Reverse q - p + 1 nodes\n    current = prev.next\n    for _ in range(q - p):\n        next_node = current.next\n        current.next = next_node.next\n        next_node.next = prev.next\n        prev.next = next_node\n    return dummy.next',
  E'class Solution {\n    public Object buildList(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n            this.next = null;\n        }\n    }\n\n    public static ListNode buildList(int[] values) {\n        if (values == null || values.length == 0) {\n            return null;\n        }\n        ListNode head = new ListNode(values[0]);\n        ListNode curr = head;\n        for (int i = 1; i < values.length; i++) {\n            curr.next = new ListNode(values[i]);\n            curr = curr.next;\n        }\n        return head;\n    }\n\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.List;\n\n    public static List<Integer> toList(ListNode head) {\n        List<Integer> result = new ArrayList<>();\n        while (head != null) {\n            result.add(head.val);\n            head = head.next;\n        }\n        return result;\n    }\n\n    public static ListNode reverseSubList(ListNode head, int p, int q) {\n        if (p == q) {\n            return head;\n        }\n        ListNode dummy = new ListNode(0);\n        dummy.next = head;\n        ListNode prev = dummy;\n        // Move prev to node before position p\n        for (int i = 0; i < p - 1; i++) {\n            prev = prev.next;\n        }\n        // Reverse q - p + 1 nodes\n        ListNode current = prev.next;\n        for (int i = 0; i < q - p; i++) {\n            ListNode nextNode = current.next;\n            current.next = nextNode.next;\n            nextNode.next = prev.next;\n            prev.next = nextNode;\n        }\n        return dummy.next;\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildList(val) {\n    // Your code here\n}',
  E'class ListNode {\n    constructor(val = 0) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction buildList(values) {\n    if (!values || values.length === 0) {\n        return null;\n    }\n    const head = new ListNode(values[0]);\n    let curr = head;\n    for (let i = 1; i < values.length; i++) {\n        curr.next = new ListNode(values[i]);\n        curr = curr.next;\n    }\n    return head;\n}\n\nfunction toList(head) {\n    const result = [];\n    while (head) {\n        result.push(head.val);\n        head = head.next;\n    }\n    return result;\n}\n\nfunction reverseSubList(head, p, q) {\n    if (p === q) {\n        return head;\n    }\n    const dummy = new ListNode(0);\n    dummy.next = head;\n    let prev = dummy;\n    // Move prev to node before position p\n    for (let i = 0; i < p - 1; i++) {\n        prev = prev.next;\n    }\n    // Reverse q - p + 1 nodes\n    let current = prev.next;\n    for (let i = 0; i < q - p; i++) {\n        const nextNode = current.next;\n        current.next = nextNode.next;\n        nextNode.next = prev.next;\n        prev.next = nextNode;\n    }\n    return dummy.next;\n}',
  ARRAY['linked-list-reversal', 'linked-list'],
  ARRAY['meta-e4', 'amazon-sde2', 'microsoft-sde2', 'apple-ict3'],
