INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-reverse-every-k-elements',
  'Reverse Every K-element Sub-list',
  'medium',
  'Reverse Every K-element Sub-list

Problem Statement

Given the head of a linked list and a number `k`, reverse the list in groups of `k` nodes. If the remaining nodes are fewer than `k`, reverse them as well.

Examples',
  '',
  '[{"input":"1 -> 2 -> 3 -> 4 -> 5 -> 6 -> 7 -> 8, k=3","output":"3 -> 2 -> 1 -> 6 -> 5 -> 4 -> 8 -> 7"},{"input":"1 -> 2 -> 3 -> 4 -> 5, k=2","output":"2 -> 1 -> 4 -> 3 -> 5"},{"input":"1 -> 2 -> 3, k=4","output":"3 -> 2 -> 1","explanation":"Fewer than k nodes, reverse them all."}]'::jsonb,
  'build_list',
  E'class ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef build_list(values):\n    if not values:\n        return None\n    head = ListNode(values[0])\n    curr = head\n    for v in values[1:]:\n        curr.next = ListNode(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef reverse_every_k(head, k):\n    # TODO: reverse in groups of k\n    pass\n\n# Expected: [3,2,1,6,5,4,8,7]\n# Expected: [2,1,4,3,5]\n# Expected: [3,2,1]',
  E'class ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef build_list(values):\n    if not values:\n        return None\n    head = ListNode(values[0])\n    curr = head\n    for v in values[1:]:\n        curr.next = ListNode(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef reverse_every_k(head, k):\n    if k <= 1 or head is None:\n        return head\n    dummy = ListNode(0)\n    dummy.next = head\n    prev_group_end = dummy\n    current = head\n    while current:\n        group_start = current\n        # Check if there are k nodes remaining\n        count = 0\n        temp = current\n        while temp and count < k:\n            temp = temp.next\n            count += 1\n        # Reverse k nodes\n        prev = None\n        for _ in range(count):\n            next_node = current.next\n            current.next = prev\n            prev = current\n            current = next_node\n        # Connect with previous part\n        prev_group_end.next = prev\n        group_start.next = current\n        prev_group_end = group_start\n    return dummy.next\n\n# Expected: [3,2,1,6,5,4,8,7]\n# Expected: [2,1,4,3,5]\n# Expected: [3,2,1]',
  E'class Solution {\n    public Object buildList(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n            this.next = null;\n        }\n    }\n\n    public static ListNode buildList(int[] values) {\n        if (values == null || values.length == 0) {\n            return null;\n        }\n        ListNode head = new ListNode(values[0]);\n        ListNode curr = head;\n        for (int i = 1; i < values.length; i++) {\n            curr.next = new ListNode(values[i]);\n            curr = curr.next;\n        }\n        return head;\n    }\n\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.List;\n\n    public static List<Integer> toList(ListNode head) {\n        List<Integer> result = new ArrayList<>();\n        while (head != null) {\n            result.add(head.val);\n            head = head.next;\n        }\n        return result;\n    }\n\n    public static ListNode reverseEveryK(ListNode head, int k) {\n        if (k <= 1 || head == null) {\n            return head;\n        }\n        ListNode dummy = new ListNode(0);\n        dummy.next = head;\n        ListNode prevGroupEnd = dummy;\n        ListNode current = head;\n\n        while (current != null) {\n            ListNode groupStart = current;\n            // Check if there are k nodes remaining\n            int count = 0;\n            ListNode temp = current;\n            while (temp != null && count < k) {\n                temp = temp.next;\n                count++;\n            }\n\n            // If fewer than k nodes remain, don\'t reverse\n            if (count < k) {\n                prevGroupEnd.next = groupStart;\n                break;\n            }\n\n            // Reverse k nodes\n            ListNode prev = null;\n            ListNode tailOfReversedGroup = current; // This will be the new tail of the reversed group\n            for (int i = 0; i < count; i++) {\n                ListNode nextNode = current.next;\n                current.next = prev;\n                prev = current;\n                current = nextNode;\n            }\n            // prev is now the head of the reversed group\n            // current is now the node after the reversed group\n\n            // Connect with previous part\n            prevGroupEnd.next = prev;\n            tailOfReversedGroup.next = current; // The original groupStart is now the tail\n            prevGroupEnd = tailOfReversedGroup;\n        }\n        return dummy.next;\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildList(val) {\n    // Your code here\n}',
  E'class ListNode {\n    constructor(val = 0) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction buildList(values) {\n    if (!values || values.length === 0) {\n        return null;\n    }\n    const head = new ListNode(values[0]);\n    let curr = head;\n    for (let i = 1; i < values.length; i++) {\n        curr.next = new ListNode(values[i]);\n        curr = curr.next;\n    }\n    return head;\n}\n\nfunction toList(head) {\n    const result = [];\n    while (head) {\n        result.push(head.val);\n        head = head.next;\n    }\n    return result;\n}\n\nfunction reverseEveryK(head, k) {\n    if (k <= 1 || head === null) {\n        return head;\n    }\n    const dummy = new ListNode(0);\n    dummy.next = head;\n    let prevGroupEnd = dummy;\n    let current = head;\n\n    while (current) {\n        const groupStart = current;\n        // Check if there are k nodes remaining\n        let count = 0;\n        let temp = current;\n        while (temp && count < k) {\n            temp = temp.next;\n            count++;\n        }\n\n        // If fewer than k nodes remain, don\'t reverse\n        if (count < k) {\n            prevGroupEnd.next = groupStart;\n            break;\n        }\n\n        // Reverse k nodes\n        let prev = null;\n        const tailOfReversedGroup = current; // This will be the new tail of the reversed group\n        for (let i = 0; i < count; i++) {\n            const nextNode = current.next;\n            current.next = prev;\n            prev = current;\n            current = nextNode;\n        }\n        // prev is now the head of the reversed group\n        // current is now the node after the reversed group\n\n        // Connect with previous part\n        prevGroupEnd.next = prev;\n        tailOfReversedGroup.next = current; // The original groupStart is now the tail\n        prevGroupEnd = tailOfReversedGroup;\n    }\n    return dummy.next;\n}',
  ARRAY['linked-list-reversal', 'linked-list'],
  ARRAY['meta-e4', 'amazon-sde2', 'microsoft-sde2', 'apple-ict3'],
  'linked-list-reversal',
  '[]'::jsonb,
