INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-reverse-alternating-k-elements',
  'Reverse Alternating K-element Sub-list',
  'medium',
  'Reverse Alternating K-element Sub-list

Problem Statement

Given the head of a linked list and a number `k`, reverse **every alternate** group of `k` nodes. That is: reverse the first k nodes, skip the next k nodes, reverse the next k, skip the next k, and so on.

Examples',
  '',
  '[{"input":"1 -> 2 -> 3 -> 4 -> 5 -> 6 -> 7 -> 8, k=2","output":"2 -> 1 -> 3 -> 4 -> 6 -> 5 -> 7 -> 8","explanation":"Reverse [1,2], skip [3,4], reverse [5,6], skip [7,8]."},{"input":"1 -> 2 -> 3 -> 4 -> 5 -> 6, k=3","output":"3 -> 2 -> 1 -> 4 -> 5 -> 6","explanation":"Reverse [1,2,3], skip [4,5,6]."},{"input":"1 -> 2 -> 3 -> 4 -> 5, k=1","output":"1 -> 2 -> 3 -> 4 -> 5","explanation":"k=1 means reverse single nodes (no change), skip single nodes."}]'::jsonb,
  'build_list',
  E'class ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef build_list(values):\n    if not values:\n        return None\n    head = ListNode(values[0])\n    curr = head\n    for v in values[1:]:\n        curr.next = ListNode(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef reverse_alternate_k(head, k):\n    # TODO: reverse alternate k-element groups\n    pass\n\n# Expected: [2,1,3,4,6,5,7,8]\n# Expected: [3,2,1,4,5,6]\n# Expected: [1,2,3,4,5]',
  E'class ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef build_list(values):\n    if not values:\n        return None\n    head = ListNode(values[0])\n    curr = head\n    for v in values[1:]:\n        curr.next = ListNode(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef reverse_alternate_k(head, k):\n    if k <= 1 or head is None:\n        return head\n    dummy = ListNode(0)\n    dummy.next = head\n    prev_group_end = dummy\n    current = head\n    should_reverse = True\n    while current:\n        if should_reverse:\n            group_start = current\n            prev = None\n            count = 0\n            while current and count < k:\n                next_node = current.next\n                current.next = prev\n                prev = current\n                current = next_node\n                count += 1\n            prev_group_end.next = prev\n            group_start.next = current\n            prev_group_end = group_start\n        else:\n            # Skip k nodes\n            count = 0\n            while current and count < k:\n                prev_group_end = current\n                current = current.next\n                count += 1\n        should_reverse = not should_reverse\n    return dummy.next\n\n# Expected: [2,1,3,4,6,5,7,8]\n# Expected: [3,2,1,4,5,6]\n# Expected: [1,2,3,4,5]',
  E'class Solution {\n    public Object buildList(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n            this.next = null;\n        }\n    }\n\n    public static ListNode buildList(int[] values) {\n        if (values == null || values.length == 0) {\n            return null;\n        }\n        ListNode head = new ListNode(values[0]);\n        ListNode curr = head;\n        for (int i = 1; i < values.length; i++) {\n            curr.next = new ListNode(values[i]);\n            curr = curr.next;\n        }\n        return head;\n    }\n\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.List;\n\n    public static List<Integer> toList(ListNode head) {\n        List<Integer> result = new ArrayList<>();\n        while (head != null) {\n            result.add(head.val);\n            head = head.next;\n        }\n        return result;\n    }\n\n    public static ListNode reverseAlternateK(ListNode head, int k) {\n        if (k <= 1 || head == null) {\n            return head;\n        }\n        ListNode dummy = new ListNode(0);\n        dummy.next = head;\n        ListNode prevGroupEnd = dummy;\n        ListNode current = head;\n        boolean shouldReverse = true;\n\n        while (current != null) {\n            if (shouldReverse) {\n                ListNode groupStart = current;\n                ListNode prev = null;\n                int count = 0;\n                // Reverse k nodes\n                while (current != null && count < k) {\n                    ListNode nextNode = current.next;\n                    current.next = prev;\n                    prev = current;\n                    current = nextNode;\n                    count++;\n                }\n                prevGroupEnd.next = prev;\n                groupStart.next = current;\n                prevGroupEnd = groupStart;\n            } else {\n                // Skip k nodes\n                int count = 0;\n                while (current != null && count < k) {\n                    prevGroupEnd = current;\n                    current = current.next;\n                    count++;\n                }\n            }\n            shouldReverse = !shouldReverse;\n        }\n        return dummy.next;\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildList(val) {\n    // Your code here\n}',
  E'class ListNode {\n    constructor(val = 0) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction buildList(values) {\n    if (!values || values.length === 0) {\n        return null;\n    }\n    const head = new ListNode(values[0]);\n    let curr = head;\n    for (let i = 1; i < values.length; i++) {\n        curr.next = new ListNode(values[i]);\n        curr = curr.next;\n    }\n    return head;\n}\n\nfunction toList(head) {\n    const result = [];\n    while (head) {\n        result.push(head.val);\n        head = head.next;\n    }\n    return result;\n}\n\nfunction reverseAlternateK(head, k) {\n    if (k <= 1 || head === null) {\n        return head;\n    }\n    const dummy = new ListNode(0);\n    dummy.next = head;\n    let prevGroupEnd = dummy;\n    let current = head;\n    let shouldReverse = true;\n\n    while (current) {\n        if (shouldReverse) {\n            const groupStart = current;\n            let prev = null;\n            let count = 0;\n            // Reverse k nodes\n            while (current && count < k) {\n                const nextNode = current.next;\n                current.next = prev;\n                prev = current;\n                current = nextNode;\n                count++;\n            }\n            prevGroupEnd.next = prev;\n            groupStart.next = current;\n            prevGroupEnd = groupStart;\n        } else {\n            // Skip k nodes\n            let count = 0;\n            while (current && count < k) {\n                prevGroupEnd = current;\n                current = current.next;\n                count++;\n            }\n        }\n        shouldReverse = !shouldReverse;\n    }\n    return dummy.next;\n}',
  ARRAY['linked-list-reversal', 'linked-list'],
  ARRAY['meta-e4', 'amazon-sde2', 'microsoft-sde2', 'apple-ict3'],
  'linked-list-reversal',
  '[]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
