INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-rotate-linked-list',
  'Rotate a Linked List',
  'medium',
  'Rotate a Linked List

Problem Statement

Given the head of a singly linked list and a number `k`, rotate the list to the **right** by `k` positions.

Examples',
  '',
  '[{"input":"1 -> 2 -> 3 -> 4 -> 5, k=2","output":"4 -> 5 -> 1 -> 2 -> 3","explanation":"Last 2 nodes move to the front."},{"input":"1 -> 2 -> 3, k=1","output":"3 -> 1 -> 2"},{"input":"1 -> 2 -> 3, k=3","output":"1 -> 2 -> 3","explanation":"Rotating by the list length gives the same list."}]'::jsonb,
  'build_list',
  E'class ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef build_list(values):\n    if not values:\n        return None\n    head = ListNode(values[0])\n    curr = head\n    for v in values[1:]:\n        curr.next = ListNode(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef rotate(head, k):\n    # TODO: rotate the linked list by k positions to the right\n    pass',
  E'class ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef build_list(values):\n    if not values:\n        return None\n    head = ListNode(values[0])\n    curr = head\n    for v in values[1:]:\n        curr.next = ListNode(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef rotate(head, k):\n    if not head or not head.next or k == 0:\n        return head\n    # Find length and tail\n    length = 1\n    tail = head\n    while tail.next:\n        tail = tail.next\n        length += 1\n    k = k % length\n    if k == 0:\n        return head\n    # Find new tail: (length - k - 1) steps from head\n    new_tail = head\n    for _ in range(length - k - 1):\n        new_tail = new_tail.next\n    new_head = new_tail.next\n    new_tail.next = None\n    tail.next = head\n    return new_head',
  E'class Solution {\n    public Object buildList(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n            this.next = null;\n        }\n    }\n\n    public static ListNode buildList(int[] values) {\n        if (values == null || values.length == 0) {\n            return null;\n        }\n        ListNode head = new ListNode(values[0]);\n        ListNode curr = head;\n        for (int i = 1; i < values.length; i++) {\n            curr.next = new ListNode(values[i]);\n            curr = curr.next;\n        }\n        return head;\n    }\n\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.List;\n\n    public static List<Integer> toList(ListNode head) {\n        List<Integer> result = new ArrayList<>();\n        while (head != null) {\n            result.add(head.val);\n            head = head.next;\n        }\n        return result;\n    }\n\n    public static ListNode rotate(ListNode head, int k) {\n        if (head == null || head.next == null || k == 0) {\n            return head;\n        }\n        // Find length and tail\n        int length = 1;\n        ListNode tail = head;\n        while (tail.next != null) {\n            tail = tail.next;\n            length++;\n        }\n        k = k % length;\n        if (k == 0) {\n            return head;\n        }\n        // Find new tail: (length - k - 1) steps from head\n        ListNode newTail = head;\n        for (int i = 0; i < length - k - 1; i++) {\n            newTail = newTail.next;\n        }\n        ListNode newHead = newTail.next;\n        newTail.next = null;\n        tail.next = head;\n        return newHead;\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildList(val) {\n    // Your code here\n}',
  E'class ListNode {\n    constructor(val = 0) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction buildList(values) {\n    if (!values || values.length === 0) {\n        return null;\n    }\n    const head = new ListNode(values[0]);\n    let curr = head;\n    for (let i = 1; i < values.length; i++) {\n        curr.next = new ListNode(values[i]);\n        curr = curr.next;\n    }\n    return head;\n}\n\nfunction toList(head) {\n    const result = [];\n    while (head) {\n        result.push(head.val);\n        head = head.next;\n    }\n    return result;\n}\n\nfunction rotate(head, k) {\n    if (!head || !head.next || k === 0) {\n        return head;\n    }\n    // Find length and tail\n    let length = 1;\n    let tail = head;\n    while (tail.next) {\n        tail = tail.next;\n        length++;\n    }\n    k = k % length;\n    if (k === 0) {\n        return head;\n    }\n    // Find new tail: (length - k - 1) steps from head\n    let newTail = head;\n    for (let i = 0; i < length - k - 1; i++) {\n        newTail = newTail.next;\n    }\n    const newHead = newTail.next;\n    newTail.next = null;\n    tail.next = head;\n    return newHead;\n}',
  ARRAY['linked-list-reversal', 'linked-list'],
  ARRAY['meta-e4', 'amazon-sde2', 'microsoft-sde2', 'apple-ict3'],
  'linked-list-reversal',
  '[]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
