INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-reverse-level-order',
  'Reverse Level Order Traversal',
  'easy',
  'Reverse Level Order Traversal

Problem Statement

Given the root of a binary tree, return the **reverse level order traversal** — the bottom level first, then the second-to-bottom, and so on up to the root level.

Examples',
  '',
  '[{"input":"1","output":"[[4, 5, 6], [2, 3], [1]]"},{"input":"12","output":"[[9, 10, 5], [7, 1], [12]]"},{"input":"5","output":"[[5]]"}]'::jsonb,
  'build_tree',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(values):\n    if not values:\n        return None\n    root = TreeNode(values[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(values):\n        node = queue.popleft()\n        if i < len(values) and values[i] is not None:\n            node.left = TreeNode(values[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(values) and values[i] is not None:\n            node.right = TreeNode(values[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef reverse_level_order(root):\n    # TODO: return levels from bottom to top\n    pass\n\n# Expected: [[4, 5, 6], [2, 3], [1]]\n# Expected: [[9, 10, 5], [7, 1], [12]]\n# Expected: [[5]]',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(values):\n    if not values:\n        return None\n    root = TreeNode(values[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(values):\n        node = queue.popleft()\n        if i < len(values) and values[i] is not None:\n            node.left = TreeNode(values[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(values) and values[i] is not None:\n            node.right = TreeNode(values[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef reverse_level_order(root):\n    if not root:\n        return []\n    result = deque()\n    queue = deque([root])\n    while queue:\n        level_size = len(queue)\n        current_level = []\n        for _ in range(level_size):\n            node = queue.popleft()\n            current_level.append(node.val)\n            if node.left:\n                queue.append(node.left)\n            if node.right:\n                queue.append(node.right)\n        result.appendleft(current_level)\n    return list(result)\n\n# Expected: [[4, 5, 6], [2, 3], [1]]\n# Expected: [[9, 10, 5], [7, 1], [12]]\n# Expected: [[5]]',
  E'class Solution {\n    public Object buildTree(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.List;\n    // import java.util.Queue;\n    // import java.util.LinkedList;\n    // import java.util.Deque;\n\n    public static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) {\n            this.val = val;\n            this.left = null;\n            this.right = null;\n        }\n    }\n\n    public static TreeNode buildTree(Integer[] values) {\n        if (values == null || values.length == 0 || values[0] == null) {\n            return null;\n        }\n        TreeNode root = new TreeNode(values[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < values.length) {\n            TreeNode node = queue.poll();\n            if (i < values.length && values[i] != null) {\n                node.left = new TreeNode(values[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < values.length && values[i] != null) {\n                node.right = new TreeNode(values[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    public static List<List<Integer>> reverseLevelOrder(TreeNode root) {\n        Deque<List<Integer>> resultDeque = new LinkedList<>();\n        if (root == null) {\n            return new ArrayList<>(resultDeque);\n        }\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        while (!queue.isEmpty()) {\n            int levelSize = queue.size();\n            List<Integer> currentLevel = new ArrayList<>();\n            for (int i = 0; i < levelSize; i++) {\n                TreeNode node = queue.poll();\n                currentLevel.add(node.val);\n                if (node.left != null) {\n                    queue.offer(node.left);\n                }\n                if (node.right != null) {\n                    queue.offer(node.right);\n                }\n            }\n            resultDeque.addFirst(currentLevel); // Add to the front\n        }\n        return new ArrayList<>(resultDeque); // Convert Deque to List\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildTree(val) {\n    // Your code here\n}',
  E'class TreeNode {\n    constructor(val = 0) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(values) {\n    if (!values || values.length === 0 || values[0] === null) {\n        return null;\n    }\n    const root = new TreeNode(values[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < values.length) {\n        const node = queue.shift();\n        if (i < values.length && values[i] !== null) {\n            node.left = new TreeNode(values[i]);\n            queue.push(node.left);\n        }\n        i++;\n        if (i < values.length && values[i] !== null) {\n            node.right = new TreeNode(values[i]);\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction reverseLevelOrder(root) {\n    const result = [];\n    if (!root) {\n        return result;\n    }\n    const queue = [root];\n    while (queue.length > 0) {\n        const levelSize = queue.length;\n        const currentLevel = [];\n        for (let i = 0; i < levelSize; i++) {\n            const node = queue.shift();\n            currentLevel.push(node.val);\n            if (node.left) {\n                queue.push(node.left);\n            }\n            if (node.right) {\n                queue.push(node.right);\n            }\n        }\n        result.unshift(currentLevel); // Add to the beginning\n    }\n    return result;\n}',
  ARRAY['tree-bfs', 'trees'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'tree-bfs',
  '[]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
