INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-zigzag-traversal',
  'Zigzag Traversal',
  'medium',
  'Zigzag Traversal

Problem Statement

Given the root of a binary tree, return its **zigzag level order traversal**. The first level is traversed left-to-right, the second right-to-left, the third left-to-right, and so on.

Examples',
  '',
  '[{"input":"1","output":"[[1], [3, 2], [4, 5, 6, 7]]"},{"input":"12","output":"[[12], [1, 7], [9, 10, 5], [20]]"},{"input":"1","output":"[[1]]"}]'::jsonb,
  'build_tree',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(values):\n    if not values:\n        return None\n    root = TreeNode(values[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(values):\n        node = queue.popleft()\n        if i < len(values) and values[i] is not None:\n            node.left = TreeNode(values[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(values) and values[i] is not None:\n            node.right = TreeNode(values[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef zigzag_traversal(root):\n    # TODO: return zigzag level order traversal\n    pass\n\n# Expected: [[1], [3, 2], [4, 5, 6, 7]]\n# Expected: [[12], [1, 7], [9, 10, 5], [20]]\n# Expected: [[1]]',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(values):\n    if not values:\n        return None\n    root = TreeNode(values[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(values):\n        node = queue.popleft()\n        if i < len(values) and values[i] is not None:\n            node.left = TreeNode(values[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(values) and values[i] is not None:\n            node.right = TreeNode(values[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef zigzag_traversal(root):\n    if not root:\n        return []\n    result = []\n    queue = deque([root])\n    left_to_right = True\n    while queue:\n        level_size = len(queue)\n        current_level = deque()\n        for _ in range(level_size):\n            node = queue.popleft()\n            if left_to_right:\n                current_level.append(node.val)\n            else:\n                current_level.appendleft(node.val)\n            if node.left:\n                queue.append(node.left)\n            if node.right:\n                queue.append(node.right)\n        result.append(list(current_level))\n        left_to_right = not left_to_right\n    return result\n\n# Expected: [[1], [3, 2], [4, 5, 6, 7]]\n# Expected: [[12], [1, 7], [9, 10, 5], [20]]\n# Expected: [[1]]',
  E'class Solution {\n    public Object buildTree(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayList;\nimport java.util.Deque;\nimport java.util.LinkedList;\nimport java.util.List;\n\nclass Solution {\n    public static class TreeNode {\n        public int val;\n        public TreeNode left;\n        public TreeNode right;\n\n        public TreeNode(int val) {\n            this.val = val;\n            this.left = null;\n            this.right = null;\n        }\n    }\n\n    public static TreeNode buildTree(List<Integer> values) {\n        if (values == null || values.isEmpty()) {\n            return null;\n        }\n        TreeNode root = new TreeNode(values.get(0));\n        Deque<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < values.size()) {\n            TreeNode node = queue.poll();\n            if (i < values.size() && values.get(i) != null) {\n                node.left = new TreeNode(values.get(i));\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < values.size() && values.get(i) != null) {\n                node.right = new TreeNode(values.get(i));\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    public static List<List<Integer>> zigzagTraversal(TreeNode root) {\n        if (root == null) {\n            return new ArrayList<>();\n        }\n        List<List<Integer>> result = new ArrayList<>();\n        Deque<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        boolean leftToRight = true;\n\n        while (!queue.isEmpty()) {\n            int levelSize = queue.size();\n            Deque<Integer> currentLevel = new LinkedList<>();\n            for (int i = 0; i < levelSize; i++) {\n                TreeNode node = queue.poll();\n                if (leftToRight) {\n                    currentLevel.addLast(node.val); // append\n                } else {\n                    currentLevel.addFirst(node.val); // appendleft\n                }\n                if (node.left != null) {\n                    queue.offer(node.left);\n                }\n                if (node.right != null) {\n                    queue.offer(node.right);\n                }\n            }\n            result.add(new ArrayList<>(currentLevel));\n            leftToRight = !leftToRight;\n        }\n        return result;\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildTree(val) {\n    // Your code here\n}',
  E'class TreeNode {\n    constructor(val = 0) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(values) {\n    if (!values || values.length === 0) {\n        return null;\n    }\n    let root = new TreeNode(values[0]);\n    let queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < values.length) {\n        let node = queue.shift();\n        if (i < values.length && values[i] !== null) {\n            node.left = new TreeNode(values[i]);\n            queue.push(node.left);\n        }\n        i++;\n        if (i < values.length && values[i] !== null) {\n            node.right = new TreeNode(values[i]);\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction zigzagTraversal(root) {\n    if (!root) {\n        return [];\n    }\n    let result = [];\n    let queue = [root];\n    let leftToRight = true;\n\n    while (queue.length > 0) {\n        let levelSize = queue.length;\n        let currentLevel = [];\n        for (let i = 0; i < levelSize; i++) {\n            let node = queue.shift();\n            if (leftToRight) {\n                currentLevel.push(node.val);\n            } else {\n                currentLevel.unshift(node.val);\n            }\n            if (node.left) {\n                queue.push(node.left);\n            }\n            if (node.right) {\n                queue.push(node.right);\n            }\n        }\n        result.push(currentLevel);\n        leftToRight = !leftToRight;\n    }\n    return result;\n}',
  ARRAY['tree-bfs', 'trees'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
