INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-path-sum',
  'Binary Tree Path Sum',
  'easy',
  'Binary Tree Path Sum

Problem Statement

Given the root of a binary tree and a target sum, determine if the tree has a **root-to-leaf path** such that adding up all the values along the path equals the target sum.

A **leaf** is a node with no children.

Examples',
  '',
  '[{"input":"target = 10","output":"True","explanation":"Path 1 -> 2 -> 4 = 7? No. Path 1 -> 3 -> 6 = 10? Yes!"},{"input":"target = 23","output":"True","explanation":"12 -> 1 -> 10 = 23"},{"input":"target = 16","output":"False"}]'::jsonb,
  'build_tree',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(values):\n    if not values:\n        return None\n    root = TreeNode(values[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(values):\n        node = queue.popleft()\n        if i < len(values) and values[i] is not None:\n            node.left = TreeNode(values[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(values) and values[i] is not None:\n            node.right = TreeNode(values[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef has_path_sum(root, target):\n    # TODO: check if any root-to-leaf path sums to target\n    pass\n\n# Expected: True (path: 1 -> 3 -> 6)\n# Expected: True (path: 12 -> 1 -> 10)\n# Expected: False',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(values):\n    if not values:\n        return None\n    root = TreeNode(values[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(values):\n        node = queue.popleft()\n        if i < len(values) and values[i] is not None:\n            node.left = TreeNode(values[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(values) and values[i] is not None:\n            node.right = TreeNode(values[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef has_path_sum(root, target):\n    if not root:\n        return False\n    # If leaf node, check if remaining sum matches\n    if not root.left and not root.right:\n        return root.val == target\n    # Recurse on children with reduced target\n    return (has_path_sum(root.left, target - root.val) or\n            has_path_sum(root.right, target - root.val))\n\n# Expected: True (path: 1 -> 3 -> 6)\n# Expected: True (path: 12 -> 1 -> 10)\n# Expected: False',
  E'class Solution {\n    public Object buildTree(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.LinkedList;\nimport java.util.Queue;\n\nclass Solution {\n    public static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode() {}\n        TreeNode(int val) { this.val = val; }\n        TreeNode(int val, TreeNode left, TreeNode right) {\n            this.val = val;\n            this.left = left;\n            this.right = right;\n        }\n    }\n\n    public static TreeNode buildTree(Integer[] values) {\n        if (values == null || values.length == 0 || values[0] == null) {\n            return null;\n        }\n        TreeNode root = new TreeNode(values[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < values.length) {\n            TreeNode node = queue.poll();\n            if (i < values.length && values[i] != null) {\n                node.left = new TreeNode(values[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < values.length && values[i] != null) {\n                node.right = new TreeNode(values[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    public static boolean hasPathSum(TreeNode root, int target) {\n        if (root == null) {\n            return false;\n        }\n        // If leaf node, check if remaining sum matches\n        if (root.left == null && root.right == null) {\n            return root.val == target;\n        }\n        // Recurse on children with reduced target\n        return (hasPathSum(root.left, target - root.val) ||\n                hasPathSum(root.right, target - root.val));\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildTree(val) {\n    // Your code here\n}',
  E'class TreeNode {\n    constructor(val = 0) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(values) {\n    if (!values || values.length === 0 || values[0] === null) {\n        return null;\n    }\n    const root = new TreeNode(values[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < values.length) {\n        const node = queue.shift();\n        if (i < values.length && values[i] !== null) {\n            node.left = new TreeNode(values[i]);\n            queue.push(node.left);\n        }\n        i++;\n        if (i < values.length && values[i] !== null) {\n            node.right = new TreeNode(values[i]);\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction hasPathSum(root, target) {\n    if (!root) {\n        return false;\n    }\n    // If leaf node, check if remaining sum matches\n    if (root.left === null && root.right === null) {\n        return root.val === target;\n    }\n    // Recurse on children with reduced target\n    return (hasPathSum(root.left, target - root.val) ||\n            hasPathSum(root.right, target - root.val));\n}',
  ARRAY['tree-dfs', 'trees'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
