INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-all-paths-for-sum',
  'All Paths for a Sum',
  'easy',
  'All Paths for a Sum

Problem Statement

Given the root of a binary tree and a target sum, find **all root-to-leaf paths** where the sum of the node values equals the target.

Examples',
  '',
  '[{"input":"target = 23","output":"[[12, 7, 4], [12, 1, 10]]"},{"input":"target = 18","output":"[[12, 1, 5]]"},{"input":"target = 8","output":"[[1, 3, 4]]"}]'::jsonb,
  'build_tree',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(values):\n    if not values:\n        return None\n    root = TreeNode(values[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(values):\n        node = queue.popleft()\n        if i < len(values) and values[i] is not None:\n            node.left = TreeNode(values[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(values) and values[i] is not None:\n            node.right = TreeNode(values[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef find_paths(root, target):\n    # TODO: find all root-to-leaf paths that sum to target\n    pass\n\n# Expected: [[12, 7, 4], [12, 1, 10]]\n# Expected: [[12, 1, 5]]\n# Expected: [[1, 3, 4]]',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(values):\n    if not values:\n        return None\n    root = TreeNode(values[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(values):\n        node = queue.popleft()\n        if i < len(values) and values[i] is not None:\n            node.left = TreeNode(values[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(values) and values[i] is not None:\n            node.right = TreeNode(values[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef find_paths(root, target):\n    all_paths = []\n    def dfs(node, remaining, current_path):\n        if not node:\n            return\n        current_path.append(node.val)\n        if not node.left and not node.right and node.val == remaining:\n            all_paths.append(list(current_path))\n        else:\n            dfs(node.left, remaining - node.val, current_path)\n            dfs(node.right, remaining - node.val, current_path)\n        current_path.pop()  # backtrack\n    dfs(root, target, [])\n    return all_paths\n# Expected: [[12, 7, 4], [12, 1, 10]]\n# Expected: [[12, 1, 5]]\n# Expected: [[1, 3, 4]]',
  E'class Solution {\n    public Object buildTree(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayList;\nimport java.util.LinkedList;\nimport java.util.List;\nimport java.util.Queue;\n\nclass Solution {\n    public static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode() {}\n        TreeNode(int val) { this.val = val; }\n        TreeNode(int val, TreeNode left, TreeNode right) {\n            this.val = val;\n            this.left = left;\n            this.right = right;\n        }\n    }\n\n    public static TreeNode buildTree(Integer[] values) {\n        if (values == null || values.length == 0 || values[0] == null) {\n            return null;\n        }\n        TreeNode root = new TreeNode(values[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < values.length) {\n            TreeNode node = queue.poll();\n            if (i < values.length && values[i] != null) {\n                node.left = new TreeNode(values[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < values.length && values[i] != null) {\n                node.right = new TreeNode(values[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    public static List<List<Integer>> findPaths(TreeNode root, int target) {\n        List<List<Integer>> allPaths = new ArrayList<>();\n        dfs(root, target, new ArrayList<>(), allPaths);\n        return allPaths;\n    }\n\n    private static void dfs(TreeNode node, int remaining, List<Integer> currentPath, List<List<Integer>> allPaths) {\n        if (node == null) {\n            return;\n        }\n        currentPath.add(node.val);\n        // If it\'s a leaf node and its value equals the remaining sum\n        if (node.left == null && node.right == null && node.val == remaining) {\n            allPaths.add(new ArrayList<>(currentPath));\n        } else {\n            // Recurse on children\n            dfs(node.left, remaining - node.val, currentPath, allPaths);\n            dfs(node.right, remaining - node.val, currentPath, allPaths);\n        }\n        // Backtrack: remove the current node\'s value from the path\n        currentPath.remove(currentPath.size() - 1);\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildTree(val) {\n    // Your code here\n}',
  E'class TreeNode {\n    constructor(val = 0) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(values) {\n    if (!values || values.length === 0 || values[0] === null) {\n        return null;\n    }\n    const root = new TreeNode(values[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < values.length) {\n        const node = queue.shift();\n        if (i < values.length && values[i] !== null) {\n            node.left = new TreeNode(values[i]);\n            queue.push(node.left);\n        }\n        i++;\n        if (i < values.length && values[i] !== null) {\n            node.right = new TreeNode(values[i]);\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction findPaths(root, target) {\n    const allPaths = [];\n\n    function dfs(node, remaining, currentPath) {\n        if (!node) {\n            return;\n        }\n        currentPath.push(node.val);\n\n        // If it\'s a leaf node and its value equals the remaining sum\n        if (node.left === null && node.right === null && node.val === remaining) {\n            allPaths.push([...currentPath]); // Add a copy of the current path\n        } else {\n            // Recurse on children\n            dfs(node.left, remaining - node.val, currentPath);\n            dfs(node.right, remaining - node.val, currentPath);\n        }\n        // Backtrack: remove the current node\'s value from the path\n        currentPath.pop();\n    }\n\n    dfs(root, target, []);\n    return allPaths;\n}',
  ARRAY['tree-dfs', 'trees'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'tree-dfs',
  '[]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
