INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-sum-of-path-numbers',
  'Sum of Path Numbers',
  'medium',
  'Sum of Path Numbers

Problem Statement

Given a binary tree where each node contains a single digit (0-9), each root-to-leaf path represents a number. For example, the path 1 -> 2 -> 3 represents the number 123. Find the **total sum** of all root-to-leaf path numbers.

Examples',
  '',
  '[{"input":"1","output":"408"},{"input":"1","output":"332"},{"input":"5","output":"5"}]'::jsonb,
  'build_tree',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(values):\n    if not values:\n        return None\n    root = TreeNode(values[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(values):\n        node = queue.popleft()\n        if i < len(values) and values[i] is not None:\n            node.left = TreeNode(values[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(values) and values[i] is not None:\n            node.right = TreeNode(values[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef sum_path_numbers(root):\n    # TODO: find total sum of all root-to-leaf path numbers\n    pass\n\n# Expected: 408  (17 + 192 + 199)\n# Expected: 332  (101 + 116 + 115)\n# Expected: 5',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(values):\n    if not values:\n        return None\n    root = TreeNode(values[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(values):\n        node = queue.popleft()\n        if i < len(values) and values[i] is not None:\n            node.left = TreeNode(values[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(values) and values[i] is not None:\n            node.right = TreeNode(values[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef sum_path_numbers(root):\n    def dfs(node, path_sum):\n        if not node:\n            return 0\n        path_sum = path_sum * 10 + node.val\n        if not node.left and not node.right:\n            return path_sum\n        return dfs(node.left, path_sum) + dfs(node.right, path_sum)\n    return dfs(root, 0)\n# Expected: 408  (17 + 192 + 199)\n# Expected: 332  (101 + 116 + 115)\n# Expected: 5',
  E'class Solution {\n    public Object buildTree(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.List;\nimport java.util.LinkedList;\nimport java.util.Queue;\n\nclass Solution {\n    public static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) {\n            this.val = val;\n            this.left = null;\n            this.right = null;\n        }\n    }\n\n    public static TreeNode buildTree(List<Integer> values) {\n        if (values == null || values.isEmpty()) {\n            return null;\n        }\n        TreeNode root = new TreeNode(values.get(0));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < values.size()) {\n            TreeNode node = queue.poll();\n            if (i < values.size() && values.get(i) != null) {\n                node.left = new TreeNode(values.get(i));\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < values.size() && values.get(i) != null) {\n                node.right = new TreeNode(values.get(i));\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    public static int sumPathNumbers(TreeNode root) {\n        return dfs(root, 0);\n    }\n\n    private static int dfs(TreeNode node, int pathSum) {\n        if (node == null) {\n            return 0;\n        }\n        pathSum = pathSum * 10 + node.val;\n        if (node.left == null && node.right == null) {\n            return pathSum;\n        }\n        return dfs(node.left, pathSum) + dfs(node.right, pathSum);\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildTree(val) {\n    // Your code here\n}',
  E'class TreeNode {\n    constructor(val = 0) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(values) {\n    if (!values || values.length === 0) {\n        return null;\n    }\n    const root = new TreeNode(values[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < values.length) {\n        const node = queue.shift();\n        if (i < values.length && values[i] !== null) {\n            node.left = new TreeNode(values[i]);\n            queue.push(node.left);\n        }\n        i++;\n        if (i < values.length && values[i] !== null) {\n            node.right = new TreeNode(values[i]);\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction sumPathNumbers(root) {\n    function dfs(node, pathSum) {\n        if (!node) {\n            return 0;\n        }\n        pathSum = pathSum * 10 + node.val;\n        if (!node.left && !node.right) {\n            return pathSum;\n        }\n        return dfs(node.left, pathSum) + dfs(node.right, pathSum);\n    }\n    return dfs(root, 0);\n}',
  ARRAY['tree-dfs', 'trees'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'tree-dfs',
  '[]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
