INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-path-with-given-sequence',
  'Path With Given Sequence',
  'medium',
  'Path With Given Sequence

Problem Statement

Given a binary tree and a number sequence, check if the sequence represents a valid **root-to-leaf path** in the tree.

Examples',
  '',
  '[{"input":"sequence = [1, 9, 9]","output":"True","explanation":"Path 1 -> 9 -> 9 exists."},{"input":"sequence = [1, 0, 7]","output":"False","explanation":"Path 1 -> 0 -> 1 exists but sequence asks for [1, 0, 7]."},{"input":"sequence = [1, 1, 6]","output":"True","explanation":"Path 1 -> 1 -> 6 exists."}]'::jsonb,
  'build_tree',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(values):\n    if not values:\n        return None\n    root = TreeNode(values[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(values):\n        node = queue.popleft()\n        if i < len(values) and values[i] is not None:\n            node.left = TreeNode(values[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(values) and values[i] is not None:\n            node.right = TreeNode(values[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef has_path_sequence(root, sequence):\n    # TODO: check if sequence matches a root-to-leaf path\n    pass\n\n# Expected: True\n# Expected: False\n# Expected: True',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(values):\n    if not values:\n        return None\n    root = TreeNode(values[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(values):\n        node = queue.popleft()\n        if i < len(values) and values[i] is not None:\n            node.left = TreeNode(values[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(values) and values[i] is not None:\n            node.right = TreeNode(values[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef has_path_sequence(root, sequence):\n    def dfs(node, idx):\n        if not node:\n            return False\n        if idx >= len(sequence) or node.val != sequence[idx]:\n            return False\n        # If leaf node, check if we matched the entire sequence\n        if not node.left and not node.right:\n            return idx == len(sequence) - 1\n        return dfs(node.left, idx + 1) or dfs(node.right, idx + 1)\n    if not root:\n        return len(sequence) == 0\n    return dfs(root, 0)\n# Expected: True\n# Expected: False\n# Expected: True',
  E'class Solution {\n    public Object buildTree(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.List;\nimport java.util.LinkedList;\nimport java.util.Queue;\n\nclass Solution {\n    public static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) {\n            this.val = val;\n            this.left = null;\n            this.right = null;\n        }\n    }\n\n    public static TreeNode buildTree(List<Integer> values) {\n        if (values == null || values.isEmpty()) {\n            return null;\n        }\n        TreeNode root = new TreeNode(values.get(0));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < values.size()) {\n            TreeNode node = queue.poll();\n            if (i < values.size() && values.get(i) != null) {\n                node.left = new TreeNode(values.get(i));\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < values.size() && values.get(i) != null) {\n                node.right = new TreeNode(values.get(i));\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    public static boolean hasPathSequence(TreeNode root, int[] sequence) {\n        if (root == null) {\n            return sequence.length == 0;\n        }\n        return dfs(root, sequence, 0);\n    }\n\n    private static boolean dfs(TreeNode node, int[] sequence, int idx) {\n        if (node == null) {\n            return false;\n        }\n        if (idx >= sequence.length || node.val != sequence[idx]) {\n            return false;\n        }\n        // If leaf node, check if we matched the entire sequence\n        if (node.left == null && node.right == null) {\n            return idx == sequence.length - 1;\n        }\n        return dfs(node.left, sequence, idx + 1) || dfs(node.right, sequence, idx + 1);\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildTree(val) {\n    // Your code here\n}',
  E'class TreeNode {\n    constructor(val = 0) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(values) {\n    if (!values || values.length === 0) {\n        return null;\n    }\n    const root = new TreeNode(values[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < values.length) {\n        const node = queue.shift();\n        if (i < values.length && values[i] !== null) {\n            node.left = new TreeNode(values[i]);\n            queue.push(node.left);\n        }\n        i++;\n        if (i < values.length && values[i] !== null) {\n            node.right = new TreeNode(values[i]);\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction hasPathSequence(root, sequence) {\n    function dfs(node, idx) {\n        if (!node) {\n            return false;\n        }\n        if (idx >= sequence.length || node.val !== sequence[idx]) {\n            return false;\n        }\n        // If leaf node, check if we matched the entire sequence\n        if (!node.left && !node.right) {\n            return idx === sequence.length - 1;\n        }\n        return dfs(node.left, idx + 1) || dfs(node.right, idx + 1);\n    }\n    if (!root) {\n        return sequence.length === 0;\n    }\n    return dfs(root, 0);\n}',
  ARRAY['tree-dfs', 'trees'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'tree-dfs',
  '[]'::jsonb,
