INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-count-paths-for-sum',
  'Count Paths for a Sum',
  'medium',
  'Count Paths for a Sum

Problem Statement

Given a binary tree and a target sum, find the **total number of paths** in the tree that sum to the target. A path can **start from any node** and end at any node going downward (from parent to child). The path does not need to start at the root or end at a leaf.

Examples

Let me use cleaner examples:',
  '',
  '[{"input":"target = 11","output":"3","explanation":"Paths: 7->4? No. Let''s trace: 7+5-1=11? Check all:"},{"input":"target = 12","output":"3"},{"input":"target = 11","output":"2"},{"input":"target = 8","output":"2"},{"input":"target = 7","output":"2"},{"input":"target = 6","output":"2","explanation":"[1,5] and [3,1,2] both sum to 6."},{"input":"target = 5","output":"1","explanation":"Only path [1,2... need 2 more... 1+4? 1+2+... no downward: 1->2->4=7. 2+3=5? 3 is not child of 2.]"},{"input":"target = 3","output":"2","explanation":"Paths: [1,2] (1+2=3) and [3] (3=3)."}]'::jsonb,
  'build_tree',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(values):\n    if not values:\n        return None\n    root = TreeNode(values[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(values):\n        node = queue.popleft()\n        if i < len(values) and values[i] is not None:\n            node.left = TreeNode(values[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(values) and values[i] is not None:\n            node.right = TreeNode(values[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef count_paths(root, target):\n    # TODO: count all downward paths that sum to target\n    pass\n\n# Expected: 2  (paths: [1,3,4] and [2,6])\n# Expected: 2  (paths: [1,5] and [3,1,2])\n# Expected: 2  (paths: [1,2] and [3])',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(values):\n    if not values:\n        return None\n    root = TreeNode(values[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(values):\n        node = queue.popleft()\n        if i < len(values) and values[i] is not None:\n            node.left = TreeNode(values[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(values) and values[i] is not None:\n            node.right = TreeNode(values[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef count_paths(root, target):\n    def dfs(node, prefix_sum, prefix_map):\n        if not node:\n            return 0\n        prefix_sum += node.val\n        # Count paths ending at this node\n        count = prefix_map.get(prefix_sum - target, 0)\n        # Update prefix sum map\n        prefix_map[prefix_sum] = prefix_map.get(prefix_sum, 0) + 1\n        # Recurse into children\n        count += dfs(node.left, prefix_sum, prefix_map)\n        count += dfs(node.right, prefix_sum, prefix_map)\n        # Backtrack: remove current prefix sum\n        prefix_map[prefix_sum] -= 1\n        if prefix_map[prefix_sum] == 0:\n            del prefix_map[prefix_sum]\n        return count\n    return dfs(root, 0, {0: 1})\n# Expected: 2  (paths: [1,3,4] and [2,6])\n# Expected: 2  (paths: [1,5] and [3,1,2])\n# Expected: 2  (paths: [1,2] and [3])',
  E'class Solution {\n    public Object buildTree(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.List;\nimport java.util.LinkedList;\nimport java.util.Queue;\nimport java.util.Map;\nimport java.util.HashMap;\n\nclass Solution {\n    public static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) {\n            this.val = val;\n            this.left = null;\n            this.right = null;\n        }\n    }\n\n    public static TreeNode buildTree(List<Integer> values) {\n        if (values == null || values.isEmpty()) {\n            return null;\n        }\n        TreeNode root = new TreeNode(values.get(0));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < values.size()) {\n            TreeNode node = queue.poll();\n            if (i < values.size() && values.get(i) != null) {\n                node.left = new TreeNode(values.get(i));\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < values.size() && values.get(i) != null) {\n                node.right = new TreeNode(values.get(i));\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    public static int countPaths(TreeNode root, int target) {\n        Map<Integer, Integer> prefixMap = new HashMap<>();\n        prefixMap.put(0, 1); // Base case: a path of sum 0 exists before starting\n        return dfs(root, target, 0, prefixMap);\n    }\n\n    private static int dfs(TreeNode node, int target, int currentPathSum, Map<Integer, Integer> prefixMap) {\n        if (node == null) {\n            return 0;\n        }\n        currentPathSum += node.val;\n        int count = prefixMap.getOrDefault(currentPathSum - target, 0);\n\n        prefixMap.put(currentPathSum, prefixMap.getOrDefault(currentPathSum, 0) + 1);\n\n        count += dfs(node.left, target, currentPathSum, prefixMap);\n        count += dfs(node.right, target, currentPathSum, prefixMap);\n\n        // Backtrack: remove current prefix sum from the map\n        prefixMap.put(currentPathSum, prefixMap.get(currentPathSum) - 1);\n        if (prefixMap.get(currentPathSum) == 0) {\n            prefixMap.remove(currentPathSum);\n        }\n        return count;\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildTree(val) {\n    // Your code here\n}',
  E'class TreeNode {\n    constructor(val = 0) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(values) {\n    if (!values || values.length === 0) {\n        return null;\n    }\n    const root = new TreeNode(values[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < values.length) {\n        const node = queue.shift();\n        if (i < values.length && values[i] !== null) {\n            node.left = new TreeNode(values[i]);\n            queue.push(node.left);\n        }\n        i++;\n        if (i < values.length && values[i] !== null) {\n            node.right = new TreeNode(values[i]);\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction countPaths(root, target) {\n    const prefixMap = new Map();\n    prefixMap.set(0, 1); // Base case: a path of sum 0 exists before starting\n\n    function dfs(node, currentPathSum, prefixMap) {\n        if (!node) {\n            return 0;\n        }\n        currentPathSum += node.val;\n        let count = prefixMap.get(currentPathSum - target) || 0;\n\n        prefixMap.set(currentPathSum, (prefixMap.get(currentPathSum) || 0) + 1);\n\n        count += dfs(node.left, currentPathSum, prefixMap);\n        count += dfs(node.right, currentPathSum, prefixMap);\n\n        // Backtrack: remove current prefix sum from the map\n        prefixMap.set(currentPathSum, prefixMap.get(currentPathSum) - 1);\n        if (prefixMap.get(currentPathSum) === 0) {\n            prefixMap.delete(currentPathSum);\n        }\n        return count;\n    }\n    return dfs(root, 0, prefixMap);\n}',
  ARRAY['tree-dfs', 'trees'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'tree-dfs',
  '[]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
