INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-two-heaps-sliding-window-median',
  'Sliding Window Median',
  'easy',
  'Sliding Window Median

Problem Statement

Given an array of numbers and a window size `k`, find the median of each sliding window as it moves from left to right across the array.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[{"input":"nums = [1, 2, -1, 3, 5], k = 3","output":"[1.0, 2.0, 3.0]","explanation":"Window [1,2,-1] → median 1, Window [2,-1,3] → median 2, Window [-1,3,5] → median 3"},{"input":"nums = [1, 3, -1, -3, 5, 3, 6, 7], k = 3","output":"[1.0, -1.0, -1.0, 3.0, 5.0, 6.0]"}]'::jsonb,
  'sliding_window_median',
  E'import heapq\nfrom collections import defaultdict\ndef sliding_window_median(nums, k):\n    # TODO: Return list of medians for each window of size k\n    result = []\n    return result\n\n# Expected: [1.0, 2.0, 3.0]\n# Expected: [1.0, -1.0, -1.0, 3.0, 5.0, 6.0]',
  E'import heapq\nfrom collections import defaultdict\ndef sliding_window_median(nums, k):\n    result = []\n    max_heap = []  # lower half (negated)\n    min_heap = []  # upper half\n    to_remove = defaultdict(int)\n\n    def get_median():\n        if k % 2 == 1:\n            return -max_heap[0] / 1.0\n        return (-max_heap[0] + min_heap[0]) / 2.0\n\n    def rebalance():\n        # max_heap should have equal or one more element than min_heap\n        if len(max_heap) - len(min_heap) > 1:\n            heapq.heappush(min_heap, -heapq.heappop(max_heap))\n        elif len(min_heap) > len(max_heap):\n            heapq.heappush(max_heap, -heapq.heappop(min_heap))\n\n    def clean_top(heap, is_max):\n        while heap:\n            val = -heap[0] if is_max else heap[0]\n            if to_remove[val] > 0:\n                to_remove[val] -= 1\n                heapq.heappop(heap)\n            else:\n                break\n\n    # Initialize with first k elements\n    for i in range(k):\n        heapq.heappush(max_heap, -nums[i])\n    # Move the larger half to min_heap\n    for _ in range(k // 2):\n        heapq.heappush(min_heap, -heapq.heappop(max_heap))\n    result.append(get_median())\n    for i in range(k, len(nums)):\n        out_val = nums[i - k]\n        in_val = nums[i]\n        # Mark element to remove\n        to_remove[out_val] += 1\n        # Determine which heap the outgoing element belongs to\n        balance = -1 if out_val <= -max_heap[0] else 1  # -1 if from max_heap\n        # Insert new element\n        if max_heap and in_val <= -max_heap[0]:\n            heapq.heappush(max_heap, -in_val)\n            balance += 1\n        else:\n            heapq.heappush(min_heap, in_val)\n            balance -= 1\n        # Rebalance based on net effect\n        if balance < 0:  # max_heap lost one net\n            heapq.heappush(max_heap, -heapq.heappop(min_heap))\n        elif balance > 0:  # min_heap lost one net\n            heapq.heappush(min_heap, -heapq.heappop(max_heap))\n        # Lazy cleanup\n        clean_top(max_heap, True)\n        clean_top(min_heap, False)\n        result.append(get_median())\n    return result\n# Expected: [1.0, 2.0, 3.0]\n# Expected: [1.0, -1.0, -1.0, 3.0, 5.0, 6.0]',
  E'class Solution {\n    public Object slidingWindowMedian(int[] nums, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.Collections;\n    // import java.util.HashMap;\n    // import java.util.List;\n    // import java.util.Map;\n    // import java.util.PriorityQueue;\n\n    public static List<Double> slidingWindowMedian(int[] nums, int k) {\n        List<Double> result = new ArrayList<>();\n        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder()); // lower half\n        PriorityQueue<Integer> minHeap = new PriorityQueue<>(); // upper half\n        Map<Integer, Integer> toRemove = new HashMap<>(); // Stores counts of elements to be removed lazily\n\n        // Helper to get the median\n        // Note: This helper needs access to maxHeap, minHeap, and k.\n        // In Java, it\'s cleaner to pass them or make them instance variables if this were a class.\n        // For a static method, we pass them.\n        // However, the Python solution has nested functions that implicitly capture scope.\n        // To mimic that, we can define these as private static helpers that take the heaps.\n        // Or, for simplicity, inline the logic where needed or pass all required state.\n        // Let\'s make them private static helpers and pass the heaps.\n\n        // Initialize with first k elements\n        for (int i = 0; i < k; i++) {\n            maxHeap.offer(-nums[i]);\n        }\n        // Move the larger half to minHeap\n        for (int i = 0; i < k / 2; i++) {\n            minHeap.offer(-maxHeap.poll());\n        }\n\n        result.add(getMedian(maxHeap, minHeap, k));\n\n        for (int i = k; i < nums.length; i++) {\n            int outVal = nums[i - k];\n            int inVal = nums[i];\n\n            // Mark element to remove\n            toRemove.put(outVal, toRemove.getOrDefault(outVal, 0) + 1);\n\n            // Determine which heap the outgoing element belongs to and adjust balance\n            int balance = 0; // +1 if maxHeap grows, -1 if minHeap grows\n            if (outVal <= -maxHeap.peek()) { // If outVal was in maxHeap\n                balance = -1; // maxHeap effectively loses an element\n            } else { // If outVal was in minHeap\n                balance = 1; // minHeap effectively loses an element\n            }\n\n            // Insert new element\n            if (!maxHeap.isEmpty() && inVal <= -maxHeap.peek()) {\n                maxHeap.offer(-inVal);\n                balance++; // maxHeap effectively gains an element\n            } else {\n                minHeap.offer(inVal);\n                balance--; // minHeap effectively gains an element\n            }\n\n            // Rebalance based on net effect\n            if (balance < 0) { // maxHeap lost one net, or minHeap gained one net\n                maxHeap.offer(-minHeap.poll());\n            } else if (balance > 0) { // minHeap lost one net, or maxHeap gained one net\n                minHeap.offer(-maxHeap.poll());\n            }\n\n            // Lazy cleanup\n            cleanTop(maxHeap, toRemove, true);\n            cleanTop(minHeap, toRemove, false);\n\n            result.add(getMedian(maxHeap, minHeap, k));\n        }\n        return result;\n    }\n\n    private static double getMedian(PriorityQueue<Integer> maxHeap, PriorityQueue<Integer> minHeap, int k) {\n        cleanTop(maxHeap, new HashMap<>(), true); // Ensure top is valid before peeking\n        cleanTop(minHeap, new HashMap<>(), false); // Ensure top is valid before peeking\n\n        if (k % 2 == 1) {\n            return -maxHeap.peek() / 1.0;\n        }\n        return (-maxHeap.peek() + minHeap.peek()) / 2.0;\n    }\n\n    private static void cleanTop(PriorityQueue<Integer> heap, Map<Integer, Integer> toRemove, boolean isMaxHeap) {\n        while (!heap.isEmpty()) {\n            int val = isMaxHeap ? -heap.peek() : heap.peek();\n            if (toRemove.getOrDefault(val, 0) > 0) {\n                toRemove.put(val, toRemove.get(val) - 1);\n                heap.poll();\n            } else {\n                break;\n            }\n        }\n    }\n}',
  E'/**\n * @param {any, any} nums, k\n * @return {any}\n */\nfunction slidingWindowMedian(nums, k) {\n    // Your code here\n}',
  E'class MinHeap {\n    constructor() {\n        this.heap = [];\n    }\n\n    peek() {\n        return this.heap.length === 0 ? null : this.heap[0];\n    }\n\n    push(value) {\n        this.heap.push(value);\n        this._bubbleUp(this.heap.length - 1);\n    }\n\n    pop() {\n        if (this.heap.length === 0) return null;\n        if (this.heap.length === 1) return this.heap.pop();\n\n        const root = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this._bubbleDown(0);\n        return root;\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    _bubbleUp(index) {\n        while (index > 0) {\n            const parentIndex = Math.floor((index - 1) / 2);\n            if (this.heap[parentIndex] > this.heap[index]) {\n                [this.heap[parentIndex], this.heap[index]] = [this.heap[index], this.heap[parentIndex]];\n                index = parentIndex;\n            } else {\n                break;\n            }\n        }\n    }\n\n    _bubbleDown(index) {\n        const lastIndex = this.heap.length - 1;\n        while (true) {\n            let leftChildIndex = 2 * index + 1;\n            let rightChildIndex = 2 * index + 2;\n            let smallestIndex = index;\n\n            if (leftChildIndex <= lastIndex && this.heap[leftChildIndex] < this.heap[smallestIndex]) {\n                smallestIndex = leftChildIndex;\n            }\n\n            if (rightChildIndex <= lastIndex && this.heap[rightChildIndex] < this.heap[smallestIndex]) {\n                smallestIndex = rightChildIndex;\n            }\n\n            if (smallestIndex !== index) {\n                [this.heap[index], this.heap[smallestIndex]] = [this.heap[smallestIndex], this.heap[index]];\n                index = smallestIndex;\n            } else {\n                break;\n            }\n        }\n    }\n}\n\nfunction slidingWindowMedian(nums, k) {\n    const result = [];\n    const maxHeap = new MinHeap(); // lower half (negated)\n    const minHeap = new MinHeap(); // upper half\n    const toRemove = new Map();\n\n    const getMedian = () => {\n        // Ensure heaps are clean before peeking\n        cleanTop(maxHeap, true);\n        cleanTop(minHeap, false);\n\n        if (k % 2 === 1) {\n            return -maxHeap.peek() / 1.0;\n        }\n        return (-maxHeap.peek() + minHeap.peek()) / 2.0;\n    };\n\n    const cleanTop = (heap, isMax) => {\n        while (heap.size() > 0) {\n            const val = isMax ? -heap.peek() : heap.peek();\n            if (toRemove.get(val) > 0) {\n                toRemove.set(val, toRemove.get(val) - 1);\n                heap.pop();\n            } else {\n                break;\n            }\n        }\n    };\n\n    // Initialize with first k elements\n    for (let i = 0; i < k; i++) {\n        maxHeap.push(-nums[i]);\n    }\n    // Move the larger half to minHeap\n    for (let i = 0; i < Math.floor(k / 2); i++) {\n        minHeap.push(-maxHeap.pop());\n    }\n\n    result.push(getMedian());\n\n    for (let i = k; i < nums.length; i++) {\n        const outVal = nums[i - k];\n        const inVal = nums[i];\n\n        // Mark element to remove\n        toRemove.set(outVal, (toRemove.get(outVal) || 0) + 1);\n\n        // Determine which heap the outgoing element belongs to\n        let balance = 0; // +1 if maxHeap grows, -1 if minHeap grows\n        if (outVal <= -maxHeap.peek()) { // If outVal was in maxHeap\n            balance = -1; // maxHeap effectively loses an element\n        } else { // If outVal was in minHeap\n            balance = 1; // minHeap effectively loses an element\n        }\n\n        // Insert new element\n        if (maxHeap.size() > 0 && inVal <= -maxHeap.peek()) {\n            maxHeap.push(-inVal);\n            balance++; // maxHeap effectively gains an element\n        } else {\n            minHeap.push(inVal);\n            balance--; // minHeap effectively gains an element\n        }\n\n        // Rebalance based on net effect\n        if (balance < 0) { // maxHeap lost one net, or minHeap gained one net\n            maxHeap.push(-minHeap.pop());\n        } else if (balance > 0) { // minHeap lost one net, or maxHeap gained one net\n            minHeap.push(-maxHeap.pop());\n        }\n\n        // Lazy cleanup\n        cleanTop(maxHeap, true);\n        cleanTop(minHeap, false);\n\n        result.push(getMedian());\n    }\n    return result;\n}',
  ARRAY['two-heaps', 'heap'],
