  'two-heaps',
  '[{"input":"sliding_window_median([1, 2, -1, 3, 5], 3)","expected_output":"[1.0, 2.0, 3.0]"},{"input":"sliding_window_median([1, 3, -1, -3, 5, 3, 6, 7], 3)","expected_output":"[1.0, -1.0, -1.0, 3.0, 5.0, 6.0]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
