INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-two-heaps-next-interval',
  'Next Interval',
  'hard',
  'Next Interval

Problem Statement

Given an array of intervals where each interval is `[start, end]`, for each interval find the index of the **next interval** — the interval whose start is greater than or equal to the current interval''s end. If no such interval exists, return `-1` for that position.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[{"input":"intervals = [[2,3],[3,4],[5,6]]","output":"[1, 2, -1]","explanation":"Next for [2,3] is [3,4] (index 1). Next for [3,4] is [5,6] (index 2). No next for [5,6]."},{"input":"intervals = [[3,4],[1,5],[4,6]]","output":"[2, -1, -1]","explanation":"Next for [3,4] is [4,6]. No interval starts at 5 or later for [1,5] or at 6+ for [4,6]."}]'::jsonb,
  'find_next_interval',
  E'import heapq\ndef find_next_interval(intervals):\n    # TODO: Return a list where result[i] is the index of the next interval for intervals[i]\n    n = len(intervals)\n    result = [-1] * n\n    return result\n\n# Expected: [1, 2, -1]\n# Expected: [2, -1, -1]',
  E'import heapq\ndef find_next_interval(intervals):\n    n = len(intervals)\n    result = [-1] * n\n\n    # Max-heaps (negate for max behavior)\n    start_heap = []  # (-start, index)\n    end_heap = []    # (-end, index)\n    for i, interval in enumerate(intervals):\n        heapq.heappush(start_heap, (-interval[0], i))\n        heapq.heappush(end_heap, (-interval[1], i))\n    while end_heap:\n        end_val, end_idx = heapq.heappop(end_heap)\n        end_val = -end_val\n        # Find the interval with the smallest start >= end_val\n        candidate = None\n        while start_heap and -start_heap[0][0] >= end_val:\n            candidate = heapq.heappop(start_heap)\n        if candidate is not None:\n            result[end_idx] = candidate[1]\n            # Push candidate back — it might be the answer for other intervals too\n            heapq.heappush(start_heap, candidate)\n    return result\n# Expected: [1, 2, -1]\n# Expected: [2, -1, -1]',
  E'class Solution {\n    public Object findNextInterval(int[] intervals) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.Collections;\n    // import java.util.List;\n    // import java.util.PriorityQueue;\n\n    // Custom class to store value and original index\n    static class Entry {\n        int value;\n        int index;\n\n        Entry(int value, int index) {\n            this.value = value;\n            this.index = index;\n        }\n    }\n\n    public static int[] findNextInterval(int[][] intervals) {\n        int n = intervals.length;\n        int[] result = new int[n];\n\n        // Max-heaps for start and end values, storing Entry objects\n        // Ordered by value in reverse for max-heap behavior\n        PriorityQueue<Entry> startHeap = new PriorityQueue<>((a, b) -> b.value - a.value); // (-start, index)\n        PriorityQueue<Entry> endHeap = new PriorityQueue<>((a, b) -> b.value - a.value);   // (-end, index)\n\n        for (int i = 0; i < n; i++) {\n            startHeap.offer(new Entry(intervals[i][0], i));\n            endHeap.offer(new Entry(intervals[i][1], i));\n        }\n\n        while (!endHeap.isEmpty()) {\n            Entry endEntry = endHeap.poll();\n            int endVal = endEntry.value;\n            int endIdx = endEntry.index;\n\n            // Find the interval with the smallest start >= endVal\n            Entry candidate = null;\n            // Pop all intervals from startHeap whose start is >= endVal\n            // The last one popped will have the smallest start >= endVal\n            while (!startHeap.isEmpty() && startHeap.peek().value >= endVal) {\n                candidate = startHeap.poll();\n            }\n\n            if (candidate != null) {\n                result[endIdx] = candidate.index;\n                // Push candidate back — it might be the answer for other intervals too\n                startHeap.offer(candidate);\n            } else {\n                result[endIdx] = -1;\n            }\n        }\n        return result;\n    }\n}',
  E'/**\n * @param {any} intervals\n * @return {any}\n */\nfunction findNextInterval(intervals) {\n    // Your code here\n}',
  E'class MinHeap {\n    constructor(comparator = (a, b) => a - b) {\n        this.heap = [];\n        this.comparator = comparator;\n    }\n\n    peek() {\n        return this.heap.length === 0 ? null : this.heap[0];\n    }\n\n    push(value) {\n        this.heap.push(value);\n        this._bubbleUp(this.heap.length - 1);\n    }\n\n    pop() {\n        if (this.heap.length === 0) return null;\n        if (this.heap.length === 1) return this.heap.pop();\n\n        const root = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this._bubbleDown(0);\n        return root;\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    _bubbleUp(index) {\n        while (index > 0) {\n            const parentIndex = Math.floor((index - 1) / 2);\n            if (this.comparator(this.heap[parentIndex], this.heap[index]) > 0) {\n                [this.heap[parentIndex], this.heap[index]] = [this.heap[index], this.heap[parentIndex]];\n                index = parentIndex;\n            } else {\n                break;\n            }\n        }\n    }\n\n    _bubbleDown(index) {\n        const lastIndex = this.heap.length - 1;\n        while (true) {\n            let leftChildIndex = 2 * index + 1;\n            let rightChildIndex = 2 * index + 2;\n            let smallestIndex = index;\n\n            if (leftChildIndex <= lastIndex && this.comparator(this.heap[leftChildIndex], this.heap[smallestIndex]) < 0) {\n                smallestIndex = leftChildIndex;\n            }\n\n            if (rightChildIndex <= lastIndex && this.comparator(this.heap[rightChildIndex], this.heap[smallestIndex]) < 0) {\n                smallestIndex = rightChildIndex;\n            }\n\n            if (smallestIndex !== index) {\n                [this.heap[index], this.heap[smallestIndex]] = [this.heap[smallestIndex], this.heap[index]];\n                index = smallestIndex;',
  ARRAY['two-heaps', 'heap'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'netflix-senior'],
  'two-heaps',
  '[{"input":"find_next_interval([[2,3],[3,4],[5,6]])","expected_output":"[1, 2, -1]"},{"input":"find_next_interval([[3,4],[1,5],[4,6]])","expected_output":"[2, -1, -1]"}]'::jsonb,
  '[]'::jsonb
