INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-two-heaps-kth-largest-stream',
  'Kth Largest Element in a Stream',
  'hard',
  'Kth Largest Element in a Stream

Problem Statement

Design a class that takes an integer `k` and an initial list of numbers. It should support an `add(val)` method that adds a new value and returns the kth largest element in the current collection.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[]'::jsonb,
  'KthLargest',
  E'import heapq\nclass KthLargest:\n    def __init__(self, k, nums):\n        self.k = k\n        self.heap = []\n        # TODO: Initialize the heap with the k largest from nums\n\n    def add(self, val):\n        # TODO: Add val and return the kth largest element\n        pass\n\nkl = KthLargest(3, [4, 5, 8, 2])\nkl2 = KthLargest(1, [])',
  E'import heapq\nclass KthLargest:\n    def __init__(self, k, nums):\n        self.k = k\n        self.heap = []\n        for num in nums:\n            heapq.heappush(self.heap, num)\n            if len(self.heap) > k:\n                heapq.heappop(self.heap)\n\n    def add(self, val):\n        heapq.heappush(self.heap, val)\n        if len(self.heap) > self.k:\n            heapq.heappop(self.heap)\n        return self.heap[0]\n\nkl = KthLargest(3, [4, 5, 8, 2])\nkl2 = KthLargest(1, [])',
  E'class Solution {\n    public Object KthLargest(int k, int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static class KthLargest {\n        private int k;\n        private java.util.PriorityQueue<Integer> heap;\n\n        public KthLargest(int k, int[] nums) {\n            this.k = k;\n            this.heap = new java.util.PriorityQueue<>();\n            for (int num : nums) {\n                heap.offer(num);\n                if (heap.size() > k) {\n                    heap.poll();\n                }\n            }\n        }\n\n        public int add(int val) {\n            heap.offer(val);\n            if (heap.size() > k) {\n                heap.poll();\n            }\n            return heap.peek();\n        }\n    }\n}',
  E'/**\n * @param {any, any} k, nums\n * @return {any}\n */\nfunction KthLargest(k, nums) {\n    // Your code here\n}',
  E'class MinHeap {\n    constructor() {\n        this.heap = [];\n    }\n\n    getParentIndex(i) { return Math.floor((i - 1) / 2); }\n    getLeftChildIndex(i) { return 2 * i + 1; }\n    getRightChildIndex(i) { return 2 * i + 2; }\n\n    hasParent(i) { return this.getParentIndex(i) >= 0; }\n    hasLeftChild(i) { return this.getLeftChildIndex(i) < this.heap.length; }\n    hasRightChild(i) { return this.getRightChildIndex(i) < this.heap.length; }\n\n    getParent(i) { return this.heap[this.getParentIndex(i)]; }\n    getLeftChild(i) { return this.heap[this.getLeftChildIndex(i)]; }\n    getRightChild(i) { return this.heap[this.getRightChildIndex(i)]; }\n\n    swap(i1, i2) {\n        [this.heap[i1], this.heap[i2]] = [this.heap[i2], this.heap[i1]];\n    }\n\n    peek() {\n        if (this.heap.length === 0) return null;\n        return this.heap[0];\n    }\n\n    insert(item) {\n        this.heap.push(item);\n        this._heapifyUp();\n    }\n\n    extractMin() {\n        if (this.heap.length === 0) return null;\n        if (this.heap.length === 1) return this.heap.pop();\n\n        const item = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this._heapifyDown();\n        return item;\n    }\n\n    _heapifyUp() {\n        let index = this.heap.length - 1;\n        while (this.hasParent(index) && this.getParent(index) > this.heap[index]) {\n            this.swap(this.getParentIndex(index), index);\n            index = this.getParentIndex(index);\n        }\n    }\n\n    _heapifyDown() {\n        let index = 0;\n        while (this.hasLeftChild(index)) {\n            let smallerChildIndex = this.getLeftChildIndex(index);\n            if (this.hasRightChild(index) && this.getRightChild(index) < this.getLeftChild(index)) {\n                smallerChildIndex = this.getRightChildIndex(index);\n            }\n\n            if (this.heap[index] < this.heap[smallerChildIndex]) {\n                break;\n            } else {\n                this.swap(index, smallerChildIndex);\n            }\n            index = smallerChildIndex;\n        }\n    }\n\n    size() {\n        return this.heap.length;\n    }\n}\n\nclass KthLargest {\n    constructor(k, nums) {\n        this.k = k;\n        this.heap = new MinHeap();\n        for (const num of nums) {\n            this.heap.insert(num);\n            if (this.heap.size() > k) {\n                this.heap.extractMin();\n            }\n        }\n    }\n\n    add(val) {\n        this.heap.insert(val);\n        if (this.heap.size() > this.k) {\n            this.heap.extractMin();\n        }\n        return this.heap.peek();\n    }\n}\n\n// Example usage (not part of the required output, but for context)\n// const kl = new KthLargest(3, [4, 5, 8, 2]);\n// const kl2 = new KthLargest(1, []);',
  ARRAY['two-heaps', 'heap'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'netflix-senior'],
  'two-heaps',
  '[]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
