INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-subsets-basic',
  'Subsets',
  'easy',
  'Subsets

Problem Statement

Given a set of **distinct** integers, return all possible subsets (the power set). The solution must not contain duplicate subsets.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[{"input":"[1, 3]","output":"[[], [1], [3], [1, 3]]"},{"input":"[1, 5, 3]","output":"[[], [1], [5], [1,5], [3], [1,3], [5,3], [1,5,3]]"}]'::jsonb,
  'find_subsets',
  E'def find_subsets(nums):\n    # TODO: Return all subsets of the input list\n    subsets = []\n    return subsets\n\n# Expected: [[], [1], [3], [1, 3]]\n# Expected: [[], [1], [5], [1, 5], [3], [1, 3], [5, 3], [1, 5, 3]]',
  E'def find_subsets(nums):\n    subsets = [[]]\n    for num in nums:\n        new_subsets = []\n        for subset in subsets:\n            new_subsets.append(subset + [num])\n        subsets.extend(new_subsets)\n    return subsets\n\n# Expected: [[], [1], [3], [1, 3]]\n# Expected: [[], [1], [5], [1, 5], [3], [1, 3], [5, 3], [1, 5, 3]]',
  E'class Solution {\n    public Object findSubsets(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static java.util.List<java.util.List<Integer>> findSubsets(int[] nums) {\n        java.util.List<java.util.List<Integer>> subsets = new java.util.ArrayList<>();\n        subsets.add(new java.util.ArrayList<>());\n\n        for (int num : nums) {\n            java.util.List<java.util.List<Integer>> newSubsets = new java.util.ArrayList<>();\n            for (java.util.List<Integer> subset : subsets) {\n                java.util.List<Integer> newSubset = new java.util.ArrayList<>(subset);\n                newSubset.add(num);\n                newSubsets.add(newSubset);\n            }\n            subsets.addAll(newSubsets);\n        }\n        return subsets;\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction findSubsets(nums) {\n    // Your code here\n}',
  E'function findSubsets(nums) {\n    let subsets = [[]];\n\n    for (const num of nums) {\n        let newSubsets = [];\n        for (const subset of subsets) {\n            newSubsets.push([...subset, num]);\n        }\n        subsets.push(...newSubsets);\n    }\n    return subsets;\n}',
  ARRAY['subsets'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'airbnb-swe'],
  'subsets',
  '[{"input":"find_subsets([1, 3])","expected_output":"[[], [1], [3], [1, 3]]"},{"input":"find_subsets([1, 5, 3])","expected_output":"[[], [1], [5], [1, 5], [3], [1, 3], [5, 3], [1, 5, 3]]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
