INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-subsets-duplicates',
  'Subsets With Duplicates',
  'easy',
  'Subsets With Duplicates

Problem Statement

Given a set of numbers that **may contain duplicates**, find all distinct subsets.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[{"input":"[1, 3, 3]","output":"[[], [1], [3], [1,3], [3,3], [1,3,3]]"},{"input":"[1, 5, 3, 3]","output":"[[], [1], [3], [1,3], [3,3], [1,3,3], [5], [1,5], [3,5], [1,3,5], [3,3,5], [1,3,3,5]]"}]'::jsonb,
  'find_subsets_with_duplicates',
  E'def find_subsets_with_duplicates(nums):\n    # TODO: Return all distinct subsets\n    subsets = []\n    return subsets\n\n# Expected: [[], [1], [3], [1, 3], [3, 3], [1, 3, 3]]\n# Expected: [[], [1], [3], [1, 3], [3, 3], [1, 3, 3], [5], [1, 5], [3, 5], [1, 3, 5], [3, 3, 5], [1, 3, 3, 5]]',
  E'def find_subsets_with_duplicates(nums):\n    nums.sort()\n    subsets = [[]]\n    start_index = 0\n\n    for i in range(len(nums)):\n        # If current is duplicate, only extend subsets added last round\n        if i > 0 and nums[i] == nums[i - 1]:\n            begin = start_index\n        else:\n            begin = 0\n        start_index = len(subsets)\n        new_subsets = []\n        for j in range(begin, len(subsets)):\n            new_subsets.append(subsets[j] + [nums[i]])\n        subsets.extend(new_subsets)\n    return subsets\n# Expected: [[], [1], [3], [1, 3], [3, 3], [1, 3, 3]]\n# Expected: [[], [1], [3], [1, 3], [3, 3], [1, 3, 3], [5], [1, 5], [3, 5], [1, 3, 5], [3, 3, 5], [1, 3, 3, 5]]',
  E'class Solution {\n    public Object findSubsetsWithDuplicates(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static java.util.List<java.util.List<Integer>> findSubsetsWithDuplicates(int[] nums) {\n        java.util.Arrays.sort(nums);\n        java.util.List<java.util.List<Integer>> subsets = new java.util.ArrayList<>();\n        subsets.add(new java.util.ArrayList<>());\n        int startIndex = 0;\n\n        for (int i = 0; i < nums.length; i++) {\n            int begin;\n            // If current is duplicate, only extend subsets added last round\n            if (i > 0 && nums[i] == nums[i - 1]) {\n                begin = startIndex;\n            } else {\n                begin = 0;\n            }\n            startIndex = subsets.size(); // Store the size before adding new subsets\n            java.util.List<java.util.List<Integer>> newSubsets = new java.util.ArrayList<>();\n            for (int j = begin; j < subsets.size(); j++) {\n                java.util.List<Integer> currentSubset = subsets.get(j);\n                java.util.List<Integer> newSubset = new java.util.ArrayList<>(currentSubset);\n                newSubset.add(nums[i]);\n                newSubsets.add(newSubset);\n            }\n            subsets.addAll(newSubsets);\n        }\n        return subsets;\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction findSubsetsWithDuplicates(nums) {\n    // Your code here\n}',
  E'function findSubsetsWithDuplicates(nums) {\n    nums.sort((a, b) => a - b);\n    let subsets = [[]];\n    let startIndex = 0;\n\n    for (let i = 0; i < nums.length; i++) {\n        let begin;\n        // If current is duplicate, only extend subsets added last round\n        if (i > 0 && nums[i] === nums[i - 1]) {\n            begin = startIndex;\n        } else {\n            begin = 0;\n        }\n        startIndex = subsets.length; // Store the length before adding new subsets\n        let newSubsets = [];\n        for (let j = begin; j < subsets.length; j++) {\n            newSubsets.push([...subsets[j], nums[i]]);\n        }\n        subsets.push(...newSubsets);\n    }\n    return subsets;\n}',
  ARRAY['subsets'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'airbnb-swe'],
  'subsets',
  '[{"input":"find_subsets_with_duplicates([1, 3, 3])","expected_output":"[[], [1], [3], [1, 3], [3, 3], [1, 3, 3]]"},{"input":"find_subsets_with_duplicates([1, 5, 3, 3])","expected_output":"[[], [1], [3], [1, 3], [3, 3], [1, 3, 3], [5], [1, 5], [3, 5], [1, 3, 5], [3, 3, 5], [1, 3, 3, 5]]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
