INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-subsets-permutations',
  'Permutations',
  'hard',
  'Permutations

Problem Statement

Given a set of **distinct** numbers, find all permutations.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[{"input":"[1, 3, 5]","output":"[[1,3,5],[1,5,3],[3,1,5],[3,5,1],[5,1,3],[5,3,1]]"},{"input":"[1, 2]","output":"[[1,2],[2,1]]"}]'::jsonb,
  'find_permutations',
  E'def find_permutations(nums):\n    # TODO: Return all permutations of the input list\n    result = []\n    return result\n\n# Expected: [[1,3,5],[1,5,3],[3,1,5],[3,5,1],[5,1,3],[5,3,1]]\n# Expected: [[1, 2], [2, 1]]',
  E'def find_permutations(nums):\n    result = [[]]\n\n    for num in nums:\n        new_perms = []\n        for perm in result:\n            for i in range(len(perm) + 1):\n                new_perm = list(perm)\n                new_perm.insert(i, num)\n                new_perms.append(new_perm)\n        result = new_perms\n    return result\n# Expected: [[5,3,1],[5,1,3],[3,5,1],[1,5,3],[3,1,5],[1,3,5]]\n# Expected: [[2, 1], [1, 2]]',
  E'class Solution {\n    public Object findPermutations(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayList;\nimport java.util.List;\n\nclass Solution {\n    public static List<List<Integer>> findPermutations(List<Integer> nums) {\n        List<List<Integer>> result = new ArrayList<>();\n        result.add(new ArrayList<>()); // Start with an empty permutation\n\n        for (int num : nums) {\n            List<List<Integer>> newPerms = new ArrayList<>();\n            for (List<Integer> perm : result) {\n                // Insert the current number at all possible positions in each existing permutation\n                for (int i = 0; i <= perm.size(); i++) {\n                    List<Integer> newPerm = new ArrayList<>(perm); // Create a copy\n                    newPerm.add(i, num); // Insert the number\n                    newPerms.add(newPerm);\n                }\n            }\n            result = newPerms; // Update result with the new permutations\n        }\n        return result;\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction findPermutations(nums) {\n    // Your code here\n}',
  E'function findPermutations(nums) {\n    let result = [[]]; // Start with an empty permutation\n\n    for (const num of nums) {\n        const newPerms = [];\n        for (const perm of result) {\n            // Insert the current number at all possible positions in each existing permutation\n            for (let i = 0; i <= perm.length; i++) {\n                const newPerm = [...perm]; // Create a copy\n                newPerm.splice(i, 0, num); // Insert the number\n                newPerms.push(newPerm);\n            }\n        }\n        result = newPerms; // Update result with the new permutations\n    }\n    return result;\n}',
  ARRAY['subsets'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'airbnb-swe'],
  'subsets',
  '[{"input":"find_permutations([1, 3, 5])","expected_output":"[[1,3,5],[1,5,3],[3,1,5],[3,5,1],[5,1,3],[5,3,1]]"},{"input":"find_permutations([1, 2])","expected_output":"[[1, 2], [2, 1]]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
