INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-subsets-string-case-permutations',
  'String Permutations by Changing Case',
  'hard',
  'String Permutations by Changing Case

Problem Statement

Given a string, find all permutations of it by changing the case of individual letters. Non-letter characters remain unchanged.

Examples

**Example 1:**

**Example 2:**

**Example 3:**',
  '',
  '[{"input":"\"ab7c\"","output":"[\"ab7c\", \"Ab7c\", \"aB7c\", \"AB7c\", \"ab7C\", \"Ab7C\", \"aB7C\", \"AB7C\"]"},{"input":"\"a1b\"","output":"[\"a1b\", \"A1b\", \"a1B\", \"A1B\"]"},{"input":"\"12\"","output":"[\"12\"]"}]'::jsonb,
  'letter_case_permutation',
  E'def letter_case_permutation(s):\n    # TODO: Return all case permutations of the string\n    result = []\n    return result\n\n# Expected: ["ab7c", "Ab7c", "aB7c", "AB7c", "ab7C", "Ab7C", "aB7C", "AB7C"]\n# Expected: ["a1b", "A1b", "a1B", "A1B"]\n# Expected: ["12"]',
  E'def letter_case_permutation(s):\n    result = [list(s)]\n\n    for i in range(len(s)):\n        if s[i].isalpha():\n            n = len(result)\n            for j in range(n):\n                new_str = list(result[j])\n                new_str[i] = new_str[i].swapcase()\n                result.append(new_str)\n    return ["".join(r) for r in result]\n# Expected: ["ab7c", "Ab7c", "aB7c", "AB7c", "ab7C", "Ab7C", "aB7C", "AB7C"]\n# Expected: ["a1b", "A1b", "a1B", "A1B"]\n# Expected: ["12"]',
  E'class Solution {\n    public Object letterCasePermutation(String s) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.List;\n    // import java.util.stream.Collectors;\n\n    public static List<String> letterCasePermutation(String s) {\n        List<char[]> result = new ArrayList<>();\n        result.add(s.toCharArray());\n\n        for (int i = 0; i < s.length(); i++) {\n            if (Character.isLetter(s.charAt(i))) {\n                int n = result.size();\n                for (int j = 0; j < n; j++) {\n                    char[] newStr = result.get(j).clone(); // Create a copy\n                    if (Character.isLowerCase(newStr[i])) {\n                        newStr[i] = Character.toUpperCase(newStr[i]);\n                    } else {\n                        newStr[i] = Character.toLowerCase(newStr[i]);\n                    }\n                    result.add(newStr);\n                }\n            }\n        }\n        return result.stream().map(String::new).collect(Collectors.toList());\n    }\n}',
  E'/**\n * @param {any} s\n * @return {any}\n */\nfunction letterCasePermutation(s) {\n    // Your code here\n}',
  E'function letterCasePermutation(s) {\n    let result = [s.split(\'\')];\n\n    for (let i = 0; i < s.length; i++) {\n        if (/[a-zA-Z]/.test(s[i])) { // Check if character is a letter\n            const n = result.length;\n            for (let j = 0; j < n; j++) {\n                const newStr = [...result[j]]; // Create a copy\n                if (newStr[i] === newStr[i].toLowerCase()) {\n                    newStr[i] = newStr[i].toUpperCase();\n                } else {\n                    newStr[i] = newStr[i].toLowerCase();\n                }\n                result.push(newStr);\n            }\n        }\n    }\n    return result.map(r => r.join(\'\'));\n}',
  ARRAY['subsets'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'airbnb-swe'],
  'subsets',
  '[{"input":"letter_case_permutation(\"ab7c\")","expected_output":"[\"ab7c\", \"Ab7c\", \"aB7c\", \"AB7c\", \"ab7C\", \"Ab7C\", \"aB7C\", \"AB7C\"]"},{"input":"letter_case_permutation(\"a1b\")","expected_output":"[\"a1b\", \"A1b\", \"a1B\", \"A1B\"]"},{"input":"letter_case_permutation(\"12\")","expected_output":"[\"12\"]"}]'::jsonb,
