INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-subsets-balanced-parentheses',
  'Balanced Parentheses',
  'hard',
  'Balanced Parentheses

Problem Statement

Given a number `n`, generate all strings containing `n` pairs of balanced parentheses.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[{"input":"n = 2","output":"[\"(())\", \"()()\"]"},{"input":"n = 3","output":"[\"((()))\", \"(()())\", \"(())()\", \"()(())\", \"()()()\"]"}]'::jsonb,
  'generate_parentheses',
  E'from collections import deque\ndef generate_parentheses(n):\n    # TODO: Return all valid combinations of n pairs of parentheses\n    result = []\n    return result\n\n# Expected: ["(())", "()()"]\n# Expected: ["((()))", "(()())", "(())()", "()(())", "()()()"]',
  E'from collections import deque\ndef generate_parentheses(n):\n    result = []\n    queue = deque()\n    queue.append(("", 0, 0))  # (current_string, open_count, close_count)\n\n    while queue:\n        current, open_count, close_count = queue.popleft()\n        if open_count == n and close_count == n:\n            result.append(current)\n            continue\n        if open_count < n:\n            queue.append((current + "(", open_count + 1, close_count))\n        if close_count < open_count:\n            queue.append((current + ")", open_count, close_count + 1))\n    return result\n# Expected: ["(())", "()()"]\n# Expected: ["((()))", "(()())", "(())()", "()(())", "()()()"]',
  E'class Solution {\n    public Object generateParentheses(int n) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.LinkedList;\n    // import java.util.List;\n    // import java.util.Queue;\n\n    // Helper class to simulate a tuple\n    private static class ParenthesisState {\n        String currentString;\n        int openCount;\n        int closeCount;\n\n        ParenthesisState(String currentString, int openCount, int closeCount) {\n            this.currentString = currentString;\n            this.openCount = openCount;\n            this.closeCount = closeCount;\n        }\n    }\n\n    public static List<String> generateParentheses(int n) {\n        List<String> result = new ArrayList<>();\n        Queue<ParenthesisState> queue = new LinkedList<>();\n        queue.offer(new ParenthesisState("", 0, 0));\n\n        while (!queue.isEmpty()) {\n            ParenthesisState state = queue.poll();\n            String current = state.currentString;\n            int openCount = state.openCount;\n            int closeCount = state.closeCount;\n\n            if (openCount == n && closeCount == n) {\n                result.add(current);\n                continue;\n            }\n\n            if (openCount < n) {\n                queue.offer(new ParenthesisState(current + "(", openCount + 1, closeCount));\n            }\n            if (closeCount < openCount) {\n                queue.offer(new ParenthesisState(current + ")", openCount, closeCount + 1));\n            }\n        }\n        return result;\n    }\n}',
  E'/**\n * @param {any} n\n * @return {any}\n */\nfunction generateParentheses(n) {\n    // Your code here\n}',
  E'function generateParentheses(n) {\n    const result = [];\n    const queue = []; // Using an array as a queue\n\n    // Each element in the queue is an array: [current_string, open_count, close_count]\n    queue.push(["", 0, 0]);\n\n    while (queue.length > 0) {\n        const [current, openCount, closeCount] = queue.shift(); // Dequeue\n\n        if (openCount === n && closeCount === n) {\n            result.push(current);\n            continue;\n        }\n\n        if (openCount < n) {\n            queue.push([current + "(", openCount + 1, closeCount]);\n        }\n        if (closeCount < openCount) {\n            queue.push([current + ")", openCount, closeCount + 1]);\n        }\n    }\n    return result;\n}',
  ARRAY['subsets'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'airbnb-swe'],
  'subsets',
  '[{"input":"generate_parentheses(2)","expected_output":"[\"(())\", \"()()\"]"},{"input":"generate_parentheses(3)","expected_output":"[\"((()))\", \"(()())\", \"(())()\", \"()(())\", \"()()()\"]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
