INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-modified-bs-order-agnostic',
  'Order-agnostic Binary Search',
  'easy',
  'Order-agnostic Binary Search

Problem Statement

Given a sorted array that could be in **ascending or descending** order, find the index of a given target. Return `-1` if the target is not found.

Examples

**Example 1:**

**Example 2:**

**Example 3:**',
  '',
  '[{"input":"arr = [1, 3, 8, 10, 15], target = 10","output":"3"},{"input":"arr = [15, 10, 8, 3, 1], target = 10","output":"1"},{"input":"arr = [4, 6, 10], target = 5","output":"-1"}]'::jsonb,
  'order_agnostic_binary_search',
  E'def order_agnostic_binary_search(arr, target):\n    # TODO: Search for target in a sorted array (ascending or descending)\n    return -1\n\n# Expected: 3\n# Expected: 1\n# Expected: -1',
  E'def order_agnostic_binary_search(arr, target):\n    lo, hi = 0, len(arr) - 1\n    is_ascending = arr[lo] < arr[hi]\n\n    while lo <= hi:\n        mid = lo + (hi - lo) // 2\n        if arr[mid] == target:\n            return mid\n        if is_ascending:\n            if arr[mid] < target:\n                lo = mid + 1\n            else:\n                hi = mid - 1\n        else:\n            if arr[mid] > target:\n                lo = mid + 1\n            else:\n                hi = mid - 1\n    return -1\n# Expected: 3\n# Expected: 1\n# Expected: -1',
  E'class Solution {\n    public Object orderAgnosticBinarySearch(int[] arr, int target) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int orderAgnosticBinarySearch(int[] arr, int target) {\n        int lo = 0;\n        int hi = arr.length - 1;\n        boolean isAscending = arr[lo] < arr[hi];\n\n        while (lo <= hi) {\n            int mid = lo + (hi - lo) / 2;\n            if (arr[mid] == target) {\n                return mid;\n            }\n            if (isAscending) {\n                if (arr[mid] < target) {\n                    lo = mid + 1;\n                } else {\n                    hi = mid - 1;\n                }\n            } else { // Descending order\n                if (arr[mid] > target) {\n                    lo = mid + 1;\n                } else {\n                    hi = mid - 1;\n                }\n            }\n        }\n        return -1;\n    }\n}',
  E'/**\n * @param {any, any} arr, target\n * @return {any}\n */\nfunction orderAgnosticBinarySearch(arr, target) {\n    // Your code here\n}',
  E'function orderAgnosticBinarySearch(arr, target) {\n    let lo = 0;\n    let hi = arr.length - 1;\n    const isAscending = arr[lo] < arr[hi];\n\n    while (lo <= hi) {\n        const mid = lo + Math.floor((hi - lo) / 2);\n        if (arr[mid] === target) {\n            return mid;\n        }\n        if (isAscending) {\n            if (arr[mid] < target) {\n                lo = mid + 1;\n            } else {\n                hi = mid - 1;\n            }\n        } else { // Descending order\n            if (arr[mid] > target) {\n                lo = mid + 1;\n            } else {\n                hi = mid - 1;\n            }\n        }\n    }\n    return -1;\n}',
  ARRAY['modified-binary-search'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'modified-binary-search',
  '[{"input":"order_agnostic_binary_search([1, 3, 8, 10, 15], 10)","expected_output":"3"},{"input":"order_agnostic_binary_search([15, 10, 8, 3, 1], 10)","expected_output":"1"},{"input":"order_agnostic_binary_search([4, 6, 10], 5)","expected_output":"-1"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
