INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-modified-bs-ceiling',
  'Ceiling of a Number',
  'easy',
  'Ceiling of a Number

Problem Statement

Given a sorted array in ascending order and a target number, find the index of the **smallest element that is greater than or equal to** the target. If no such element exists, return `-1`.

Examples

**Example 1:**

**Example 2:**

**Example 3:**',
  '',
  '[{"input":"arr = [1, 3, 8, 10, 15], target = 4","output":"2 (arr[2] = 8 is the ceiling of 4)"},{"input":"arr = [1, 3, 8, 10, 15], target = 8","output":"2 (exact match)"},{"input":"arr = [1, 3, 8, 10, 15], target = 16","output":"-1 (no element >= 16)"}]'::jsonb,
  'search_ceiling',
  E'def search_ceiling(arr, target):\n    # TODO: Find the index of the smallest element >= target\n    return -1\n\n# Expected: 2\n# Expected: 2\n# Expected: -1',
  E'def search_ceiling(arr, target):\n    if target > arr[-1]:\n        return -1\n\n    lo, hi = 0, len(arr) - 1\n    while lo <= hi:\n        mid = lo + (hi - lo) // 2\n        if arr[mid] == target:\n            return mid\n        elif arr[mid] < target:\n            lo = mid + 1\n        else:\n            hi = mid - 1\n    # lo is now the index of the smallest element >= target\n    return lo\n# Expected: 2\n# Expected: 2\n# Expected: -1',
  E'class Solution {\n    public Object searchCeiling(int[] arr, int target) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int searchCeiling(int[] arr, int target) {\n        // If target is greater than the largest element, no ceiling exists\n        if (target > arr[arr.length - 1]) {\n            return -1;\n        }\n\n        int lo = 0;\n        int hi = arr.length - 1;\n        while (lo <= hi) {\n            int mid = lo + (hi - lo) / 2;\n            if (arr[mid] == target) {\n                return mid;\n            } else if (arr[mid] < target) {\n                lo = mid + 1;\n            } else { // arr[mid] > target\n                hi = mid - 1;\n            }\n        }\n        // At the end of the loop, \'lo\' will be the index of the smallest element >= target\n        return lo;\n    }\n}',
  E'/**\n * @param {any, any} arr, target\n * @return {any}\n */\nfunction searchCeiling(arr, target) {\n    // Your code here\n}',
  E'function searchCeiling(arr, target) {\n    // If target is greater than the largest element, no ceiling exists\n    if (target > arr[arr.length - 1]) {\n        return -1;\n    }\n\n    let lo = 0;\n    let hi = arr.length - 1;\n    while (lo <= hi) {\n        const mid = lo + Math.floor((hi - lo) / 2);\n        if (arr[mid] === target) {\n            return mid;\n        } else if (arr[mid] < target) {\n            lo = mid + 1;\n        } else { // arr[mid] > target\n            hi = mid - 1;\n        }\n    }\n    // At the end of the loop, \'lo\' will be the index of the smallest element >= target\n    return lo;\n}',
  ARRAY['modified-binary-search'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'modified-binary-search',
  '[{"input":"search_ceiling([1, 3, 8, 10, 15], 4)","expected_output":"2"},{"input":"search_ceiling([1, 3, 8, 10, 15], 8)","expected_output":"2"},{"input":"search_ceiling([1, 3, 8, 10, 15], 16)","expected_output":"-1"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
