INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-modified-bs-rotated-search',
  'Search in Rotated Sorted Array',
  'hard',
  'Search in Rotated Sorted Array

Problem Statement

Given a sorted array that has been rotated at some unknown pivot, find the index of a given target. Return `-1` if not found. The array has no duplicates.

A rotated array `[4,5,6,7,0,1,2]` was originally `[0,1,2,4,5,6,7]` rotated at index 4.

Examples

**Example 1:**

**Example 2:**

**Example 3:**',
  '',
  '[{"input":"arr = [4,5,6,7,0,1,2], target = 0","output":"4"},{"input":"arr = [10,15,1,3,8], target = 15","output":"1"},{"input":"arr = [4,5,6,7,0,1,2], target = 3","output":"-1"}]'::jsonb,
  'search_rotated_array',
  E'def search_rotated_array(arr, target):\n    # TODO: Find target in a rotated sorted array\n    return -1\n\n# Expected: 4\n# Expected: 1\n# Expected: -1',
  E'def search_rotated_array(arr, target):\n    lo, hi = 0, len(arr) - 1\n\n    while lo <= hi:\n        mid = lo + (hi - lo) // 2\n        if arr[mid] == target:\n            return mid\n        # Left half is sorted\n        if arr[lo] <= arr[mid]:\n            if arr[lo] <= target < arr[mid]:\n                hi = mid - 1\n            else:\n                lo = mid + 1\n        # Right half is sorted\n        else:\n            if arr[mid] < target <= arr[hi]:\n                lo = mid + 1\n            else:\n                hi = mid - 1\n    return -1\n# Expected: 4\n# Expected: 1\n# Expected: -1',
  E'class Solution {\n    public Object searchRotatedArray(int[] arr, int target) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int searchRotatedArray(int[] arr, int target) {\n        int lo = 0;\n        int hi = arr.length - 1;\n\n        while (lo <= hi) {\n            int mid = lo + (hi - lo) / 2;\n            if (arr[mid] == target) {\n                return mid;\n            }\n            // Check if the left half is sorted\n            if (arr[lo] <= arr[mid]) {\n                if (arr[lo] <= target && target < arr[mid]) {\n                    hi = mid - 1;\n                } else {\n                    lo = mid + 1;\n                }\n            }\n            // Otherwise, the right half must be sorted\n            else {\n                if (arr[mid] < target && target <= arr[hi]) {\n                    lo = mid + 1;\n                } else {\n                    hi = mid - 1;\n                }\n            }\n        }\n        return -1;\n    }\n}',
  E'/**\n * @param {any, any} arr, target\n * @return {any}\n */\nfunction searchRotatedArray(arr, target) {\n    // Your code here\n}',
  E'function searchRotatedArray(arr, target) {\n    let lo = 0;\n    let hi = arr.length - 1;\n\n    while (lo <= hi) {\n        const mid = lo + Math.floor((hi - lo) / 2);\n        if (arr[mid] === target) {\n            return mid;\n        }\n        // Check if the left half is sorted\n        if (arr[lo] <= arr[mid]) {\n            if (arr[lo] <= target && target < arr[mid]) {\n                hi = mid - 1;\n            } else {\n                lo = mid + 1;\n            }\n        }\n        // Otherwise, the right half must be sorted\n        else {\n            if (arr[mid] < target && target <= arr[hi]) {\n                lo = mid + 1;\n            } else {\n                hi = mid - 1;\n            }\n        }\n    }\n    return -1;\n}',
  ARRAY['modified-binary-search'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'modified-binary-search',
  '[{"input":"search_rotated_array([4, 5, 6, 7, 0, 1, 2], 0)","expected_output":"4"},{"input":"search_rotated_array([10, 15, 1, 3, 8], 15)","expected_output":"1"},{"input":"search_rotated_array([4, 5, 6, 7, 0, 1, 2], 3)","expected_output":"-1"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
