INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-modified-bs-rotated-minimum',
  'Minimum in Rotated Sorted Array',
  'hard',
  'Minimum in Rotated Sorted Array

Problem Statement

Given a sorted array of distinct elements that has been rotated, find the **minimum element**. The array was originally sorted in ascending order.

Examples

**Example 1:**

**Example 2:**

**Example 3:**',
  '',
  '[{"input":"[4, 5, 6, 1, 2, 3]","output":"1"},{"input":"[3, 1, 2]","output":"1"},{"input":"[1, 2, 3, 4, 5]","output":"1 (not rotated)"}]'::jsonb,
  'find_min_rotated',
  E'def find_min_rotated(arr):\n    # TODO: Find the minimum element in a rotated sorted array\n    return -1\n\n# Expected: 1\n# Expected: 1\n# Expected: 1',
  E'def find_min_rotated(arr):\n    lo, hi = 0, len(arr) - 1\n\n    while lo < hi:\n        mid = lo + (hi - lo) // 2\n        if arr[mid] > arr[hi]:\n            # Minimum is in the right half\n            lo = mid + 1\n        else:\n            # Minimum is at mid or in the left half\n            hi = mid\n    return arr[lo]\n# Expected: 1\n# Expected: 1\n# Expected: 1',
  E'class Solution {\n    public Object findMinRotated(int[] arr) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int findMinRotated(int[] arr) {\n        int lo = 0;\n        int hi = arr.length - 1;\n\n        while (lo < hi) {\n            int mid = lo + (hi - lo) / 2;\n            if (arr[mid] > arr[hi]) {\n                // The minimum is in the right half (mid+1 to hi)\n                lo = mid + 1;\n            } else {\n                // The minimum is at mid or in the left half (lo to mid)\n                hi = mid;\n            }\n        }\n        // When lo == hi, we have found the minimum element\n        return arr[lo];\n    }\n}',
  E'/**\n * @param {any} arr\n * @return {any}\n */\nfunction findMinRotated(arr) {\n    // Your code here\n}',
  E'function findMinRotated(arr) {\n    let lo = 0;\n    let hi = arr.length - 1;\n\n    while (lo < hi) {\n        const mid = lo + Math.floor((hi - lo) / 2);\n        if (arr[mid] > arr[hi]) {\n            // The minimum is in the right half (mid+1 to hi)\n            lo = mid + 1;\n        } else {\n            // The minimum is at mid or in the left half (lo to mid)\n            hi = mid;\n        }\n    }\n    // When lo == hi, we have found the minimum element\n    return arr[lo];\n}',
  ARRAY['modified-binary-search'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
