INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-bitwise-xor-two-single-numbers',
  'Two Single Numbers',
  'easy',
  'Two Single Numbers

Problem Statement

Given an array where every element appears **twice** except for **two** elements that appear only once, find those two unique elements.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[{"input":"[1, 4, 2, 1, 3, 5, 6, 2, 3, 5]","output":"[4, 6] (order may vary)"},{"input":"[2, 1, 3, 2]","output":"[1, 3]"}]'::jsonb,
  'find_two_single_numbers',
  E'def find_two_single_numbers(nums):\n    # TODO: Find the two numbers that appear only once\n    pass\n\n# Expected: [4, 6] (order may vary)\n# Expected: [1, 3] (order may vary)',
  E'def find_two_single_numbers(nums):\n    # Step 1: XOR all numbers to get a ^ b\n    xor_all = 0\n    for num in nums:\n        xor_all ^= num\n\n    # Step 2: Find a distinguishing bit (rightmost set bit)\n    diff_bit = xor_all & (-xor_all)\n    # Step 3: Partition and XOR each group\n    num1, num2 = 0, 0\n    for num in nums:\n        if num & diff_bit:\n            num1 ^= num\n        else:\n            num2 ^= num\n    return [num1, num2]\n# Expected: [4, 6] (order may vary)\n# Expected: [1, 3] (order may vary)',
  E'class Solution {\n    public Object findTwoSingleNumbers(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.List;\n\n    public static int[] findTwoSingleNumbers(int[] nums) {\n        // Step 1: XOR all numbers to get a ^ b\n        int xorAll = 0;\n        for (int num : nums) {\n            xorAll ^= num;\n        }\n\n        // Step 2: Find a distinguishing bit (rightmost set bit)\n        // xorAll & (-xorAll) isolates the rightmost set bit.\n        // For example, if xorAll is 12 (1100), -xorAll is -12 (two\'s complement: 0100 + 1 = 0100, then invert and add 1: 0011 -> 1100 + 1 = 1101, wait, this is wrong.\n        // -N in two\'s complement is ~N + 1.\n        // If xorAll = 12 (0...01100)\n        // ~xorAll = 1...10011\n        // ~xorAll + 1 = 1...10100\n        // xorAll & (~xorAll + 1) = 0...01100 & 1...10100 = 0...00100 (which is 4)\n        // This correctly isolates the rightmost set bit.\n        int diffBit = xorAll & (-xorAll);\n\n        // Step 3: Partition and XOR each group\n        int num1 = 0;\n        int num2 = 0;\n        for (int num : nums) {\n            if ((num & diffBit) != 0) { // Check if the distinguishing bit is set in \'num\'\n                num1 ^= num;\n            } else {\n                num2 ^= num;\n            }\n        }\n        return new int[]{num1, num2};\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction findTwoSingleNumbers(nums) {\n    // Your code here\n}',
  E'function findTwoSingleNumbers(nums) {\n    // Step 1: XOR all numbers to get a ^ b\n    let xorAll = 0;\n    for (const num of nums) {\n        xorAll ^= num;\n    }\n\n    // Step 2: Find a distinguishing bit (rightmost set bit)\n    // xorAll & (-xorAll) isolates the rightmost set bit.\n    let diffBit = xorAll & (-xorAll);\n\n    // Step 3: Partition and XOR each group\n    let num1 = 0;\n    let num2 = 0;\n    for (const num of nums) {\n        if ((num & diffBit) !== 0) { // Check if the distinguishing bit is set in \'num\'\n            num1 ^= num;\n        } else {\n            num2 ^= num;\n        }\n    }\n    return [num1, num2];\n}',
  ARRAY['bitwise-xor'],
  ARRAY['google-l4', 'amazon-sde2', 'nvidia-swe'],
  'bitwise-xor',
  '[{"input":"find_two_single_numbers([1, 4, 2, 1, 3, 5, 6, 2, 3, 5])","expected_output":"[4, 6] (order may vary)"},{"input":"find_two_single_numbers([2, 1, 3, 2])","expected_output":"[1, 3] (order may vary)"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
