INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-bitwise-xor-complement',
  'Complement of Base 10 Number',
  'hard',
  'Complement of Base 10 Number

Problem Statement

Given a positive integer `n`, find its **bitwise complement**. The complement flips all bits in the binary representation of the number (only considering the significant bits, not leading zeros).

Examples

**Example 1:**

**Example 2:**

**Example 3:**',
  '',
  '[{"input":"8 (binary: 1000)","output":"7 (binary: 0111)"},{"input":"10 (binary: 1010)","output":"5 (binary: 0101)"},{"input":"1 (binary: 1)","output":"0 (binary: 0)"}]'::jsonb,
  'bitwise_complement',
  E'def bitwise_complement(n):\n    # TODO: Return the complement of n (flip all significant bits)\n    pass\n\n# Expected: 7\n# Expected: 5\n# Expected: 0',
  E'def bitwise_complement(n):\n    if n == 0:\n        return 1\n\n    # Count number of bits\n    bit_count = 0\n    temp = n\n    while temp > 0:\n        bit_count += 1\n        temp >>= 1\n    # Create mask of all 1s with same bit length\n    mask = (1 << bit_count) - 1\n    return n ^ mask\n# Expected: 7\n# Expected: 5\n# Expected: 0',
  E'class Solution {\n    public Object bitwiseComplement(int n) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int bitwiseComplement(int n) {\n        if (n == 0) {\n            return 1;\n        }\n\n        // Count number of bits\n        int bitCount = 0;\n        int temp = n;\n        while (temp > 0) {\n            bitCount++;\n            temp >>= 1;\n        }\n        // Create mask of all 1s with same bit length\n        // (1 << bitCount) creates a number with a 1 at the (bitCount)-th position (0-indexed)\n        // and 0s elsewhere. Subtracting 1 makes it a sequence of \'bitCount\' ones.\n        // Example: bitCount = 3, (1 << 3) = 8 (1000_2). (1 << 3) - 1 = 7 (0111_2).\n        int mask = (1 << bitCount) - 1;\n        return n ^ mask;\n    }\n}',
  E'/**\n * @param {any} n\n * @return {any}\n */\nfunction bitwiseComplement(n) {\n    // Your code here\n}',
  E'function bitwiseComplement(n) {\n    if (n === 0) {\n        return 1;\n    }\n\n    // Count number of bits\n    let bitCount = 0;\n    let temp = n;\n    while (temp > 0) {\n        bitCount++;\n        temp >>= 1;\n    }\n    // Create mask of all 1s with same bit length\n    let mask = (1 << bitCount) - 1;\n    return n ^ mask;\n}',
  ARRAY['bitwise-xor'],
  ARRAY['google-l4', 'amazon-sde2', 'nvidia-swe'],
  'bitwise-xor',
  '[{"input":"bitwise_complement(8)","expected_output":"7"},{"input":"bitwise_complement(10)","expected_output":"5"},{"input":"bitwise_complement(1)","expected_output":"0"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
