INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-bitwise-xor-flip-invert',
  'Flip and Invert an Image',
  'hard',
  'Flip and Invert an Image

Problem Statement

Given a binary matrix (2D list of 0s and 1s), first flip it **horizontally** (reverse each row), then **invert** it (flip 0 to 1 and 1 to 0). Return the resulting matrix.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[{"input":"[[1,1,0],[1,0,1],[0,0,0]]","output":"[[1,0,0],[0,1,0],[1,1,1]]"},{"input":"[[1,0],[0,1]]","output":"[[1,0],[0,1]]"}]'::jsonb,
  'flip_and_invert_image',
  E'def flip_and_invert_image(matrix):\n    # TODO: Flip horizontally and invert the binary matrix\n    pass\n\n# Expected: [[1,0,0],[0,1,0],[1,1,1]]\n# Expected: [[1,0],[0,1]]',
  E'def flip_and_invert_image(matrix):\n    for row in matrix:\n        n = len(row)\n        for i in range((n + 1) // 2):\n            # Swap and invert simultaneously\n            row[i], row[n - 1 - i] = row[n - 1 - i] ^ 1, row[i] ^ 1\n\n    return matrix\n# Expected: [[1,0,0],[0,1,0],[1,1,1]]\n# Expected: [[1,0],[0,1]]',
  E'class Solution {\n    public Object flipAndInvertImage(int[][] matrix) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int[][] flipAndInvertImage(int[][] matrix) {\n        for (int[] row : matrix) {\n            int n = row.length;\n            for (int i = 0; i < (n + 1) / 2; i++) {\n                // Swap and invert simultaneously\n                // Python\'s tuple assignment `a, b = b^1, a^1` means:\n                // 1. Evaluate b^1 and a^1\n                // 2. Assign results to a and b\n                // In Java, we need a temporary variable for the swap.\n                // temp_i = row[i]\n                // temp_j = row[n - 1 - i]\n                // row[i] = temp_j ^ 1\n                // row[n - 1 - i] = temp_i ^ 1\n                int temp = row[i];\n                row[i] = row[n - 1 - i] ^ 1;\n                row[n - 1 - i] = temp ^ 1;\n            }\n        }\n        return matrix;\n    }\n}',
  E'/**\n * @param {any} matrix\n * @return {any}\n */\nfunction flipAndInvertImage(matrix) {\n    // Your code here\n}',
  E'function flipAndInvertImage(matrix) {\n    for (let row of matrix) {\n        const n = row.length;\n        for (let i = 0; i < Math.floor((n + 1) / 2); i++) {\n            // Swap and invert simultaneously\n            // JavaScript\'s destructuring assignment allows direct translation\n            [row[i], row[n - 1 - i]] = [row[n - 1 - i] ^ 1, row[i] ^ 1];\n        }\n    }\n    return matrix;\n}',
  ARRAY['bitwise-xor'],
  ARRAY['google-l4', 'amazon-sde2', 'nvidia-swe'],
  'bitwise-xor',
  '[{"input":"flip_and_invert_image([[1,1,0],[1,0,1],[0,0,0]])","expected_output":"[[1,0,0],[0,1,0],[1,1,1]]"},{"input":"flip_and_invert_image([[1,0],[0,1]])","expected_output":"[[1,0],[0,1]]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
