INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-top-k-numbers',
  'Top K Numbers',
  'hard',
  'Top K Numbers

Problem Statement

Given an unsorted array of numbers, find the **K largest numbers** in it. Return them in any order.

Examples

**Example 1:**

**Example 2:**

**Example 3:**',
  '',
  '[{"input":"nums = [3, 1, 5, 12, 2, 11], k = 3","output":"[5, 12, 11]"},{"input":"nums = [5, 12, 11, -1, 12], k = 3","output":"[12, 11, 12]"},{"input":"nums = [1, 2, 3], k = 2","output":"[2, 3]"}]'::jsonb,
  'find_k_largest',
  E'import heapq\ndef find_k_largest(nums, k):\n    # TODO: Return the k largest numbers\n    pass\n\n# Expected: [5, 12, 11]\n# Expected: [12, 11, 12]\n# Expected: [2, 3]',
  E'import heapq\ndef find_k_largest(nums, k):\n    min_heap = []\n\n    for num in nums:\n        heapq.heappush(min_heap, num)\n        if len(min_heap) > k:\n            heapq.heappop(min_heap)\n    return list(min_heap)\n# Expected: [5, 12, 11]\n# Expected: [12, 11, 12]\n# Expected: [2, 3]',
  E'class Solution {\n    public Object findKLargest(int[] nums, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.List;\n    // import java.util.PriorityQueue;\n    // import java.util.Collections; // Not strictly needed for min-heap, but good to know for max-heap\n\n    public static List<Integer> findKLargest(int[] nums, int k) {\n        // A PriorityQueue in Java is a min-heap by default.\n        PriorityQueue<Integer> minHeap = new PriorityQueue<>();\n\n        for (int num : nums) {\n            minHeap.add(num); // Add to heap\n            if (minHeap.size() > k) {\n                minHeap.poll(); // Remove smallest element if heap size exceeds k\n            }\n        }\n        \n        // Convert the heap to a List. The order in the list might not be sorted,\n        // but it contains the k largest elements.\n        return new ArrayList<>(minHeap);\n    }\n}',
  E'/**\n * @param {any, any} nums, k\n * @return {any}\n */\nfunction findKLargest(nums, k) {\n    // Your code here\n}',
  E'// Helper MinHeap class for JavaScript\nclass MinHeap {\n    constructor(comparator = (a, b) => a < b) { // Default to min-heap for numbers\n        this.heap = [];\n        this.comparator = comparator; // (a, b) => true if a should come before b\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    peek() {\n        return this.heap[0];\n    }\n\n    push(item) {\n        this.heap.push(item);\n        this._bubbleUp();\n    }\n\n    pop() {\n        if (this.size() === 0) return undefined;\n        if (this.size() === 1) return this.heap.pop();\n\n        const root = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this._bubbleDown();\n        return root;\n    }\n\n    _bubbleUp() {\n        let index = this.heap.length - 1;\n        while (index > 0) {\n            const parentIndex = Math.floor((index - 1) / 2);\n            if (this.comparator(this.heap[index], this.heap[parentIndex])) {\n                [this.heap[index], this.heap[parentIndex]] = [this.heap[parentIndex], this.heap[index]];\n                index = parentIndex;\n            } else {\n                break;\n            }\n        }\n    }\n\n    _bubbleDown() {\n        let index = 0;\n        const lastIndex = this.heap.length - 1;\n        while (true) {\n            let leftChildIndex = 2 * index + 1;\n            let rightChildIndex = 2 * index + 2;\n            let smallestIndex = index;\n\n            if (leftChildIndex <= lastIndex && this.comparator(this.heap[leftChildIndex], this.heap[smallestIndex])) {\n                smallestIndex = leftChildIndex;\n            }\n\n            if (rightChildIndex <= lastIndex && this.comparator(this.heap[rightChildIndex], this.heap[smallestIndex])) {\n                smallestIndex = rightChildIndex;\n            }\n\n            if (smallestIndex !== index) {\n                [this.heap[index], this.heap[smallestIndex]] = [this.heap[smallestIndex], this.heap[index]];\n                index = smallestIndex;\n            } else {\n                break;\n            }\n        }\n    }\n}\n\nfunction findKLargest(nums, k) {\n    const minHeap = new MinHeap(); // Default comparator makes it a min-heap\n\n    for (const num of nums) {\n        minHeap.push(num);\n        if (minHeap.size() > k) {\n            minHeap.pop();\n        }\n    }\n    return minHeap.heap; // The internal array of the heap contains the elements\n}',
  ARRAY['top-k-elements'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'netflix-senior', 'uber-sde2'],
  'top-k-elements',
  '[{"input":"find_k_largest([3, 1, 5, 12, 2, 11], 3)","expected_output":"[5, 12, 11]"},{"input":"find_k_largest([5, 12, 11, -1, 12], 3)","expected_output":"[12, 11, 12]"},{"input":"find_k_largest([1, 2, 3], 2)","expected_output":"[2, 3]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
