INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-top-k-kth-smallest',
  'Kth Smallest Number',
  'hard',
  'Kth Smallest Number

Problem Statement

Given an unsorted array and a number K, find the **Kth smallest** element in the array.

Examples

**Example 1:**

**Example 2:**

**Example 3:**',
  '',
  '[{"input":"nums = [1, 5, 12, 2, 11, 5], k = 3","output":"5","explanation":"Sorted: [1, 2, 5, 5, 11, 12], 3rd smallest = 5"},{"input":"nums = [7, 10, 4, 3, 20, 15], k = 4","output":"10","explanation":"Sorted: [3, 4, 7, 10, 15, 20], 4th smallest = 10"},{"input":"nums = [1, 2, 3], k = 1","output":"1"}]'::jsonb,
  'find_kth_smallest',
  E'import heapq\ndef find_kth_smallest(nums, k):\n    # TODO: Return the kth smallest element\n    pass\n\n# Expected: 5\n# Expected: 10\n# Expected: 1',
  E'import heapq\ndef find_kth_smallest(nums, k):\n    max_heap = []\n\n    for num in nums:\n        heapq.heappush(max_heap, -num)\n        if len(max_heap) > k:\n            heapq.heappop(max_heap)\n    return -max_heap[0]\n# Expected: 5\n# Expected: 10\n# Expected: 1',
  E'class Solution {\n    public Object findKthSmallest(int[] nums, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.Collections;\n    // import java.util.PriorityQueue;\n\n    public static int findKthSmallest(int[] nums, int k) {\n        // A PriorityQueue can be made a max-heap by providing a custom comparator\n        // or by using Collections.reverseOrder().\n        // Python\'s solution uses a min-heap of negative numbers to simulate a max-heap.\n        // We\'ll follow that logic for direct translation.\n        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(); // This is a min-heap by default\n        // To make it a max-heap, we can use:\n        // PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());\n        // Or, as in Python, store negative values and use default min-heap behavior.\n\n        for (int num : nums) {\n            maxHeap.add(-num); // Add negative to simulate max-heap behavior for positive numbers\n            if (maxHeap.size() > k) {\n                maxHeap.poll(); // Remove the smallest negative (which corresponds to the largest positive)\n            }\n        }\n        // The top of the heap is the smallest negative number,\n        // which corresponds to the largest positive number among the k elements.\n        // Negate it to get the actual kth smallest positive number.\n        return -maxHeap.peek();\n    }\n}',
  E'/**\n * @param {any, any} nums, k\n * @return {any}\n */\nfunction findKthSmallest(nums, k) {\n    // Your code here\n}',
  E'// Helper MinHeap class for JavaScript (same as Problem 5)\nclass MinHeap {\n    constructor(comparator = (a, b) => a < b) {\n        this.heap = [];\n        this.comparator = comparator;\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    peek() {\n        return this.heap[0];\n    }\n\n    push(item) {\n        this.heap.push(item);\n        this._bubbleUp();\n    }\n\n    pop() {\n        if (this.size() === 0) return undefined;\n        if (this.size() === 1) return this.heap.pop();\n\n        const root = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this._bubbleDown();\n        return root;\n    }\n\n    _bubbleUp() {\n        let index = this.heap.length - 1;\n        while (index > 0) {\n            const parentIndex = Math.floor((index - 1) / 2);\n            if (this.comparator(this.heap[index], this.heap[parentIndex])) {\n                [this.heap[index], this.heap[parentIndex]] = [this.heap[parentIndex], this.heap[index]];\n                index = parentIndex;\n            } else {\n                break;\n            }\n        }\n    }\n\n    _bubbleDown() {\n        let index = 0;\n        const lastIndex = this.heap.length - 1;\n        while (true) {\n            let leftChildIndex = 2 * index + 1;\n            let rightChildIndex = 2 * index + 2;\n            let smallestIndex = index;\n\n            if (leftChildIndex <= lastIndex && this.comparator(this.heap[leftChildIndex], this.heap[smallestIndex])) {\n                smallestIndex = leftChildIndex;\n            }\n\n            if (rightChildIndex <= lastIndex && this.comparator(this.heap[rightChildIndex], this.heap[smallestIndex])) {\n                smallestIndex = rightChildIndex;\n            }\n\n            if (smallestIndex !== index) {\n                [this.heap[index], this.heap[smallestIndex]] = [this.heap[smallestIndex], this.heap[index]];\n                index = smallestIndex;\n            } else {\n                break;\n            }\n        }\n    }\n}\n\nfunction findKthSmallest(nums, k) {\n    // Use a min-heap to store negative numbers to simulate a max-heap for positive numbers.\n    const maxHeap = new MinHeap(); // Default comparator works for negative numbers\n\n    for (const num of nums) {\n        maxHeap.push(-num); // Push negative of the number\n        if (maxHeap.size() > k) {\n            maxHeap.pop();\n        }\n    }\n    // The smallest negative number in the heap corresponds to the largest positive number\n    // among the k elements. Negate it to get the actual kth smallest positive number.\n    return -maxHeap.peek();\n}',
  ARRAY['top-k-elements'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'netflix-senior', 'uber-sde2'],
  'top-k-elements',
  '[{"input":"find_kth_smallest([1, 5, 12, 2, 11, 5], 3)","expected_output":"5"},{"input":"find_kth_smallest([7, 10, 4, 3, 20, 15], 4)","expected_output":"10"},{"input":"find_kth_smallest([1, 2, 3], 1)","expected_output":"1"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
