  E'import heapq\ndef k_closest_points(points, k):\n    # TODO: Return the k closest points to the origin\n    pass\n\n# Expected: [[1, 2]]\n# Expected: [[3, 3], [-2, 4]] (order may vary)',
  E'import heapq\ndef k_closest_points(points, k):\n    max_heap = []\n\n    for point in points:\n        dist = point[0] ** 2 + point[1] ** 2\n        heapq.heappush(max_heap, (-dist, point))\n        if len(max_heap) > k:\n            heapq.heappop(max_heap)\n    return [item[1] for item in max_heap]\n# Expected: [[1, 2]]\n# Expected: [[3, 3], [-2, 4]] (order may vary)',
  E'class Solution {\n    public Object kClosestPoints(Object points, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.List;\n    // import java.util.PriorityQueue;\n    // import java.util.Comparator;\n\n    // Helper class to store point and its distance for the PriorityQueue\n    static class PointWithDistance {\n        int[] point;\n        int dist;\n\n        PointWithDistance(int[] p) {\n            this.point = p;\n            this.dist = p[0] * p[0] + p[1] * p[1];\n        }\n    }\n\n    public static List<int[]> kClosestPoints(int[][] points, int k) {\n        // Create a max-heap based on distance.\n        // The comparator (a, b) -> b.dist - a.dist makes it a max-heap.\n        PriorityQueue<PointWithDistance> maxHeap = new PriorityQueue<>(\n            (a, b) -> Integer.compare(b.dist, a.dist)\n        );\n\n        for (int[] point : points) {\n            maxHeap.add(new PointWithDistance(point));\n            if (maxHeap.size() > k) {\n                maxHeap.poll();\n            }\n        }\n\n        // Extract points from the heap\n        List<int[]> result = new ArrayList<>();\n        while (!maxHeap.isEmpty()) {\n            result.add(maxHeap.poll().point);\n        }\n        // The order might be reversed from how Python returns it, but problem states "order may vary".\n        // If exact order (e.g., smallest distance first) is needed, sort result or extract in reverse.\n        // Python\'s list comprehension `[item[1] for item in max_heap]` extracts in arbitrary order.\n        return result;\n    }\n}',
  E'/**\n * @param {any, any} points, k\n * @return {any}\n */\nfunction kClosestPoints(points, k) {\n    // Your code here\n}',
  E'// Helper MinHeap class for JavaScript (same as Problem 5)\nclass MinHeap {\n    constructor(comparator = (a, b) => a < b) {\n        this.heap = [];\n        this.comparator = comparator;\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    peek() {\n        return this.heap[0];\n    }\n\n    push(item) {\n        this.heap.push(item);\n        this._bubbleUp();\n    }\n\n    pop() {\n        if (this.size() === 0) return undefined;\n        if (this.size() === 1) return this.heap.pop();\n\n        const root = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this._bubbleDown();\n        return root;\n    }\n\n    _bubbleUp() {\n        let index = this.heap.length - 1;\n        while (index > 0) {\n            const parentIndex = Math.floor((index - 1) / 2);\n            if (this.comparator(this.heap[index], this.heap[parentIndex])) {\n                [this.heap[index], this.heap[parentIndex]] = [this.heap[parentIndex], this.heap[index]];\n                index = parentIndex;\n            } else {\n                break;\n            }\n        }\n    }\n\n    _bubbleDown() {\n        let index = 0;\n        const lastIndex = this.heap.length - 1;\n        while (true) {\n            let leftChildIndex = 2 * index + 1;\n            let rightChildIndex = 2 * index + 2;\n            let smallestIndex = index;\n\n            if (leftChildIndex <= lastIndex && this.comparator(this.heap[leftChildIndex], this.heap[smallestIndex])) {\n                smallestIndex = leftChildIndex;\n            }\n\n            if (rightChildIndex <= lastIndex && this.comparator(this.heap[rightChildIndex], this.heap[smallestIndex])) {\n                smallestIndex = rightChildIndex;\n            }\n\n            if (smallestIndex !== index) {\n                [this.heap[index], this.heap[smallestIndex]] = [this.heap[',
  ARRAY['top-k-elements'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'netflix-senior', 'uber-sde2'],
  'top-k-elements',
  '[{"input":"k_closest_points([[1,2],[1,3]], 1)","expected_output":"[[1, 2]]"},{"input":"k_closest_points([[3,3],[5,-1],[-2,4]], 2)","expected_output":"[[3, 3], [-2, 4]] (order may vary)"}]'::jsonb,
  '[]'::jsonb
