INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-top-k-frequent-numbers',
  'Top K Frequent Numbers',
  'hard',
  'Top K Frequent Numbers

Problem Statement

Given an unsorted array of numbers, find the **K most frequently occurring** numbers. If two numbers have the same frequency, either can be chosen.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[{"input":"nums = [1, 3, 5, 12, 11, 12, 11], k = 2","output":"[12, 11]","explanation":"12 appears 2x, 11 appears 2x, rest appear 1x."},{"input":"nums = [5, 12, 11, 3, 11], k = 2","output":"[11, 5] or [11, 12] or [11, 3]","explanation":"11 appears 2x (must be included), rest appear 1x (pick any)."}]'::jsonb,
  'find_k_frequent',
  E'import heapq\nfrom collections import Counter\ndef find_k_frequent(nums, k):\n    # TODO: Return the k most frequently occurring numbers\n    pass\n\n# Expected: [12, 11] (order may vary)\n# Expected: [11, <any other>] (11 must be included)',
  E'import heapq\nfrom collections import Counter\ndef find_k_frequent(nums, k):\n    freq = Counter(nums)\n    min_heap = []\n\n    for num, count in freq.items():\n        heapq.heappush(min_heap, (count, num))\n        if len(min_heap) > k:\n            heapq.heappop(min_heap)\n    return [item[1] for item in min_heap]\n# Expected: [12, 11] (order may vary)\n# Expected: [11, <any other>] (11 must be included)',
  E'class Solution {\n    public Object findKFrequent(int[] nums, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.PriorityQueue;\n\nclass Solution {\n    public static List<Integer> findKFrequent(int[] nums, int k) {\n        Map<Integer, Integer> freq = new HashMap<>();\n        for (int num : nums) {\n            freq.put(num, freq.getOrDefault(num, 0) + 1);\n        }\n\n        // Min-heap to store pairs of (count, num)\n        // The comparator ensures that elements are ordered by count (first element of the array)\n        PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> a[0] - b[0]);\n\n        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {\n            int num = entry.getKey();\n            int count = entry.getValue();\n            minHeap.offer(new int[]{count, num}); // Push (count, num)\n\n            if (minHeap.size() > k) {\n                minHeap.poll(); // Remove the element with the smallest count\n            }\n        }\n\n        List<Integer> result = new ArrayList<>();\n        while (!minHeap.isEmpty()) {\n            result.add(minHeap.poll()[1]); // Extract the number (second element)\n        }\n        return result;\n    }\n}',
  E'/**\n * @param {any, any} nums, k\n * @return {any}\n */\nfunction findKFrequent(nums, k) {\n    // Your code here\n}',
  E'class MinHeap {\n    constructor(comparator = (a, b) => a[0] - b[0]) {\n        this.heap = [];\n        this.comparator = comparator;\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    peek() {\n        return this.heap[0];\n    }\n\n    push(item) {\n        this.heap.push(item);\n        this._bubbleUp();\n    }\n\n    pop() {\n        if (this.size() === 0) return undefined;\n        if (this.size() === 1) return this.heap.pop();\n\n        const item = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this._bubbleDown();\n        return item;\n    }\n\n    _bubbleUp() {\n        let index = this.heap.length - 1;\n        while (index > 0) {\n            const parentIndex = Math.floor((index - 1) / 2);\n            if (this.comparator(this.heap[index], this.heap[parentIndex]) < 0) {\n                [this.heap[index], this.heap[parentIndex]] = [this.heap[parentIndex], this.heap[index]];\n                index = parentIndex;\n            } else {\n                break;\n            }\n        }\n    }\n\n    _bubbleDown() {\n        let index = 0;\n        const lastIndex = this.heap.length - 1;\n        while (true) {\n            let leftChildIndex = 2 * index + 1;\n            let rightChildIndex = 2 * index + 2;\n            let smallestIndex = index;\n\n            if (leftChildIndex <= lastIndex && this.comparator(this.heap[leftChildIndex], this.heap[smallestIndex]) < 0) {\n                smallestIndex = leftChildIndex;\n            }\n\n            if (rightChildIndex <= lastIndex && this.comparator(this.heap[rightChildIndex], this.heap[smallestIndex]) < 0) {\n                smallestIndex = rightChildIndex;\n            }\n\n            if (smallestIndex !== index) {\n                [this.heap[index], this.heap[smallestIndex]] = [this.heap[smallestIndex], this.heap[index]];\n                index = smallestIndex;\n            } else {\n                break;\n            }\n        }\n    }\n}\n\nfunction findKFrequent(nums, k) {\n    const freq = new Map();\n    for (const num of nums) {\n        freq.set(num, (freq.get(num) || 0) + 1);\n    }\n\n    // Min-heap to store pairs of [count, num]\n    const minHeap = new MinHeap();\n\n    for (const [num, count] of freq.entries()) {\n        minHeap.push([count, num]); // Push [count, num]\n        if (minHeap.size() > k) {\n            minHeap.pop(); // Remove the element with the smallest count\n        }\n    }\n\n    const result = [];\n    while (minHeap.size() > 0) {\n        result.push(minHeap.pop()[1]); // Extract the number (second element)\n    }\n    return result;\n}',
  ARRAY['top-k-elements'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'netflix-senior', 'uber-sde2'],
  'top-k-elements',
  '[{"input":"find_k_frequent([1, 3, 5, 12, 11, 12, 11], 2)","expected_output":"[12, 11] (order may vary)"},{"input":"find_k_frequent([5, 12, 11, 3, 11], 2)","expected_output":"[11, <any other>] (11 must be included)"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
