INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-k-way-merge-sorted-lists',
  'Merge K Sorted Lists',
  'hard',
  'Merge K Sorted Lists

Problem Statement

Given K sorted arrays, merge them into a **single sorted array**.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[{"input":"[[2, 6, 8], [3, 6, 7], [1, 3, 4]]","output":"[1, 2, 3, 3, 4, 6, 6, 7, 8]"},{"input":"[[5, 8, 9], [1, 7]]","output":"[1, 5, 7, 8, 9]"}]'::jsonb,
  'merge_k_sorted_lists',
  E'import heapq\ndef merge_k_sorted_lists(lists):\n    # TODO: Merge K sorted arrays into one sorted array\n    result = []\n    return result\n\n# Expected: [1, 2, 3, 3, 4, 6, 6, 7, 8]\n# Expected: [1, 5, 7, 8, 9]',
  E'import heapq\ndef merge_k_sorted_lists(lists):\n    min_heap = []\n    for i, lst in enumerate(lists):\n        if lst:\n            heapq.heappush(min_heap, (lst[0], i, 0))\n\n    result = []\n    while min_heap:\n        val, list_idx, elem_idx = heapq.heappop(min_heap)\n        result.append(val)\n        if elem_idx + 1 < len(lists[list_idx]):\n            next_val = lists[list_idx][elem_idx + 1]\n            heapq.heappush(min_heap, (next_val, list_idx, elem_idx + 1))\n    return result\n# Expected: [1, 2, 3, 3, 4, 6, 6, 7, 8]\n# Expected: [1, 5, 7, 8, 9]',
  E'class Solution {\n    public Object mergeKSortedLists(List<Integer> lists) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayList;\nimport java.util.List;\nimport java.util.PriorityQueue;\n\nclass Solution {\n    public static List<Integer> mergeKSortedLists(List<List<Integer>> lists) {\n        // Min-heap to store elements: [value, list_idx, elem_idx]\n        // The comparator ensures elements are ordered by value (first element of the array)\n        PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> a[0] - b[0]);\n\n        for (int i = 0; i < lists.size(); i++) {\n            List<Integer> lst = lists.get(i);\n            if (!lst.isEmpty()) {\n                // Push (first_val, list_index, element_index)\n                minHeap.offer(new int[]{lst.get(0), i, 0});\n            }\n        }\n\n        List<Integer> result = new ArrayList<>();\n        while (!minHeap.isEmpty()) {\n            int[] entry = minHeap.poll();\n            int val = entry[0];\n            int listIdx = entry[1];\n            int elemIdx = entry[2];\n\n            result.add(val);\n\n            // If there are more elements in the current list, add the next one to the heap\n            if (elemIdx + 1 < lists.get(listIdx).size()) {\n                int nextVal = lists.get(listIdx).get(elemIdx + 1);\n                minHeap.offer(new int[]{nextVal, listIdx, elemIdx + 1});\n            }\n        }\n        return result;\n    }\n}',
  E'/**\n * @param {any} lists\n * @return {any}\n */\nfunction mergeKSortedLists(lists) {\n    // Your code here\n}',
  E'class MinHeap {\n    constructor(comparator = (a, b) => a[0] - b[0]) {\n        this.heap = [];\n        this.comparator = comparator;\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    peek() {\n        return this.heap[0];\n    }\n\n    push(item) {\n        this.heap.push(item);\n        this._bubbleUp();\n    }\n\n    pop() {\n        if (this.size() === 0) return undefined;\n        if (this.size() === 1) return this.heap.pop();\n\n        const item = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this._bubbleDown();\n        return item;\n    }\n\n    _bubbleUp() {\n        let index = this.heap.length - 1;\n        while (index > 0) {\n            const parentIndex = Math.floor((index - 1) / 2);\n            if (this.comparator(this.heap[index], this.heap[parentIndex]) < 0) {\n                [this.heap[index], this.heap[parentIndex]] = [this.heap[parentIndex], this.heap[index]];\n                index = parentIndex;\n            } else {\n                break;\n            }\n        }\n    }\n\n    _bubbleDown() {\n        let index = 0;\n        const lastIndex = this.heap.length - 1;\n        while (true) {\n            let leftChildIndex = 2 * index + 1;\n            let rightChildIndex = 2 * index + 2;\n            let smallestIndex = index;\n\n            if (leftChildIndex <= lastIndex && this.comparator(this.heap[leftChildIndex], this.heap[smallestIndex]) < 0) {\n                smallestIndex = leftChildIndex;\n            }\n\n            if (rightChildIndex <= lastIndex && this.comparator(this.heap[rightChildIndex], this.heap[smallestIndex]) < 0) {\n                smallestIndex = rightChildIndex;\n            }\n\n            if (smallestIndex !== index) {\n                [this.heap[index], this.heap[smallestIndex]] = [this.heap[smallestIndex], this.heap[index]];\n                index = smallestIndex;\n            } else {\n                break;\n            }\n        }\n    }\n}\n\nfunction mergeKSortedLists(lists) {\n    // Min-heap to store elements: [value, list_idx, elem_idx]\n    const minHeap = new MinHeap();\n\n    lists.forEach((lst, i) => {\n        if (lst.length > 0) {\n            // Push (first_val, list_index, element_index)\n            minHeap.push([lst[0], i, 0]);\n        }\n    });\n\n    const result = [];\n    while (minHeap.size() > 0) {\n        const [val, listIdx, elemIdx] = minHeap.pop();\n        result.push(val);\n\n        // If there are more elements in the current list, add the next one to the heap\n        if (elemIdx + 1 < lists[listIdx].length) {\n            const nextVal = lists[listIdx][elemIdx + 1];\n            minHeap.push([nextVal, listIdx, elemIdx + 1]);\n        }\n    }\n    return result;\n}',
  ARRAY['k-way-merge'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'databricks-swe'],
  'k-way-merge',
  '[{"input":"merge_k_sorted_lists([[2, 6, 8], [3, 6, 7], [1, 3, 4]])","expected_output":"[1, 2, 3, 3, 4, 6, 6, 7, 8]"},{"input":"merge_k_sorted_lists([[5, 8, 9], [1, 7]])","expected_output":"[1, 5, 7, 8, 9]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
