INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-k-way-merge-sorted-matrix',
  'Kth Smallest Number in a Sorted Matrix',
  'hard',
  'Kth Smallest Number in a Sorted Matrix

Problem Statement

Given an N x N matrix where each **row** and each **column** is sorted in ascending order, find the **Kth smallest** element.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[{"input":"matrix = [[1,5,9],[10,11,13],[12,13,15]], k = 8","output":"13","explanation":"Sorted elements: [1,5,9,10,11,12,13,13,15], 8th = 13."},{"input":"matrix = [[1,3],[2,4]], k = 3","output":"3","explanation":"Sorted: [1,2,3,4], 3rd = 3."}]'::jsonb,
  'kth_smallest_in_matrix',
  E'import heapq\ndef kth_smallest_in_matrix(matrix, k):\n    # TODO: Find the kth smallest element in the sorted matrix\n    pass\n\n# Expected: 13\n# Expected: 3',
  E'import heapq\ndef kth_smallest_in_matrix(matrix, k):\n    n = len(matrix)\n    min_heap = []\n\n    # Push the first element of each row\n    for i in range(min(n, k)):\n        heapq.heappush(min_heap, (matrix[i][0], i, 0))\n    count = 0\n    while min_heap:\n        val, row, col = heapq.heappop(min_heap)\n        count += 1\n        if count == k:\n            return val\n        if col + 1 < len(matrix[row]):\n            heapq.heappush(min_heap, (matrix[row][col + 1], row, col + 1))\n    return -1\n# Expected: 13\n# Expected: 3',
  E'class Solution {\n    public Object kthSmallestInMatrix(int[][] matrix, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.List;\nimport java.util.PriorityQueue;\nimport java.util.ArrayList;\n\nclass Solution {\n\n    static class Element implements Comparable<Element> {\n        int val;\n        int row;\n        int col;\n\n        public Element(int val, int row, int col) {\n            this.val = val;\n            this.row = row;\n            this.col = col;\n        }\n\n        @Override\n        public int compareTo(Element other) {\n            return Integer.compare(this.val, other.val);\n        }\n    }\n\n    public static int kthSmallestInMatrix(int[][] matrix, int k) {\n        int n = matrix.length;\n        PriorityQueue<Element> minHeap = new PriorityQueue<>();\n\n        // Push the first element of each row\n        for (int i = 0; i < Math.min(n, k); i++) {\n            if (matrix[i].length > 0) { // Ensure row is not empty\n                minHeap.offer(new Element(matrix[i][0], i, 0));\n            }\n        }\n\n        int count = 0;\n        while (!minHeap.isEmpty()) {\n            Element current = minHeap.poll();\n            count++;\n            if (count == k) {\n                return current.val;\n            }\n            if (current.col + 1 < matrix[current.row].length) {\n                minHeap.offer(new Element(matrix[current.row][current.col + 1], current.row, current.col + 1));\n            }\n        }\n        return -1;\n    }\n}',
  E'/**\n * @param {any, any} matrix, k\n * @return {any}\n */\nfunction kthSmallestInMatrix(matrix, k) {\n    // Your code here\n}',
  E'class MinHeap {\n    constructor() {\n        this.heap = [];\n    }\n\n    getParentIndex(i) { return Math.floor((i - 1) / 2); }\n    getLeftChildIndex(i) { return 2 * i + 1; }\n    getRightChildIndex(i) { return 2 * i + 2; }\n\n    hasParent(i) { return this.getParentIndex(i) >= 0; }\n    hasLeftChild(i) { return this.getLeftChildIndex(i) < this.heap.length; }\n    hasRightChild(i) { return this.getRightChildIndex(i) < this.heap.length; }\n\n    getParent(i) { return this.heap[this.getParentIndex(i)]; }\n    getLeftChild(i) { return this.heap[this.getLeftChildIndex(i)]; }\n    getRightChild(i) { return this.heap[this.getRightChildIndex(i)]; }\n\n    peek() {\n        if (this.heap.length === 0) return null;\n        return this.heap[0];\n    }\n\n    insert(item) {\n        this.heap.push(item);\n        this.heapifyUp();\n    }\n\n    extractMin() {\n        if (this.heap.length === 0) return null;\n        if (this.heap.length === 1) return this.heap.pop();\n\n        const item = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this.heapifyDown();\n        return item;\n    }\n\n    heapifyUp() {\n        let index = this.heap.length - 1;\n        while (this.hasParent(index) && this.compare(this.heap[index], this.getParent(index)) < 0) {\n            this.swap(index, this.getParentIndex(index));\n            index = this.getParentIndex(index);\n        }\n    }\n\n    heapifyDown() {\n        let index = 0;\n        while (this.hasLeftChild(index)) {\n            let smallerChildIndex = this.getLeftChildIndex(index);\n            if (this.hasRightChild(index) && this.compare(this.getRightChild(index), this.getLeftChild(index)) < 0) {\n                smallerChildIndex = this.getRightChildIndex(index);\n            }\n\n            if (this.compare(this.heap[index], this.heap[smallerChildIndex]) < 0) {\n                break;\n            } else {\n                this.swap(index, smallerChildIndex);\n            }\n            index = smallerChildIndex;\n        }\n    }\n\n    swap(indexOne, indexTwo) {\n        [this.heap[indexOne], this.heap[indexTwo]] = [this.heap[indexTwo], this.heap[indexOne]];\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    // Comparison function for elements {val, row, col}\n    compare(a, b) {\n        return a.val - b.val;\n    }\n}\n\nfunction kthSmallestInMatrix(matrix, k) {\n    const n = matrix.length;\n    const minHeap = new MinHeap();\n\n    // Push the first element of each row\n    for (let i = 0; i < Math.min(n, k); i++) {\n        if (matrix[i].length > 0) { // Ensure row is not empty\n            minHeap.insert({ val: matrix[i][0], row: i, col: 0 });\n        }\n    }\n\n    let count = 0;\n    while (minHeap.size() > 0) {\n        const current = minHeap.extractMin();\n        count++;\n        if (count === k) {\n            return current.val;\n        }\n        if (current.col + 1 < matrix[current.row].length) {\n            minHeap.insert({ val: matrix[current.row][current.col + 1], row: current.row, col: current.col + 1 });\n        }\n    }\n    return -1;\n}',
  ARRAY['k-way-merge'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'databricks-swe'],
  'k-way-merge',
  '[{"input":"kth_smallest_in_matrix([[1,5,9],[10,11,13],[12,13,15]], 8)","expected_output":"13"},{"input":"kth_smallest_in_matrix([[1,3],[2,4]], 3)","expected_output":"3"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
