INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-k-way-merge-smallest-range',
  'Smallest Number Range',
  'hard',
  'Smallest Number Range

Problem Statement

Given M sorted lists, find the **smallest range** [a, b] such that at least one number from each list falls within the range. If multiple ranges have the same size, return the one with the smaller starting value.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[{"input":"[[1,5,8],[4,12],[7,8,10]]","output":"[4, 7]","explanation":"Range [4,7] includes 5 from list 1, 4 from list 2, 7 from list 3."},{"input":"[[1,9],[4,12],[7,10,16]]","output":"[4, 7]"}]'::jsonb,
  'find_smallest_range',
  E'import heapq\ndef find_smallest_range(lists):\n    # TODO: Find smallest range covering at least one element from each list\n    pass\n\n# Expected: [4, 7]\n# Expected: [4, 7]',
  E'import heapq\ndef find_smallest_range(lists):\n    min_heap = []\n    current_max = float(''-inf'')\n\n    # Initialize heap with first element of each list\n    for i, lst in enumerate(lists):\n        heapq.heappush(min_heap, (lst[0], i, 0))\n        current_max = max(current_max, lst[0])\n    best_range = [float(''-inf''), float(''inf'')]\n    while len(min_heap) == len(lists):\n        current_min, list_idx, elem_idx = heapq.heappop(min_heap)\n        # Update best range if current is smaller\n        if current_max - current_min < best_range[1] - best_range[0]:\n            best_range = [current_min, current_max]\n        # Push next element from the same list\n        if elem_idx + 1 < len(lists[list_idx]):\n            next_val = lists[list_idx][elem_idx + 1]\n            heapq.heappush(min_heap, (next_val, list_idx, elem_idx + 1))\n            current_max = max(current_max, next_val)\n        else:\n            break  # One list exhausted, can''t cover all lists\n    return best_range\n# Expected: [4, 7]\n# Expected: [4, 7]',
  E'class Solution {\n    public Object findSmallestRange(List<Integer> lists) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.List;\nimport java.util.PriorityQueue;\nimport java.util.ArrayList;\n\nclass Solution {\n\n    static class Element implements Comparable<Element> {\n        int val;\n        int listIdx;\n        int elemIdx;\n\n        public Element(int val, int listIdx, int elemIdx) {\n            this.val = val;\n            this.listIdx = listIdx;\n            this.elemIdx = elemIdx;\n        }\n\n        @Override\n        public int compareTo(Element other) {\n            return Integer.compare(this.val, other.val);\n        }\n    }\n\n    public static int[] findSmallestRange(List<List<Integer>> lists) {\n        PriorityQueue<Element> minHeap = new PriorityQueue<>();\n        int currentMax = Integer.MIN_VALUE;\n\n        // Initialize heap with first elements and find initial max\n        for (int i = 0; i < lists.size(); i++) {\n            List<Integer> lst = lists.get(i);\n            if (!lst.isEmpty()) {\n                minHeap.offer(new Element(lst.get(0), i, 0));\n                currentMax = Math.max(currentMax, lst.get(0));\n            }\n        }\n\n        int rangeStart = 0;\n        int rangeEnd = Integer.MAX_VALUE;\n\n        // Loop while heap contains one element from each list\n        while (minHeap.size() == lists.size()) {\n            Element current = minHeap.poll();\n            \n            // Check if current range is smaller than the best found so far\n            if (currentMax - current.val < rangeEnd - rangeStart) {\n                rangeStart = current.val;\n                rangeEnd = currentMax;\n            }\n\n            // If there\'s a next element in the list from which \'current\' was taken\n            if (current.elemIdx + 1 < lists.get(current.listIdx).size()) {\n                int nextVal = lists.get(current.listIdx).get(current.elemIdx + 1);\n                minHeap.offer(new Element(nextVal, current.listIdx, current.elemIdx + 1));\n                currentMax = Math.max(currentMax, nextVal); // Update currentMax\n            } else {\n                // If any list runs out of elements, we can\'t form a range covering all lists\n                break;\n            }\n        }\n        return new int[]{rangeStart, rangeEnd};\n    }\n}''-inf'')\n    // \n    //     # Initialize heap with first element of each list\n    //     for i, lst in enumerate(lists):\n    //         heapq.heappush(min_heap, (lst[0], i, 0))\n    //         current_max = max(current_max, lst[0])\n    // \n    //     best_range = [float(''-inf''), float(''inf'')]\n    // \n    //     while len(min_heap) == len(lists):\n    //         current_min, list_idx, elem_idx = heapq.heappop(min_heap)\n    // \n    //         # Update best range if current is smaller\n    //         if current_max - current_min < best_range[1] - best_range[0]:\n    //             best_range = [current_min, current_max]\n    // \n    //         # Push next element from the same list\n    //         if elem_idx + 1 < len(lists[list_idx]):\n    //             next_val = lists[list_idx][elem_idx + 1]\n    //             heapq.heappush(min_heap, (next_val, list_idx, elem_idx + 1))\n    //             current_max = max(current_max, next_val)\n    //         else:\n    //             break  # One list exhausted, can''t cover all lists\n    // \n    //     return best_range\n    // \n    // # Expected: [4, 7]\n    // \n    // # Expected: [4, 7]\n    // \n}',
  E'/**\n * @param {any} lists\n * @return {any}\n */\nfunction findSmallestRange(lists) {\n    // Your code here\n}',
  E'class MinHeap {\n    constructor() {\n        this.heap = [];\n    }\n\n    getParentIndex(i) { return Math.floor((i - 1) / 2); }\n    getLeftChildIndex(i) { return 2 * i + 1; }\n    getRightChildIndex(i) { return 2 * i + 2; }\n\n    hasParent(i) { return this.getParentIndex(i) >= 0; }\n    hasLeftChild(i) { return this.getLeftChildIndex(i) < this.heap.length; }\n    hasRightChild(i) { return this.getRightChildIndex(i) < this.heap.length; }\n\n    getParent(i) { return this.heap[this.getParentIndex(i)]; }\n    getLeftChild(i) { return this.heap[this.getLeftChildIndex(i)]; }\n    getRightChild(i) { return this.heap[this.getRightChildIndex(i)]; }\n\n    peek() {\n        if (this.heap.length === 0) return null;\n        return this.heap[0];\n    }\n\n    insert(item) {\n        this.heap.push(item);\n        this.heapifyUp();\n    }\n\n    extractMin() {\n        if (this.heap.length === 0) return null;\n        if (this.heap.length === 1) return this.heap.pop();\n\n        const item = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this.heapifyDown();\n        return item;\n    }\n\n    heapifyUp() {\n        let index = this.heap.length - 1;\n        while (this.hasParent(index) && this.compare(this.heap[index], this.getParent(index)) < 0) {\n            this.swap(index, this.getParentIndex(index));\n            index = this.getParentIndex(index);\n        }\n    }\n\n    heapifyDown() {\n        let index = 0;\n        while (this.hasLeftChild(index)) {\n            let smallerChildIndex = this.getLeftChildIndex(index);\n            if (this.hasRightChild(index) && this.compare(this.getRightChild(index), this.getLeftChild(index)) < 0) {\n                smallerChildIndex = this.getRightChildIndex(index);\n            }\n\n            if (this.compare(this.heap[index], this.heap[smallerChildIndex]) < 0) {\n                break;\n            } else {\n                this.swap(index, smallerChildIndex);\n            }\n            index = smallerChildIndex;\n        }\n    }\n\n    swap(indexOne, indexTwo) {\n        [this.heap[indexOne], this.heap[indexTwo]] = [this.heap[indexTwo], this.heap[indexOne]];\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    // Comparison function for elements {val, listIdx, elemIdx}\n    compare(a, b) {\n        return a.val - b.val;\n    }\n}\n\nfunction findSmallestRange(lists) {\n    const minHeap = new MinHeap();\n    let currentMax = Number.MIN_SAFE_INTEGER;\n\n    // Initialize heap with first elements and find initial max\n    for (let i = 0; i < lists.length; i++) {\n        const lst = lists[i];\n        if (lst.length > 0) {\n            minHeap.insert({ val: lst[0], listIdx: i, elemIdx: 0 });\n            currentMax = Math.max(currentMax, lst[0]);\n        }\n    }\n\n    let rangeStart = 0;\n    let rangeEnd = Infinity;\n\n    // Loop while heap contains one element from each list\n    while (minHeap.size() === lists.length) {\n        const current = minHeap.extractMin();\n        \n        // Check if current range is smaller than the best found so far\n        if (currentMax - current.val < rangeEnd - rangeStart) {\n            rangeStart = current.val;\n            rangeEnd = currentMax;\n        }\n\n        // If there\'s a next element in the list from which \'current\' was taken\n        if (current.elemIdx + 1 < lists[current.listIdx].length) {\n            const nextVal = lists[current.listIdx][current.elemIdx + 1];\n            minHeap.insert({ val: nextVal, listIdx: current.listIdx, elemIdx: current.elemIdx + 1 });\n            currentMax = Math.max(currentMax, nextVal); // Update currentMax\n        } else {\n            // If any list runs out of elements, we can\'t form a range covering all lists\n            break;\n        }\n    }\n    return [rangeStart, rangeEnd];\n}',
  ARRAY['k-way-merge'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'databricks-swe'],
  'k-way-merge',
  '[{"input":"find_smallest_range([[1,5,8],[4,12],[7,8,10]])","expected_output":"[4, 7]"},{"input":"find_smallest_range([[1,9],[4,12],[7,10,16]])","expected_output":"[4, 7]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
