INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-k-way-merge-k-pairs-largest-sums',
  'K Pairs with Largest Sums',
  'hard',
  'K Pairs with Largest Sums

Problem Statement

Given two sorted arrays in **descending order**, find **K pairs** (one element from each array) with the **largest sums**. Return the pairs sorted by their sum in descending order.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[{"input":"nums1 = [9, 8, 2], nums2 = [6, 3, 1], k = 3","output":"[[9,6],[8,6],[9,3]]","explanation":"Sums = 15, 14, 12. These are the 3 largest pair sums."},{"input":"nums1 = [5, 2, 1], nums2 = [2, -1], k = 3","output":"[[5,2],[5,-1],[2,2]]","explanation":"Sums = 7, 4, 4."}]'::jsonb,
  'k_pairs_largest_sums',
  E'import heapq\ndef k_pairs_largest_sums(nums1, nums2, k):\n    # TODO: Find k pairs with largest sums from two descending-sorted arrays\n    result = []\n    return result\n\n# Expected: [[9, 6], [8, 6], [9, 3]]\n# Expected: [[5, 2], [5, -1], [2, 2]]',
  E'import heapq\ndef k_pairs_largest_sums(nums1, nums2, k):\n    if not nums1 or not nums2:\n        return []\n\n    result = []\n    visited = set()\n    # Max-heap: negate the sum\n    max_heap = [(-( nums1[0] + nums2[0]), 0, 0)]\n    visited.add((0, 0))\n    while max_heap and len(result) < k:\n        neg_sum, i, j = heapq.heappop(max_heap)\n        result.append([nums1[i], nums2[j]])\n        # Push (i+1, j)\n        if i + 1 < len(nums1) and (i + 1, j) not in visited:\n            heapq.heappush(max_heap, (-(nums1[i+1] + nums2[j]), i + 1, j))\n            visited.add((i + 1, j))\n        # Push (i, j+1)\n        if j + 1 < len(nums2) and (i, j + 1) not in visited:\n            heapq.heappush(max_heap, (-(nums1[i] + nums2[j+1]), i, j + 1))\n            visited.add((i, j + 1))\n    return result\n# Expected: [[9, 6], [8, 6], [9, 3]]\n# Expected: [[5, 2], [5, -1], [2, 2]]',
  E'class Solution {\n    public Object kPairsLargestSums(Object nums1, Object nums2, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.*;\n\nclass Solution {\n    public static List<List<Integer>> kPairsLargestSums(int[] nums1, int[] nums2, int k) {\n        List<List<Integer>> result = new ArrayList<>();\n        if (nums1 == null || nums1.length == 0 || nums2 == null || nums2.length == 0 || k <= 0) {\n            return result;\n        }\n\n        // Max-heap: store [neg_sum, i, j]. We use a min-priority queue and negate sums.\n        // The comparator orders elements based on the first element (neg_sum).\n        PriorityQueue<int[]> maxHeap = new PriorityQueue<>((a, b) -> a[0] - b[0]);\n        Set<String> visited = new HashSet<>();\n\n        // Initial push: (nums1[0] + nums2[0])\n        maxHeap.offer(new int[]{-(nums1[0] + nums2[0]), 0, 0});\n        visited.add("0,0");\n\n        while (!maxHeap.isEmpty() && result.size() < k) {\n            int[] current = maxHeap.poll();\n            // int negSum = current[0]; // negSum is not directly used after polling\n            int i = current[1];\n            int j = current[2];\n\n            result.add(Arrays.asList(nums1[i], nums2[j]));\n\n            // Push (i+1, j)\n            if (i + 1 < nums1.length) {\n                String nextPair = (i + 1) + "," + j;\n                if (!visited.contains(nextPair)) {\n                    maxHeap.offer(new int[]{-(nums1[i+1] + nums2[j]), i + 1, j});\n                    visited.add(nextPair);\n                }\n            }\n\n            // Push (i, j+1)\n            if (j + 1 < nums2.length) {\n                String nextPair = i + "," + (j + 1);\n                if (!visited.contains(nextPair)) {\n                    maxHeap.offer(new int[]{-(nums1[i] + nums2[j+1]), i, j + 1});\n                    visited.add(nextPair);\n                }\n            }\n        }\n        return result;\n    }\n}',
  E'/**\n * @param {any, any, any} nums1, nums2, k\n * @return {any}\n */\nfunction kPairsLargestSums(nums1, nums2, k) {\n    // Your code here\n}',
  E'// Helper MinHeap class\nclass MinHeap {\n    constructor(comparator = (a, b) => a - b) {\n        this.heap = [];\n        this.comparator = comparator;\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    peek() {\n        return this.heap.length === 0 ? undefined : this.heap[0];\n    }\n\n    push(val) {\n        this.heap.push(val);\n        this._bubbleUp(this.heap.length - 1);\n    }\n\n    pop() {\n        if (this.heap.length === 0) return undefined;\n        if (this.heap.length === 1) return this.heap.pop();\n\n        const root = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this._bubbleDown(0);\n        return root;\n    }\n\n    _bubbleUp(index) {\n        while (index > 0) {\n            const parentIndex = Math.floor((index - 1) / 2);\n            if (this.comparator(this.heap[index], this.heap[parentIndex]) < 0) {\n                [this.heap[index], this.heap[parentIndex]] = [this.heap[parentIndex], this.heap[index]];\n                index = parentIndex;\n            } else {\n                break;\n            }\n        }\n    }\n\n    _bubbleDown(index) {\n        const lastIndex = this.heap.length - 1;\n        while (true) {\n            let leftChildIndex = 2 * index + 1;\n            let rightChildIndex = 2 * index + 2;\n            let smallestIndex = index;\n\n            if (leftChildIndex <= lastIndex && this.comparator(this.heap[leftChildIndex], this.heap[smallestIndex]) < 0) {\n                smallestIndex = leftChildIndex;\n            }\n\n            if (rightChildIndex <= lastIndex && this.comparator(this.heap[rightChildIndex], this.heap[smallestIndex]) < 0) {\n                smallestIndex = rightChildIndex;\n            }\n\n            if (smallestIndex !== index) {\n                [this.heap[index], this.heap[smallestIndex]] = [this.heap[smallestIndex], this.heap[index]];\n                index = smallestIndex;\n            } else {\n                break;\n            }\n        }\n    }\n}\n\nfunction kPairsLargestSums(nums1, nums2, k) {\n    const result = [];\n    if (!nums1 || nums1.length === 0 || !nums2 || nums2.length === 0 || k <= 0) {\n        return result;\n    }\n\n    // Max-heap: store [neg_sum, i, j]. We use a min-heap and negate sums.\n    // Comparator for [neg_sum, i, j] to sort by neg_sum\n    const maxHeap = new MinHeap((a, b) => a[0] - b[0]);\n    const visited = new Set();\n\n    // Initial push: (nums1[0] + nums2[0])\n    maxHeap.push([-(nums1[0] + nums2[0]), 0, 0]);\n    visited.add("0,0");\n\n    while (maxHeap.size() > 0 && result.length < k) {\n        const [negSum, i, j] = maxHeap.pop(); // negSum is not directly used after popping\n\n        result.push([nums1[i], nums2[j]]);\n\n        // Push (i+1, j)\n        if (i + 1 < nums1.length) {\n            const nextPair = `${i + 1},${j}`;\n            if (!visited.has(nextPair)) {\n                maxHeap.push([-(nums1[i+1] + nums2[j]), i + 1, j]);\n                visited.add(nextPair);\n            }\n        }\n\n        // Push (i, j+1)\n        if (j + 1 < nums2.length) {\n            const nextPair = `${i},${j + 1}`;\n            if (!visited.has(nextPair)) {\n                maxHeap.push([-(nums1[i] + nums2[j+1]), i, j + 1]);\n                visited.add(nextPair);\n            }\n        }\n    }\n    return result;\n}',
  ARRAY['k-way-merge'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'databricks-swe'],
  'k-way-merge',
  '[{"input":"k_pairs_largest_sums([9, 8, 2], [6, 3, 1], 3)","expected_output":"[[9, 6], [8, 6], [9, 3]]"},{"input":"k_pairs_largest_sums([5, 2, 1], [2, -1], 3)","expected_output":"[[5, 2], [5, -1], [2, 2]]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
