INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-topo-sort-basic',
  'Topological Sort',
  'hard',
  'Topological Sort

Problem Statement

Given a number of tasks labeled from 0 to `n-1` and a list of dependency pairs `[a, b]` meaning task `a` must be done before task `b`, find a valid ordering of all tasks. If multiple valid orderings exist, return any one.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[{"input":"tasks = 4, prerequisites = [[3,2],[3,0],[2,0],[2,1]]","output":"[3, 2, 0, 1] or [3, 2, 1, 0]","explanation":"Task 3 has no prerequisites. Task 2 depends on 3. Tasks 0 and 1 depend on 2."},{"input":"tasks = 3, prerequisites = [[0,1],[1,2]]","output":"[0, 1, 2]"}]'::jsonb,
  'topological_sort',
  E'from collections import deque, defaultdict\ndef topological_sort(tasks, prerequisites):\n    # TODO: Return a valid topological ordering of tasks\n    pass\n\n# Expected: [3, 2, 0, 1] or [3, 2, 1, 0]\n# Expected: [0, 1, 2]',
  E'from collections import deque, defaultdict\ndef topological_sort(tasks, prerequisites):\n    in_degree = {i: 0 for i in range(tasks)}\n    graph = defaultdict(list)\n\n    for parent, child in prerequisites:\n        graph[parent].append(child)\n        in_degree[child] += 1\n    queue = deque([node for node in in_degree if in_degree[node] == 0])\n    sorted_order = []\n    while queue:\n        node = queue.popleft()\n        sorted_order.append(node)\n        for child in graph[node]:\n            in_degree[child] -= 1\n            if in_degree[child] == 0:\n                queue.append(child)\n    if len(sorted_order) != tasks:\n        return []  # Cycle detected\n    return sorted_order\n# Expected: [3, 2, 0, 1] or [3, 2, 1, 0]\n# Expected: [0, 1, 2]',
  E'class Solution {\n    public Object topologicalSort(Object tasks, Object prerequisites) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.*;\n\nclass Solution {\n    public static List<Integer> topologicalSort(int tasks, int[][] prerequisites) {\n        List<Integer> sortedOrder = new ArrayList<>();\n        if (tasks <= 0) {\n            return sortedOrder;\n        }\n\n        // Initialize graph and in-degrees\n        Map<Integer, Integer> inDegree = new HashMap<>();\n        Map<Integer, List<Integer>> graph = new HashMap<>();\n        for (int i = 0; i < tasks; i++) {\n            inDegree.put(i, 0);\n            graph.put(i, new ArrayList<>());\n        }\n\n        // Build graph and populate in-degrees\n        for (int[] prerequisite : prerequisites) {\n            int parent = prerequisite[0];\n            int child = prerequisite[1];\n            graph.get(parent).add(child);\n            inDegree.put(child, inDegree.get(child) + 1);\n        }\n\n        // Find all sources (nodes with 0 in-degree)\n        Queue<Integer> queue = new LinkedList<>();\n        for (Map.Entry<Integer, Integer> entry : inDegree.entrySet()) {\n            if (entry.getValue() == 0) {\n                queue.offer(entry.getKey());\n            }\n        }\n\n        // Process nodes\n        while (!queue.isEmpty()) {\n            int node = queue.poll();\n            sortedOrder.add(node);\n\n            // For each child, decrement its in-degree\n            for (int child : graph.get(node)) {\n                inDegree.put(child, inDegree.get(child) - 1);\n                if (inDegree.get(child) == 0) {\n                    queue.offer(child);\n                }\n            }\n        }\n\n        // If sortedOrder doesn\'t contain all tasks, a cycle exists\n        if (sortedOrder.size() != tasks) {\n            return new ArrayList<>(); // Return empty list for cycle\n        }\n\n        return sortedOrder;\n    }\n}',
  E'/**\n * @param {any, any} tasks, prerequisites\n * @return {any}\n */\nfunction topologicalSort(tasks, prerequisites) {\n    // Your code here\n}',
  E'function topologicalSort(tasks, prerequisites) {\n    const sortedOrder = [];\n    if (tasks <= 0) {\n        return sortedOrder;\n    }\n\n    // Initialize graph and in-degrees\n    const inDegree = new Map(); // Map<number, number>\n    const graph = new Map();    // Map<number, number[]>\n\n    for (let i = 0; i < tasks; i++) {\n        inDegree.set(i, 0);\n        graph.set(i, []);\n    }\n\n    // Build graph and populate in-degrees\n    for (const [parent, child] of prerequisites) {\n        graph.get(parent).push(child);\n        inDegree.set(child, inDegree.get(child) + 1);\n    }\n\n    // Find all sources (nodes with 0 in-degree)\n    const queue = []; // Use array as a queue\n    for (const [node, degree] of inDegree.entries()) {\n        if (degree === 0) {\n            queue.push(node);\n        }\n    }\n\n    // Process nodes\n    while (queue.length > 0) {\n        const node = queue.shift(); // Dequeue\n        sortedOrder.push(node);\n\n        // For each child, decrement its in-degree\n        for (const child of graph.get(node)) {\n            inDegree.set(child, inDegree.get(child) - 1);\n            if (inDegree.get(child) === 0) {\n                queue.push(child); // Enqueue\n            }\n        }\n    }\n\n    // If sortedOrder doesn\'t contain all tasks, a cycle exists\n    if (sortedOrder.length !== tasks) {\n        return []; // Return empty array for cycle\n    }\n\n    return sortedOrder;\n}',
  ARRAY['topological-sort', 'sorting'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'uber-sde2', 'airbnb-swe'],
  'topological-sort',
  '[{"input":"topological_sort(4, [[3,2],[3,0],[2,0],[2,1]])","expected_output":"[3, 2, 0, 1] or [3, 2, 1, 0]"},{"input":"topological_sort(3, [[0,1],[1,2]])","expected_output":"[0, 1, 2]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
