INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-topo-sort-can-schedule',
  'Tasks Scheduling',
  'hard',
  'Tasks Scheduling

Problem Statement

Given a number of tasks and a list of prerequisite pairs, determine if it is possible to schedule **all** tasks. In other words, check if the dependency graph contains a cycle.

Examples

**Example 1:**

**Example 2:**

**Example 3:**',
  '',
  '[{"input":"tasks = 3, prerequisites = [[0,1],[1,2]]","output":"True","explanation":"Linear chain 0→1→2, no cycle."},{"input":"tasks = 3, prerequisites = [[0,1],[1,2],[2,0]]","output":"False","explanation":"Cycle exists: 0→1→2→0."},{"input":"tasks = 6, prerequisites = [[2,5],[0,5],[0,4],[1,4],[3,2],[1,3]]","output":"True"}]'::jsonb,
  'can_schedule',
  E'from collections import deque, defaultdict\ndef can_schedule(tasks, prerequisites):\n    # TODO: Return True if all tasks can be scheduled, False if cycle exists\n    pass\n\n# Expected: True\n# Expected: False\n# Expected: True',
  E'from collections import deque, defaultdict\ndef can_schedule(tasks, prerequisites):\n    in_degree = {i: 0 for i in range(tasks)}\n    graph = defaultdict(list)\n\n    for parent, child in prerequisites:\n        graph[parent].append(child)\n        in_degree[child] += 1\n    queue = deque([node for node in in_degree if in_degree[node] == 0])\n    count = 0\n    while queue:\n        node = queue.popleft()\n        count += 1\n        for child in graph[node]:\n            in_degree[child] -= 1\n            if in_degree[child] == 0:\n                queue.append(child)\n    return count == tasks\n# Expected: True\n# Expected: False\n# Expected: True',
  E'class Solution {\n    public Object canSchedule(Object tasks, Object prerequisites) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.*;\n\nclass Solution {\n    public static boolean canSchedule(int tasks, int[][] prerequisites) {\n        if (tasks <= 0) {\n            return true; // No tasks, so all can be scheduled\n        }\n\n        // Initialize graph and in-degrees\n        Map<Integer, Integer> inDegree = new HashMap<>();\n        Map<Integer, List<Integer>> graph = new HashMap<>();\n        for (int i = 0; i < tasks; i++) {\n            inDegree.put(i, 0);\n            graph.put(i, new ArrayList<>());\n        }\n\n        // Build graph and populate in-degrees\n        for (int[] prerequisite : prerequisites) {\n            int parent = prerequisite[0];\n            int child = prerequisite[1];\n            graph.get(parent).add(child);\n            inDegree.put(child, inDegree.get(child) + 1);\n        }\n\n        // Find all sources (nodes with 0 in-degree)\n        Queue<Integer> queue = new LinkedList<>();\n        for (Map.Entry<Integer, Integer> entry : inDegree.entrySet()) {\n            if (entry.getValue() == 0) {\n                queue.offer(entry.getKey());\n            }\n        }\n\n        int count = 0; // Count of tasks processed\n        // Process nodes\n        while (!queue.isEmpty()) {\n            int node = queue.poll();\n            count++;\n\n            // For each child, decrement its in-degree\n            for (int child : graph.get(node)) {\n                inDegree.put(child, inDegree.get(child) - 1);\n                if (inDegree.get(child) == 0) {\n                    queue.offer(child);\n                }\n            }\n        }\n\n        // If count equals total tasks, all tasks can be scheduled (no cycle)\n        return count == tasks;\n    }\n}',
  E'/**\n * @param {any, any} tasks, prerequisites\n * @return {any}\n */\nfunction canSchedule(tasks, prerequisites) {\n    // Your code here\n}',
  E'function canSchedule(tasks, prerequisites) {\n    if (tasks <= 0) {\n        return true; // No tasks, so all can be scheduled\n    }\n\n    // Initialize graph and in-degrees\n    const inDegree = new Map(); // Map<number, number>\n    const graph = new Map();    // Map<number, number[]>\n\n    for (let i = 0; i < tasks; i++) {\n        inDegree.set(i, 0);\n        graph.set(i, []);\n    }\n\n    // Build graph and populate in-degrees\n    for (const [parent, child] of prerequisites) {\n        graph.get(parent).push(child);\n        inDegree.set(child, inDegree.get(child) + 1);\n    }\n\n    // Find all sources (nodes with 0 in-degree)\n    const queue = []; // Use array as a queue\n    for (const [node, degree] of inDegree.entries()) {\n        if (degree === 0) {\n            queue.push(node);\n        }\n    }\n\n    let count = 0; // Count of tasks processed\n    // Process nodes\n    while (queue.length > 0) {\n        const node = queue.shift(); // Dequeue\n        count++;\n\n        // For each child, decrement its in-degree\n        for (const child of graph.get(node)) {\n            inDegree.set(child, inDegree.get(child) - 1);\n            if (inDegree.get(child) === 0) {\n                queue.push(child); // Enqueue\n            }\n        }\n    }\n\n    // If count equals total tasks, all tasks can be scheduled (no cycle)\n    return count === tasks;\n}',
  ARRAY['topological-sort', 'sorting'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'uber-sde2', 'airbnb-swe'],
  'topological-sort',
  '[{"input":"can_schedule(3, [[0,1],[1,2]])","expected_output":"True"},{"input":"can_schedule(3, [[0,1],[1,2],[2,0]])","expected_output":"False"},{"input":"can_schedule(6, [[2,5],[0,5],[0,4],[1,4],[3,2],[1,3]])","expected_output":"True"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
