INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-topo-sort-order',
  'Tasks Scheduling Order',
  'hard',
  'Tasks Scheduling Order

Problem Statement

Given a number of tasks and prerequisite pairs, find the **execution order** of all tasks. If tasks cannot all be scheduled (cycle exists), return an empty list.

This is the same as basic topological sort but with explicit cycle detection and an empty-list return for invalid inputs.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[{"input":"tasks = 6, prerequisites = [[2,5],[0,5],[0,4],[1,4],[3,2],[1,3]]","output":"[0, 1, 3, 2, 4, 5] (one valid ordering)"},{"input":"tasks = 3, prerequisites = [[0,1],[1,2],[2,0]]","output":"[] (cycle detected)"}]'::jsonb,
  'find_scheduling_order',
  E'from collections import deque, defaultdict\ndef find_scheduling_order(tasks, prerequisites):\n    # TODO: Return task execution order, or [] if cycle exists\n    pass\n\n# Expected: [0, 1, 3, 2, 4, 5] (or another valid ordering)\n# Expected: []',
  E'from collections import deque, defaultdict\ndef find_scheduling_order(tasks, prerequisites):\n    in_degree = {i: 0 for i in range(tasks)}\n    graph = defaultdict(list)\n\n    for parent, child in prerequisites:\n        graph[parent].append(child)\n        in_degree[child] += 1\n    queue = deque([node for node in in_degree if in_degree[node] == 0])\n    sorted_order = []\n    while queue:\n        node = queue.popleft()\n        sorted_order.append(node)\n        for child in graph[node]:\n            in_degree[child] -= 1\n            if in_degree[child] == 0:\n                queue.append(child)\n    if len(sorted_order) != tasks:\n        return []\n    return sorted_order\n# Expected: [0, 1, 3, 2, 4, 5] (or another valid ordering)\n# Expected: []',
  E'class Solution {\n    public Object findSchedulingOrder(Object tasks, Object prerequisites) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.*;\n\nclass Solution {\n    public static List<Integer> findSchedulingOrder(int tasks, int[][] prerequisites) {\n        // 1. Initialize in-degrees and graph\n        int[] inDegree = new int[tasks];\n        Map<Integer, List<Integer>> graph = new HashMap<>();\n\n        for (int i = 0; i < tasks; i++) {\n            graph.put(i, new ArrayList<>()); // Ensure all nodes are in graph, even if no outgoing edges\n        }\n\n        for (int[] prerequisite : prerequisites) {\n            int parent = prerequisite[0];\n            int child = prerequisite[1];\n            graph.get(parent).add(child);\n            inDegree[child]++;\n        }\n\n        // 2. Initialize queue with all sources (nodes with in-degree 0)\n        Deque<Integer> queue = new LinkedList<>();\n        for (int i = 0; i < tasks; i++) {\n            if (inDegree[i] == 0) {\n                queue.offer(i);\n            }\n        }\n\n        // 3. Perform BFS\n        List<Integer> sortedOrder = new ArrayList<>();\n        while (!queue.isEmpty()) {\n            int node = queue.poll();\n            sortedOrder.add(node);\n\n            for (int child : graph.get(node)) {\n                inDegree[child]--;\n                if (inDegree[child] == 0) {\n                    queue.offer(child);\n                }\n            }\n        }\n\n        // 4. Check for cycle\n        if (sortedOrder.size() != tasks) {\n            return new ArrayList<>(); // Cycle detected\n        }\n\n        return sortedOrder;\n    }\n}',
  E'/**\n * @param {any, any} tasks, prerequisites\n * @return {any}\n */\nfunction findSchedulingOrder(tasks, prerequisites) {\n    // Your code here\n}',
  E'function findSchedulingOrder(tasks, prerequisites) {\n    // 1. Initialize in-degrees and graph\n    const inDegree = new Array(tasks).fill(0);\n    const graph = new Map();\n\n    for (let i = 0; i < tasks; i++) {\n        graph.set(i, []);\n    }\n\n    for (const [parent, child] of prerequisites) {\n        graph.get(parent).push(child);\n        inDegree[child]++;\n    }\n\n    // 2. Initialize queue with all sources (nodes with in-degree 0)\n    const queue = [];\n    for (let i = 0; i < tasks; i++) {\n        if (inDegree[i] === 0) {\n            queue.push(i);\n        }\n    }\n\n    // 3. Perform BFS\n    const sortedOrder = [];\n    while (queue.length > 0) {\n        const node = queue.shift(); // Dequeue\n        sortedOrder.push(node);\n\n        for (const child of graph.get(node)) {\n            inDegree[child]--;\n            if (inDegree[child] === 0) {\n                queue.push(child);\n            }\n        }\n    }\n\n    // 4. Check for cycle\n    if (sortedOrder.length !== tasks) {\n        return []; // Cycle detected\n    }\n\n    return sortedOrder;\n}',
  ARRAY['topological-sort', 'sorting'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'uber-sde2', 'airbnb-swe'],
  'topological-sort',
  '[{"input":"find_scheduling_order(6, [[2,5],[0,5],[0,4],[1,4],[3,2],[1,3]])","expected_output":"[0, 1, 3, 2, 4, 5] (or another valid ordering)"},{"input":"find_scheduling_order(3, [[0,1],[1,2],[2,0]])","expected_output":"[]"}]'::jsonb,
