INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-topo-sort-all-orders',
  'All Tasks Scheduling Orders',
  'hard',
  'All Tasks Scheduling Orders

Problem Statement

Given a number of tasks and prerequisite pairs, find **all possible valid orderings** of the tasks.

Examples

**Example 1:**

**Example 2:**',
  '',
  '[{"input":"tasks = 3, prerequisites = [[0,1],[1,2]]","output":"[[0, 1, 2]]","explanation":"Only one valid ordering exists."},{"input":"tasks = 4, prerequisites = [[3,2],[3,0],[2,0],[2,1]]","output":"[[3,2,0,1],[3,2,1,0]]","explanation":"After task 3 and 2, tasks 0 and 1 can be done in either order."}]'::jsonb,
  'all_topological_sorts',
  E'from collections import defaultdict, deque\ndef all_topological_sorts(tasks, prerequisites):\n    # TODO: Return all valid topological orderings\n    result = []\n    return result\n\n# Expected: [[0, 1, 2]]\n# Expected: [[3, 2, 0, 1], [3, 2, 1, 0]]',
  E'from collections import defaultdict, deque\ndef all_topological_sorts(tasks, prerequisites):\n    in_degree = {i: 0 for i in range(tasks)}\n    graph = defaultdict(list)\n\n    for parent, child in prerequisites:\n        graph[parent].append(child)\n        in_degree[child] += 1\n    result = []\n    def backtrack(current_order, in_deg):\n        # Find all current sources (in-degree 0)\n        sources = [node for node in range(tasks) if in_deg[node] == 0 and node not in current_order]\n\n        if not sources:\n            if len(current_order) == tasks:\n                result.append(list(current_order))\n            return\n        for source in sources:\n            current_order.append(source)\n            # Decrement in-degrees\n            for child in graph[source]:\n                in_deg[child] -= 1\n            backtrack(current_order, in_deg)\n            # Backtrack\n            current_order.pop()\n            for child in graph[source]:\n                in_deg[child] += 1\n    backtrack([], dict(in_degree))\n    return result\n# Expected: [[0, 1, 2]]\n# Expected: [[3, 2, 0, 1], [3, 2, 1, 0]]',
  E'class Solution {\n    public Object allTopologicalSorts(Object tasks, Object prerequisites) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.*;\n\nclass Solution {\n    private static List<List<Integer>> result;\n    private static Map<Integer, List<Integer>> graph;\n    private static int totalTasks;\n\n    public static List<List<Integer>> allTopologicalSorts(int tasks, int[][] prerequisites) {\n        totalTasks = tasks;\n        result = new ArrayList<>();\n        graph = new HashMap<>();\n\n        int[] inDegree = new int[tasks];\n\n        for (int i = 0; i < tasks; i++) {\n            graph.put(i, new ArrayList<>());\n        }\n\n        for (int[] prerequisite : prerequisites) {\n            int parent = prerequisite[0];\n            int child = prerequisite[1];\n            graph.get(parent).add(child);\n            inDegree[child]++;\n        }\n\n        // The Python solution passes a copy of in_degree to the initial backtrack call.\n        // We create a copy of the inDegree array for the initial call.\n        int[] initialInDegree = Arrays.copyOf(inDegree, tasks);\n        \n        backtrack(new ArrayList<>(), initialInDegree);\n        return result;\n    }\n\n    private static void backtrack(List<Integer> currentOrder, int[] currentInDegree) {\n        // Find all current sources (in-degree 0)\n        List<Integer> sources = new ArrayList<>();\n        for (int node = 0; node < totalTasks; node++) {\n            if (currentInDegree[node] == 0 && !currentOrder.contains(node)) {\n                sources.add(node);\n            }\n        }\n\n        if (sources.isEmpty()) {\n            if (currentOrder.size() == totalTasks) {\n                result.add(new ArrayList<>(currentOrder)); // Add a copy of the current order\n            }\n            return;\n        }\n\n        for (int source : sources) {\n            currentOrder.add(source);\n            \n            // Decrement in-degrees\n            for (int child : graph.get(source)) {\n                currentInDegree[child]--;\n            }\n\n            backtrack(currentOrder, currentInDegree);\n\n            // Backtrack: restore state\n            currentOrder.remove(currentOrder.size() - 1);\n            for (int child : graph.get(source)) {\n                currentInDegree[child]++;\n            }\n        }\n    }\n}',
  E'/**\n * @param {any, any} tasks, prerequisites\n * @return {any}\n */\nfunction allTopologicalSorts(tasks, prerequisites) {\n    // Your code here\n}',
  E'function allTopologicalSorts(tasks, prerequisites) {\n    const result = [];\n    const graph = new Map();\n    const inDegree = new Array(tasks).fill(0);\n\n    for (let i = 0; i < tasks; i++) {\n        graph.set(i, []);\n    }\n\n    for (const [parent, child] of prerequisites) {\n        graph.get(parent).push(child);\n        inDegree[child]++;\n    }\n\n    // Python\'s `dict(in_degree)` creates a shallow copy.\n    // For an array, `[...inDegree]` creates a shallow copy.\n    const initialInDegree = [...inDegree];\n\n    function backtrack(currentOrder, currentInDegree) {\n        // Find all current sources (in-degree 0)\n        const sources = [];\n        for (let node = 0; node < tasks; node++) {\n            if (currentInDegree[node] === 0 && !currentOrder.includes(node)) {\n                sources.push(node);\n            }\n        }\n\n        if (sources.length === 0) {\n            if (currentOrder.length === tasks) {\n                result.push([...currentOrder]); // Add a copy of the current order\n            }\n            return;\n        }\n\n        for (const source of sources) {\n            currentOrder.push(source);\n            \n            // Decrement in-degrees\n            for (const child of graph.get(source)) {\n                currentInDegree[child]--;\n            }\n\n            backtrack(currentOrder, currentInDegree);\n\n            // Backtrack: restore state\n            currentOrder.pop();\n            for (const child of graph.get(source)) {\n                currentInDegree[child]++;\n            }\n        }\n    }\n\n    backtrack([], initialInDegree);\n    return result;\n}',
  ARRAY['topological-sort', 'sorting'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'uber-sde2', 'airbnb-swe'],
  'topological-sort',
  '[{"input":"all_topological_sorts(3, [[0,1],[1,2]])","expected_output":"[[0, 1, 2]]"},{"input":"all_topological_sorts(4, [[3,2],[3,0],[2,0],[2,1]])","expected_output":"[[3, 2, 0, 1], [3, 2, 1, 0]]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
