INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-topo-sort-course-schedule',
  'Course Schedule',
  'hard',
  'Course Schedule

Problem Statement

There are `numCourses` courses labeled from 0 to `numCourses - 1`. You are given prerequisite pairs where `[a, b]` means you must complete course `b` before course `a`. Determine if it is possible to finish all courses.

Examples

**Example 1:**

**Example 2:**

**Example 3:**',
  '',
  '[{"input":"numCourses = 2, prerequisites = [[1, 0]]","output":"True","explanation":"Take course 0 first, then course 1."},{"input":"numCourses = 2, prerequisites = [[1, 0], [0, 1]]","output":"False","explanation":"Circular dependency: 0 requires 1 and 1 requires 0."},{"input":"numCourses = 4, prerequisites = [[1,0],[2,1],[3,2]]","output":"True","explanation":"Linear chain 0→1→2→3."}]'::jsonb,
  'can_finish',
  E'from collections import deque, defaultdict\ndef can_finish(num_courses, prerequisites):\n    # TODO: Return True if all courses can be completed\n    # Note: [a, b] means b must be taken before a\n    pass\n\n# Expected: True\n# Expected: False\n# Expected: True',
  E'from collections import deque, defaultdict\ndef can_finish(num_courses, prerequisites):\n    in_degree = {i: 0 for i in range(num_courses)}\n    graph = defaultdict(list)\n\n    for course, prereq in prerequisites:\n        graph[prereq].append(course)\n        in_degree[course] += 1\n    queue = deque([node for node in in_degree if in_degree[node] == 0])\n    count = 0\n    while queue:\n        node = queue.popleft()\n        count += 1\n        for child in graph[node]:\n            in_degree[child] -= 1\n            if in_degree[child] == 0:\n                queue.append(child)\n    return count == num_courses\n# Expected: True\n# Expected: False\n# Expected: True',
  E'class Solution {\n    public Object canFinish(Object num_courses, Object prerequisites) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.*;\n\nclass Solution {\n    public static boolean canFinish(int numCourses, int[][] prerequisites) {\n        // 1. Initialize in-degrees and graph\n        int[] inDegree = new int[numCourses];\n        Map<Integer, List<Integer>> graph = new HashMap<>();\n\n        for (int i = 0; i < numCourses; i++) {\n            graph.put(i, new ArrayList<>());\n        }\n\n        // Note: [course, prereq] means prereq must be taken before course.\n        // So, prereq is parent, course is child.\n        for (int[] prerequisite : prerequisites) {\n            int course = prerequisite[0];\n            int prereq = prerequisite[1];\n            graph.get(prereq).add(course); // Edge from prereq to course\n            inDegree[course]++;\n        }\n\n        // 2. Initialize queue with all sources (nodes with in-degree 0)\n        Deque<Integer> queue = new LinkedList<>();\n        for (int i = 0; i < numCourses; i++) {\n            if (inDegree[i] == 0) {\n                queue.offer(i);\n            }\n        }\n\n        // 3. Perform BFS\n        int count = 0;\n        while (!queue.isEmpty()) {\n            int node = queue.poll();\n            count++;\n\n            for (int child : graph.get(node)) {\n                inDegree[child]--;\n                if (inDegree[child] == 0) {\n                    queue.offer(child);\n                }\n            }\n        }\n\n        // 4. Check if all courses can be finished (no cycle)\n        return count == numCourses;\n    }\n}',
  E'/**\n * @param {any, any} num_courses, prerequisites\n * @return {any}\n */\nfunction canFinish(num_courses, prerequisites) {\n    // Your code here\n}',
  E'function canFinish(numCourses, prerequisites) {\n    // 1. Initialize in-degrees and graph\n    const inDegree = new Array(numCourses).fill(0);\n    const graph = new Map();\n\n    for (let i = 0; i < numCourses; i++) {\n        graph.set(i, []);\n    }\n\n    // Note: [course, prereq] means prereq must be taken before course.\n    // So, prereq is parent, course is child.\n    for (const [course, prereq] of prerequisites) {\n        graph.get(prereq).push(course); // Edge from prereq to course\n        inDegree[course]++;\n    }\n\n    // 2. Initialize queue with all sources (nodes with in-degree 0)\n    const queue = [];\n    for (let i = 0; i < numCourses; i++) {\n        if (inDegree[i] === 0) {\n            queue.push(i);\n        }\n    }\n\n    // 3. Perform BFS\n    let count = 0;\n    while (queue.length > 0) {\n        const node = queue.shift(); // Dequeue\n        count++;\n\n        for (const child of graph.get(node)) {\n            inDegree[child]--;\n            if (inDegree[child] === 0) {\n                queue.push(child);\n            }\n        }\n    }\n\n    // 4. Check if all courses can be finished (no cycle)\n    return count === numCourses;\n}',
  ARRAY['topological-sort', 'sorting'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'uber-sde2', 'airbnb-swe'],
  'topological-sort',
  '[{"input":"can_finish(2, [[1, 0]])","expected_output":"True"},{"input":"can_finish(2, [[1, 0], [0, 1]])","expected_output":"False"},{"input":"can_finish(4, [[1, 0], [2, 1], [3, 2]])","expected_output":"True"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
  description = EXCLUDED.description,
  constraints = EXCLUDED.constraints,
  examples = EXCLUDED.examples,
  function_name = EXCLUDED.function_name,
  starter_code_python = EXCLUDED.starter_code_python,
  solution_code_python = EXCLUDED.solution_code_python,
  starter_code_java = EXCLUDED.starter_code_java,
