INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-dp-lcs',
  'Longest Common Subsequence',
  'hard',
  'Longest Common Subsequence

Problem Statement

Given two strings `s1` and `s2`, find the length of their **longest common subsequence** (LCS). A subsequence is a sequence derived by deleting zero or more characters without changing the order of remaining characters.

Examples

**Example 1:**

**Example 2:**

**Example 3:**',
  '',
  '[{"input":"s1 = \"abdca\", s2 = \"cbda\"","output":"3","explanation":"LCS is \"bda\" (length 3)."},{"input":"s1 = \"passport\", s2 = \"ppsspt\"","output":"5","explanation":"LCS is \"psspt\" (length 5)."},{"input":"s1 = \"abc\", s2 = \"def\"","output":"0","explanation":"No common characters."}]'::jsonb,
  'longest_common_subsequence',
  E'def longest_common_subsequence(s1, s2):\n    # TODO: Return the length of the longest common subsequence\n    pass\n\n# Expected: 3\n# Expected: 5\n# Expected: 0',
  E'def longest_common_subsequence(s1, s2):\n    m, n = len(s1), len(s2)\n    dp = [[0] * (n + 1) for _ in range(m + 1)]\n\n    for i in range(1, m + 1):\n        for j in range(1, n + 1):\n            if s1[i - 1] == s2[j - 1]:\n                dp[i][j] = 1 + dp[i - 1][j - 1]\n            else:\n                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])\n    return dp[m][n]\n# Expected: 3\n# Expected: 5\n# Expected: 0',
  E'class Solution {\n    public Object longestCommonSubsequence(Object s1, Object s2) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int longestCommonSubsequence(String s1, String s2) {\n        int m = s1.length();\n        int n = s2.length();\n        int[][] dp = new int[m + 1][n + 1];\n\n        for (int i = 1; i <= m; i++) {\n            for (int j = 1; j <= n; j++) {\n                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {\n                    dp[i][j] = 1 + dp[i - 1][j - 1];\n                } else {\n                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);\n                }\n            }\n        }\n        return dp[m][n];\n    }\n}',
  E'/**\n * @param {any, any} s1, s2\n * @return {any}\n */\nfunction longestCommonSubsequence(s1, s2) {\n    // Your code here\n}',
  E'function longestCommonSubsequence(s1, s2) {\n    const m = s1.length;\n    const n = s2.length;\n    const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));\n\n    for (let i = 1; i <= m; i++) {\n        for (let j = 1; j <= n; j++) {\n            if (s1[i - 1] === s2[j - 1]) {\n                dp[i][j] = 1 + dp[i - 1][j - 1];\n            } else {\n                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);\n            }\n        }\n    }\n    return dp[m][n];\n}',
  ARRAY['dynamic-programming'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'stripe-l2'],
  'dynamic-programming',
  '[{"input":"longest_common_subsequence(\"abdca\", \"cbda\")","expected_output":"3"},{"input":"longest_common_subsequence(\"passport\", \"ppsspt\")","expected_output":"5"},{"input":"longest_common_subsequence(\"abc\", \"def\")","expected_output":"0"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
  description = EXCLUDED.description,
  constraints = EXCLUDED.constraints,
  examples = EXCLUDED.examples,
