INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-dp-lis',
  'Longest Increasing Subsequence',
  'hard',
  'Longest Increasing Subsequence

Problem Statement

Given an integer array, find the length of the **longest strictly increasing subsequence**.

Examples

**Example 1:**

**Example 2:**

**Example 3:**',
  '',
  '[{"input":"[4, 2, 3, 6, 10, 1, 12]","output":"5","explanation":"[2, 3, 6, 10, 12] is the LIS."},{"input":"[10, 9, 2, 5, 3, 7, 101, 18]","output":"4","explanation":"[2, 3, 7, 101] or [2, 3, 7, 18] or [2, 5, 7, 101] etc."},{"input":"[7, 7, 7, 7]","output":"1","explanation":"All elements are equal, so LIS has length 1."}]'::jsonb,
  'longest_increasing_subsequence',
  E'def longest_increasing_subsequence(nums):\n    # TODO: Return the length of the longest increasing subsequence\n    pass\n\n# Expected: 5\n# Expected: 4\n# Expected: 1',
  E'def longest_increasing_subsequence(nums):\n    if not nums:\n        return 0\n\n    n = len(nums)\n    dp = [1] * n\n    for i in range(1, n):\n        for j in range(i):\n            if nums[j] < nums[i]:\n                dp[i] = max(dp[i], dp[j] + 1)\n    return max(dp)\n# Expected: 5\n# Expected: 4\n# Expected: 1',
  E'class Solution {\n    public Object longestIncreasingSubsequence(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int longestIncreasingSubsequence(int[] nums) {\n        if (nums == null || nums.length == 0) {\n            return 0;\n        }\n\n        int n = nums.length;\n        int[] dp = new int[n];\n        for (int i = 0; i < n; i++) {\n            dp[i] = 1;\n        }\n\n        for (int i = 1; i < n; i++) {\n            for (int j = 0; j < i; j++) {\n                if (nums[j] < nums[i]) {\n                    dp[i] = Math.max(dp[i], dp[j] + 1);\n                }\n            }\n        }\n\n        int maxLength = 0;\n        for (int length : dp) {\n            maxLength = Math.max(maxLength, length);\n        }\n        return maxLength;\n    }\n}',
