INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-pair-with-target-sum',
  'Pair with Target Sum',
  'medium',
  'Pair with Target Sum

<!-- voice:section_check concept="opposite-direction two pointers" -->

Problem Statement

Given a **sorted** array of integers and a target sum, find **two numbers** in the array that add up to the target. Return their **indices** as a list `[i, j]` where `i < j`. If no such pair exists, return `[-1, -1]`.

Examples

~~~
Input:  arr = [1, 2, 3, 4, 6], target = 6
Output: [1, 3]
Explanation: arr[1] + arr[3] = 2 + 4 = 6
~~~

~~~
Input:  arr = [2, 5, 9, 11], target = 11
Output: [0, 2]
Explanation: arr[0] + arr[2] = 2 + 9 = 11
~~~

~~~
Input:  arr = [1, 2, 3], target = 7
Output: [-1, -1]
~~~',
  '',
  '[{"input":"arr = [1, 2, 3, 4, 6], target = 6","output":"[1, 3]","explanation":"arr[1] + arr[3] = 2 + 4 = 6"}]'::jsonb,
  'pair_with_target_sum',
  E'def pair_with_target_sum(arr, target):\n    """\n    Find two numbers in a sorted array that add up to target.\n\n    Args:\n        arr: Sorted list of integers\n        target: Target sum\n    Returns:\n        List of two indices [i, j] where arr[i] + arr[j] == target,\n        or [-1, -1] if no such pair exists\n    Example:\n        >>> pair_with_target_sum([1, 2, 3, 4, 6], 6)\n        [1, 3]\n    """\n    # TODO: Use two pointers starting at opposite ends\n    # Hint: Move pointers based on whether current sum is too small or too large\n    pass\n# ─── Test Cases ───\n# Do not modify below this line\n# Normal case\n# Expected: [1, 3]\n# Different target\n# Expected: [0, 2]\n# No solution exists\n# Expected: [-1, -1]\n# Edge case: single element\n# Expected: [-1, -1]',
  E'def pair_with_target_sum(arr, target):\n    """\n    Find two numbers in a sorted array that add up to target.\n\n    Time Complexity: O(n) — each pointer moves at most n steps\n    Space Complexity: O(1) — no extra data structures\n    """\n    left, right = 0, len(arr) - 1\n    while left < right:\n        current_sum = arr[left] + arr[right]\n        if current_sum == target:\n            return [left, right]\n        elif current_sum < target:\n            # Sum is too small, need larger values → move left right\n            left += 1\n        else:\n            # Sum is too large, need smaller values → move right left\n            right -= 1\n    return [-1, -1]\n# ─── Test Cases ───\n# Expected: [1, 3]\n# Expected: [0, 2]\n# Expected: [-1, -1]\n# Expected: [-1, -1]',
  E'class Solution {\n    public Object pairWithTargetSum(int[] arr, int target) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int[] pairWithTargetSum(int[] arr, int target) {\n        int left = 0;\n        int right = arr.length - 1;\n        while (left < right) {\n            int currentSum = arr[left] + arr[right];\n            if (currentSum == target) {\n                return new int[]{left, right};\n            } else if (currentSum < target) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n        return new int[]{-1, -1};\n    }\n}',
  E'/**\n * @param {any, any} arr, target\n * @return {any}\n */\nfunction pairWithTargetSum(arr, target) {\n    // Your code here\n}',
  E'function pairWithTargetSum(arr, target) {\n    let left = 0;\n    let right = arr.length - 1;\n    while (left < right) {\n        let currentSum = arr[left] + arr[right];\n        if (currentSum === target) {\n            return [left, right];\n        } else if (currentSum < target) {\n            left++;\n        } else {\n            right--;\n        }\n    }\n    return [-1, -1];\n}',
  ARRAY['two-pointers'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'apple-ict3', 'linkedin-swe'],
  'two-pointers',
  '[{"input":"pair_with_target_sum([1, 2, 3, 4, 6], 6)","expected_output":"[1, 3]"},{"input":"pair_with_target_sum([2, 5, 9, 11], 11)","expected_output":"[0, 2]"},{"input":"pair_with_target_sum([1, 2, 3], 7)","expected_output":"[-1, -1]"}]'::jsonb,
  '[{"input":"pair_with_target_sum([5], 5)","expected_output":"[-1, -1]"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
