INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-remove-duplicates',
  'Remove Duplicates',
  'medium',
  'Remove Duplicates from Sorted Array

<!-- voice:section_check concept="same-direction two pointers" -->

Problem Statement

Given a **sorted** array, remove all duplicate values **in-place** so that each element appears only once. Return the **new length** of the array. The first `k` elements of the array should hold the unique values.

Examples

~~~
Input:  [2, 3, 3, 3, 6, 9, 9]
Output: 4
Array becomes: [2, 3, 6, 9, ...]
~~~

~~~
Input:  [2, 2, 2, 11]
Output: 2
Array becomes: [2, 11, ...]
~~~',
  '',
  '[{"input":"[2, 3, 3, 3, 6, 9, 9]","output":"4"}]'::jsonb,
  'remove_duplicates',
  E'def remove_duplicates(arr):\n    """\n    Remove duplicates from sorted array in-place.\n    Return the new length of the array with unique elements.\n\n    Args:\n        arr: Sorted list of integers (modified in-place)\n    Returns:\n        int: Length of array with unique elements\n    Example:\n        >>> remove_duplicates([2, 3, 3, 3, 6, 9, 9])\n        4\n    """\n    # TODO: Use slow and fast pointers\n    # Hint: slow tracks unique elements, fast scans for new values\n    pass\n# ─── Test Cases ───\n# Normal case with duplicates\narr1 = [2, 3, 3, 3, 6, 9, 9]\n# Expected: 4\n# All same elements\narr2 = [2, 2, 2, 11]\n# Expected: 2\n# No duplicates\narr3 = [1, 2, 3, 4]\n# Expected: 4\n# Empty array\narr4 = []\n# Expected: 0',
  E'def remove_duplicates(arr):\n    """\n    Remove duplicates from sorted array in-place.\n    Return the new length of the array with unique elements.\n\n    Time Complexity: O(n) — single pass through array\n    Space Complexity: O(1) — in-place modification\n    """\n    if not arr:\n        return 0\n    # slow marks the last unique element found\n    slow = 0\n    # fast scans for next unique element\n    for fast in range(1, len(arr)):\n        if arr[fast] != arr[slow]:\n            # Found a new unique element\n            slow += 1\n            arr[slow] = arr[fast]\n    # Length is index + 1\n    return slow + 1\n# ─── Test Cases ───\narr1 = [2, 3, 3, 3, 6, 9, 9]\n# Expected: 4\narr2 = [2, 2, 2, 11]\n# Expected: 2\narr3 = [1, 2, 3, 4]\n# Expected: 4\narr4 = []\n# Expected: 0',
  E'class Solution {\n    public Object removeDuplicates(int[] arr) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int removeDuplicates(int[] arr) {\n        if (arr == null || arr.length == 0) {\n            return 0;\n        }\n        int slow = 0;\n        for (int fast = 1; fast < arr.length; fast++) {\n            if (arr[fast] != arr[slow]) {\n                slow++;\n                arr[slow] = arr[fast];\n            }\n        }\n        return slow + 1;\n    }\n}',
  E'/**\n * @param {any} arr\n * @return {any}\n */\nfunction removeDuplicates(arr) {\n    // Your code here\n}',
  E'function removeDuplicates(arr) {\n    if (!arr || arr.length === 0) {\n        return 0;\n    }\n    let slow = 0;\n    for (let fast = 1; fast < arr.length; fast++) {\n        if (arr[fast] !== arr[slow]) {\n            slow++;\n            arr[slow] = arr[fast];\n        }\n    }\n    return slow + 1;\n}',
  ARRAY['two-pointers'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'apple-ict3', 'linkedin-swe'],
  'two-pointers',
  '[{"input":"remove_duplicates(arr1)","expected_output":"4"},{"input":"remove_duplicates(arr2)","expected_output":"2"},{"input":"remove_duplicates(arr3)","expected_output":"4"}]'::jsonb,
  '[{"input":"remove_duplicates(arr4)","expected_output":"0"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
