INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-squaring-sorted-array',
  'Squaring a Sorted Array',
  'medium',
  'Squaring a Sorted Array

<!-- voice:section_check concept="two pointers from both ends" -->

Problem Statement

Given a sorted array of integers (which may contain negative numbers), return a **new array** containing the squares of each number, also **sorted in ascending order**.

Examples

~~~
Input:  [-2, -1, 0, 2, 3]
Output: [0, 1, 4, 4, 9]
~~~

~~~
Input:  [-3, -1, 0, 1, 2]
Output: [0, 1, 1, 4, 9]
~~~',
  '',
  '[{"input":"[-2, -1, 0, 2, 3]","output":"[0, 1, 4, 4, 9]"}]'::jsonb,
  'make_squares',
  E'def make_squares(arr):\n    """\n    Return a new array with squares of input array, sorted.\n\n    Args:\n        arr: Sorted list of integers (may contain negatives)\n    Returns:\n        List of squares in sorted order\n    Example:\n        >>> make_squares([-2, -1, 0, 2, 3])\n        [0, 1, 4, 4, 9]\n    """\n    # TODO: Use two pointers from both ends\n    # Hint: Fill result array from the end with larger squares first\n    pass\n# ─── Test Cases ───\n# Mixed negative and positive\n# Expected: [0, 1, 4, 4, 9]\n# More negatives\n# Expected: [0, 1, 1, 4, 9]\n# All positive\n# Expected: [1, 4, 9]\n# All negative\n# Expected: [4, 9, 25]',
  E'def make_squares(arr):\n    """\n    Return a new array with squares of input array, sorted.\n\n    Time Complexity: O(n) — single pass with two pointers\n    Space Complexity: O(n) — output array\n    """\n    n = len(arr)\n    squares = [0] * n\n    left, right = 0, n - 1\n    highest_index = n - 1\n    while left <= right:\n        left_sq = arr[left] ** 2\n        right_sq = arr[right] ** 2\n        if left_sq > right_sq:\n            # Larger square comes from left (negative number)\n            squares[highest_index] = left_sq\n            left += 1\n        else:\n            # Larger or equal square comes from right\n            squares[highest_index] = right_sq\n            right -= 1\n        highest_index -= 1\n    return squares\n# ─── Test Cases ───\n# Expected: [0, 1, 4, 4, 9]\n# Expected: [0, 1, 1, 4, 9]\n# Expected: [1, 4, 9]\n# Expected: [4, 9, 25]',
  E'class Solution {\n    public Object makeSquares(int[] arr) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int[] makeSquares(int[] arr) {\n        int n = arr.length;\n        int[] squares = new int[n];\n        int left = 0;\n        int right = n - 1;\n        int highestIndex = n - 1;\n        while (left <= right) {\n            int leftSq = arr[left] * arr[left];\n            int rightSq = arr[right] * arr[right];\n            if (leftSq > rightSq) {\n                squares[highestIndex] = leftSq;\n                left++;\n            } else {\n                squares[highestIndex] = rightSq;\n                right--;\n            }\n            highestIndex--;\n        }\n        return squares;\n    }\n}',
  E'/**\n * @param {any} arr\n * @return {any}\n */\nfunction makeSquares(arr) {\n    // Your code here\n}',
  E'function makeSquares(arr) {\n    const n = arr.length;\n    const squares = new Array(n).fill(0);\n    let left = 0;\n    let right = n - 1;\n    let highestIndex = n - 1;\n    while (left <= right) {\n        const leftSq = arr[left] * arr[left];\n        const rightSq = arr[right] * arr[right];\n        if (leftSq > rightSq) {\n            squares[highestIndex] = leftSq;\n            left++;\n        } else {\n            squares[highestIndex] = rightSq;\n            right--;\n        }\n        highestIndex--;\n    }\n    return squares;\n}',
  ARRAY['two-pointers'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'apple-ict3', 'linkedin-swe'],
  'two-pointers',
