INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-triplet-sum-to-zero',
  'Triplet Sum to Zero',
  'hard',
  'Triplet Sum to Zero

<!-- voice:section_check concept="two pointers with sorting" -->

Problem Statement

Given an array of unsorted integers, find **all unique triplets** that sum to zero. The solution must not contain duplicate triplets.

Examples

~~~
Input:  [-3, 0, 1, 2, -1, 1, -2]
Output: [[-3, 1, 2], [-2, 0, 2], [-2, 1, 1], [-1, 0, 1]]
~~~',
  '',
  '[{"input":"[-3, 0, 1, 2, -1, 1, -2]","output":"[[-3, 1, 2], [-2, 0, 2], [-2, 1, 1], [-1, 0, 1]]"}]'::jsonb,
  'search_triplets',
  E'def search_triplets(arr):\n    """\n    Find all unique triplets in the array that sum to zero.\n\n    Args:\n        arr: List of integers (unsorted)\n    Returns:\n        List of unique triplets [a, b, c] where a + b + c == 0\n    Example:\n        >>> search_triplets([-3, 0, 1, 2, -1, 1, -2])\n        [[-3, 1, 2], [-2, 0, 2], [-2, 1, 1], [-1, 0, 1]]\n    """\n    # TODO: Sort array, then for each element use two pointers to find pairs\n    # Hint: Skip duplicates at each level to avoid duplicate triplets\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: [[-3, 1, 2], [-2, 0, 2], [-2, 1, 1], [-1, 0, 1]]\n# Fewer elements\n# Expected: [[-5, 2, 3], [-2, -1, 3]]\n# All zeros\n# Expected: [[0, 0, 0]]\n# No solution\n# Expected: []',
  E'def search_triplets(arr):\n    """\n    Find all unique triplets in the array that sum to zero.\n\n    Time Complexity: O(n²) — sorting O(n log n) + two-pointer scan O(n²)\n    Space Complexity: O(n) — for sorting\n    """\n    arr.sort()\n    triplets = []\n    for i in range(len(arr) - 2):\n        # Skip duplicate values for the first element\n        if i > 0 and arr[i] == arr[i - 1]:\n            continue\n        # Use two pointers to find pair that sums to -arr[i]\n        left, right = i + 1, len(arr) - 1\n        target = -arr[i]\n        while left < right:\n            total = arr[left] + arr[right]\n            if total == target:\n                triplets.append([arr[i], arr[left], arr[right]])\n                left += 1\n                right -= 1\n                # Skip duplicates for second element\n                while left < right and arr[left] == arr[left - 1]:\n                    left += 1\n                # Skip duplicates for third element\n                while left < right and arr[right] == arr[right + 1]:\n                    right -= 1\n            elif total < target:\n                left += 1\n            else:\n                right -= 1\n    return triplets\n# ─── Test Cases ───\n# Expected: [[-3, 1, 2], [-2, 0, 2], [-2, 1, 1], [-1, 0, 1]]\n# Expected: [[-5, 2, 3], [-2, -1, 3]]\n# Expected: [[0, 0, 0]]\n# Expected: []',
  E'class Solution {\n    public Object searchTriplets(int[] arr) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.Arrays;\n    // import java.util.ArrayList;\n    // import java.util.List;\n\n    public static List<List<Integer>> searchTriplets(int[] arr) {\n        Arrays.sort(arr);\n        List<List<Integer>> triplets = new ArrayList<>();\n        for (int i = 0; i < arr.length - 2; i++) {\n            if (i > 0 && arr[i] == arr[i - 1]) {\n                continue;\n            }\n            int left = i + 1;\n            int right = arr.length - 1;\n            int target = -arr[i];\n            while (left < right) {\n                int total = arr[left] + arr[right];\n                if (total == target) {\n                    triplets.add(Arrays.asList(arr[i], arr[left], arr[right]));\n                    left++;\n                    right--;\n                    while (left < right && arr[left] == arr[left - 1]) {\n                        left++;\n                    }\n                    while (left < right && arr[right] == arr[right + 1]) {\n                        right--;\n                    }\n                } else if (total < target) {\n                    left++;\n                } else {\n                    right--;\n                }\n            }\n        }\n        return triplets;\n    }\n}',
  E'/**\n * @param {any} arr\n * @return {any}\n */\nfunction searchTriplets(arr) {\n    // Your code here\n}',
  E'function searchTriplets(arr) {\n    arr.sort((a, b) => a - b);\n    const triplets = [];\n    for (let i = 0; i < arr.length - 2; i++) {\n        if (i > 0 && arr[i] === arr[i - 1]) {\n            continue;\n        }\n        let left = i + 1;\n        let right = arr.length - 1;\n        const target = -arr[i];\n        while (left < right) {\n            const total = arr[left] + arr[right];\n            if (total === target) {\n                triplets.push([arr[i], arr[left], arr[right]]);\n                left++;\n                right--;\n                while (left < right && arr[left] === arr[left - 1]) {\n                    left++;\n                }\n                while (left < right && arr[right] === arr[right + 1]) {\n                    right--;\n                }\n            } else if (total < target) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n    }\n    return triplets;\n}',
  ARRAY['two-pointers'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'apple-ict3', 'linkedin-swe'],
  'two-pointers',
  '[{"input":"search_triplets([-3, 0, 1, 2, -1, 1, -2])","expected_output":"[[-3, 1, 2], [-2, 0, 2], [-2, 1, 1], [-1, 0, 1]]"},{"input":"search_triplets([-5, 2, -1, -2, 3])","expected_output":"[[-5, 2, 3], [-2, -1, 3]]"},{"input":"search_triplets([0, 0, 0])","expected_output":"[[0, 0, 0]]"}]'::jsonb,
  '[{"input":"search_triplets([1, 2, 3])","expected_output":"[]"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
