INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-dutch-national-flag',
  'Dutch National Flag',
  'hard',
  'Dutch National Flag Problem

<!-- voice:section_check concept="three pointers technique" -->

Problem Statement

Given an array containing only **0s, 1s, and 2s**, sort it **in-place** so that all 0s come first, then all 1s, then all 2s. You must do this in a single pass.

This is known as the Dutch National Flag problem, originally proposed by Edsger Dijkstra.

Examples

~~~
Input:  [1, 0, 2, 1, 0]
Output: [0, 0, 1, 1, 2]
~~~

~~~
Input:  [2, 2, 0, 1, 2, 0]
Output: [0, 0, 1, 2, 2, 2]
~~~',
  '',
  '[{"input":"[1, 0, 2, 1, 0]","output":"[0, 0, 1, 1, 2]"}]'::jsonb,
  'dutch_flag_sort',
  E'def dutch_flag_sort(arr):\n    """\n    Sort array of 0s, 1s, and 2s in-place using Dutch National Flag algorithm.\n\n    Args:\n        arr: List containing only 0s, 1s, and 2s (modified in-place)\n    Returns:\n        None (array is modified in-place)\n    Example:\n        >>> arr = [1, 0, 2, 1, 0]\n        >>> dutch_flag_sort(arr)\n        >>> arr\n        [0, 0, 1, 1, 2]\n    """\n    # TODO: Implement three-pointer Dutch National Flag algorithm\n    # Hint: low tracks 0s boundary, high tracks 2s boundary, mid scans\n    pass\n# ─── Test Cases ───\n# Standard case\narr1 = [1, 0, 2, 1, 0]\ndutch_flag_sort(arr1)\n# Expected: [0, 0, 1, 1, 2]\n# More 2s\narr2 = [2, 2, 0, 1, 2, 0]\ndutch_flag_sort(arr2)\n# Expected: [0, 0, 1, 2, 2, 2]\n# Already sorted\narr3 = [0, 0, 1, 1, 2, 2]\ndutch_flag_sort(arr3)\n# Expected: [0, 0, 1, 1, 2, 2]\n# All same\narr4 = [1, 1, 1]\ndutch_flag_sort(arr4)\n# Expected: [1, 1, 1]',
  E'def dutch_flag_sort(arr):\n    """\n    Sort array of 0s, 1s, and 2s in-place using Dutch National Flag algorithm.\n\n    Time Complexity: O(n) — single pass through array\n    Space Complexity: O(1) — in-place swaps\n    Partition zones:\n    [0, low) → all 0s\n    [low, mid) → all 1s\n    [mid, high] → unknown (to be processed)\n    (high, end] → all 2s\n    """\n    low, mid, high = 0, 0, len(arr) - 1\n    while mid <= high:\n        if arr[mid] == 0:\n            # Found a 0, move to low section\n            arr[low], arr[mid] = arr[mid], arr[low]\n            low += 1\n            mid += 1\n        elif arr[mid] == 1:\n            # 1 is in correct position, just advance\n            mid += 1\n        else:  # arr[mid] == 2\n            # Found a 2, move to high section\n            # Don''t advance mid — swapped value needs checking\n            arr[mid], arr[high] = arr[high], arr[mid]\n            high -= 1\n# ─── Test Cases ───\narr1 = [1, 0, 2, 1, 0]\ndutch_flag_sort(arr1)\n# Expected: [0, 0, 1, 1, 2]\narr2 = [2, 2, 0, 1, 2, 0]\ndutch_flag_sort(arr2)\n# Expected: [0, 0, 1, 2, 2, 2]\narr3 = [0, 0, 1, 1, 2, 2]\ndutch_flag_sort(arr3)\n# Expected: [0, 0, 1, 1, 2, 2]\narr4 = [1, 1, 1]\ndutch_flag_sort(arr4)\n# Expected: [1, 1, 1]',
  E'class Solution {\n    public Object dutchFlagSort(int[] arr) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static void dutchFlagSort(int[] arr) {\n        int low = 0;\n        int mid = 0;\n        int high = arr.length - 1;\n        while (mid <= high) {\n            if (arr[mid] == 0) {\n                int temp = arr[low];\n                arr[low] = arr[mid];\n                arr[mid] = temp;\n                low++;\n                mid++;\n            } else if (arr[mid] == 1) {\n                mid++;\n            } else { // arr[mid] == 2\n                int temp = arr[mid];\n                arr[mid] = arr[high];\n                arr[high] = temp;\n                high--;\n            }\n        }\n    }\n}''t advance mid — swapped value needs checking\n    //             arr[mid], arr[high] = arr[high], arr[mid]\n    //             high -= 1\n    // \n    // \n    // # ─── Test Cases ───\n    // arr1 = [1, 0, 2, 1, 0]\n    // dutch_flag_sort(arr1)\n    // # Expected: [0, 0, 1, 1, 2]\n    // \n    // arr2 = [2, 2, 0, 1, 2, 0]\n    // dutch_flag_sort(arr2)\n    // # Expected: [0, 0, 1, 2, 2, 2]\n    // \n    // arr3 = [0, 0, 1, 1, 2, 2]\n    // dutch_flag_sort(arr3)\n    // # Expected: [0, 0, 1, 1, 2, 2]\n    // \n    // arr4 = [1, 1, 1]\n    // dutch_flag_sort(arr4)\n    // # Expected: [1, 1, 1]\n    // \n}',
  E'/**\n * @param {any} arr\n * @return {any}\n */\nfunction dutchFlagSort(arr) {\n    // Your code here\n}',
  E'function dutchFlagSort(arr) {\n    let low = 0;\n    let mid = 0;\n    let high = arr.length - 1;\n    while (mid <= high) {\n        if (arr[mid] === 0) {\n            [arr[low], arr[mid]] = [arr[mid], arr[low]]; // Swap\n            low++;\n            mid++;\n        } else if (arr[mid] === 1) {\n            mid++;\n        } else { // arr[mid] === 2\n            [arr[mid], arr[high]] = [arr[high], arr[mid]]; // Swap\n            high--;\n        }\n    }\n}',
  ARRAY['two-pointers'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'apple-ict3', 'linkedin-swe'],
  'two-pointers',
  '[]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
  description = EXCLUDED.description,
  constraints = EXCLUDED.constraints,
  examples = EXCLUDED.examples,
  function_name = EXCLUDED.function_name,
  starter_code_python = EXCLUDED.starter_code_python,
  solution_code_python = EXCLUDED.solution_code_python,
  starter_code_java = EXCLUDED.starter_code_java,
  solution_code_java = EXCLUDED.solution_code_java,
  starter_code_js = EXCLUDED.starter_code_js,
  solution_code_js = EXCLUDED.solution_code_js,
