INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-linked-list-cycle',
  'Linked List Cycle Detection',
  'medium',
  'Linked List Cycle Detection

<!-- voice:section_check concept="Floyd''s cycle detection" -->

Problem Statement

Given the head of a linked list, determine if the linked list has a **cycle** in it. A cycle exists if some node can be reached again by continuously following the `next` pointer.

Examples

~~~
Input:  head = [3, 2, 0, -4], pos = 1 (cycle back to index 1)
Output: True
~~~

~~~
Input:  head = [1, 2], pos = 0 (cycle back to index 0)
Output: True
~~~

~~~
Input:  head = [1], pos = -1 (no cycle)
Output: False
~~~',
  '',
  '[{"input":"head = [3, 2, 0, -4], pos = 1 (cycle back to index 1)","output":"True"}]'::jsonb,
  'has_cycle',
  E'class ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef has_cycle(head):\n    """\n    Detect if a linked list has a cycle using Floyd''s algorithm.\n\n    Args:\n        head: ListNode, the head of the linked list\n    Returns:\n        bool: True if there''s a cycle, False otherwise\n    Example:\n        # 1 -> 2 -> 3 -> 2 (cycle)\n        # has_cycle(head) returns True\n    """\n    # TODO: Use fast and slow pointers\n    # Hint: Slow moves 1 step, fast moves 2 steps. If they meet, there''s a cycle.\n    pass\n# ─── Test Cases ───\n# Create list: 1 -> 2 -> 3 -> 4 -> 2 (cycle back to node 2)\nnode1 = ListNode(1)\nnode2 = ListNode(2)\nnode3 = ListNode(3)\nnode4 = ListNode(4)\nnode1.next = node2\nnode2.next = node3\nnode3.next = node4\nnode4.next = node2  # Creates cycle\n# Expected: True\n# No cycle: 1 -> 2 -> 3 -> None\nnode_a = ListNode(1)\nnode_b = ListNode(2)\nnode_c = ListNode(3)\nnode_a.next = node_b\nnode_b.next = node_c\n# Expected: False\n# Single node, no cycle\nsingle = ListNode(1)\n# Expected: False\n# Single node with self-cycle\nself_cycle = ListNode(1)\nself_cycle.next = self_cycle\n# Expected: True',
  E'class ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef has_cycle(head):\n    """\n    Detect if a linked list has a cycle using Floyd''s algorithm.\n\n    Time Complexity: O(n) — fast pointer visits at most n nodes\n    Space Complexity: O(1) — only two pointers used\n    """\n    if not head or not head.next:\n        return False\n    slow = head\n    fast = head.next  # Start fast one step ahead\n    while fast and fast.next:\n        if slow == fast:\n            return True  # Pointers met, cycle exists\n        slow = slow.next        # Move 1 step\n        fast = fast.next.next   # Move 2 steps\n    return False  # Fast reached end, no cycle\n# ─── Test Cases ───\nnode1 = ListNode(1)\nnode2 = ListNode(2)\nnode3 = ListNode(3)\nnode4 = ListNode(4)\nnode1.next = node2\nnode2.next = node3\nnode3.next = node4\nnode4.next = node2\n# Expected: True\nnode_a = ListNode(1)\nnode_b = ListNode(2)\nnode_c = ListNode(3)\nnode_a.next = node_b\nnode_b.next = node_c\n# Expected: False\nsingle = ListNode(1)\n# Expected: False\nself_cycle = ListNode(1)\nself_cycle.next = self_cycle\n# Expected: True',
  E'class Solution {\n    public Object hasCycle(Object val, Object next) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Definition for singly-linked list.\n    public static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int x) {\n            val = x;\n            next = null;\n        }\n    }\n\n    public static boolean hasCycle(ListNode head) {\n        if (head == null || head.next == null) {\n            return false;\n        }\n        ListNode slow = head;\n        ListNode fast = head;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) {\n                return true;\n            }\n        }\n        return false;\n    }\n}''s algorithm.\n    //     \n    //     Time Complexity: O(n) — fast pointer visits at most n nodes\n    //     Space Complexity: O(1) — only two pointers used\n    //     """\n    //     if not head or not head.next:\n    //         return False\n    //     \n    //     slow = head\n    //     fast = head.next  # Start fast one step ahead\n    //     \n    //     while fast and fast.next:\n    //         if slow == fast:\n    //             return True  # Pointers met, cycle exists\n    //         slow = slow.next        # Move 1 step\n    //         fast = fast.next.next   # Move 2 steps\n    //     \n    //     return False  # Fast reached end, no cycle\n    // \n    // \n    // # ─── Test Cases ───\n    // node1 = ListNode(1)\n    // node2 = ListNode(2)\n    // node3 = ListNode(3)\n    // node4 = ListNode(4)\n    // node1.next = node2\n    // node2.next = node3\n    // node3.next = node4\n    // node4.next = node2\n    // # Expected: True\n    // \n    // node_a = ListNode(1)\n    // node_b = ListNode(2)\n    // node_c = ListNode(3)\n    // node_a.next = node_b\n    // node_b.next = node_c\n    // # Expected: False\n    // \n    // single = ListNode(1)\n    // # Expected: False\n    // \n    // self_cycle = ListNode(1)\n    // self_cycle.next = self_cycle\n    // # Expected: True\n    // \n}',
  E'/**\n * @param {any, any} val, next\n * @return {any}\n */\nfunction hasCycle(val, next) {\n    // Your code here\n}',
  E'// Definition for singly-linked list.\nfunction ListNode(val, next) {\n    this.val = (val === undefined ? 0 : val);\n    this.next = (next === undefined ? null : next);\n}\n\nfunction hasCycle(head) {\n    if (!head || !head.next) {\n        return false;\n    }\n    let slow = head;\n    let fast = head;\n    while (fast && fast.next) {\n        slow = slow.next;\n        fast = fast.next.next;\n        if (slow === fast) {\n            return true;\n        }\n    }\n    return false;\n}',
  ARRAY['fast-slow-pointers'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2'],
