INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-find-middle-linked-list',
  'Middle of Linked List',
  'medium',
  'Find the Middle of a Linked List

<!-- voice:section_check concept="finding middle with fast/slow" -->

Problem Statement

Given the head of a singly linked list, return the **middle node**. If there are two middle nodes, return the **second middle node**.

Examples

~~~
Input:  [1, 2, 3, 4, 5]
Output: Node with value 3
~~~

~~~
Input:  [1, 2, 3, 4, 5, 6]
Output: Node with value 4 (second middle)
~~~',
  '',
  '[{"input":"[1, 2, 3, 4, 5]","output":"Node with value 3"}]'::jsonb,
  'find_middle',
  E'class ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef find_middle(head):\n    """\n    Find the middle node of a linked list.\n    If two middle nodes, return the second one.\n\n    Args:\n        head: ListNode, the head of the linked list\n    Returns:\n        ListNode: The middle node\n    Example:\n        # 1 -> 2 -> 3 -> 4 -> 5\n        # find_middle(head).val returns 3\n    """\n    # TODO: Use fast and slow pointers\n    # Hint: When fast reaches end, slow is at middle\n    pass\n# ─── Test Cases ───\n# Odd length: 1 -> 2 -> 3 -> 4 -> 5, middle is 3\nn1 = ListNode(1)\nn2 = ListNode(2)\nn3 = ListNode(3)\nn4 = ListNode(4)\nn5 = ListNode(5)\nn1.next = n2\nn2.next = n3\nn3.next = n4\nn4.next = n5\n# Expected: 3\n# Even length: 1 -> 2 -> 3 -> 4, middle is 3 (second)\na1 = ListNode(1)\na2 = ListNode(2)\na3 = ListNode(3)\na4 = ListNode(4)\na1.next = a2\na2.next = a3\na3.next = a4\n# Expected: 3\n# Single node\nsingle = ListNode(42)\n# Expected: 42\n# Two nodes\ntwo1 = ListNode(1)\ntwo2 = ListNode(2)\ntwo1.next = two2\n# Expected: 2',
  E'class ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef find_middle(head):\n    """\n    Find the middle node of a linked list.\n    If two middle nodes, return the second one.\n\n    Time Complexity: O(n) — single pass\n    Space Complexity: O(1) — two pointers\n    """\n    slow = fast = head\n    # Fast moves 2x, slow moves 1x\n    # When fast reaches end, slow is at middle\n    while fast and fast.next:\n        slow = slow.next        # 1 step\n        fast = fast.next.next   # 2 steps\n    return slow\n# ─── Test Cases ───\nn1 = ListNode(1)\nn2 = ListNode(2)\nn3 = ListNode(3)\nn4 = ListNode(4)\nn5 = ListNode(5)\nn1.next = n2\nn2.next = n3\nn3.next = n4\nn4.next = n5\n# Expected: 3\na1 = ListNode(1)\na2 = ListNode(2)\na3 = ListNode(3)\na4 = ListNode(4)\na1.next = a2\na2.next = a3\na3.next = a4\n# Expected: 3\nsingle = ListNode(42)\n# Expected: 42\ntwo1 = ListNode(1)\ntwo2 = ListNode(2)\ntwo1.next = two2\n# Expected: 2',
  E'class Solution {\n    public Object findMiddle(Object val, Object next) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Definition for singly-linked list.\n    public static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int x) {\n            val = x;\n            next = null;\n        }\n    }\n\n    public static ListNode findMiddle(ListNode head) {\n        ListNode slow = head;\n        ListNode fast = head;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        return slow;\n    }\n}',
  E'/**\n * @param {any, any} val, next\n * @return {any}\n */\nfunction findMiddle(val, next) {\n    // Your code here\n}',
  E'// Definition for singly-linked list.\nfunction ListNode(val, next) {\n    this.val = (val === undefined ? 0 : val);\n    this.next = (next === undefined ? null : next);\n}\n\nfunction findMiddle(head) {\n    let slow = head;\n    let fast = head;\n    while (fast && fast.next) {\n        slow = slow.next;\n        fast = fast.next.next;\n    }\n    return slow;\n}',
  ARRAY['fast-slow-pointers'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2'],
  'fast-slow-pointers',
  '[]'::jsonb,
  '[]'::jsonb
