INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-happy-number',
  'Happy Number',
  'hard',
  'Happy Number

<!-- voice:section_check concept="cycle detection in numbers" -->

Problem Statement

Write an algorithm to determine if a number is **happy**. A happy number is defined by the following process:
- Starting with any positive integer, replace the number by the sum of the squares of its digits.
- Repeat the process until the number equals 1 (happy) or loops endlessly in a cycle (not happy).

Examples

~~~
Input:  n = 19
Output: True
Explanation: 
1² + 9² = 82
8² + 2² = 68
6² + 8² = 100
1² + 0² + 0² = 1
~~~

~~~
Input:  n = 2
Output: False
Explanation: Enters cycle 4 → 16 → 37 → 58 → 89 → 145 → 42 → 20 → 4
~~~',
  '',
  '[{"input":"n = 19","output":"True","explanation":"1² + 9² = 82"}]'::jsonb,
  'is_happy',
  E'def is_happy(n):\n    """\n    Determine if a number is happy.\n\n    A happy number eventually reaches 1 when replacing it with\n    sum of squares of its digits. Unhappy numbers enter a cycle.\n    Args:\n        n: Positive integer\n    Returns:\n        bool: True if happy number, False otherwise\n    Example:\n        >>> is_happy(19)\n        True\n        >>> is_happy(2)\n        False\n    """\n    # TODO: Use fast/slow pointers on number transformation\n    # Hint: Detect if we reach 1 (happy) or enter a cycle (unhappy)\n    pass\ndef get_next_number(n):\n    """Helper: Calculate sum of squares of digits."""\n    # TODO: Implement sum of squares of digits\n    pass\n\n# ─── Test Cases ───\n# Expected: True (19 → 82 → 68 → 100 → 1)\n# Expected: False (enters cycle)\n# Expected: True (7 → 49 → 97 → 130 → 10 → 1)\n# Expected: True\n# Expected: False (part of unhappy cycle)',
  E'def is_happy(n):\n    """\n    Determine if a number is happy.\n\n    Time Complexity: O(log n) — number of digits in n\n    Space Complexity: O(1) — only pointers used\n    """\n    def get_next(num):\n        """Calculate sum of squares of digits."""\n        total = 0\n        while num > 0:\n            digit = num % 10\n            total += digit * digit\n            num //= 10\n        return total\n\n    slow = n\n    fast = get_next(n)\n    # Fast moves 2 steps, slow moves 1 step\n    while fast != 1 and slow != fast:\n        slow = get_next(slow)           # 1 step\n        fast = get_next(get_next(fast)) # 2 steps\n    return fast == 1\n# ─── Test Cases ───\n# Expected: True\n# Expected: False\n# Expected: True\n# Expected: True\n# Expected: False',
  E'class Solution {\n    public Object isHappy(int n) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports: java.util.* (not strictly needed for this problem, but good practice for general use)\n\n    public static boolean isHappy(int n) {\n        int slow = n;\n        int fast = getNext(n);\n        // Fast moves 2 steps, slow moves 1 step\n        while (fast != 1 && slow != fast) {\n            slow = getNext(slow);           // 1 step\n            fast = getNext(getNext(fast)); // 2 steps\n        }\n        return fast == 1;\n    }\n\n    /**\n     * Calculate sum of squares of digits.\n     */\n    private static int getNext(int num) {\n        int total = 0;\n        while (num > 0) {\n            int digit = num % 10;\n            total += digit * digit;\n            num /= 10; // Integer division\n        }\n        return total;\n    }\n}',
  E'/**\n * @param {any} n\n * @return {any}\n */\nfunction isHappy(n) {\n    // Your code here\n}',
  E'function isHappy(n) {\n    /**\n     * Calculate sum of squares of digits.\n     */\n    function getNext(num) {\n        let total = 0;\n        while (num > 0) {\n            const digit = num % 10;\n            total += digit * digit;\n            num = Math.floor(num / 10);\n        }\n        return total;\n    }\n\n    let slow = n;\n    let fast = getNext(n);\n    // Fast moves 2 steps, slow moves 1 step\n    while (fast !== 1 && slow !== fast) {\n        slow = getNext(slow);           // 1 step\n        fast = getNext(getNext(fast)); // 2 steps\n    }\n    return fast === 1;\n}',
  ARRAY['fast-slow-pointers'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2'],
  'fast-slow-pointers',
  '[{"input":"is_happy(19)","expected_output":"True (19 → 82 → 68 → 100 → 1)"},{"input":"is_happy(2)","expected_output":"False (enters cycle)"},{"input":"is_happy(7)","expected_output":"True (7 → 49 → 97 → 130 → 10 → 1)"}]'::jsonb,
  '[{"input":"is_happy(1)","expected_output":"True"},{"input":"is_happy(4)","expected_output":"False (part of unhappy cycle)"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
