INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-max-sum-subarray-size-k',
  'Maximum Sum Subarray of Size K',
  'medium',
  'Maximum Sum Subarray of Size K

<!-- voice:section_check concept="fixed-size sliding window" -->

Problem Statement

Given an array of integers and a number k, find the **maximum sum** of any contiguous subarray of size k.

Examples

~~~
Input:  [2, 1, 5, 1, 3, 2], k = 3
Output: 9
Explanation: Subarray [5, 1, 3] has maximum sum 9
~~~

~~~
Input:  [2, 3, 4, 1, 5], k = 2
Output: 7
Explanation: Subarray [3, 4] has maximum sum 7
~~~',
  '',
  '[{"input":"[2, 1, 5, 1, 3, 2], k = 3","output":"9","explanation":"Subarray [5, 1, 3] has maximum sum 9"}]'::jsonb,
  'max_sum_subarray',
  E'def max_sum_subarray(arr, k):\n    """\n    Find maximum sum of any contiguous subarray of size k.\n\n    Args:\n        arr: List of integers\n        k: Size of subarray\n    Returns:\n        int: Maximum sum of any k-length subarray\n    Example:\n        >>> max_sum_subarray([2, 1, 5, 1, 3, 2], 3)\n        9\n    """\n    # TODO: Use sliding window of fixed size k\n    # Hint: Calculate first window sum, then slide and update\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: 9\n# Different array\n# Expected: 7\n# Single element windows\n# Expected: 10\n# Entire array as window\n# Expected: 10\n# Negative numbers included\n# Expected: 6',
  E'def max_sum_subarray(arr, k):\n    """\n    Find maximum sum of any contiguous subarray of size k.\n\n    Time Complexity: O(n) — single pass\n    Space Complexity: O(1) — only tracking sums\n    """\n    if k > len(arr) or k <= 0:\n        return 0\n    # Calculate sum of first window\n    window_sum = sum(arr[:k])\n    max_sum = window_sum\n    # Slide window: remove leftmost, add new right element\n    for i in range(k, len(arr)):\n        window_sum = window_sum - arr[i - k] + arr[i]\n        max_sum = max(max_sum, window_sum)\n    return max_sum\n# ─── Test Cases ───\n# Expected: 9\n# Expected: 7\n# Expected: 10\n# Expected: 10\n# Expected: 6',
  E'class Solution {\n    public Object maxSumSubarray(int[] arr, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int maxSumSubarray(int[] arr, int k) {\n        if (k > arr.length || k <= 0) {\n            return 0;\n        }\n\n        // Calculate sum of first window\n        int windowSum = 0;\n        for (int i = 0; i < k; i++) {\n            windowSum += arr[i];\n        }\n\n        int maxSum = windowSum;\n\n        // Slide window: remove leftmost, add new right element\n        for (int i = k; i < arr.length; i++) {\n            windowSum = windowSum - arr[i - k] + arr[i];\n            maxSum = Math.max(maxSum, windowSum);\n        }\n\n        return maxSum;\n    }\n}',
  E'/**\n * @param {any, any} arr, k\n * @return {any}\n */\nfunction maxSumSubarray(arr, k) {\n    // Your code here\n}',
  E'function maxSumSubarray(arr, k) {\n    if (k > arr.length || k <= 0) {\n        return 0;\n    }\n\n    // Calculate sum of first window\n    let windowSum = 0;\n    for (let i = 0; i < k; i++) {\n        windowSum += arr[i];\n    }\n\n    let maxSum = windowSum;\n\n    // Slide window: remove leftmost, add new right element\n    for (let i = k; i < arr.length; i++) {\n        windowSum = windowSum - arr[i - k] + arr[i];\n        maxSum = Math.max(maxSum, windowSum);\n    }\n\n    return maxSum;\n}',
  ARRAY['sliding-window'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2', 'databricks-swe'],
  'sliding-window',
  '[{"input":"max_sum_subarray([2, 1, 5, 1, 3, 2], 3)","expected_output":"9"},{"input":"max_sum_subarray([2, 3, 4, 1, 5], 2)","expected_output":"7"},{"input":"max_sum_subarray([1, 4, 2, 10], 1)","expected_output":"10"}]'::jsonb,
  '[{"input":"max_sum_subarray([1, 2, 3, 4], 4)","expected_output":"10"},{"input":"max_sum_subarray([-1, 2, 3, -2, 5], 3)","expected_output":"6"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
