INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-smallest-subarray-sum',
  'Smallest Subarray with Given Sum',
  'medium',
  'Smallest Subarray with a Given Sum

<!-- voice:section_check concept="dynamic-size sliding window" -->

Problem Statement

Given an array of positive integers and a target sum S, find the **length** of the smallest contiguous subarray whose sum is greater than or equal to S. Return 0 if no such subarray exists.

Examples

~~~
Input:  [2, 1, 5, 2, 3, 2], S = 7
Output: 2
Explanation: Subarray [5, 2] has sum 7 and length 2
~~~

~~~
Input:  [2, 1, 5, 2, 8], S = 7
Output: 1
Explanation: Single element [8] has sum ≥ 7
~~~',
  '',
  '[{"input":"[2, 1, 5, 2, 3, 2], S = 7","output":"2","explanation":"Subarray [5, 2] has sum 7 and length 2"}]'::jsonb,
  'smallest_subarray_with_sum',
  E'def smallest_subarray_with_sum(arr, s):\n    """\n    Find length of smallest subarray with sum >= s.\n\n    Args:\n        arr: List of positive integers\n        s: Target sum\n    Returns:\n        int: Minimum length of subarray with sum >= s, or 0 if none exists\n    Example:\n        >>> smallest_subarray_with_sum([2, 1, 5, 2, 3, 2], 7)\n        2\n    """\n    # TODO: Use dynamic sliding window\n    # Hint: Expand until sum >= s, then shrink to find minimum\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: 2\n# Single element solution\n# Expected: 1\n# Entire array needed\n# Expected: 5\n# No solution possible\n# Expected: 0\n# Single element meets target\n# Expected: 1',
  E'def smallest_subarray_with_sum(arr, s):\n    """\n    Find length of smallest subarray with sum >= s.\n\n    Time Complexity: O(n) — each element visited at most twice\n    Space Complexity: O(1) — only tracking window state\n    """\n    min_length = float(''inf'')\n    window_sum = 0\n    window_start = 0\n    for window_end in range(len(arr)):\n        # Expand window by adding current element\n        window_sum += arr[window_end]\n        # Shrink window while condition is satisfied\n        while window_sum >= s:\n            min_length = min(min_length, window_end - window_start + 1)\n            window_sum -= arr[window_start]\n            window_start += 1\n    return min_length if min_length != float(''inf'') else 0\n# ─── Test Cases ───\n# Expected: 2\n# Expected: 1\n# Expected: 5\n# Expected: 0\n# Expected: 1',
  E'class Solution {\n    public Object smallestSubarrayWithSum(int[] arr, String s) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int smallestSubarrayWithSum(int[] arr, int s) {\n        int minLength = Integer.MAX_VALUE;\n        int windowSum = 0;\n        int windowStart = 0;\n\n        for (int windowEnd = 0; windowEnd < arr.length; windowEnd++) {\n            windowSum += arr[windowEnd]; // Add the next element to the window\n            // Shrink the window as long as the window_sum is greater than or equal to \'s\'\n            while (windowSum >= s) {\n                minLength = Math.min(minLength, windowEnd - windowStart + 1);\n                windowSum -= arr[windowStart]; // Subtract the element going out\n                windowStart++;                 // Slide the window ahead\n            }\n        }\n\n        return minLength == Integer.MAX_VALUE ? 0 : minLength;\n    }\n}''inf'')\n    //     window_sum = 0\n    //     window_start = 0\n    //     \n    //     for window_end in range(len(arr)):\n    //         # Expand window by adding current element\n    //         window_sum += arr[window_end]\n    //         \n    //         # Shrink window while condition is satisfied\n    //         while window_sum >= s:\n    //             min_length = min(min_length, window_end - window_start + 1)\n    //             window_sum -= arr[window_start]\n    //             window_start += 1\n    //     \n    //     return min_length if min_length != float(''inf'') else 0\n    // \n    // \n    // # ─── Test Cases ───\n    // # Expected: 2\n    // \n    // # Expected: 1\n    // \n    // # Expected: 5\n    // \n    // # Expected: 0\n    // \n    // # Expected: 1\n    // \n}',
  E'/**\n * @param {any, any} arr, s\n * @return {any}\n */\nfunction smallestSubarrayWithSum(arr, s) {\n    // Your code here\n}',
  E'function smallestSubarrayWithSum(arr, s) {\n    let minLength = Infinity;\n    let windowSum = 0;\n    let windowStart = 0;\n\n    for (let windowEnd = 0; windowEnd < arr.length; windowEnd++) {\n        windowSum += arr[windowEnd]; // Add the next element to the window\n        // Shrink the window as long as the window_sum is greater than or equal to \'s\'\n        while (windowSum >= s) {\n            minLength = Math.min(minLength, windowEnd - windowStart + 1);\n            windowSum -= arr[windowStart]; // Subtract the element going out\n            windowStart++;                 // Slide the window ahead\n        }\n    }\n\n    return minLength === Infinity ? 0 : minLength;\n}',
  ARRAY['sliding-window'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2', 'databricks-swe'],
  'sliding-window',
  '[{"input":"smallest_subarray_with_sum([2, 1, 5, 2, 3, 2], 7)","expected_output":"2"},{"input":"smallest_subarray_with_sum([2, 1, 5, 2, 8], 7)","expected_output":"1"},{"input":"smallest_subarray_with_sum([1, 2, 3, 4, 5], 15)","expected_output":"5"}]'::jsonb,
  '[{"input":"smallest_subarray_with_sum([1, 2, 3], 10)","expected_output":"0"},{"input":"smallest_subarray_with_sum([5], 5)","expected_output":"1"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
