INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-longest-substring-k-distinct',
  'Longest Substring with K Distinct Characters',
  'medium',
  'Longest Substring with K Distinct Characters

<!-- voice:section_check concept="hash map with sliding window" -->

Problem Statement

Given a string, find the **length** of the longest substring containing **no more than K distinct characters**.

Examples

~~~
Input:  String = "araaci", K = 2
Output: 4
Explanation: "araa" has 2 distinct characters (a, r) and length 4
~~~

~~~
Input:  String = "araaci", K = 1
Output: 2
Explanation: "aa" is the longest substring with 1 distinct character
~~~',
  '',
  '[{"input":"String = \"araaci\", K = 2","output":"4","explanation":"\"araa\" has 2 distinct characters (a, r) and length 4"}]'::jsonb,
  'longest_substring_k_distinct',
  E'def longest_substring_k_distinct(s, k):\n    """\n    Find length of longest substring with at most k distinct characters.\n\n    Args:\n        s: Input string\n        k: Maximum number of distinct characters allowed\n    Returns:\n        int: Length of longest valid substring\n    Example:\n        >>> longest_substring_k_distinct("araaci", 2)\n        4\n    """\n    # TODO: Use sliding window with hash map for character counts\n    # Hint: Track character frequencies, shrink when distinct count > k\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: 4\n# K = 1\n# Expected: 2\n# Longer string\n# Expected: 5 ("cbbeb" or "bbebi")\n# K >= distinct chars in string\n# Expected: 3\n# Empty string\n# Expected: 0',
  E'def longest_substring_k_distinct(s, k):\n    """\n    Find length of longest substring with at most k distinct characters.\n\n    Time Complexity: O(n) — each character visited at most twice\n    Space Complexity: O(k) — hash map holds at most k+1 characters\n    """\n    if k == 0 or not s:\n        return 0\n    char_frequency = {}\n    max_length = 0\n    window_start = 0\n    for window_end in range(len(s)):\n        # Add current character to frequency map\n        right_char = s[window_end]\n        char_frequency[right_char] = char_frequency.get(right_char, 0) + 1\n        # Shrink window while we have more than k distinct characters\n        while len(char_frequency) > k:\n            left_char = s[window_start]\n            char_frequency[left_char] -= 1\n            if char_frequency[left_char] == 0:\n                del char_frequency[left_char]\n            window_start += 1\n        # Update max length\n        max_length = max(max_length, window_end - window_start + 1)\n    return max_length\n# ─── Test Cases ───\n# Expected: 4\n# Expected: 2\n# Expected: 5\n# Expected: 3\n# Expected: 0',
  E'class Solution {\n    public Object longestSubstringKDistinct(String s, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports: java.util.HashMap; java.util.Map;\n    public static int longestSubstringKDistinct(String s, int k) {\n        if (k == 0 || s == null || s.isEmpty()) {\n            return 0;\n        }\n\n        Map<Character, Integer> charFrequency = new HashMap<>();\n        int maxLength = 0;\n        int windowStart = 0;\n\n        for (int windowEnd = 0; windowEnd < s.length(); windowEnd++) {\n            char rightChar = s.charAt(windowEnd);\n            charFrequency.put(rightChar, charFrequency.getOrDefault(rightChar, 0) + 1);\n\n            // Shrink window while we have more than k distinct characters\n            while (charFrequency.size() > k) {\n                char leftChar = s.charAt(windowStart);\n                charFrequency.put(leftChar, charFrequency.get(leftChar) - 1);\n                if (charFrequency.get(leftChar) == 0) {\n                    charFrequency.remove(leftChar);\n                }\n                windowStart++;\n            }\n            // Update max length\n            maxLength = Math.max(maxLength, windowEnd - windowStart + 1);\n        }\n        return maxLength;\n    }\n}',
  E'/**\n * @param {any, any} s, k\n * @return {any}\n */\nfunction longestSubstringKDistinct(s, k) {\n    // Your code here\n}',
  E'function longestSubstringKDistinct(s, k) {\n    if (k === 0 || !s) {\n        return 0;\n    }\n\n    const charFrequency = new Map();\n    let maxLength = 0;\n    let windowStart = 0;\n\n    for (let windowEnd = 0; windowEnd < s.length; windowEnd++) {\n        const rightChar = s[windowEnd];\n        charFrequency.set(rightChar, (charFrequency.get(rightChar) || 0) + 1);\n\n        // Shrink window while we have more than k distinct characters\n        while (charFrequency.size > k) {\n            const leftChar = s[windowStart];\n            charFrequency.set(leftChar, charFrequency.get(leftChar) - 1);\n            if (charFrequency.get(leftChar) === 0) {\n                charFrequency.delete(leftChar);\n            }\n            windowStart++;\n        }\n        // Update max length\n        maxLength = Math.max(maxLength, windowEnd - windowStart + 1);\n    }\n    return maxLength;\n}',
  ARRAY['sliding-window'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2', 'databricks-swe'],
  'sliding-window',
  '[{"input":"longest_substring_k_distinct(\"araaci\", 2)","expected_output":"4"},{"input":"longest_substring_k_distinct(\"araaci\", 1)","expected_output":"2"},{"input":"longest_substring_k_distinct(\"cbbebi\", 3)","expected_output":"5 (\"cbbeb\" or \"bbebi\")"}]'::jsonb,
  '[{"input":"longest_substring_k_distinct(\"abc\", 5)","expected_output":"3"},{"input":"longest_substring_k_distinct(\"\", 2)","expected_output":"0"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
