INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-fruits-into-baskets',
  'Fruits Into Baskets',
  'hard',
  'Fruits Into Baskets (Longest Subarray with 2 Distinct)

<!-- voice:section_check concept="practical application of sliding window" -->

Problem Statement

You are visiting a farm with a single row of fruit trees. Each tree produces a type of fruit. You have **two baskets**, and each basket can only hold **one type of fruit**. Starting from any tree, pick exactly one fruit from every tree while moving to the right, until you cannot pick more.

Find the **maximum number of fruits** you can pick.

Examples

~~~
Input:  Fruit = [''A'', ''B'', ''C'', ''A'', ''C'']
Output: 3
Explanation: Pick [''C'', ''A'', ''C''] — two types (A and C), length 3
~~~

~~~
Input:  Fruit = [''A'', ''B'', ''C'', ''B'', ''B'', ''C'']
Output: 5
Explanation: Pick [''B'', ''C'', ''B'', ''B'', ''C''] — two types (B and C), length 5
~~~',
  '',
  '[{"input":"Fruit = [''A'', ''B'', ''C'', ''A'', ''C'']","output":"3","explanation":"Pick [''C'', ''A'', ''C''] — two types (A and C), length 3"}]'::jsonb,
  'max_fruits_in_baskets',
  E'def max_fruits_in_baskets(fruits):\n    """\n    Find maximum number of fruits that can be collected with 2 baskets.\n    Each basket holds one type of fruit.\n\n    Args:\n        fruits: List of characters representing fruit types\n    Returns:\n        int: Maximum fruits that can be collected\n    Example:\n        >>> max_fruits_in_baskets([''A'', ''B'', ''C'', ''A'', ''C''])\n        3\n    """\n    # TODO: Find longest subarray with at most 2 distinct elements\n    # Hint: Same pattern as longest substring with k distinct, where k=2\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: 3\n# Better collection possible\n# Expected: 5\n# All same type\n# Expected: 4\n# Two types throughout\n# Expected: 5\n# Single tree\n# Expected: 1',
  E'def max_fruits_in_baskets(fruits):\n    """\n    Find maximum number of fruits that can be collected with 2 baskets.\n    Each basket holds one type of fruit.\n\n    Time Complexity: O(n) — single pass\n    Space Complexity: O(1) — at most 3 types tracked\n    """\n    basket = {}  # fruit_type -> count\n    max_fruits = 0\n    window_start = 0\n    for window_end in range(len(fruits)):\n        # Add current fruit to basket\n        fruit = fruits[window_end]\n        basket[fruit] = basket.get(fruit, 0) + 1\n        # Shrink while we have more than 2 types\n        while len(basket) > 2:\n            left_fruit = fruits[window_start]\n            basket[left_fruit] -= 1\n            if basket[left_fruit] == 0:\n                del basket[left_fruit]\n            window_start += 1\n        # Update max\n        max_fruits = max(max_fruits, window_end - window_start + 1)\n    return max_fruits\n# ─── Test Cases ───\n# Expected: 3\n# Expected: 5\n# Expected: 4\n# Expected: 5\n# Expected: 1',
  E'class Solution {\n    public Object maxFruitsInBaskets(Object fruits) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports: java.util.HashMap; java.util.Map;\n    public static int maxFruitsInBaskets(char[] fruits) {\n        // k is implicitly 2 for this problem (two baskets)\n        if (fruits == null || fruits.length == 0) {\n            return 0;\n        }\n\n        Map<Character, Integer> basket = new HashMap<>(); // fruit_type -> count\n        int maxFruits = 0;\n        int windowStart = 0;\n\n        for (int windowEnd = 0; windowEnd < fruits.length; windowEnd++) {\n            char fruit = fruits[windowEnd];\n            basket.put(fruit, basket.getOrDefault(fruit, 0) + 1);\n\n            // Shrink while we have more than 2 types\n            while (basket.size() > 2) {\n                char leftFruit = fruits[windowStart];\n                basket.put(leftFruit, basket.get(leftFruit) - 1);\n                if (basket.get(leftFruit) == 0) {\n                    basket.remove(leftFruit);\n                }\n                windowStart++;\n            }\n            // Update max\n            maxFruits = Math.max(maxFruits, windowEnd - windowStart + 1);\n        }\n        return maxFruits;\n    }\n}',
  E'/**\n * @param {any} fruits\n * @return {any}\n */\nfunction maxFruitsInBaskets(fruits) {\n    // Your code here\n}',
  E'function maxFruitsInBaskets(fruits) {\n    // k is implicitly 2 for this problem (two baskets)\n    if (!fruits || fruits.length === 0) {\n        return 0;\n    }\n\n    const basket = new Map(); // fruit_type -> count\n    let maxFruits = 0;\n    let windowStart = 0;\n\n    for (let windowEnd = 0; windowEnd < fruits.length; windowEnd++) {\n        const fruit = fruits[windowEnd];\n        basket.set(fruit, (basket.get(fruit) || 0) + 1);\n\n        // Shrink while we have more than 2 types\n        while (basket.size > 2) {\n            const leftFruit = fruits[windowStart];\n            basket.set(leftFruit, basket.get(leftFruit) - 1);\n            if (basket.get(leftFruit) === 0) {\n                basket.delete(leftFruit);\n            }\n            windowStart++;\n        }\n        // Update max\n        maxFruits = Math.max(maxFruits, windowEnd - windowStart + 1);\n    }\n    return maxFruits;\n}',
  ARRAY['sliding-window'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2', 'databricks-swe'],
  'sliding-window',
  '[{"input":"max_fruits_in_baskets([''A'', ''B'', ''C'', ''A'', ''C''])","expected_output":"3"},{"input":"max_fruits_in_baskets([''A'', ''B'', ''C'', ''B'', ''B'', ''C''])","expected_output":"5"},{"input":"max_fruits_in_baskets([''A'', ''A'', ''A'', ''A''])","expected_output":"4"}]'::jsonb,
  '[{"input":"max_fruits_in_baskets([''A'', ''B'', ''A'', ''B'', ''A''])","expected_output":"5"},{"input":"max_fruits_in_baskets([''A''])","expected_output":"1"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
