INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-merge-overlapping-intervals',
  'Merge Overlapping Intervals',
  'medium',
  'Merge Overlapping Intervals

<!-- voice:section_check concept="merging overlapping intervals" -->

Problem Statement

Given a collection of intervals, merge all **overlapping intervals** and return the minimal set of non-overlapping intervals.

Examples

~~~
Input:  [[1, 3], [2, 6], [8, 10], [15, 18]]
Output: [[1, 6], [8, 10], [15, 18]]
Explanation: [1, 3] and [2, 6] overlap, merge into [1, 6]
~~~

~~~
Input:  [[1, 4], [4, 5]]
Output: [[1, 5]]
Explanation: Adjacent intervals (touching) are merged
~~~',
  '',
  '[{"input":"[[1, 3], [2, 6], [8, 10], [15, 18]]","output":"[[1, 6], [8, 10], [15, 18]]","explanation":"[1, 3] and [2, 6] overlap, merge into [1, 6]"}]'::jsonb,
  'merge_intervals',
  E'def merge_intervals(intervals):\n    """\n    Merge all overlapping intervals into minimal set.\n\n    Args:\n        intervals: List of [start, end] pairs\n    Returns:\n        List of merged [start, end] pairs\n    Example:\n        >>> merge_intervals([[1, 3], [2, 6], [8, 10]])\n        [[1, 6], [8, 10]]\n    """\n    # TODO: Sort by start time, then merge overlapping intervals\n    # Hint: Track current merged interval, extend when overlapping\n    pass\n# ─── Test Cases ───\n# Standard overlapping\n# Expected: [[1, 6], [8, 10], [15, 18]]\n# Adjacent intervals (touching)\n# Expected: [[1, 5]]\n# No overlap\n# Expected: [[1, 2], [3, 4], [5, 6]]\n# Complete overlap (one inside another)\n# Expected: [[1, 10]]\n# Single interval\n# Expected: [[1, 5]]\n# Empty input\n# Expected: []',
  E'def merge_intervals(intervals):\n    """\n    Merge all overlapping intervals into minimal set.\n\n    Time Complexity: O(n log n) — sorting dominates\n    Space Complexity: O(n) — result storage\n    """\n    if not intervals:\n        return []\n    # Sort by start time\n    intervals.sort(key=lambda x: x[0])\n    merged = [intervals[0]]\n    for current in intervals[1:]:\n        last_merged = merged[-1]\n        # Check if overlapping (current starts before last ends)\n        if current[0] <= last_merged[1]:\n            # Merge by extending the end if needed\n            last_merged[1] = max(last_merged[1], current[1])\n        else:\n            # No overlap, add as new interval\n            merged.append(current)\n    return merged\n# ─── Test Cases ───\n# Expected: [[1, 6], [8, 10], [15, 18]]\n# Expected: [[1, 5]]\n# Expected: [[1, 2], [3, 4], [5, 6]]\n# Expected: [[1, 10]]\n# Expected: [[1, 5]]\n# Expected: []',
  E'class Solution {\n    public Object mergeIntervals(int[] intervals) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports: java.util.ArrayList; java.util.Arrays; java.util.Collections; java.util.Comparator; java.util.List;\n    public static List<int[]> mergeIntervals(int[][] intervals) {\n        if (intervals == null || intervals.length == 0) {\n            return new ArrayList<>();\n        }\n\n        // Sort by start time\n        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));\n\n        List<int[]> merged = new ArrayList<>();\n        merged.add(intervals[0]);\n\n        for (int i = 1; i < intervals.length; i++) {\n            int[] current = intervals[i];\n            int[] lastMerged = merged.get(merged.size() - 1);\n\n            // Check if overlapping (current starts before or at last ends)\n            if (current[0] <= lastMerged[1]) {\n                // Merge by extending the end if needed\n                lastMerged[1] = Math.max(lastMerged[1], current[1]);\n            } else {\n                // No overlap, add as new interval\n                merged.add(current);\n            }\n        }\n        return merged;\n    }\n}',
  E'/**\n * @param {any} intervals\n * @return {any}\n */\nfunction mergeIntervals(intervals) {\n    // Your code here\n}',
  E'function mergeIntervals(intervals) {\n    if (!intervals || intervals.length === 0) {\n        return [];\n    }\n\n    // Sort by start time\n    intervals.sort((a, b) => a[0] - b[0]);\n\n    const merged = [intervals[0]];\n\n    for (let i = 1; i < intervals.length; i++) {\n        const current = intervals[i];\n        const lastMerged = merged[merged.length - 1];\n\n        // Check if overlapping (current starts before or at last ends)\n        if (current[0] <= lastMerged[1]) {\n            // Merge by extending the end if needed\n            lastMerged[1] = Math.max(lastMerged[1], current[1]);\n        } else {\n            // No overlap, add as new interval\n            merged.push(current);\n        }\n    }\n    return merged;\n}',
  ARRAY['merge-intervals'],
