INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-interval-intersection',
  'Interval Intersection',
  'medium',
  'Interval Intersection

<!-- voice:section_check concept="finding common intervals" -->

Problem Statement

Given two lists of closed intervals, each list is pairwise disjoint and sorted. Return the **intersection** of these two interval lists.

Examples

~~~
Input:  first = [[0, 2], [5, 10], [13, 23], [24, 25]]
        second = [[1, 5], [8, 12], [15, 24], [25, 26]]
Output: [[1, 2], [5, 5], [8, 10], [15, 23], [24, 24], [25, 25]]
~~~',
  '',
  '[{"input":"first = [[0, 2], [5, 10], [13, 23], [24, 25]]","output":"[[1, 2], [5, 5], [8, 10], [15, 23], [24, 24], [25, 25]]"}]'::jsonb,
  'interval_intersection',
  E'def interval_intersection(first, second):\n    """\n    Find intersections of two interval lists.\n\n    Args:\n        first: List of [start, end] pairs, sorted and non-overlapping\n        second: List of [start, end] pairs, sorted and non-overlapping\n    Returns:\n        List of intersection intervals\n    Example:\n        >>> interval_intersection([[0, 2], [5, 10]], [[1, 5], [8, 12]])\n        [[1, 2], [5, 5], [8, 10]]\n    """\n    # TODO: Use two pointers to find intersections\n    # Hint: Intersection is [max(starts), min(ends)], advance pointer with smaller end\n    pass\n# ─── Test Cases ───\n# Standard case\nfirst = [[0, 2], [5, 10], [13, 23], [24, 25]]\nsecond = [[1, 5], [8, 12], [15, 24], [25, 26]]\n# Expected: [[1, 2], [5, 5], [8, 10], [15, 23], [24, 24], [25, 25]]\n# No intersection\n# Expected: []\n# Complete overlap\n# Expected: [[2, 5]]\n# Empty lists\n# Expected: []\n# Multiple intersections with same interval\n# Expected: [[2, 3], [5, 10], [15, 20]]',
  E'def interval_intersection(first, second):\n    """\n    Find intersections of two interval lists.\n\n    Time Complexity: O(n + m) — single pass through both lists\n    Space Complexity: O(min(n, m)) — result storage\n    """\n    result = []\n    i = j = 0\n    while i < len(first) and j < len(second):\n        # Find intersection\n        start = max(first[i][0], second[j][0])\n        end = min(first[i][1], second[j][1])\n        # Valid intersection if start <= end\n        if start <= end:\n            result.append([start, end])\n        # Advance pointer with smaller end (can''t intersect with more)\n        if first[i][1] < second[j][1]:\n            i += 1\n        else:\n            j += 1\n    return result\n# ─── Test Cases ───\nfirst = [[0, 2], [5, 10], [13, 23], [24, 25]]\nsecond = [[1, 5], [8, 12], [15, 24], [25, 26]]\n# Expected: [[1, 2], [5, 5], [8, 10], [15, 23], [24, 24], [25, 25]]\n# Expected: []\n# Expected: [[2, 5]]\n# Expected: []\n# Expected: [[2, 3], [5, 10], [15, 20]]',
  E'class Solution {\n    public Object intervalIntersection(Object first, Object second) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports: java.util.ArrayList; java.util.List;\n    public static List<int[]> intervalIntersection(int[][] first, int[][] second) {\n        List<int[]> result = new ArrayList<>();\n        int i = 0;\n        int j = 0;\n\n        while (i < first.length && j < second.length) {\n            // Find intersection\n            int start = Math.max(first[i][0], second[j][0]);\n            int end = Math.min(first[i][1], second[j][1]);\n\n            // Valid intersection if start <= end\n            if (start <= end) {\n                result.add(new int[]{start, end});\n            }\n\n            // Advance pointer with smaller end\n            if (first[i][1] < second[j][1]) {\n                i++;\n            } else {\n                j++;\n            }\n        }\n        return result;\n    }\n}''t intersect with more)\n    //         if first[i][1] < second[j][1]:\n    //             i += 1\n    //         else:\n    //             j += 1\n    //     \n    //     return result\n    // \n    // \n    // # ─── Test Cases ───\n    // first = [[0, 2], [5, 10], [13, 23], [24, 25]]\n    // second = [[1, 5], [8, 12], [15, 24], [25, 26]]\n    // # Expected: [[1, 2], [5, 5], [8, 10], [15, 23], [24, 24], [25, 25]]\n    // \n    // # Expected: []\n    // \n    // # Expected: [[2, 5]]\n    // \n    // # Expected: []\n    // \n    // # Expected: [[2, 3], [5, 10], [15, 20]]\n    // \n}',
  E'/**\n * @param {any, any} first, second\n * @return {any}\n */\nfunction intervalIntersection(first, second) {\n    // Your code here\n}',
  E'function intervalIntersection(first, second) {\n    const result = [];\n    let i = 0;\n    let j = 0;\n\n    while (i < first.length && j < second.length) {\n        // Find intersection\n        const start = Math.max(first[i][0], second[j][0]);\n        const end = Math.min(first[i][1], second[j][1]);\n\n        // Valid intersection if start <= end\n        if (start <= end) {\n            result.push([start, end]);\n        }\n\n        // Advance pointer with smaller end\n        if (first[i][1] < second[j][1]) {\n            i++;\n        } else {\n            j++;\n        }\n    }\n    return result;\n}',
  ARRAY['merge-intervals'],
  ARRAY['google-l4', 'meta-e4', 'uber-sde2', 'airbnb-swe', 'linkedin-swe'],
  'merge-intervals',
  '[{"input":"interval_intersection(first, second)","expected_output":"[[1, 2], [5, 5], [8, 10], [15, 23], [24, 24], [25, 25]]"},{"input":"interval_intersection([[1, 3]], [[4, 6]])","expected_output":"[]"},{"input":"interval_intersection([[1, 10]], [[2, 5]])","expected_output":"[[2, 5]]"}]'::jsonb,
  '[{"input":"interval_intersection([], [[1, 5]])","expected_output":"[]"},{"input":"interval_intersection([[1, 100]], [[2, 3], [5, 10], [15, 20]])","expected_output":"[[2, 3], [5, 10], [15, 20]]"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
