INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-meeting-rooms',
  'Meeting Rooms',
  'hard',
  'Meeting Rooms (Conflict Detection)

<!-- voice:section_check concept="conflict detection" -->

Problem Statement

Given an array of meeting time intervals where intervals[i] = [start, end], determine if a person could **attend all meetings** without conflicts.

Examples

~~~
Input:  [[0, 30], [5, 10], [15, 20]]
Output: False
Explanation: [0, 30] overlaps with both [5, 10] and [15, 20]
~~~

~~~
Input:  [[7, 10], [2, 4]]
Output: True
Explanation: No overlaps
~~~',
  '',
  '[{"input":"[[0, 30], [5, 10], [15, 20]]","output":"False","explanation":"[0, 30] overlaps with both [5, 10] and [15, 20]"}]'::jsonb,
  'can_attend_all_meetings',
  E'def can_attend_all_meetings(intervals):\n    """\n    Determine if a person can attend all meetings without conflicts.\n\n    Args:\n        intervals: List of [start, end] meeting times\n    Returns:\n        bool: True if no conflicts, False otherwise\n    Example:\n        >>> can_attend_all_meetings([[0, 30], [5, 10]])\n        False\n    """\n    # TODO: Sort by start time, check for adjacent overlaps\n    # Hint: After sorting, check if any interval starts before previous ends\n    pass\n# ─── Test Cases ───\n# Has conflicts\n# Expected: False\n# No conflicts\n# Expected: True\n# Back-to-back meetings (no conflict)\n# Expected: True\n# Single meeting\n# Expected: True\n# Empty schedule\n# Expected: True\n# Same start time\n# Expected: False',
  E'def can_attend_all_meetings(intervals):\n    """\n    Determine if a person can attend all meetings without conflicts.\n\n    Time Complexity: O(n log n) — sorting dominates\n    Space Complexity: O(1) — in-place check\n    """\n    if len(intervals) <= 1:\n        return True\n    # Sort by start time\n    intervals.sort(key=lambda x: x[0])\n    # Check adjacent intervals for overlap\n    for i in range(1, len(intervals)):\n        # If current starts before previous ends, there''s conflict\n        if intervals[i][0] < intervals[i - 1][1]:\n            return False\n    return True\n# ─── Test Cases ───\n# Expected: False\n# Expected: True\n# Expected: True\n# Expected: True\n# Expected: True\n# Expected: False',
  E'class Solution {\n    public Object canAttendAllMeetings(int[] intervals) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // import java.util.Arrays;\n    // import java.util.Comparator;\n\n    public static boolean canAttendAllMeetings(int[][] intervals) {\n        if (intervals == null || intervals.length <= 1) {\n            return true;\n        }\n\n        // Sort by start time\n        Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));\n\n        // Check adjacent intervals for overlap\n        for (int i = 1; i < intervals.length; i++) {\n            // If current starts before previous ends, there\'s an overlap\n            if (intervals[i][0] < intervals[i - 1][1]) {\n                return false;\n            }\n        }\n        return true;\n    }\n}''s conflict\n    //         if intervals[i][0] < intervals[i - 1][1]:\n    //             return False\n    //     \n    //     return True\n    // \n    // \n    // # ─── Test Cases ───\n    // # Expected: False\n    // \n    // # Expected: True\n    // \n    // # Expected: True\n    // \n    // # Expected: True\n    // \n    // # Expected: True\n    // \n    // # Expected: False\n    // \n}',
  E'/**\n * @param {any} intervals\n * @return {any}\n */\nfunction canAttendAllMeetings(intervals) {\n    // Your code here\n}',
  E'function canAttendAllMeetings(intervals) {\n    if (!intervals || intervals.length <= 1) {\n        return true;\n    }\n\n    // Sort by start time\n    intervals.sort((a, b) => a[0] - b[0]);\n\n    // Check adjacent intervals for overlap\n    for (let i = 1; i < intervals.length; i++) {\n        // If current starts before previous ends, there\'s an overlap\n        if (intervals[i][0] < intervals[i - 1][1]) {\n            return false;\n        }\n    }\n    return true;\n}',
  ARRAY['merge-intervals'],
  ARRAY['google-l4', 'meta-e4', 'uber-sde2', 'airbnb-swe', 'linkedin-swe'],
  'merge-intervals',
  '[{"input":"can_attend_all_meetings([[0, 30], [5, 10], [15, 20]])","expected_output":"False"},{"input":"can_attend_all_meetings([[7, 10], [2, 4]])","expected_output":"True"},{"input":"can_attend_all_meetings([[1, 5], [5, 10]])","expected_output":"True"}]'::jsonb,
  '[{"input":"can_attend_all_meetings([[1, 5]])","expected_output":"True"},{"input":"can_attend_all_meetings([])","expected_output":"True"},{"input":"can_attend_all_meetings([[1, 5], [1, 3]])","expected_output":"False"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
