INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-find-missing-number',
  'Find Missing Number',
  'medium',
  'Find the Missing Number

<!-- voice:section_check concept="cyclic sort for missing number" -->

Problem Statement

Given an array containing n distinct numbers taken from the range [0..n], find the one number that is missing from the array.

Examples

~~~
Input:  [4, 0, 3, 1]
Output: 2
Explanation: The array should contain [0..4], missing 2
~~~

~~~
Input:  [8, 3, 5, 2, 4, 6, 0, 1]
Output: 7
~~~',
  '',
  '[{"input":"[4, 0, 3, 1]","output":"2","explanation":"The array should contain [0..4], missing 2"}]'::jsonb,
  'find_missing_number',
