INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-find-all-duplicates',
  'Find All Duplicates',
  'hard',
  'Find All Duplicates

<!-- voice:section_check concept="finding all duplicates with cyclic sort" -->

Problem Statement

Given an array of n integers where each number is in range [1..n], find all numbers that appear twice in the array.

Examples

~~~
Input:  [3, 4, 4, 5, 5]
Output: [4, 5]
~~~

~~~
Input:  [5, 4, 7, 2, 3, 5, 3]
Output: [5, 3]
~~~',
  '',
  '[{"input":"[3, 4, 4, 5, 5]","output":"[4, 5]"}]'::jsonb,
  'find_all_duplicates',
  E'def find_all_duplicates(nums):\n    """\n    Find all numbers that appear twice in the array.\n\n    Args:\n        nums: List of integers in range [1..n]\n    Returns:\n        List of duplicate numbers\n    Example:\n        >>> find_all_duplicates([3, 4, 4, 5, 5])\n        [4, 5]\n    """\n    # TODO: Use cyclic sort, collect all duplicates found\n    # Hint: Same as finding one duplicate, but keep track of all found\n    pass\n# ─── Test Cases ───\n# Multiple duplicates\n# Expected: [4, 5]\n# Duplicates in different positions\n# Expected: [5, 3]\n# No duplicates\n# Expected: []\n# All duplicates\n# Expected: [1, 2, 3]\n# Single element appearing multiple times\n# Expected: [2]',
  E'def find_all_duplicates(nums):\n    """\n    Find all numbers that appear twice in the array.\n\n    Time Complexity: O(n) — cyclic sort\n    Space Complexity: O(1) excluding output — in-place\n    """\n    duplicates = []\n    i = 0\n    while i < len(nums):\n        correct_idx = nums[i] - 1\n        # If not in correct position\n        if nums[i] != nums[correct_idx]:\n            # Swap to place it correctly\n            nums[i], nums[correct_idx] = nums[correct_idx], nums[i]\n        else:\n            # Already in correct position, move on\n            i += 1\n    # After sorting, duplicates will be at wrong positions\n    for i in range(len(nums)):\n        if nums[i] != i + 1:\n            duplicates.append(nums[i])\n    return duplicates\n# ─── Test Cases ───\n# Expected: [4, 5]\n# Expected: [5, 3]\n# Expected: []\n# Expected: [1, 2, 3]\n# Expected: [2]',
  E'class Solution {\n    public Object findAllDuplicates(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayList;\nimport java.util.List;\n\nclass Solution {\n    public static List<Integer> findAllDuplicates(int[] nums) {\n        List<Integer> duplicates = new ArrayList<>();\n        int i = 0;\n        while (i < nums.length) {\n            int correctIdx = nums[i] - 1;\n            // If not in correct position\n            if (nums[i] != nums[correctIdx]) {\n                // Swap to place it correctly\n                int temp = nums[i];\n                nums[i] = nums[correctIdx];\n                nums[correctIdx] = temp;\n            } else {\n                // Already in correct position, move on\n                i++;\n            }\n        }\n        // After sorting, duplicates will be at wrong positions\n        for (int j = 0; j < nums.length; j++) {\n            if (nums[j] != j + 1) {\n                duplicates.add(nums[j]);\n            }\n        }\n        return duplicates;\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction findAllDuplicates(nums) {\n    // Your code here\n}',
  E'function findAllDuplicates(nums) {\n    const duplicates = [];\n    let i = 0;\n    while (i < nums.length) {\n        const correctIdx = nums[i] - 1;\n        // If not in correct position\n        if (nums[i] !== nums[correctIdx]) {\n            // Swap to place it correctly\n            [nums[i], nums[correctIdx]] = [nums[correctIdx], nums[i]];\n        } else {\n            // Already in correct position, move on\n            i++;\n        }\n    }\n    // After sorting, duplicates will be at wrong positions\n    for (let j = 0; j < nums.length; j++) {\n        if (nums[j] !== j + 1) {\n            duplicates.push(nums[j]);\n        }\n    }\n    return duplicates;\n}',
  ARRAY['cyclic-sort', 'sorting'],
  ARRAY['google-l4', 'amazon-sde2', 'microsoft-sde2'],
  'cyclic-sort',
  '[{"input":"find_all_duplicates([3, 4, 4, 5, 5])","expected_output":"[4, 5]"},{"input":"find_all_duplicates([5, 4, 7, 2, 3, 5, 3])","expected_output":"[5, 3]"},{"input":"find_all_duplicates([1, 2, 3, 4])","expected_output":"[]"}]'::jsonb,
  '[{"input":"find_all_duplicates([1, 1, 2, 2, 3, 3])","expected_output":"[1, 2, 3]"},{"input":"find_all_duplicates([2, 2, 2, 2])","expected_output":"[2]"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
