INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-reverse-sublist',
  'Reverse a Sub-list',
  'medium',
  'Reverse a Sub-list

<!-- voice:section_check concept="reversing portion of linked list" -->

Problem Statement

Given the head of a linked list and two positions left and right, reverse the nodes from position left to position right (1-indexed) and return the head.

Examples

~~~
Input:  1 -> 2 -> 3 -> 4 -> 5, left = 2, right = 4
Output: 1 -> 4 -> 3 -> 2 -> 5
~~~

~~~
Input:  5, left = 1, right = 1
Output: 5
~~~',
  '',
  '[{"input":"1 -> 2 -> 3 -> 4 -> 5, left = 2, right = 4","output":"1 -> 4 -> 3 -> 2 -> 5"}]'::jsonb,
  'reverse_between',
  E'class ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef reverse_between(head, left, right):\n    """\n    Reverse nodes of the list from position left to position right (1-indexed).\n\n    Args:\n        head: ListNode, head of the linked list\n        left: int, starting position (1-indexed)\n        right: int, ending position (1-indexed)\n    Returns:\n        ListNode: Head of modified list\n    Example:\n        >>> head = ListNode(1, ListNode(2, ListNode(3, ListNode(4, ListNode(5)))))\n        >>> result = reverse_between(head, 2, 4)\n        >>> # 1 -> 4 -> 3 -> 2 -> 5\n    """\n    # TODO: Find node before left, reverse sublist, reconnect\n    # Hint: Use dummy node to handle edge case when left = 1\n    pass\ndef print_list(head):\n    """Helper to print list"""\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n\n# ─── Test Cases ───\n# Reverse middle portion\nhead1 = ListNode(1, ListNode(2, ListNode(3, ListNode(4, ListNode(5)))))\n# Expected: [1, 4, 3, 2, 5]\n# Reverse from start\nhead2 = ListNode(1, ListNode(2, ListNode(3)))\n# Expected: [2, 1, 3]\n# Reverse entire list\nhead3 = ListNode(1, ListNode(2, ListNode(3)))\n# Expected: [3, 2, 1]\n# Single node\nhead4 = ListNode(5)\n# Expected: [5]\n# Reverse single element\nhead5 = ListNode(1, ListNode(2, ListNode(3)))\n# Expected: [1, 2, 3]',
  E'class ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef reverse_between(head, left, right):\n    """\n    Reverse nodes of the list from position left to position right.\n\n    Time Complexity: O(n) — traverse to right position\n    Space Complexity: O(1) — only pointers\n    """\n    if not head or left == right:\n        return head\n    # Dummy node helps when left = 1\n    dummy = ListNode(0)\n    dummy.next = head\n    # Find node before the sublist\n    prev = dummy\n    for _ in range(left - 1):\n        prev = prev.next\n    # Reverse the sublist\n    current = prev.next  # First node of sublist (will become last)\n    for _ in range(right - left):\n        next_temp = current.next\n        current.next = next_temp.next\n        next_temp.next = prev.next\n        prev.next = next_temp\n    return dummy.next\ndef print_list(head):\n    """Helper to print list"""\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n\n# ─── Test Cases ───\nhead1 = ListNode(1, ListNode(2, ListNode(3, ListNode(4, ListNode(5)))))\n# Expected: [1, 4, 3, 2, 5]\nhead2 = ListNode(1, ListNode(2, ListNode(3)))\n# Expected: [2, 1, 3]\nhead3 = ListNode(1, ListNode(2, ListNode(3)))\n# Expected: [3, 2, 1]\nhead4 = ListNode(5)\n# Expected: [5]\nhead5 = ListNode(1, ListNode(2, ListNode(3)))\n# Expected: [1, 2, 3]',
  E'class Solution {\n    public Object reverseBetween(Object val, Object next) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static class ListNode {\n        int val;\n        ListNode next;\n        ListNode() {}\n        ListNode(int val) { this.val = val; }\n        ListNode(int val, ListNode next) { this.val = val; this.next = next; }\n    }\n\n    public static ListNode reverseBetween(ListNode head, int left, int right) {\n        if (head == null || left == right) {\n            return head;\n        }\n\n        ListNode dummy = new ListNode(0);\n        dummy.next = head;\n\n        ListNode prev = dummy;\n        for (int i = 0; i < left - 1; i++) {\n            prev = prev.next;\n        }\n\n        ListNode current = prev.next; // First node of sublist (will become last)\n        for (int i = 0; i < right - left; i++) {\n            ListNode nextTemp = current.next;\n            current.next = nextTemp.next;\n            nextTemp.next = prev.next;\n            prev.next = nextTemp;\n        }\n\n        return dummy.next;\n    }\n}',
  E'/**\n * @param {any, any} val, next\n * @return {any}\n */\nfunction reverseBetween(val, next) {\n    // Your code here\n}',
  E'/**\n * Definition for singly-linked list.\n * function ListNode(val, next) {\n *     this.val = (val===undefined ? 0 : val)\n *     this.next = (next===undefined ? null : next)\n * }\n */\nfunction reverseBetween(head, left, right) {\n    if (!head || left === right) {\n        return head;\n    }\n\n    let dummy = new ListNode(0);\n    dummy.next = head;\n\n    let prev = dummy;\n    for (let i = 0; i < left - 1; i++) {\n        prev = prev.next;\n    }\n\n    let current = prev.next; // First node of sublist (will become last)\n    for (let i = 0; i < right - left; i++) {\n        let nextTemp = current.next;\n        current.next = nextTemp.next;\n        nextTemp.next = prev.next;\n        prev.next = nextTemp;\n    }\n\n    return dummy.next;\n}\n\n// Helper ListNode class for standalone JS (if not provided by platform)\n// class ListNode {\n//     constructor(val = 0, next = null) {\n//         this.val = val;\n//         this.next = next;\n//     }\n// }',
  ARRAY['linked-list-reversal', 'linked-list'],
  ARRAY['meta-e4', 'amazon-sde2', 'microsoft-sde2', 'apple-ict3'],
  'linked-list-reversal',
  '[]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
