INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-rotate-linked-list',
  'Rotate a Linked List',
  'hard',
  'Rotate a Linked List

<!-- voice:section_check concept="rotating list using reversal" -->

Problem Statement

Given the head of a linked list, rotate the list to the right by k places.

Examples

~~~
Input:  1 -> 2 -> 3 -> 4 -> 5, k = 2
Output: 4 -> 5 -> 1 -> 2 -> 3
~~~

~~~
Input:  0 -> 1 -> 2, k = 4
Output: 2 -> 0 -> 1
Explanation: Rotate by 4 is same as rotate by 1 (4 % 3 = 1)
~~~',
  '',
  '[{"input":"1 -> 2 -> 3 -> 4 -> 5, k = 2","output":"4 -> 5 -> 1 -> 2 -> 3","explanation":"Rotate by 4 is same as rotate by 1 (4 % 3 = 1)"}]'::jsonb,
  'rotate_right',
  E'class ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef rotate_right(head, k):\n    """\n    Rotate the list to the right by k places.\n\n    Args:\n        head: ListNode, head of the linked list\n        k: int, number of places to rotate\n    Returns:\n        ListNode: Head of rotated list\n    Example:\n        >>> head = ListNode(1, ListNode(2, ListNode(3, ListNode(4, ListNode(5)))))\n        >>> result = rotate_right(head, 2)\n        >>> # 4 -> 5 -> 1 -> 2 -> 3\n    """\n    # TODO: Find length, make circular, find new tail, break circle\n    # Hint: k may be larger than list length, use modulo\n    pass\ndef print_list(head):\n    """Helper to print list"""\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n\n# ─── Test Cases ───\n# Rotate by 2\nhead1 = ListNode(1, ListNode(2, ListNode(3, ListNode(4, ListNode(5)))))\n# Expected: [4, 5, 1, 2, 3]\n# k > length\nhead2 = ListNode(0, ListNode(1, ListNode(2)))\n# Expected: [2, 0, 1]\n# k = 0\nhead3 = ListNode(1, ListNode(2, ListNode(3)))\n# Expected: [1, 2, 3]\n# Single node\nhead4 = ListNode(1)\n# Expected: [1]\n# Empty list\n# Expected: []',
  E'class ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef rotate_right(head, k):\n    """\n    Rotate the list to the right by k places.\n\n    Time Complexity: O(n) — find length and new tail\n    Space Complexity: O(1) — only pointers\n    """\n    if not head or not head.next or k == 0:\n        return head\n    # Find length and tail\n    length = 1\n    tail = head\n    while tail.next:\n        tail = tail.next\n        length += 1\n    # Make circular\n    tail.next = head\n    # Find new tail position\n    k = k % length\n    if k == 0:\n        tail.next = None\n        return head\n    # New tail is at position (length - k)\n    steps_to_new_tail = length - k\n    new_tail = head\n    for _ in range(steps_to_new_tail - 1):\n        new_tail = new_tail.next\n    new_head = new_tail.next\n    new_tail.next = None\n    return new_head\ndef print_list(head):\n    """Helper to print list"""\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n\n# ─── Test Cases ───\nhead1 = ListNode(1, ListNode(2, ListNode(3, ListNode(4, ListNode(5)))))\n# Expected: [4, 5, 1, 2, 3]\nhead2 = ListNode(0, ListNode(1, ListNode(2)))\n# Expected: [2, 0, 1]\nhead3 = ListNode(1, ListNode(2, ListNode(3)))\n# Expected: [1, 2, 3]\nhead4 = ListNode(1)\n# Expected: [1]\n# Expected: []',
  E'class Solution {\n    public Object rotateRight(Object val, Object next) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.List;\n    // import java.util.ArrayList;\n\n    public static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n        ListNode(int val, ListNode next) { this.val = val; this.next = next; }\n    }\n\n    public static ListNode rotateRight(ListNode head, int k) {\n        if (head == null || head.next == null || k == 0) {\n            return head;\n        }\n\n        // Find length and tail\n        int length = 1;\n        ListNode tail = head;\n        while (tail.next != null) {\n            tail = tail.next;\n            length++;\n        }\n\n        // Make circular\n        tail.next = head;\n\n        // Find new tail position\n        k = k % length;\n        if (k == 0) {\n            tail.next = null; // Break the circle if no effective rotation\n            return head;\n        }\n\n        // New tail is at position (length - k) steps from original head\n        int stepsToNewTail = length - k;\n        ListNode newTail = head;\n        for (int i = 0; i < stepsToNewTail - 1; i++) {\n            newTail = newTail.next;\n        }\n\n        ListNode newHead = newTail.next;\n        newTail.next = null; // Break the circle\n\n        return newHead;\n    }\n}',
  E'/**\n * @param {any, any} val, next\n * @return {any}\n */\nfunction rotateRight(val, next) {\n    // Your code here\n}',
  E'/**\n * Definition for singly-linked list.\n */\nfunction ListNode(val, next) {\n    this.val = (val===undefined ? 0 : val)\n    this.next = (next===undefined ? null : next)\n}\n\n/**\n * @param {ListNode} head\n * @param {number} k\n * @return {ListNode}\n */\nfunction rotateRight(head, k) {\n    if (!head || !head.next || k === 0) {\n        return head;\n    }\n\n    // Find length and tail\n    let length = 1;\n    let tail = head;\n    while (tail.next) {\n        tail = tail.next;\n        length++;\n    }\n\n    // Make circular\n    tail.next = head;\n\n    // Find new tail position\n    k = k % length;\n    if (k === 0) {\n        tail.next = null; // Break the circle if no effective rotation\n        return head;\n    }\n\n    // New tail is at position (length - k) steps from original head\n    const stepsToNewTail = length - k;\n    let newTail = head;\n    for (let i = 0; i < stepsToNewTail - 1; i++) {\n        newTail = newTail.next;\n    }\n\n    const newHead = newTail.next;\n    newTail.next = null; // Break the circle\n\n    return newHead;\n}',
  ARRAY['linked-list-reversal', 'linked-list'],
  ARRAY['meta-e4', 'amazon-sde2', 'microsoft-sde2', 'apple-ict3'],
  'linked-list-reversal',
