INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-binary-tree-level-order',
  'Binary Tree Level Order Traversal',
  'medium',
  'Binary Tree Level Order Traversal

<!-- voice:section_check concept="classic BFS pattern" -->

Problem Statement

Given the root of a binary tree, return the level order traversal of its nodes'' values (from left to right, level by level).

Examples

~~~
Input:  root = [3, 9, 20, null, null, 15, 7]
         3
        / \\
       9  20
         /  \\
        15   7
Output: [[3], [9, 20], [15, 7]]
~~~',
  '',
  '[{"input":"root = [3, 9, 20, null, null, 15, 7]","output":"[[3], [9, 20], [15, 7]]"}]'::jsonb,
  'level_order',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef level_order(root):\n    """\n    Return level order traversal of binary tree.\n\n    Args:\n        root: TreeNode, root of the binary tree\n    Returns:\n        List of lists, where each inner list contains values of one level\n    Example:\n        >>> root = TreeNode(3, TreeNode(9), TreeNode(20, TreeNode(15), TreeNode(7)))\n        >>> level_order(root)\n        [[3], [9, 20], [15, 7]]\n    """\n    # TODO: Use BFS with queue, track level size\n    # Hint: Use queue size at start of each level to know how many nodes to process\n    pass\n# ─── Test Cases ───\n# Standard tree\nroot1 = TreeNode(3, TreeNode(9), TreeNode(20, TreeNode(15), TreeNode(7)))\n# Expected: [[3], [9, 20], [15, 7]]\n# Single node\nroot2 = TreeNode(1)\n# Expected: [[1]]\n# Empty tree\n# Expected: []\n# Left-skewed tree\nroot3 = TreeNode(1, TreeNode(2, TreeNode(3)))\n# Expected: [[1], [2], [3]]\n# Right-skewed tree\nroot4 = TreeNode(1, None, TreeNode(2, None, TreeNode(3)))\n# Expected: [[1], [2], [3]]',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef level_order(root):\n    """\n    Return level order traversal of binary tree.\n\n    Time Complexity: O(n) — visit each node\n    Space Complexity: O(w) — queue holds max width\n    """\n    if not root:\n        return []\n    result = []\n    queue = deque([root])\n    while queue:\n        level_size = len(queue)\n        current_level = []\n        for _ in range(level_size):\n            node = queue.popleft()\n            current_level.append(node.val)\n            if node.left:\n                queue.append(node.left)\n            if node.right:\n                queue.append(node.right)\n        result.append(current_level)\n    return result\n# ─── Test Cases ───\nroot1 = TreeNode(3, TreeNode(9), TreeNode(20, TreeNode(15), TreeNode(7)))\n# Expected: [[3], [9, 20], [15, 7]]\nroot2 = TreeNode(1)\n# Expected: [[1]]\n# Expected: []\nroot3 = TreeNode(1, TreeNode(2, TreeNode(3)))\n# Expected: [[1], [2], [3]]\nroot4 = TreeNode(1, None, TreeNode(2, None, TreeNode(3)))\n# Expected: [[1], [2], [3]]',
  E'class Solution {\n    public Object levelOrder(Object val, Object left, Object right) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.List;\n    // import java.util.ArrayList;\n    // import java.util.Deque;\n    // import java.util.LinkedList;\n\n    public static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n        TreeNode(int val, TreeNode left, TreeNode right) {\n            this.val = val;\n            this.left = left;\n            this.right = right;\n        }\n    }\n\n    public static List<List<Integer>> levelOrder(TreeNode root) {\n        List<List<Integer>> result = new ArrayList<>();\n        if (root == null) {\n            return result;\n        }\n\n        Deque<TreeNode> queue = new LinkedList<>();\n        queue.offer(root); // Add root to the queue\n\n        while (!queue.isEmpty()) {\n            int levelSize = queue.size();\n            List<Integer> currentLevel = new ArrayList<>();\n            for (int i = 0; i < levelSize; i++) {\n                TreeNode node = queue.poll(); // Remove from front\n                currentLevel.add(node.val);\n\n                if (node.left != null) {\n                    queue.offer(node.left);\n                }\n                if (node.right != null) {\n                    queue.offer(node.right);\n                }\n            }\n            result.add(currentLevel);\n        }\n        return result;\n    }\n}',
  E'/**\n * @param {any, any, any} val, left, right\n * @return {any}\n */\nfunction levelOrder(val, left, right) {\n    // Your code here\n}',
  E'/**\n * Definition for a binary tree node.\n */\nfunction TreeNode(val, left, right) {\n    this.val = (val===undefined ? 0 : val)\n    this.left = (left===undefined ? null : left)\n    this.right = (right===undefined ? null : right)\n}\n\n/**\n * @param {TreeNode} root\n * @return {number[][]}\n */\nfunction levelOrder(root) {\n    const result = [];\n    if (!root) {\n        return result;\n    }\n\n    const queue = [root]; // Use an array as a queue\n\n    while (queue.length > 0) {\n        const levelSize = queue.length;\n        const currentLevel = [];\n        for (let i = 0; i < levelSize; i++) {\n            const node = queue.shift(); // Remove from front\n            currentLevel.push(node.val);\n\n            if (node.left) {\n                queue.push(node.left);\n            }\n            if (node.right) {\n                queue.push(node.right);\n            }\n        }\n        result.push(currentLevel);\n    }\n    return result;\n}',
  ARRAY['tree-bfs', 'trees'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'tree-bfs',
  '[{"input":"level_order(root1)","expected_output":"[[3], [9, 20], [15, 7]]"},{"input":"level_order(root2)","expected_output":"[[1]]"},{"input":"level_order(None)","expected_output":"[]"}]'::jsonb,
  '[{"input":"level_order(root3)","expected_output":"[[1], [2], [3]]"},{"input":"level_order(root4)","expected_output":"[[1], [2], [3]]"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
