  'coding-interview-premium-reverse-level-order',
  'Reverse Level Order Traversal',
  'medium',
  'Reverse Level Order Traversal

<!-- voice:section_check concept="BFS with reversed result" -->

Problem Statement

Given a binary tree, return the bottom-up level order traversal of its nodes'' values (from leaf to root, left to right).

Examples

~~~
Input:  root = [3, 9, 20, null, null, 15, 7]
         3
        / \\
       9  20
         /  \\
        15   7
Output: [[15, 7], [9, 20], [3]]
~~~',
  '',
  '[{"input":"root = [3, 9, 20, null, null, 15, 7]","output":"[[15, 7], [9, 20], [3]]"}]'::jsonb,
  'reverse_level_order',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef reverse_level_order(root):\n    """\n    Return bottom-up level order traversal.\n\n    Args:\n        root: TreeNode, root of the binary tree\n    Returns:\n        List of lists, levels ordered from leaf to root\n    Example:\n        >>> root = TreeNode(3, TreeNode(9), TreeNode(20, TreeNode(15), TreeNode(7)))\n        >>> reverse_level_order(root)\n        [[15, 7], [9, 20], [3]]\n    """\n    # TODO: Do level order, reverse result (or insert at front)\n    # Hint: Can use insert(0, level) or reverse at the end\n    pass\n# ─── Test Cases ───\n# Standard tree\nroot1 = TreeNode(3, TreeNode(9), TreeNode(20, TreeNode(15), TreeNode(7)))\n# Expected: [[15, 7], [9, 20], [3]]\n# Single node\nroot2 = TreeNode(1)\n# Expected: [[1]]\n# Empty tree\n# Expected: []\n# Complete binary tree\nroot3 = TreeNode(1, TreeNode(2, TreeNode(4), TreeNode(5)), TreeNode(3, TreeNode(6), TreeNode(7)))\n# Expected: [[4, 5, 6, 7], [2, 3], [1]]',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef reverse_level_order(root):\n    """\n    Return bottom-up level order traversal.\n\n    Time Complexity: O(n) — visit each node\n    Space Complexity: O(w) — queue storage\n    """\n    if not root:\n        return []\n    result = deque()\n    queue = deque([root])\n    while queue:\n        level_size = len(queue)\n        current_level = []\n        for _ in range(level_size):\n            node = queue.popleft()\n            current_level.append(node.val)\n            if node.left:\n                queue.append(node.left)\n            if node.right:\n                queue.append(node.right)\n        result.appendleft(current_level)\n    return list(result)\n# ─── Test Cases ───\nroot1 = TreeNode(3, TreeNode(9), TreeNode(20, TreeNode(15), TreeNode(7)))\n# Expected: [[15, 7], [9, 20], [3]]\nroot2 = TreeNode(1)\n# Expected: [[1]]\n# Expected: []\nroot3 = TreeNode(1, TreeNode(2, TreeNode(4), TreeNode(5)), TreeNode(3, TreeNode(6), TreeNode(7)))\n# Expected: [[4, 5, 6, 7], [2, 3], [1]]',
  E'class Solution {\n    public Object reverseLevelOrder(Object val, Object left, Object right) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.List;\n    // import java.util.ArrayList;\n    // import java.util.Deque;\n    // import java.util.LinkedList;\n\n    public static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n        TreeNode(int val, TreeNode left, TreeNode right) {\n            this.val = val;\n            this.left = left;\n            this.right = right;\n        }\n    }\n\n    public static List<List<Integer>> reverseLevelOrder(TreeNode root) {\n        // Using LinkedList as a Deque to efficiently add to the front (appendleft)\n        List<List<Integer>> result = new LinkedList<>();\n        if (root == null) {\n            return result;\n        }\n\n        Deque<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n\n        while (!queue.isEmpty()) {\n            int levelSize = queue.size();\n            List<Integer> currentLevel = new ArrayList<>();\n            for (int i = 0; i < levelSize; i++) {\n                TreeNode node = queue.poll();\n                currentLevel.add(node.val);\n\n                if (node.left != null) {\n                    queue.offer(node.left);\n                }\n                if (node.right != null) {\n                    queue.offer(node.right);\n                }\n            }\n            ((LinkedList<List<Integer>>) result).addFirst(currentLevel); // Add to the beginning\n        }\n        return result;\n    }\n}',
  E'/**\n * @param {any, any, any} val, left, right\n * @return {any}\n */\nfunction reverseLevelOrder(val, left, right) {\n    // Your code here\n}',
  E'/**\n * Definition for a binary tree node.\n */\nfunction TreeNode(val, left, right) {\n    this.val = (val===undefined ? 0 : val)\n    this.left = (left===undefined ? null : left)\n    this.right = (right===undefined ? null : right)\n}\n\n/**\n * @param {TreeNode} root\n * @return {number[][]}\n */\nfunction reverseLevelOrder(root) {\n    const result = []; // Will use unshift to add to the front\n    if (!root) {\n        return result;\n    }\n\n    const queue = [root];\n\n    while (queue.length > 0) {\n        const levelSize = queue.length;\n        const currentLevel = [];\n        for (let i = 0; i < levelSize; i++) {\n            const node = queue.shift();\n            currentLevel.push(node.val);\n\n            if (node.left) {\n                queue.push(node.left);\n            }\n            if (node.right) {\n                queue.push(node.right);\n            }\n        }\n        result.unshift(currentLevel); // Add to the beginning\n    }\n    return result;\n}',
  ARRAY['tree-bfs', 'trees'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'tree-bfs',
  '[{"input":"reverse_level_order(root1)","expected_output":"[[15, 7], [9, 20], [3]]"},{"input":"reverse_level_order(root2)","expected_output":"[[1]]"},{"input":"reverse_level_order(None)","expected_output":"[]"}]'::jsonb,
  '[{"input":"reverse_level_order(root3)","expected_output":"[[4, 5, 6, 7], [2, 3], [1]]"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
