INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-zigzag-traversal',
  'Zigzag Traversal',
  'medium',
  'Zigzag Traversal

<!-- voice:section_check concept="alternating level directions" -->

Problem Statement

Given a binary tree, return the zigzag level order traversal of its nodes'' values (alternate left-to-right and right-to-left for each level).

Examples

~~~
Input:  root = [3, 9, 20, null, null, 15, 7]
         3
        / \\
       9  20
         /  \\
        15   7
Output: [[3], [20, 9], [15, 7]]
~~~',
  '',
  '[{"input":"root = [3, 9, 20, null, null, 15, 7]","output":"[[3], [20, 9], [15, 7]]"}]'::jsonb,
  'zigzag_level_order',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef zigzag_level_order(root):\n    """\n    Return zigzag level order traversal.\n\n    Args:\n        root: TreeNode, root of the binary tree\n    Returns:\n        List of lists, alternating left-to-right and right-to-left\n    Example:\n        >>> root = TreeNode(3, TreeNode(9), TreeNode(20, TreeNode(15), TreeNode(7)))\n        >>> zigzag_level_order(root)\n        [[3], [20, 9], [15, 7]]\n    """\n    # TODO: BFS level order, reverse every other level\n    # Hint: Use a flag or level index to determine direction\n    pass\n# ─── Test Cases ───\n# Standard tree\nroot1 = TreeNode(3, TreeNode(9), TreeNode(20, TreeNode(15), TreeNode(7)))\n# Expected: [[3], [20, 9], [15, 7]]\n# Single node\nroot2 = TreeNode(1)\n# Expected: [[1]]\n# Empty tree\n# Expected: []\n# Larger tree\nroot3 = TreeNode(1,\n    TreeNode(2, TreeNode(4), TreeNode(5)),\n    TreeNode(3, TreeNode(6), TreeNode(7)))\n# Expected: [[1], [3, 2], [4, 5, 6, 7]]',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef zigzag_level_order(root):\n    """\n    Return zigzag level order traversal.\n\n    Time Complexity: O(n) — visit each node\n    Space Complexity: O(w) — queue storage\n    """\n    if not root:\n        return []\n    result = []\n    queue = deque([root])\n    left_to_right = True\n    while queue:\n        level_size = len(queue)\n        current_level = []\n        for _ in range(level_size):\n            node = queue.popleft()\n            current_level.append(node.val)\n            if node.left:\n                queue.append(node.left)\n            if node.right:\n                queue.append(node.right)\n        if not left_to_right:\n            current_level.reverse()\n        result.append(current_level)\n        left_to_right = not left_to_right\n    return result\n# ─── Test Cases ───\nroot1 = TreeNode(3, TreeNode(9), TreeNode(20, TreeNode(15), TreeNode(7)))\n# Expected: [[3], [20, 9], [15, 7]]\nroot2 = TreeNode(1)\n# Expected: [[1]]\n# Expected: []\nroot3 = TreeNode(1,\n    TreeNode(2, TreeNode(4), TreeNode(5)),\n    TreeNode(3, TreeNode(6), TreeNode(7)))\n# Expected: [[1], [3, 2], [4, 5, 6, 7]]',
  E'class Solution {\n    public Object zigzagLevelOrder(Object val, Object left, Object right) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.List;\n    // import java.util.ArrayList;\n    // import java.util.Deque;\n    // import java.util.LinkedList;\n    // import java.util.Collections; // For Collections.reverse\n\n    public static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n        TreeNode(int val, TreeNode left, TreeNode right) {\n            this.val = val;\n            this.left = left;\n            this.right = right;\n        }\n    }\n\n    public static List<List<Integer>> zigzagLevelOrder(TreeNode root) {\n        List<List<Integer>> result = new ArrayList<>();\n        if (root == null) {\n            return result;\n        }\n\n        Deque<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        boolean leftToRight = true;\n\n        while (!queue.isEmpty()) {\n            int levelSize = queue.size();\n            List<Integer> currentLevel = new ArrayList<>();\n            for (int i = 0; i < levelSize; i++) {\n                TreeNode node = queue.poll();\n                currentLevel.add(node.val);\n\n                if (node.left != null) {\n                    queue.offer(node.left);\n                }\n                if (node.right != null) {\n                    queue.offer(node.right);\n                }\n            }\n\n            if (!leftToRight) {\n                Collections.reverse(currentLevel);\n            }\n            result.add(currentLevel);\n            leftToRight = !leftToRight; // Toggle direction for next level\n        }\n        return result;\n    }\n}',
  E'/**\n * @param {any, any, any} val, left, right\n * @return {any}\n */\nfunction zigzagLevelOrder(val, left, right) {\n    // Your code here\n}',
  E'/**\n * Definition for a binary tree node.\n */\nfunction TreeNode(val, left, right) {\n    this.val = (val===undefined ? 0 : val)\n    this.left = (left===undefined ? null : left)\n    this.right = (right===undefined ? null : right)\n}\n\n/**\n * @param {TreeNode} root\n * @return {number[][]}\n */\nfunction zigzagLevelOrder(root) {\n    const result = [];\n    if (!root) {\n        return result;\n    }\n\n    const queue = [root];\n    let leftToRight = true;\n\n    while (queue.length > 0) {\n        const levelSize = queue.length;\n        const currentLevel = [];\n        for (let i = 0; i < levelSize; i++) {\n            const node = queue.shift();\n            currentLevel.push(node.val);\n\n            if (node.left) {\n                queue.push(node.left);\n            }\n            if (node.right) {\n                queue.push(node.right);\n            }\n        }\n\n        if (!leftToRight) {\n            currentLevel.reverse();\n        }\n        result.push(currentLevel);\n        leftToRight = !leftToRight; // Toggle direction for next level\n    }\n    return result;\n}',
  ARRAY['tree-bfs', 'trees'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'tree-bfs',
  '[{"input":"zigzag_level_order(root1)","expected_output":"[[3], [20, 9], [15, 7]]"},{"input":"zigzag_level_order(root2)","expected_output":"[[1]]"},{"input":"zigzag_level_order(None)","expected_output":"[]"}]'::jsonb,
  '[{"input":"zigzag_level_order(root3)","expected_output":"[[1], [3, 2], [4, 5, 6, 7]]"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
