INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-level-averages',
  'Level Averages',
  'hard',
  'Level Averages in a Binary Tree

<!-- voice:section_check concept="computing per-level statistics" -->

Problem Statement

Given a binary tree, return the average value of nodes on each level.

Examples

~~~
Input:  root = [3, 9, 20, null, null, 15, 7]
         3
        / \\
       9  20
         /  \\
        15   7
Output: [3.0, 14.5, 11.0]
Explanation: Level 0: 3, Level 1: (9+20)/2 = 14.5, Level 2: (15+7)/2 = 11.0
~~~',
  '',
  '[{"input":"root = [3, 9, 20, null, null, 15, 7]","output":"[3.0, 14.5, 11.0]","explanation":"Level 0: 3, Level 1: (9+20)/2 = 14.5, Level 2: (15+7)/2 = 11.0"}]'::jsonb,
  'find_level_averages',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef find_level_averages(root):\n    """\n    Return average value of nodes on each level.\n\n    Args:\n        root: TreeNode, root of the binary tree\n    Returns:\n        List of floats, average for each level\n    Example:\n        >>> root = TreeNode(3, TreeNode(9), TreeNode(20, TreeNode(15), TreeNode(7)))\n        >>> find_level_averages(root)\n        [3.0, 14.5, 11.0]\n    """\n    # TODO: BFS level order, compute average for each level\n    # Hint: Sum values and divide by level size\n    pass\n# ─── Test Cases ───\n# Standard tree\nroot1 = TreeNode(3, TreeNode(9), TreeNode(20, TreeNode(15), TreeNode(7)))\n# Expected: [3.0, 14.5, 11.0]\n# Single node\nroot2 = TreeNode(1)\n# Expected: [1.0]\n# Empty tree\n# Expected: []\n# All same values\nroot3 = TreeNode(5, TreeNode(5), TreeNode(5))\n# Expected: [5.0, 5.0]',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef find_level_averages(root):\n    """\n    Return average value of nodes on each level.\n\n    Time Complexity: O(n) — visit each node\n    Space Complexity: O(w) — queue storage\n    """\n    if not root:\n        return []\n    result = []\n    queue = deque([root])\n    while queue:\n        level_size = len(queue)\n        level_sum = 0\n        for _ in range(level_size):\n            node = queue.popleft()\n            level_sum += node.val\n            if node.left:\n                queue.append(node.left)\n            if node.right:\n                queue.append(node.right)\n        result.append(level_sum / level_size)\n    return result\n# ─── Test Cases ───\nroot1 = TreeNode(3, TreeNode(9), TreeNode(20, TreeNode(15), TreeNode(7)))\n# Expected: [3.0, 14.5, 11.0]\nroot2 = TreeNode(1)\n# Expected: [1.0]\n# Expected: []\nroot3 = TreeNode(5, TreeNode(5), TreeNode(5))\n# Expected: [5.0, 5.0]',
  E'class Solution {\n    public Object findLevelAverages(Object val, Object left, Object right) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.List;\n    // import java.util.ArrayList;\n    // import java.util.Deque;\n    // import java.util.LinkedList;\n\n    public static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n        TreeNode(int val, TreeNode left, TreeNode right) {\n            this.val = val;\n            this.left = left;\n            this.right = right;\n        }\n    }\n\n    public static List<Double> findLevelAverages(TreeNode root) {\n        List<Double> result = new ArrayList<>();\n        if (root == null) {\n            return result;\n        }\n\n        Deque<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n\n        while (!queue.isEmpty()) {\n            int levelSize = queue.size();\n            double levelSum = 0; // Use double for sum to ensure float division\n            for (int i = 0; i < levelSize; i++) {\n                TreeNode node = queue.poll();\n                levelSum += node.val;\n\n                if (node.left != null) {\n                    queue.offer(node.left);\n                }\n                if (node.right != null) {\n                    queue.offer(node.right);\n                }\n            }\n            result.add(levelSum / levelSize);\n        }\n        return result;\n    }\n}',
  E'/**\n * @param {any, any, any} val, left, right\n * @return {any}\n */\nfunction findLevelAverages(val, left, right) {\n    // Your code here\n}',
  E'/**\n * Definition for a binary tree node.\n */\nfunction TreeNode(val, left, right) {\n    this.val = (val===undefined ? 0 : val)\n    this.left = (left===undefined ? null : left)\n    this.right = (right===undefined ? null : right)\n}\n\n/**\n * @param {TreeNode} root\n * @return {number[]}\n */\nfunction findLevelAverages(root) {\n    const result = [];\n    if (!root) {\n        return result;\n    }\n\n    const queue = [root];\n\n    while (queue.length > 0) {\n        const levelSize = queue.length;\n        let levelSum = 0;\n        for (let i = 0; i < levelSize; i++) {\n            const node = queue.shift();\n            levelSum += node.val;\n\n            if (node.left) {\n                queue.push(node.left);\n            }\n            if (node.right) {\n                queue.push(node.right);\n            }\n        }\n        result.push(levelSum / levelSize);\n    }\n    return result;\n}',
  ARRAY['tree-bfs', 'trees'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'tree-bfs',
  '[{"input":"find_level_averages(root1)","expected_output":"[3.0, 14.5, 11.0]"},{"input":"find_level_averages(root2)","expected_output":"[1.0]"},{"input":"find_level_averages(None)","expected_output":"[]"}]'::jsonb,
  '[{"input":"find_level_averages(root3)","expected_output":"[5.0, 5.0]"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
