INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-minimum-depth',
  'Minimum Depth',
  'hard',
  'Minimum Depth of Binary Tree

<!-- voice:section_check concept="BFS for shortest path" -->

Problem Statement

Given a binary tree, find its minimum depth. The minimum depth is the number of nodes along the shortest path from the root down to the nearest leaf node.

Examples

~~~
Input:  root = [3, 9, 20, null, null, 15, 7]
         3
        / \\
       9  20
         /  \\
        15   7
Output: 2
Explanation: Shortest path is 3 -> 9
~~~

~~~
Input:  root = [2, null, 3, null, 4, null, 5, null, 6]
         2
          \\
           3
            \\
             4
              \\
               5
                \\
                 6
Output: 5
~~~',
  '',
  '[{"input":"root = [3, 9, 20, null, null, 15, 7]","output":"2","explanation":"Shortest path is 3 -> 9"}]'::jsonb,
  'min_depth',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef min_depth(root):\n    """\n    Find minimum depth of binary tree.\n\n    Args:\n        root: TreeNode, root of the binary tree\n    Returns:\n        int: Minimum depth\n    Example:\n        >>> root = TreeNode(3, TreeNode(9), TreeNode(20, TreeNode(15), TreeNode(7)))\n        >>> min_depth(root)\n        2\n    """\n    # TODO: BFS, return depth when first leaf is found\n    # Hint: A leaf has no left and no right child\n    pass\n# ─── Test Cases ───\n# Standard tree\nroot1 = TreeNode(3, TreeNode(9), TreeNode(20, TreeNode(15), TreeNode(7)))\n# Expected: 2\n# Skewed right\nroot2 = TreeNode(2, None, TreeNode(3, None, TreeNode(4, None, TreeNode(5, None, TreeNode(6)))))\n# Expected: 5\n# Single node\nroot3 = TreeNode(1)\n# Expected: 1\n# Empty tree\n# Expected: 0\n# Left skewed\nroot4 = TreeNode(1, TreeNode(2, TreeNode(3)))\n# Expected: 3',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef min_depth(root):\n    """\n    Find minimum depth of binary tree.\n\n    Time Complexity: O(n) worst case\n    Space Complexity: O(w) — queue storage\n    """\n    if not root:\n        return 0\n    queue = deque([(root, 1)])\n    while queue:\n        node, depth = queue.popleft()\n        # Check if this is a leaf node\n        if not node.left and not node.right:\n            return depth\n        if node.left:\n            queue.append((node.left, depth + 1))\n        if node.right:\n            queue.append((node.right, depth + 1))\n    return 0\n# ─── Test Cases ───\nroot1 = TreeNode(3, TreeNode(9), TreeNode(20, TreeNode(15), TreeNode(7)))\n# Expected: 2\nroot2 = TreeNode(2, None, TreeNode(3, None, TreeNode(4, None, TreeNode(5, None, TreeNode(6)))))\n# Expected: 5\nroot3 = TreeNode(1)\n# Expected: 1\n# Expected: 0\nroot4 = TreeNode(1, TreeNode(2, TreeNode(3)))\n# Expected: 3',
  E'class Solution {\n    public Object minDepth(Object val, Object left, Object right) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.Deque;\n    // import java.util.LinkedList;\n\n    public static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n        TreeNode(int val, TreeNode left, TreeNode right) {\n            this.val = val;\n            this.left = left;\n            this.right = right;\n        }\n    }\n\n    // Helper class to store TreeNode and its depth\n    private static class NodeDepth {\n        TreeNode node;\n        int depth;\n\n        NodeDepth(TreeNode node, int depth) {\n            this.node = node;\n            this.depth = depth;\n        }\n    }\n\n    public static int minDepth(TreeNode root) {\n        if (root == null) {\n            return 0;\n        }\n\n        Deque<NodeDepth> queue = new LinkedList<>();\n        queue.offer(new NodeDepth(root, 1));\n\n        while (!queue.isEmpty()) {\n            NodeDepth current = queue.poll();\n            TreeNode node = current.node;\n            int depth = current.depth;\n\n            // If it\'s a leaf node, return its depth\n            if (node.left == null && node.right == null) {\n                return depth;\n            }\n\n            if (node.left != null) {\n                queue.offer(new NodeDepth(node.left, depth + 1));\n            }\n            if (node.right != null) {\n                queue.offer(new NodeDepth(node.right, depth + 1));\n            }\n        }\n        // This line should theoretically not be reached if the tree is valid\n        // (i.e., root is not null, a leaf will always be found).\n        return 0;\n    }\n}',
  E'/**\n * @param {any, any, any} val, left, right\n * @return {any}\n */\nfunction minDepth(val, left, right) {\n    // Your code here\n}',
  E'/**\n * Definition for a binary tree node.\n */\nfunction TreeNode(val, left, right) {\n    this.val = (val===undefined ? 0 : val)\n    this.left = (left===undefined ? null : left)\n    this.right = (right===undefined ? null : right)\n}\n\n/**\n * @param {TreeNode} root\n * @return {number}\n */\nfunction minDepth(root) {\n    if (!root) {\n        return 0;\n    }\n\n    // Queue stores pairs of [node, depth]\n    const queue = [[root, 1]];\n\n    while (queue.length > 0) {\n        const [node, depth] = queue.shift();\n\n        // If it\'s a leaf node, return its depth\n        if (!node.left && !node.right) {\n            return depth;\n        }\n\n        if (node.left) {\n            queue.push([node.left, depth + 1]);\n        }\n        if (node.right) {\n            queue.push([node.right, depth + 1]);\n        }\n    }\n    // This line should theoretically not be reached if the tree is valid\n    // (i.e., root is not null, a leaf will always be found).\n    return 0;\n}',
  ARRAY['tree-bfs', 'trees'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'tree-bfs',
  '[{"input":"min_depth(root1)","expected_output":"2"},{"input":"min_depth(root2)","expected_output":"5"},{"input":"min_depth(root3)","expected_output":"1"}]'::jsonb,
  '[{"input":"min_depth(None)","expected_output":"0"},{"input":"min_depth(root4)","expected_output":"3"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
  description = EXCLUDED.description,
  constraints = EXCLUDED.constraints,
  examples = EXCLUDED.examples,
