INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-binary-tree-path-sum',
  'Binary Tree Path Sum',
  'medium',
  'Binary Tree Path Sum

<!-- voice:section_check concept="DFS for path existence" -->

Problem Statement

Given a binary tree and a target sum, determine if the tree has a root-to-leaf path such that adding up all the values along the path equals the target sum.

Examples

~~~
Input:  root = [5, 4, 8, 11, null, 13, 4, 7, 2, null, null, null, 1], targetSum = 22
             5
            / \\
           4   8
          /   / \\
         11  13  4
        / \\       \\
       7   2       1
Output: True
Explanation: Path 5 -> 4 -> 11 -> 2 sums to 22
~~~',
  '',
  '[{"input":"root = [5, 4, 8, 11, null, 13, 4, 7, 2, null, null, null, 1], targetSum = 22","output":"True","explanation":"Path 5 -> 4 -> 11 -> 2 sums to 22"}]'::jsonb,
  'has_path_sum',
  E'class TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef has_path_sum(root, target_sum):\n    """\n    Determine if tree has a root-to-leaf path with given sum.\n\n    Args:\n        root: TreeNode, root of binary tree\n        target_sum: int, target path sum\n    Returns:\n        bool: True if path with target sum exists\n    Example:\n        >>> root = TreeNode(5, TreeNode(4, TreeNode(11, TreeNode(7), TreeNode(2))), TreeNode(8, TreeNode(13), TreeNode(4, None, TreeNode(1))))\n        >>> has_path_sum(root, 22)\n        True\n    """\n    # TODO: DFS, subtract node value from sum, check at leaf\n    # Hint: At leaf, check if node.val == remaining sum\n    pass\n# ─── Test Cases ───\n# Standard tree with path\nroot1 = TreeNode(5,\n    TreeNode(4, TreeNode(11, TreeNode(7), TreeNode(2))),\n    TreeNode(8, TreeNode(13), TreeNode(4, None, TreeNode(1))))\n# Expected: True\n# No path exists\n# Expected: False\n# Single node matches\nroot2 = TreeNode(5)\n# Expected: True\n# Single node doesn''t match\n# Expected: False\n# Empty tree\n# Expected: False',
  E'class TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef has_path_sum(root, target_sum):\n    """\n    Determine if tree has a root-to-leaf path with given sum.\n\n    Time Complexity: O(n) — may visit all nodes\n    Space Complexity: O(h) — recursion stack\n    """\n    if not root:\n        return False\n    # Check if leaf node\n    if not root.left and not root.right:\n        return root.val == target_sum\n    # Recursively check left and right subtrees with reduced sum\n    remaining = target_sum - root.val\n    return has_path_sum(root.left, remaining) or has_path_sum(root.right, remaining)\n# ─── Test Cases ───\nroot1 = TreeNode(5,\n    TreeNode(4, TreeNode(11, TreeNode(7), TreeNode(2))),\n    TreeNode(8, TreeNode(13), TreeNode(4, None, TreeNode(1))))\n# Expected: True\n# Expected: False\nroot2 = TreeNode(5)\n# Expected: True\n# Expected: False\n# Expected: False',
  E'class Solution {\n    public Object hasPathSum(Object val, Object left, Object right) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n        TreeNode(int val, TreeNode left, TreeNode right) {\n            this.val = val;\n            this.left = left;\n            this.right = right;\n        }\n    }\n\n    public static boolean hasPathSum(TreeNode root, int targetSum) {\n        if (root == null) {\n            return false;\n        }\n\n        // Check if it\'s a leaf node\n        if (root.left == null && root.right == null) {\n            return root.val == targetSum;\n        }\n\n        // Recursively check left and right subtrees with reduced sum\n        int remaining = targetSum - root.val;\n        return hasPathSum(root.left, remaining) || hasPathSum(root.right, remaining);\n    }\n}',
  E'/**\n * @param {any, any, any} val, left, right\n * @return {any}\n */\nfunction hasPathSum(val, left, right) {\n    // Your code here\n}',
  E'/**\n * Definition for a binary tree node.\n */\nfunction TreeNode(val, left, right) {\n    this.val = (val===undefined ? 0 : val)\n    this.left = (left===undefined ? null : left)\n    this.right = (right===undefined ? null : right)\n}\n\n/**\n * @param {TreeNode} root\n * @param {number} targetSum\n * @return {boolean}\n */\nfunction hasPathSum(root, targetSum) {\n    if (!root) {\n        return false;\n    }\n\n    // Check if it\'s a leaf node\n    if (!root.left && !root.right) {\n        return root.val === targetSum;\n    }\n\n    // Recursively check left and right subtrees with reduced sum\n    const remaining = targetSum - root.val;\n    return hasPathSum(root.left, remaining) || hasPathSum(root.right, remaining);\n}',
