INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-find-median-number-stream',
  'Find Median of Number Stream',
  'medium',
  'Find Median of Number Stream

<!-- voice:section_check concept="Two Heaps for streaming median" -->

Problem Statement

Design a class to calculate the median of a number stream. The class should have:
- \\`insertNum(int num)\\`: stores the number
- \\`findMedian()\\`: returns the median of all numbers inserted so far

If the count of numbers is even, the median is the average of the middle two numbers.

Examples

~~~
MedianFinder medianFinder = new MedianFinder();
medianFinder.insertNum(3);
medianFinder.insertNum(1);
medianFinder.findMedian();  // returns 2.0
medianFinder.insertNum(5);
medianFinder.findMedian();  // returns 3.0
medianFinder.insertNum(4);
medianFinder.findMedian();  // returns 3.5
~~~',
  '',
  '[]'::jsonb,
  'MedianFinder',
  E'import heapq\nclass MedianFinder:\n    """\n    Class to find median of a stream of numbers using two heaps.\n    Example:\n        >>> finder = MedianFinder()\n        >>> finder.insertNum(3)\n        >>> finder.insertNum(1)\n        >>> finder.findMedian()\n        2.0\n        >>> finder.insertNum(5)\n        >>> finder.findMedian()\n        3.0\n    """\n    def __init__(self):\n        """Initialize two heaps for median finding."""\n        # TODO: Initialize max_heap (smaller half) and min_heap (larger half)\n        # Hint: Use negative values for max_heap in Python\n        pass\n\n    def insertNum(self, num):\n        """\n        Insert a number into the data structure.\n\n        Args:\n            num: int, number to insert\n        """\n        # TODO: Insert into appropriate heap, then rebalance\n        # Hint: Compare with top of max_heap to decide where to insert\n        pass\n    def findMedian(self):\n        """\n        Return the median of all inserted numbers.\n\n        Returns:\n            float: median value\n        """\n        # TODO: Return median based on heap sizes\n        # Hint: If heaps equal size, average the tops; else max_heap top\n        pass\n# ─── Test Cases ───\nfinder = MedianFinder()\nfinder.insertNum(3)\nfinder.insertNum(1)\n# Expected: 2.0\nfinder.insertNum(5)\n# Expected: 3.0\nfinder.insertNum(4)\n# Expected: 3.5\nfinder.insertNum(2)\n# Expected: 3.0\n# Single element\nfinder2 = MedianFinder()\nfinder2.insertNum(10)\n# Expected: 10.0',
  E'import heapq\nclass MedianFinder:\n    """\n    Class to find median of a stream of numbers using two heaps.\n    Time Complexity:\n        insertNum: O(log n) — heap push\n        findMedian: O(1) — peek at heap tops\n    Space Complexity: O(n) — store all numbers\n    """\n    def __init__(self):\n        """Initialize two heaps for median finding."""\n        self.max_heap = []  # smaller half (store negatives)\n        self.min_heap = []  # larger half\n\n    def insertNum(self, num):\n        """\n        Insert a number into the data structure.\n        """\n        # Insert into appropriate heap\n        if not self.max_heap or num <= -self.max_heap[0]:\n            heapq.heappush(self.max_heap, -num)\n        else:\n            heapq.heappush(self.min_heap, num)\n\n        # Rebalance: max_heap can have at most 1 more element\n        if len(self.max_heap) > len(self.min_heap) + 1:\n            heapq.heappush(self.min_heap, -heapq.heappop(self.max_heap))\n        elif len(self.min_heap) > len(self.max_heap):\n            heapq.heappush(self.max_heap, -heapq.heappop(self.min_heap))\n    def findMedian(self):\n        """\n        Return the median of all inserted numbers.\n        """\n        if len(self.max_heap) == len(self.min_heap):\n            # Even number of elements\n            return (-self.max_heap[0] + self.min_heap[0]) / 2\n        else:\n            # Odd number of elements, max_heap has the extra\n            return float(-self.max_heap[0])\n\n# ─── Test Cases ───\nfinder = MedianFinder()\nfinder.insertNum(3)\nfinder.insertNum(1)\n# Expected: 2.0\nfinder.insertNum(5)\n# Expected: 3.0\nfinder.insertNum(4)\n# Expected: 3.5\nfinder.insertNum(2)\n# Expected: 3.0\nfinder2 = MedianFinder()\nfinder2.insertNum(10)\n# Expected: 10.0',
  E'class Solution {\n    public Object MedianFinder() {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.PriorityQueue;\nimport java.util.Collections;\n\nclass Solution {\n    static class MedianFinder {\n        private PriorityQueue<Integer> maxHeap; // smaller half (stores actual values)\n        private PriorityQueue<Integer> minHeap; // larger half\n\n        public MedianFinder() {\n            maxHeap = new PriorityQueue<>(Collections.reverseOrder()); // Max-heap\n            minHeap = new PriorityQueue<>(); // Min-heap\n        }\n\n        public void insertNum(int num) {\n            // Insert into appropriate heap\n            if (maxHeap.isEmpty() || num <= maxHeap.peek()) {\n                maxHeap.offer(num);\n            } else {\n                minHeap.offer(num);\n            }\n\n            // Rebalance: maxHeap can have at most 1 more element\n            if (maxHeap.size() > minHeap.size() + 1) {\n                minHeap.offer(maxHeap.poll());\n            } else if (minHeap.size() > maxHeap.size()) {\n                maxHeap.offer(minHeap.poll());\n            }\n        }\n\n        public double findMedian() {\n            if (maxHeap.isEmpty()) { // Should not happen if numbers are inserted\n                return 0.0;\n            }\n            if (maxHeap.size() == minHeap.size()) {\n                // Even number of elements\n                return (maxHeap.peek() + minHeap.peek()) / 2.0;\n            } else {\n                // Odd number of elements, maxHeap has the extra\n                return (double) maxHeap.peek();\n            }\n        }\n    }\n}',
  E'/**\n * @param {} \n * @return {any}\n */\nfunction MedianFinder() {\n    // Your code here\n}',
  E'class MinHeap {\n    constructor() {\n        this.heap = [];\n    }\n\n    push(val) {\n        this.heap.push(val);\n        this._bubbleUp(this.heap.length - 1);\n    }\n\n    pop() {\n        if (this.isEmpty()) return undefined;\n        if (this.heap.length === 1) return this.heap.pop();\n\n        const root = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this._bubbleDown(0);\n        return root;\n    }\n\n    peek() {\n        return this.isEmpty() ? undefined : this.heap[0];\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    isEmpty() {\n        return this.heap.length === 0;\n    }\n\n    _bubbleUp(index) {\n        while (index > 0) {\n            const parentIndex = Math.floor((index - 1) / 2);\n            if (this.heap[parentIndex] > this.heap[index]) {\n                this._swap(parentIndex, index);\n                index = parentIndex;\n            } else {\n                break;\n            }\n        }\n    }\n\n    _bubbleDown(index) {\n        const lastIndex = this.heap.length - 1;\n        while (true) {\n            let leftChildIndex = 2 * index + 1;\n            let rightChildIndex = 2 * index + 2;\n            let smallestIndex = index;\n\n            if (leftChildIndex <= lastIndex && this.heap[leftChildIndex] < this.heap[smallestIndex]) {\n                smallestIndex = leftChildIndex;\n            }\n\n            if (rightChildIndex <= lastIndex && this.heap[rightChildIndex] < this.heap[smallestIndex]) {\n                smallestIndex = rightChildIndex;\n            }\n\n            if (smallestIndex !== index) {\n                this._swap(index, smallestIndex);\n                index = smallestIndex;\n            } else {\n                break;\n            }\n        }\n    }\n\n    _swap(i, j) {\n        [this.heap[i], this.heap[j]] = [this.heap[j], this.heap[i]];\n    }\n}\n\nclass MedianFinder {\n    constructor() {\n        this.maxHeap = new MinHeap(); // Stores negative values to simulate a max-heap\n        this.minHeap = new MinHeap(); // Stores positive values as a min-heap\n    }\n\n    insertNum(num) {\n        // Insert into appropriate heap\n        // If maxHeap is empty or num is smaller than or equal to the top of maxHeap (negated)\n        if (this.maxHeap.isEmpty() || num <= -this.maxHeap.peek()) {\n            this.maxHeap.push(-num);\n        } else {\n            this.minHeap.push(num);\n        }\n\n        // Rebalance: maxHeap can have at most 1 more element\n        if (this.maxHeap.size() > this.minHeap.size() + 1) {\n            this.minHeap.push(-this.maxHeap.pop());\n        } else if (this.minHeap.size() > this.maxHeap.size()) {\n            this.maxHeap.push(-this.minHeap.pop());\n        }\n    }\n\n    findMedian() {\n        if (this.maxHeap.isEmpty()) {\n            return 0.0; // Or throw an error, depending on requirements for empty stream\n        }\n        if (this.maxHeap.size() === this.minHeap.size()) {\n            // Even number of elements\n            return (-this.maxHeap.peek() + this.minHeap.peek()) / 2;\n        } else {\n            // Odd number of elements, maxHeap has the extra\n            return -this.maxHeap.peek();\n        }\n    }\n}',
  ARRAY['two-heaps', 'heap'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'netflix-senior'],
  'two-heaps',
  '[]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
