INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-sliding-window-median',
  'Sliding Window Median',
  'medium',
  'Sliding Window Median

<!-- voice:section_check concept="Two Heaps for sliding window" -->

Problem Statement

Given an array of numbers and a window size ''k'', find the median of all contiguous subarrays of size ''k''.

Examples

~~~
Input: nums = [1, 2, -1, 3, 5], k = 2
Output: [1.5, 0.5, 1.0, 4.0]
Explanation: 
- Window [1, 2]: median = (1+2)/2 = 1.5
- Window [2, -1]: median = (2+(-1))/2 = 0.5
- Window [-1, 3]: median = (-1+3)/2 = 1.0
- Window [3, 5]: median = (3+5)/2 = 4.0
~~~

~~~
Input: nums = [1, 2, -1, 3, 5], k = 3
Output: [1.0, 2.0, 3.0]
~~~',
  '',
  '[{"input":"nums = [1, 2, -1, 3, 5], k = 2","output":"[1.5, 0.5, 1.0, 4.0]","explanation":"- Window [1, 2]: median = (1+2)/2 = 1.5"}]'::jsonb,
  'median_sliding_window',
  E'import heapq\ndef median_sliding_window(nums, k):\n    """\n    Find median of all subarrays of size k.\n\n    Args:\n        nums: List of integers\n        k: int, window size\n    Returns:\n        List of floats, median for each window\n    Example:\n        >>> median_sliding_window([1, 2, -1, 3, 5], 2)\n        [1.5, 0.5, 1.0, 4.0]\n    """\n    # TODO: Use two heaps with lazy deletion for sliding window median\n    # Hint: Track outgoing elements with a hash map, clean lazily\n    pass\n# ─── Test Cases ───\n# Standard case, k=2\n# Expected: [1.5, 0.5, 1.0, 4.0]\n# k=3\n# Expected: [1.0, 2.0, 3.0]\n# Single window\n# Expected: [2.0]\n# All same numbers\n# Expected: [5.0, 5.0, 5.0]\n# k=1 (each element is its own median)\n# Expected: [1.0, 2.0, 3.0]',
  E'import heapq\ndef median_sliding_window(nums, k):\n    """\n    Find median of all subarrays of size k.\n\n    Time Complexity: O(n log k) — n elements, heap ops O(log k)\n    Space Complexity: O(k) — heaps store window elements\n    """\n    def get_median():\n        """Get current median from heaps."""\n        if k % 2 == 1:\n            return float(-max_heap[0])\n        return (-max_heap[0] + min_heap[0]) / 2\n\n    def prune(heap):\n        """Remove delayed elements from heap top."""\n        while heap:\n            num = -heap[0] if heap is max_heap else heap[0]\n            if num in delayed:\n                heapq.heappop(heap)\n                delayed[num] -= 1\n                if delayed[num] == 0:\n                    del delayed[num]\n            else:\n                break\n\n    def make_balance():\n        """Balance the two heaps."""\n        # max_heap can have at most 1 more element\n        if len(max_heap) > len(min_heap) + 1:\n            num = -heapq.heappop(max_heap)\n            prune(max_heap)\n            heapq.heappush(min_heap, num)\n        elif len(min_heap) > len(max_heap):\n            num = heapq.heappop(min_heap)\n            prune(min_heap)\n            heapq.heappush(max_heap, -num)\n\n    def insert(num):\n        """Insert number into appropriate heap."""\n        if not max_heap or num <= -max_heap[0]:\n            heapq.heappush(max_heap, -num)\n        else:\n            heapq.heappush(min_heap, num)\n        make_balance()\n\n    def remove(num):\n        """Mark number for lazy deletion."""\n        delayed[num] = delayed.get(num, 0) + 1\n        if num <= -max_heap[0]:\n            max_size -= 1\n            if num == -max_heap[0]:\n                prune(max_heap)\n        else:\n            min_size -= 1\n            if min_heap and num == min_heap[0]:\n                prune(min_heap)\n        make_balance()\n\n    if not nums or k == 0:\n        return []\n    max_heap = []  # smaller half\n    min_heap = []  # larger half\n    delayed = {}   # lazy deletion tracker\n    # Initialize with first k elements\n    for i in range(k):\n        heapq.heappush(max_heap, -nums[i])\n    # Balance: move half to min_heap\n    for i in range(k // 2):\n        heapq.heappush(min_heap, -heapq.heappop(max_heap))\n    result = [get_median()]\n    # Slide window\n    for i in range(k, len(nums)):\n        # Remove outgoing element (nums[i-k])\n        out_num = nums[i - k]\n        in_num = nums[i]\n        # Remove out_num\n        delayed[out_num] = delayed.get(out_num, 0) + 1\n        balance = -1 if out_num <= -max_heap[0] else 1\n        # Insert in_num\n        if in_num <= -max_heap[0]:\n            heapq.heappush(max_heap, -in_num)\n            balance += 1\n        else:\n            heapq.heappush(min_heap, in_num)\n            balance -= 1\n        # Rebalance\n        if balance < 0:\n            # min_heap has more\n            heapq.heappush(max_heap, -heapq.heappop(min_heap))\n        elif balance > 0:\n            # max_heap has more\n            heapq.heappush(min_heap, -heapq.heappop(max_heap))\n        # Clean tops\n        prune(max_heap)\n        prune(min_heap)\n        result.append(get_median())\n    return result\n# ─── Test Cases ───\n# Expected: [1.5, 0.5, 1.0, 4.0]\n# Expected: [1.0, 2.0, 3.0]\n# Expected: [2.0]\n# Expected: [5.0, 5.0, 5.0]\n# Expected: [1.0, 2.0, 3.0]',
  E'class Solution {\n    public Object medianSlidingWindow(int[] nums, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.*;\n\nclass Solution {\n    public static List<Double> medianSlidingWindow(int[] nums, int k) {\n        if (nums == null || nums.length == 0 || k == 0) {\n            return new ArrayList<>();\n        }\n\n        // Max-heap for the smaller half (stores actual values)\n        // Uses a custom comparator to make it a max-heap\n        PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> b - a);\n        // Min-heap for the larger half\n        PriorityQueue<Integer> minHeap = new PriorityQueue<>();\n        // Map to track elements for lazy deletion\n        Map<Integer, Integer> delayed = new HashMap<>();\n\n        List<Double> result = new ArrayList<>();\n\n        // Helper to prune elements from the top of a heap if they are marked for deletion\n        // and then rebalance the heaps.\n        // This helper is called after any heap operation that might change the top element.\n        Runnable prune = () -> {\n            while (!maxHeap.isEmpty() && delayed.containsKey(maxHeap.peek())) {\n                delayed.put(maxHeap.peek(), delayed.get(maxHeap.peek()) - 1);\n                if (delayed.get(maxHeap.peek()) == 0) {\n                    delayed.remove(maxHeap.peek());\n                }\n                maxHeap.poll();\n            }\n            while (!minHeap.isEmpty() && delayed.containsKey(minHeap.peek())) {\n                delayed.put(minHeap.peek(), delayed.get(minHeap.peek()) - 1);\n                if (delayed.get(minHeap.peek()) == 0) {\n                    delayed.remove(minHeap.peek());\n                }\n                minHeap.poll();\n            }\n        };\n\n        // Helper to balance the heaps\n        // maxHeap can have at most 1 more element than minHeap\n        Runnable makeBalance = () -> {\n            prune.run(); // Prune before checking sizes\n            if (maxHeap.size() > minHeap.size() + 1) {\n                minHeap.offer(maxHeap.poll());\n            } else if (minHeap.size() > maxHeap.size()) {\n                maxHeap.offer(minHeap.poll());\n            }\n            prune.run(); // Prune again after balance\n        };\n\n        // Helper to get the current median\n        Callable<Double> getMedian = () -> {\n            if (k % 2 == 1) {\n                return (double) maxHeap.peek();\n            } else {\n                return ((double) maxHeap.peek() + minHeap.peek()) / 2.0;\n            }\n        };\n\n        // Initialize with the first k elements\n        for (int i = 0; i < k; i++) {\n            maxHeap.offer(nums[i]);\n        }\n        // Balance: move half to minHeap\n        for (int i = 0; i < k / 2; i++) {\n            minHeap.offer(maxHeap.poll());\n        }\n        makeBalance.run(); // Ensure initial balance and pruning\n\n        try {\n            result.add(getMedian.call());\n        } catch (Exception e) {\n            // Should not happen if k > 0\n        }\n\n        // Slide window\n        for (int i = k; i < nums.length; i++) {\n            int outNum = nums[i - k];\n            int inNum = nums[i];\n\n            // Mark outNum for lazy deletion\n            delayed.put(outNum, delayed.getOrDefault(outNum, 0) + 1);\n\n            // Track the balance change due to removal and insertion\n            // balance < 0 means minHeap effectively grew more (or maxHeap shrunk more)\n            // balance > 0 means maxHeap effectively grew more (or minHeap shrunk more)\n            int balance = 0;\n            if (outNum <= maxHeap.peek()) {\n                balance--; // outNum was in maxHeap, maxHeap effectively loses an element\n            } else {\n                balance++; // outNum was in minHeap, minHeap effectively loses an element\n            }\n\n            // Insert inNum\n            if (inNum <= maxHeap.peek()) {\n                maxHeap.offer(inNum);\n                balance++; // inNum goes to maxHeap, maxHeap effectively gains an element\n            } else {\n                minHeap.offer(inNum);\n                balance--; // inNum goes to minHeap, minHeap effectively gains an element\n            }\n\n            // Rebalance based on the net effect\n            if (balance < 0) {\n                // minHeap has more elements, move one to maxHeap\n                maxHeap.offer(minHeap.poll());\n            } else if (balance > 0) {\n                // maxHeap has more elements, move one to minHeap\n                minHeap.offer(maxHeap.poll());\n            }\n\n            // Clean tops after rebalancing\n            prune.run();\n\n            try {\n                result.add(getMedian.call());\n            } catch (Exception e) {\n                // Should not happen\n            }\n        }\n\n        return result;\n    }\n}',
  E'/**\n * @param {any, any} nums, k\n * @return {any}\n */\nfunction medianSlidingWindow(nums, k) {\n    // Your code here\n}',
  E'class Heap {\n    constructor(comparator) {\n        this.heap = [];\n        this.comparator = comparator || ((a, b) => a - b); // Min-heap by default\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    peek() {\n        return this.heap.length === 0 ? undefined : this.heap[0];\n    }\n\n    offer(val) {\n        this.heap.push(val);\n        this._bubbleUp();\n    }\n\n    poll() {\n        if (this.heap.length === 0) return undefined;\n        if (this.heap.length === 1) return this.heap.pop();\n        const val = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this._bubbleDown();\n        return val;\n    }\n\n    _bubbleUp() {\n        let idx = this.heap.length - 1;\n        while (idx > 0) {\n            let parentIdx = Math.floor((idx - 1) / 2);\n            if (this.comparator(this.heap[idx], this.heap[parentIdx]) < 0) {\n                [this.heap[idx], this.heap[parentIdx]] = [this.heap[parentIdx], this.heap[idx]];\n                idx = parentIdx;\n            } else {\n                break;\n            }\n        }\n    }\n\n    _bubbleDown() {\n        let idx = 0;\n        const lastIdx = this.heap.length - 1;\n        while (true) {\n            let leftChildIdx = 2 * idx + 1;\n            let rightChildIdx = 2 * idx + 2;\n            let smallestIdx = idx;\n\n            if (leftChildIdx <= lastIdx && this.comparator(this.heap[leftChildIdx], this.heap[smallestIdx]) < 0) {\n                smallestIdx = leftChildIdx;\n            }\n            if (rightChildIdx <= lastIdx && this.comparator(this.heap[rightChildIdx], this.heap[smallestIdx]) < 0) {\n                smallestIdx = rightChildIdx;\n            }\n\n            if (smallestIdx !== idx) {\n                [this.heap[idx], this.heap[smallestIdx]] = [this.heap[smallestIdx], this.heap[idx]];\n                idx = smallestIdx;\n            } else {\n                break;\n            }\n        }\n    }\n}\n\nfunction medianSlidingWindow(nums, k) {\n    if (!nums || nums.length === 0 || k === 0) {\n        return [];\n    }\n\n    // Max-heap for the smaller half\n    const maxHeap = new Heap((a, b) => b - a);\n    // Min-heap for the larger half\n    const minHeap = new Heap();\n    // Map to track elements for lazy deletion\n    const delayed = new Map();\n\n    const result = [];\n\n    // Helper to prune elements from the top of a heap if they are marked for deletion\n    const prune = () => {\n        while (maxHeap.size() > 0 && delayed.has(maxHeap.peek())) {\n            delayed.set(maxHeap.peek(), delayed.get(maxHeap.peek()) - 1);\n            if (delayed.get(maxHeap.peek()) === 0) {\n                delayed.delete(maxHeap.peek());\n            }\n            maxHeap.poll();\n        }\n        while (minHeap.size() > 0 && delayed.has(minHeap.peek())) {\n            delayed.set(minHeap.peek(), delayed.get(minHeap.peek()) - 1);\n            if (delayed.get(minHeap.peek()) === 0) {\n                delayed.delete(minHeap.peek());\n            }\n            minHeap.poll();\n        }\n    };\n\n    // Helper to balance the heaps\n    const makeBalance = () => {\n        prune(); // Prune before checking sizes\n        if (maxHeap.size() > minHeap.size() + 1) {\n            minHeap.offer(maxHeap.poll());\n        } else if (minHeap.size() > maxHeap.size()) {\n            maxHeap.offer(minHeap.poll());\n        }\n        prune(); // Prune again after balance\n    };\n\n    // Helper to get the current median\n    const getMedian = () => {\n        if (k % 2 === 1) {\n            return maxHeap.peek();\n        } else {\n            return (maxHeap.peek() + minHeap.peek()) / 2;\n        }\n    };\n\n    // Initialize with the first k elements\n    for (let i = 0; i < k; i++) {\n        maxHeap.offer(nums[i]);\n    }\n    // Balance: move half to minHeap\n    for (let i = 0; i < Math.floor(k / 2); i++) {\n        minHeap.offer(maxHeap.poll());\n    }\n    makeBalance(); // Ensure initial balance and pruning\n\n    result.push(getMedian());\n\n    // Slide window\n    for (let i = k; i < nums.length; i++) {\n        const outNum = nums[i - k];\n        const inNum = nums[i];\n\n        // Mark outNum for lazy deletion\n        delayed.set(outNum, (delayed.get(outNum) || 0) + 1);\n\n        // Track the balance change due to removal and insertion\n        let balance = 0;\n        if (outNum <= maxHeap.peek()) {\n            balance--; // outNum was in maxHeap, maxHeap effectively loses an element\n        } else {\n            balance++; // outNum was in minHeap, minHeap effectively loses an element\n        }\n\n        // Insert inNum\n        if (inNum <= maxHeap.peek()) {\n            maxHeap.offer(inNum);\n            balance++; // inNum goes to maxHeap, maxHeap effectively gains an element\n        } else {\n            minHeap.offer(inNum);\n            balance--; // inNum goes to minHeap, minHeap effectively gains an element\n        }\n\n        // Rebalance based on the net effect\n        if (balance < 0) {\n            // minHeap has more elements, move one to maxHeap\n            maxHeap.offer(minHeap.poll());\n        } else if (balance > 0) {\n            // maxHeap has more elements, move one to minHeap\n            minHeap.offer(maxHeap.poll());\n        }\n\n        // Clean tops after rebalancing\n        prune();\n\n        result.push(getMedian());\n    }\n\n    return result;\n}',
  ARRAY['two-heaps', 'heap'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'netflix-senior'],
  'two-heaps',
  '[{"input":"median_sliding_window([1, 2, -1, 3, 5], 2)","expected_output":"[1.5, 0.5, 1.0, 4.0]"},{"input":"median_sliding_window([1, 2, -1, 3, 5], 3)","expected_output":"[1.0, 2.0, 3.0]"},{"input":"median_sliding_window([1, 2, 3], 3)","expected_output":"[2.0]"}]'::jsonb,
  '[{"input":"median_sliding_window([5, 5, 5, 5], 2)","expected_output":"[5.0, 5.0, 5.0]"},{"input":"median_sliding_window([1, 2, 3], 1)","expected_output":"[1.0, 2.0, 3.0]"}]'::jsonb
