INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-maximize-capital',
  'Maximize Capital (IPO)',
  'medium',
  'Maximize Capital (IPO Problem)

<!-- voice:section_check concept="Two Heaps for project selection" -->

Problem Statement

Given:
- Initial capital ''c''
- Number of projects you can select ''k''
- List of capitals for ''n'' projects
- List of profits for ''n'' projects

Each project requires at least the given capital to start, and yields the given profit upon completion. Select at most ''k'' distinct projects to maximize final capital.

Examples

~~~
Input: c = 0, k = 2, capitals = [0, 1, 2], profits = [1, 2, 3]
Output: 4
Explanation:
- Start with capital 0, can only do project 0 (capital 0)
- After project 0: capital = 0 + 1 = 1
- Now can do project 1 (capital 1), profit = 2
- Final capital = 1 + 2 = 3
- Or do project 0 then 2: 0 + 1 + 3 = 4 (optimal)
~~~',
  '',
  '[{"input":"c = 0, k = 2, capitals = [0, 1, 2], profits = [1, 2, 3]","output":"4","explanation":"- Start with capital 0, can only do project 0 (capital 0)"}]'::jsonb,
  'find_maximized_capital',
  E'import heapq\ndef find_maximized_capital(k, c, capitals, profits):\n    """\n    Find maximum capital after selecting at most k projects.\n\n    Args:\n        k: int, number of projects to select\n        c: int, initial capital\n        capitals: List of integers, capital required for each project\n        profits: List of integers, profit from each project\n    Returns:\n        int: Maximum capital after k projects\n    Example:\n        >>> find_maximized_capital(2, 0, [0, 1, 2], [1, 2, 3])\n        4\n    """\n    # TODO: Use min-heap for capitals, max-heap for profits\n    # Hint: Move affordable projects to profit heap, pick max profit\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: 4\n# Can do all projects\n# Expected: 6\n# Limited initial capital\n# Expected: 6 (start with 1, can do proj 0 or 1)\n# k=0 (no projects)\n# Expected: 5\n# Single project\n# Expected: 5',
  E'import heapq\ndef find_maximized_capital(k, c, capitals, profits):\n    """\n    Find maximum capital after selecting at most k projects.\n\n    Time Complexity: O(n log n + k log n) — heap operations\n    Space Complexity: O(n) — store all projects\n    """\n    n = len(capitals)\n    # Min-heap for capitals: (capital_required, profit)\n    capital_heap = []\n    for i in range(n):\n        heapq.heappush(capital_heap, (capitals[i], profits[i]))\n    # Max-heap for profits (use negative for max-heap in Python)\n    profit_heap = []\n    current_capital = c\n    for _ in range(k):\n        # Move all affordable projects to profit heap\n        while capital_heap and capital_heap[0][0] <= current_capital:\n            cap, prof = heapq.heappop(capital_heap)\n            heapq.heappush(profit_heap, -prof)  # negative for max-heap\n        # If no affordable projects, break\n        if not profit_heap:\n            break\n        # Select most profitable project\n        current_capital += -heapq.heappop(profit_heap)\n    return current_capital\n# ─── Test Cases ───\n# Expected: 4\n# Expected: 6\n# Expected: 6\n# Expected: 5\n# Expected: 5',
  E'class Solution {\n    public Object findMaximizedCapital(int k, Object c, Object capitals, Object profits) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.*;\n\nclass Solution {\n    public static int findMaximizedCapital(int k, int c, int[] capitals, int[] profits) {\n        int n = capitals.length;\n        // Min-heap for projects based on capital required: (capital_required, profit)\n        PriorityQueue<int[]> capitalHeap = new PriorityQueue<>((a, b) -> a[0] - b[0]);\n        // Max-heap for profits of affordable projects\n        PriorityQueue<Integer> profitHeap = new PriorityQueue<>((a, b) -> b - a);\n\n        // Populate capitalHeap with all projects\n        for (int i = 0; i < n; i++) {\n            capitalHeap.offer(new int[]{capitals[i], profits[i]});\n        }\n\n        int currentCapital = c;\n\n        for (int i = 0; i < k; i++) {\n            // Move all affordable projects from capitalHeap to profitHeap\n            while (!capitalHeap.isEmpty() && capitalHeap.peek()[0] <= currentCapital) {\n                int[] project = capitalHeap.poll();\n                profitHeap.offer(project[1]); // Add profit to max-heap\n            }\n\n            // If no affordable projects, we can\'t do any more\n            if (profitHeap.isEmpty()) {\n                break;\n            }\n\n            // Select the most profitable project\n            currentCapital += profitHeap.poll();\n        }\n\n        return currentCapital;\n    }\n}',
  E'/**\n * @param {any, any, any, any} k, c, capitals, profits\n * @return {any}\n */\nfunction findMaximizedCapital(k, c, capitals, profits) {\n    // Your code here\n}',
  E'class Heap {\n    constructor(comparator) {\n        this.heap = [];\n        this.comparator = comparator || ((a, b) => a - b); // Min-heap by default\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    peek() {\n        return this.heap.length === 0 ? undefined : this.heap[0];\n    }\n\n    offer(val) {\n        this.heap.push(val);\n        this._bubbleUp();\n    }\n\n    poll() {\n        if (this.heap.length === 0) return undefined;\n        if (this.heap.length === 1) return this.heap.pop();\n        const val = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this._bubbleDown();\n        return val;\n    }\n\n    _bubbleUp() {\n        let idx = this.heap.length - 1;\n        while (idx > 0) {\n            let parentIdx = Math.floor((idx - 1) / 2);\n            if (this.comparator(this.heap[idx], this.heap[parentIdx]) < 0) {\n                [this.heap[idx], this.heap[parentIdx]] = [this.heap[parentIdx], this.heap[idx]];\n                idx = parentIdx;\n            } else {\n                break;\n            }\n        }\n    }\n\n    _bubbleDown() {\n        let idx = 0;\n        const lastIdx = this.heap.length - 1;\n        while (true) {\n            let leftChildIdx = 2 * idx + 1;\n            let rightChildIdx = 2 * idx + 2;\n            let smallestIdx = idx;\n\n            if (leftChildIdx <= lastIdx && this.comparator(this.heap[leftChildIdx], this.heap[smallestIdx]) < 0) {\n                smallestIdx = leftChildIdx;\n            }\n            if (rightChildIdx <= lastIdx && this.comparator(this.heap[rightChildIdx], this.heap[smallestIdx]) < 0) {\n                smallestIdx = rightChildIdx;\n            }\n\n            if (smallestIdx !== idx) {\n                [this.heap[idx], this.heap[smallestIdx]] = [this.heap[smallestIdx], this.heap[idx]];\n                idx = smallestIdx;\n            } else {\n                break;\n            }\n        }\n    }\n}\n\nfunction findMaximizedCapital(k, c, capitals, profits) {\n    const n = capitals.length;\n    // Min-heap for projects based on capital required: [capital_required, profit]\n    const capitalHeap = new Heap((a, b) => a[0] - b[0]);\n    // Max-heap for profits of affordable projects\n    const profitHeap = new Heap((a, b) => b - a);\n\n    // Populate capitalHeap with all projects\n    for (let i = 0; i < n; i++) {\n        capitalHeap.offer([capitals[i], profits[i]]);\n    }\n\n    let currentCapital = c;\n\n    for (let i = 0; i < k; i++) {\n        // Move all affordable projects from capitalHeap to profitHeap\n        while (capitalHeap.size() > 0 && capitalHeap.peek()[0] <= currentCapital) {\n            const project = capitalHeap.poll();\n            profitHeap.offer(project[1]); // Add profit to max-heap\n        }\n\n        // If no affordable projects, we can\'t do any more\n        if (profitHeap.size() === 0) {\n            break;\n        }\n\n        // Select the most profitable project\n        currentCapital += profitHeap.poll();\n    }\n\n    return currentCapital;\n}',
  ARRAY['two-heaps', 'heap'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'netflix-senior'],
  'two-heaps',
  '[{"input":"find_maximized_capital(2, 0, [0, 1, 2], [1, 2, 3])","expected_output":"4"},{"input":"find_maximized_capital(3, 0, [0, 1, 2], [1, 2, 3])","expected_output":"6"},{"input":"find_maximized_capital(2, 1, [0, 1, 2], [1, 2, 3])","expected_output":"6 (start with 1, can do proj 0 or 1)"}]'::jsonb,
  '[{"input":"find_maximized_capital(0, 5, [0, 1, 2], [1, 2, 3])","expected_output":"5"},{"input":"find_maximized_capital(1, 0, [0], [5])","expected_output":"5"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
