INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-generate-all-subsets',
  'Generate All Subsets',
  'medium',
  'Generate All Subsets

<!-- voice:section_check concept="BFS/DFS for subset generation" -->

Problem Statement

Given a set of distinct integers, return all possible subsets (the power set).

**Note:** The solution set must not contain duplicate subsets.

Examples

~~~
Input: [1, 2, 3]
Output: [[], [1], [2], [3], [1,2], [1,3], [2,3], [1,2,3]]
~~~

~~~
Input: [0]
Output: [[], [0]]
~~~',
  '',
  '[{"input":"[1, 2, 3]","output":"[[], [1], [2], [3], [1,2], [1,3], [2,3], [1,2,3]]"}]'::jsonb,
  'find_subsets',
  E'def find_subsets(nums):\n    """\n    Generate all subsets of a given set of distinct integers.\n\n    Args:\n        nums: List of distinct integers\n    Returns:\n        List of lists, all possible subsets\n    Example:\n        >>> find_subsets([1, 2, 3])\n        [[], [1], [2], [3], [1, 2], [1, 3], [2, 3], [1, 2, 3]]\n    """\n    # TODO: Use BFS or DFS to generate all subsets\n    # Hint: Start with empty subset, add each number to existing subsets\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: [[], [1], [2], [3], [1, 2], [1, 3], [2, 3], [1, 2, 3]]\n# Single element\n# Expected: [[], [0]]\n# Empty array\n# Expected: [[]]\n# Two elements\n# Expected: [[], [1], [2], [1, 2]]\n# Negative numbers\n# Expected: [[], [-1], [0], [1], [-1, 0], [-1, 1], [0, 1], [-1, 0, 1]]',
  E'def find_subsets(nums):\n    """\n    Generate all subsets of a given set of distinct integers.\n\n    Time Complexity: O(n × 2^n) — 2^n subsets, each up to size n\n    Space Complexity: O(n × 2^n) — store all subsets\n    """\n    subsets = [[]]  # Start with empty subset\n    for num in nums:\n        # For each existing subset, create a new subset with current number\n        n = len(subsets)\n        for i in range(n):\n            new_subset = subsets[i] + [num]\n            subsets.append(new_subset)\n    return subsets\n# ─── Test Cases ───\n# Expected: [[], [1], [2], [3], [1, 2], [1, 3], [2, 3], [1, 2, 3]]\n# Expected: [[], [0]]\n# Expected: [[]]\n# Expected: [[], [1], [2], [1, 2]]\n# Expected: [[], [-1], [0], [1], [-1, 0], [-1, 1], [0, 1], [-1, 0, 1]]',
  E'class Solution {\n    public Object findSubsets(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.*;\n\nclass Solution {\n    public static List<List<Integer>> findSubsets(int[] nums) {\n        List<List<Integer>> subsets = new ArrayList<>();\n        subsets.add(new ArrayList<>()); // Start with empty subset\n\n        for (int num : nums) {\n            // For each existing subset, create a new subset with current number\n            int n = subsets.size();\n            for (int i = 0; i < n; i++) {\n                List<Integer> currentSubset = subsets.get(i);\n                List<Integer> newSubset = new ArrayList<>(currentSubset); // Create a copy\n                newSubset.add(num);\n                subsets.add(newSubset);\n            }\n        }\n        return subsets;\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction findSubsets(nums) {\n    // Your code here\n}',
  E'function findSubsets(nums) {\n    const subsets = [[]]; // Start with empty subset\n\n    for (const num of nums) {\n        // For each existing subset, create a new subset with current number\n        const n = subsets.length;\n        for (let i = 0; i < n; i++) {\n            const currentSubset = subsets[i];\n            const newSubset = [...currentSubset, num]; // Create a copy and add num\n            subsets.push(newSubset);\n        }\n    }\n    return subsets;\n}',
  ARRAY['subsets'],
