INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-balanced-parentheses',
  'Balanced Parentheses',
  'hard',
  'Balanced Parentheses

<!-- voice:section_check concept="Generating balanced parentheses" -->

Problem Statement

Given ''n'', generate all combinations of well-formed (balanced) parentheses with n pairs.

Examples

~~~
Input: n = 2
Output: ["(())", "()()"]
~~~

~~~
Input: n = 3
Output: ["((()))", "(()())", "(())()", "()(())", "()()()"]
~~~',
  'Can add ''('' if count of open < n
Can add '')'' if count of close < count of open

<!-- voice:key_insight insight="To maintain balance: can always add ''('' if we haven''t used all; can add '')'' only if it won''t exceed ''('' count" -->

<!-- voice:exercise_intro difficulty="medium" hints_available="3" -->',
  '[{"input":"n = 2","output":"[\"(())\", \"()()\"]"}]'::jsonb,
  'generate_balanced_parentheses',
  E'def generate_balanced_parentheses(n):\n    """\n    Generate all combinations of well-formed parentheses.\n\n    Args:\n        n: int, number of pairs of parentheses\n    Returns:\n        List of strings, all valid combinations\n    Example:\n        >>> generate_balanced_parentheses(2)\n        [''(())'', ''()()'']\n    """\n    # TODO: Use DFS with open/close count constraints\n    # Hint: Add ''('' if open < n, add '')'' if close < open\n    pass\n# ─── Test Cases ───\n# n=2\n# Expected: [''(())'', ''()()'']\n# n=3\n# Expected: [''((()))'', ''(()())'', ''(())()'', ''()(())'', ''()()()'']\n# n=1\n# Expected: [''()'']\n# Check count for n=4 (Catalan number C4 = 14)\n# Expected: 14',
  E'def generate_balanced_parentheses(n):\n    """\n    Generate all combinations of well-formed parentheses.\n\n    Time Complexity: O(n × 4^n / √n) — Catalan number\n    Space Complexity: O(n × 4^n / √n)\n    """\n    def backtrack(current, open_count, close_count):\n        # Base case: used all parentheses\n        if len(current) == 2 * n:\n            result.append(current)\n            return\n\n        # Can add ''('' if we haven''t used all n\n        if open_count < n:\n            backtrack(current + ''('', open_count + 1, close_count)\n        # Can add '')'' if it won''t exceed open count\n        if close_count < open_count:\n            backtrack(current + '')'', open_count, close_count + 1)\n    result = []\n    backtrack("", 0, 0)\n    return result\n# ─── Test Cases ───\n# Expected: [''(())'', ''()()'']\n# Expected: [''((()))'', ''(()())'', ''(())()'', ''()(())'', ''()()()'']\n# Expected: [''()'']\n# Expected: 14',
  E'class Solution {\n    public Object generateBalancedParentheses(int n) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayList;\nimport java.util.List;\n\nclass Solution {\n    public static List<String> generateBalancedParentheses(int n) {\n        List<String> result = new ArrayList<>();\n        backtrack(result, "", 0, 0, n);\n        return result;\n    }\n\n    private static void backtrack(List<String> result, String current, int openCount, int closeCount, int n) {\n        // Base case: used all parentheses\n        if (current.length() == 2 * n) {\n            result.add(current);\n            return;\n        }\n\n        // Can add \'(\' if open_count is less than n\n        if (openCount < n) {\n            backtrack(result, current + "(", openCount + 1, closeCount, n);\n        }\n\n        // Can add \')\' if close_count is less than open_count\n        if (closeCount < openCount) {\n            backtrack(result, current + ")", openCount, closeCount + 1, n);\n        }\n    }\n}''('' if we haven''t used all n\n    //         if open_count < n:\n    //             backtrack(current + ''('', open_count + 1, close_count)\n    //         \n    //         # Can add '')'' if it won''t exceed open count\n    //         if close_count < open_count:\n    //             backtrack(current + '')'', open_count, close_count + 1)\n    //     \n    //     result = []\n    //     backtrack("", 0, 0)\n    //     return result\n    // \n    // \n    // # ─── Test Cases ───\n    // # Expected: [''(())'', ''()()'']\n    // \n    // # Expected: [''((()))'', ''(()())'', ''(())()'', ''()(())'', ''()()()'']\n    // \n    // # Expected: [''()'']\n    // \n    // # Expected: 14\n    // \n}',
  E'/**\n * @param {any} n\n * @return {any}\n */\nfunction generateBalancedParentheses(n) {\n    // Your code here\n}',
  E'function generateBalancedParentheses(n) {\n    const result = [];\n\n    function backtrack(current, openCount, closeCount) {\n        // Base case: used all parentheses\n        if (current.length === 2 * n) {\n            result.push(current);\n            return;\n        }\n\n        // Can add \'(\' if openCount is less than n\n        if (openCount < n) {\n            backtrack(current + "(", openCount + 1, closeCount);\n        }\n\n        // Can add \')\' if closeCount is less than openCount\n        if (closeCount < openCount) {\n            backtrack(current + ")", openCount, closeCount + 1);\n        }\n    }\n\n    backtrack("", 0, 0);\n    return result;\n}',
  ARRAY['subsets'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'airbnb-swe'],
  'subsets',
  '[{"input":"generate_balanced_parentheses(2)","expected_output":"[''(())'', ''()()'']"},{"input":"generate_balanced_parentheses(3)","expected_output":"[''((()))'', ''(()())'', ''(())()'', ''()(())'', ''()()()'']"},{"input":"generate_balanced_parentheses(1)","expected_output":"[''()'']"}]'::jsonb,
