INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-order-agnostic-binary-search',
  'Order-Agnostic Binary Search',
  'medium',
  'Order-Agnostic Binary Search

<!-- voice:section_check concept="Binary search without knowing order" -->

Problem Statement

Given a sorted array, search for a target. The array could be sorted in ascending or descending order.

Examples

~~~
Input: arr = [4, 6, 10], target = 10
Output: 2
Explanation: Array is ascending
~~~

~~~
Input: arr = [10, 6, 4], target = 10
Output: 0
Explanation: Array is descending
~~~',
  '',
  '[{"input":"arr = [4, 6, 10], target = 10","output":"2","explanation":"Array is ascending"}]'::jsonb,
  'order_agnostic_binary_search',
  E'def order_agnostic_binary_search(arr, target):\n    """\n    Binary search when array order (asc/desc) is unknown.\n\n    Args:\n        arr: Sorted array (ascending or descending)\n        target: Value to search for\n    Returns:\n        int: Index of target, or -1 if not found\n    Example:\n        >>> order_agnostic_binary_search([4, 6, 10], 10)\n        2\n        >>> order_agnostic_binary_search([10, 6, 4], 10)\n        0\n    """\n    # TODO: Determine order, then apply appropriate binary search\n    # Hint: Compare arr[0] and arr[-1] to determine if ascending\n    pass\n# ─── Test Cases ───\n# Ascending order\n# Expected: 4\n# Descending order\n# Expected: 2\n# Target not found\n# Expected: -1\n# Single element\n# Expected: 0\n# Two elements ascending\n# Expected: 1\n# Two elements descending\n# Expected: 0',
  E'def order_agnostic_binary_search(arr, target):\n    """\n    Binary search when array order (asc/desc) is unknown.\n\n    Time Complexity: O(log n)\n    Space Complexity: O(1)\n    """\n    if not arr:\n        return -1\n    # Determine if array is ascending or descending\n    is_ascending = arr[0] < arr[-1]\n    left, right = 0, len(arr) - 1\n    while left <= right:\n        mid = left + (right - left) // 2\n        if arr[mid] == target:\n            return mid\n        if is_ascending:\n            # Standard binary search for ascending\n            if arr[mid] < target:\n                left = mid + 1\n            else:\n                right = mid - 1\n        else:\n            # Reversed binary search for descending\n            if arr[mid] < target:\n                right = mid - 1\n            else:\n                left = mid + 1\n    return -1\n# ─── Test Cases ───\n# Expected: 4\n# Expected: 2\n# Expected: -1\n# Expected: 0\n# Expected: 1\n# Expected: 0',
  E'class Solution {\n    public Object orderAgnosticBinarySearch(int[] arr, int target) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int orderAgnosticBinarySearch(int[] arr, int target) {\n        if (arr == null || arr.length == 0) {\n            return -1;\n        }\n\n        boolean isAscending = arr[0] < arr[arr.length - 1];\n        int left = 0;\n        int right = arr.length - 1;\n\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n\n            if (arr[mid] == target) {\n                return mid;\n            }\n\n            if (isAscending) {\n                // Standard binary search for ascending\n                if (arr[mid] < target) {\n                    left = mid + 1;\n                } else {\n                    right = mid - 1;\n                }\n            } else {\n                // Reversed binary search for descending\n                if (arr[mid] < target) {\n                    right = mid - 1;\n                } else {\n                    left = mid + 1;\n                }\n            }\n        }\n        return -1;\n    }\n}',
  E'/**\n * @param {any, any} arr, target\n * @return {any}\n */\nfunction orderAgnosticBinarySearch(arr, target) {\n    // Your code here\n}',
  E'function orderAgnosticBinarySearch(arr, target) {\n    if (!arr || arr.length === 0) {\n        return -1;\n    }\n\n    const isAscending = arr[0] < arr[arr.length - 1];\n    let left = 0;\n    let right = arr.length - 1;\n\n    while (left <= right) {\n        const mid = Math.floor(left + (right - left) / 2);\n\n        if (arr[mid] === target) {\n            return mid;\n        }\n\n        if (isAscending) {\n            // Standard binary search for ascending\n            if (arr[mid] < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        } else {\n            // Reversed binary search for descending\n            if (arr[mid] < target) {\n                right = mid - 1;\n            } else {\n                left = mid + 1;\n            }\n        }\n    }\n    return -1;\n}',
  ARRAY['modified-binary-search'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'modified-binary-search',
  '[{"input":"order_agnostic_binary_search([1, 2, 3, 4, 5, 6, 7], 5)","expected_output":"4"},{"input":"order_agnostic_binary_search([10, 8, 6, 4, 2], 6)","expected_output":"2"},{"input":"order_agnostic_binary_search([1, 2, 3], 10)","expected_output":"-1"}]'::jsonb,
  '[{"input":"order_agnostic_binary_search([5], 5)","expected_output":"0"},{"input":"order_agnostic_binary_search([1, 3], 3)","expected_output":"1"},{"input":"order_agnostic_binary_search([5, 3], 5)","expected_output":"0"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
