INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-search-rotated-array',
  'Search in Rotated Array',
  'medium',
  'Search in Rotated Sorted Array

<!-- voice:section_check concept="Binary search in rotated array" -->

Problem Statement

Given a sorted array that has been rotated at some pivot point, search for a target value.

**Note:** Array contains distinct elements.

Examples

~~~
Input: arr = [10, 15, 1, 3, 8], target = 15
Output: 1
Explanation: Original sorted array [1, 3, 8, 10, 15] was rotated at 10
~~~

~~~
Input: arr = [4, 5, 7, 9, 10, -1, 2], target = -1
Output: 5
~~~',
  '',
  '[{"input":"arr = [10, 15, 1, 3, 8], target = 15","output":"1","explanation":"Original sorted array [1, 3, 8, 10, 15] was rotated at 10"}]'::jsonb,
  'search_rotated_array',
  E'def search_rotated_array(arr, target):\n    """\n    Search for target in a rotated sorted array with distinct elements.\n\n    Args:\n        arr: Rotated sorted array with distinct elements\n        target: Value to search for\n    Returns:\n        int: Index of target, or -1 if not found\n    Example:\n        >>> search_rotated_array([10, 15, 1, 3, 8], 15)\n        1\n    """\n    # TODO: Binary search determining which half is sorted\n    # Hint: Check if left half is sorted, then check if target is in range\n    pass\n# ─── Test Cases ───\n# Standard rotated array\n# Expected: 1\n# Target in second half\n# Expected: 5\n# Not rotated\n# Expected: 2\n# Target not found\n# Expected: -1\n# Single element\n# Expected: 0\n# Two elements rotated\n# Expected: 1',
  E'def search_rotated_array(arr, target):\n    """\n    Search for target in a rotated sorted array with distinct elements.\n\n    Time Complexity: O(log n)\n    Space Complexity: O(1)\n    """\n    left, right = 0, len(arr) - 1\n    while left <= right:\n        mid = left + (right - left) // 2\n        if arr[mid] == target:\n            return mid\n        # Determine which half is sorted\n        if arr[left] <= arr[mid]:\n            # Left half is sorted\n            if arr[left] <= target < arr[mid]:\n                # Target in left half\n                right = mid - 1\n            else:\n                # Target in right half\n                left = mid + 1\n        else:\n            # Right half is sorted\n            if arr[mid] < target <= arr[right]:\n                # Target in right half\n                left = mid + 1\n            else:\n                # Target in left half\n                right = mid - 1\n    return -1\n# ─── Test Cases ───\n# Expected: 1\n# Expected: 5\n# Expected: 2\n# Expected: -1\n# Expected: 0\n# Expected: 1',
  E'class Solution {\n    public Object searchRotatedArray(int[] arr, int target) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int searchRotatedArray(int[] arr, int target) {\n        if (arr == null || arr.length == 0) {\n            return -1;\n        }\n\n        int left = 0;\n        int right = arr.length - 1;\n\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n\n            if (arr[mid] == target) {\n                return mid;\n            }\n\n            // Determine which half is sorted\n            if (arr[left] <= arr[mid]) {\n                // Left half is sorted\n                if (arr[left] <= target && target < arr[mid]) {\n                    // Target in left half\n                    right = mid - 1;\n                } else {\n                    // Target in right half\n                    left = mid + 1;\n                }\n            } else {\n                // Right half is sorted\n                if (arr[mid] < target && target <= arr[right]) {\n                    // Target in right half\n                    left = mid + 1;\n                } else {\n                    // Target in left half\n                    right = mid - 1;\n                }\n            }\n        }\n        return -1;\n    }\n}',
  E'/**\n * @param {any, any} arr, target\n * @return {any}\n */\nfunction searchRotatedArray(arr, target) {\n    // Your code here\n}',
  E'function searchRotatedArray(arr, target) {\n    if (!arr || arr.length === 0) {\n        return -1;\n    }\n\n    let left = 0;\n    let right = arr.length - 1;\n\n    while (left <= right) {\n        const mid = Math.floor(left + (right - left) / 2);\n\n        if (arr[mid] === target) {\n            return mid;\n        }\n\n        // Determine which half is sorted\n        if (arr[left] <= arr[mid]) {\n            // Left half is sorted\n            if (arr[left] <= target && target < arr[mid]) {\n                // Target in left half\n                right = mid - 1;\n            } else {\n                // Target in right half\n                left = mid + 1;\n            }\n        } else {\n            // Right half is sorted\n            if (arr[mid] < target && target <= arr[right]) {\n                // Target in right half\n                left = mid + 1;\n            } else {\n                // Target in left half\n                right = mid - 1;\n            }\n        }\n    }\n    return -1;\n}',
  ARRAY['modified-binary-search'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'modified-binary-search',
  '[{"input":"search_rotated_array([10, 15, 1, 3, 8], 15)","expected_output":"1"},{"input":"search_rotated_array([4, 5, 7, 9, 10, -1, 2], -1)","expected_output":"5"},{"input":"search_rotated_array([1, 2, 3, 4, 5], 3)","expected_output":"2"}]'::jsonb,
  '[{"input":"search_rotated_array([10, 15, 1, 3, 8], 20)","expected_output":"-1"},{"input":"search_rotated_array([5], 5)","expected_output":"0"},{"input":"search_rotated_array([2, 1], 1)","expected_output":"1"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
