INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-find-minimum-rotated',
  'Find Minimum in Rotated Array',
  'medium',
  'Find Minimum in Rotated Sorted Array

<!-- voice:section_check concept="Finding minimum in rotated array" -->

Problem Statement

Find the minimum element in a sorted array that has been rotated.

Examples

~~~
Input: [10, 15, 1, 3, 8]
Output: 1
~~~

~~~
Input: [4, 5, 7, 9, 10, -1, 2]
Output: -1
~~~',
  '',
  '[{"input":"[10, 15, 1, 3, 8]","output":"1"}]'::jsonb,
  'find_minimum_rotated',
  E'def find_minimum_rotated(arr):\n    """\n    Find the minimum element in a rotated sorted array.\n\n    Args:\n        arr: Rotated sorted array\n    Returns:\n        int: Minimum element\n    Example:\n        >>> find_minimum_rotated([10, 15, 1, 3, 8])\n        1\n    """\n    # TODO: Binary search to find minimum\n    # Hint: Check if array is not rotated first; otherwise find unsorted half\n    pass\n# ─── Test Cases ───\n# Standard rotated\n# Expected: 1\n# Rotated at different point\n# Expected: -1\n# Not rotated\n# Expected: 1\n# Single element\n# Expected: 5\n# Two elements\n# Expected: 1\n# Rotated once\n# Expected: 1',
  E'def find_minimum_rotated(arr):\n    """\n    Find the minimum element in a rotated sorted array.\n\n    Time Complexity: O(log n)\n    Space Complexity: O(1)\n    """\n    if not arr:\n        return None\n    left, right = 0, len(arr) - 1\n    # Array not rotated\n    if arr[left] < arr[right]:\n        return arr[left]\n    while left < right:\n        mid = left + (right - left) // 2\n        # Check if mid is the minimum\n        if mid > 0 and arr[mid] < arr[mid - 1]:\n            return arr[mid]\n        # Determine which half contains minimum\n        if arr[mid] > arr[right]:\n            # Minimum is in right half\n            left = mid + 1\n        else:\n            # arr[mid] < arr[right], minimum is in left half (including mid)\n            # Note: can''t be mid+1 to right since arr[mid] <= arr[right]\n            right = mid\n    return arr[left]\n# ─── Test Cases ───\n# Expected: 1\n# Expected: -1\n# Expected: 1\n# Expected: 5\n# Expected: 1\n# Expected: 1',
  E'class Solution {\n    public Object findMinimumRotated(int[] arr) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static Integer findMinimumRotated(int[] arr) {\n        if (arr == null || arr.length == 0) {\n            return null;\n        }\n\n        int left = 0;\n        int right = arr.length - 1;\n\n        // Array not rotated\n        if (arr[left] < arr[right]) {\n            return arr[left];\n        }\n\n        while (left < right) {\n            int mid = left + (right - left) / 2;\n\n            // Check if mid is the minimum\n            if (mid > 0 && arr[mid] < arr[mid - 1]) {\n                return arr[mid];\n            }\n\n            // Determine which half contains minimum\n            if (arr[mid] > arr[right]) {\n                // Minimum is in right half\n                left = mid + 1;\n            } else {\n                // arr[mid] <= arr[right], minimum is in left half (including mid)\n                right = mid;\n            }\n        }\n        return arr[left]; // When left == right, this is the minimum\n    }\n}''t be mid+1 to right since arr[mid] <= arr[right]\n    //             right = mid\n    //     \n    //     return arr[left]\n    // \n    // \n    // # ─── Test Cases ───\n    // # Expected: 1\n    // \n    // # Expected: -1\n    // \n    // # Expected: 1\n    // \n    // # Expected: 5\n    // \n    // # Expected: 1\n    // \n    // # Expected: 1\n    // \n}',
  E'/**\n * @param {any} arr\n * @return {any}\n */\nfunction findMinimumRotated(arr) {\n    // Your code here\n}',
  E'function findMinimumRotated(arr) {\n    if (!arr || arr.length === 0) {\n        return null;\n    }\n\n    let left = 0;\n    let right = arr.length - 1;\n\n    // Array not rotated\n    if (arr[left] < arr[right]) {\n        return arr[left];\n    }\n\n    while (left < right) {\n        const mid = Math.floor(left + (right - left) / 2);\n\n        // Check if mid is the minimum\n        if (mid > 0 && arr[mid] < arr[mid - 1]) {\n            return arr[mid];\n        }\n\n        // Determine which half contains minimum\n        if (arr[mid] > arr[right]) {\n            // Minimum is in right half\n            left = mid + 1;\n        } else {\n            // arr[mid] <= arr[right], minimum is in left half (including mid)\n            right = mid;\n        }\n    }\n    return arr[left]; // When left == right, this is the minimum\n}',
  ARRAY['modified-binary-search'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'modified-binary-search',
  '[{"input":"find_minimum_rotated([10, 15, 1, 3, 8])","expected_output":"1"},{"input":"find_minimum_rotated([4, 5, 7, 9, 10, -1, 2])","expected_output":"-1"},{"input":"find_minimum_rotated([1, 2, 3, 4, 5])","expected_output":"1"}]'::jsonb,
  '[{"input":"find_minimum_rotated([5])","expected_output":"5"},{"input":"find_minimum_rotated([2, 1])","expected_output":"1"},{"input":"find_minimum_rotated([3, 1, 2])","expected_output":"1"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
