INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-kth-largest-element',
  'Kth Largest Element in Array',
  'medium',
  'Kth Largest Element in Array

<!-- voice:section_check concept="Min-heap for kth largest" -->

Problem Statement

Given an integer array `nums` and an integer `k`, return the `kth` largest element in the array.

Note that it is the `kth` largest element in sorted order, not the `kth` distinct element.

Examples

~~~
Input: nums = [3, 2, 1, 5, 6, 4], k = 2
Output: 5
Explanation: Sorted: [1, 2, 3, 4, 5, 6], 2nd largest is 5
~~~

~~~
Input: nums = [3, 2, 3, 1, 2, 4, 5, 5, 6], k = 4
Output: 4
~~~',
  '',
  '[{"input":"nums = [3, 2, 1, 5, 6, 4], k = 2","output":"5","explanation":"Sorted: [1, 2, 3, 4, 5, 6], 2nd largest is 5"}]'::jsonb,
  'find_kth_largest',
  E'import heapq\ndef find_kth_largest(nums, k):\n    """\n    Find the kth largest element in an unsorted array.\n\n    Args:\n        nums: List of integers\n        k: int, which largest element to find\n    Returns:\n        int: The kth largest element\n    Example:\n        >>> find_kth_largest([3, 2, 1, 5, 6, 4], 2)\n        5\n        >>> find_kth_largest([3, 2, 3, 1, 2, 4, 5, 5, 6], 4)\n        4\n    """\n    # TODO: Use min-heap of size k to find kth largest\n    # Hint: Heap will contain k largest elements, top is the kth largest\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: 5\n# With duplicates\n# Expected: 4\n# k=1 (largest element)\n# Expected: 5\n# k=n (smallest element)\n# Expected: 1\n# Single element\n# Expected: 42\n# All same elements\n# Expected: 5',
  E'import heapq\ndef find_kth_largest(nums, k):\n    """\n    Find the kth largest element in an unsorted array.\n\n    Time Complexity: O(n log k) — heap operations for n elements\n    Space Complexity: O(k) — min-heap of size k\n    """\n    min_heap = []\n    for num in nums:\n        if len(min_heap) < k:\n            heapq.heappush(min_heap, num)\n        elif num > min_heap[0]:\n            # Current num is larger than kth largest so far\n            heapq.heapreplace(min_heap, num)\n    # Top of min-heap is the kth largest\n    return min_heap[0]\n# Alternative using max-heap (negate all numbers)\ndef find_kth_largest_max_heap(nums, k):\n    """\n    Alternative using max-heap approach.\n    """\n    # Negate all numbers to simulate max-heap\n    max_heap = [-num for num in nums]\n    heapq.heapify(max_heap)\n\n    # Pop k-1 largest elements\n    for _ in range(k - 1):\n        heapq.heappop(max_heap)\n    # Next pop is kth largest\n    return -heapq.heappop(max_heap)\n# ─── Test Cases ───\n# Expected: 5\n# Expected: 4\n# Expected: 5\n# Expected: 1\n# Expected: 42\n# Expected: 5',
  E'class Solution {\n    public Object findKthLargest(int[] nums, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.PriorityQueue;\n\nclass Solution {\n    public static int findKthLargest(int[] nums, int k) {\n        // Min-heap to store the k largest elements\n        PriorityQueue<Integer> minHeap = new PriorityQueue<>();\n\n        for (int num : nums) {\n            if (minHeap.size() < k) {\n                minHeap.offer(num);\n            } else if (num > minHeap.peek()) {\n                // Current num is larger than the smallest in the heap (kth largest so far)\n                minHeap.poll(); // Remove the smallest\n                minHeap.offer(num); // Add the new larger number\n            }\n        }\n        // The top of the min-heap is the kth largest element\n        return minHeap.peek();\n    }\n}',
  E'/**\n * @param {any, any} nums, k\n * @return {any}\n */\nfunction findKthLargest(nums, k) {\n    // Your code here\n}',
  E'class MinHeap {\n    constructor(comparator = (a, b) => a - b) {\n        this.heap = [];\n        this.comparator = comparator;\n    }\n\n    getParentIndex(i) { return Math.floor((i - 1) / 2); }\n    getLeftChildIndex(i) { return 2 * i + 1; }\n    getRightChildIndex(i) { return 2 * i + 2; }\n\n    hasParent(i) { return this.getParentIndex(i) >= 0; }\n    hasLeftChild(i) { return this.getLeftChildIndex(i) < this.heap.length; }\n    hasRightChild(i) { return this.getRightChildIndex(i) < this.heap.length; }\n\n    getParent(i) { return this.heap[this.getParentIndex(i)]; }\n    getLeftChild(i) { return this.heap[this.getLeftChildIndex(i)]; }\n    getRightChild(i) { return this.heap[this.getRightChildIndex(i)]; }\n\n    peek() {\n        if (this.heap.length === 0) return null;\n        return this.heap[0];\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    swap(i, j) {\n        [this.heap[i], this.heap[j]] = [this.heap[j], this.heap[i]];\n    }\n\n    push(item) {\n        this.heap.push(item);\n        this.heapifyUp();\n    }\n\n    pop() {\n        if (this.heap.length === 0) return null;\n        if (this.heap.length === 1) return this.heap.pop();\n\n        const item = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this.heapifyDown();\n        return item;\n    }\n\n    heapifyUp() {\n        let index = this.heap.length - 1;\n        while (this.hasParent(index) && this.comparator(this.getParent(index), this.heap[index]) > 0) {\n            this.swap(this.getParentIndex(index), index);\n            index = this.getParentIndex(index);\n        }\n    }\n\n    heapifyDown() {\n        let index = 0;\n        while (this.hasLeftChild(index)) {\n            let smallerChildIndex = this.getLeftChildIndex(index);\n            if (this.hasRightChild(index) && this.comparator(this.getRightChild(index), this.getLeftChild(index)) < 0) {\n                smallerChildIndex = this.getRightChildIndex(index);\n            }\n\n            if (this.comparator(this.heap[index], this.heap[smallerChildIndex]) < 0) {\n                break;\n            } else {\n                this.swap(index, smallerChildIndex);\n            }\n            index = smallerChildIndex;\n        }\n    }\n}\n\nfunction findKthLargest(nums, k) {\n    const minHeap = new MinHeap();\n\n    for (const num of nums) {\n        if (minHeap.size() < k) {\n            minHeap.push(num);\n        } else if (num > minHeap.peek()) {\n            minHeap.pop();\n            minHeap.push(num);\n        }\n    }\n    return minHeap.peek();\n}',
  ARRAY['top-k-elements'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'netflix-senior', 'uber-sde2'],
  'top-k-elements',
  '[{"input":"find_kth_largest([3, 2, 1, 5, 6, 4], 2)","expected_output":"5"},{"input":"find_kth_largest([3, 2, 3, 1, 2, 4, 5, 5, 6], 4)","expected_output":"4"},{"input":"find_kth_largest([1, 2, 3, 4, 5], 1)","expected_output":"5"}]'::jsonb,
  '[{"input":"find_kth_largest([1, 2, 3, 4, 5], 5)","expected_output":"1"},{"input":"find_kth_largest([42], 1)","expected_output":"42"},{"input":"find_kth_largest([5, 5, 5, 5], 2)","expected_output":"5"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
