INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-kth-smallest-sorted-matrix',
  'Kth Smallest Element in Sorted Matrix',
  'medium',
  'Kth Smallest Element in Sorted Matrix

<!-- voice:section_check concept="Heap for kth smallest in sorted matrix" -->

Problem Statement

Given an `n x n` matrix where each of the rows and columns is sorted in ascending order, return the `kth` smallest element in the matrix.

Examples

~~~
Input: matrix = [[1, 5, 9], [10, 11, 13], [12, 13, 15]], k = 8
Output: 13
Explanation: Elements in sorted order: [1, 5, 9, 10, 11, 12, 13, 13, 15]
                                      1st          ...           8th
~~~

~~~
Input: matrix = [[-5]], k = 1
Output: -5
~~~',
  '',
  '[{"input":"matrix = [[1, 5, 9], [10, 11, 13], [12, 13, 15]], k = 8","output":"13","explanation":"Elements in sorted order: [1, 5, 9, 10, 11, 12, 13, 13, 15]"}]'::jsonb,
  'kth_smallest_matrix',
  E'import heapq\ndef kth_smallest_matrix(matrix, k):\n    """\n    Find kth smallest element in a sorted n x n matrix.\n\n    Args:\n        matrix: n x n matrix where rows and columns are sorted\n        k: int, which smallest element to find\n    Returns:\n        int: The kth smallest element\n    Example:\n        >>> kth_smallest_matrix([[1, 5, 9], [10, 11, 13], [12, 13, 15]], 8)\n        13\n    """\n    # TODO: Use min-heap to merge sorted rows\n    # Hint: Start with first element of each row, track (value, row, col)\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: 13\n# Single element\n# Expected: -5\n# k=1 (smallest)\n# Expected: 1\n# k=n*n (largest)\n# Expected: 4\n# 2x2 matrix\n# Expected: 3',
  E'import heapq\ndef kth_smallest_matrix(matrix, k):\n    """\n    Find kth smallest element in a sorted n x n matrix.\n\n    Time Complexity: O(k log n) — k heap operations, heap size n\n    Space Complexity: O(n) — heap stores one element per row max\n    """\n    n = len(matrix)\n    # Min-heap: (value, row, col)\n    # Start with first element of each row\n    min_heap = []\n    for r in range(min(n, k)):  # Only need first k rows\n        min_heap.append((matrix[r][0], r, 0))\n    heapq.heapify(min_heap)\n    # Pop k-1 smallest elements\n    for _ in range(k - 1):\n        val, row, col = heapq.heappop(min_heap)\n        # Push next element from same row if exists\n        if col + 1 < n:\n            heapq.heappush(min_heap, (matrix[row][col + 1], row, col + 1))\n    # kth smallest is at heap top\n    return min_heap[0][0]\n# Alternative: Binary Search approach (O(n log(max-min)))\ndef kth_smallest_binary_search(matrix, k):\n    """\n    Alternative using binary search on value range.\n    """\n    n = len(matrix)\n\n    def count_less_equal(mid):\n        """Count elements <= mid in sorted matrix."""\n        count = 0\n        row, col = n - 1, 0  # Start from bottom-left\n\n        while row >= 0 and col < n:\n            if matrix[row][col] <= mid:\n                # All elements in this column up to row are <= mid\n                count += row + 1\n                col += 1\n            else:\n                row -= 1\n        return count\n    left, right = matrix[0][0], matrix[n-1][n-1]\n    while left < right:\n        mid = left + (right - left) // 2\n        if count_less_equal(mid) < k:\n            left = mid + 1\n        else:\n            right = mid\n    return left\n# ─── Test Cases ───\n# Expected: 13\n# Expected: -5\n# Expected: 1\n# Expected: 4\n# Expected: 3',
  E'class Solution {\n    public Object kthSmallestMatrix(int[][] matrix, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.PriorityQueue;\n\nclass Solution {\n    public static int kthSmallestMatrix(int[][] matrix, int k) {\n        int n = matrix.length;\n        // Min-heap stores int[]: {value, row, col}\n        // Compares based on value (int[0])\n        PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> a[0] - b[0]);\n\n        // Add the first element of each row to the min-heap\n        for (int r = 0; r < Math.min(n, k); r++) {\n            minHeap.offer(new int[]{matrix[r][0], r, 0});\n        }\n\n        // Pop k-1 smallest elements\n        for (int i = 0; i < k - 1; i++) {\n            int[] current = minHeap.poll();\n            int row = current[1];\n            int col = current[2];\n\n            // If there\'s a next element in the same row, add it to the heap\n            if (col + 1 < n) {\n                minHeap.offer(new int[]{matrix[row][col + 1], row, col + 1});\n            }\n        }\n        // The kth smallest is at the top of the heap\n        return minHeap.peek()[0];\n    }\n}',
  E'/**\n * @param {any, any} matrix, k\n * @return {any}\n */\nfunction kthSmallestMatrix(matrix, k) {\n    // Your code here\n}',
  E'class MinHeap {\n    constructor(comparator = (a, b) => a - b) {\n        this.heap = [];\n        this.comparator = comparator;\n    }\n\n    getParentIndex(i) { return Math.floor((i - 1) / 2); }\n    getLeftChildIndex(i) { return 2 * i + 1; }\n    getRightChildIndex(i) { return 2 * i + 2; }\n\n    hasParent(i) { return this.getParentIndex(i) >= 0; }\n    hasLeftChild(i) { return this.getLeftChildIndex(i) < this.heap.length; }\n    hasRightChild(i) { return this.getRightChildIndex(i) < this.heap.length; }\n\n    getParent(i) { return this.heap[this.getParentIndex(i)]; }\n    getLeftChild(i) { return this.heap[this.getLeftChildIndex(i)]; }\n    getRightChild(i) { return this.heap[this.getRightChildIndex(i)]; }\n\n    peek() {\n        if (this.heap.length === 0) return null;\n        return this.heap[0];\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    swap(i, j) {\n        [this.heap[i], this.heap[j]] = [this.heap[j], this.heap[i]];\n    }\n\n    push(item) {\n        this.heap.push(item);\n        this.heapifyUp();\n    }\n\n    pop() {\n        if (this.heap.length === 0) return null;\n        if (this.heap.length === 1) return this.heap.pop();\n\n        const item = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this.heapifyDown();\n        return item;\n    }\n\n    heapifyUp() {\n        let index = this.heap.length - 1;\n        while (this.hasParent(index) && this.comparator(this.getParent(index), this.heap[index]) > 0) {\n            this.swap(this.getParentIndex(index), index);\n            index = this.getParentIndex(index);\n        }\n    }\n\n    heapifyDown() {\n        let index = 0;\n        while (this.hasLeftChild(index)) {\n            let smallerChildIndex = this.getLeftChildIndex(index);\n            if (this.hasRightChild(index) && this.comparator(this.getRightChild(index), this.getLeftChild(index)) < 0) {\n                smallerChildIndex = this.getRightChildIndex(index);\n            }\n\n            if (this.comparator(this.heap[index], this.heap[smallerChildIndex]) < 0) {\n                break;\n            } else {\n                this.swap(index, smallerChildIndex);\n            }\n            index = smallerChildIndex;\n        }\n    }\n}\n\nfunction kthSmallestMatrix(matrix, k) {\n    const n = matrix.length;\n    const minHeap = new MinHeap((a, b) => a[0] - b[0]);\n\n    for (let r = 0; r < Math.min(n, k); r++) {\n        minHeap.push([matrix[r][0], r, 0]);\n    }\n\n    for (let i = 0; i < k - 1; i++) {\n        const [, row, col] = minHeap.pop();\n\n        if (col + 1 < n) {\n            minHeap.push([matrix[row][col + 1], row, col + 1]);\n        }\n    }\n    return minHeap.peek()[0];\n}',
  ARRAY['top-k-elements'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'netflix-senior', 'uber-sde2'],
  'top-k-elements',
  '[{"input":"kth_smallest_matrix([[1, 5, 9], [10, 11, 13], [12, 13, 15]], 8)","expected_output":"13"},{"input":"kth_smallest_matrix([[-5]], 1)","expected_output":"-5"},{"input":"kth_smallest_matrix([[1, 2], [3, 4]], 1)","expected_output":"1"}]'::jsonb,
  '[{"input":"kth_smallest_matrix([[1, 2], [3, 4]], 4)","expected_output":"4"},{"input":"kth_smallest_matrix([[1, 3], [2, 4]], 3)","expected_output":"3"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
