INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-k-closest-points-origin',
  'Find K Closest Points to Origin',
  'medium',
  'Find K Closest Points to Origin

<!-- voice:section_check concept="Max-heap for k closest points" -->

Problem Statement

Given an array of `points` where `points[i] = [xi, yi]` represents a point on the X-Y plane and an integer `k`, return the `k` closest points to the origin `(0, 0)`.

The distance between two points on the X-Y plane is the Euclidean distance: `sqrt((x1 - x2)² + (y1 - y2)²)`.

You may return the answer in any order.

Examples

~~~
Input: points = [[1, 3], [-2, 2]], k = 1
Output: [[-2, 2]]
Explanation: 
- Distance of [1, 3] from origin = sqrt(1 + 9) = sqrt(10)
- Distance of [-2, 2] from origin = sqrt(4 + 4) = sqrt(8)
- [-2, 2] is closer
~~~

~~~
Input: points = [[3, 3], [5, -1], [-2, 4]], k = 2
Output: [[3, 3], [-2, 4]] or [[-2, 4], [3, 3]]
~~~',
  '',
  '[{"input":"points = [[1, 3], [-2, 2]], k = 1","output":"[[-2, 2]]","explanation":"- Distance of [1, 3] from origin = sqrt(1 + 9) = sqrt(10)"}]'::jsonb,
  'k_closest',
  E'import heapq\ndef k_closest(points, k):\n    """\n    Find k closest points to origin.\n\n    Args:\n        points: List of [x, y] coordinates\n        k: int, number of closest points to return\n    Returns:\n        List of [x, y] coordinates, k closest to origin\n    Example:\n        >>> k_closest([[1, 3], [-2, 2]], 1)\n        [[-2, 2]]\n        >>> k_closest([[3, 3], [5, -1], [-2, 4]], 2)\n        [[3, 3], [-2, 4]]  # or [[-2, 4], [3, 3]]\n    """\n    # TODO: Use max-heap of size k to track k closest points\n    # Hint: Store (-distance, point) for max-heap in Python\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: [[-2, 2]]\n# Two closest from three\nresult = k_closest([[3, 3], [5, -1], [-2, 4]], 2)\n# Expected: [[-2, 4], [3, 3]] (sorted)\n# k equals number of points\n# Expected: [[1, 1], [2, 2]] (any order)\n# All same distance\n# Expected: Any 2 of the 4 points\n# Single point\n# Expected: [[0, 0]]',
  E'import heapq\ndef k_closest(points, k):\n    """\n    Find k closest points to origin.\n\n    Time Complexity: O(n log k) — n points, heap operations O(log k)\n    Space Complexity: O(k) — max-heap of size k\n    """\n    # Max-heap: store (-distance, point) to simulate max-heap\n    max_heap = []\n    for x, y in points:\n        # Use squared distance (same ordering, avoid sqrt)\n        dist = x * x + y * y\n        if len(max_heap) < k:\n            # Negate distance for max-heap behavior\n            heapq.heappush(max_heap, (-dist, [x, y]))\n        elif dist < -max_heap[0][0]:\n            # Current point is closer than farthest in heap\n            heapq.heapreplace(max_heap, (-dist, [x, y]))\n    # Extract points from heap\n    return [point for (_, point) in max_heap]\n# Alternative: Sort approach (O(n log n))\ndef k_closest_sort(points, k):\n    """\n    Alternative using sorting.\n    """\n    # Sort by squared distance\n    points.sort(key=lambda p: p[0]**2 + p[1]**2)\n    return points[:k]\n\n# Alternative: QuickSelect approach (O(n) average)\ndef k_closest_quickselect(points, k):\n    """\n    Alternative using QuickSelect for O(n) average.\n    """\n    def dist_sq(p):\n        return p[0]**2 + p[1]**2\n\n    def partition(left, right, pivot_idx):\n        pivot_dist = dist_sq(points[pivot_idx])\n        # Move pivot to end\n        points[pivot_idx], points[right] = points[right], points[pivot_idx]\n\n        store_idx = left\n        for i in range(left, right):\n            if dist_sq(points[i]) < pivot_dist:\n                points[store_idx], points[i] = points[i], points[store_idx]\n                store_idx += 1\n        # Move pivot to final place\n        points[right], points[store_idx] = points[store_idx], points[right]\n        return store_idx\n    def select(left, right, k_smallest):\n        if left == right:\n            return\n\n        pivot_idx = left + (right - left) // 2\n        pivot_idx = partition(left, right, pivot_idx)\n        if k_smallest == pivot_idx:\n            return\n        elif k_smallest < pivot_idx:\n            select(left, pivot_idx - 1, k_smallest)\n        else:\n            select(pivot_idx + 1, right, k_smallest)\n    select(0, len(points) - 1, k)\n    return points[:k]\n# ─── Test Cases ───\n# Expected: [[-2, 2]]\nresult = k_closest([[3, 3], [5, -1], [-2, 4]], 2)\n# Expected: [[-2, 4], [3, 3]] (sorted for comparison)\n# Expected: [[1, 1], [2, 2]]\n# Expected: [[0, 0]]',
  E'class Solution {\n    public Object kClosest(Object points, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.PriorityQueue;\n\nclass Solution {\n    public static int[][] kClosest(int[][] points, int k) {\n        // Max-heap to store int[]: {squared_distance, x, y}\n        // Comparator sorts by squared_distance (index 0) in descending order\n        PriorityQueue<int[]> maxHeap = new PriorityQueue<>((a, b) -> b[0] - a[0]);\n\n        for (int[] point : points) {\n            int x = point[0];\n            int y = point[1];\n            int distSq = x * x + y * y;\n\n            if (maxHeap.size() < k) {\n                maxHeap.offer(new int[]{distSq, x, y});\n            } else if (distSq < maxHeap.peek()[0]) {\n                // Current point is closer than the farthest in the heap\n                maxHeap.poll(); // Remove the farthest\n                maxHeap.offer(new int[]{distSq, x, y}); // Add the new closer point\n            }\n        }\n\n        // Extract points from heap\n        int[][] result = new int[k][2];\n        for (int i = k - 1; i >= 0; i--) {\n            int[] current = maxHeap.poll();\n            result[i] = new int[]{current[1], current[2]}; // Store [x, y]\n        }\n        return result;\n    }\n}',
  E'/**\n * @param {any, any} points, k\n * @return {any}\n */\nfunction kClosest(points, k) {\n    // Your code here\n}',
  E'class MaxHeap {\n    constructor(comparator = (a, b) => b - a) {\n        this.heap = [];\n        this.comparator = comparator;\n    }\n\n    getParentIndex(i) { return Math.floor((i - 1) / 2); }\n    getLeftChildIndex(i) { return 2 * i + 1; }\n    getRightChildIndex(i) { return 2 * i + 2; }\n\n    hasParent(i) { return this.getParentIndex(i) >= 0; }\n    hasLeftChild(i) { return this.getLeftChildIndex(i) < this.heap.length; }\n    hasRightChild(i) { return this.getRightChildIndex(i) < this.heap.length; }\n\n    getParent(i) { return this.heap[this.getParentIndex(i)]; }\n    getLeftChild(i) { return this.heap[this.getLeftChildIndex(i)]; }\n    getRightChild(i) { return this.heap[this.getRightChildIndex(i)]; }\n\n    peek() {\n        if (this.heap.length === 0) return null;\n        return this.heap[0];\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    swap(i, j) {\n        [this.heap[i], this.heap[j]] = [this.heap[j], this.heap[i]];\n    }\n\n    push(item) {\n        this.heap.push(item);\n        this.heapifyUp();\n    }\n\n    pop() {\n        if (this.heap.length === 0) return null;\n        if (this.heap.length === 1) return this.heap.pop();\n\n        const item = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this.heapifyDown();\n        return item;\n    }\n\n    heapifyUp() {\n        let index = this.heap.length - 1;\n        while (this.hasParent(index) && this.comparator(this.getParent(index), this.heap[index]) < 0) {\n            this.swap(this.getParentIndex(index), index);\n            index = this.getParentIndex(index);\n        }\n    }\n\n    heapifyDown() {\n        let index = 0;\n        while (this.hasLeftChild(index)) {\n            let largerChildIndex = this.getLeftChildIndex(index);\n            if (this.hasRightChild(index) && this.comparator(this.getRightChild(index), this.getLeftChild(index)) > 0) {\n                largerChildIndex = this.getRightChildIndex(index);\n            }\n\n            if (this.comparator(this.heap[index], this.heap[largerChildIndex]) > 0) {\n                break;\n            } else {\n                this.swap(index, largerChildIndex);\n            }\n            index = largerChildIndex;\n        }\n    }\n}\n\nfunction kClosest(points, k) {\n    // Max-heap stores [squared_distance, x, y]\n    // Comparator sorts by squared_distance (index 0) in descending order\n    const maxHeap = new MaxHeap((a, b) => b[0] - a[0]);\n\n    for (const point of points) {\n        const x = point[0];\n        const y = point[1];\n        const distSq = x * x + y * y;\n\n        if (maxHeap.size() < k) {\n            maxHeap.push([distSq, x, y]);\n        } else if (distSq < maxHeap.peek()[0]) {\n            maxHeap.pop();\n            maxHeap.push([distSq, x, y]);\n        }\n    }\n\n    const result = [];\n    while (maxHeap.size() > 0) {\n        const [, x, y] = maxHeap.pop();\n        result.push([x, y]);\n    }\n    return result;\n}',
  ARRAY['top-k-elements'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'netflix-senior', 'uber-sde2'],
  'top-k-elements',
  '[{"input":"k_closest([[1, 3], [-2, 2]], 1)","expected_output":"[[-2, 2]]"},{"input":"k_closest([[1, 1], [2, 2]], 2)","expected_output":"[[1, 1], [2, 2]] (any order)"},{"input":"k_closest([[1, 1], [-1, 1], [1, -1], [-1, -1]], 2)","expected_output":"Any 2 of the 4 points"}]'::jsonb,
  '[{"input":"k_closest([[0, 0]], 1)","expected_output":"[[0, 0]]"}]'::jsonb
