INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-top-k-frequent-elements',
  'Top K Frequent Elements',
  'hard',
  'Top K Frequent Elements

<!-- voice:section_check concept="Min-heap for top k frequent elements" -->

Problem Statement

Given an integer array `nums` and an integer `k`, return the `k` most frequent elements. You may return the answer in any order.

Examples

~~~
Input: nums = [1, 1, 1, 2, 2, 3], k = 2
Output: [1, 2]
Explanation: 1 appears 3 times, 2 appears 2 times, 3 appears 1 time
             Top 2 frequent: 1 and 2
~~~

~~~
Input: nums = [1], k = 1
Output: [1]
~~~',
  '',
  '[{"input":"nums = [1, 1, 1, 2, 2, 3], k = 2","output":"[1, 2]","explanation":"1 appears 3 times, 2 appears 2 times, 3 appears 1 time"}]'::jsonb,
  'top_k_frequent',
  E'import heapq\nfrom collections import Counter\ndef top_k_frequent(nums, k):\n    """\n    Find k most frequent elements.\n\n    Args:\n        nums: List of integers\n        k: int, number of most frequent elements to return\n    Returns:\n        List of k most frequent elements\n    Example:\n        >>> top_k_frequent([1, 1, 1, 2, 2, 3], 2)\n        [1, 2]\n        >>> top_k_frequent([1], 1)\n        [1]\n    """\n    # TODO: Count frequencies, then use min-heap to find top k\n    # Hint: Use Counter for frequencies, then heap with (freq, num)\n    pass\n# ─── Test Cases ───\n# Standard case\nresult = top_k_frequent([1, 1, 1, 2, 2, 3], 2)\n# Expected: [1, 2]\n# Single element\n# Expected: [1]\n# All same frequency (any k elements valid)\nresult = top_k_frequent([1, 2, 3, 4], 2)\n# Expected: 2\n# k equals unique elements\nresult = top_k_frequent([1, 1, 2, 2], 2)\n# Expected: [1, 2]\n# More complex case\nresult = top_k_frequent([4, 1, -1, 2, -1, 2, 3], 2)\n# Expected: [-1, 2] (both appear twice)',
  E'import heapq\nfrom collections import Counter\ndef top_k_frequent(nums, k):\n    """\n    Find k most frequent elements.\n\n    Time Complexity: O(n log k) — counting O(n), heap O(n log k)\n    Space Complexity: O(n) — frequency map\n    """\n    # Count frequencies\n    freq_map = Counter(nums)\n    # Use min-heap of size k\n    min_heap = []\n    for num, freq in freq_map.items():\n        if len(min_heap) < k:\n            heapq.heappush(min_heap, (freq, num))\n        elif freq > min_heap[0][0]:\n            heapq.heapreplace(min_heap, (freq, num))\n    # Extract elements\n    return [num for (freq, num) in min_heap]\n# Cleaner alternative using heapq.nlargest\ndef top_k_frequent_clean(nums, k):\n    """\n    Clean solution using heapq.nlargest.\n    """\n    freq_map = Counter(nums)\n    # nlargest returns k elements with largest frequency\n    return heapq.nlargest(k, freq_map.keys(), key=freq_map.get)\n\n# Alternative using bucket sort (O(n) time)\ndef top_k_frequent_bucket(nums, k):\n    """\n    O(n) solution using bucket sort.\n    """\n    freq_map = Counter(nums)\n    n = len(nums)\n\n    # Buckets[i] contains elements with frequency i\n    buckets = [[] for _ in range(n + 1)]\n    for num, freq in freq_map.items():\n        buckets[freq].append(num)\n    # Collect from highest frequency bucket\n    result = []\n    for i in range(n, 0, -1):\n        result.extend(buckets[i])\n        if len(result) >= k:\n            return result[:k]\n    return result[:k]\n# ─── Test Cases ───\nresult = top_k_frequent([1, 1, 1, 2, 2, 3], 2)\n# Expected: [1, 2]\n# Expected: [1]\nresult = top_k_frequent([1, 2, 3, 4], 2)\n# Expected: 2\nresult = top_k_frequent([1, 1, 2, 2], 2)\n# Expected: [1, 2]\nresult = top_k_frequent([4, 1, -1, 2, -1, 2, 3], 2)\n# Expected: [-1, 2]',
  E'class Solution {\n    public Object topKFrequent(int[] nums, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.PriorityQueue;\n\nclass Solution {\n    public static List<Integer> topKFrequent(int[] nums, int k) {\n        // Count frequencies\n        Map<Integer, Integer> freqMap = new HashMap<>();\n        for (int num : nums) {\n            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);\n        }\n\n        // Use min-heap of size k\n        // Stores int[] where [0] is frequency, [1] is number\n        PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> a[0] - b[0]);\n\n        for (Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {\n            int num = entry.getKey();\n            int freq = entry.getValue();\n\n            if (minHeap.size() < k) {\n                minHeap.offer(new int[]{freq, num});\n            } else if (freq > minHeap.peek()[0]) {\n                minHeap.poll(); // Remove smallest frequency element\n                minHeap.offer(new int[]{freq, num}); // Add new element\n            }\n        }\n\n        // Extract elements\n        List<Integer> result = new ArrayList<>();\n        while (!minHeap.isEmpty()) {\n            result.add(minHeap.poll()[1]);\n        }\n        return result;\n    }\n}',
  E'/**\n * @param {any, any} nums, k\n * @return {any}\n */\nfunction topKFrequent(nums, k) {\n    // Your code here\n}',
  E'class MinHeap {\n    constructor(comparator = (a, b) => a - b) {\n        this.heap = [];\n        this.comparator = comparator;\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    peek() {\n        return this.heap.length === 0 ? undefined : this.heap[0];\n    }\n\n    insert(value) {\n        this.heap.push(value);\n        this._bubbleUp(this.heap.length - 1);\n    }\n\n    extractMin() {\n        if (this.heap.length === 0) return undefined;\n        if (this.heap.length === 1) return this.heap.pop();\n\n        const min = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this._bubbleDown(0);\n        return min;\n    }\n\n    _bubbleUp(index) {\n        while (index > 0) {\n            const parentIndex = Math.floor((index - 1) / 2);\n            if (this.comparator(this.heap[index], this.heap[parentIndex]) < 0) {\n                [this.heap[index], this.heap[parentIndex]] = [this.heap[parentIndex], this.heap[index]];\n                index = parentIndex;\n            } else {\n                break;\n            }\n        }\n    }\n\n    _bubbleDown(index) {\n        const lastIndex = this.heap.length - 1;\n        while (true) {\n            let leftChildIndex = 2 * index + 1;\n            let rightChildIndex = 2 * index + 2;\n            let smallestIndex = index;\n\n            if (leftChildIndex <= lastIndex && this.comparator(this.heap[leftChildIndex], this.heap[smallestIndex]) < 0) {\n                smallestIndex = leftChildIndex;\n            }\n\n            if (rightChildIndex <= lastIndex && this.comparator(this.heap[rightChildIndex], this.heap[smallestIndex]) < 0) {\n                smallestIndex = rightChildIndex;\n            }\n\n            if (smallestIndex !== index) {\n                [this.heap[index], this.heap[smallestIndex]] = [this.heap[smallestIndex], this.heap[index]];\n                index = smallestIndex;\n            } else {\n                break;\n            }\n        }\n    }\n}\n\nfunction topKFrequent(nums, k) {\n    // Count frequencies\n    const freqMap = new Map();\n    for (const num of nums) {\n        freqMap.set(num, (freqMap.get(num) || 0) + 1);\n    }\n\n    // Use min-heap of size k\n    // Stores [frequency, number]\n    const minHeap = new MinHeap((a, b) => a[0] - b[0]);\n\n    for (const [num, freq] of freqMap.entries()) {\n        if (minHeap.size() < k) {\n            minHeap.insert([freq, num]);\n        } else if (freq > minHeap.peek()[0]) {\n            minHeap.extractMin(); // Remove smallest frequency element\n            minHeap.insert([freq, num]); // Add new element\n        }\n    }\n\n    // Extract elements\n    const result = [];\n    while (minHeap.size() > 0) {\n        result.push(minHeap.extractMin()[1]);\n    }\n    return result;\n}',
  ARRAY['top-k-elements'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'netflix-senior', 'uber-sde2'],
  'top-k-elements',
  '[{"input":"top_k_frequent([1], 1)","expected_output":"[1]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
