INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-merge-k-sorted-lists',
  'Merge K Sorted Lists',
  'medium',
  'Merge K Sorted Lists

<!-- voice:section_check concept="Heap for merging k sorted linked lists" -->

Problem Statement

You are given an array of `k` linked-lists `lists`, each linked-list is sorted in ascending order.

Merge all the linked-lists into one sorted linked-list and return it.

Examples

~~~
Input: lists = [[1, 4, 5], [1, 3, 4], [2, 6]]
Output: [1, 1, 2, 3, 4, 4, 5, 6]
Explanation: Merged sorted list from all 3 lists
~~~

~~~
Input: lists = []
Output: []
~~~

~~~
Input: lists = [[]]
Output: []
~~~',
  '',
  '[{"input":"lists = [[1, 4, 5], [1, 3, 4], [2, 6]]","output":"[1, 1, 2, 3, 4, 4, 5, 6]","explanation":"Merged sorted list from all 3 lists"}]'::jsonb,
  'merge_k_lists',
  E'import heapq\nclass ListNode:\n    """Node in a singly linked list."""\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\n    def __repr__(self):\n        """String representation for debugging."""\n        result = []\n        curr = self\n        while curr:\n            result.append(str(curr.val))\n            curr = curr.next\n        return " -> ".join(result)\n\ndef merge_k_lists(lists):\n    """\n    Merge k sorted linked lists into one sorted list.\n\n    Args:\n        lists: List of ListNode, heads of sorted linked lists\n    Returns:\n        ListNode: Head of merged sorted list\n    Example:\n        >>> lists = [ListNode(1, ListNode(4, ListNode(5))),\n        ...          ListNode(1, ListNode(3, ListNode(4))),\n        ...          ListNode(2, ListNode(6))]\n        >>> result = merge_k_lists(lists)\n        >>> print(result)\n        1 -> 1 -> 2 -> 3 -> 4 -> 4 -> 5 -> 6\n    """\n    # TODO: Use min-heap to merge k sorted lists\n    # Hint: Store (val, list_index, node) in heap\n    pass\n# ─── Helper Functions ───\ndef create_linked_list(arr):\n    """Create linked list from array."""\n    if not arr:\n        return None\n    head = ListNode(arr[0])\n    curr = head\n    for val in arr[1:]:\n        curr.next = ListNode(val)\n        curr = curr.next\n    return head\n\ndef linked_list_to_array(head):\n    """Convert linked list to array."""\n    result = []\n    curr = head\n    while curr:\n        result.append(curr.val)\n        curr = curr.next\n    return result\n\n# ─── Test Cases ───\n# Standard case\nlists = [\n    create_linked_list([1, 4, 5]),\n    create_linked_list([1, 3, 4]),\n    create_linked_list([2, 6])\n]\nresult = merge_k_lists(lists)\n# Expected: [1, 1, 2, 3, 4, 4, 5, 6]\n# Empty list of lists\n# Expected: None\n# List with empty list\nresult = merge_k_lists([[]])\n# Expected: None\n# Single list\nresult = merge_k_lists([create_linked_list([1, 2, 3])])\n# Expected: [1, 2, 3]\n# Two lists\nlists = [\n    create_linked_list([1, 3, 5]),\n    create_linked_list([2, 4, 6])\n]\nresult = merge_k_lists(lists)\n# Expected: [1, 2, 3, 4, 5, 6]',
  E'import heapq\nclass ListNode:\n    """Node in a singly linked list."""\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\n    def __repr__(self):\n        result = []\n        curr = self\n        while curr:\n            result.append(str(curr.val))\n            curr = curr.next\n        return " -> ".join(result)\n\n    def __lt__(self, other):\n        """Less than comparison for heap."""\n        return self.val < other.val\n\ndef merge_k_lists(lists):\n    """\n    Merge k sorted linked lists into one sorted list.\n\n    Time Complexity: O(n log k) — n total nodes, heap ops O(log k)\n    Space Complexity: O(k) — heap stores at most k nodes\n    """\n    # Min-heap to track smallest node from each list\n    min_heap = []\n    # Push head of each non-empty list\n    for i, node in enumerate(lists):\n        if node:\n            # Use counter to break ties (nodes not directly comparable)\n            heapq.heappush(min_heap, (node.val, i, node))\n    # Dummy head for result list\n    dummy = ListNode(0)\n    curr = dummy\n    while min_heap:\n        val, i, node = heapq.heappop(min_heap)\n        # Add to result\n        curr.next = node\n        curr = curr.next\n        # Push next node from same list\n        if node.next:\n            heapq.heappush(min_heap, (node.next.val, i, node.next))\n    return dummy.next\n# Alternative without modifying ListNode\ndef merge_k_lists_v2(lists):\n    """\n    Alternative using wrapper class for comparison.\n    """\n    class Wrapper:\n        def __init__(self, node):\n            self.node = node\n        def __lt__(self, other):\n            return self.node.val < other.node.val\n\n    min_heap = []\n    for node in lists:\n        if node:\n            heapq.heappush(min_heap, Wrapper(node))\n    dummy = ListNode(0)\n    curr = dummy\n    while min_heap:\n        wrapper = heapq.heappop(min_heap)\n        node = wrapper.node\n        curr.next = node\n        curr = curr.next\n        if node.next:\n            heapq.heappush(min_heap, Wrapper(node.next))\n    return dummy.next\n# ─── Helper Functions ───\ndef create_linked_list(arr):\n    if not arr:\n        return None\n    head = ListNode(arr[0])\n    curr = head\n    for val in arr[1:]:\n        curr.next = ListNode(val)\n        curr = curr.next\n    return head\n\ndef linked_list_to_array(head):\n    result = []\n    curr = head\n    while curr:\n        result.append(curr.val)\n        curr = curr.next\n    return result\n\n# ─── Test Cases ───\nlists = [\n    create_linked_list([1, 4, 5]),\n    create_linked_list([1, 3, 4]),\n    create_linked_list([2, 6])\n]\nresult = merge_k_lists(lists)\n# Expected: [1, 1, 2, 3, 4, 4, 5, 6]\n# Expected: None\n# Expected: None\nresult = merge_k_lists([create_linked_list([1, 2, 3])])\n# Expected: [1, 2, 3]\nlists = [\n    create_linked_list([1, 3, 5]),\n    create_linked_list([2, 4, 6])\n]\nresult = merge_k_lists(lists)\n# Expected: [1, 2, 3, 4, 5, 6]',
  E'class Solution {\n    public Object mergeKLists(Object val, Object next) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.List;\nimport java.util.PriorityQueue;\n\nclass Solution {\n    public static class ListNode implements Comparable<ListNode> {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n        ListNode(int val, ListNode next) { this.val = val; this.next = next; }\n\n        @Override\n        public int compareTo(ListNode other) {\n            return this.val - other.val;\n        }\n    }\n\n    public static ListNode mergeKLists(List<ListNode> lists) {\n        // Min-heap to track smallest node from each list\n        PriorityQueue<ListNode> minHeap = new PriorityQueue<>();\n\n        // Push head of each non-empty list\n        for (ListNode node : lists) {\n            if (node != null) {\n                minHeap.offer(node);\n            }\n        }\n\n        // Dummy head for result list\n        ListNode dummy = new ListNode(0);\n        ListNode curr = dummy;\n\n        while (!minHeap.isEmpty()) {\n            ListNode node = minHeap.poll();\n            // Add to result\n            curr.next = node;\n            curr = curr.next;\n\n            // Push next node from same list\n            if (node.next != null) {\n                minHeap.offer(node.next);\n            }\n        }\n        return dummy.next;\n    }\n}',
  E'/**\n * @param {any, any} val, next\n * @return {any}\n */\nfunction mergeKLists(val, next) {\n    // Your code here\n}',
  E'class ListNode {\n    constructor(val = 0, next = null) {\n        this.val = val;\n        this.next = next;\n    }\n}\n\nclass MinHeap {\n    constructor(comparator = (a, b) => a - b) {\n        this.heap = [];\n        this.comparator = comparator;\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    peek() {\n        return this.heap.length === 0 ? undefined : this.heap[0];\n    }\n\n    insert(value) {\n        this.heap.push(value);\n        this._bubbleUp(this.heap.length - 1);\n    }\n\n    extractMin() {\n        if (this.heap.length === 0) return undefined;\n        if (this.heap.length === 1) return this.heap.pop();\n\n        const min = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this._bubbleDown(0);\n        return min;\n    }\n\n    _bubbleUp(index) {\n        while (index > 0) {\n            const parentIndex = Math.floor((index - 1) / 2);\n            if (this.comparator(this.heap[index], this.heap[parentIndex]) < 0) {\n                [this.heap[index], this.heap[parentIndex]] = [this.heap[parentIndex], this.heap[index]];\n                index = parentIndex;\n            } else {\n                break;\n            }\n        }\n    }\n\n    _bubbleDown(index) {\n        const lastIndex = this.heap.length - 1;\n        while (true) {\n            let leftChildIndex = 2 * index + 1;\n            let rightChildIndex = 2 * index + 2;\n            let smallestIndex = index;\n\n            if (leftChildIndex <= lastIndex && this.comparator(this.heap[leftChildIndex], this.heap[smallestIndex]) < 0) {\n                smallestIndex = leftChildIndex;\n            }\n\n            if (rightChildIndex <= lastIndex && this.comparator(this.heap[rightChildIndex], this.heap[smallestIndex]) < 0) {\n                smallestIndex = rightChildIndex;\n            }\n\n            if (smallestIndex !== index) {\n                [this.heap[index], this.heap[smallestIndex]] = [this.heap[smallestIndex], this.heap[index]];\n                index = smallestIndex;\n            } else {\n                break;\n            }\n        }\n    }\n}\n\nfunction mergeKLists(lists) {\n    // Min-heap to track smallest node from each list\n    const minHeap = new MinHeap((a, b) => a.val - b.val);\n\n    // Push head of each non-empty list\n    for (const node of lists) {\n        if (node) {\n            minHeap.insert(node);\n        }\n    }\n\n    // Dummy head for result list\n    const dummy = new ListNode(0);\n    let curr = dummy;\n\n    while (minHeap.size() > 0) {\n        const node = minHeap.extractMin();\n        // Add to result\n        curr.next = node;\n        curr = curr.next;\n\n        // Push next node from same list\n        if (node.next) {\n            minHeap.insert(node.next);\n        }\n    }\n    return dummy.next;\n}',
  ARRAY['k-way-merge'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'databricks-swe'],
  'k-way-merge',
  '[{"input":"merge_k_lists([])","expected_output":"None"},{"input":"merge_k_lists([[]])","expected_output":"None"}]'::jsonb,
  '[]'::jsonb
