INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-kth-smallest-m-sorted-lists',
  'Kth Smallest Number in M Sorted Lists',
  'medium',
  'Kth Smallest Number in M Sorted Lists

<!-- voice:section_check concept="Finding kth smallest without full merge" -->

Problem Statement

Given M sorted arrays, find the Kth smallest number among all the arrays.

Examples

~~~
Input: lists = [[2, 6, 8], [3, 6, 7], [1, 3, 4]], k = 5
Output: 4
Explanation: Merged sorted: [1, 2, 3, 3, 4, 6, 6, 7, 8]
                              1st    ...     5th
~~~

~~~
Input: lists = [[5, 8, 9], [1, 7]], k = 3
Output: 7
Explanation: Merged sorted: [1, 5, 7, 8, 9], 3rd is 7
~~~',
  '',
  '[{"input":"lists = [[2, 6, 8], [3, 6, 7], [1, 3, 4]], k = 5","output":"4","explanation":"Merged sorted: [1, 2, 3, 3, 4, 6, 6, 7, 8]"}]'::jsonb,
  'find_kth_smallest',
  E'import heapq\ndef find_kth_smallest(lists, k):\n    """\n    Find kth smallest number in m sorted lists.\n\n    Args:\n        lists: List of sorted arrays\n        k: int, which smallest element to find\n    Returns:\n        int: The kth smallest element\n    Example:\n        >>> find_kth_smallest([[2, 6, 8], [3, 6, 7], [1, 3, 4]], 5)\n        4\n        >>> find_kth_smallest([[5, 8, 9], [1, 7]], 3)\n        7\n    """\n    # TODO: Use min-heap to find kth smallest without full merge\n    # Hint: Pop from heap k times, the kth pop is the answer\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: 4\n# Two lists\n# Expected: 7\n# k=1 (smallest overall)\n# Expected: 1\n# Single list\n# Expected: 3\n# Multiple duplicates\n# Expected: 2\n# Larger k\n# Expected: 7',
  E'import heapq\ndef find_kth_smallest(lists, k):\n    """\n    Find kth smallest number in m sorted lists.\n\n    Time Complexity: O(k log m) — k heap pops, heap size m\n    Space Complexity: O(m) — heap stores at most m elements\n    """\n    min_heap = []\n    # Push first element from each list\n    for i, arr in enumerate(lists):\n        if arr:\n            heapq.heappush(min_heap, (arr[0], i, 0))\n    count = 0\n    while min_heap:\n        val, list_idx, elem_idx = heapq.heappop(min_heap)\n        count += 1\n        # Found kth smallest\n        if count == k:\n            return val\n        # Push next element from same list\n        if elem_idx + 1 < len(lists[list_idx]):\n            next_val = lists[list_idx][elem_idx + 1]\n            heapq.heappush(min_heap, (next_val, list_idx, elem_idx + 1))\n    return -1  # k is larger than total elements\n# Alternative: Binary Search approach\ndef find_kth_smallest_binary_search(lists, k):\n    """\n    Alternative using binary search on value range.\n    """\n    def count_less_equal(num):\n        """Count elements <= num across all lists."""\n        count = 0\n        for arr in lists:\n            # Binary search for rightmost position <= num\n            left, right = 0, len(arr)\n            while left < right:\n                mid = left + (right - left) // 2\n                if arr[mid] <= num:\n                    left = mid + 1\n                else:\n                    right = mid\n            count += left\n        return count\n\n    # Find min and max values\n    left = min(arr[0] for arr in lists if arr)\n    right = max(arr[-1] for arr in lists if arr)\n    while left < right:\n        mid = left + (right - left) // 2\n        if count_less_equal(mid) < k:\n            left = mid + 1\n        else:\n            right = mid\n    return left\n# ─── Test Cases ───\n# Expected: 4\n# Expected: 7\n# Expected: 1\n# Expected: 3\n# Expected: 2\n# Expected: 7',
  E'class Solution {\n    public Object findKthSmallest(List<Integer> lists, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.List;\nimport java.util.PriorityQueue;\n\nclass Solution {\n    public static int findKthSmallest(List<List<Integer>> lists, int k) {\n        // Min-heap stores int[] where [0] is value, [1] is list index, [2] is element index within the list\n        PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> a[0] - b[0]);\n\n        // Push first element from each list\n        for (int i = 0; i < lists.size(); i++) {\n            if (!lists.get(i).isEmpty()) {\n                minHeap.offer(new int[]{lists.get(i).get(0), i, 0});\n            }\n        }\n\n        int count = 0;\n        while (!minHeap.isEmpty()) {\n            int[] entry = minHeap.poll();\n            int val = entry[0];\n            int listIdx = entry[1];\n            int elemIdx = entry[2];\n\n            count++;\n            // Found kth smallest\n            if (count == k) {\n                return val;\n            }\n\n            // Push next element from same list\n            if (elemIdx + 1 < lists.get(listIdx).size()) {\n                int nextVal = lists.get(listIdx).get(elemIdx + 1);\n                minHeap.offer(new int[]{nextVal, listIdx, elemIdx + 1});\n            }\n        }\n        return -1; // k is larger than total elements\n    }\n}',
  E'/**\n * @param {any, any} lists, k\n * @return {any}\n */\nfunction findKthSmallest(lists, k) {\n    // Your code here\n}',
  E'class MinHeap {\n    constructor(comparator = (a, b) => a - b) {\n        this.heap = [];\n        this.comparator = comparator;\n    }\n\n    size() {\n        return this.heap.length;\n    }\n\n    peek() {\n        return this.heap.length === 0 ? undefined : this.heap[0];\n    }\n\n    insert(value) {\n        this.heap.push(value);\n        this._bubbleUp(this.heap.length - 1);\n    }\n\n    extractMin() {\n        if (this.heap.length === 0) return undefined;\n        if (this.heap.length === 1) return this.heap.pop();\n\n        const min = this.heap[0];\n        this.heap[0] = this.heap.pop();\n        this._bubbleDown(0);\n        return min;\n    }\n\n    _bubbleUp(index) {\n        while (index > 0) {\n            const parentIndex = Math.floor((index - 1) / 2);\n            if (this.comparator(this.heap[index], this.heap[parentIndex]) < 0) {\n                [this.heap[index], this.heap[parentIndex]] = [this.heap[parentIndex], this.heap[index]];\n                index = parentIndex;\n            } else {\n                break;\n            }\n        }\n    }\n\n    _bubbleDown(index) {\n        const lastIndex = this.heap.length - 1;\n        while (true) {\n            let leftChildIndex = 2 * index + 1;\n            let rightChildIndex = 2 * index + 2;\n            let smallestIndex = index;\n\n            if (leftChildIndex <= lastIndex && this.comparator(this.heap[leftChildIndex], this.heap[smallestIndex]) < 0) {\n                smallestIndex = leftChildIndex;\n            }\n\n            if (rightChildIndex <= lastIndex && this.comparator(this.heap[rightChildIndex], this.heap[smallestIndex]) < 0) {\n                smallestIndex = rightChildIndex;\n            }\n\n            if (smallestIndex !== index) {\n                [this.heap[index], this.heap[smallestIndex]] = [this.heap[smallestIndex], this.heap[index]];\n                index = smallestIndex;\n            } else {\n                break;\n            }\n        }\n    }\n}\n\nfunction findKthSmallest(lists, k) {\n    // Min-heap stores [value, list_index, element_index within the list]\n    const minHeap = new MinHeap((a, b) => a[0] - b[0]);\n\n    // Push first element from each list\n    for (let i = 0; i < lists.length; i++) {\n        if (lists[i].length > 0) {\n            minHeap.insert([lists[i][0], i, 0]);\n        }\n    }\n\n    let count = 0;\n    while (minHeap.size() > 0) {\n        const [val, listIdx, elemIdx] = minHeap.extractMin();\n\n        count++;\n        // Found kth smallest\n        if (count === k) {\n            return val;\n        }\n\n        // Push next element from same list\n        if (elemIdx + 1 < lists[listIdx].length) {\n            const nextVal = lists[listIdx][elemIdx + 1];\n            minHeap.insert([nextVal, listIdx, elemIdx + 1]);\n        }\n    }\n    return -1; // k is larger than total elements\n}',
  ARRAY['k-way-merge'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'databricks-swe'],
  'k-way-merge',
  '[{"input":"find_kth_smallest([[2, 6, 8], [3, 6, 7], [1, 3, 4]], 5)","expected_output":"4"},{"input":"find_kth_smallest([[5, 8, 9], [1, 7]], 3)","expected_output":"7"},{"input":"find_kth_smallest([[2, 4], [1, 3]], 1)","expected_output":"1"}]'::jsonb,
  '[{"input":"find_kth_smallest([[1, 2, 3, 4, 5]], 3)","expected_output":"3"},{"input":"find_kth_smallest([[1, 1, 1], [1, 2, 3]], 4)","expected_output":"2"},{"input":"find_kth_smallest([[1, 2, 3], [4, 5, 6], [7, 8, 9]], 7)","expected_output":"7"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
