INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-smallest-range-covering-k-lists',
  'Find Smallest Range Covering Elements from K Lists',
  'medium',
  'Find Smallest Range Covering Elements from K Lists

<!-- voice:section_check concept="Sliding window on k-way merge" -->

Problem Statement

Given M sorted lists, find the smallest range that includes at least one number from each of the M lists.

Examples

~~~
Input: lists = [[1, 5, 8], [4, 12], [7, 8, 10]]
Output: [4, 7]
Explanation: 4 from 2nd list, 7 from 3rd list
             Range size = 7 - 4 = 3 (smallest possible)
~~~

~~~
Input: lists = [[1, 2, 3], [1, 2, 3], [1, 2, 3]]
Output: [1, 1]
Explanation: 1 is in all three lists
~~~',
  '',
  '[{"input":"lists = [[1, 5, 8], [4, 12], [7, 8, 10]]","output":"[4, 7]","explanation":"4 from 2nd list, 7 from 3rd list"}]'::jsonb,
  'find_smallest_range',
  E'import heapq\ndef find_smallest_range(lists):\n    """\n    Find smallest range covering at least one element from each list.\n\n    Args:\n        lists: List of sorted arrays\n    Returns:\n        List [start, end] representing smallest range\n    Example:\n        >>> find_smallest_range([[1, 5, 8], [4, 12], [7, 8, 10]])\n        [4, 7]\n        >>> find_smallest_range([[1, 2, 3], [1, 2, 3], [1, 2, 3]])\n        [1, 1]\n    """\n    # TODO: Use min-heap to track range covering all lists\n    # Hint: Track current max, range is [heap_min, current_max]\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: [4, 7]\n# All same elements\n# Expected: [1, 1]\n# Two lists\n# Expected: [5, 10]\n# Single element lists\n# Expected: [1, 3]\n# Overlapping ranges\n# Expected: [3, 3]',
  E'import heapq\ndef find_smallest_range(lists):\n    """\n    Find smallest range covering at least one element from each list.\n\n    Time Complexity: O(n log m) — n total elements, heap ops O(log m)\n    Space Complexity: O(m) — heap stores at most m elements\n    """\n    min_heap = []\n    current_max = float(''-inf'')\n    # Push first element from each list\n    for i, arr in enumerate(lists):\n        heapq.heappush(min_heap, (arr[0], i, 0))\n        current_max = max(current_max, arr[0])\n    # Track smallest range\n    range_start, range_end = 0, float(''inf'')\n    while len(min_heap) == len(lists):\n        # Current range is [heap_min, current_max]\n        current_min, list_idx, elem_idx = heapq.heappop(min_heap)\n        # Update smallest range if this is better\n        if current_max - current_min < range_end - range_start:\n            range_start = current_min\n            range_end = current_max\n        # Push next element from same list\n        if elem_idx + 1 < len(lists[list_idx]):\n            next_val = lists[list_idx][elem_idx + 1]\n            heapq.heappush(min_heap, (next_val, list_idx, elem_idx + 1))\n            current_max = max(current_max, next_val)\n        else:\n            # This list is exhausted, can''t form valid range anymore\n            break\n    return [range_start, range_end]\n# ─── Test Cases ───\n# Expected: [4, 7]\n# Expected: [1, 1]\n# Expected: [5, 10]\n# Expected: [1, 3]\n# Expected: [3, 3]',
  E'class Solution {\n    public Object findSmallestRange(List<Integer> lists) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.List;\n    // import java.util.PriorityQueue;\n    // import java.util.Comparator;\n\n    public static int[] findSmallestRange(List<List<Integer>> lists) {\n        PriorityQueue<int[]> minHeap = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));\n        int currentMax = Integer.MIN_VALUE;\n\n        // Add first element from each list to the minHeap\n        // Each element in heap: [value, list_index, element_index_in_list]\n        for (int i = 0; i < lists.size(); i++) {\n            if (!lists.get(i).isEmpty()) {\n                int val = lists.get(i).get(0);\n                minHeap.offer(new int[]{val, i, 0});\n                currentMax = Math.max(currentMax, val);\n            }\n        }\n\n        int rangeStart = 0;\n        int rangeEnd = Integer.MAX_VALUE;\n        int minRangeLen = Integer.MAX_VALUE;\n\n        // Loop while the heap contains one element from each list\n        // This means minHeap.size() == lists.size()\n        while (minHeap.size() == lists.size()) {\n            int[] entry = minHeap.poll();\n            int val = entry[0];\n            int listIdx = entry[1];\n            int elementIdx = entry[2];\n\n            // Current range is [val, currentMax]\n            if (currentMax - val < minRangeLen) {\n                minRangeLen = currentMax - val;\n                rangeStart = val;\n                rangeEnd = currentMax;\n            }\n\n            // Move to the next element in the list from which \'val\' was taken\n            if (elementIdx + 1 < lists.get(listIdx).size()) {\n                int nextVal = lists.get(listIdx).get(elementIdx + 1);\n                minHeap.offer(new int[]{nextVal, listIdx, elementIdx + 1});\n                currentMax = Math.max(currentMax, nextVal);\n            } else {\n                // If any list is exhausted, we can\'t cover all lists anymore\n                break;\n            }\n        }\n\n        return new int[]{rangeStart, rangeEnd};\n    }\n}''-inf'')\n    //     \n    //     # Push first element from each list\n    //     for i, arr in enumerate(lists):\n    //         heapq.heappush(min_heap, (arr[0], i, 0))\n    //         current_max = max(current_max, arr[0])\n    //     \n    //     # Track smallest range\n    //     range_start, range_end = 0, float(''inf'')\n    //     \n    //     while len(min_heap) == len(lists):\n    //         # Current range is [heap_min, current_max]\n    //         current_min, list_idx, elem_idx = heapq.heappop(min_heap)\n    //         \n    //         # Update smallest range if this is better\n    //         if current_max - current_min < range_end - range_start:\n    //             range_start = current_min\n    //             range_end = current_max\n    //         \n    //         # Push next element from same list\n    //         if elem_idx + 1 < len(lists[list_idx]):\n    //             next_val = lists[list_idx][elem_idx + 1]\n    //             heapq.heappush(min_heap, (next_val, list_idx, elem_idx + 1))\n    //             current_max = max(current_max, next_val)\n    //         else:\n    //             # This list is exhausted, can''t form valid range anymore\n    //             break\n    //     \n    //     return [range_start, range_end]\n    // \n    // \n    // # ─── Test Cases ───\n    // # Expected: [4, 7]\n    // \n    // # Expected: [1, 1]\n    // \n    // # Expected: [5, 10]\n    // \n    // # Expected: [1, 3]\n    // \n    // # Expected: [3, 3]\n    // \n}',
  E'/**\n * @param {any} lists\n * @return {any}\n */\nfunction findSmallestRange(lists) {\n    // Your code here\n}',
  E'function findSmallestRange(lists) {\n    // Basic Min-Heap implementation for this problem\n    class MinHeap {\n        constructor() {\n            this.heap = [];\n        }\n\n        push(item) {\n            this.heap.push(item);\n            this._bubbleUp();\n        }\n\n        pop() {\n            if (this.isEmpty()) return null;\n            if (this.heap.length === 1) return this.heap.pop();\n\n            const root = this.heap[0];\n            this.heap[0] = this.heap.pop();\n            this._bubbleDown();\n            return root;\n        }\n\n        peek() {\n            return this.heap[0];\n        }\n\n        size() {\n            return this.heap.length;\n        }\n\n        isEmpty() {\n            return this.heap.length === 0;\n        }\n\n        _bubbleUp() {\n            let index = this.heap.length - 1;\n            while (index > 0) {\n                let parentIndex = Math.floor((index - 1) / 2);\n                if (this.heap[parentIndex][0] <= this.heap[index][0]) break;\n                [this.heap[parentIndex], this.heap[index]] = [this.heap[index], this.heap[parentIndex]];\n                index = parentIndex;\n            }\n        }\n\n        _bubbleDown() {\n            let index = 0;\n            const lastIndex = this.heap.length - 1;\n            while (true) {\n                let leftChildIndex = 2 * index + 1;\n                let rightChildIndex = 2 * index + 2;\n                let smallestIndex = index;\n\n                if (leftChildIndex <= lastIndex && this.heap[leftChildIndex][0] < this.heap[smallestIndex][0]) {\n                    smallestIndex = leftChildIndex;\n                }\n\n                if (rightChildIndex <= lastIndex && this.heap[rightChildIndex][0] < this.heap[smallestIndex][0]) {\n                    smallestIndex = rightChildIndex;\n                }\n\n                if (smallestIndex === index) break;\n\n                [this.heap[index], this.heap[smallestIndex]] = [this.heap[smallestIndex], this.heap[index]];\n                index = smallestIndex;\n            }\n        }\n    }\n\n    const minHeap = new MinHeap();\n    let currentMax = -Infinity;\n\n    // Add first element from each list to the minHeap\n    // Each element in heap: [value, list_index, element_index_in_list]\n    for (let i = 0; i < lists.length; i++) {\n        if (lists[i].length > 0) {\n            const val = lists[i][0];\n            minHeap.push([val, i, 0]);\n            currentMax = Math.max(currentMax, val);\n        }\n    }\n\n    let rangeStart = 0;\n    let rangeEnd = Infinity;\n    let minRangeLen = Infinity;\n\n    // Loop while the heap contains one element from each list\n    // This means minHeap.size() == lists.length\n    while (minHeap.size() === lists.length) {\n        const [val, listIdx, elementIdx] = minHeap.pop();\n\n        // Current range is [val, currentMax]\n        if (currentMax - val < minRangeLen) {\n            minRangeLen = currentMax - val;\n            rangeStart = val;\n            rangeEnd = currentMax;\n        }\n\n        // Move to the next element in the list from which \'val\' was taken\n        if (elementIdx + 1 < lists[listIdx].length) {\n            const nextVal = lists[listIdx][elementIdx + 1];\n            minHeap.push([nextVal, listIdx, elementIdx + 1]);\n            currentMax = Math.max(currentMax, nextVal);\n        } else {\n            // If any list is exhausted, we can\'t cover all lists anymore\n            break;\n        }\n    }\n\n    return [rangeStart, rangeEnd];\n}\n===END',
  ARRAY['k-way-merge'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'databricks-swe'],
  'k-way-merge',
  '[{"input":"find_smallest_range([[1, 5, 8], [4, 12], [7, 8, 10]])","expected_output":"[4, 7]"},{"input":"find_smallest_range([[1, 2, 3], [1, 2, 3], [1, 2, 3]])","expected_output":"[1, 1]"},{"input":"find_smallest_range([[1, 10], [5, 15]])","expected_output":"[5, 10]"}]'::jsonb,
  '[{"input":"find_smallest_range([[1], [2], [3]])","expected_output":"[1, 3]"},{"input":"find_smallest_range([[1, 3, 5], [2, 4, 6], [3, 5, 7]])","expected_output":"[3, 3]"}]'::jsonb
