INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-task-scheduling-order',
  'Task Scheduling Order (Return Order)',
  'hard',
  'Task Scheduling Order (Return Order)

<!-- voice:section_check concept="Returning valid task ordering" -->

Problem Statement

There are a total of `n` tasks you have to pick, labeled from `0` to `n-1`. Some tasks may have prerequisite tasks. Given the total number of tasks and a list of prerequisite pairs, return a valid ordering of tasks to finish all tasks. If multiple valid orderings exist, return any. If impossible, return empty list.

Examples

~~~
Input: n = 4, prerequisites = [[1, 0], [2, 0], [3, 1], [3, 2]]
Output: [0, 1, 2, 3] or [0, 2, 1, 3]
Explanation: 
- Task 0 has no prerequisites
- Tasks 1 and 2 depend on task 0
- Task 3 depends on tasks 1 and 2
~~~

~~~
Input: n = 2, prerequisites = [[1, 0], [0, 1]]
Output: []
Explanation: Cycle detected, impossible to schedule
~~~',
  '',
  '[{"input":"n = 4, prerequisites = [[1, 0], [2, 0], [3, 1], [3, 2]]","output":"[0, 1, 2, 3] or [0, 2, 1, 3]","explanation":"- Task 0 has no prerequisites"}]'::jsonb,
  'find_task_order',
  E'from collections import deque, defaultdict\ndef find_task_order(n, prerequisites):\n    """\n    Return a valid ordering of tasks to finish all tasks.\n\n    Args:\n        n: int, total number of tasks (0 to n-1)\n        prerequisites: List of [task, prerequisite] pairs\n    Returns:\n        List of task IDs in valid order, or empty list if impossible\n    Example:\n        >>> find_task_order(4, [[1, 0], [2, 0], [3, 1], [3, 2]])\n        [0, 1, 2, 3]  # or [0, 2, 1, 3]\n        >>> find_task_order(2, [[1, 0], [0, 1]])\n        []\n    """\n    # TODO: Return topological ordering of tasks\n    # Hint: Same as cycle detection but collect the order\n    pass\n# ─── Test Cases ───\n# Valid ordering\nresult = find_task_order(4, [[1, 0], [2, 0], [3, 1], [3, 2]])\n# Expected: [0, 1, 2, 3] or [0, 2, 1, 3]\n# Cycle\n# Expected: []\n# Linear chain\nresult = find_task_order(4, [[1, 0], [2, 1], [3, 2]])\n# Expected: [0, 1, 2, 3] (only valid order)\n# No prerequisites\nresult = find_task_order(3, [])\n# Expected: [0, 1, 2] (any order valid)\n# Single task\n# Expected: [0]\n# Complex case\nresult = find_task_order(6, [[3, 0], [3, 1], [4, 1], [4, 2], [5, 3], [5, 4]])\n# Expected: Valid topological order',
  E'from collections import deque, defaultdict\ndef find_task_order(n, prerequisites):\n    """\n    Return a valid ordering of tasks to finish all tasks.\n\n    Time Complexity: O(V + E)\n    Space Complexity: O(V + E)\n    """\n    # Build graph and calculate in-degrees\n    graph = defaultdict(list)\n    in_degree = [0] * n\n    for task, prereq in prerequisites:\n        graph[prereq].append(task)\n        in_degree[task] += 1\n    # Start with tasks having no prerequisites\n    queue = deque()\n    for i in range(n):\n        if in_degree[i] == 0:\n            queue.append(i)\n    result = []\n    while queue:\n        task = queue.popleft()\n        result.append(task)\n        # Process all tasks that depend on current task\n        for dependent in graph[task]:\n            in_degree[dependent] -= 1\n            if in_degree[dependent] == 0:\n                queue.append(dependent)\n    # Return order only if all tasks were processed\n    return result if len(result) == n else []\n# ─── Test Cases ───\nresult = find_task_order(4, [[1, 0], [2, 0], [3, 1], [3, 2]])\n# Expected: [0, 1, 2, 3] or [0, 2, 1, 3]\n# Expected: []\nresult = find_task_order(4, [[1, 0], [2, 1], [3, 2]])\n# Expected: [0, 1, 2, 3]\nresult = find_task_order(3, [])\n# Expected: [0, 1, 2]\n# Expected: [0]\nresult = find_task_order(6, [[3, 0], [3, 1], [4, 1], [4, 2], [5, 3], [5, 4]])\n# Expected: Valid order like [0, 1, 2, 3, 4, 5] or similar',
  E'class Solution {\n    public Object findTaskOrder(int n, Object prerequisites) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.HashMap;\n    // import java.util.LinkedList;\n    // import java.util.List;\n    // import java.util.Map;\n    // import java.util.Queue;\n\n    public static boolean canFinishTasks(int n, int[][] prerequisites) {\n        // Build adjacency list and in-degree count\n        Map<Integer, List<Integer>> graph = new HashMap<>();\n        int[] inDegree = new int[n];\n\n        for (int i = 0; i < n; i++) {\n            graph.put(i, new ArrayList<>());\n        }\n\n        for (int[] prereq : prerequisites) {\n            int task = prereq[0];\n            int pre = prereq[1];\n            graph.get(pre).add(task);\n            inDegree[task]++;\n        }\n\n        // Start with tasks having no prerequisites\n        Queue<Integer> queue = new LinkedList<>();\n        for (int i = 0; i < n; i++) {\n            if (inDegree[i] == 0) {\n                queue.offer(i);\n            }\n        }\n\n        int processed = 0;\n        while (!queue.isEmpty()) {\n            int task = queue.poll();\n            processed++;\n\n            // Reduce in-degree for all dependent tasks\n            for (int dependent : graph.get(task)) {\n                inDegree[dependent]--;\n                if (inDegree[dependent] == 0) {\n                    queue.offer(dependent);\n                }\n            }\n        }\n\n        // If we processed all tasks, no cycle exists\n        return processed == n;\n    }\n}',
  E'/**\n * @param {any, any} n, prerequisites\n * @return {any}\n */\nfunction findTaskOrder(n, prerequisites) {\n    // Your code here\n}',
  E'function canFinishTasks(n, prerequisites) {\n    // Build adjacency list and in-degree count\n    const graph = new Map();\n    const inDegree = new Array(n).fill(0);\n\n    for (let i = 0; i < n; i++) {\n        graph.set(i, []);\n    }\n\n    for (const [task, prereq] of prerequisites) {\n        graph.get(prereq).push(task);\n        inDegree[task]++;\n    }\n\n    // Start with tasks having no prerequisites\n    const queue = []; // Using array as a queue\n    for (let i = 0; i < n; i++) {\n        if (inDegree[i] === 0) {\n            queue.push(i);\n        }\n    }\n\n    let processed = 0;\n    while (queue.length > 0) {\n        const task = queue.shift(); // Dequeue\n        processed++;\n\n        // Reduce in-degree for all dependent tasks\n        for (const dependent of graph.get(task)) {\n            inDegree[dependent]--;\n            if (inDegree[dependent] === 0) {\n                queue.push(dependent); // Enqueue\n            }\n        }\n    }\n\n    // If we processed all tasks, no cycle exists\n    return processed === n;\n}\n===END',
  ARRAY['topological-sort', 'sorting'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'uber-sde2', 'airbnb-swe'],
  'topological-sort',
  '[{"input":"find_task_order(2, [[1, 0], [0, 1]])","expected_output":"[]"},{"input":"find_task_order(1, [])","expected_output":"[0]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
