INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-all-tasks-scheduling-orders',
  'All Tasks Scheduling Orders',
  'hard',
  'All Tasks Scheduling Orders

<!-- voice:section_check concept="Generating all valid topological orders" -->

Problem Statement

Given tasks (0 to n-1) and prerequisites, find all possible orderings of tasks that satisfy all prerequisites.

Examples

~~~
Input: n = 3, prerequisites = [[0, 1], [1, 2]]
Output: [[2, 1, 0]]
Explanation: Only one valid order: 2 -> 1 -> 0
~~~

~~~
Input: n = 4, prerequisites = [[1, 0], [2, 0]]
Output: [[0, 1, 2, 3], [0, 2, 1, 3]]
Explanation: Tasks 1 and 2 both depend on 0, but are independent of each other
~~~',
  '',
  '[{"input":"n = 3, prerequisites = [[0, 1], [1, 2]]","output":"[[2, 1, 0]]","explanation":"Only one valid order: 2 -> 1 -> 0"}]'::jsonb,
  'find_all_task_orders',
  E'from collections import defaultdict\ndef find_all_task_orders(n, prerequisites):\n    """\n    Find all possible valid orderings of tasks.\n\n    Args:\n        n: int, total number of tasks (0 to n-1)\n        prerequisites: List of [task, prerequisite] pairs\n    Returns:\n        List of all valid orderings (each ordering is a list)\n    Example:\n        >>> find_all_task_orders(3, [[0, 1], [1, 2]])\n        [[2, 1, 0]]\n        >>> find_all_task_orders(4, [[1, 0], [2, 0]])\n        [[0, 1, 2, 3], [0, 2, 1, 3]]\n    """\n    # TODO: Use backtracking with topological sort\n    # Hint: Try all tasks with in-degree 0 at each step, backtrack\n    pass\n# ─── Test Cases ───\n# Single valid order\n# Expected: [[2, 1, 0]]\n# Multiple valid orders\nresult = find_all_task_orders(4, [[1, 0], [2, 0]])\n# Expected: [[0, 1, 2, 3], [0, 2, 1, 3]] (order may vary)\n# No prerequisites\nresult = find_all_task_orders(3, [])\n# Expected: 6 (3! permutations)\n# Linear chain\n# Expected: [[0, 1, 2, 3]] (only one order)\n# More complex\nresult = find_all_task_orders(6, [[3, 2], [3, 0], [5, 2], [5, 0]])\n# Expected: Multiple valid orders',
  E'from collections import defaultdict\ndef find_all_task_orders(n, prerequisites):\n    """\n    Find all possible valid orderings of tasks.\n\n    Time Complexity: O(V! × E) — exponential in worst case\n    Space Complexity: O(V + E) — recursion and graph\n    """\n    # Build graph\n    graph = defaultdict(list)\n    in_degree = [0] * n\n    for task, prereq in prerequisites:\n        graph[prereq].append(task)\n        in_degree[task] += 1\n    result = []\n    def backtrack(current_order, current_in_degree):\n        # Base case: all tasks scheduled\n        if len(current_order) == n:\n            result.append(list(current_order))\n            return\n\n        # Try each task with in-degree 0\n        for task in range(n):\n            if current_in_degree[task] == 0:\n                # Choose this task\n                current_order.append(task)\n                # Save state for backtracking\n                saved_changes = []\n                for dependent in graph[task]:\n                    if current_in_degree[dependent] > 0:\n                        current_in_degree[dependent] -= 1\n                        saved_changes.append(dependent)\n                # Mark as processed\n                current_in_degree[task] = -1\n                # Recurse\n                backtrack(current_order, current_in_degree)\n                # Backtrack: restore state\n                current_in_degree[task] = 0\n                for dependent in saved_changes:\n                    current_in_degree[dependent] += 1\n                current_order.pop()\n    backtrack([], in_degree[:])\n    return result\n# ─── Test Cases ───\n# Expected: [[2, 1, 0]]\nresult = find_all_task_orders(4, [[1, 0], [2, 0]])\n# Expected: [[0, 1, 2, 3], [0, 2, 1, 3]]\nresult = find_all_task_orders(3, [])\n# Expected: 6\n# Expected: [[0, 1, 2, 3]]\nresult = find_all_task_orders(6, [[3, 2], [3, 0], [5, 2], [5, 0]])\n# Expected: Multiple orders',
  E'class Solution {\n    public Object findAllTaskOrders(int n, Object prerequisites) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.*;\n\nclass Solution {\n    public static List<List<Integer>> findAllTaskOrders(int n, int[][] prerequisites) {\n        // Build graph\n        List<List<Integer>> graph = new ArrayList<>();\n        for (int i = 0; i < n; i++) {\n            graph.add(new ArrayList<>());\n        }\n\n        int[] inDegree = new int[n];\n        for (int[] prereqPair : prerequisites) {\n            int task = prereqPair[0];\n            int prereq = prereqPair[1];\n            graph.get(prereq).add(task);\n            inDegree[task]++;\n        }\n\n        List<List<Integer>> result = new ArrayList<>();\n        List<Integer> currentOrder = new ArrayList<>();\n\n        backtrack(n, graph, inDegree, currentOrder, result);\n\n        return result;\n    }\n\n    private static void backtrack(int n, List<List<Integer>> graph, int[] currentInDegree,\n                                  List<Integer> currentOrder, List<List<Integer>> result) {\n        // Base case: all tasks scheduled\n        if (currentOrder.size() == n) {\n            result.add(new ArrayList<>(currentOrder));\n            return;\n        }\n\n        // Try each task with in-degree 0\n        for (int task = 0; task < n; task++) {\n            if (currentInDegree[task] == 0) {\n                // Choose this task\n                currentOrder.add(task);\n\n                // Save state for backtracking\n                List<Integer> savedChanges = new ArrayList<>();\n                for (int dependent : graph.get(task)) {\n                    if (currentInDegree[dependent] > 0) { // Only decrement if > 0 to avoid negative\n                        currentInDegree[dependent]--;\n                        savedChanges.add(dependent);\n                    }\n                }\n\n                // Mark as processed (by setting in-degree to -1)\n                currentInDegree[task] = -1;\n\n                // Recurse\n                backtrack(n, graph, currentInDegree, currentOrder, result);\n\n                // Backtrack: restore state\n                currentInDegree[task] = 0; // Restore in-degree for current task\n                for (int dependent : savedChanges) {\n                    currentInDegree[dependent]++; // Restore in-degree for dependents\n                }\n                currentOrder.remove(currentOrder.size() - 1); // Remove last added task\n            }\n        }\n    }\n}',
  E'/**\n * @param {any, any} n, prerequisites\n * @return {any}\n */\nfunction findAllTaskOrders(n, prerequisites) {\n    // Your code here\n}',
  E'function findAllTaskOrders(n, prerequisites) {\n    // Build graph\n    const graph = new Array(n).fill(0).map(() => []);\n    const inDegree = new Array(n).fill(0);\n\n    for (const [task, prereq] of prerequisites) {\n        graph[prereq].push(task);\n        inDegree[task]++;\n    }\n\n    const result = [];\n    const currentOrder = [];\n\n    function backtrack(currentInDegree) {\n        // Base case: all tasks scheduled\n        if (currentOrder.length === n) {\n            result.push([...currentOrder]); // Add a copy\n            return;\n        }\n\n        // Try each task with in-degree 0\n        for (let task = 0; task < n; task++) {\n            if (currentInDegree[task] === 0) {\n                // Choose this task\n                currentOrder.push(task);\n\n                // Save state for backtracking\n                const savedChanges = [];\n                for (const dependent of graph[task]) {\n                    if (currentInDegree[dependent] > 0) {\n                        currentInDegree[dependent]--;\n                        savedChanges.push(dependent);\n                    }\n                }\n\n                // Mark as processed (by setting in-degree to -1)\n                currentInDegree[task] = -1;\n\n                // Recurse\n                backtrack(currentInDegree);\n\n                // Backtrack: restore state\n                currentInDegree[task] = 0; // Restore in-degree for current task\n                for (const dependent of savedChanges) {\n                    currentInDegree[dependent]++; // Restore in-degree for dependents\n                }\n                currentOrder.pop(); // Remove last added task\n            }\n        }\n    }\n\n    backtrack([...inDegree]); // Pass a copy of inDegree\n    return result;\n}',
  ARRAY['topological-sort', 'sorting'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'uber-sde2', 'airbnb-swe'],
  'topological-sort',
  '[{"input":"find_all_task_orders(3, [[0, 1], [1, 2]])","expected_output":"[[2, 1, 0]]"},{"input":"find_all_task_orders(4, [[1, 0], [2, 1], [3, 2]])","expected_output":"[[0, 1, 2, 3]] (only one order)"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
