INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-alien-dictionary',
  'Alien Dictionary (Verifying/Changing)',
  'hard',
  'Alien Dictionary (Verifying/Changing)

<!-- voice:section_check concept="Deriving character order from words" -->

Problem Statement

There is a new alien language that uses the English alphabet. However, the order of the letters is unknown to you.

You are given a list of strings `words` from the dictionary, where the strings are sorted lexicographically by the rules of this new language.

Derive the order of letters in this language. Return empty string if invalid (cycle detected).

Examples

~~~
Input: words = ["wrt", "wrf", "er", "ett", "rftt"]
Output: "wertf"
Explanation: 
- From "wrt" and "wrf": t comes before f
- From "wrt" and "er": w comes before e
- From "er" and "ett": r comes before t
- From "ett" and "rftt": e comes before r
~~~

~~~
Input: words = ["z", "x"]
Output: "zx"
~~~

~~~
Input: words = ["z", "x", "z"]
Output: ""
Explanation: Invalid order (cycle)
~~~',
  '',
  '[{"input":"words = [\"wrt\", \"wrf\", \"er\", \"ett\", \"rftt\"]","output":"\"wertf\"","explanation":"- From \"wrt\" and \"wrf\": t comes before f"}]'::jsonb,
  'alien_order',
  E'from collections import deque, defaultdict\ndef alien_order(words):\n    """\n    Derive the order of letters in alien dictionary.\n\n    Args:\n        words: List of strings sorted lexicographically in alien language\n    Returns:\n        str: Order of letters, or empty string if invalid\n    Example:\n        >>> alien_order(["wrt", "wrf", "er", "ett", "rftt"])\n        "wertf"\n        >>> alien_order(["z", "x"])\n        "zx"\n        >>> alien_order(["z", "x", "z"])\n        ""\n    """\n    # TODO: Build graph from word comparisons, then topological sort\n    # Hint: Compare adjacent words to find edges\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: "wertf" (or any valid order)\n# Simple case\n# Expected: "zx"\n# Cycle detected\n# Expected: ""\n# Single word\nresult = alien_order(["abc"])\n# Expected: "abc" (letters in any order)\n# All same prefix\n# Expected: "" (invalid: longer word before shorter)\n# Multiple valid orders possible\nresult = alien_order(["abc", "acd"])\n# Expected: valid order with b before c, a before c',
  E'from collections import deque, defaultdict\ndef alien_order(words):\n    """\n    Derive the order of letters in alien dictionary.\n\n    Time Complexity: O(C) where C is total characters\n    Space Complexity: O(1) — at most 26 unique chars\n    """\n    # Step 1: Find all unique characters\n    chars = set()\n    for word in words:\n        for c in word:\n            chars.add(c)\n    # Step 2: Build graph by comparing adjacent words\n    graph = defaultdict(set)\n    in_degree = {c: 0 for c in chars}\n    for i in range(len(words) - 1):\n        word1, word2 = words[i], words[i + 1]\n        # Check for invalid case: word2 is prefix of word1\n        if len(word1) > len(word2) and word1[:len(word2)] == word2:\n            return ""\n        # Find first differing character\n        for j in range(min(len(word1), len(word2))):\n            if word1[j] != word2[j]:\n                c1, c2 = word1[j], word2[j]\n                if c2 not in graph[c1]:\n                    graph[c1].add(c2)\n                    in_degree[c2] += 1\n                break\n    # Step 3: Topological sort (Kahn''s algorithm)\n    queue = deque()\n    for c in chars:\n        if in_degree[c] == 0:\n            queue.append(c)\n    result = []\n    while queue:\n        c = queue.popleft()\n        result.append(c)\n        for neighbor in graph[c]:\n            in_degree[neighbor] -= 1\n            if in_degree[neighbor] == 0:\n                queue.append(neighbor)\n    # Check for cycle\n    if len(result) != len(chars):\n        return ""\n    return "".join(result)\n# ─── Test Cases ───\n# Expected: "wertf"\n# Expected: "zx"\n# Expected: ""\nresult = alien_order(["abc"])\n# Expected: "abc"\n# Expected: ""\nresult = alien_order(["abc", "acd"])\n# Expected: Valid order',
  E'class Solution {\n    public Object alienOrder(Object words) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.HashMap;\n    // import java.util.LinkedList;\n    // import java.util.List;\n    // import java.util.Map;\n    // import java.util.Queue;\n\n    public static List<Integer> findTaskOrder(int n, int[][] prerequisites) {\n        // Build graph and calculate in-degrees\n        Map<Integer, List<Integer>> graph = new HashMap<>();\n        int[] inDegree = new int[n];\n\n        for (int i = 0; i < n; i++) {\n            graph.put(i, new ArrayList<>());\n        }\n\n        for (int[] prereq : prerequisites) {\n            int task = prereq[0];\n            int pre = prereeq[1];\n            graph.get(pre).add(task);\n            inDegree[task]++;\n        }\n\n        // Start with tasks having no prerequisites\n        Queue<Integer> queue = new LinkedList<>();\n        for (int i = 0; i < n; i++) {\n            if (inDegree[i] == 0) {\n                queue.offer(i);\n            }\n        }\n\n        List<Integer> result = new ArrayList<>();\n        while (!queue.isEmpty()) {\n            int task = queue.poll();\n            result.add(task);\n\n            // Process all tasks that depend on current task\n            for (int dependent : graph.get(task)) {\n                inDegree[dependent]--;\n                if (inDegree[dependent] == 0) {\n                    queue.offer(dependent);\n                }\n            }\n        }\n\n        // Return order only if all tasks were processed\n        return result.size() == n ? result : new ArrayList<>();\n    }\n}''s algorithm)\n    //     queue = deque()\n    //     for c in chars:\n    //         if in_degree[c] == 0:\n    //             queue.append(c)\n    //     \n    //     result = []\n    //     while queue:\n    //         c = queue.popleft()\n    //         result.append(c)\n    //         \n    //         for neighbor in graph[c]:\n    //             in_degree[neighbor] -= 1\n    //             if in_degree[neighbor] == 0:\n    //                 queue.append(neighbor)\n    //     \n    //     # Check for cycle\n    //     if len(result) != len(chars):\n    //         return ""\n    //     \n    //     return "".join(result)\n    // \n    // \n    // # ─── Test Cases ───\n    // # Expected: "wertf"\n    // \n    // # Expected: "zx"\n    // \n    // # Expected: ""\n    // \n    // result = alien_order(["abc"])\n    // # Expected: "abc"\n    // \n    // # Expected: ""\n    // \n    // result = alien_order(["abc", "acd"])\n    // # Expected: Valid order\n    // \n}',
  E'/**\n * @param {any} words\n * @return {any}\n */\nfunction alienOrder(words) {\n    // Your code here\n}',
  E'function findTaskOrder(n, prerequisites) {\n    // Build graph and calculate in-degrees\n    const graph = new Map();\n    const inDegree = new Array(n).fill(0);\n\n    for (let i = 0; i < n; i++) {\n        graph.set(i, []);\n    }\n\n    for (const [task, prereq] of prerequisites) {\n        graph.get(prereq).push(task);\n        inDegree[task]++;\n    }\n\n    // Start with tasks having no prerequisites\n    const queue = []; // Using array as a queue\n    for (let i = 0; i < n; i++) {\n        if (inDegree[i] === 0) {\n            queue.push(i);\n        }\n    }\n\n    const result = [];\n    while (queue.length > 0) {\n        const task = queue.shift(); // Dequeue\n        result.push(task);\n\n        // Process all tasks that depend on current task\n        for (const dependent of graph.get(task)) {\n            inDegree[dependent]--;\n            if (inDegree[dependent] === 0) {\n                queue.push(dependent); // Enqueue\n            }\n        }\n    }\n\n    // Return order only if all tasks were processed\n    return result.length === n ? result : [];\n}\n===END',
  ARRAY['topological-sort', 'sorting'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'uber-sde2', 'airbnb-swe'],
  'topological-sort',
  '[{"input":"alien_order([\"wrt\", \"wrf\", \"er\", \"ett\", \"rftt\"])","expected_output":"\"wertf\" (or any valid order)"},{"input":"alien_order([\"z\", \"x\"])","expected_output":"\"zx\""},{"input":"alien_order([\"z\", \"x\", \"z\"])","expected_output":"\"\""}]'::jsonb,
  '[{"input":"alien_order([\"abc\", \"ab\"])","expected_output":"\"\" (invalid: longer word before shorter)"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
