INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-zero-one-knapsack',
  '0/1 Knapsack Problem',
  'hard',
  '0/1 Knapsack Problem

<!-- voice:section_check concept="Classic DP problem" -->

Problem Statement

Given two integer arrays `weights` and `values` representing items, and an integer `capacity` representing knapsack capacity, return the maximum value you can achieve without exceeding capacity.

Each item can be selected at most once (0/1 property).

Examples

~~~
Input: weights = [1, 2, 3], values = [6, 10, 12], capacity = 5
Output: 22
Explanation: Select items with weights 2 and 3 (values 10 + 12 = 22)
~~~

~~~
Input: weights = [1, 3, 4, 5], values = [1, 4, 5, 7], capacity = 7
Output: 9
Explanation: Select items with weights 3 and 4 (values 4 + 5 = 9)
~~~',
  '',
  '[{"input":"weights = [1, 2, 3], values = [6, 10, 12], capacity = 5","output":"22","explanation":"Select items with weights 2 and 3 (values 10 + 12 = 22)"}]'::jsonb,
  'knapsack',
  E'def knapsack(weights, values, capacity):\n    """\n    Solve 0/1 Knapsack problem.\n\n    Args:\n        weights: List of item weights\n        values: List of item values\n        capacity: int, maximum weight capacity\n    Returns:\n        int: Maximum achievable value\n    Example:\n        >>> knapsack([1, 2, 3], [6, 10, 12], 5)\n        22\n        >>> knapsack([1, 3, 4, 5], [1, 4, 5, 7], 7)\n        9\n    """\n    # TODO: Implement 0/1 Knapsack with space optimization\n    # Hint: Use 1D dp array, iterate capacity backwards\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: 22\n# Example from above\n# Expected: 9\n# Cannot take any item\n# Expected: 0\n# Can take all items\n# Expected: 60\n# Single item fits\n# Expected: 10\n# Single item doesn''t fit\n# Expected: 0',
  E'def knapsack(weights, values, capacity):\n    """\n    Solve 0/1 Knapsack problem with space optimization.\n\n    Time Complexity: O(n × capacity)\n    Space Complexity: O(capacity)\n    """\n    n = len(weights)\n    # dp[c] = max value achievable with capacity c\n    dp = [0] * (capacity + 1)\n    for i in range(n):\n        # Iterate backwards to avoid using updated values\n        for c in range(capacity, weights[i] - 1, -1):\n            # Option 1: Skip item i -> dp[c] stays same\n            # Option 2: Take item i -> values[i] + dp[c - weights[i]]\n            dp[c] = max(dp[c], values[i] + dp[c - weights[i]])\n    return dp[capacity]\n# Full 2D solution for clarity\ndef knapsack_2d(weights, values, capacity):\n    """\n    2D DP solution showing the complete state.\n    """\n    n = len(weights)\n\n    # dp[i][c] = max value using first i items with capacity c\n    dp = [[0] * (capacity + 1) for _ in range(n + 1)]\n    for i in range(1, n + 1):\n        for c in range(capacity + 1):\n            # Skip item i-1\n            dp[i][c] = dp[i-1][c]\n            # Take item i-1 if possible\n            if weights[i-1] <= c:\n                dp[i][c] = max(dp[i][c], \n                               values[i-1] + dp[i-1][c - weights[i-1]])\n    return dp[n][capacity]\n# ─── Test Cases ───\n# Expected: 22\n# Expected: 9\n# Expected: 0\n# Expected: 60\n# Expected: 10\n# Expected: 0',
  E'class Solution {\n    public Object knapsack(Object weights, Object values, int capacity) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.*;\n\nclass Solution {\n    public static int knapsack(int[] weights, int[] values, int capacity) {\n        int n = weights.length;\n        // dp[c] = max value achievable with capacity c\n        int[] dp = new int[capacity + 1];\n\n        for (int i = 0; i < n; i++) {\n            // Iterate backwards to avoid using updated values from the current item\n            for (int c = capacity; c >= weights[i]; c--) {\n                // Option 1: Skip item i -> dp[c] stays same\n                // Option 2: Take item i -> values[i] + dp[c - weights[i]]\n                dp[c] = Math.max(dp[c], values[i] + dp[c - weights[i]]);\n            }\n        }\n        return dp[capacity];\n    }\n}',
  E'/**\n * @param {any, any, any} weights, values, capacity\n * @return {any}\n */\nfunction knapsack(weights, values, capacity) {\n    // Your code here\n}',
  E'function knapsack(weights, values, capacity) {\n    const n = weights.length;\n    // dp[c] = max value achievable with capacity c\n    const dp = new Array(capacity + 1).fill(0);\n\n    for (let i = 0; i < n; i++) {\n        // Iterate backwards to avoid using updated values from the current item\n        for (let c = capacity; c >= weights[i]; c--) {\n            // Option 1: Skip item i -> dp[c] stays same\n            // Option 2: Take item i -> values[i] + dp[c - weights[i]]\n            dp[c] = Math.max(dp[c], values[i] + dp[c - weights[i]]);\n        }\n    }\n    return dp[capacity];\n}',
  ARRAY['dynamic-programming'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'stripe-l2'],
  'dynamic-programming',
  '[{"input":"knapsack([1, 2, 3], [6, 10, 12], 5)","expected_output":"22"},{"input":"knapsack([1, 3, 4, 5], [1, 4, 5, 7], 7)","expected_output":"9"},{"input":"knapsack([3, 4, 5], [10, 20, 30], 2)","expected_output":"0"}]'::jsonb,
  '[{"input":"knapsack([1, 2, 3], [10, 20, 30], 6)","expected_output":"60"},{"input":"knapsack([2], [10], 5)","expected_output":"10"},{"input":"knapsack([5], [10], 3)","expected_output":"0"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
