INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-equal-subset-sum-partition',
  'Equal Subset Sum Partition',
  'hard',
  'Equal Subset Sum Partition

<!-- voice:section_check concept="Subset sum variation" -->

Problem Statement

Given a set of positive numbers, determine if it can be partitioned into two subsets such that the sum of elements in both subsets is equal.

Examples

~~~
Input: [1, 2, 3, 4]
Output: true
Explanation: Can be partitioned into [1, 4] and [2, 3], both sum to 5
~~~

~~~
Input: [1, 1, 3, 4, 7]
Output: true
Explanation: Can be partitioned into [1, 3, 4] and [1, 7], both sum to 8
~~~

~~~
Input: [2, 3, 4, 6]
Output: false
Explanation: Cannot partition into equal sum subsets
~~~',
  '',
  '[{"input":"[1, 2, 3, 4]","output":"true","explanation":"Can be partitioned into [1, 4] and [2, 3], both sum to 5"}]'::jsonb,
  'can_partition',
  E'def can_partition(nums):\n    """\n    Determine if array can be partitioned into two equal sum subsets.\n\n    Args:\n        nums: List of positive integers\n    Returns:\n        bool: True if equal partition possible\n    Example:\n        >>> can_partition([1, 2, 3, 4])\n        True\n        >>> can_partition([1, 1, 3, 4, 7])\n        True\n        >>> can_partition([2, 3, 4, 6])\n        False\n    """\n    # TODO: Transform to subset sum problem (variation of knapsack)\n    # Hint: Check if sum is even, then find subset with sum = total/2\n    pass\n# ─── Test Cases ───\n# Can partition\n# Expected: True\n# Can partition\n# Expected: True\n# Cannot partition\n# Expected: False\n# Odd sum\n# Expected: False (sum=6, wait that''s even... try [1,2,5] sum=8 but no partition)\n# Actually odd sum\n# Expected: False (sum=8, no valid partition)\n# Single element\n# Expected: False (can''t partition single element)\n# Two equal elements\n# Expected: True',
  E'def can_partition(nums):\n    """\n    Determine if array can be partitioned into two equal sum subsets.\n\n    Time Complexity: O(n × sum)\n    Space Complexity: O(sum)\n    """\n    total = sum(nums)\n    # If total is odd, can''t partition equally\n    if total % 2 != 0:\n        return False\n    target = total // 2\n    # dp[s] = can we achieve sum s?\n    dp = [False] * (target + 1)\n    dp[0] = True  # Sum 0 is always achievable\n    for num in nums:\n        # Iterate backwards to avoid reuse\n        for s in range(target, num - 1, -1):\n            dp[s] = dp[s] or dp[s - num]\n    return dp[target]\n# Alternative: Set-based approach\ndef can_partition_set(nums):\n    """\n    Alternative using set to track achievable sums.\n    """\n    total = sum(nums)\n\n    if total % 2 != 0:\n        return False\n    target = total // 2\n    possible_sums = {0}\n    for num in nums:\n        new_sums = set()\n        for s in possible_sums:\n            if s + num == target:\n                return True\n            new_sums.add(s + num)\n        possible_sums = possible_sums.union(new_sums)\n    return target in possible_sums\n# ─── Test Cases ───\n# Expected: True\n# Expected: True\n# Expected: False\n# Expected: False\n# Expected: False\n# Expected: True',
  E'class Solution {\n    public Object canPartition(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.HashMap;\n    // import java.util.List;\n    // import java.util.Map;\n\n    public static List<List<Integer>> findAllTaskOrders(int n, int[][] prerequisites) {\n        // Build graph\n        Map<Integer, List<Integer>> graph = new HashMap<>();\n        int[] inDegree = new int[n];\n\n        for (int i = 0; i < n; i++) {\n            graph.put(i, new ArrayList<>());\n        }\n\n        for (int[] prereq : prerequisites) {\n            int task = prereq[0];\n            int pre = prereq[1];\n            graph.get(pre).add(task);\n            inDegree[task]++;\n        }\n\n        List<List<Integer>> result = new ArrayList<>();\n        List<Integer> currentOrder = new ArrayList<>();\n\n        // Create a copy of inDegree for the initial call\n        int[] initialInDegree = inDegree.clone();\n\n        backtrack(n, graph, initialInDegree, currentOrder, result);\n        return result;\n    }\n\n    private static void backtrack(int n, Map<Integer, List<Integer>> graph,\n                                  int[] currentInDegree, List<Integer> currentOrder,\n                                  List<List<Integer>> result) {\n        // Base case: all tasks scheduled\n        if (currentOrder.size() == n) {\n            result.add(new ArrayList<>(currentOrder));\n            return;\n        }\n\n        // Try each task with in-degree 0\n        for (int task = 0; task < n; task++) {\n            if (currentInDegree[task] == 0) {\n                // Choose this task\n                currentOrder.add(task);\n                \n                // Mark as processed by setting in-degree to -1\n                // This prevents it from being chosen again in the current path\n                currentInDegree[task] = -1; \n\n                // Reduce in-degree for all dependent tasks\n                List<Integer> savedChanges = new ArrayList<>();\n                for (int dependent : graph.get(task)) {\n                    if (currentInDegree[dependent] > 0) { // Only decrement if not already processed\n                        currentInDegree[dependent]--;\n                        savedChanges.add(dependent); // Store dependents whose in-degree was changed\n                    }\n                }\n\n                // Recurse\n                backtrack(n, graph, currentInDegree, currentOrder, result);\n\n                // Backtrack: restore state\n                currentInDegree[task] = 0; // Mark as available again\n                for (int dependent : savedChanges) {\n                    currentInDegree[dependent]++; // Restore in-degree\n                }\n                currentOrder.remove(currentOrder.size() - 1); // Remove last task\n            }\n        }\n    }\n}''t partition equally\n    //     if total % 2 != 0:\n    //         return False\n    //     \n    //     target = total // 2\n    //     \n    //     # dp[s] = can we achieve sum s?\n    //     dp = [False] * (target + 1)\n    //     dp[0] = True  # Sum 0 is always achievable\n    //     \n    //     for num in nums:\n    //         # Iterate backwards to avoid reuse\n    //         for s in range(target, num - 1, -1):\n    //             dp[s] = dp[s] or dp[s - num]\n    //     \n    //     return dp[target]\n    // \n    // \n    // # Alternative: Set-based approach\n    // def can_partition_set(nums):\n    //     """\n    //     Alternative using set to track achievable sums.\n    //     """\n    //     total = sum(nums)\n    //     \n    //     if total % 2 != 0:\n    //         return False\n    //     \n    //     target = total // 2\n    //     possible_sums = {0}\n    //     \n    //     for num in nums:\n    //         new_sums = set()\n    //         for s in possible_sums:\n    //             if s + num == target:\n    //                 return True\n    //             new_sums.add(s + num)\n    //         possible_sums = possible_sums.union(new_sums)\n    //     \n    //     return target in possible_sums\n    // \n    // \n    // # ─── Test Cases ───\n    // # Expected: True\n    // \n    // # Expected: True\n    // \n    // # Expected: False\n    // \n    // # Expected: False\n    // \n    // # Expected: False\n    // \n    // # Expected: True\n    // \n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction canPartition(nums) {\n    // Your code here\n}',
  E'function findAllTaskOrders(n, prerequisites) {\n    // Build graph\n    const graph = new Map();\n    const inDegree = new Array(n).fill(0);\n\n    for (let i = 0; i < n; i++) {\n        graph.set(i, []);\n    }\n\n    for (const [task, prereq] of prerequisites) {\n        graph.get(prereq).push(task);\n        inDegree[task]++;\n    }\n\n    const result = [];\n    const currentOrder = [];\n\n    // The backtrack function needs to modify currentInDegree, so we pass a copy\n    // or ensure modifications are reverted. Python\'s `in_degree[:]` creates a shallow copy.\n    // Here, we\'ll pass the original and carefully revert changes.\n\n    function backtrack(currentInDegreeCopy) {\n        // Base case: all tasks scheduled\n        if (currentOrder.length === n) {\n            result.push([...currentOrder]); // Add a copy of the current order\n            return;\n        }\n\n        // Try each task with in-degree 0\n        for (let task = 0; task < n; task++) {\n            if (currentInDegreeCopy[task] === 0) {\n                // Choose this task\n                currentOrder.push(task);\n                \n                // Mark as processed by setting in-degree to -1\n                // This prevents it from being chosen again in the current path\n                currentInDegreeCopy[task] = -1; \n\n                // Reduce in-degree for all dependent tasks\n                const savedChanges = [];\n                for (const dependent of graph.get(task)) {\n                    // Only decrement if not already processed (i.e., inDegree > 0)\n                    if (currentInDegreeCopy[dependent] > 0) { \n                        currentInDegreeCopy[dependent]--;\n                        savedChanges.push(dependent); // Store dependents whose in-degree was changed\n                    }\n                }\n\n                // Recurse\n                backtrack(currentInDegreeCopy);\n\n                // Backtrack: restore state\n                currentInDegreeCopy[task] = 0; // Mark as available again\n                for (const dependent of savedChanges) {\n                    currentInDegreeCopy[dependent]++; // Restore in-degree\n                }\n                currentOrder.pop(); // Remove last task\n            }\n        }\n    }\n\n    backtrack([...inDegree]); // Pass a shallow copy of the initial inDegree\n    return result;\n}\n===END',
  ARRAY['dynamic-programming'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'stripe-l2'],
  'dynamic-programming',
  '[{"input":"can_partition([1, 2, 3, 4])","expected_output":"True"},{"input":"can_partition([1, 1, 3, 4, 7])","expected_output":"True"},{"input":"can_partition([2, 3, 4, 6])","expected_output":"False"}]'::jsonb,
  '[{"input":"can_partition([1, 2, 3])","expected_output":"False (sum=6, wait that''s even... try [1,2,5] sum=8 but no partition)"},{"input":"can_partition([1, 2, 5])","expected_output":"False (sum=8, no valid partition)"},{"input":"can_partition([1])","expected_output":"False (can''t partition single element)"},{"input":"can_partition([5, 5])","expected_output":"True"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
