INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-subset-sum-problem',
  'Subset Sum Problem',
  'hard',
  'Subset Sum Problem

<!-- voice:section_check concept="Classic subset sum" -->

Problem Statement

Given a set of positive numbers and a target sum `S`, determine if there exists a subset whose sum is equal to `S`.

Examples

~~~
Input: nums = [1, 2, 3, 7], S = 6
Output: true
Explanation: Subset [1, 2, 3] sums to 6
~~~

~~~
Input: nums = [1, 3, 4, 8], S = 6
Output: false
Explanation: No subset sums to 6
~~~

~~~
Input: nums = [2, 3, 7, 8, 10], S = 11
Output: true
Explanation: Subset [3, 8] sums to 11
~~~',
  '',
  '[{"input":"nums = [1, 2, 3, 7], S = 6","output":"true","explanation":"Subset [1, 2, 3] sums to 6"}]'::jsonb,
  'subset_sum',
  E'def subset_sum(nums, target):\n    """\n    Determine if a subset with given target sum exists.\n\n    Args:\n        nums: List of positive integers\n        target: int, target sum\n    Returns:\n        bool: True if subset with target sum exists\n    Example:\n        >>> subset_sum([1, 2, 3, 7], 6)\n        True\n        >>> subset_sum([1, 3, 4, 8], 6)\n        False\n        >>> subset_sum([2, 3, 7, 8, 10], 11)\n        True\n    """\n    # TODO: Apply knapsack pattern to find subset sum\n    # Hint: dp[s] = can we achieve sum s?\n    pass\n# ─── Test Cases ───\n# Subset exists\n# Expected: True\n# No subset\n# Expected: False\n# Another subset exists\n# Expected: True\n# Target is 0 (empty subset)\n# Expected: True\n# Single element matches\n# Expected: True\n# Single element doesn''t match\n# Expected: False\n# Larger target\n# Expected: True (4 + 5 = 9)',
  E'def subset_sum(nums, target):\n    """\n    Determine if a subset with given target sum exists.\n\n    Time Complexity: O(n × target)\n    Space Complexity: O(target)\n    """\n    # dp[s] = can we achieve sum s?\n    dp = [False] * (target + 1)\n    dp[0] = True  # Sum 0 is always achievable (empty subset)\n    for num in nums:\n        # Iterate backwards to avoid reuse\n        for s in range(target, num - 1, -1):\n            dp[s] = dp[s] or dp[s - num]\n    return dp[target]\n# Alternative: Recursive with memoization\ndef subset_sum_recursive(nums, target):\n    """\n    Top-down recursive solution.\n    """\n    memo = {}\n\n    def helper(idx, remaining):\n        if remaining == 0:\n            return True\n        if idx >= len(nums) or remaining < 0:\n            return False\n\n        if (idx, remaining) in memo:\n            return memo[(idx, remaining)]\n        # Include current or skip\n        result = helper(idx + 1, remaining - nums[idx]) or                  helper(idx + 1, remaining)\n        memo[(idx, remaining)] = result\n        return result\n    return helper(0, target)\n# ─── Test Cases ───\n# Expected: True\n# Expected: False\n# Expected: True\n# Expected: True\n# Expected: True\n# Expected: False\n# Expected: True',
  E'class Solution {\n    public Object subsetSum(int[] nums, int target) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static boolean subsetSum(int[] nums, int target) {\n        // dp[s] = can we achieve sum s?\n        boolean[] dp = new boolean[target + 1];\n        dp[0] = true; // Sum 0 is always achievable (empty subset)\n\n        for (int num : nums) {\n            // Iterate backwards to avoid reuse\n            for (int s = target; s >= num; s--) {\n                dp[s] = dp[s] || dp[s - num];\n            }\n        }\n        return dp[target];\n    }\n}',
  E'/**\n * @param {any, any} nums, target\n * @return {any}\n */\nfunction subsetSum(nums, target) {\n    // Your code here\n}',
  E'function subsetSum(nums, target) {\n    // dp[s] = can we achieve sum s?\n    const dp = new Array(target + 1).fill(false);\n    dp[0] = true; // Sum 0 is always achievable (empty subset)\n\n    for (const num of nums) {\n        // Iterate backwards to avoid reuse\n        for (let s = target; s >= num; s--) {\n            dp[s] = dp[s] || dp[s - num];\n        }\n    }\n    return dp[target];\n}',
  ARRAY['dynamic-programming'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'stripe-l2'],
  'dynamic-programming',
  '[{"input":"subset_sum([1, 2, 3, 7], 6)","expected_output":"True"},{"input":"subset_sum([1, 3, 4, 8], 6)","expected_output":"False"},{"input":"subset_sum([2, 3, 7, 8, 10], 11)","expected_output":"True"}]'::jsonb,
  '[{"input":"subset_sum([1, 2, 3], 0)","expected_output":"True"},{"input":"subset_sum([5], 5)","expected_output":"True"},{"input":"subset_sum([5], 3)","expected_output":"False"},{"input":"subset_sum([3, 34, 4, 12, 5, 2], 9)","expected_output":"True (4 + 5 = 9)"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
