INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-count-of-subset-sum',
  'Count of Subset Sum',
  'hard',
  'Count of Subset Sum

<!-- voice:section_check concept="Counting variation of subset sum" -->

Problem Statement

Given a set of positive numbers and a target sum `S`, count the number of subsets whose sum is equal to `S`. (Each number can be used only once per subset.)

Examples

~~~
Input: nums = [1, 1, 2, 3], S = 4
Output: 3
Explanation: Three subsets sum to 4: [1, 3], [1, 3] (using different 1s), [1, 1, 2]
~~~

~~~
Input: nums = [1, 2, 7, 1, 5], S = 9
Output: 3
Explanation: [2, 7], [1, 2, 1, 5] (using first 1), [1, 2, 1, 5] (using second 1)
~~~

~~~
Input: nums = [2, 3, 5, 6, 8, 10], S = 10
Output: 3
Explanation: [2, 3, 5], [2, 8], [10]
~~~',
  '',
  '[{"input":"nums = [1, 1, 2, 3], S = 4","output":"3","explanation":"Three subsets sum to 4: [1, 3], [1, 3] (using different 1s), [1, 1, 2]"}]'::jsonb,
  'count_subsets',
  E'def count_subsets(nums, target):\n    """\n    Count number of subsets with given target sum.\n\n    Args:\n        nums: List of positive integers\n        target: int, target sum\n    Returns:\n        int: Number of subsets with target sum\n    Example:\n        >>> count_subsets([1, 1, 2, 3], 4)\n        3\n        >>> count_subsets([1, 2, 7, 1, 5], 9)\n        3\n        >>> count_subsets([2, 3, 5, 6, 8, 10], 10)\n        3\n    """\n    # TODO: Count ways to achieve target sum (not just check if possible)\n    # Hint: dp[s] = number of ways to achieve sum s\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: 3\n# With duplicates\n# Expected: 3\n# Multiple combinations\n# Expected: 3\n# Target is 0 (empty subset counts as 1 way)\n# Expected: 1\n# No valid subsets\n# Expected: 0\n# Single element matches\n# Expected: 1\n# All elements match\n# Expected: 1',
  E'def count_subsets(nums, target):\n    """\n    Count number of subsets with given target sum.\n\n    Time Complexity: O(n × target)\n    Space Complexity: O(target)\n    """\n    # dp[s] = number of ways to achieve sum s\n    dp = [0] * (target + 1)\n    dp[0] = 1  # One way to achieve sum 0: empty subset\n    for num in nums:\n        # Iterate backwards to avoid reuse\n        for s in range(target, num - 1, -1):\n            dp[s] += dp[s - num]\n    return dp[target]\n# Alternative: Recursive with memoization\ndef count_subsets_recursive(nums, target):\n    """\n    Top-down recursive solution.\n    """\n    memo = {}\n\n    def helper(idx, remaining):\n        if remaining == 0:\n            return 1\n        if idx >= len(nums) or remaining < 0:\n            return 0\n\n        if (idx, remaining) in memo:\n            return memo[(idx, remaining)]\n        # Include current + skip current\n        include = helper(idx + 1, remaining - nums[idx])\n        skip = helper(idx + 1, remaining)\n        result = include + skip\n        memo[(idx, remaining)] = result\n        return result\n    return helper(0, target)\n# 2D solution for clarity\ndef count_subsets_2d(nums, target):\n    """\n    2D DP solution showing complete state.\n    """\n    n = len(nums)\n    # dp[i][s] = number of ways to achieve sum s using first i elements\n    dp = [[0] * (target + 1) for _ in range(n + 1)]\n\n    # Base case: one way to achieve sum 0 (empty subset)\n    for i in range(n + 1):\n        dp[i][0] = 1\n    for i in range(1, n + 1):\n        for s in range(target + 1):\n            # Skip current element\n            dp[i][s] = dp[i-1][s]\n            # Include current element if possible\n            if s >= nums[i-1]:\n                dp[i][s] += dp[i-1][s - nums[i-1]]\n    return dp[n][target]\n# ─── Test Cases ───\n# Expected: 3\n# Expected: 3\n# Expected: 3\n# Expected: 1\n# Expected: 0\n# Expected: 1\n# Expected: 1',
  E'class Solution {\n    public Object countSubsets(int[] nums, int target) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // (No specific imports needed for this solution)\n\n    public static int countSubsets(int[] nums, int target) {\n        int[] dp = new int[target + 1];\n        dp[0] = 1; // One way to achieve sum 0: empty subset\n\n        for (int num : nums) {\n            // Iterate backwards to avoid reusing the same number in the current subset\n            for (int s = target; s >= num; s--) {\n                dp[s] += dp[s - num];\n            }\n        }\n        return dp[target];\n    }\n}',
  E'/**\n * @param {any, any} nums, target\n * @return {any}\n */\nfunction countSubsets(nums, target) {\n    // Your code here\n}',
  E'function countSubsets(nums, target) {\n    const dp = new Array(target + 1).fill(0);\n    dp[0] = 1; // One way to achieve sum 0: empty subset\n\n    for (const num of nums) {\n        // Iterate backwards to avoid reusing the same number in the current subset\n        for (let s = target; s >= num; s--) {\n            dp[s] += dp[s - num];\n        }\n    }\n    return dp[target];\n}',
  ARRAY['dynamic-programming'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'stripe-l2'],
