INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-n-queens',
  'N-Queens Problem',
  'hard',
  'N-Queens Problem

<!-- voice:section_check concept="Classic backtracking problem" -->

Problem Statement

Place ''n'' queens on an n×n chessboard such that no two queens threaten each other. Return all distinct solutions.

**Note:** Queens threaten each other if they share the same row, column, or diagonal.

Examples

~~~
Input: n = 4
Output: [
  [".Q..","...Q","Q...","..Q."],
  ["..Q.","Q...","...Q",".Q.."]
]
Explanation: There are 2 distinct solutions for 4 queens.
~~~

~~~
Input: n = 1
Output: [["Q"]]
~~~',
  '',
  '[{"input":"n = 4","output":"[","explanation":"There are 2 distinct solutions for 4 queens."}]'::jsonb,
  'solve_n_queens',
  E'def solve_n_queens(n):\n    """\n    Return all distinct solutions to the N-Queens problem.\n\n    Args:\n        n: int, board size and number of queens\n    Returns:\n        List of solutions, each solution is a list of strings representing the board\n    Example:\n        >>> solve_n_queens(4)\n        [[''.Q..'', ''...Q'', ''Q...'', ''..Q.''], [''..Q.'', ''Q...'', ''...Q'', ''.Q..'']]\n    """\n    # TODO: Use backtracking to place queens one row at a time\n    # Hint: Check columns and diagonals for conflicts\n    pass\n# ─── Test Cases ───\n# n = 1\n# Expected: [[''Q'']]\n# n = 4\n# Expected: 2 solutions (as shown above)\n# n = 2 (no solution)\n# Expected: []\n# n = 3 (no solution)\n# Expected: []\n# Check count for n = 5\n# Expected: 10',
  E'def solve_n_queens(n):\n    """\n    Return all distinct solutions to the N-Queens problem.\n\n    Time Complexity: O(n!) — n choices for first row, n-1 for second, etc.\n    Space Complexity: O(n) for recursion stack\n    """\n    def is_safe(row, col):\n        # Check column\n        for r in range(row):\n            if board[r] == col:\n                return False\n\n        # Check diagonal (r + c is constant)\n        for r in range(row):\n            if board[r] + r == col + row:\n                return False\n        # Check anti-diagonal (r - c is constant)\n        for r in range(row):\n            if board[r] - r == col - row:\n                return False\n        return True\n    def backtrack(row):\n        if row == n:\n            # All queens placed, create board representation\n            solution = []\n            for c in board:\n                row_str = [''.''] * n\n                row_str[c] = ''Q''\n                solution.append(''''.join(row_str))\n            results.append(solution)\n            return\n\n        for col in range(n):\n            if is_safe(row, col):\n                board[row] = col\n                backtrack(row + 1)\n                board[row] = -1  # Backtrack\n    board = [-1] * n  # board[i] = column of queen in row i\n    results = []\n    backtrack(0)\n    return results\n# Alternative using sets for O(1) conflict checking\ndef solve_n_queens_optimized(n):\n    """\n    Optimized version using sets for O(1) safety checks.\n    """\n    def backtrack(row):\n        if row == n:\n            solution = []\n            for c in board:\n                row_str = [''.''] * n\n                row_str[c] = ''Q''\n                solution.append(''''.join(row_str))\n            results.append(solution)\n            return\n\n        for col in range(n):\n            # Check using sets: diagonal = row + col, anti-diagonal = row - col\n            if col not in cols and (row + col) not in diagonals and (row - col) not in anti_diagonals:\n                cols.add(col)\n                diagonals.add(row + col)\n                anti_diagonals.add(row - col)\n                board.append(col)\n                backtrack(row + 1)\n                # Backtrack\n                board.pop()\n                cols.remove(col)\n                diagonals.remove(row + col)\n                anti_diagonals.remove(row - col)\n    cols = set()\n    diagonals = set()\n    anti_diagonals = set()\n    board = []\n    results = []\n    backtrack(0)\n    return results\n# ─── Test Cases ───\n# Expected: [[''Q'']]\n# Expected: 2 solutions\n# Expected: []\n# Expected: []\n# Expected: 10',
  E'class Solution {\n    public Object solveNQueens(int n) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.List;\n\n    public static List<List<String>> solveNQueens(int n) {\n        List<List<String>> results = new ArrayList<>();\n        int[] board = new int[n]; // board[row] stores the column of the queen in that row\n\n        backtrack(0, n, board, results);\n        return results;\n    }\n\n    private static void backtrack(int row, int n, int[] board, List<List<String>> results) {\n        if (row == n) {\n            // All queens placed, create board representation\n            List<String> solution = new ArrayList<>();\n            for (int colOfQueen : board) {\n                StringBuilder rowStr = new StringBuilder();\n                for (int c = 0; c < n; c++) {\n                    if (c == colOfQueen) {\n                        rowStr.append(\'Q\');\n                    } else {\n                        rowStr.append(\'.\');\n                    }\n                }\n                solution.add(rowStr.toString());\n            }\n            results.add(solution);\n            return;\n        }\n\n        for (int col = 0; col < n; col++) {\n            if (isSafe(row, col, board, n)) {\n                board[row] = col; // Place queen\n                backtrack(row + 1, n, board, results);\n                // No need to "unplace" queen (board[row] = -1) as it will be overwritten\n                // in the next iteration or by the next recursive call.\n                // The Python solution also doesn\'t explicitly unplace, it just overwrites.\n            }\n        }\n    }\n\n    private static boolean isSafe(int row, int col, int[] board, int n) {\n        for (int r = 0; r < row; r++) {\n            // Check column\n            if (board[r] == col) {\n                return false;\n            }\n            // Check diagonal (r + c is constant)\n            if (board[r] + r == col + row) {\n                return false;\n            }\n            // Check anti-diagonal (r - c is constant)\n            if (board[r] - r == col - row) {\n                return false;\n            }\n        }\n        return true;\n    }\n}''.''] * n\n    //                 row_str[c] = ''Q''\n    //                 solution.append(''''.join(row_str))\n    //             results.append(solution)\n    //             return\n    //         \n    //         for col in range(n):\n    //             if is_safe(row, col):\n    //                 board[row] = col\n    //                 backtrack(row + 1)\n    //                 board[row] = -1  # Backtrack\n    //     \n    //     board = [-1] * n  # board[i] = column of queen in row i\n    //     results = []\n    //     backtrack(0)\n    //     return results\n    // \n    // \n    // # Alternative using sets for O(1) conflict checking\n    // def solve_n_queens_optimized(n):\n    //     """\n    //     Optimized version using sets for O(1) safety checks.\n    //     """\n    //     def backtrack(row):\n    //         if row == n:\n    //             solution = []\n    //             for c in board:\n    //                 row_str = [''.''] * n\n    //                 row_str[c] = ''Q''\n    //                 solution.append(''''.join(row_str))\n    //             results.append(solution)\n    //             return\n    //         \n    //         for col in range(n):\n    //             # Check using sets: diagonal = row + col, anti-diagonal = row - col\n    //             if col not in cols and (row + col) not in diagonals and (row - col) not in anti_diagonals:\n    //                 cols.add(col)\n    //                 diagonals.add(row + col)\n    //                 anti_diagonals.add(row - col)\n    //                 board.append(col)\n    //                 \n    //                 backtrack(row + 1)\n    //                 \n    //                 # Backtrack\n    //                 board.pop()\n    //                 cols.remove(col)\n    //                 diagonals.remove(row + col)\n    //                 anti_diagonals.remove(row - col)\n    //     \n    //     cols = set()\n    //     diagonals = set()\n    //     anti_diagonals = set()\n    //     board = []\n    //     results = []\n    //     backtrack(0)\n    //     return results\n    // \n    // \n    // # ─── Test Cases ───\n    // # Expected: [[''Q'']]\n    // \n    // # Expected: 2 solutions\n    // \n    // # Expected: []\n    // \n    // # Expected: []\n    // \n    // # Expected: 10\n    // \n}',
  E'/**\n * @param {any} n\n * @return {any}\n */\nfunction solveNQueens(n) {\n    // Your code here\n}',
  E'function solveNQueens(n) {\n    const results = [];\n    const board = new Array(n); // board[row] stores the column of the queen in that row\n\n    function isSafe(row, col) {\n        for (let r = 0; r < row; r++) {\n            // Check column\n            if (board[r] === col) {\n                return false;\n            }\n            // Check diagonal (r + c is constant)\n            if (board[r] + r === col + row) {\n                return false;\n            }\n            // Check anti-diagonal (r - c is constant)\n            if (board[r] - r === col - row) {\n                return false;\n            }\n        }\n        return true;\n    }\n\n    function backtrack(row) {\n        if (row === n) {\n            // All queens placed, create board representation\n            const solution = [];\n            for (const colOfQueen of board) {\n                let rowStr = \'\';\n                for (let c = 0; c < n; c++) {\n                    rowStr += (c === colOfQueen ? \'Q\' : \'.\');\n                }\n                solution.push(rowStr);\n            }\n            results.push(solution);\n            return;\n        }\n\n        for (let col = 0; col < n; col++) {\n            if (isSafe(row, col)) {\n                board[row] = col; // Place queen\n                backtrack(row + 1);\n                // No need to "unplace" queen as it will be overwritten\n                // in the next iteration or by the next recursive call.\n            }\n        }\n    }\n\n    backtrack(0);\n    return results;\n}',
  ARRAY['backtracking'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'airbnb-swe'],
  'backtracking',
  '[{"input":"solve_n_queens(1)","expected_output":"[[''Q'']]"},{"input":"solve_n_queens(4)","expected_output":"2 solutions (as shown above)"},{"input":"solve_n_queens(2)","expected_output":"[]"}]'::jsonb,
  '[{"input":"solve_n_queens(3)","expected_output":"[]"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
