INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-combination-sum',
  'Combination Sum',
  'hard',
  'Combination Sum

<!-- voice:section_check concept="Backtracking with target sum" -->

Problem Statement

Given an array of distinct integers `candidates` and a target integer `target`, return a list of all unique combinations of `candidates` where the chosen numbers sum to `target`. You may use the same number unlimited times.

Examples

~~~
Input: candidates = [2,3,6,7], target = 7
Output: [[2,2,3],[7]]
Explanation: 2+2+3=7 and 7=7
~~~

~~~
Input: candidates = [2,3,5], target = 8
Output: [[2,2,2,2],[2,3,3],[3,5]]
~~~',
  '',
  '[{"input":"candidates = [2,3,6,7], target = 7","output":"[[2,2,3],[7]]","explanation":"2+2+3=7 and 7=7"}]'::jsonb,
  'combination_sum',
  E'def combination_sum(candidates, target):\n    """\n    Return all unique combinations where numbers sum to target.\n    Each number can be used unlimited times.\n\n    Args:\n        candidates: List of distinct integers\n        target: int, target sum\n    Returns:\n        List of lists, each list is a valid combination\n    Example:\n        >>> combination_sum([2,3,6,7], 7)\n        [[2, 2, 3], [7]]\n        >>> combination_sum([2,3,5], 8)\n        [[2, 2, 2, 2], [2, 3, 3], [3, 5]]\n    """\n    # TODO: Use backtracking to find all combinations\n    # Hint: Sort first, start from current index to allow reuse\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: [[2, 2, 3], [7]]\n# Multiple combinations\n# Expected: [[2, 2, 2, 2], [2, 3, 3], [3, 5]]\n# Single element solution\n# Expected: []\n# Multiple same elements\n# Expected: [[2, 2, 2], [3, 3]]\n# Large target with small candidate\n# Expected: [[1, 1, 1]]\n# No solution\n# Expected: []',
  E'def combination_sum(candidates, target):\n    """\n    Return all unique combinations where numbers sum to target.\n\n    Time Complexity: O(k^(target/min)) where k is number of candidates\n    Space Complexity: O(target/min) for recursion stack\n    """\n    def backtrack(start, remaining, current):\n        if remaining == 0:\n            results.append(list(current))\n            return\n\n        if remaining < 0:\n            return\n        for i in range(start, len(candidates)):\n            # Include candidates[i] and stay at i (can reuse)\n            current.append(candidates[i])\n            backtrack(i, remaining - candidates[i], current)\n            current.pop()  # Backtrack\n    candidates.sort()  # Sort to handle duplicates properly\n    results = []\n    backtrack(0, target, [])\n    return results\n# Alternative: Pre-check to avoid unnecessary recursion\ndef combination_sum_pruned(candidates, target):\n    """\n    Pruned version that stops early if candidate > remaining.\n    """\n    def backtrack(start, remaining, current):\n        if remaining == 0:\n            results.append(list(current))\n            return\n\n        for i in range(start, len(candidates)):\n            # Pruning: stop if candidate exceeds remaining\n            if candidates[i] > remaining:\n                break\n            current.append(candidates[i])\n            backtrack(i, remaining - candidates[i], current)\n            current.pop()\n    candidates.sort()\n    results = []\n    backtrack(0, target, [])\n    return results\n# ─── Test Cases ───\n# Expected: [[2, 2, 3], [7]]\n# Expected: [[2, 2, 2, 2], [2, 3, 3], [3, 5]]\n# Expected: []\n# Expected: [[2, 2, 2], [3, 3]]\n# Expected: [[1, 1, 1]]\n# Expected: []',
  E'class Solution {\n    public Object combinationSum(Object candidates, int target) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.ArrayList;\n    // import java.util.Arrays;\n    // import java.util.List;\n\n    public static List<List<Integer>> combinationSum(int[] candidates, int target) {\n        List<List<Integer>> results = new ArrayList<>();\n        Arrays.sort(candidates); // Sort to handle duplicates properly (though problem states distinct integers, sorting helps with pruning)\n        backtrack(0, target, new ArrayList<>(), candidates, results);\n        return results;\n    }\n\n    private static void backtrack(int start, int remaining, List<Integer> current, int[] candidates, List<List<Integer>> results) {\n        if (remaining == 0) {\n            results.add(new ArrayList<>(current));\n            return;\n        }\n\n        if (remaining < 0) {\n            return;\n        }\n\n        for (int i = start; i < candidates.length; i++) {\n            // Pruning: if current candidate is already greater than remaining, no need to check further\n            // (only works because candidates are sorted)\n            if (candidates[i] > remaining) {\n                break;\n            }\n            \n            // Include candidates[i] and stay at i (can reuse)\n            current.add(candidates[i]);\n            backtrack(i, remaining - candidates[i], current, candidates, results);\n            current.remove(current.size() - 1); // Backtrack\n        }\n    }\n}',
  E'/**\n * @param {any, any} candidates, target\n * @return {any}\n */\nfunction combinationSum(candidates, target) {\n    // Your code here\n}',
  E'function combinationSum(candidates, target) {\n    const results = [];\n    candidates.sort((a, b) => a - b); // Sort to handle duplicates properly (though problem states distinct integers, sorting helps with pruning)\n\n    function backtrack(start, remaining, current) {\n        if (remaining === 0) {\n            results.push([...current]); // Add a copy of the current combination\n            return;\n        }\n\n        if (remaining < 0) {\n            return;\n        }\n\n        for (let i = start; i < candidates.length; i++) {\n            // Pruning: if current candidate is already greater than remaining, no need to check further\n            // (only works because candidates are sorted)\n            if (candidates[i] > remaining) {\n                break;\n            }\n\n            // Include candidates[i] and stay at i (can reuse)\n            current.push(candidates[i]);\n            backtrack(i, remaining - candidates[i], current);\n            current.pop(); // Backtrack\n        }\n    }\n\n    backtrack(0, target, []);\n    return results;\n}',
  ARRAY['backtracking'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'airbnb-swe'],
  'backtracking',
  '[{"input":"combination_sum([2, 3, 6, 7], 7)","expected_output":"[[2, 2, 3], [7]]"},{"input":"combination_sum([2, 3, 5], 8)","expected_output":"[[2, 2, 2, 2], [2, 3, 3], [3, 5]]"},{"input":"combination_sum([2], 1)","expected_output":"[]"}]'::jsonb,
  '[{"input":"combination_sum([2, 3], 6)","expected_output":"[[2, 2, 2], [3, 3]]"},{"input":"combination_sum([1], 3)","expected_output":"[[1, 1, 1]]"},{"input":"combination_sum([4, 5], 3)","expected_output":"[]"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
