INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-palindrome-partitioning',
  'Palindrome Partitioning',
  'hard',
  'Palindrome Partitioning

<!-- voice:section_check concept="Backtracking with string partitioning" -->

Problem Statement

Given a string `s`, partition `s` such that every substring of the partition is a palindrome. Return all possible palindrome partitioning of `s`.

Examples

~~~
Input: s = "aab"
Output: [["a","a","b"],["aa","b"]]
~~~

~~~
Input: s = "a"
Output: [["a"]]
~~~

~~~
Input: s = "racecar"
Output: Multiple solutions including ["r","a","c","e","c","a","r"], ["racecar"], etc.
~~~',
  '',
  '[{"input":"s = \"aab\"","output":"[[\"a\",\"a\",\"b\"],[\"aa\",\"b\"]]"}]'::jsonb,
  'partition_palindromes',
  E'def partition_palindromes(s):\n    """\n    Return all possible palindrome partitioning of string s.\n\n    Args:\n        s: String to partition\n    Returns:\n        List of lists, each inner list is a valid palindrome partition\n    Example:\n        >>> partition_palindromes("aab")\n        [[''a'', ''a'', ''b''], [''aa'', ''b'']]\n        >>> partition_palindromes("a")\n        [[''a'']]\n    """\n    # TODO: Use backtracking to try all partitions\n    # Hint: Check if substring is palindrome, if yes, recurse on rest\n    pass\n# ─── Test Cases ───\n# Standard case\n# Expected: [[''a'', ''a'', ''b''], [''aa'', ''b'']]\n# Single character\n# Expected: [[''a'']]\n# All same characters\n# Expected: [[''a'',''a'',''a''], [''a'',''aa''], [''aa'',''a''], [''aaa'']]\n# No palindrome longer than 1\n# Expected: [[''a'', ''b'', ''c'']]\n# Complex palindrome\n# Should include [''racecar''] and [''r'',''a'',''c'',''e'',''c'',''a'',''r'']\n# Empty string\n# Expected: [[]]',
  E'def partition_palindromes(s):\n    """\n    Return all possible palindrome partitioning of string s.\n\n    Time Complexity: O(n × 2^n)\n    Space Complexity: O(n) for recursion stack\n    """\n    def is_palindrome(start, end):\n        """Check if s[start:end+1] is a palindrome."""\n        while start < end:\n            if s[start] != s[end]:\n                return False\n            start += 1\n            end -= 1\n        return True\n\n    def backtrack(start, current):\n        if start >= len(s):\n            results.append(list(current))\n            return\n\n        for end in range(start, len(s)):\n            if is_palindrome(start, end):\n                current.append(s[start:end+1])\n                backtrack(end + 1, current)\n                current.pop()  # Backtrack\n    results = []\n    backtrack(0, [])\n    return results\n# Optimized with memoization\ndef partition_palindromes_dp(s):\n    """\n    Optimized using DP to precompute palindrome table.\n    """\n    n = len(s)\n\n    # dp[i][j] = True if s[i:j+1] is palindrome\n    dp = [[False] * n for _ in range(n)]\n    # Single characters are palindromes\n    for i in range(n):\n        dp[i][i] = True\n    # Fill DP table\n    for length in range(2, n + 1):\n        for i in range(n - length + 1):\n            j = i + length - 1\n            if length == 2:\n                dp[i][j] = (s[i] == s[j])\n            else:\n                dp[i][j] = (s[i] == s[j] and dp[i+1][j-1])\n    def backtrack(start, current):\n        if start >= n:\n            results.append(list(current))\n            return\n\n        for end in range(start, n):\n            if dp[start][end]:\n                current.append(s[start:end+1])\n                backtrack(end + 1, current)\n                current.pop()\n    results = []\n    backtrack(0, [])\n    return results\n# ─── Test Cases ───\n# Expected: [[''a'', ''a'', ''b''], [''aa'', ''b'']]\n# Expected: [[''a'']]\n# Expected: 4 solutions\n# Expected: [[''a'', ''b'', ''c'']]\n# Includes [''racecar''] and single character partition\n# Expected: [[]]',
  E'class Solution {\n    public Object partitionPalindromes(String s) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayList;\nimport java.util.List;\n\nclass Solution {\n    public static List<List<String>> partitionPalindromes(String s) {\n        int n = s.length();\n\n        // dp[i][j] = True if s[i:j+1] is palindrome\n        boolean[][] dp = new boolean[n][n];\n        // Single characters are palindromes\n        for (int i = 0; i < n; i++) {\n            dp[i][i] = true;\n        }\n        // Fill DP table\n        for (int length = 2; length <= n; length++) {\n            for (int i = 0; i <= n - length; i++) {\n                int j = i + length - 1;\n                if (length == 2) {\n                    dp[i][j] = (s.charAt(i) == s.charAt(j));\n                } else {\n                    dp[i][j] = (s.charAt(i) == s.charAt(j) && dp[i + 1][j - 1]);\n                }\n            }\n        }\n\n        List<List<String>> results = new ArrayList<>();\n        backtrack(s, n, dp, 0, new ArrayList<>(), results);\n        return results;\n    }\n\n    private static void backtrack(String s, int n, boolean[][] dp, int start, List<String> current, List<List<String>> results) {\n        if (start >= n) {\n            results.add(new ArrayList<>(current));\n            return;\n        }\n\n        for (int end = start; end < n; end++) {\n            if (dp[start][end]) {\n                current.add(s.substring(start, end + 1));\n                backtrack(s, n, dp, end + 1, current, results);\n                current.remove(current.size() - 1); // Backtrack\n            }\n        }\n    }\n}''a'', ''a'', ''b''], [''aa'', ''b'']]\n    // \n    // # Expected: [[''a'']]\n    // \n    // # Expected: 4 solutions\n    // \n    // # Expected: [[''a'', ''b'', ''c'']]\n    // \n    // # Includes [''racecar''] and single character partition\n    // \n    // # Expected: [[]]\n    // \n}',
  E'/**\n * @param {any} s\n * @return {any}\n */\nfunction partitionPalindromes(s) {\n    // Your code here\n}',
  E'function partitionPalindromes(s) {\n    const n = s.length;\n\n    // dp[i][j] = True if s[i:j+1] is palindrome\n    const dp = Array(n).fill(0).map(() => Array(n).fill(false));\n    // Single characters are palindromes\n    for (let i = 0; i < n; i++) {\n        dp[i][i] = true;\n    }\n    // Fill DP table\n    for (let length = 2; length <= n; length++) {\n        for (let i = 0; i <= n - length; i++) {\n            const j = i + length - 1;\n            if (length === 2) {\n                dp[i][j] = (s[i] === s[j]);\n            } else {\n                dp[i][j] = (s[i] === s[j] && dp[i + 1][j - 1]);\n            }\n        }\n    }\n\n    const results = [];\n\n    function backtrack(start, current) {\n        if (start >= n) {\n            results.push([...current]);\n            return;\n        }\n\n        for (let end = start; end < n; end++) {\n            if (dp[start][end]) {\n                current.push(s.substring(start, end + 1));\n                backtrack(end + 1, current);\n                current.pop(); // Backtrack\n            }\n        }\n    }\n\n    backtrack(0, []);\n    return results;\n}',
  ARRAY['backtracking'],
