INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-word-search',
  'Word Search (Grid)',
  'hard',
  'Word Search

<!-- voice:section_check concept="Backtracking on 2D grid" -->

Problem Statement

Given an m×n grid of characters `board` and a string `word`, return `true` if `word` exists in the grid. The word can be constructed from letters of sequentially adjacent cells (horizontally or vertically neighboring). The same letter cell may not be used more than once.

Examples

~~~
Input: board = [
  ["A","B","C","E"],
  ["S","F","C","S"],
  ["A","D","E","E"]
], word = "ABCCED"
Output: true
~~~

~~~
Input: board = [
  ["A","B","C","E"],
  ["S","F","C","S"],
  ["A","D","E","E"]
], word = "SEE"
Output: true
~~~

~~~
Input: word = "ABCB"
Output: false (can''t reuse ''B'')
~~~',
  '',
  '[{"input":"board = [","output":"true"}]'::jsonb,
  'exist',
  E'def exist(board, word):\n    """\n    Return true if word exists in the grid.\n\n    Args:\n        board: 2D list of characters\n        word: String to search for\n    Returns:\n        bool: True if word exists in grid\n    Example:\n        >>> board = [["A","B","C","E"],["S","F","C","S"],["A","D","E","E"]]\n        >>> exist(board, "ABCCED")\n        True\n        >>> exist(board, "SEE")\n        True\n        >>> exist(board, "ABCB")\n        False\n    """\n    # TODO: Use backtracking to search for word in grid\n    # Hint: Mark visited cells by temporarily changing their value\n    pass\n# ─── Test Cases ───\nboard = [\n    ["A", "B", "C", "E"],\n    ["S", "F", "C", "S"],\n    ["A", "D", "E", "E"]\n]\n# Word exists\n# Expected: True\n# Word exists (different path)\n# Expected: True\n# Word doesn''t exist (reuse not allowed)\n# Expected: False\n# Single cell match\n# Expected: True\n# Single cell no match\n# Expected: False\n# Empty word\n# Expected: True\n# Longer word than board\n# Expected: False',
  E'def exist(board, word):\n    """\n    Return true if word exists in the grid.\n\n    Time Complexity: O(m × n × 4^L) where L is word length\n    Space Complexity: O(L) for recursion stack\n    """\n    if not board or not board[0]:\n        return False\n    if not word:\n        return True\n    rows, cols = len(board), len(board[0])\n    def backtrack(r, c, index):\n        # Base case: all characters matched\n        if index == len(word):\n            return True\n\n        # Check bounds and character match\n        if r < 0 or r >= rows or c < 0 or c >= cols:\n            return False\n        if board[r][c] != word[index]:\n            return False\n        # Mark as visited\n        temp = board[r][c]\n        board[r][c] = ''#''  # Use special character\n        # Try all 4 directions\n        found = (backtrack(r + 1, c, index + 1) or\n                 backtrack(r - 1, c, index + 1) or\n                 backtrack(r, c + 1, index + 1) or\n                 backtrack(r, c - 1, index + 1))\n        # Backtrack: restore cell\n        board[r][c] = temp\n        return found\n    # Try starting from each cell that matches first character\n    for r in range(rows):\n        for c in range(cols):\n            if board[r][c] == word[0]:\n                if backtrack(r, c, 0):\n                    return True\n    return False\n# Alternative with visited set\ndef exist_visited_set(board, word):\n    """\n    Alternative using explicit visited set.\n    """\n    if not board or not board[0]:\n        return False\n\n    rows, cols = len(board), len(board[0])\n    visited = set()\n    def backtrack(r, c, index):\n        if index == len(word):\n            return True\n        if (r, c) in visited:\n            return False\n        if r < 0 or r >= rows or c < 0 or c >= cols:\n            return False\n        if board[r][c] != word[index]:\n            return False\n\n        visited.add((r, c))\n        found = (backtrack(r + 1, c, index + 1) or\n                 backtrack(r - 1, c, index + 1) or\n                 backtrack(r, c + 1, index + 1) or\n                 backtrack(r, c - 1, index + 1))\n        visited.remove((r, c))\n        return found\n    for r in range(rows):\n        for c in range(cols):\n            if board[r][c] == word[0]:\n                if backtrack(r, c, 0):\n                    return True\n    return False\n# ─── Test Cases ───\nboard = [\n    ["A", "B", "C", "E"],\n    ["S", "F", "C", "S"],\n    ["A", "D", "E", "E"]\n]\n# Expected: True\n# Expected: True\n# Expected: False\n# Expected: True\n# Expected: False\n# Expected: True\n# Expected: False',
  E'class Solution {\n    public Object exist(Object board, String word) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static boolean exist(char[][] board, String word) {\n        if (board == null || board.length == 0 || board[0].length == 0) {\n            return false;\n        }\n        if (word == null || word.isEmpty()) {\n            return true;\n        }\n\n        int rows = board.length;\n        int cols = board[0].length;\n\n        for (int r = 0; r < rows; r++) {\n            for (int c = 0; c < cols; c++) {\n                if (board[r][c] == word.charAt(0)) {\n                    if (backtrack(board, word, r, c, 0, rows, cols)) {\n                        return true;\n                    }\n                }\n            }\n        }\n        return false;\n    }\n\n    private static boolean backtrack(char[][] board, String word, int r, int c, int index, int rows, int cols) {\n        // Base case: all characters matched\n        if (index == word.length()) {\n            return true;\n        }\n\n        // Check bounds and character match\n        if (r < 0 || r >= rows || c < 0 || c >= cols || board[r][c] != word.charAt(index)) {\n            return false;\n        }\n\n        // Mark as visited\n        char temp = board[r][c];\n        board[r][c] = \'#\'; // Use a special character to mark as visited\n\n        // Explore 4 directions\n        int[] dr = {-1, 1, 0, 0};\n        int[] dc = {0, 0, -1, 1};\n\n        for (int i = 0; i < 4; i++) {\n            if (backtrack(board, word, r + dr[i], c + dc[i], index + 1, rows, cols)) {\n                board[r][c] = temp; // Unmark before returning\n                return true;\n            }\n        }\n\n        board[r][c] = temp; // Unmark before returning\n        return false;\n    }\n}''#''  # Use special character\n    //         \n    //         # Try all 4 directions\n    //         found = (backtrack(r + 1, c, index + 1) or\n    //                  backtrack(r - 1, c, index + 1) or\n    //                  backtrack(r, c + 1, index + 1) or\n    //                  backtrack(r, c - 1, index + 1))\n    //         \n    //         # Backtrack: restore cell\n    //         board[r][c] = temp\n    //         \n    //         return found\n    //     \n    //     # Try starting from each cell that matches first character\n    //     for r in range(rows):\n    //         for c in range(cols):\n    //             if board[r][c] == word[0]:\n    //                 if backtrack(r, c, 0):\n    //                     return True\n    //     \n    //     return False\n    // \n    // \n    // # Alternative with visited set\n    // def exist_visited_set(board, word):\n    //     """\n    //     Alternative using explicit visited set.\n    //     """\n    //     if not board or not board[0]:\n    //         return False\n    //     \n    //     rows, cols = len(board), len(board[0])\n    //     visited = set()\n    //     \n    //     def backtrack(r, c, index):\n    //         if index == len(word):\n    //             return True\n    //         if (r, c) in visited:\n    //             return False\n    //         if r < 0 or r >= rows or c < 0 or c >= cols:\n    //             return False\n    //         if board[r][c] != word[index]:\n    //             return False\n    //         \n    //         visited.add((r, c))\n    //         \n    //         found = (backtrack(r + 1, c, index + 1) or\n    //                  backtrack(r - 1, c, index + 1) or\n    //                  backtrack(r, c + 1, index + 1) or\n    //                  backtrack(r, c - 1, index + 1))\n    //         \n    //         visited.remove((r, c))\n    //         return found\n    //     \n    //     for r in range(rows):\n    //         for c in range(cols):\n    //             if board[r][c] == word[0]:\n    //                 if backtrack(r, c, 0):\n    //                     return True\n    //     \n    //     return False\n    // \n    // \n    // # ─── Test Cases ───\n    // board = [\n    //     ["A", "B", "C", "E"],\n    //     ["S", "F", "C", "S"],\n    //     ["A", "D", "E", "E"]\n    // ]\n    // \n    // # Expected: True\n    // \n    // # Expected: True\n    // \n    // # Expected: False\n    // \n    // # Expected: True\n    // \n    // # Expected: False\n    // \n    // # Expected: True\n    // \n    // # Expected: False\n    // \n}',
  E'/**\n * @param {any, any} board, word\n * @return {any}\n */\nfunction exist(board, word) {\n    // Your code here\n}',
  E'function exist(board, word) {\n    if (!board || board.length === 0 || board[0].length === 0) {\n        return false;\n    }\n    if (!word) {\n        return true;\n    }\n\n    const rows = board.length;\n    const cols = board[0].length;\n\n    function backtrack(r, c, index) {\n        // Base case: all characters matched\n        if (index === word.length) {\n            return true;\n        }\n\n        // Check bounds and character match\n        if (r < 0 || r >= rows || c < 0 || c >= cols || board[r][c] !== word[index]) {\n            return false;\n        }\n\n        // Mark as visited\n        const temp = board[r][c];\n        board[r][c] = \'#\'; // Use a special character to mark as visited\n\n        // Explore 4 directions\n        const dr = [-1, 1, 0, 0];\n        const dc = [0, 0, -1, 1];\n\n        for (let i = 0; i < 4; i++) {\n            if (backtrack(r + dr[i], c + dc[i], index + 1)) {\n                board[r][c] = temp; // Unmark before returning\n                return true;\n            }\n        }\n\n        board[r][c] = temp; // Unmark before returning\n        return false;\n    }\n\n    for (let r = 0; r < rows; r++) {\n        for (let c = 0; c < cols; c++) {\n            if (board[r][c] === word[0]) {\n                if (backtrack(r, c, 0)) {\n                    return true;\n                }\n            }\n        }\n    }\n    return false;\n}',
  ARRAY['backtracking'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'airbnb-swe'],
  'backtracking',
  '[{"input":"exist(board, \"ABCCED\")","expected_output":"True"},{"input":"exist(board, \"SEE\")","expected_output":"True"},{"input":"exist(board, \"ABCB\")","expected_output":"False"}]'::jsonb,
  '[{"input":"exist([[\"A\"]], \"A\")","expected_output":"True"},{"input":"exist([[\"A\"]], \"B\")","expected_output":"False"},{"input":"exist(board, \"\")","expected_output":"True"},{"input":"exist([[\"A\"]], \"AB\")","expected_output":"False"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
