INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-word-search-ii',
  'Word Search II',
  'hard',
  'Word Search II

<!-- voice:section_check concept="Trie + Backtracking combination" -->

Problem Statement

Given an m×n `board` of characters and a list of strings `words`, return all words on the board.

Each word must be constructed from letters of sequentially adjacent cells (horizontally or vertically neighboring). The same letter cell may not be used more than once in a word.

Examples

~~~
Input: 
board = [
  ["o","a","a","n"],
  ["e","t","a","e"],
  ["i","h","k","r"],
  ["i","f","l","v"]
]
words = ["oath","pea","eat","rain"]

Output: ["eat","oath"]
~~~',
  '',
  '[{"input":"board = [","output":"[\"eat\",\"oath\"]"}]'::jsonb,
  'find_words',
  E'class TrieNode:\n    def __init__(self):\n        self.children = {}\n        self.word = None  # Store complete word at end node\n\ndef find_words(board, words):\n    """\n    Find all words from the list that exist on the board.\n\n    Args:\n        board: 2D list of characters\n        words: List of strings to search for\n    Returns:\n        List of found words\n    Example:\n        >>> board = [\n        ...     ["o","a","a","n"],\n        ...     ["e","t","a","e"],\n        ...     ["i","h","k","r"],\n        ...     ["i","f","l","v"]\n        ... ]\n        >>> words = ["oath","pea","eat","rain"]\n        >>> find_words(board, words)\n        ["eat", "oath"]  (order may vary)\n    """\n    # TODO: Build Trie from words, then backtrack on board\n    # Hint: Store complete word in Trie node to avoid string building\n    pass\n# ─── Test Cases ───\nboard = [\n    ["o", "a", "a", "n"],\n    ["e", "t", "a", "e"],\n    ["i", "h", "k", "r"],\n    ["i", "f", "l", "v"]\n]\nwords = ["oath", "pea", "eat", "rain"]\n# Expected: ["eat", "oath"] (order may vary)\n# Single word\nboard2 = [["a"]]\nwords2 = ["a"]\n# Expected: ["a"]\n# No matches\nboard3 = [["a", "b"], ["c", "d"]]\nwords3 = ["xyz"]\n# Expected: []\n# Words with common prefix\nboard4 = [["a", "b"], ["c", "d"]]\nwords4 = ["abc", "abd"]\n# Expected: []',
  E'class TrieNode:\n    def __init__(self):\n        self.children = {}\n        self.word = None  # Store complete word at end node\n\ndef find_words(board, words):\n    """\n    Find all words from the list that exist on the board.\n\n    Time Complexity: O(m × n × 4^L) but pruned by Trie\n    Space Complexity: O(total characters in words)\n    """\n    # Build Trie\n    root = TrieNode()\n    for word in words:\n        node = root\n        for char in word:\n            if char not in node.children:\n                node.children[char] = TrieNode()\n            node = node.children[char]\n        node.word = word  # Store word at end\n    rows, cols = len(board), len(board[0])\n    result = []\n    def backtrack(r, c, parent):\n        char = board[r][c]\n        node = parent.children[char]\n\n        # Check if we found a word\n        if node.word is not None:\n            result.append(node.word)\n            node.word = None  # Avoid duplicates\n        # Mark as visited\n        board[r][c] = ''#''\n        # Explore neighbors\n        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]\n        for dr, dc in directions:\n            nr, nc = r + dr, c + dc\n            if 0 <= nr < rows and 0 <= nc < cols:\n                if board[nr][nc] in node.children:\n                    backtrack(nr, nc, node)\n        # Restore\n        board[r][c] = char\n        # Optimization: Remove leaf nodes\n        if not node.children:\n            parent.children.pop(char)\n    # Start from each cell\n    for r in range(rows):\n        for c in range(cols):\n            if board[r][c] in root.children:\n                backtrack(r, c, root)\n    return result\n# ─── Test Cases ───\nboard = [\n    ["o", "a", "a", "n"],\n    ["e", "t", "a", "e"],\n    ["i", "h", "k", "r"],\n    ["i", "f", "l", "v"]\n]\nwords = ["oath", "pea", "eat", "rain"]\nresult = find_words(board, words)\n# Expected: ["eat", "oath"]\nboard2 = [["a"]]\nwords2 = ["a"]\n# Expected: ["a"]\nboard3 = [["a", "b"], ["c", "d"]]\nwords3 = ["xyz"]\n# Expected: []',
  E'class Solution {\n    public Object findWords() {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\n\nclass Solution {\n    static class TrieNode {\n        Map<Character, TrieNode> children;\n        String word; // Store complete word at end node\n\n        public TrieNode() {\n            children = new HashMap<>();\n            word = null;\n        }\n    }\n\n    // Directions for DFS\n    private static final int[][] DIRS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};\n    private static int R, C;\n    private static char[][] BOARD;\n    private static List<String> RESULT;\n\n    public static List<String> findWords(char[][] board, String[] words) {\n        // Build Trie\n        TrieNode root = new TrieNode();\n        for (String word : words) {\n            TrieNode node = root;\n            for (char c : word.toCharArray()) {\n                node.children.putIfAbsent(c, new TrieNode());\n                node = node.children.get(c);\n            }\n            node.word = word; // Store word at end\n        }\n\n        R = board.length;\n        C = board[0].length;\n        BOARD = board; // Store board reference\n        RESULT = new ArrayList<>();\n\n        for (int r = 0; r < R; r++) {\n            for (int c = 0; c < C; c++) {\n                if (root.children.containsKey(BOARD[r][c])) {\n                    backtrack(r, c, root);\n                }\n            }\n        }\n        return RESULT;\n    }\n\n    private static void backtrack(int r, int c, TrieNode parent) {\n        char charOnBoard = BOARD[r][c];\n        TrieNode node = parent.children.get(charOnBoard);\n\n        // Check if we found a word\n        if (node.word != null) {\n            RESULT.add(node.word);\n            node.word = null; // Avoid duplicates for this word\n        }\n\n        // Mark as visited\n        BOARD[r][c] = \'#\';\n\n        // Explore neighbors\n        for (int[] dir : DIRS) {\n            int nr = r + dir[0];\n            int nc = c + dir[1];\n\n            if (nr >= 0 && nr < R && nc >= 0 && nc < C && BOARD[nr][nc] != \'#\') {\n                if (node.children.containsKey(BOARD[nr][nc])) {\n                    backtrack(nr, nc, node);\n                }\n            }\n        }\n\n        // Restore board character\n        BOARD[r][c] = charOnBoard;\n    }\n}''#''\n    //         \n    //         # Explore neighbors\n    //         directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]\n    //         for dr, dc in directions:\n    //             nr, nc = r + dr, c + dc\n    //             if 0 <= nr < rows and 0 <= nc < cols:\n    //                 if board[nr][nc] in node.children:\n    //                     backtrack(nr, nc, node)\n    //         \n    //         # Restore\n    //         board[r][c] = char\n    //         \n    //         # Optimization: Remove leaf nodes\n    //         if not node.children:\n    //             parent.children.pop(char)\n    //     \n    //     # Start from each cell\n    //     for r in range(rows):\n    //         for c in range(cols):\n    //             if board[r][c] in root.children:\n    //                 backtrack(r, c, root)\n    //     \n    //     return result\n    // \n    // \n    // # ─── Test Cases ───\n    // board = [\n    //     ["o", "a", "a", "n"],\n    //     ["e", "t", "a", "e"],\n    //     ["i", "h", "k", "r"],\n    //     ["i", "f", "l", "v"]\n    // ]\n    // words = ["oath", "pea", "eat", "rain"]\n    // \n    // result = find_words(board, words)\n    // # Expected: ["eat", "oath"]\n    // \n    // board2 = [["a"]]\n    // words2 = ["a"]\n    // # Expected: ["a"]\n    // \n    // board3 = [["a", "b"], ["c", "d"]]\n    // words3 = ["xyz"]\n    // # Expected: []\n    // \n}',
  E'/**\n * @param {} \n * @return {any}\n */\nfunction findWords() {\n    // Your code here\n}',
  E'class TrieNode {\n    constructor() {\n        this.children = {};\n        this.word = null; // Store complete word at end node\n    }\n}\n\nfunction findWords(board, words) {\n    // Build Trie\n    const root = new TrieNode();\n    for (const word of words) {\n        let node = root;\n        for (const char of word) {\n            if (!(char in node.children)) {\n                node.children[char] = new TrieNode();\n            }\n            node = node.children[char];\n        }\n        node.word = word; // Store word at end\n    }\n\n    const rows = board.length;\n    const cols = board[0].length;\n    const result = [];\n\n    const DIRS = [[0, 1], [0, -1], [1, 0], [-1, 0]];\n\n    function backtrack(r, c, parent) {\n        const charOnBoard = board[r][c];\n        const node = parent.children[charOnBoard];\n\n        // Check if we found a word\n        if (node.word !== null) {\n            result.push(node.word);\n            node.word = null; // Avoid duplicates\n        }\n\n        // Mark as visited\n        board[r][c] = \'#\';\n\n        // Explore neighbors\n        for (const [dr, dc] of DIRS) {\n            const nr = r + dr;\n            const nc = c + dc;\n\n            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc] !== \'#\') {\n                if (node.children[board[nr][nc]]) { // Check if child exists for next char\n                    backtrack(nr, nc, node);\n                }\n            }\n        }\n\n        // Restore board character\n        board[r][c] = charOnBoard;\n    }\n\n    for (let r = 0; r < rows; r++) {\n        for (let c = 0; c < cols; c++) {\n            if (root.children[board[r][c]]) { // Check if first char exists in Trie\n                backtrack(r, c, root);\n            }\n        }\n    }\n\n    return result;\n}',
  ARRAY['trie', 'trees'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'uber-sde2'],
  'trie',
  '[{"input":"find_words(board, words)","expected_output":"[\"eat\", \"oath\"] (order may vary)"},{"input":"find_words(board2, words2)","expected_output":"[\"a\"]"},{"input":"find_words(board3, words3)","expected_output":"[]"}]'::jsonb,
  '[{"input":"find_words(board4, words4)","expected_output":"[]"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
