INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-redundant-connection',
  'Redundant Connection',
  'hard',
  'Redundant Connection

<!-- voice:section_check concept="Cycle detection with Union Find" -->

Problem Statement

In this problem, a tree is an undirected graph that is connected and has no cycles.

You are given a graph that started as a tree with n nodes labeled from 1 to n, with one additional edge added. The added edge has two different vertices chosen from 1 to n, and was not an edge that already existed.

The graph is represented as a 2D array `edges` of length n where `edges[i] = [ui, vi]` indicates an edge between nodes ui and vi.

Return an edge that can be removed so that the result is a tree. If there are multiple answers, return the answer that occurs last in `edges`.

Examples

~~~
Input: edges = [[1,2],[1,3],[2,3]]
Output: [2,3]
Explanation: Adding edge [2,3] creates a cycle: 1-2-3-1
~~~

~~~
Input: edges = [[1,2],[2,3],[3,4],[1,4],[1,5]]
Output: [1,4]
Explanation: Adding edge [1,4] creates a cycle: 1-2-3-4-1
~~~',
  '',
  '[{"input":"edges = [[1,2],[1,3],[2,3]]","output":"[2,3]","explanation":"Adding edge [2,3] creates a cycle: 1-2-3-1"}]'::jsonb,
  'find_redundant_connection',
  E'class UnionFind:\n    """Union Find with path compression."""\n    def __init__(self, n):\n        self.parent = list(range(n + 1))  # 1-indexed\n\n    def find(self, x):\n        # TODO: Find with path compression\n        pass\n\n    def union(self, x, y):\n        # TODO: Union two sets\n        pass\n\ndef find_redundant_connection(edges):\n    """\n    Find the redundant edge that creates a cycle.\n\n    Args:\n        edges: List of [u, v] edges (1-indexed nodes)\n    Returns:\n        List [u, v] of the redundant edge\n    Example:\n        >>> find_redundant_connection([[1,2],[1,3],[2,3]])\n        [2, 3]\n        >>> find_redundant_connection([[1,2],[2,3],[3,4],[1,4],[1,5]])\n        [1, 4]\n    """\n    # TODO: Use Union Find to detect cycle\n    pass\n# ─── Test Cases ───\n# Basic cycle\nedges1 = [[1, 2], [1, 3], [2, 3]]\n# Expected: [2, 3]\n# Larger cycle\nedges2 = [[1, 2], [2, 3], [3, 4], [1, 4], [1, 5]]\n# Expected: [1, 4]\n# Multiple possible answers (return last)\nedges3 = [[1, 2], [2, 3], [3, 1], [1, 4]]\n# Expected: [3, 1] (creates cycle 1-2-3-1)\n# Simple triangle\nedges4 = [[1, 2], [2, 3], [1, 3]]\n# Expected: [1, 3]',
  E'class UnionFind:\n    """Union Find with path compression."""\n    def __init__(self, n):\n        self.parent = list(range(n + 1))  # 1-indexed\n\n    def find(self, x):\n        """Find root with path compression."""\n        if self.parent[x] != x:\n            self.parent[x] = self.find(self.parent[x])\n        return self.parent[x]\n\n    def union(self, x, y):\n        """Union two sets."""\n        px, py = self.find(x), self.find(y)\n        if px != py:\n            self.parent[py] = px\n\ndef find_redundant_connection(edges):\n    """\n    Find the redundant edge that creates a cycle.\n\n    Time Complexity: O(n × α(n)) ≈ O(n)\n    Space Complexity: O(n)\n    """\n    n = len(edges)\n    uf = UnionFind(n)\n    for u, v in edges:\n        # If already connected, this edge creates a cycle\n        if uf.find(u) == uf.find(v):\n            return [u, v]\n        uf.union(u, v)\n    return []  # Should not reach here for valid input\n# Alternative: Union by rank\ndef find_redundant_connection_optimized(edges):\n    """Optimized with union by rank."""\n    n = len(edges)\n    parent = list(range(n + 1))\n    rank = [0] * (n + 1)\n\n    def find(x):\n        if parent[x] != x:\n            parent[x] = find(parent[x])\n        return parent[x]\n\n    def union(x, y):\n        px, py = find(x), find(y)\n        if px == py:\n            return False\n\n        if rank[px] < rank[py]:\n            px, py = py, px\n        parent[py] = px\n        if rank[px] == rank[py]:\n            rank[px] += 1\n        return True\n    for u, v in edges:\n        if not union(u, v):\n            return [u, v]\n    return []\n# ─── Test Cases ───\nedges1 = [[1, 2], [1, 3], [2, 3]]\n# Expected: [2, 3]\nedges2 = [[1, 2], [2, 3], [3, 4], [1, 4], [1, 5]]\n# Expected: [1, 4]\nedges3 = [[1, 2], [2, 3], [3, 1], [1, 4]]\n# Expected: [3, 1]\nedges4 = [[1, 2], [2, 3], [1, 3]]\n# Expected: [1, 3]',
  E'class Solution {\n    public Object findRedundantConnection(int n) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // import java.util.Arrays;\n\n    static class UnionFind {\n        int[] parent;\n\n        public UnionFind(int n) {\n            parent = new int[n + 1]; // 1-indexed\n            for (int i = 0; i <= n; i++) {\n                parent[i] = i;\n            }\n        }\n\n        public int find(int x) {\n            if (parent[x] != x) {\n                parent[x] = find(parent[x]);\n            }\n            return parent[x];\n        }\n\n        public void union(int x, int y) {\n            int px = find(x);\n            int py = find(y);\n            if (px != py) {\n                parent[py] = px;\n            }\n        }\n    }\n\n    public static int[] findRedundantConnection(int[][] edges) {\n        int n = edges.length;\n        UnionFind uf = new UnionFind(n); // Max node value is n if nodes are 1 to n\n\n        for (int[] edge : edges) {\n            int u = edge[0];\n            int v = edge[1];\n            if (uf.find(u) == uf.find(v)) {\n                return edge;\n            }\n            uf.union(u, v);\n        }\n        return new int[0]; // Should not be reached for valid input\n    }\n}',
  E'/**\n * @param {any} n\n * @return {any}\n */\nfunction findRedundantConnection(n) {\n    // Your code here\n}',
  E'class UnionFind {\n    constructor(n) {\n        this.parent = Array.from({ length: n + 1 }, (_, i) => i); // 1-indexed\n    }\n\n    find(x) {\n        if (this.parent[x] !== x) {\n            this.parent[x] = this.find(this.parent[x]);\n        }\n        return this.parent[x];\n    }\n\n    union(x, y) {\n        const px = this.find(x);\n        const py = this.find(y);\n        if (px !== py) {\n            this.parent[py] = px;\n        }\n    }\n}\n\nfunction findRedundantConnection(edges) {\n    const n = edges.length; // Max node value is n if nodes are 1 to n\n    const uf = new UnionFind(n);\n\n    for (const edge of edges) {\n        const u = edge[0];\n        const v = edge[1];\n        if (uf.find(u) === uf.find(v)) {\n            return edge;\n        }\n        uf.union(u, v);\n    }\n    return []; // Should not be reached for valid input\n}\n===',
  ARRAY['union-find'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'databricks-swe'],
  'union-find',
  '[{"input":"find_redundant_connection(edges1)","expected_output":"[2, 3]"},{"input":"find_redundant_connection(edges2)","expected_output":"[1, 4]"},{"input":"find_redundant_connection(edges3)","expected_output":"[3, 1] (creates cycle 1-2-3-1)"}]'::jsonb,
  '[{"input":"find_redundant_connection(edges4)","expected_output":"[1, 3]"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
