INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-number-of-islands-ii',
  'Number of Islands II',
  'hard',
  'Number of Islands II

<!-- voice:section_check concept="Dynamic connectivity with Union Find" -->

Problem Statement

You are given an empty 2D binary grid `grid` of size m×n. The grid represents a map where `0` represents water and `1` represents land.

Initially, all cells are water (all 0s). We may perform an `addLand` operation which turns the water at position into land. You are given an array `positions` where `positions[i] = [ri, ci]` is the position to turn into land.

Return an array of integers representing the number of islands after each addLand operation.

An **island** is surrounded by water and formed by connecting adjacent lands horizontally or vertically.

Examples

~~~
Input: m = 3, n = 3, positions = [[0,0],[0,1],[1,2],[2,1]]
Output: [1,1,2,3]

Explanation:
- Add [0,0]: 1 island
  1 0 0
  0 0 0
  0 0 0
- Add [0,1]: connects to [0,0], still 1 island
  1 1 0
  0 0 0
  0 0 0
- Add [1,2]: separate island, total 2
  1 1 0
  0 0 1
  0 0 0
- Add [2,1]: separate island, tota',
  '',
  '[{"input":"m = 3, n = 3, positions = [[0,0],[0,1],[1,2],[2,1]]","output":"[1,1,2,3]","explanation":"- Add [0,0]: 1 island"}]'::jsonb,
  'num_islands2',
  E'class UnionFind:\n    """Union Find for 2D grid."""\n    def __init__(self, size):\n        self.parent = list(range(size))\n        self.rank = [0] * size\n        self.count = 0  # Number of islands (connected components)\n\n    def find(self, x):\n        # TODO: Find with path compression\n        pass\n\n    def union(self, x, y):\n        # TODO: Union by rank, update count\n        pass\n\ndef num_islands2(m, n, positions):\n    """\n    Return number of islands after each addLand operation.\n\n    Args:\n        m: int, number of rows\n        n: int, number of columns\n        positions: List of [r, c] positions to turn into land\n    Returns:\n        List of integers, island count after each operation\n    Example:\n        >>> num_islands2(3, 3, [[0,0],[0,1],[1,2],[2,1]])\n        [1, 1, 2, 3]\n    """\n    # TODO: Use Union Find for dynamic connectivity\n    # Hint: Convert 2D coordinates to 1D index\n    pass\n# ─── Test Cases ───\n# Example from problem\n# Expected: [1, 1, 2, 3]\n# Single cell\n# Expected: [1]\n# All positions connect\n# Expected: [1, 1, 1, 1]\n# All separate islands\n# Expected: [1, 2, 3, 4]\n# Duplicate position (should be ignored)\n# Expected: [1, 1, 1]',
  E'class UnionFind:\n    """Union Find for 2D grid."""\n    def __init__(self, size):\n        self.parent = list(range(size))\n        self.rank = [0] * size\n        self.count = 0  # Number of islands (connected components)\n\n    def find(self, x):\n        """Find root with path compression."""\n        if self.parent[x] != x:\n            self.parent[x] = self.find(self.parent[x])\n        return self.parent[x]\n\n    def union(self, x, y):\n        """Union by rank."""\n        px, py = self.find(x), self.find(y)\n        if px == py:\n            return False\n\n        if self.rank[px] < self.rank[py]:\n            px, py = py, px\n        self.parent[py] = px\n        if self.rank[px] == self.rank[py]:\n            self.rank[px] += 1\n        self.count -= 1\n        return True\ndef num_islands2(m, n, positions):\n    """\n    Return number of islands after each addLand operation.\n\n    Time Complexity: O(k × α(m×n)) where k = len(positions)\n    Space Complexity: O(m × n)\n    """\n    def index(r, c):\n        """Convert 2D coordinates to 1D index."""\n        return r * n + c\n\n    uf = UnionFind(m * n)\n    grid = [[0] * n for _ in range(m)]\n    result = []\n    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]\n    for r, c in positions:\n        # Skip if already land\n        if grid[r][c] == 1:\n            result.append(uf.count)\n            continue\n        # Add land\n        grid[r][c] = 1\n        uf.count += 1\n        # Check neighbors\n        for dr, dc in directions:\n            nr, nc = r + dr, c + dc\n            if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 1:\n                uf.union(index(r, c), index(nr, nc))\n        result.append(uf.count)\n    return result\n# Alternative: Without full grid storage\ndef num_islands2_optimized(m, n, positions):\n    """Optimized using set to track land cells."""\n    def index(r, c):\n        return r * n + c\n\n    parent = {}\n    rank = {}\n    count = 0\n    def find(x):\n        if parent[x] != x:\n            parent[x] = find(parent[x])\n        return parent[x]\n\n    def union(x, y):\n        nonlocal count\n        px, py = find(x), find(y)\n        if px == py:\n            return\n\n        if rank[px] < rank[py]:\n            px, py = py, px\n        parent[py] = px\n        if rank[px] == rank[py]:\n            rank[px] += 1\n        count -= 1\n    result = []\n    land = set()\n    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]\n    for r, c in positions:\n        if (r, c) in land:\n            result.append(count)\n            continue\n        # Add new island\n        land.add((r, c))\n        idx = index(r, c)\n        parent[idx] = idx\n        rank[idx] = 0\n        count += 1\n        # Union with neighbors\n        for dr, dc in directions:\n            nr, nc = r + dr, c + dc\n            if (nr, nc) in land:\n                union(idx, index(nr, nc))\n        result.append(count)\n    return result\n# ─── Test Cases ───\n# Expected: [1, 1, 2, 3]\n# Expected: [1]\n# Expected: [1, 1, 1, 1]\n# Expected: [1, 2, 3, 4]\n# Expected: [1, 1, 1]',
  E'class Solution {\n    public Object numIslands2(Object size) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // import java.util.List;\n    // import java.util.ArrayList;\n    // import java.util.Arrays;\n\n    static class UnionFind {\n        int[] parent;\n        int[] rank;\n        int count;\n\n        public UnionFind(int size) {\n            parent = new int[size];\n            for (int i = 0; i < size; i++) {\n                parent[i] = i;\n            }\n            rank = new int[size];\n            Arrays.fill(rank, 0);\n            count = 0; // Number of islands (connected components)\n        }\n\n        public int find(int x) {\n            if (parent[x] != x) {\n                parent[x] = find(parent[x]);\n            }\n            return parent[x];\n        }\n\n        public boolean union(int x, int y) {\n            int px = find(x);\n            int py = find(y);\n\n            if (px == py) {\n                return false;\n            }\n\n            if (rank[px] < rank[py]) {\n                int temp = px;\n                px = py;\n                py = temp;\n            }\n            parent[py] = px;\n            if (rank[px] == rank[py]) {\n                rank[px]++;\n            }\n            count--;\n            return true;\n        }\n    }\n\n    public static List<Integer> numIslands2(int m, int n, int[][] positions) {\n        List<Integer> result = new ArrayList<>();\n        UnionFind uf = new UnionFind(m * n);\n        int[][] grid = new int[m][n]; // 0 for water, 1 for land\n\n        int[] dr = {0, 0, 1, -1};\n        int[] dc = {1, -1, 0, 0};\n\n        for (int[] pos : positions) {\n            int r = pos[0];\n            int c = pos[1];\n\n            // Skip if already land\n            if (grid[r][c] == 1) {\n                result.add(uf.count);\n                continue;\n            }\n\n            // Add land\n            grid[r][c] = 1;\n            uf.count++;\n\n            // Check neighbors\n            for (int i = 0; i < 4; i++) {\n                int nr = r + dr[i];\n                int nc = c + dc[i];\n\n                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1) {\n                    uf.union(r * n + c, nr * n + nc);\n                }\n            }\n            result.add(uf.count);\n        }\n        return result;\n    }\n}',
  E'/**\n * @param {any} size\n * @return {any}\n */\nfunction numIslands2(size) {\n    // Your code here\n}',
  E'class UnionFind {\n    constructor(size) {\n        this.parent = Array.from({ length: size }, (_, i) => i);\n        this.rank = new Array(size).fill(0);\n        this.count = 0; // Number of islands (connected components)\n    }\n\n    find(x) {\n        if (this.parent[x] !== x) {\n            this.parent[x] = this.find(this.parent[x]);\n        }\n        return this.parent[x];\n    }\n\n    union(x, y) {\n        let px = this.find(x);\n        let py = this.find(y);\n\n        if (px === py) {\n            return false;\n        }\n\n        if (this.rank[px] < this.rank[py]) {\n            [px, py] = [py, px]; // Swap px and py\n        }\n        this.parent[py] = px;\n        if (this.rank[px] === this.rank[py]) {\n            this.rank[px]++;\n        }\n        this.count--;\n        return true;\n    }\n}\n\nfunction numIslands2(m, n, positions) {\n    const result = [];\n    const uf = new UnionFind(m * n);\n    const grid = Array(m).fill(0).map(() => Array(n).fill(0)); // 0 for water, 1 for land\n\n    const directions = [[0, 1], [0, -1], [1, 0], [-1, 0]];\n\n    for (const pos of positions) {\n        const r = pos[0];\n        const c = pos[1];\n\n        // Skip if already land\n        if (grid[r][c] === 1) {\n            result.push(uf.count);\n            continue;\n        }\n\n        // Add land\n        grid[r][c] = 1;\n        uf.count++;\n\n        // Check neighbors\n        for (const [dr, dc] of directions) {\n            const nr = r + dr;\n            const nc = c + dc;\n\n            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] === 1) {\n                uf.union(r * n + c, nr * n + nc);\n            }\n        }\n        result.push(uf.count);\n    }\n    return result;\n}\n===',
  ARRAY['union-find'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'databricks-swe'],
  'union-find',
  '[{"input":"num_islands2(3, 3, [[0, 0], [0, 1], [1, 2], [2, 1]])","expected_output":"[1, 1, 2, 3]"},{"input":"num_islands2(1, 1, [[0, 0]])","expected_output":"[1]"},{"input":"num_islands2(3, 3, [[0, 0], [0, 1], [1, 0], [1, 1]])","expected_output":"[1, 1, 1, 1]"}]'::jsonb,
  '[{"input":"num_islands2(3, 3, [[0, 0], [0, 2], [2, 0], [2, 2]])","expected_output":"[1, 2, 3, 4]"},{"input":"num_islands2(3, 3, [[0, 0], [0, 0], [0, 1]])","expected_output":"[1, 1, 1]"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
