INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-range-sum-query-mutable',
  'Range Sum Query - Mutable',
  'hard',
  'Range Sum Query - Mutable

<!-- voice:section_check concept="Segment tree for sum queries" -->

Problem Statement

Given an integer array `nums`, handle multiple queries:
1. `sumRange(left, right)`: Return sum of elements between indices left and right inclusive
2. `update(index, val)`: Update element at index to val

Examples

~~~
Input:
["NumArray", "sumRange", "update", "sumRange"]
[[[1, 3, 5]], [0, 2], [1, 2], [0, 2]]

Output:
[null, 9, null, 8]

Explanation:
NumArray numArray = new NumArray([1, 3, 5])
numArray.sumRange(0, 2)  # 1 + 3 + 5 = 9
numArray.update(1, 2)    # nums = [1, 2, 5]
numArray.sumRange(0, 2)  # 1 + 2 + 5 = 8
~~~',
  '',
  '[{"input":"[\"NumArray\", \"sumRange\", \"update\", \"sumRange\"]","output":"[null, 9, null, 8]","explanation":"NumArray numArray = new NumArray([1, 3, 5])"}]'::jsonb,
  'NumArray',
  E'class NumArray:\n    """\n    Segment Tree implementation for range sum queries with updates.\n    Example:\n        >>> nums = NumArray([1, 3, 5])\n        >>> nums.sumRange(0, 2)\n        9\n        >>> nums.update(1, 2)\n        >>> nums.sumRange(0, 2)\n        8\n    """\n    def __init__(self, nums):\n        """Initialize with nums array."""\n        # TODO: Build segment tree\n        pass\n\n    def update(self, index, val):\n        """Update nums[index] to val."""\n        # TODO: Update segment tree\n        pass\n\n    def sumRange(self, left, right):\n        """Return sum of nums[left..right]."""\n        # TODO: Query segment tree\n        pass\n\n# ─── Test Cases ───\n# Basic operations\nnums = NumArray([1, 3, 5])\nnums.update(1, 2)\n# Single element\nnums2 = NumArray([5])\nnums2.update(0, 10)\n# Multiple updates\nnums3 = NumArray([0, 9, 5, 7, 3])\nnums3.update(1, 1)\nnums3.update(2, 2)',
  E'class NumArray:\n    """\n    Segment Tree implementation for range sum queries with updates.\n    Time Complexity:\n        __init__: O(n)\n        update: O(log n)\n        sumRange: O(log n)\n    Space Complexity: O(n)\n    """\n    def __init__(self, nums):\n        self.n = len(nums)\n        # Use 4*n size for safety (max nodes in segment tree)\n        self.tree = [0] * (4 * self.n)\n        self.nums = nums\n        if self.n > 0:\n            self._build(0, 0, self.n - 1, nums)\n\n    def _build(self, node, start, end, nums):\n        """Build segment tree recursively."""\n        if start == end:\n            self.tree[node] = nums[start]\n        else:\n            mid = (start + end) // 2\n            self._build(2 * node + 1, start, mid, nums)\n            self._build(2 * node + 2, mid + 1, end, nums)\n            self.tree[node] = self.tree[2 * node + 1] + self.tree[2 * node + 2]\n\n    def update(self, index, val):\n        """Update nums[index] to val."""\n        self._update(0, 0, self.n - 1, index, val)\n\n    def _update(self, node, start, end, idx, val):\n        """Update segment tree recursively."""\n        if start == end:\n            self.tree[node] = val\n        else:\n            mid = (start + end) // 2\n            if start <= idx <= mid:\n                self._update(2 * node + 1, start, mid, idx, val)\n            else:\n                self._update(2 * node + 2, mid + 1, end, idx, val)\n            self.tree[node] = self.tree[2 * node + 1] + self.tree[2 * node + 2]\n\n    def sumRange(self, left, right):\n        """Return sum of nums[left..right]."""\n        return self._query(0, 0, self.n - 1, left, right)\n\n    def _query(self, node, start, end, L, R):\n        """Query sum over range [L, R]."""\n        # No overlap\n        if R < start or end < L:\n            return 0\n        # Total overlap\n        if L <= start and end <= R:\n            return self.tree[node]\n        # Partial overlap\n        mid = (start + end) // 2\n        left_sum = self._query(2 * node + 1, start, mid, L, R)\n        right_sum = self._query(2 * node + 2, mid + 1, end, L, R)\n        return left_sum + right_sum\n\n# Iterative Segment Tree (more efficient)\nclass NumArrayIterative:\n    """Iterative segment tree implementation."""\n    def __init__(self, nums):\n        n = len(nums)\n        self.n = n\n        # Size to next power of 2\n        self.size = 1\n        while self.size < n:\n            self.size *= 2\n\n        # Tree has 2*size elements\n        self.tree = [0] * (2 * self.size)\n        # Copy nums to leaves\n        for i in range(n):\n            self.tree[self.size + i] = nums[i]\n        # Build tree\n        for i in range(self.size - 1, 0, -1):\n            self.tree[i] = self.tree[2 * i] + self.tree[2 * i + 1]\n    def update(self, index, val):\n        # Update leaf\n        i = self.size + index\n        self.tree[i] = val\n\n        # Propagate up\n        i //= 2\n        while i >= 1:\n            self.tree[i] = self.tree[2 * i] + self.tree[2 * i + 1]\n            i //= 2\n    def sumRange(self, left, right):\n        # Convert to leaf indices\n        l = self.size + left\n        r = self.size + right\n        res = 0\n\n        while l <= r:\n            if l % 2 == 1:  # l is right child\n                res += self.tree[l]\n                l += 1\n            if r % 2 == 0:  # r is left child\n                res += self.tree[r]\n                r -= 1\n            l //= 2\n            r //= 2\n        return res\n# ─── Test Cases ───\nnums = NumArray([1, 3, 5])\nnums.update(1, 2)\nnums2 = NumArray([5])\nnums2.update(0, 10)\nnums3 = NumArray([0, 9, 5, 7, 3])\nnums3.update(1, 1)\nnums3.update(2, 2)',
  E'class Solution {\n    public Object NumArray(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    static class NumArray {\n        private int n;\n        private int[] tree;\n\n        public NumArray(int[] nums) {\n            this.n = nums.length;\n            this.tree = new int[4 * this.n]; // Max size for segment tree\n            \n            if (this.n > 0) {\n                _build(0, 0, this.n - 1, nums);\n            }\n        }\n\n        private void _build(int node, int start, int end, int[] nums) {\n            if (start == end) {\n                tree[node] = nums[start];\n            } else {\n                int mid = start + (end - start) / 2;\n                _build(2 * node + 1, start, mid, nums);\n                _build(2 * node + 2, mid + 1, end, nums);\n                tree[node] = tree[2 * node + 1] + tree[2 * node + 2];\n            }\n        }\n\n        public void update(int index, int val) {\n            _update(0, 0, this.n - 1, index, val);\n        }\n\n        private void _update(int node, int start, int end, int idx, int val) {\n            if (start == end) {\n                tree[node] = val;\n            } else {\n                int mid = start + (end - start) / 2;\n                if (idx >= start && idx <= mid) {\n                    _update(2 * node + 1, start, mid, idx, val);\n                } else {\n                    _update(2 * node + 2, mid + 1, end, idx, val);\n                }\n                tree[node] = tree[2 * node + 1] + tree[2 * node + 2];\n            }\n        }\n\n        public int sumRange(int left, int right) {\n            return _query(0, 0, this.n - 1, left, right);\n        }\n\n        private int _query(int node, int start, int end, int L, int R) {\n            // No overlap\n            if (R < start || end < L) {\n                return 0;\n            }\n            // Total overlap\n            if (L <= start && end <= R) {\n                return tree[node];\n            }\n            // Partial overlap\n            int mid = start + (end - start) / 2;\n            int leftSum = _query(2 * node + 1, start, mid, L, R);\n            int rightSum = _query(2 * node + 2, mid + 1, end, L, R);\n            return leftSum + rightSum;\n        }\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction NumArray(nums) {\n    // Your code here\n}',
  E'class NumArray {\n    constructor(nums) {\n        this.n = nums.length;\n        this.tree = new Array(4 * this.n).fill(0);\n\n        if (this.n > 0) {\n            this._build(0, 0, this.n - 1, nums);\n        }\n    }\n\n    _build(node, start, end, nums) {\n        if (start === end) {\n            this.tree[node] = nums[start];\n        } else {\n            const mid = Math.floor((start + end) / 2);\n            this._build(2 * node + 1, start, mid, nums);\n            this._build(2 * node + 2, mid + 1, end, nums);\n            this.tree[node] = this.tree[2 * node + 1] + this.tree[2 * node + 2];\n        }\n    }\n\n    update(index, val) {\n        this._update(0, 0, this.n - 1, index, val);\n    }\n\n    _update(node, start, end, idx, val) {\n        if (start === end) {\n            this.tree[node] = val;\n        } else {\n            const mid = Math.floor((start + end) / 2);\n            if (idx >= start && idx <= mid) {\n                this._update(2 * node + 1, start, mid, idx, val);\n            } else {\n                this._update(2 * node + 2, mid + 1, end, idx, val);\n            }\n            this.tree[node] = this.tree[2 * node + 1] + this.tree[2 * node + 2];\n        }\n    }\n\n    sumRange(left, right) {\n        return this._query(0, 0, this.n - 1, left, right);\n    }\n\n    _query(node, start, end, L, R) {\n        // No overlap\n        if (R < start || end < L) {\n            return 0;\n        }\n        // Total overlap\n        if (L <= start && end <= R) {\n            return this.tree[node];\n        }\n        // Partial overlap\n        const mid = Math.floor((start + end) / 2);\n        const leftSum = this._query(2 * node + 1, start, mid, L, R);\n        const rightSum = this._query(2 * node + 2, mid + 1, end, L, R);\n        return leftSum + rightSum;\n    }\n}',
