INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'coding-interview-premium-range-maximum-query',
  'Range Maximum Query',
  'hard',
  'Range Maximum Query

<!-- voice:section_check concept="Segment tree for max queries" -->

Problem Statement

Given an integer array `nums`, handle multiple queries:
1. `query(left, right)`: Return maximum element between indices left and right inclusive
2. `update(index, val)`: Update element at index to val

Examples

~~~
Input:
["SegTree", "query", "update", "query"]
[[[1, 3, 5, 7, 9]], [0, 4], [2, 10], [0, 4]]

Output:
[null, 9, null, 10]

Explanation:
SegTree st = new SegTree([1, 3, 5, 7, 9])
st.query(0, 4)     # max([1,3,5,7,9]) = 9
st.update(2, 10)   # nums = [1, 3, 10, 7, 9]
st.query(0, 4)     # max([1,3,10,7,9]) = 10
~~~',
  '',
  '[{"input":"[\"SegTree\", \"query\", \"update\", \"query\"]","output":"[null, 9, null, 10]","explanation":"SegTree st = new SegTree([1, 3, 5, 7, 9])"}]'::jsonb,
  'SegTreeMax',
  E'class SegTreeMax:\n    """\n    Segment Tree for range maximum queries with updates.\n    Example:\n        >>> st = SegTreeMax([1, 3, 5, 7, 9])\n        >>> st.query(0, 4)\n        9\n        >>> st.update(2, 10)\n        >>> st.query(0, 4)\n        10\n    """\n    def __init__(self, nums):\n        """Initialize with nums array."""\n        # TODO: Build max segment tree\n        pass\n\n    def update(self, index, val):\n        """Update nums[index] to val."""\n        # TODO: Update max segment tree\n        pass\n\n    def query(self, left, right):\n        """Return max of nums[left..right]."""\n        # TODO: Query max segment tree\n        pass\n\n# ─── Test Cases ───\n# Basic operations\nst = SegTreeMax([1, 3, 5, 7, 9])\nst.update(2, 10)\n# Single element\nst2 = SegTreeMax([5])\nst2.update(0, 100)\n# Decreasing array\nst3 = SegTreeMax([9, 7, 5, 3, 1])\nst3.update(4, 10)',
  E'class SegTreeMax:\n    """\n    Segment Tree for range maximum queries with updates.\n    Time Complexity:\n        __init__: O(n)\n        update: O(log n)\n        query: O(log n)\n    Space Complexity: O(n)\n    """\n    def __init__(self, nums):\n        self.n = len(nums)\n        self.tree = [float(''-inf'')] * (4 * self.n)\n        if self.n > 0:\n            self._build(0, 0, self.n - 1, nums)\n\n    def _build(self, node, start, end, nums):\n        """Build max segment tree."""\n        if start == end:\n            self.tree[node] = nums[start]\n        else:\n            mid = (start + end) // 2\n            self._build(2 * node + 1, start, mid, nums)\n            self._build(2 * node + 2, mid + 1, end, nums)\n            self.tree[node] = max(self.tree[2 * node + 1], self.tree[2 * node + 2])\n\n    def update(self, index, val):\n        """Update nums[index] to val."""\n        self._update(0, 0, self.n - 1, index, val)\n\n    def _update(self, node, start, end, idx, val):\n        """Update max segment tree."""\n        if start == end:\n            self.tree[node] = val\n        else:\n            mid = (start + end) // 2\n            if start <= idx <= mid:\n                self._update(2 * node + 1, start, mid, idx, val)\n            else:\n                self._update(2 * node + 2, mid + 1, end, idx, val)\n            self.tree[node] = max(self.tree[2 * node + 1], self.tree[2 * node + 2])\n\n    def query(self, left, right):\n        """Return max of nums[left..right]."""\n        return self._query(0, 0, self.n - 1, left, right)\n\n    def _query(self, node, start, end, L, R):\n        """Query max over range [L, R]."""\n        # No overlap\n        if R < start or end < L:\n            return float(''-inf'')\n        # Total overlap\n        if L <= start and end <= R:\n            return self.tree[node]\n        # Partial overlap\n        mid = (start + end) // 2\n        left_max = self._query(2 * node + 1, start, mid, L, R)\n        right_max = self._query(2 * node + 2, mid + 1, end, L, R)\n        return max(left_max, right_max)\n\n# Generic segment tree (works for any associative operation)\nclass SegTree:\n    """Generic segment tree with custom operation."""\n    def __init__(self, nums, op, default):\n        """\n        Args:\n            nums: Array of values\n            op: Binary operation (e.g., max, min, lambda x,y: x+y)\n            default: Identity for op (e.g., -inf for max, 0 for sum)\n        """\n        self.n = len(nums)\n        self.op = op\n        self.default = default\n        self.tree = [default] * (4 * self.n)\n        if self.n > 0:\n            self._build(0, 0, self.n - 1, nums)\n\n    def _build(self, node, start, end, nums):\n        if start == end:\n            self.tree[node] = nums[start]\n        else:\n            mid = (start + end) // 2\n            self._build(2 * node + 1, start, mid, nums)\n            self._build(2 * node + 2, mid + 1, end, nums)\n            self.tree[node] = self.op(self.tree[2 * node + 1], self.tree[2 * node + 2])\n\n    def update(self, index, val):\n        self._update(0, 0, self.n - 1, index, val)\n\n    def _update(self, node, start, end, idx, val):\n        if start == end:\n            self.tree[node] = val\n        else:\n            mid = (start + end) // 2\n            if start <= idx <= mid:\n                self._update(2 * node + 1, start, mid, idx, val)\n            else:\n                self._update(2 * node + 2, mid + 1, end, idx, val)\n            self.tree[node] = self.op(self.tree[2 * node + 1], self.tree[2 * node + 2])\n\n    def query(self, left, right):\n        return self._query(0, 0, self.n - 1, left, right)\n\n    def _query(self, node, start, end, L, R):\n        if R < start or end < L:\n            return self.default\n        if L <= start and end <= R:\n            return self.tree[node]\n        mid = (start + end) // 2\n        left_val = self._query(2 * node + 1, start, mid, L, R)\n        right_val = self._query(2 * node + 2, mid + 1, end, L, R)\n        return self.op(left_val, right_val)\n\n# ─── Test Cases ───\nst = SegTreeMax([1, 3, 5, 7, 9])\nst.update(2, 10)\nst2 = SegTreeMax([5])\nst2.update(0, 100)\nst3 = SegTreeMax([9, 7, 5, 3, 1])\nst3.update(4, 10)',
  E'class Solution {\n    public Object SegTreeMax(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static class SegTreeMax {\n        private int n;\n        private int[] tree;\n        private int[] arr; // Optional: to store original array for leaf nodes, not strictly needed for segtree logic\n\n        public SegTreeMax(int[] nums) {\n            this.n = nums.length;\n            this.tree = new int[4 * n];\n            this.arr = nums; // Copy reference, or deep copy if original array should not be modified\n            if (n > 0) {\n                build(0, 0, n - 1);\n            }\n        }\n\n        private void build(int node, int start, int end) {\n            if (start == end) {\n                this.tree[node] = this.arr[start];\n            } else {\n                int mid = (start + end) / 2;\n                build(2 * node + 1, start, mid);\n                build(2 * node + 2, mid + 1, end);\n                this.tree[node] = Math.max(this.tree[2 * node + 1], this.tree[2 * node + 2]);\n            }\n        }\n\n        public void update(int index, int val) {\n            if (n == 0) return;\n            update(0, 0, n - 1, index, val);\n        }\n\n        private void update(int node, int start, int end, int idx, int val) {\n            if (start == end) {\n                this.tree[node] = val;\n                this.arr[idx] = val; // Update original array\n            } else {\n                int mid = (start + end) / 2;\n                if (idx <= mid) {\n                    update(2 * node + 1, start, mid, idx, val);\n                } else {\n                    update(2 * node + 2, mid + 1, end, idx, val);\n                }\n                this.tree[node] = Math.max(this.tree[2 * node + 1], this.tree[2 * node + 2]);\n            }\n        }\n\n        public int query(int left, int right) {\n            if (n == 0) {\n                return Integer.MIN_VALUE; // Or throw an exception for empty tree\n            }\n            return query(0, 0, n - 1, left, right);\n        }\n\n        private int query(int node, int start, int end, int L, int R) {\n            // If segment range is outside query range\n            if (R < start || end < L) {\n                return Integer.MIN_VALUE;\n            }\n            // If segment range is completely within query range\n            if (L <= start && end <= R) {\n                return this.tree[node];\n            }\n            // If segment range partially overlaps query range\n            int mid = (start + end) / 2;\n            int p1 = query(2 * node + 1, start, mid, L, R);\n            int p2 = query(2 * node + 2, mid + 1, end, L, R);\n            return Math.max(p1, p2);\n        }\n    }\n}''-inf'')] * (4 * self.n)\n    //         if self.n > 0:\n    //             self._build(0, 0, self.n - 1, nums)\n    //     \n    //     def _build(self, node, start, end, nums):\n    //         """Build max segment tree."""\n    //         if start == end:\n    //             self.tree[node] = nums[start]\n    //         else:\n    //             mid = (start + end) // 2\n    //             self._build(2 * node + 1, start, mid, nums)\n    //             self._build(2 * node + 2, mid + 1, end, nums)\n    //             self.tree[node] = max(self.tree[2 * node + 1], self.tree[2 * node + 2])\n    //     \n    //     def update(self, index, val):\n    //         """Update nums[index] to val."""\n    //         self._update(0, 0, self.n - 1, index, val)\n    //     \n    //     def _update(self, node, start, end, idx, val):\n    //         """Update max segment tree."""\n    //         if start == end:\n    //             self.tree[node] = val\n    //         else:\n    //             mid = (start + end) // 2\n    //             if start <= idx <= mid:\n    //                 self._update(2 * node + 1, start, mid, idx, val)\n    //             else:\n    //                 self._update(2 * node + 2, mid + 1, end, idx, val)\n    //             self.tree[node] = max(self.tree[2 * node + 1], self.tree[2 * node + 2])\n    //     \n    //     def query(self, left, right):\n    //         """Return max of nums[left..right]."""\n    //         return self._query(0, 0, self.n - 1, left, right)\n    //     \n    //     def _query(self, node, start, end, L, R):\n    //         """Query max over range [L, R]."""\n    //         # No overlap\n    //         if R < start or end < L:\n    //             return float(''-inf'')\n    //         # Total overlap\n    //         if L <= start and end <= R:\n    //             return self.tree[node]\n    //         # Partial overlap\n    //         mid = (start + end) // 2\n    //         left_max = self._query(2 * node + 1, start, mid, L, R)\n    //         right_max = self._query(2 * node + 2, mid + 1, end, L, R)\n    //         return max(left_max, right_max)\n    // \n    // \n    // # Generic segment tree (works for any associative operation)\n    // class SegTree:\n    //     """Generic segment tree with custom operation."""\n    //     \n    //     def __init__(self, nums, op, default):\n    //         """\n    //         Args:\n    //             nums: Array of values\n    //             op: Binary operation (e.g., max, min, lambda x,y: x+y)\n    //             default: Identity for op (e.g., -inf for max, 0 for sum)\n    //         """\n    //         self.n = len(nums)\n    //         self.op = op\n    //         self.default = default\n    //         self.tree = [default] * (4 * self.n)\n    //         if self.n > 0:\n    //             self._build(0, 0, self.n - 1, nums)\n    //     \n    //     def _build(self, node, start, end, nums):\n    //         if start == end:\n    //             self.tree[node] = nums[start]\n    //         else:\n    //             mid = (start + end) // 2\n    //             self._build(2 * node + 1, start, mid, nums)\n    //             self._build(2 * node + 2, mid + 1, end, nums)\n    //             self.tree[node] = self.op(self.tree[2 * node + 1], self.tree[2 * node + 2])\n    //     \n    //     def update(self, index, val):\n    //         self._update(0, 0, self.n - 1, index, val)\n    //     \n    //     def _update(self, node, start, end, idx, val):\n    //         if start == end:\n    //             self.tree[node] = val\n    //         else:\n    //             mid = (start + end) // 2\n    //             if start <= idx <= mid:\n    //                 self._update(2 * node + 1, start, mid, idx, val)\n    //             else:\n    //                 self._update(2 * node + 2, mid + 1, end, idx, val)\n    //             self.tree[node] = self.op(self.tree[2 * node + 1], self.tree[2 * node + 2])\n    //     \n    //     def query(self, left, right):\n    //         return self._query(0, 0, self.n - 1, left, right)\n    //     \n    //     def _query(self, node, start, end, L, R):\n    //         if R < start or end < L:\n    //             return self.default\n    //         if L <= start and end <= R:\n    //             return self.tree[node]\n    //         mid = (start + end) // 2\n    //         left_val = self._query(2 * node + 1, start, mid, L, R)\n    //         right_val = self._query(2 * node + 2, mid + 1, end, L, R)\n    //         return self.op(left_val, right_val)\n    // \n    // \n    // # ─── Test Cases ───\n    // st = SegTreeMax([1, 3, 5, 7, 9])\n    // \n    // st.update(2, 10)\n    // \n    // st2 = SegTreeMax([5])\n    // st2.update(0, 100)\n    // \n    // st3 = SegTreeMax([9, 7, 5, 3, 1])\n    // st3.update(4, 10)\n    // \n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction SegTreeMax(nums) {\n    // Your code here\n}',
  E'class SegTreeMax {\n    constructor(nums) {\n        this.n = nums.length;\n        // Initialize with a very small number for max queries\n        this.tree = new Array(4 * this.n).fill(-Infinity);\n        this.arr = nums; // Store original array for leaf nodes\n        if (this.n > 0) {\n            this._build(0, 0, this.n - 1);\n        }\n    }\n\n    _build(node, start, end) {\n        if (start === end) {\n            this.tree[node] = this.arr[start];\n        } else {\n            const mid = Math.floor((start + end) / 2);\n            this._build(2 * node + 1, start, mid);\n            this._build(2 * node + 2, mid + 1, end);\n            this.tree[node] = Math.max(this.tree[2 * node + 1], this.tree[2 * node + 2]);\n        }\n    }\n\n    update(index, val) {\n        if (this.n === 0) return;\n        this._update(0, 0, this.n - 1, index, val);\n    }\n\n    _update(node, start, end, idx, val) {\n        if (start === end) {\n            this.tree[node] = val;\n            this.arr[idx] = val; // Update original array\n        } else {\n            const mid = Math.floor((start + end) / 2);\n            if (idx <= mid) {\n                this._update(2 * node + 1, start, mid, idx, val);\n            } else {\n                this._update(2 * node + 2, mid + 1, end, idx, val);\n            }\n            this.tree[node] = Math.max(this.tree[2 * node + 1], this.tree[2 * node + 2]);\n        }\n    }\n\n    query(left, right) {\n        if (this.n === 0) {\n            return -Infinity; // Or handle error\n        }\n        return this._query(0, 0, this.n - 1, left, right);\n    }\n\n    _query(node, start, end, L, R) {\n        // If segment range is outside query range\n        if (R < start || end < L) {\n            return -Infinity;\n        }\n        // If segment range is completely within query range\n        if (L <= start && end <= R) {\n            return this.tree[node];\n        }\n        // If segment range partially overlaps query range\n        const mid = Math.floor((start + end) / 2);\n        const p1 = this._query(2 * node + 1, start, mid, L, R);\n        const p2 = this._query(2 * node + 2, mid + 1, end, L, R);\n        return Math.max(p1, p2);\n    }\n}\n===END',
