INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dsa-linked-list-operations',
  'Linked List Operations',
  'medium',
  'Linked List Operations

Problem Statement

Implement three essential linked list operations:

1. **Reverse** a singly linked list in-place
2. **Find the middle** node using the fast/slow pointer technique
3. **Detect a cycle** using Floyd''s algorithm

These are fundamental building blocks that appear in many interview problems.

Examples

Key Techniques

- **Three-pointer reversal**: Use prev, curr, next to reverse links one at a time
- **Fast/slow pointers**: Fast moves 2 steps, slow moves 1. When fast reaches the end, slow is at the middle
- **Floyd''s cycle detection**: If fast and slow ever meet, there is a cycle',
  '',
  '[]'::jsonb,
  'build_list',
  E'class Node:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef build_list(values):\n    if not values:\n        return None\n    head = Node(values[0])\n    curr = head\n    for v in values[1:]:\n        curr.next = Node(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef reverse_list(head):\n    # TODO: Reverse the linked list in-place, return new head\n    pass\n\ndef find_middle(head):\n    # TODO: Return the value of the middle node (slow/fast pointers)\n    pass\n\ndef has_cycle(head):\n    # TODO: Return True if the list has a cycle\n    pass\n\nhead = build_list([1, 2, 3, 4])\n# Create a cycle: 4 -> 2\ncurr = head\nwhile curr.next:\n    curr = curr.next\ncurr.next = head.next',
  E'class Node:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef build_list(values):\n    if not values:\n        return None\n    head = Node(values[0])\n    curr = head\n    for v in values[1:]:\n        curr.next = Node(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef reverse_list(head):\n    prev = None\n    curr = head\n    while curr:\n        next_node = curr.next\n        curr.next = prev\n        prev = curr\n        curr = next_node\n    return prev\n\ndef find_middle(head):\n    slow = head\n    fast = head\n    while fast.next and fast.next.next:\n        slow = slow.next\n        fast = fast.next.next\n    return slow.val\n\ndef has_cycle(head):\n    slow = head\n    fast = head\n    while fast and fast.next:\n        slow = slow.next\n        fast = fast.next.next\n        if slow == fast:\n            return True\n    return False\n\nhead = build_list([1, 2, 3, 4])\n# Create a cycle: 4 -> 2\ncurr = head\nwhile curr.next:\n    curr = curr.next\ncurr.next = head.next',
  E'class Solution {\n    public Object buildList(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayList;\nimport java.util.List;\n\nclass Solution {\n    public static class Node {\n        int val;\n        Node next;\n\n        public Node(int val) {\n            this.val = val;\n            this.next = null;\n        }\n    }\n\n    public static Node buildList(List<Integer> values) {\n        if (values == null || values.isEmpty()) {\n            return null;\n        }\n        Node head = new Node(values.get(0));\n        Node curr = head;\n        for (int i = 1; i < values.size(); i++) {\n            curr.next = new Node(values.get(i));\n            curr = curr.next;\n        }\n        return head;\n    }\n\n    public static List<Integer> toList(Node head) {\n        List<Integer> result = new ArrayList<>();\n        while (head != null) {\n            result.add(head.val);\n            head = head.next;\n        }\n        return result;\n    }\n\n    public static Node reverseList(Node head) {\n        Node prev = null;\n        Node curr = head;\n        while (curr != null) {\n            Node nextNode = curr.next;\n            curr.next = prev;\n            prev = curr;\n            curr = nextNode;\n        }\n        return prev;\n    }\n\n    public static int findMiddle(Node head) {\n        Node slow = head;\n        Node fast = head;\n        while (fast.next != null && fast.next.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        return slow.val;\n    }\n\n    public static boolean hasCycle(Node head) {\n        Node slow = head;\n        Node fast = head;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) {\n                return true;\n            }\n        }\n        return false;\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildList(val) {\n    // Your code here\n}',
  E'class Node {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction buildList(values) {\n    if (!values || values.length === 0) {\n        return null;\n    }\n    let head = new Node(values[0]);\n    let curr = head;\n    for (let i = 1; i < values.length; i++) {\n        curr.next = new Node(values[i]);\n        curr = curr.next;\n    }\n    return head;\n}\n\nfunction toList(head) {\n    let result = [];\n    while (head) {\n        result.push(head.val);\n        head = head.next;\n    }\n    return result;\n}\n\nfunction reverseList(head) {\n    let prev = null;\n    let curr = head;\n    while (curr) {\n        let nextNode = curr.next;\n        curr.next = prev;\n        prev = curr;\n        curr = nextNode;\n    }\n    return prev;\n}\n\nfunction findMiddle(head) {\n    let slow = head;\n    let fast = head;\n    while (fast.next && fast.next.next) {\n        slow = slow.next;\n        fast = fast.next.next;\n    }\n    return slow.val;\n}\n\nfunction hasCycle(head) {\n    let slow = head;\n    let fast = head;\n    while (fast && fast.next) {\n        slow = slow.next;\n        fast = fast.next.next;\n        if (slow === fast) {\n            return true;\n        }\n    }\n    return false;\n}\n\n// Example usage (not part of the solution, but for context)\n// let head = buildList([1, 2, 3, 4]);\n// // Create a cycle: 4 -> 2\n// let curr = head;\n// while (curr.next) {\n//     curr = curr.next;\n// }\n// curr.next = head.next;\n// console.log(hasCycle(head)); // true',
  ARRAY['linked-lists', 'linked-list'],
  ARRAY['meta-e4', 'amazon-sde2', 'microsoft-sde2', 'apple-ict3'],
  'linked-lists',
  '[]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
