INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dsa-linked-list-problems',
  'Linked List Problems',
  'medium',
  'Linked List Problems

Problem Statement

Solve two classic linked list interview problems:

**Problem 1: Merge Two Sorted Lists**

Given two sorted linked lists, merge them into a single sorted linked list.

**Problem 2: Remove N-th Node From End**

Given a linked list, remove the n-th node from the end and return the head.',
  '',
  '[]'::jsonb,
  'build_list',
  E'class Node:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef build_list(values):\n    if not values:\n        return None\n    head = Node(values[0])\n    curr = head\n    for v in values[1:]:\n        curr.next = Node(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef merge_sorted(l1, l2):\n    # TODO: Merge two sorted linked lists\n    pass\n\ndef remove_nth_from_end(head, n):\n    # TODO: Remove the n-th node from the end\n    pass\n\n# Expected: [1, 2, 3, 4, 5, 6]\n# Expected: [1, 2, 3]\n# Expected: [1, 2]\n# Expected: [1, 2, 3, 5]\n# Expected: [1, 2, 3, 4]\n# Expected: []',
  E'class Node:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef build_list(values):\n    if not values:\n        return None\n    head = Node(values[0])\n    curr = head\n    for v in values[1:]:\n        curr.next = Node(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef merge_sorted(l1, l2):\n    dummy = Node(0)\n    curr = dummy\n    while l1 and l2:\n        if l1.val <= l2.val:\n            curr.next = l1\n            l1 = l1.next\n        else:\n            curr.next = l2\n            l2 = l2.next\n        curr = curr.next\n    curr.next = l1 if l1 else l2\n    return dummy.next\n\ndef remove_nth_from_end(head, n):\n    dummy = Node(0)\n    dummy.next = head\n    fast = dummy\n    slow = dummy\n    for _ in range(n + 1):\n        fast = fast.next\n    while fast:\n        fast = fast.next\n        slow = slow.next\n    slow.next = slow.next.next\n    return dummy.next\n\n# Expected: [1, 2, 3, 4, 5, 6]\n# Expected: [1, 2, 3]\n# Expected: [1, 2]\n# Expected: [1, 2, 3, 5]\n# Expected: [1, 2, 3, 4]\n# Expected: []',
  E'class Solution {\n    public Object buildList(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.List;\n    // import java.util.ArrayList;\n\n    public static class Node {\n        int val;\n        Node next;\n\n        public Node(int val) {\n            this.val = val;\n            this.next = null;\n        }\n    }\n\n    public static Node buildList(List<Integer> values) {\n        if (values == null || values.isEmpty()) {\n            return null;\n        }\n        Node head = new Node(values.get(0));\n        Node curr = head;\n        for (int i = 1; i < values.size(); i++) {\n            curr.next = new Node(values.get(i));\n            curr = curr.next;\n        }\n        return head;\n    }\n\n    public static Node mergeSorted(Node l1, Node l2) {\n        Node dummy = new Node(0);\n        Node curr = dummy;\n        while (l1 != null && l2 != null) {\n            if (l1.val <= l2.val) {\n                curr.next = l1;\n                l1 = l1.next;\n            } else {\n                curr.next = l2;\n                l2 = l2.next;\n            }\n            curr = curr.next;\n        }\n        curr.next = (l1 != null) ? l1 : l2;\n        return dummy.next;\n    }\n\n    public static Node removeNthFromEnd(Node head, int n) {\n        Node dummy = new Node(0);\n        dummy.next = head;\n        Node fast = dummy;\n        Node slow = dummy;\n        for (int i = 0; i < n + 1; i++) {\n            fast = fast.next;\n        }\n        while (fast != null) {\n            fast = fast.next;\n            slow = slow.next;\n        }\n        slow.next = slow.next.next;\n        return dummy.next;\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction buildList(val) {\n    // Your code here\n}',
  E'class Node {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction buildList(values) {\n    if (!values || values.length === 0) {\n        return null;\n    }\n    let head = new Node(values[0]);\n    let curr = head;\n    for (let i = 1; i < values.length; i++) {\n        curr.next = new Node(values[i]);\n        curr = curr.next;\n    }\n    return head;\n}\n\nfunction mergeSorted(l1, l2) {\n    let dummy = new Node(0);\n    let curr = dummy;\n    while (l1 && l2) {\n        if (l1.val <= l2.val) {\n            curr.next = l1;\n            l1 = l1.next;\n        } else {\n            curr.next = l2;\n            l2 = l2.next;\n        }\n        curr = curr.next;\n    }\n    curr.next = l1 || l2;\n    return dummy.next;\n}\n\nfunction removeNthFromEnd(head, n) {\n    let dummy = new Node(0);\n    dummy.next = head;\n    let fast = dummy;\n    let slow = dummy;\n    for (let i = 0; i < n + 1; i++) {\n        fast = fast.next;\n    }\n    while (fast) {\n        fast = fast.next;\n        slow = slow.next;\n    }\n    slow.next = slow.next.next;\n    return dummy.next;\n}',
