INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dsa-min-stack',
  'Min Stack & Monotonic Queue',
  'medium',
  'Min Stack & Monotonic Queue

Problem 1: Min Stack

Design a stack that supports `push`, `pop`, `peek`, and retrieving the **minimum element** — all in O(1) time.

**Key Insight**: Maintain a second stack that tracks the minimum at each level.

Problem 2: Sliding Window Maximum

Given an array and window size k, return the maximum value in each window as it slides from left to right. Use a **monotonic deque** for O(n) total time.',
  '',
  '[{"input":"[1, 3, -1, -3, 5, 3, 6, 7], 3","output":"[3, 3, 5, 5, 6, 7]"},{"input":"[1, -1], 1","output":"[1, -1]"},{"input":"[4, 3, 2, 1], 2","output":"[4, 3, 2]"}]'::jsonb,
  'sliding_window_max',
  E'from collections import deque\nclass MinStack:\n    def __init__(self):\n        self.stack = []\n        self.min_stack = []\n\n    def push(self, val):\n        # TODO: Push val and update min tracking\n        pass\n\n    def pop(self):\n        # TODO: Pop and update min tracking\n        pass\n\n    def peek(self):\n        # TODO: Return top element\n        pass\n\n    def get_min(self):\n        # TODO: Return minimum element in O(1)\n        pass\n\ndef sliding_window_max(nums, k):\n    # TODO: Return list of max values for each window of size k\n    # Use a monotonic deque\n    pass\n\nms = MinStack()\nms.push(3)\nms.push(5)\nms.push(1)\nms.pop()\n# Expected: [3, 3, 5, 5, 6, 7]\n# Expected: [1, -1]\n# Expected: [4, 3, 2]',
  E'from collections import deque\nclass MinStack:\n    def __init__(self):\n        self.stack = []\n        self.min_stack = []\n\n    def push(self, val):\n        self.stack.append(val)\n        if not self.min_stack or val <= self.min_stack[-1]:\n            self.min_stack.append(val)\n\n    def pop(self):\n        if self.stack:\n            val = self.stack.pop()\n            if val == self.min_stack[-1]:\n                self.min_stack.pop()\n            return val\n        return None\n\n    def peek(self):\n        return self.stack[-1] if self.stack else None\n\n    def get_min(self):\n        return self.min_stack[-1] if self.min_stack else None\n\ndef sliding_window_max(nums, k):\n    dq = deque()  # stores indices\n    result = []\n    for i in range(len(nums)):\n        # Remove elements outside the window\n        while dq and dq[0] < i - k + 1:\n            dq.popleft()\n        # Remove smaller elements from the back\n        while dq and nums[dq[-1]] < nums[i]:\n            dq.pop()\n        dq.append(i)\n        # Start recording once we have a full window\n        if i >= k - 1:\n            result.append(nums[dq[0]])\n    return result\n\nms = MinStack()\nms.push(3)\nms.push(5)\nms.push(1)\nms.pop()\n# Expected: [3, 3, 5, 5, 6, 7]\n# Expected: [1, -1]\n# Expected: [4, 3, 2]',
  E'class Solution {\n    public Object slidingWindowMax() {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayDeque;\nimport java.util.ArrayList;\nimport java.util.Deque;\nimport java.util.List;\n\nclass Solution {\n    public static class MinStack {\n        private List<Integer> stack;\n        private List<Integer> minStack;\n\n        public MinStack() {\n            this.stack = new ArrayList<>();\n            this.minStack = new ArrayList<>();\n        }\n\n        public void push(int val) {\n            this.stack.add(val);\n            if (this.minStack.isEmpty() || val <= this.minStack.get(this.minStack.size() - 1)) {\n                this.minStack.add(val);\n            }\n        }\n\n        public Integer pop() {\n            if (this.stack.isEmpty()) {\n                return null;\n            }\n            int val = this.stack.remove(this.stack.size() - 1);\n            if (val == this.minStack.get(this.minStack.size() - 1)) {\n                this.minStack.remove(this.minStack.size() - 1);\n            }\n            return val;\n        }\n\n        public Integer peek() {\n            return this.stack.isEmpty() ? null : this.stack.get(this.stack.size() - 1);\n        }\n\n        public Integer getMin() {\n            return this.minStack.isEmpty() ? null : this.minStack.get(this.minStack.size() - 1);\n        }\n    }\n\n    public static List<Integer> slidingWindowMax(int[] nums, int k) {\n        Deque<Integer> dq = new ArrayDeque<>(); // stores indices\n        List<Integer> result = new ArrayList<>();\n\n        for (int i = 0; i < nums.length; i++) {\n            // Remove elements outside the window\n            while (!dq.isEmpty() && dq.peekFirst() < i - k + 1) {\n                dq.pollFirst();\n            }\n            // Remove smaller elements from the back\n            while (!dq.isEmpty() && nums[dq.peekLast()] < nums[i]) {\n                dq.pollLast();\n            }\n            dq.offerLast(i);\n            // Start recording once we have a full window\n            if (i >= k - 1) {\n                result.add(nums[dq.peekFirst()]);\n            }\n        }\n        return result;\n    }\n}',
  E'/**\n * @param {} \n * @return {any}\n */\nfunction slidingWindowMax() {\n    // Your code here\n}',
  E'class MinStack {\n    constructor() {\n        this.stack = [];\n        this.minStack = [];\n    }\n\n    push(val) {\n        this.stack.push(val);\n        if (this.minStack.length === 0 || val <= this.minStack[this.minStack.length - 1]) {\n            this.minStack.push(val);\n        }\n    }\n\n    pop() {\n        if (this.stack.length === 0) {\n            return null;\n        }\n        let val = this.stack.pop();\n        if (val === this.minStack[this.minStack.length - 1]) {\n            this.minStack.pop();\n        }\n        return val;\n    }\n\n    peek() {\n        return this.stack.length === 0 ? null : this.stack[this.stack.length - 1];\n    }\n\n    getMin() {\n        return this.minStack.length === 0 ? null : this.minStack[this.minStack.length - 1];\n    }\n}\n\nfunction slidingWindowMax(nums, k) {\n    let dq = []; // stores indices\n    let result = [];\n\n    for (let i = 0; i < nums.length; i++) {\n        // Remove elements outside the window\n        while (dq.length > 0 && dq[0] < i - k + 1) {\n            dq.shift();\n        }\n        // Remove smaller elements from the back\n        while (dq.length > 0 && nums[dq[dq.length - 1]] < nums[i]) {\n            dq.pop();\n        }\n        dq.push(i);\n        // Start recording once we have a full window\n        if (i >= k - 1) {\n            result.push(nums[dq[0]]);\n        }\n    }\n    return result;\n}\n\n// Example usage (not part of the solution, but for context)\n// let ms = new MinStack();\n// ms.push(3);\n// ms.push(5);\n// ms.push(1);\n// ms.pop();\n// console.log(ms.getMin()); // 3\n// console.log(slidingWindowMax([1,3,-1,-3,5,3,6,7], 3)); // [3, 3, 5, 5, 6, 7]',
  ARRAY['stacks-queues', 'stack'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2'],
  'stacks-queues',
  '[{"input":"sliding_window_max([1, 3, -1, -3, 5, 3, 6, 7], 3)","expected_output":"[3, 3, 5, 5, 6, 7]"},{"input":"sliding_window_max([1, -1], 1)","expected_output":"[1, -1]"},{"input":"sliding_window_max([4, 3, 2, 1], 2)","expected_output":"[4, 3, 2]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
