INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dsa-tree-traversals',
  'Tree Traversals',
  'easy',
  'Tree Traversals

The Four Traversals

| Traversal | Order | Use Case |
|-----------|-------|----------|
| **In-order** | Left, Root, Right | Sorted output from BST |
| **Pre-order** | Root, Left, Right | Copying/serializing a tree |
| **Post-order** | Left, Right, Root | Deleting a tree, expression eval |
| **Level-order** | Level by level (BFS) | Level-based processing |

Traversal Orders Visualized

Problem

Given a binary tree, implement all four traversals. Return each as a list of values.',
  '',
  '[{"input":"root","output":"[4, 2, 5, 1, 3, 6]"}]'::jsonb,
  'inorder',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef inorder(root):\n    # TODO: Return in-order traversal as list\n    pass\n\ndef preorder(root):\n    # TODO: Return pre-order traversal as list\n    pass\n\ndef postorder(root):\n    # TODO: Return post-order traversal as list\n    pass\n\ndef level_order(root):\n    # TODO: Return level-order traversal as list\n    pass\n\n# Build test tree\nroot = TreeNode(1)\nroot.left = TreeNode(2)\nroot.right = TreeNode(3)\nroot.left.left = TreeNode(4)\nroot.left.right = TreeNode(5)\nroot.right.right = TreeNode(6)',
  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef inorder(root):\n    if not root:\n        return []\n    return inorder(root.left) + [root.val] + inorder(root.right)\n\ndef preorder(root):\n    if not root:\n        return []\n    return [root.val] + preorder(root.left) + preorder(root.right)\n\ndef postorder(root):\n    if not root:\n        return []\n    return postorder(root.left) + postorder(root.right) + [root.val]\n\ndef level_order(root):\n    if not root:\n        return []\n    result = []\n    queue = deque([root])\n    while queue:\n        node = queue.popleft()\n        result.append(node.val)\n        if node.left:\n            queue.append(node.left)\n        if node.right:\n            queue.append(node.right)\n    return result\n\n# Build test tree\nroot = TreeNode(1)\nroot.left = TreeNode(2)\nroot.right = TreeNode(3)\nroot.left.left = TreeNode(4)\nroot.left.right = TreeNode(5)\nroot.right.right = TreeNode(6)',
  E'class Solution {\n    public Object inorder(Object val) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.*;\n\nclass Solution {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n\n        TreeNode(int val) {\n            this.val = val;\n            this.left = null;\n            this.right = null;\n        }\n    }\n\n    public static List<Integer> inorder(TreeNode root) {\n        if (root == null) {\n            return new ArrayList<>();\n        }\n        List<Integer> result = new ArrayList<>();\n        result.addAll(inorder(root.left));\n        result.add(root.val);\n        result.addAll(inorder(root.right));\n        return result;\n    }\n\n    public static List<Integer> preorder(TreeNode root) {\n        if (root == null) {\n            return new ArrayList<>();\n        }\n        List<Integer> result = new ArrayList<>();\n        result.add(root.val);\n        result.addAll(preorder(root.left));\n        result.addAll(preorder(root.right));\n        return result;\n    }\n\n    public static List<Integer> postorder(TreeNode root) {\n        if (root == null) {\n            return new ArrayList<>();\n        }\n        List<Integer> result = new ArrayList<>();\n        result.addAll(postorder(root.left));\n        result.addAll(postorder(root.right));\n        result.add(root.val);\n        return result;\n    }\n\n    public static List<Integer> levelOrder(TreeNode root) {\n        if (root == null) {\n            return new ArrayList<>();\n        }\n        List<Integer> result = new ArrayList<>();\n        Queue<TreeNode> queue = new ArrayDeque<>();\n        queue.offer(root);\n\n        while (!queue.isEmpty()) {\n            TreeNode node = queue.poll();\n            result.add(node.val);\n            if (node.left != null) {\n                queue.offer(node.left);\n            }\n            if (node.right != null) {\n                queue.offer(node.right);\n            }\n        }\n        return result;\n    }\n}',
  E'/**\n * @param {any} val\n * @return {any}\n */\nfunction inorder(val) {\n    // Your code here\n}',
  E'class TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction inorder(root) {\n    if (!root) {\n        return [];\n    }\n    return [...inorder(root.left), root.val, ...inorder(root.right)];\n}\n\nfunction preorder(root) {\n    if (!root) {\n        return [];\n    }\n    return [root.val, ...preorder(root.left), ...preorder(root.right)];\n}\n\nfunction postorder(root) {\n    if (!root) {\n        return [];\n    }\n    return [...postorder(root.left), ...postorder(root.right), root.val];\n}\n\nfunction levelOrder(root) {\n    if (!root) {\n        return [];\n    }\n    const result = [];\n    const queue = [root]; // JavaScript array can be used as a queue\n\n    while (queue.length > 0) {\n        const node = queue.shift(); // Dequeue\n        result.push(node.val);\n\n        if (node.left) {\n            queue.push(node.left); // Enqueue\n        }\n        if (node.right) {\n            queue.push(node.right); // Enqueue\n        }\n    }\n    return result;\n}',
  ARRAY['trees'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'uber-sde2'],
  'trees',
  '[{"input":"inorder(root)","expected_output":"[4, 2, 5, 1, 3, 6]"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
