INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dsa-graph-bfs',
  'Breadth-First Search',
  'easy',
  'Breadth-First Search (BFS)

BFS explores a graph **level by level**, visiting all neighbors of a node before moving to their neighbors. It uses a **queue** to maintain the order.

Properties

- Finds the **shortest path** in unweighted graphs
- Time: O(V + E)
- Space: O(V) for the queue and visited set',
  '',
  '[{"input":"graph, ''A''","output":"[''A'', ''B'', ''C'', ''D'', ''E'', ''F'']"}]'::jsonb,
  'bfs_traversal',
  E'from collections import deque\ndef bfs_traversal(graph, start):\n    # TODO: Return list of vertices in BFS order\n    pass\n\ndef bfs_shortest_path(graph, start, end):\n    # TODO: Return shortest path as list of vertices\n    # Return empty list if no path exists\n    pass\n\ngraph = {\n    ''A'': [''B'', ''C''],\n    ''B'': [''A'', ''D'', ''E''],\n    ''C'': [''A'', ''F''],\n    ''D'': [''B''],\n    ''E'': [''B'', ''F''],\n    ''F'': [''C'', ''E'']\n}\n# Expected: [''A'', ''B'', ''C'', ''D'', ''E'', ''F'']\n# Expected: [''A'', ''C'', ''F'']\n# Expected: [''D'', ''B'', ''E'', ''F'']\n# Expected: []',
  E'from collections import deque\ndef bfs_traversal(graph, start):\n    visited = set([start])\n    queue = deque([start])\n    result = []\n    while queue:\n        vertex = queue.popleft()\n        result.append(vertex)\n        for neighbor in graph.get(vertex, []):\n            if neighbor not in visited:\n                visited.add(neighbor)\n                queue.append(neighbor)\n    return result\n\ndef bfs_shortest_path(graph, start, end):\n    if start == end:\n        return [start]\n    visited = set([start])\n    queue = deque([(start, [start])])\n    while queue:\n        vertex, path = queue.popleft()\n        for neighbor in graph.get(vertex, []):\n            if neighbor not in visited:\n                new_path = path + [neighbor]\n                if neighbor == end:\n                    return new_path\n                visited.add(neighbor)\n                queue.append((neighbor, new_path))\n    return []\n\ngraph = {\n    ''A'': [''B'', ''C''],\n    ''B'': [''A'', ''D'', ''E''],\n    ''C'': [''A'', ''F''],\n    ''D'': [''B''],\n    ''E'': [''B'', ''F''],\n    ''F'': [''C'', ''E'']\n}\n# Expected: [''A'', ''B'', ''C'', ''D'', ''E'', ''F'']\n# Expected: [''A'', ''C'', ''F'']\n# Expected: [''D'', ''B'', ''E'', ''F'']\n# Expected: []',
  E'class Solution {\n    public Object bfsTraversal(Object graph, Object start) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.*;\n\nclass Solution {\n\n    /**\n     * Performs a Breadth-First Search (BFS) traversal on a graph starting from a given vertex.\n     *\n     * @param graph The graph represented as an adjacency list (Map from vertex to list of neighbors).\n     * @param start The starting vertex for the traversal.\n     * @param <V> The type of the vertices in the graph.\n     * @return A list of vertices in the order they were visited during the BFS traversal.\n     */\n    public static <V> List<V> bfsTraversal(Map<V, List<V>> graph, V start) {\n        // Set to keep track of visited vertices to avoid cycles and redundant processing.\n        Set<V> visited = new HashSet<>();\n        // Queue for BFS, storing vertices to be processed.\n        Deque<V> queue = new LinkedList<>();\n        // List to store the result of the traversal.\n        List<V> result = new ArrayList<>();\n\n        // Start the BFS from the ''start'' vertex.\n        visited.add(start);\n        queue.addLast(start); // Add to the end of the queue\n\n        while (!queue.isEmpty()) {\n            // Get the next vertex from the front of the queue.\n            V vertex = queue.removeFirst(); // Remove from the front of the queue\n            result.add(vertex); // Add to the result list\n\n            // Iterate over all neighbors of the current vertex.\n            // Use getOrDefault to handle cases where a vertex might not have any neighbors\n            // or might not be explicitly a key in the graph map, returning an empty list.\n            for (V neighbor : graph.getOrDefault(vertex, Collections.emptyList())) {\n                // If the neighbor has not been visited yet, mark it as visited and add it to the queue.\n                if (!visited.contains(neighbor)) {\n                    visited.add(neighbor);\n                    queue.addLast(neighbor);\n                }\n            }\n        }\n        return result;\n    }\n\n    // Helper nested static class to store a vertex along with the path taken to reach it.\n    static class PathNode<V> {\n        V vertex;\n        List<V> path;\n\n        PathNode(V vertex, List<V> path) {\n            this.vertex = vertex;\n            this.path = path;\n        }\n    }\n\n    /**\n     * Finds the shortest path between two vertices in an unweighted graph using BFS.\n     *\n     * @param graph The graph represented as an adjacency list (Map from vertex to list of neighbors).\n     * @param start The starting vertex.\n     * @param end The target vertex.\n     * @param <V> The type of the vertices in the graph.\n     * @return A list of vertices representing the shortest path from start to end,\n     *         or an empty list if no path exists.\n     */\n    public static <V> List<V> bfsShortestPath(Map<V, List<V>> graph, V start, V end) {\n        // If start and end are the same, the path is just the start vertex.\n        if (start.equals(end)) {\n            return Collections.singletonList(start);\n        }\n\n        // Set to keep track of visited vertices to avoid cycles and redundant processing.\n        // This set tracks only vertices, not paths.\n        Set<V> visited = new HashSet<>();\n        // Queue for BFS, storing PathNode objects (vertex and the path to reach it).\n        Deque<PathNode<V>> queue = new LinkedList<>();\n\n        // Start the BFS from the ''start'' vertex.\n        visited.add(start);\n        // Initialize the queue with the start vertex and its initial path.\n        queue.addLast(new PathNode<>(start, Collections.singletonList(start)));\n\n        while (!queue.isEmpty()) {\n            // Get the next PathNode from the front of the queue.\n            PathNode<V> current = queue.removeFirst();\n            V vertex = current.vertex;\n            List<V> path = current.path;\n\n            // Iterate over all neighbors of the current vertex.\n            for (V neighbor : graph.getOrDefault(vertex, Collections.emptyList())) {\n                // If the neighbor has not been visited yet.\n                if (!visited.contains(neighbor)) {\n                    // Create a new path by extending the current path.\n                    List<V> newPath = new ArrayList<>(path);\n                    newPath.add(neighbor);\n\n                    // If the neighbor is the target ''end'' vertex, we found the shortest path.\n                    if (neighbor.equals(end)) {\n                        return newPath;\n                    }\n\n                    // Mark the neighbor as visited and add it to the queue with its new path.\n                    visited.add(neighbor);\n                    queue.addLast(new PathNode<>(neighbor, newPath));\n                }\n            }\n        }\n        // If the queue becomes empty and the end vertex was not reached, no path exists.\n        return Collections.emptyList();\n    }\n\n    // Example usage (not part of the required solution, but for testing)\n    public static void main(String[] args) {\n        Map<String, List<String>> graph = new HashMap<>();\n        graph.put("A", Arrays.asList("B", "C"));\n        graph.put("B", Arrays.asList("A", "D", "E"));\n        graph.put("C", Arrays.asList("A", "F"));\n        graph.put("D", Collections.singletonList("B"));\n        graph.put("E", Arrays.asList("B", "F"));\n        graph.put("F", Arrays.asList("C", "E"));\n\n        System.out.println("BFS Traversal from A: " + bfsTraversal(graph, "A")); // Expected: [A, B, C, D, E, F]\n        System.out.println("Shortest path from A to F: " + bfsShortestPath(graph, "A", "F")); // Expected: [A, C, F]\n        System.out.println("Shortest path from D to F: " + bfsShortestPath(graph, "D", "F")); // Expected: [D, B, E, F]\n        System.out.println("Shortest path from A to A: " + bfsShortestPath(graph, "A", "A")); // Expected: [A]\n        System.out.println("Shortest path from A to Z: " + bfsShortestPath(graph, "A", "Z")); // Expected: []\n    }\n}',
  E'/**\n * @param {any, any} graph, start\n * @return {any}\n */\nfunction bfsTraversal(graph, start) {\n    // Your code here\n}',
  E'/**\n * Performs a Breadth-First Search (BFS) traversal on a graph starting from a given vertex.\n *\n * @param {Object.<string, string[]>} graph The graph represented as an adjacency list\n *                                         (object where keys are vertices and values are arrays of neighbors).\n * @param {string} start The starting vertex for the traversal.\n * @returns {string[]} A list of vertices in the order they were visited during the BFS traversal.\n */\nfunction bfsTraversal(graph, start) {\n    // Set to keep track of visited vertices to avoid cycles and redundant processing.\n    const visited = new Set();\n    // Queue for BFS, storing vertices to be processed.\n    const queue = [];\n    // List to store the result of the traversal.\n    const result = [];\n\n    // Start the BFS from the ''start'' vertex.\n    visited.add(start);\n    queue.push(start); // Add to the end of the queue\n\n    while (queue.length > 0) {\n        // Get the next vertex from the front of the queue.\n        const vertex = queue.shift(); // Remove from the front of the queue\n        result.push(vertex); // Add to the result list\n\n        // Iterate over all neighbors of the current vertex.\n        // Use `graph[vertex] || []` to handle cases where a vertex might not have any neighbors\n        // or might not be explicitly a key in the graph object, returning an empty array.\n        for (const neighbor of (graph[vertex] || [])) {\n            // If the neighbor has not been visited yet, mark it as visited and add it to the queue.\n            if (!visited.has(neighbor)) {\n                visited.add(neighbor);\n                queue.push(neighbor);\n            }\n        }\n    }\n    return result;\n}\n\n/**\n * Finds the shortest path between two vertices in an unweighted graph using BFS.\n *\n * @param {Object.<string, string[]>} graph The graph represented as an adjacency list.\n * @param {string} start The starting vertex.\n * @param {string} end The target vertex.\n * @returns {string[]} An array of vertices representing the shortest path from start to end,\n *                     or an empty array if no path exists.\n */\nfunction bfsShortestPath(graph, start, end) {\n    // If start and end are the same, the path is just the start vertex.\n    if (start === end) {\n        return [start];\n    }\n\n    // Set to keep track of visited vertices to avoid cycles and redundant processing.\n    // This set tracks only vertices, not paths.\n    const visited = new Set();\n    // Queue for BFS, storing objects with ''vertex'' and ''path'' properties.\n    const queue = [];\n\n    // Start the BFS from the ''start'' vertex.\n    visited.add(start);\n    // Initialize the queue with the start vertex and its initial path.\n    queue.push({ vertex: start, path: [start] });\n\n    while (queue.length > 0) {\n        // Get the next object (vertex and its path) from the front of the queue.\n        const { vertex, path } = queue.shift();\n\n        // Iterate over all neighbors of the current vertex.\n        for (const neighbor of (graph[vertex] || [])) {\n            // If the neighbor has not been visited yet.\n            if (!visited.has(neighbor)) {\n                // Create a new path by extending the current path.\n                // Using spread operator `...path` creates a new array copy.\n                const newPath = [...path, neighbor];\n\n                // If the neighbor is the target ''end'' vertex, we found the shortest path.\n                if (neighbor === end) {\n                    return newPath;\n                }\n\n                // Mark the neighbor as visited and add it to the queue with its new path.\n                visited.add(neighbor);\n                queue.push({ vertex: neighbor, path: newPath });\n            }\n        }\n    }\n    // If the queue becomes empty and the end vertex was not reached, no path exists.\n    return [];\n}\n\n// Example usage (not part of the required solution, but for testing)\n// const graph = {\n//     ''A'': [''B'', ''C''],\n//     ''B'': [''A'', ''D'', ''E''],\n//     ''C'': [''A'', ''F''],\n//     ''D'': [''B''],\n//     ''E'': [''B'', ''F''],\n//     ''F'': [''C'', ''E'']\n// };\n// console.log("BFS Traversal from A:", bfsTraversal(graph, ''A'')); // Expected: [''A'', ''B'', ''C'', ''D'', ''E'', ''F'']\n// console.log("Shortest path from A to F:", bfsShortestPath(graph, ''A'', ''F'')); // Expected: [''A'', ''C'', ''F'']\n// console.log("Shortest path from D to F:", bfsShortestPath(graph, ''D'', ''F'')); // Expected: [''D'', ''B'', ''E'', ''F'']\n// console.log("Shortest path from A to A:", bfsShortestPath(graph, ''A'', ''A'')); // Expected: [''A'']\n// console.log("Shortest path from A to Z:", bfsShortestPath(graph, ''A'', ''Z'')); // Expected: []',
  ARRAY['graphs'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'uber-sde2', 'databricks-swe'],
  'graphs',
  '[{"input":"bfs_traversal(graph, ''A'')","expected_output":"[''A'', ''B'', ''C'', ''D'', ''E'', ''F'']"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
  description = EXCLUDED.description,
  constraints = EXCLUDED.constraints,
  examples = EXCLUDED.examples,
  function_name = EXCLUDED.function_name,
  starter_code_python = EXCLUDED.starter_code_python,
  solution_code_python = EXCLUDED.solution_code_python,
  starter_code_java = EXCLUDED.starter_code_java,
  solution_code_java = EXCLUDED.solution_code_java,
  starter_code_js = EXCLUDED.starter_code_js,
  solution_code_js = EXCLUDED.solution_code_js,
  topics = EXCLUDED.topics,
  company_tags = EXCLUDED.company_tags,
  pattern = EXCLUDED.pattern,
  test_cases_visible = EXCLUDED.test_cases_visible,
