INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dsa-graph-dfs',
  'Depth-First Search',
  'medium',
  'Depth-First Search (DFS)

DFS explores a graph by going **as deep as possible** along each branch before backtracking. It uses a **stack** (or recursion).

*Numbers show DFS visit order -- goes deep (A->B->D) before backtracking to E, then C->F.*

Properties

- Time: O(V + E)
- Space: O(V) for the stack and visited set
- Does NOT guarantee shortest path',
  '',
  '[{"input":"graph, ''A''","output":"One valid output: [''A'', ''B'', ''D'', ''E'', ''F'', ''C'']"}]'::jsonb,
  'dfs_recursive',
  E'def dfs_recursive(graph, start, visited=None):\n    # TODO: Return list of vertices in DFS order (recursive)\n    pass\n\ndef dfs_iterative(graph, start):\n    # TODO: Return list of vertices in DFS order (iterative with stack)\n    pass\n\ndef has_cycle(graph):\n    # TODO: Detect cycle in a directed graph\n    # graph is a dict of vertex -> list of neighbors (directed)\n    pass\n\ngraph = {\n    ''A'': [''B'', ''C''],\n    ''B'': [''A'', ''D'', ''E''],\n    ''C'': [''A'', ''F''],\n    ''D'': [''B''],\n    ''E'': [''B'', ''F''],\n    ''F'': [''C'', ''E'']\n}\n# One valid output: [''A'', ''B'', ''D'', ''E'', ''F'', ''C'']\n# One valid output: [''A'', ''C'', ''F'', ''E'', ''B'', ''D'']\ndag = {''A'': [''B'', ''C''], ''B'': [''D''], ''C'': [''D''], ''D'': []}\ncyclic = {''A'': [''B''], ''B'': [''C''], ''C'': [''A'']}',
  E'def dfs_recursive(graph, start, visited=None):\n    if visited is None:\n        visited = set()\n    visited.add(start)\n    result = [start]\n    for neighbor in graph.get(start, []):\n        if neighbor not in visited:\n            result.extend(dfs_recursive(graph, neighbor, visited))\n    return result\n\ndef dfs_iterative(graph, start):\n    visited = set()\n    stack = [start]\n    result = []\n    while stack:\n        vertex = stack.pop()\n        if vertex not in visited:\n            visited.add(vertex)\n            result.append(vertex)\n            for neighbor in reversed(graph.get(vertex, [])):\n                if neighbor not in visited:\n                    stack.append(neighbor)\n    return result\n\ndef has_cycle(graph):\n    WHITE, GRAY, BLACK = 0, 1, 2\n    color = {v: WHITE for v in graph}\n\n    def dfs(v):\n        color[v] = GRAY\n        for neighbor in graph.get(v, []):\n            if color.get(neighbor, WHITE) == GRAY:\n                return True\n            if color.get(neighbor, WHITE) == WHITE and dfs(neighbor):\n                return True\n        color[v] = BLACK\n        return False\n\n    for vertex in graph:\n        if color[vertex] == WHITE:\n            if dfs(vertex):\n                return True\n    return False\ngraph = {\n    ''A'': [''B'', ''C''],\n    ''B'': [''A'', ''D'', ''E''],\n    ''C'': [''A'', ''F''],\n    ''D'': [''B''],\n    ''E'': [''B'', ''F''],\n    ''F'': [''C'', ''E'']\n}\n# One valid output: [''A'', ''B'', ''D'', ''E'', ''F'', ''C'']\n# One valid output: [''A'', ''C'', ''F'', ''E'', ''B'', ''D'']\ndag = {''A'': [''B'', ''C''], ''B'': [''D''], ''C'': [''D''], ''D'': []}\ncyclic = {''A'': [''B''], ''B'': [''C''], ''C'': [''A'']}',
  E'class Solution {\n    public Object dfsRecursive(Object graph, Object start, Object visited) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.*;\n\nclass Solution {\n\n    /**\n     * Performs a Depth-First Search (DFS) recursively starting from a given node.\n     *\n     * @param graph The graph represented as an adjacency list (Map from node to list of its neighbors).\n     * @param start The starting node for the DFS.\n     * @param <T> The type of the nodes in the graph.\n     * @return A list of nodes in the order they were visited during the DFS.\n     */\n    public static <T> List<T> dfsRecursive(Map<T, List<T>> graph, T start) {\n        Set<T> visited = new HashSet<>();\n        return dfsRecursiveHelper(graph, start, visited);\n    }\n\n    /**\n     * Helper method for recursive DFS.\n     *\n     * @param graph The graph.\n     * @param current The current node being visited.\n     * @param visited A set of already visited nodes to prevent cycles and redundant visits.\n     * @param <T> The type of the nodes.\n     * @return A list of nodes visited from ''current'' onwards.\n     */\n    private static <T> List<T> dfsRecursiveHelper(Map<T, List<T>> graph, T current, Set<T> visited) {\n        visited.add(current);\n        List<T> result = new ArrayList<>();\n        result.add(current);\n\n        // Get neighbors, handling cases where ''current'' might not be a key in the graph\n        List<T> neighbors = graph.getOrDefault(current, Collections.emptyList());\n        for (T neighbor : neighbors) {\n            if (!visited.contains(neighbor)) {\n                result.addAll(dfsRecursiveHelper(graph, neighbor, visited));\n            }\n        }\n        return result;\n    }\n\n    /**\n     * Performs an iterative Depth-First Search (DFS) starting from a given node.\n     *\n     * @param graph The graph represented as an adjacency list (Map from node to list of its neighbors).\n     * @param start The starting node for the DFS.\n     * @param <T> The type of the nodes in the graph.\n     * @return A list of nodes in the order they were visited during the DFS.\n     */\n    public static <T> List<T> dfsIterative(Map<T, List<T>> graph, T start) {\n        Set<T> visited = new HashSet<>();\n        Deque<T> stack = new ArrayDeque<>(); // Use ArrayDeque as a stack for LIFO behavior\n        List<T> result = new ArrayList<>();\n\n        stack.push(start); // Add start to stack\n\n        while (!stack.isEmpty()) {\n            T vertex = stack.pop(); // Get vertex from stack\n\n            if (!visited.contains(vertex)) {\n                visited.add(vertex);\n                result.add(vertex);\n\n                // Get neighbors. To mimic Python''s `reversed` behavior for DFS\n                // (where the first neighbor in the list is processed first),\n                // we push neighbors onto the stack in reverse order of their appearance in the adjacency list.\n                List<T> neighbors = graph.getOrDefault(vertex, Collections.emptyList());\n                for (int i = neighbors.size() - 1; i >= 0; i--) {\n                    T neighbor = neighbors.get(i);\n                    if (!visited.contains(neighbor)) {\n                        stack.push(neighbor);\n                    }\n                }\n            }\n        }\n        return result;\n    }\n\n    /**\n     * Enum to represent the color (state) of a node during cycle detection.\n     * WHITE: Node has not been visited yet.\n     * GRAY: Node is currently being visited (in the recursion stack).\n     * BLACK: Node has been completely visited (all its descendants processed).\n     */\n    private enum Color {\n        WHITE, GRAY, BLACK\n    }\n\n    /**\n     * Checks if a directed graph contains a cycle using DFS.\n     *\n     * @param graph The directed graph represented as an adjacency list.\n     * @param <T> The type of the nodes in the graph.\n     * @return true if a cycle is detected, false otherwise.\n     */\n    public static <T> boolean hasCycle(Map<T, List<T>> graph) {\n        Map<T, Color> color = new HashMap<>();\n        // Initialize all vertices that are keys in the graph to WHITE.\n        // Vertices that only appear as neighbors will be handled by getOrDefault.\n        for (T vertex : graph.keySet()) {\n            color.put(vertex, Color.WHITE);\n        }\n\n        // Iterate over all vertices to ensure all disconnected components are checked\n        for (T vertex : graph.keySet()) {\n            // Only start DFS from unvisited (WHITE) nodes\n            if (color.get(vertex) == Color.WHITE) {\n                if (dfsCycleCheck(graph, vertex, color)) {\n                    return true; // Cycle found\n                }\n            }\n        }\n        return false; // No cycle found after checking all components\n    }\n\n    /**\n     * Helper method for DFS-based cycle detection.\n     *\n     * @param graph The graph.\n     * @param current The current node being visited.\n     * @param color A map storing the color (state) of each node.\n     * @param <T> The type of the nodes.\n     * @return true if a cycle is detected from ''current'' onwards, false otherwise.\n     */\n    private static <T> boolean dfsCycleCheck(Map<T, List<T>> graph, T current, Map<T, Color> color) {\n        color.put(current, Color.GRAY); // Mark current node as GRAY (visiting)\n\n        List<T> neighbors = graph.getOrDefault(current, Collections.emptyList());\n        for (T neighbor : neighbors) {\n            // Get neighbor''s color, defaulting to WHITE if not yet in the map\n            Color neighborColor = color.getOrDefault(neighbor, Color.WHITE);\n\n            if (neighborColor == Color.GRAY) {\n                return true; // Back-edge detected: neighbor is in current recursion stack, so a cycle exists.\n            }\n            if (neighborColor == Color.WHITE) {\n                // If neighbor is unvisited, recurse\n                if (dfsCycleCheck(graph, neighbor, color)) {\n                    return true; // Cycle found in a deeper recursion\n                }\n            }\n            // If neighborColor is BLACK, it means the neighbor and its subtree have been fully processed\n            // and no cycle was found through it, so we can ignore it.\n        }\n        color.put(current, Color.BLACK); // Mark current node as BLACK (finished visiting)\n        return false; // No cycle found from this node\n    }\n}',
  E'/**\n * @param {any, any, any} graph, start, visited\n * @return {any}\n */\nfunction dfsRecursive(graph, start, visited) {\n    // Your code here\n}',
  E'/**\n * Performs a Depth-First Search (DFS) recursively starting from a given node.\n *\n * @param {Map<any, any[]>} graph The graph represented as an adjacency list (Map from node to array of its neighbors).\n * @param {any} start The starting node for the DFS.\n * @param {Set<any>} [visited=new Set()] A set of already visited nodes to prevent cycles and redundant visits.\n * @returns {any[]} A list of nodes in the order they were visited during the DFS.\n */\nfunction dfsRecursive(graph, start, visited = new Set()) {\n    visited.add(start);\n    let result = [start];\n\n    // Get neighbors, handling cases where ''start'' might not be a key in the graph\n    const neighbors = graph.get(start) || [];\n    for (const neighbor of neighbors) {\n        if (!visited.has(neighbor)) {\n            result.push(...dfsRecursive(graph, neighbor, visited));\n        }\n    }\n    return result;\n}\n\n/**\n * Performs an iterative Depth-First Search (DFS) starting from a given node.\n *\n * @param {Map<any, any[]>} graph The graph represented as an adjacency list (Map from node to array of its neighbors).\n * @param {any} start The starting node for the DFS.\n * @returns {any[]} A list of nodes in the order they were visited during the DFS.\n */\nfunction dfsIterative(graph, start) {\n    const visited = new Set();\n    const stack = [start]; // Use an array as a stack for LIFO behavior\n    const result = [];\n\n    while (stack.length > 0) {\n        const vertex = stack.pop(); // Get vertex from stack\n\n        if (!visited.has(vertex)) {\n            visited.add(vertex);\n            result.push(vertex);\n\n            // Get neighbors. To mimic Python''s `reversed` behavior for DFS\n            // (where the first neighbor in the list is processed first),\n            // we push neighbors onto the stack in reverse order of their appearance in the adjacency list.\n            const neighbors = graph.get(vertex) || [];\n            for (let i = neighbors.length - 1; i >= 0; i--) {\n                const neighbor = neighbors[i];\n                if (!visited.has(neighbor)) {\n                    stack.push(neighbor);\n                }\n            }\n        }\n    }\n    return result;\n}\n\n/**\n * Checks if a directed graph contains a cycle using DFS.\n *\n * @param {Map<any, any[]>} graph The directed graph represented as an adjacency list.\n * @returns {boolean} true if a cycle is detected, false otherwise.\n */\nfunction hasCycle(graph) {\n    // Define node states (colors)\n    const WHITE = 0; // Node has not been visited yet\n    const GRAY = 1;  // Node is currently being visited (in the recursion stack)\n    const BLACK = 2; // Node has been completely visited (all its descendants processed)\n\n    const color = new Map();\n    // Initialize all vertices that are keys in the graph to WHITE.\n    // Vertices that only appear as neighbors will be handled by the `?? WHITE` operator.\n    for (const vertex of graph.keys()) {\n        color.set(vertex, WHITE);\n    }\n\n    /**\n     * Helper function for DFS-based cycle detection.\n     * @param {any} current The current node being visited.\n     * @returns {boolean} true if a cycle is detected from ''current'' onwards, false otherwise.\n     */\n    function dfsCycleCheck(current) {\n        color.set(current, GRAY); // Mark current node as GRAY (visiting)\n\n        const neighbors = graph.get(current) || [];\n        for (const neighbor of neighbors) {\n            // Get neighbor''s color, defaulting to WHITE if not yet in the map\n            const neighborColor = color.get(neighbor) ?? WHITE;\n\n            if (neighborColor === GRAY) {\n                return true; // Back-edge detected: neighbor is in current recursion stack, so a cycle exists.\n            }\n            if (neighborColor === WHITE) {\n                // If neighbor is unvisited, recurse\n                if (dfsCycleCheck(neighbor)) {\n                    return true; // Cycle found in a deeper recursion\n                }\n            }\n            // If neighborColor is BLACK, it means the neighbor and its subtree have been fully processed\n            // and no cycle was found through it, so we can ignore it.\n        }\n        color.set(current, BLACK); // Mark current node as BLACK (finished visiting)\n        return false; // No cycle found from this node\n    }\n\n    // Iterate over all vertices to ensure all disconnected components are checked\n    for (const vertex of graph.keys()) {\n        // Only start DFS from unvisited (WHITE) nodes\n        if (color.get(vertex) === WHITE) {\n            if (dfsCycleCheck(vertex)) {\n                return true; // Cycle found\n            }\n        }\n    }\n    return false; // No cycle found after checking all components\n}',
  ARRAY['graphs'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'uber-sde2', 'databricks-swe'],
  'graphs',
  '[{"input":"dfs_recursive(graph, ''A'')","expected_output":"One valid output: [''A'', ''B'', ''D'', ''E'', ''F'', ''C'']"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
