INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dsa-shortest-path',
  'Shortest Path (Dijkstra)',
  'medium',
  'Shortest Path — Dijkstra''s Algorithm

**Dijkstra''s algorithm** finds the shortest path from a source to all other vertices in a **weighted graph with non-negative edge weights**.',
  '',
  '[{"input":"graph, ''A''","output":"{''A'': 0, ''B'': 4, ''C'': 2, ''D'': 6, ''E'': 5, ''F'': 7}"}]'::jsonb,
  'dijkstra',
  E'import heapq\ndef dijkstra(graph, start):\n    # TODO: Return dict of shortest distances from start to all vertices\n    # graph format: {vertex: [(neighbor, weight), ...]}\n    pass\n\ndef shortest_path(graph, start, end):\n    # TODO: Return (distance, path) for shortest path from start to end\n    pass\n\ngraph = {\n    ''A'': [(''B'', 4), (''C'', 2)],\n    ''B'': [(''A'', 4), (''D'', 3), (''E'', 1)],\n    ''C'': [(''A'', 2), (''D'', 4), (''F'', 5)],\n    ''D'': [(''B'', 3), (''C'', 4), (''E'', 2)],\n    ''E'': [(''B'', 1), (''D'', 2), (''F'', 3)],\n    ''F'': [(''C'', 5), (''E'', 3)]\n}\n# Expected: {''A'': 0, ''B'': 4, ''C'': 2, ''D'': 6, ''E'': 5, ''F'': 7}\ndist, path = shortest_path(graph, ''A'', ''F'')',
  E'import heapq\ndef dijkstra(graph, start):\n    distances = {v: float(''inf'') for v in graph}\n    distances[start] = 0\n    pq = [(0, start)]\n\n    while pq:\n        dist, vertex = heapq.heappop(pq)\n        if dist > distances[vertex]:\n            continue\n        for neighbor, weight in graph.get(vertex, []):\n            new_dist = dist + weight\n            if new_dist < distances[neighbor]:\n                distances[neighbor] = new_dist\n                heapq.heappush(pq, (new_dist, neighbor))\n    return distances\ndef shortest_path(graph, start, end):\n    distances = {v: float(''inf'') for v in graph}\n    distances[start] = 0\n    previous = {v: None for v in graph}\n    pq = [(0, start)]\n\n    while pq:\n        dist, vertex = heapq.heappop(pq)\n        if vertex == end:\n            break\n        if dist > distances[vertex]:\n            continue\n        for neighbor, weight in graph.get(vertex, []):\n            new_dist = dist + weight\n            if new_dist < distances[neighbor]:\n                distances[neighbor] = new_dist\n                previous[neighbor] = vertex\n                heapq.heappush(pq, (new_dist, neighbor))\n    # Reconstruct path\n    path = []\n    curr = end\n    while curr is not None:\n        path.append(curr)\n        curr = previous[curr]\n    path.reverse()\n    if distances[end] == float(''inf''):\n        return float(''inf''), []\n    return distances[end], path\ngraph = {\n    ''A'': [(''B'', 4), (''C'', 2)],\n    ''B'': [(''A'', 4), (''D'', 3), (''E'', 1)],\n    ''C'': [(''A'', 2), (''D'', 4), (''F'', 5)],\n    ''D'': [(''B'', 3), (''C'', 4), (''E'', 2)],\n    ''E'': [(''B'', 1), (''D'', 2), (''F'', 3)],\n    ''F'': [(''C'', 5), (''E'', 3)]\n}\n# Expected: {''A'': 0, ''B'': 4, ''C'': 2, ''D'': 6, ''E'': 5, ''F'': 7}\ndist, path = shortest_path(graph, ''A'', ''F'')',
  E'class Solution {\n    public Object dijkstra(Object graph, Object start) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.*;\n\nclass Solution {\n\n    // Helper class for edges in the graph\n    static class Edge<Type> {\n        Type neighbor;\n        int weight;\n\n        Edge(Type neighbor, int weight) {\n            this.neighbor = neighbor;\n            this.weight = weight;\n        }\n    }\n\n    // Helper class for elements in the priority queue\n    static class NodeDistance<Type> implements Comparable<NodeDistance<Type>> {\n        Type node;\n        double distance;\n\n        NodeDistance(Type node, double distance) {\n            this.node = node;\n            this.distance = distance;\n        }\n\n        @Override\n        public int compareTo(NodeDistance<Type> other) {\n            return Double.compare(this.distance, other.distance);\n        }\n    }\n\n    // Helper class for the result of shortest_path\n    static class ShortestPathResult<Type> {\n        double distance;\n        List<Type> path;\n\n        ShortestPathResult(double distance, List<Type> path) {\n            this.distance = distance;\n            this.path = path;\n        }\n    }\n\n    /**\n     * Implements Dijkstra''s algorithm to find the shortest distances from a start node\n     * to all other reachable nodes in a graph.\n     *\n     * @param graph A map representing the graph where keys are nodes and values are\n     *              lists of Edge objects (neighbor, weight).\n     * @param start The starting node for the algorithm.\n     * @param <Type> The type of the nodes in the graph (e.g., String, Integer).\n     * @return A map where keys are nodes and values are their shortest distances\n     *         from the start node.\n     */\n    public static <Type> Map<Type, Double> dijkstra(Map<Type, List<Edge<Type>>> graph, Type start) {\n        Map<Type, Double> distances = new HashMap<>();\n        \n        // Collect all unique nodes from the graph (keys and neighbors)\n        Set<Type> allNodes = new HashSet<>(graph.keySet());\n        for (List<Edge<Type>> edges : graph.values()) {\n            for (Edge<Type> edge : edges) {\n                allNodes.add(edge.neighbor);\n            }\n        }\n\n        for (Type v : allNodes) {\n            distances.put(v, Double.POSITIVE_INFINITY);\n        }\n        distances.put(start, 0.0);\n\n        PriorityQueue<NodeDistance<Type>> pq = new PriorityQueue<>();\n        pq.add(new NodeDistance<>(start, 0.0));\n\n        while (!pq.isEmpty()) {\n            NodeDistance<Type> current = pq.poll();\n            double dist = current.distance;\n            Type vertex = current.node;\n\n            // If we found a shorter path to this vertex already, skip\n            if (dist > distances.getOrDefault(vertex, Double.POSITIVE_INFINITY)) {\n                continue;\n            }\n\n            // Iterate over neighbors\n            for (Edge<Type> edge : graph.getOrDefault(vertex, Collections.emptyList())) {\n                Type neighbor = edge.neighbor;\n                int weight = edge.weight;\n                double newDist = dist + weight;\n\n                if (newDist < distances.getOrDefault(neighbor, Double.POSITIVE_INFINITY)) {\n                    distances.put(neighbor, newDist);\n                    pq.add(new NodeDistance<>(neighbor, newDist));\n                }\n            }\n        }\n        return distances;\n    }\n\n    /**\n     * Implements Dijkstra''s algorithm to find the shortest distance and path\n     * from a start node to an end node in a graph.\n     *\n     * @param graph A map representing the graph where keys are nodes and values are\n     *              lists of Edge objects (neighbor, weight).\n     * @param start The starting node for the algorithm.\n     * @param end The target node for which to find the shortest path.\n     * @param <Type> The type of the nodes in the graph (e.g., String, Integer).\n     * @return A ShortestPathResult object containing the shortest distance and the path\n     *         as a list of nodes. Returns Double.POSITIVE_INFINITY and an empty list\n     *         if the end node is unreachable.\n     */\n    public static <Type> ShortestPathResult<Type> shortest_path(Map<Type, List<Edge<Type>>> graph, Type start, Type end) {\n        Map<Type, Double> distances = new HashMap<>();\n        Map<Type, Type> previous = new HashMap<>();\n\n        // Collect all unique nodes from the graph (keys and neighbors)\n        Set<Type> allNodes = new HashSet<>(graph.keySet());\n        for (List<Edge<Type>> edges : graph.values()) {\n            for (Edge<Type> edge : edges) {\n                allNodes.add(edge.neighbor);\n            }\n        }\n\n        for (Type v : allNodes) {\n            distances.put(v, Double.POSITIVE_INFINITY);\n            previous.put(v, null); // Initialize previous nodes to null\n        }\n\n        distances.put(start, 0.0);\n        PriorityQueue<NodeDistance<Type>> pq = new PriorityQueue<>();\n        pq.add(new NodeDistance<>(start, 0.0));\n\n        while (!pq.isEmpty()) {\n            NodeDistance<Type> current = pq.poll();\n            double dist = current.distance;\n            Type vertex = current.node;\n\n            if (vertex.equals(end)) {\n                break; // Found the shortest path to the end node\n            }\n\n            // If we found a shorter path to this vertex already, skip\n            if (dist > distances.getOrDefault(vertex, Double.POSITIVE_INFINITY)) {\n                continue;\n            }\n\n            for (Edge<Type> edge : graph.getOrDefault(vertex, Collections.emptyList())) {\n                Type neighbor = edge.neighbor;\n                int weight = edge.weight;\n                double newDist = dist + weight;\n\n                if (newDist < distances.getOrDefault(neighbor, Double.POSITIVE_INFINITY)) {\n                    distances.put(neighbor, newDist);\n                    previous.put(neighbor, vertex);\n                    pq.add(new NodeDistance<>(neighbor, newDist));\n                }\n            }\n        }\n\n        // Reconstruct path\n        List<Type> path = new ArrayList<>();\n        double finalDistance = distances.getOrDefault(end, Double.POSITIVE_INFINITY);\n\n        if (finalDistance == Double.POSITIVE_INFINITY) {\n            return new ShortestPathResult<>(Double.POSITIVE_INFINITY, Collections.emptyList());\n        }\n\n        Type curr = end;\n        while (curr != null) {\n            path.add(curr);\n            curr = previous.get(curr);\n        }\n        Collections.reverse(path);\n\n        return new ShortestPathResult<>(finalDistance, path);\n    }\n}',
  E'/**\n * @param {any, any} graph, start\n * @return {any}\n */\nfunction dijkstra(graph, start) {\n    // Your code here\n}',
  E'// Helper class for a Min-Priority Queue\nclass MinPriorityQueue {\n    constructor() {\n        this.heap = [];\n    }\n\n    // Pushes an item onto the heap. Item is expected to be [priority, value].\n    push(item) {\n        this.heap.push(item);\n        this._bubbleUp();\n    }\n\n    // Removes and returns the item with the lowest priority.\n    pop() {\n        if (this.isEmpty()) return undefined;\n        const min = this.heap[0];\n        const last = this.heap.pop();\n        if (!this.isEmpty()) {\n            this.heap[0] = last;\n            this._sinkDown();\n        }\n        return min;\n    }\n\n    // Returns true if the queue is empty, false otherwise.\n    isEmpty() {\n        return this.heap.length === 0;\n    }\n\n    // Helper to maintain heap property after push.\n    _bubbleUp() {\n        let index = this.heap.length - 1;\n        while (index > 0) {\n            let parentIndex = Math.floor((index - 1) / 2);\n            // Compare by priority (first element of the item tuple)\n            if (this.heap[parentIndex][0] > this.heap[index][0]) {\n                [this.heap[parentIndex], this.heap[index]] = [this.heap[index], this.heap[parentIndex]];\n                index = parentIndex;\n            } else {\n                break;\n            }\n        }\n    }\n\n    // Helper to maintain heap property after pop.\n    _sinkDown() {\n        let index = 0;\n        const length = this.heap.length;\n        const element = this.heap[0]; // The element that just moved to the root\n        while (true) {\n            let leftChildIndex = 2 * index + 1;\n            let rightChildIndex = 2 * index + 2;\n            let swap = null;\n            let leftChild, rightChild;\n\n            if (leftChildIndex < length) {\n                leftChild = this.heap[leftChildIndex];\n                if (leftChild[0] < element[0]) {\n                    swap = leftChildIndex;\n                }\n            }\n            if (rightChildIndex < length) {\n                rightChild = this.heap[rightChildIndex];\n                // If right child exists and is smaller than current element,\n                // AND (either no left child or right child is smaller than left child)\n                if (\n                    (swap === null && rightChild[0] < element[0]) ||\n                    (swap !== null && rightChild[0] < leftChild[0])\n                ) {\n                    swap = rightChildIndex;\n                }\n            }\n            if (swap === null) break; // No swap needed, element is in correct position\n            [this.heap[index], this.heap[swap]] = [this.heap[swap], this.heap[index]];\n            index = swap;\n        }\n    }\n}\n\n/**\n * Implements Dijkstra''s algorithm to find the shortest distances from a start node\n * to all other reachable nodes in a graph.\n *\n * @param {Object.<string, Array<[string, number]>>} graph A dictionary-like object\n *        where keys are node names (strings) and values are arrays of [neighbor, weight] tuples.\n * @param {string} start The starting node for the algorithm.\n * @returns {Object.<string, number>} A dictionary-like object where keys are nodes\n *          and values are their shortest distances from the start node.\n */\nfunction dijkstra(graph, start) {\n    const distances = {};\n    const pq = new MinPriorityQueue();\n\n    // Collect all unique nodes first\n    const allNodes = new Set();\n    for (const vertex in graph) {\n        allNodes.add(vertex);\n        for (const [neighbor, weight] of graph[vertex]) {\n            allNodes.add(neighbor);\n        }\n    }\n\n    // Initialize distances for all nodes\n    for (const node of allNodes) {\n        distances[node] = Infinity;\n    }\n\n    distances[start] = 0;\n    pq.push([0, start]); // [distance, vertex]\n\n    while (!pq.isEmpty()) {\n        const [dist, vertex] = pq.pop();\n\n        // If we found a shorter path to this vertex already, skip\n        if (dist > distances[vertex]) {\n            continue;\n        }\n\n        // Iterate over neighbors\n        // graph[vertex] might be undefined if a node has no outgoing edges\n        // or if it''s a target node not explicitly listed as a key.\n        // The `|| []` handles the case where graph[vertex] is undefined.\n        for (const [neighbor, weight] of (graph[vertex] || [])) {\n            const newDist = dist + weight;\n\n            if (newDist < distances[neighbor]) {\n                distances[neighbor] = newDist;\n                pq.push([newDist, neighbor]);\n            }\n        }\n    }\n    return distances;\n}\n\n/**\n * Implements Dijkstra''s algorithm to find the shortest distance and path\n * from a start node to an end node in a graph.\n *\n * @param {Object.<string, Array<[string, number]>>} graph A dictionary-like object\n *        where keys are node names (strings) and values are arrays of [neighbor, weight] tuples.\n * @param {string} start The starting node for the algorithm.\n * @param {string} end The target node for which to find the shortest path.\n * @returns {[number, Array<string>]} A tuple containing the shortest distance and the path\n *          as an array of node names. Returns [Infinity, []] if the end node is unreachable.\n */\nfunction shortest_path(graph, start, end) {\n    const distances = {};\n    const previous = {};\n    const pq = new MinPriorityQueue();\n\n    // Collect all unique nodes first\n    const allNodes = new Set();\n    for (const vertex in graph) {\n        allNodes.add(vertex);\n        for (const [neighbor, weight] of graph[vertex]) {\n            allNodes.add(neighbor);\n        }\n    }\n\n    // Initialize distances and previous for all nodes\n    for (const node of allNodes) {\n        distances[node] = Infinity;\n        previous[node] = null;\n    }\n\n    distances[start] = 0;\n    pq.push([0, start]); // [distance, vertex]\n\n    while (!pq.isEmpty()) {\n        const [dist, vertex] = pq.pop();\n\n        if (vertex === end) {\n            break; // Found the shortest path to the end node\n        }\n\n        // If we found a shorter path to this vertex already, skip\n        if (dist > distances[vertex]) {\n            continue;\n        }\n\n        for (const [neighbor, weight] of (graph[vertex] || [])) {\n            const newDist = dist + weight;\n\n            if (newDist < distances[neighbor]) {\n                distances[neighbor] = newDist;\n                previous[neighbor] = vertex;\n                pq.push([newDist, neighbor]);\n            }\n        }\n    }\n\n    // Reconstruct path\n    const path = [];\n    let curr = end;\n    while (curr !== null && curr !== undefined) {\n        path.push(curr);\n        curr = previous[curr];\n    }\n    path.reverse();\n\n    const finalDistance = distances[end];\n    if (finalDistance === Infinity) {\n        return [Infinity, []];\n    }\n\n    return [finalDistance, path];\n}',
  ARRAY['graphs'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'uber-sde2', 'databricks-swe'],
