INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dsa-dp-knapsack-lcs',
  'Knapsack & LCS',
  'medium',
  'Classic DP: 0/1 Knapsack & Longest Common Subsequence

Problem 1: 0/1 Knapsack

Given items with weights and values, and a knapsack capacity, find the maximum value you can carry. Each item can be used at most once.

**Recurrence:** `dp[i][w] = max(dp[i-1][w], dp[i-1][w-weight[i]] + value[i])`

Problem 2: Longest Common Subsequence (LCS)

Find the length of the longest subsequence common to two strings.

**Recurrence:**
- If chars match: `dp[i][j] = dp[i-1][j-1] + 1`
- If not: `dp[i][j] = max(dp[i-1][j], dp[i][j-1])`',
  '',
  '[{"input":"[1, 3, 4, 5], [1, 4, 5, 7], 7","output":"9"},{"input":"[2, 3, 4, 5], [3, 4, 5, 6], 5","output":"7"},{"input":"[10], [100], 5","output":"0"}]'::jsonb,
  'knapsack',
  E'def knapsack(weights, values, capacity):\n    # TODO: Return maximum value achievable\n    pass\n\ndef lcs(s1, s2):\n    # TODO: Return length of longest common subsequence\n    pass\n\ndef lcs_string(s1, s2):\n    # TODO: Return the actual LCS string (not just length)\n    pass',
  E'def knapsack(weights, values, capacity):\n    n = len(weights)\n    dp = [[0] * (capacity + 1) for _ in range(n + 1)]\n    for i in range(1, n + 1):\n        for w in range(capacity + 1):\n            dp[i][w] = dp[i - 1][w]\n            if weights[i - 1] <= w:\n                dp[i][w] = max(dp[i][w], dp[i - 1][w - weights[i - 1]] + values[i - 1])\n    return dp[n][capacity]\n\ndef lcs(s1, s2):\n    m, n = len(s1), len(s2)\n    dp = [[0] * (n + 1) for _ in range(m + 1)]\n    for i in range(1, m + 1):\n        for j in range(1, n + 1):\n            if s1[i - 1] == s2[j - 1]:\n                dp[i][j] = dp[i - 1][j - 1] + 1\n            else:\n                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])\n    return dp[m][n]\n\ndef lcs_string(s1, s2):\n    m, n = len(s1), len(s2)\n    dp = [[0] * (n + 1) for _ in range(m + 1)]\n    for i in range(1, m + 1):\n        for j in range(1, n + 1):\n            if s1[i - 1] == s2[j - 1]:\n                dp[i][j] = dp[i - 1][j - 1] + 1\n            else:\n                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])\n    # Backtrack to find the string\n    result = []\n    i, j = m, n\n    while i > 0 and j > 0:\n        if s1[i - 1] == s2[j - 1]:\n            result.append(s1[i - 1])\n            i -= 1\n            j -= 1\n        elif dp[i - 1][j] > dp[i][j - 1]:\n            i -= 1\n        else:\n            j -= 1\n    return ''''.join(reversed(result))',
  E'class Solution {\n    public Object knapsack(Object weights, Object values, int capacity) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayList; // Required for lcsString\nimport java.util.Collections; // Required for lcsString\nimport java.util.List; // Required for lcsString\n\nclass Solution {\n    public static int knapsack(int[] weights, int[] values, int capacity) {\n        int n = weights.length;\n        int[][] dp = new int[n + 1][capacity + 1];\n\n        for (int i = 1; i <= n; i++) {\n            for (int w = 0; w <= capacity; w++) {\n                dp[i][w] = dp[i - 1][w]; // Exclude item i\n                if (weights[i - 1] <= w) {\n                    dp[i][w] = Math.max(dp[i][w], dp[i - 1][w - weights[i - 1]] + values[i - 1]);\n                }\n            }\n        }\n        return dp[n][capacity];\n    }\n\n    public static int lcs(String s1, String s2) {\n        int m = s1.length();\n        int n = s2.length();\n        int[][] dp = new int[m + 1][n + 1];\n\n        for (int i = 1; i <= m; i++) {\n            for (int j = 1; j <= n; j++) {\n                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {\n                    dp[i][j] = dp[i - 1][j - 1] + 1;\n                } else {\n                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);\n                }\n            }\n        }\n        return dp[m][n];\n    }\n\n    public static String lcsString(String s1, String s2) {\n        int m = s1.length();\n        int n = s2.length();\n        int[][] dp = new int[m + 1][n + 1];\n\n        for (int i = 1; i <= m; i++) {\n            for (int j = 1; j <= n; j++) {\n                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {\n                    dp[i][j] = dp[i - 1][j - 1] + 1;\n                } else {\n                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);\n                }\n            }\n        }\n\n        // Backtrack to find the string\n        List<Character> result = new ArrayList<>();\n        int i = m, j = n;\n        while (i > 0 && j > 0) {\n            if (s1.charAt(i - 1) == s2.charAt(j - 1)) {\n                result.add(s1.charAt(i - 1));\n                i--;\n                j--;\n            } else if (dp[i - 1][j] > dp[i][j - 1]) {\n                i--;\n            } else {\n                j--;\n            }\n        }\n        Collections.reverse(result);\n        StringBuilder sb = new StringBuilder(result.size());\n        for (char c : result) {\n            sb.append(c);\n        }\n        return sb.toString();\n    }\n}''''.join(reversed(result))\n    // \n    // \n    // \n    // \n}',
  E'/**\n * @param {any, any, any} weights, values, capacity\n * @return {any}\n */\nfunction knapsack(weights, values, capacity) {\n    // Your code here\n}',
  E'function knapsack(weights, values, capacity) {\n    const n = weights.length;\n    const dp = Array.from({ length: n + 1 }, () => new Array(capacity + 1).fill(0));\n\n    for (let i = 1; i <= n; i++) {\n        for (let w = 0; w <= capacity; w++) {\n            dp[i][w] = dp[i - 1][w]; // Exclude item i\n            if (weights[i - 1] <= w) {\n                dp[i][w] = Math.max(dp[i][w], dp[i - 1][w - weights[i - 1]] + values[i - 1]);\n            }\n        }\n    }\n    return dp[n][capacity];\n}\n\nfunction lcs(s1, s2) {\n    const m = s1.length;\n    const n = s2.length;\n    const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));\n\n    for (let i = 1; i <= m; i++) {\n        for (let j = 1; j <= n; j++) {\n            if (s1[i - 1] === s2[j - 1]) {\n                dp[i][j] = dp[i - 1][j - 1] + 1;\n            } else {\n                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);\n            }\n        }\n    }\n    return dp[m][n];\n}\n\nfunction lcsString(s1, s2) {\n    const m = s1.length;\n    const n = s2.length;\n    const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));\n\n    for (let i = 1; i <= m; i++) {\n        for (let j = 1; j <= n; j++) {\n            if (s1[i - 1] === s2[j - 1]) {\n                dp[i][j] = dp[i - 1][j - 1] + 1;\n            } else {\n                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);\n            }\n        }\n    }\n\n    // Backtrack to find the string\n    const result = [];\n    let i = m, j = n;\n    while (i > 0 && j > 0) {\n        if (s1[i - 1] === s2[j - 1]) {\n            result.push(s1[i - 1]);\n            i--;\n            j--;\n        } else if (dp[i - 1][j] > dp[i][j - 1]) {\n            i--;\n        } else {\n            j--;\n        }\n    }\n    return result.reverse().join(\'\');\n}',
  ARRAY['dynamic-programming'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'stripe-l2'],
  'dynamic-programming',
  '[{"input":"knapsack([1, 3, 4, 5], [1, 4, 5, 7], 7)","expected_output":"9"},{"input":"knapsack([2, 3, 4, 5], [3, 4, 5, 6], 5)","expected_output":"7"},{"input":"knapsack([10], [100], 5)","expected_output":"0"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
