INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dsa-dp-lis-edit-distance',
  'LIS & Edit Distance',
  'medium',
  'Classic DP: Longest Increasing Subsequence & Edit Distance

Problem 1: Longest Increasing Subsequence (LIS)

Find the length of the longest strictly increasing subsequence.

**O(n^2) approach:** `dp[i]` = length of LIS ending at index i.
For each j < i: if `arr[j] < arr[i]`, then `dp[i] = max(dp[i], dp[j] + 1)`

Problem 2: Edit Distance (Levenshtein Distance)

Find the minimum number of operations (insert, delete, replace) to transform one string into another.

**Recurrence:**
- If chars match: `dp[i][j] = dp[i-1][j-1]`
- If not: `dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])`
  - (delete, insert, replace)',
  '',
  '[{"input":"[10, 9, 2, 5, 3, 7, 101, 18]","output":"4"},{"input":"[0, 1, 0, 3, 2, 3]","output":"4"},{"input":"[7, 7, 7, 7]","output":"1"}]'::jsonb,
  'longest_increasing_subsequence',
  E'def longest_increasing_subsequence(arr):\n    # TODO: Return length of LIS\n    pass\n\ndef lis_sequence(arr):\n    # TODO: Return the actual LIS (not just length)\n    pass\n\ndef edit_distance(s1, s2):\n    # TODO: Return minimum edit distance\n    pass\n\n# Expected: 4\n# Expected: 4\n# Expected: 1\n# Expected: [2, 3, 7, 18] or [2, 5, 7, 18] or similar',
  E'def longest_increasing_subsequence(arr):\n    if not arr:\n        return 0\n    n = len(arr)\n    dp = [1] * n\n    for i in range(1, n):\n        for j in range(i):\n            if arr[j] < arr[i]:\n                dp[i] = max(dp[i], dp[j] + 1)\n    return max(dp)\n\ndef lis_sequence(arr):\n    if not arr:\n        return []\n    n = len(arr)\n    dp = [1] * n\n    parent = [-1] * n\n    for i in range(1, n):\n        for j in range(i):\n            if arr[j] < arr[i] and dp[j] + 1 > dp[i]:\n                dp[i] = dp[j] + 1\n                parent[i] = j\n    # Find the index of max LIS length\n    max_idx = 0\n    for i in range(n):\n        if dp[i] > dp[max_idx]:\n            max_idx = i\n    # Backtrack\n    result = []\n    idx = max_idx\n    while idx != -1:\n        result.append(arr[idx])\n        idx = parent[idx]\n    return list(reversed(result))\n\ndef edit_distance(s1, s2):\n    m, n = len(s1), len(s2)\n    dp = [[0] * (n + 1) for _ in range(m + 1)]\n    for i in range(m + 1):\n        dp[i][0] = i\n    for j in range(n + 1):\n        dp[0][j] = j\n    for i in range(1, m + 1):\n        for j in range(1, n + 1):\n            if s1[i - 1] == s2[j - 1]:\n                dp[i][j] = dp[i - 1][j - 1]\n            else:\n                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])\n    return dp[m][n]\n\n# Expected: 4\n# Expected: 4\n# Expected: 1\n# Expected: [2, 3, 7, 18] or similar',
  E'class Solution {\n    public Object longestIncreasingSubsequence(int[] arr) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayList; // Required for lisSequence\nimport java.util.Arrays; // Required for longestIncreasingSubsequence, lisSequence\nimport java.util.Collections; // Required for lisSequence\nimport java.util.List; // Required for lisSequence\n\nclass Solution {\n    public static int longestIncreasingSubsequence(int[] arr) {\n        if (arr == null || arr.length == 0) {\n            return 0;\n        }\n        int n = arr.length;\n        int[] dp = new int[n];\n        Arrays.fill(dp, 1);\n\n        for (int i = 1; i < n; i++) {\n            for (int j = 0; j < i; j++) {\n                if (arr[j] < arr[i]) {\n                    dp[i] = Math.max(dp[i], dp[j] + 1);\n                }\n            }\n        }\n\n        int maxLen = 0;\n        for (int len : dp) {\n            maxLen = Math.max(maxLen, len);\n        }\n        return maxLen;\n    }\n\n    public static List<Integer> lisSequence(int[] arr) {\n        if (arr == null || arr.length == 0) {\n            return new ArrayList<>();\n        }\n        int n = arr.length;\n        int[] dp = new int[n];\n        Arrays.fill(dp, 1);\n        int[] parent = new int[n];\n        Arrays.fill(parent, -1);\n\n        for (int i = 1; i < n; i++) {\n            for (int j = 0; j < i; j++) {\n                if (arr[j] < arr[i] && dp[j] + 1 > dp[i]) {\n                    dp[i] = dp[j] + 1;\n                    parent[i] = j;\n                }\n            }\n        }\n\n        // Find the index of max LIS length\n        int maxIdx = 0;\n        for (int i = 0; i < n; i++) {\n            if (dp[i] > dp[maxIdx]) {\n                maxIdx = i;\n            }\n        }\n\n        // Backtrack\n        List<Integer> result = new ArrayList<>();\n        int idx = maxIdx;\n        while (idx != -1) {\n            result.add(arr[idx]);\n            idx = parent[idx];\n        }\n        Collections.reverse(result);\n        return result;\n    }\n\n    public static int editDistance(String s1, String s2) {\n        int m = s1.length();\n        int n = s2.length();\n        int[][] dp = new int[m + 1][n + 1];\n\n        for (int i = 0; i <= m; i++) {\n            dp[i][0] = i;\n        }\n        for (int j = 0; j <= n; j++) {\n            dp[0][j] = j;\n        }\n\n        for (int i = 1; i <= m; i++) {\n            for (int j = 1; j <= n; j++) {\n                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {\n                    dp[i][j] = dp[i - 1][j - 1];\n                } else {\n                    dp[i][j] = 1 + Math.min(dp[i - 1][j], Math.min(dp[i][j - 1], dp[i - 1][j - 1]));\n                }\n            }\n        }\n        return dp[m][n];\n    }\n}',
  E'/**\n * @param {any} arr\n * @return {any}\n */\nfunction longestIncreasingSubsequence(arr) {\n    // Your code here\n}',
  E'function longestIncreasingSubsequence(arr) {\n    if (!arr || arr.length === 0) {\n        return 0;\n    }\n    const n = arr.length;\n    const dp = new Array(n).fill(1);\n\n    for (let i = 1; i < n; i++) {\n        for (let j = 0; j < i; j++) {\n            if (arr[j] < arr[i]) {\n                dp[i] = Math.max(dp[i], dp[j] + 1);\n            }\n        }\n    }\n    return Math.max(...dp);\n}\n\nfunction lisSequence(arr) {\n    if (!arr || arr.length === 0) {\n        return [];\n    }\n    const n = arr.length;\n    const dp = new Array(n).fill(1);\n    const parent = new Array(n).fill(-1);\n\n    for (let i = 1; i < n; i++) {\n        for (let j = 0; j < i; j++) {\n            if (arr[j] < arr[i] && dp[j] + 1 > dp[i]) {\n                dp[i] = dp[j] + 1;\n                parent[i] = j;\n            }\n        }\n    }\n\n    // Find the index of max LIS length\n    let maxIdx = 0;\n    for (let i = 0; i < n; i++) {\n        if (dp[i] > dp[maxIdx]) {',
  ARRAY['dynamic-programming'],
  ARRAY['google-l4', 'meta-e4', 'amazon-sde2', 'microsoft-sde2', 'stripe-l2'],
  'dynamic-programming',
  '[{"input":"longest_increasing_subsequence([10, 9, 2, 5, 3, 7, 101, 18])","expected_output":"4"},{"input":"longest_increasing_subsequence([0, 1, 0, 3, 2, 3])","expected_output":"4"},{"input":"longest_increasing_subsequence([7, 7, 7, 7])","expected_output":"1"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
