INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-knapsack-classic',
  '0/1 Knapsack',
  'easy',
  '0/1 Knapsack

Problem Statement

Given two arrays `profits` and `weights` of length `n`, and an integer `capacity`, find the **maximum profit** achievable by selecting items such that the total weight does not exceed `capacity`. Each item can be selected **at most once**.

Examples',
  '',
  '[{"input":"profits = [1, 6, 10, 16], weights = [1, 2, 3, 5], capacity = 7","output":"22","explanation":"Select items with weights 2 and 5 → profits 6 + 16 = 22"},{"input":"profits = [1, 6, 10, 16], weights = [1, 2, 3, 5], capacity = 6","output":"17","explanation":"Select items with weights 1 and 5 → profits 1 + 16 = 17"}]'::jsonb,
  'solve_knapsack',
  E'def solve_knapsack(profits, weights, capacity):\n    # TODO: implement using dynamic programming (bottom-up)\n    pass',
  E'def solve_knapsack(profits, weights, capacity):\n    n = len(profits)\n    dp = [[0] * (capacity + 1) for _ in range(n + 1)]\n\n    for i in range(1, n + 1):\n        for c in range(1, capacity + 1):\n            # Exclude item i\n            dp[i][c] = dp[i - 1][c]\n            # Include item i (if it fits)\n            if weights[i - 1] <= c:\n                dp[i][c] = max(dp[i][c], profits[i - 1] + dp[i - 1][c - weights[i - 1]])\n    return dp[n][capacity]',
  E'class Solution {\n    public Object solveKnapsack(Object profits, Object weights, int capacity) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int solveKnapsack(int[] profits, int[] weights, int capacity) {\n        int n = profits.length;\n        int[][] dp = new int[n + 1][capacity + 1];\n\n        for (int i = 1; i <= n; i++) {\n            for (int c = 1; c <= capacity; c++) {\n                // Exclude item i\n                dp[i][c] = dp[i - 1][c];\n                // Include item i (if it fits)\n                if (weights[i - 1] <= c) {\n                    dp[i][c] = Math.max(dp[i][c], profits[i - 1] + dp[i - 1][c - weights[i - 1]]);\n                }\n            }\n        }\n        return dp[n][capacity];\n    }\n}',
  E'/**\n * @param {any, any, any} profits, weights, capacity\n * @return {any}\n */\nfunction solveKnapsack(profits, weights, capacity) {\n    // Your code here\n}',
  E'function solveKnapsack(profits, weights, capacity) {\n    const n = profits.length;\n    const dp = Array(n + 1).fill(0).map(() => Array(capacity + 1).fill(0));\n\n    for (let i = 1; i <= n; i++) {\n        for (let c = 1; c <= capacity; c++) {\n            // Exclude item i\n            dp[i][c] = dp[i - 1][c];\n            // Include item i (if it fits)\n            if (weights[i - 1] <= c) {\n                dp[i][c] = Math.max(dp[i][c], profits[i - 1] + dp[i - 1][c - weights[i - 1]]);\n            }\n        }\n    }\n    return dp[n][capacity];\n}',
  ARRAY['knapsack-pattern'],
  ARRAY['generic'],
  'knapsack-pattern',
  '[{"input":"solve_knapsack([1, 6, 10, 16], [1, 2, 3, 5], 7)","expected_output":"22"},{"input":"solve_knapsack([1, 6, 10, 16], [1, 2, 3, 5], 6)","expected_output":"17"},{"input":"solve_knapsack([1, 2, 3], [1, 1, 1], 2)","expected_output":"5"}]'::jsonb,
