INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-minimum-subset-sum-difference',
  'Minimum Subset Sum Difference',
  'medium',
  'Minimum Subset Sum Difference

Problem Statement

Given an array of positive integers, partition it into two subsets such that the **absolute difference** of their sums is **minimized**. Return that minimum difference.

Examples',
  '',
  '[{"input":"[1, 6, 11, 5]","output":"1","explanation":"Subsets [1, 5, 6] (sum=12) and [11] (sum=11) → diff = 1"},{"input":"[1, 2, 3, 9]","output":"3","explanation":"Subsets [1, 2, 3] (sum=6) and [9] (sum=9) → diff = 3"}]'::jsonb,
  'min_subset_sum_diff',
  E'def min_subset_sum_diff(nums):\n    # TODO: implement using knapsack to find closest sum to total/2\n    pass',
  E'def min_subset_sum_diff(nums):\n    total = sum(nums)\n    half = total // 2\n\n    dp = [False] * (half + 1)\n    dp[0] = True\n    for num in nums:\n        for s in range(half, num - 1, -1):\n            dp[s] = dp[s] or dp[s - num]\n    # Find the largest achievable sum <= half\n    for s in range(half, -1, -1):\n        if dp[s]:\n            return total - 2 * s',
  E'class Solution {\n    public Object minSubsetSumDiff(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int minSubsetSumDiff(int[] nums) {\n        int total = 0;\n        for (int num : nums) {\n            total += num;\n        }\n        int half = total / 2;\n\n        boolean[] dp = new boolean[half + 1];\n        dp[0] = true;\n        for (int num : nums) {\n            for (int s = half; s >= num; s--) {\n                dp[s] = dp[s] || dp[s - num];\n            }\n        }\n        // Find the largest achievable sum <= half\n        for (int s = half; s >= 0; s--) {\n            if (dp[s]) {\n                return total - 2 * s;\n            }\n        }\n        return total; // Should not be reached if nums is not empty\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction minSubsetSumDiff(nums) {\n    // Your code here\n}',
  E'function minSubsetSumDiff(nums) {\n    const total = nums.reduce((sum, num) => sum + num, 0);\n    const half = Math.floor(total / 2);\n\n    const dp = new Array(half + 1).fill(false);\n    dp[0] = true;\n    for (const num of nums) {\n        for (let s = half; s >= num; s--) {\n            dp[s] = dp[s] || dp[s - num];\n        }\n    }\n    // Find the largest achievable sum <= half\n    for (let s = half; s >= 0; s--) {\n        if (dp[s]) {\n            return total - 2 * s;\n        }\n    }\n    return total; // Should not be reached if nums is not empty\n}',
  ARRAY['knapsack-pattern'],
  ARRAY['generic'],
  'knapsack-pattern',
  '[{"input":"min_subset_sum_diff([1, 6, 11, 5])","expected_output":"1"},{"input":"min_subset_sum_diff([1, 2, 3, 9])","expected_output":"3"},{"input":"min_subset_sum_diff([1, 2, 3])","expected_output":"0"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
