INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-minimum-coin-change',
  'Minimum Coin Change',
  'medium',
  'Minimum Coin Change

Problem Statement

Given an array of coin denominations and a total amount, find the **fewest number of coins** needed to make the amount. Return `-1` if it''s not possible.

Examples',
  '',
  '[{"input":"coins = [1, 5, 10, 25], amount = 30","output":"2","explanation":"25 + 5 = 30"},{"input":"coins = [1, 3, 4], amount = 6","output":"2","explanation":"3 + 3 = 6"},{"input":"coins = [2], amount = 3","output":"-1"}]'::jsonb,
  'min_coins',
  E'def min_coins(coins, amount):\n    # TODO: find minimum number of coins\n    pass',
  E'def min_coins(coins, amount):\n    dp = [float(''inf'')] * (amount + 1)\n    dp[0] = 0\n\n    for coin in coins:\n        for s in range(coin, amount + 1):\n            dp[s] = min(dp[s], 1 + dp[s - coin])\n    return dp[amount] if dp[amount] != float(''inf'') else -1',
  E'class Solution {\n    public Object minCoins(Object coins, Object amount) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int minCoins(int[] coins, int amount) {\n        // Use Integer.MAX_VALUE as infinity, but be careful with addition to avoid overflow.\n        // A value like amount + 1 could also work if amount is not excessively large,\n        // as the max coins needed would be amount itself (if all coins are 1).\n        int[] dp = new int[amount + 1];\n        for (int i = 1; i <= amount; i++) {\n            dp[i] = Integer.MAX_VALUE;\n        }\n        dp[0] = 0;\n\n        for (int coin : coins) {\n            for (int s = coin; s <= amount; s++) {\n                if (dp[s - coin] != Integer.MAX_VALUE) { // Check to prevent overflow and ensure a valid path\n                    dp[s] = Math.min(dp[s], 1 + dp[s - coin]);\n                }\n            }\n        }\n\n        return dp[amount] == Integer.MAX_VALUE ? -1 : dp[amount];\n    }\n}''inf'')] * (amount + 1)\n    //     dp[0] = 0\n    // \n    //     for coin in coins:\n    //         for s in range(coin, amount + 1):\n    //             dp[s] = min(dp[s], 1 + dp[s - coin])\n    // \n    //     return dp[amount] if dp[amount] != float(''inf'') else -1\n    // \n    // \n}',
  E'/**\n * @param {any, any} coins, amount\n * @return {any}\n */\nfunction minCoins(coins, amount) {\n    // Your code here\n}',
  E'function minCoins(coins, amount) {\n    const dp = new Array(amount + 1).fill(Number.POSITIVE_INFINITY);\n    dp[0] = 0;\n\n    for (const coin of coins) {\n        for (let s = coin; s <= amount; s++) {\n            if (dp[s - coin] !== Number.POSITIVE_INFINITY) {\n                dp[s] = Math.min(dp[s], 1 + dp[s - coin]);\n            }\n        }\n    }\n\n    return dp[amount] === Number.POSITIVE_INFINITY ? -1 : dp[amount];\n}',
  ARRAY['unbounded-knapsack-pattern'],
  ARRAY['generic'],
  'unbounded-knapsack-pattern',
  '[{"input":"min_coins([1, 5, 10, 25], 30)","expected_output":"2"},{"input":"min_coins([1, 3, 4], 6)","expected_output":"2"},{"input":"min_coins([2], 3)","expected_output":"-1"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
