INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-maximum-ribbon-cut',
  'Maximum Ribbon Cut',
  'medium',
  'Maximum Ribbon Cut

Problem Statement

Given a ribbon of length `n` and an array of allowed cut lengths, find the **maximum number of pieces** the ribbon can be cut into. Return `-1` if it''s not possible to cut the ribbon using the given lengths.

Examples',
  '',
  '[{"input":"lengths = [2, 3, 5], total = 5","output":"2","explanation":"2 + 3 = 5 (2 pieces)"},{"input":"lengths = [2, 3], total = 7","output":"3","explanation":"2 + 2 + 3 = 7 (3 pieces)"},{"input":"lengths = [5, 7], total = 3","output":"-1"}]'::jsonb,
  'max_ribbon_cut',
  E'def max_ribbon_cut(lengths, total):\n    # TODO: find maximum number of ribbon pieces\n    pass',
  E'def max_ribbon_cut(lengths, total):\n    dp = [float(''-inf'')] * (total + 1)\n    dp[0] = 0\n\n    for cut in lengths:\n        for l in range(cut, total + 1):\n            dp[l] = max(dp[l], 1 + dp[l - cut])\n    return dp[total] if dp[total] > 0 else -1',
  E'class Solution {\n    public Object maxRibbonCut(Object lengths, Object total) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int maxRibbonCut(int[] lengths, int total) {\n        // Use Integer.MIN_VALUE as negative infinity.\n        // Be careful with addition to avoid overflow.\n        int[] dp = new int[total + 1];\n        for (int i = 1; i <= total; i++) {\n            dp[i] = Integer.MIN_VALUE;\n        }\n        dp[0] = 0;\n\n        for (int length : lengths) {\n            for (int t = length; t <= total; t++) {\n                if (dp[t - length] != Integer.MIN_VALUE) { // Check to prevent overflow and ensure a valid path\n                    dp[t] = Math.max(dp[t], 1 + dp[t - length]);\n                }\n            }\n        }\n\n        return dp[total] == Integer.MIN_VALUE ? -1 : dp[total];\n    }\n}''-inf'')] * (total + 1)\n    //     dp[0] = 0\n    // \n    //     for cut in lengths:\n    //         for l in range(cut, total + 1):\n    //             dp[l] = max(dp[l], 1 + dp[l - cut])\n    // \n    //     return dp[total] if dp[total] > 0 else -1\n    // \n    // \n}',
  E'/**\n * @param {any, any} lengths, total\n * @return {any}\n */\nfunction maxRibbonCut(lengths, total) {\n    // Your code here\n}',
  E'function maxRibbonCut(lengths, total) {\n    const dp = new Array(total + 1).fill(Number.NEGATIVE_INFINITY);\n    dp[0] = 0;\n\n    for (const length of lengths) {\n        for (let t = length; t <= total; t++) {\n            if (dp[t - length] !== Number.NEGATIVE_INFINITY) {\n                dp[t] = Math.max(dp[t], 1 + dp[t - length]);\n            }\n        }\n    }\n\n    return dp[total] === Number.NEGATIVE_INFINITY ? -1 : dp[total];\n}',
  ARRAY['unbounded-knapsack-pattern'],
  ARRAY['generic'],
  'unbounded-knapsack-pattern',
  '[{"input":"max_ribbon_cut([2, 3, 5], 5)","expected_output":"2"},{"input":"max_ribbon_cut([2, 3], 7)","expected_output":"3"},{"input":"max_ribbon_cut([5, 7], 3)","expected_output":"-1"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
