INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-fibonacci-numbers',
  'Fibonacci Numbers',
  'easy',
  'Fibonacci Numbers

Problem Statement

Compute the `n`th Fibonacci number where `F(0) = 0`, `F(1) = 1`, and `F(n) = F(n-1) + F(n-2)`.

Examples

Three Approaches

1. **Naive Recursion** — O(2^n) time, O(n) space — exponential, unusable for large n
2. **Memoization** — O(n) time, O(n) space — cache results
3. **Bottom-Up with O(1) space** — just track prev two values',
  '',
  '[{"input":"5    Output: 5   (0, 1, 1, 2, 3, 5)","output":"5   (0, 1, 1, 2, 3, 5)"}]'::jsonb,
  'fibonacci',
  E'def fibonacci(n):\n    # TODO: implement with O(1) space\n    pass',
  E'def fibonacci(n):\n    if n <= 1:\n        return n\n\n    prev2, prev1 = 0, 1\n    for _ in range(2, n + 1):\n        curr = prev1 + prev2\n        prev2, prev1 = prev1, curr\n    return prev1',
  E'class Solution {\n    public Object fibonacci(int n) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int fibonacci(int n) {\n        if (n <= 1) {\n            return n;\n        }\n\n        int prev2 = 0;\n        int prev1 = 1;\n        for (int i = 2; i <= n; i++) {\n            int curr = prev1 + prev2;\n            prev2 = prev1;\n            prev1 = curr;\n        }\n        return prev1;\n    }\n}',
  E'/**\n * @param {any} n\n * @return {any}\n */\nfunction fibonacci(n) {\n    // Your code here\n}',
  E'function fibonacci(n) {\n    if (n <= 1) {\n        return n;\n    }\n\n    let prev2 = 0;\n    let prev1 = 1;\n    for (let i = 2; i <= n; i++) {\n        const curr = prev1 + prev2;\n        prev2 = prev1;\n        prev1 = curr;\n    }\n    return prev1;\n}',
  ARRAY['fibonacci-pattern'],
  ARRAY['generic'],
  'fibonacci-pattern',
  '[{"input":"fibonacci(5)","expected_output":"5"},{"input":"fibonacci(7)","expected_output":"13"},{"input":"fibonacci(10)","expected_output":"55"}]'::jsonb,
  '[{"input":"fibonacci(0)","expected_output":"0"}]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
  description = EXCLUDED.description,
  constraints = EXCLUDED.constraints,
  examples = EXCLUDED.examples,
