INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-climbing-stairs',
  'Staircase (Climbing Stairs)',
  'easy',
  'Staircase (Climbing Stairs)

Problem Statement

You are climbing a staircase with `n` steps. Each time you can climb **1, 2, or 3** steps. How many **distinct ways** can you reach the top?

Examples',
  '',
  '[{"input":"3    Output: 4","output":"4"},{"input":"4    Output: 7","output":"7"}]'::jsonb,
  'count_ways',
  E'def count_ways(n):\n    # TODO: count ways to climb n stairs (1, 2, or 3 steps at a time)\n    pass',
  E'def count_ways(n):\n    if n <= 1:\n        return 1\n    if n == 2:\n        return 2\n\n    a, b, c = 1, 1, 2\n    for _ in range(3, n + 1):\n        total = a + b + c\n        a, b, c = b, c, total\n    return c',
  E'class Solution {\n    public Object countWays(int n) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int countWays(int n) {\n        if (n <= 1) {\n            return 1;\n        }\n        if (n == 2) {\n            return 2;\n        }\n\n        int a = 1; // ways to reach i-3\n        int b = 1; // ways to reach i-2\n        int c = 2; // ways to reach i-1\n        for (int i = 3; i <= n; i++) {\n            int total = a + b + c;\n            a = b;\n            b = c;\n            c = total;\n        }\n        return c;\n    }\n}',
  E'/**\n * @param {any} n\n * @return {any}\n */\nfunction countWays(n) {\n    // Your code here\n}',
  E'function countWays(n) {\n    if (n <= 1) {\n        return 1;\n    }\n    if (n === 2) {\n        return 2;\n    }\n\n    let a = 1; // ways to reach i-3\n    let b = 1; // ways to reach i-2\n    let c = 2; // ways to reach i-1\n    for (let i = 3; i <= n; i++) {\n        const total = a + b + c;\n        a = b;\n        b = c;\n        c = total;\n    }\n    return c;\n}',
  ARRAY['fibonacci-pattern'],
  ARRAY['generic'],
  'fibonacci-pattern',
  '[{"input":"count_ways(3)","expected_output":"4"},{"input":"count_ways(4)","expected_output":"7"},{"input":"count_ways(5)","expected_output":"13"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
