INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-number-factors',
  'Number Factors',
  'medium',
  'Number Factors

Problem Statement

Given a number `n`, count the number of ways to express it as a **sum of 1, 3, and 4**.

Examples',
  '',
  '[{"input":"4    Output: 4","output":"4"},{"input":"5    Output: 6","output":"6"}]'::jsonb,
  'count_factors',
  E'def count_factors(n):\n    # TODO: count ways to express n as sum of 1, 3, and 4\n    pass',
  E'def count_factors(n):\n    if n <= 2:\n        return 1\n    if n == 3:\n        return 2\n\n    dp = [0] * (n + 1)\n    dp[0] = dp[1] = dp[2] = 1\n    dp[3] = 2\n    for i in range(4, n + 1):\n        dp[i] = dp[i - 1] + dp[i - 3] + dp[i - 4]\n    return dp[n]',
  E'class Solution {\n    public Object countFactors(int n) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int countFactors(int n) {\n        if (n <= 2) {\n            return 1;\n        }\n        if (n == 3) {\n            return 2;\n        }\n\n        int[] dp = new int[n + 1];\n        dp[0] = 1;\n        dp[1] = 1;\n        dp[2] = 1;\n        dp[3] = 2;\n        for (int i = 4; i <= n; i++) {\n            dp[i] = dp[i - 1] + dp[i - 3] + dp[i - 4];\n        }\n        return dp[n];\n    }\n}',
  E'/**\n * @param {any} n\n * @return {any}\n */\nfunction countFactors(n) {\n    // Your code here\n}',
  E'function countFactors(n) {\n    if (n <= 2) {\n        return 1;\n    }\n    if (n === 3) {\n        return 2;\n    }\n\n    const dp = new Array(n + 1).fill(0);\n    dp[0] = 1;\n    dp[1] = 1;\n    dp[2] = 1;\n    dp[3] = 2;\n    for (let i = 4; i <= n; i++) {\n        dp[i] = dp[i - 1] + dp[i - 3] + dp[i - 4];\n    }\n    return dp[n];\n}',
  ARRAY['fibonacci-pattern'],
  ARRAY['generic'],
  'fibonacci-pattern',
  '[{"input":"count_factors(4)","expected_output":"4"},{"input":"count_factors(5)","expected_output":"6"},{"input":"count_factors(6)","expected_output":"9"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
