INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-minimum-jumps',
  'Minimum Jumps to Reach End',
  'medium',
  'Minimum Jumps to Reach End

Problem Statement

Given an array of non-negative integers where each element represents the **maximum jump length** from that position, find the **minimum number of jumps** to reach the last index. Assume you can always reach the end.

Examples',
  '',
  '[{"input":"[2, 1, 1, 1, 4]","output":"3","explanation":"Jump 2→1→1→4 (indices 0→1→2→3 or 0→2→3→4)"},{"input":"[1, 1, 3, 6, 9, 3, 0, 1, 3]","output":"4"}]'::jsonb,
  'min_jumps',
  E'def min_jumps(arr):\n    # TODO: find minimum jumps to reach the end\n    pass',
  E'def min_jumps(arr):\n    n = len(arr)\n    if n <= 1:\n        return 0\n\n    jumps = 0\n    current_end = 0\n    farthest = 0\n    for i in range(n - 1):\n        farthest = max(farthest, i + arr[i])\n        if i == current_end:\n            jumps += 1\n            current_end = farthest\n            if current_end >= n - 1:\n                break\n    return jumps',
  E'class Solution {\n    public Object minJumps(int[] arr) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int minJumps(int[] arr) {\n        int n = arr.length;\n        if (n <= 1) {\n            return 0;\n        }\n\n        int jumps = 0;\n        int currentEnd = 0;\n        int farthest = 0;\n        for (int i = 0; i < n - 1; i++) {\n            farthest = Math.max(farthest, i + arr[i]);\n            if (i == currentEnd) {\n                jumps++;\n                currentEnd = farthest;\n                if (currentEnd >= n - 1) {\n                    break;\n                }\n            }\n        }\n        return jumps;\n    }\n}',
  E'/**\n * @param {any} arr\n * @return {any}\n */\nfunction minJumps(arr) {\n    // Your code here\n}',
  E'function minJumps(arr) {\n    const n = arr.length;\n    if (n <= 1) {\n        return 0;\n    }\n\n    let jumps = 0;\n    let currentEnd = 0;\n    let farthest = 0;\n    for (let i = 0; i < n - 1; i++) {\n        farthest = Math.max(farthest, i + arr[i]);\n        if (i === currentEnd) {\n            jumps++;\n            currentEnd = farthest;\n            if (currentEnd >= n - 1) {\n                break;\n            }\n        }\n    }\n    return jumps;\n}',
