INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-house-thief',
  'House Thief (House Robber)',
  'medium',
  'House Thief (House Robber)

Problem Statement

A thief plans to rob houses along a street. Each house has a certain amount of money. Adjacent houses have connected security systems — if two **adjacent** houses are broken into, the alarm triggers. Find the **maximum amount** the thief can rob without triggering the alarm.

Examples',
  '',
  '[{"input":"[2, 5, 1, 3, 6, 2, 4]","output":"15","explanation":"Rob houses with amounts 5 + 6 + 4 = 15"},{"input":"[2, 10, 14, 8, 1]","output":"18","explanation":"Rob houses with amounts 2 + 14 + 1 = 17? No — 10 + 8 = 18 ✓"}]'::jsonb,
  'house_thief',
  E'def house_thief(houses):\n    # TODO: find max money without robbing adjacent houses\n    pass',
  E'def house_thief(houses):\n    if not houses:\n        return 0\n    if len(houses) == 1:\n        return houses[0]\n\n    prev2, prev1 = 0, houses[0]\n    for i in range(1, len(houses)):\n        curr = max(prev1, houses[i] + prev2)\n        prev2, prev1 = prev1, curr\n    return prev1',
  E'class Solution {\n    public Object houseThief(Object houses) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int houseThief(int[] houses) {\n        if (houses == null || houses.length == 0) {\n            return 0;\n        }\n        if (houses.length == 1) {\n            return houses[0];\n        }\n\n        int prev2 = 0;\n        int prev1 = houses[0];\n        for (int i = 1; i < houses.length; i++) {\n            int curr = Math.max(prev1, houses[i] + prev2);\n            prev2 = prev1;\n            prev1 = curr;\n        }\n        return prev1;\n    }\n}',
  E'/**\n * @param {any} houses\n * @return {any}\n */\nfunction houseThief(houses) {\n    // Your code here\n}',
  E'function houseThief(houses) {\n    if (!houses || houses.length === 0) {\n        return 0;\n    }\n    if (houses.length === 1) {\n        return houses[0];\n    }\n\n    let prev2 = 0;\n    let prev1 = houses[0];\n    for (let i = 1; i < houses.length; i++) {\n        const curr = Math.max(prev1, houses[i] + prev2);\n        prev2 = prev1;\n        prev1 = curr;\n    }\n    return prev1;\n}',
  ARRAY['fibonacci-pattern'],
  ARRAY['generic'],
  'fibonacci-pattern',
  '[{"input":"house_thief([2, 5, 1, 3, 6, 2, 4])","expected_output":"15"},{"input":"house_thief([2, 10, 14, 8, 1])","expected_output":"18"},{"input":"house_thief([6, 7, 1, 30, 8, 2, 4])","expected_output":"41"}]'::jsonb,
  '[]'::jsonb
