INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-longest-palindromic-subsequence',
  'Longest Palindromic Subsequence',
  'easy',
  'Longest Palindromic Subsequence

Problem Statement

Given a string `s`, find the length of the **longest palindromic subsequence** (LPS).

Examples',
  '',
  '[{"input":"\"abdbca\"","output":"5","explanation":"LPS is \"abdba\""},{"input":"\"cddpd\"","output":"3","explanation":"LPS is \"ddd\""},{"input":"\"pqr\"","output":"1","explanation":"Any single character"}]'::jsonb,
  'lps',
  E'def lps(s):\n    # TODO: find length of longest palindromic subsequence\n    pass',
  E'def lps(s):\n    n = len(s)\n    dp = [[0] * n for _ in range(n)]\n\n    # Every single character is a palindrome of length 1\n    for i in range(n):\n        dp[i][i] = 1\n    for length in range(2, n + 1):\n        for i in range(n - length + 1):\n            j = i + length - 1\n            if s[i] == s[j]:\n                dp[i][j] = 2 + dp[i + 1][j - 1]\n            else:\n                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])\n    return dp[0][n - 1]',
  E'class Solution {\n    public Object lps(String s) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int lps(String s) {\n        int n = s.length();\n        int[][] dp = new int[n][n];\n\n        // Every single character is a palindrome of length 1\n        for (int i = 0; i < n; i++) {\n            dp[i][i] = 1;\n        }\n\n        for (int length = 2; length <= n; length++) {\n            for (int i = 0; i < n - length + 1; i++) {\n                int j = i + length - 1;\n                if (s.charAt(i) == s.charAt(j)) {\n                    dp[i][j] = 2 + dp[i + 1][j - 1];\n                } else {\n                    dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);\n                }\n            }\n        }\n        return dp[0][n - 1];\n    }\n}',
  E'/**\n * @param {any} s\n * @return {any}\n */\nfunction lps(s) {\n    // Your code here\n}',
  E'function lps(s) {\n    const n = s.length;\n    const dp = Array.from({ length: n }, () => Array(n).fill(0));\n\n    // Every single character is a palindrome of length 1\n    for (let i = 0; i < n; i++) {\n        dp[i][i] = 1;\n    }\n\n    for (let length = 2; length <= n; length++) {\n        for (let i = 0; i < n - length + 1; i++) {\n            const j = i + length - 1;\n            if (s[i] === s[j]) {\n                dp[i][j] = 2 + dp[i + 1][j - 1];\n            } else {\n                dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);\n            }\n        }\n    }\n    return dp[0][n - 1];\n}',
  ARRAY['palindromic-pattern'],
  ARRAY['generic'],
  'palindromic-pattern',
  '[{"input":"lps(\"abdbca\")","expected_output":"5"},{"input":"lps(\"cddpd\")","expected_output":"3"},{"input":"lps(\"pqr\")","expected_output":"1"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
