INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-longest-palindromic-substring',
  'Longest Palindromic Substring',
  'easy',
  'Longest Palindromic Substring

Problem Statement

Given a string `s`, find the **longest palindromic substring**.

Examples',
  '',
  '[{"input":"\"babad\"","output":"\"bab\" (or \"aba\")"},{"input":"\"cbbd\"","output":"\"bb\""}]'::jsonb,
  'longest_palindrome_substring',
  E'def longest_palindrome_substring(s):\n    # TODO: find the longest palindromic substring\n    pass',
  E'def longest_palindrome_substring(s):\n    n = len(s)\n    if n < 2:\n        return s\n\n    start, max_len = 0, 1\n    def expand(left, right):\n        nonlocal start, max_len\n        while left >= 0 and right < n and s[left] == s[right]:\n            if right - left + 1 > max_len:\n                start = left\n                max_len = right - left + 1\n            left -= 1\n            right += 1\n\n    for i in range(n):\n        expand(i, i)      # odd-length palindromes\n        expand(i, i + 1)  # even-length palindromes\n    return s[start:start + max_len]',
  E'class Solution {\n    public Object longestPalindromeSubstring(String s) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static String longestPalindromeSubstring(String s) {\n        int n = s.length();\n        if (n < 2) {\n            return s;\n        }\n\n        int start = 0;\n        int maxLength = 1;\n\n        for (int i = 0; i < n; i++) {\n            // Odd-length palindromes\n            int left = i, right = i;\n            while (left >= 0 && right < n && s.charAt(left) == s.charAt(right)) {\n                if (right - left + 1 > maxLength) {\n                    start = left;\n                    maxLength = right - left + 1;\n                }\n                left--;\n                right++;\n            }\n\n            // Even-length palindromes\n            left = i;\n            right = i + 1;\n            while (left >= 0 && right < n && s.charAt(left) == s.charAt(right)) {\n                if (right - left + 1 > maxLength) {\n                    start = left;\n                    maxLength = right - left + 1;\n                }\n                left--;\n                right++;\n            }\n        }\n        return s.substring(start, start + maxLength);\n    }\n}',
  E'/**\n * @param {any} s\n * @return {any}\n */\nfunction longestPalindromeSubstring(s) {\n    // Your code here\n}',
  E'function longestPalindromeSubstring(s) {\n    const n = s.length;\n    if (n < 2) {\n        return s;\n    }\n\n    let start = 0;\n    let maxLength = 1;\n\n    for (let i = 0; i < n; i++) {\n        // Odd-length palindromes\n        let left = i;\n        let right = i;\n        while (left >= 0 && right < n && s[left] === s[right]) {\n            if (right - left + 1 > maxLength) {\n                start = left;\n                maxLength = right - left + 1;\n            }\n            left--;\n            right++;\n        }\n\n        // Even-length palindromes\n        left = i;\n        right = i + 1;\n        while (left >= 0 && right < n && s[left] === s[right]) {\n            if (right - left + 1 > maxLength) {\n                start = left;\n                maxLength = right - left + 1;\n            }\n            left--;\n            right++;\n        }\n    }\n    return s.substring(start, start + maxLength);\n}',
  ARRAY['palindromic-pattern'],
  ARRAY['generic'],
  'palindromic-pattern',
  '[{"input":"longest_palindrome_substring(\"babad\")","expected_output":"\"bab\" or \"aba\""},{"input":"longest_palindrome_substring(\"cbbd\")","expected_output":"\"bb\""},{"input":"longest_palindrome_substring(\"a\")","expected_output":"\"a\""}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
