INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-count-palindromic-substrings',
  'Count of Palindromic Substrings',
  'medium',
  'Count of Palindromic Substrings

Problem Statement

Given a string `s`, count the number of **palindromic substrings** in it.

Examples',
  '',
  '[{"input":"\"abc\"","output":"3","explanation":"\"a\", \"b\", \"c\""},{"input":"\"aaa\"","output":"6","explanation":"\"a\", \"a\", \"a\", \"aa\", \"aa\", \"aaa\""}]'::jsonb,
  'count_palindromic_substrings',
  E'def count_palindromic_substrings(s):\n    # TODO: count all palindromic substrings\n    pass',
  E'def count_palindromic_substrings(s):\n    n = len(s)\n    count = 0\n\n    def expand(left, right):\n        nonlocal count\n        while left >= 0 and right < n and s[left] == s[right]:\n            count += 1\n            left -= 1\n            right += 1\n\n    for i in range(n):\n        expand(i, i)      # odd-length\n        expand(i, i + 1)  # even-length\n    return count',
  E'class Solution {\n    public Object countPalindromicSubstrings(String s) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int countPalindromicSubstrings(String s) {\n        int n = s.length();\n        int count = 0;\n\n        for (int i = 0; i < n; i++) {\n            // Odd-length palindromes\n            int left = i, right = i;\n            while (left >= 0 && right < n && s.charAt(left) == s.charAt(right)) {\n                count++;\n                left--;\n                right++;\n            }\n\n            // Even-length palindromes\n            left = i;\n            right = i + 1;\n            while (left >= 0 && right < n && s.charAt(left) == s.charAt(right)) {\n                count++;\n                left--;\n                right++;\n            }\n        }\n        return count;\n    }\n}',
  E'/**\n * @param {any} s\n * @return {any}\n */\nfunction countPalindromicSubstrings(s) {\n    // Your code here\n}',
  E'function countPalindromicSubstrings(s) {\n    const n = s.length;\n    let count = 0;\n\n    for (let i = 0; i < n; i++) {\n        // Odd-length palindromes\n        let left = i;\n        let right = i;\n        while (left >= 0 && right < n && s[left] === s[right]) {\n            count++;\n            left--;\n            right++;\n        }\n\n        // Even-length palindromes\n        left = i;\n        right = i + 1;\n        while (left >= 0 && right < n && s[left] === s[right]) {\n            count++;\n            left--;\n            right++;\n        }\n    }\n    return count;\n}',
  ARRAY['palindromic-pattern'],
  ARRAY['generic'],
  'palindromic-pattern',
  '[{"input":"count_palindromic_substrings(\"abc\")","expected_output":"3"},{"input":"count_palindromic_substrings(\"aaa\")","expected_output":"6"},{"input":"count_palindromic_substrings(\"abba\")","expected_output":"6"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
