INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-palindromic-partitioning',
  'Palindromic Partitioning',
  'medium',
  'Palindromic Partitioning

Problem Statement

Given a string `s`, find the **minimum number of cuts** needed to partition it such that every substring is a palindrome.

Examples',
  '',
  '[{"input":"\"abcba\"","output":"0","explanation":"Already a palindrome"},{"input":"\"aab\"","output":"1","explanation":"\"aa\" | \"b\""},{"input":"\"aabbc\"","output":"2","explanation":"\"aa\" | \"bb\" | \"c\""}]'::jsonb,
  'min_palindrome_cuts',
  E'def min_palindrome_cuts(s):\n    # TODO: find minimum cuts to partition into palindromes\n    pass',
  E'def min_palindrome_cuts(s):\n    n = len(s)\n    if n <= 1:\n        return 0\n\n    # Precompute palindrome table\n    is_pal = [[False] * n for _ in range(n)]\n    for i in range(n):\n        is_pal[i][i] = True\n    for length in range(2, n + 1):\n        for i in range(n - length + 1):\n            j = i + length - 1\n            if s[i] == s[j]:\n                is_pal[i][j] = (length == 2) or is_pal[i + 1][j - 1]\n    # dp[i] = min cuts for s[0..i]\n    dp = list(range(n))  # worst case: cut every char\n    for i in range(1, n):\n        if is_pal[0][i]:\n            dp[i] = 0\n            continue\n        for j in range(1, i + 1):\n            if is_pal[j][i]:\n                dp[i] = min(dp[i], dp[j - 1] + 1)\n    return dp[n - 1]',
  E'class Solution {\n    public Object minPalindromeCuts(String s) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int minPalindromeCuts(String s) {\n        int n = s.length();\n        if (n <= 1) {\n            return 0;\n        }\n\n        // Precompute palindrome table\n        boolean[][] isPal = new boolean[n][n];\n        for (int i = 0; i < n; i++) {\n            isPal[i][i] = true;\n        }\n\n        for (int length = 2; length <= n; length++) {\n            for (int i = 0; i < n - length + 1; i++) {\n                int j = i + length - 1;\n                if (s.charAt(i) == s.charAt(j)) {\n                    isPal[i][j] = (length == 2) || isPal[i + 1][j - 1];\n                } else {\n                    isPal[i][j] = false; // Not strictly needed as default is false\n                }\n            }\n        }\n\n        // dp[i] = min cuts for s[0..i]\n        int[] dp = new int[n];\n        for (int k = 0; k < n; k++) {\n            dp[k] = k; // worst case: cut every char\n        }\n\n        for (int i = 1; i < n; i++) {\n            if (isPal[0][i]) {\n                dp[i] = 0;\n                continue;\n            }\n            for (int j = 1; j <= i; j++) {\n                if (isPal[j][i]) {\n                    dp[i] = Math.min(dp[i], dp[j - 1] + 1);\n                }\n            }\n        }\n        return dp[n - 1];\n    }\n}',
  E'/**\n * @param {any} s\n * @return {any}\n */\nfunction minPalindromeCuts(s) {\n    // Your code here\n}',
  E'function minPalindromeCuts(s) {\n    const n = s.length;\n    if (n <= 1) {\n        return 0;\n    }\n\n    // Precompute palindrome table\n    const isPal = Array.from({ length: n }, () => Array(n).fill(false));\n    for (let i = 0; i < n; i++) {\n        isPal[i][i] = true;\n    }\n\n    for (let length = 2; length <= n; length++) {\n        for (let i = 0; i < n - length + 1; i++) {\n            const j = i + length - 1;\n            if (s[i] === s[j]) {\n                isPal[i][j] = (length === 2) || isPal[i + 1][j - 1];\n            }\n        }\n    }\n\n    // dp[i] = min cuts for s[0..i]\n    const dp = Array.from({ length: n }, (_, k) => k); // worst case: cut every char\n\n    for (let i = 1; i < n; i++) {\n        if (isPal[0][i]) {\n            dp[i] = 0;\n            continue;\n        }\n        for (let j = 1; j <= i; j++) {\n            if (isPal[j][i]) {\n                dp[i] = Math.min(dp[i], dp[j - 1] + 1);\n            }\n        }\n    }\n    return dp[n - 1];\n}',
  ARRAY['palindromic-pattern'],
  ARRAY['generic'],
  'palindromic-pattern',
