INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-min-deletions-insertions',
  'Minimum Deletions & Insertions to Transform',
  'medium',
  'Minimum Deletions & Insertions to Transform

Problem Statement

Given two strings `s1` and `s2`, find the minimum number of **deletions** from `s1` and **insertions** into `s1` to transform it into `s2`.

Examples',
  '',
  '[{"input":"s1 = \"abc\", s2 = \"fbc\"","output":"1 deletion, 1 insertion","explanation":"Delete ''a'', insert ''f''"},{"input":"s1 = \"abdca\", s2 = \"cbda\"","output":"2 deletions, 1 insertion"}]'::jsonb,
  'min_operations',
  E'def min_operations(s1, s2):\n    # TODO: return (deletions, insertions) to transform s1 to s2\n    pass',
  E'def min_operations(s1, s2):\n    n, m = len(s1), len(s2)\n    dp = [[0] * (m + 1) for _ in range(n + 1)]\n\n    for i in range(1, n + 1):\n        for j in range(1, m + 1):\n            if s1[i - 1] == s2[j - 1]:\n                dp[i][j] = 1 + dp[i - 1][j - 1]\n            else:\n                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])\n    lcs_len = dp[n][m]\n    deletions = n - lcs_len\n    insertions = m - lcs_len\n    return (deletions, insertions)',
  E'class Solution {\n    public Object minOperations(Object s1, Object s2) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // import java.lang.Math; // For Math.max\n    public static int[] minOperations(String s1, String s2) {\n        int n = s1.length();\n        int m = s2.length();\n        int[][] dp = new int[n + 1][m + 1];\n\n        for (int i = 1; i <= n; i++) {\n            for (int j = 1; j <= m; j++) {\n                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {\n                    dp[i][j] = 1 + dp[i - 1][j - 1];\n                } else {\n                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);\n                }\n            }\n        }\n        int lcsLen = dp[n][m];\n        int deletions = n - lcsLen;\n        int insertions = m - lcsLen;\n        return new int[]{deletions, insertions};\n    }\n}',
  E'/**\n * @param {any, any} s1, s2\n * @return {any}\n */\nfunction minOperations(s1, s2) {\n    // Your code here\n}',
  E'function minOperations(s1, s2) {\n    const n = s1.length;\n    const m = s2.length;\n    const dp = Array(n + 1).fill(0).map(() => Array(m + 1).fill(0));\n\n    for (let i = 1; i <= n; i++) {\n        for (let j = 1; j <= m; j++) {\n            if (s1[i - 1] === s2[j - 1]) {\n                dp[i][j] = 1 + dp[i - 1][j - 1];\n            } else {\n                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);\n            }\n        }\n    }\n    const lcsLen = dp[n][m];\n    const deletions = n - lcsLen;\n    const insertions = m - lcsLen;\n    return [deletions, insertions];\n}',
  ARRAY['lcs-pattern', 'strings'],
  ARRAY['generic'],
  'lcs-pattern',
  '[{"input":"min_operations(\"abc\", \"fbc\")","expected_output":"(1, 1)"},{"input":"min_operations(\"abdca\", \"cbda\")","expected_output":"(2, 1)"},{"input":"min_operations(\"abc\", \"abc\")","expected_output":"(0, 0)"}]'::jsonb,
  '[]'::jsonb
