INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-longest-increasing-subsequence',
  'Longest Increasing Subsequence',
  'medium',
  'Longest Increasing Subsequence (LIS)

Problem Statement

Given an array of integers, find the length of the **longest strictly increasing subsequence**.

Examples

Two Approaches

**1. DP — O(n²):** `dp[i]` = LIS ending at index `i`.

**2. Binary Search — O(n log n):** Maintain a "tails" array and use binary search to find the insertion point.',
  '',
  '[{"input":"[4, 2, 3, 6, 10, 1, 12]","output":"5","explanation":"[2, 3, 6, 10, 12]"},{"input":"[10, 9, 2, 5, 3, 7, 101, 18]","output":"4","explanation":"[2, 3, 7, 101] or [2, 5, 7, 101]"}]'::jsonb,
  'lis',
  E'def lis(nums):\n    # TODO: find length of longest increasing subsequence\n    pass',
  E'from bisect import bisect_left\ndef lis(nums):\n    if not nums:\n        return 0\n\n    # O(n log n) approach using binary search\n    tails = []\n    for num in nums:\n        pos = bisect_left(tails, num)\n        if pos == len(tails):\n            tails.append(num)\n        else:\n            tails[pos] = num\n    return len(tails)',
  E'class Solution {\n    public Object lis(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // import java.util.ArrayList;\n    // import java.util.Collections; // For Collections.binarySearch, though manual is used here\n    public static int lis(int[] nums) {\n        if (nums == null || nums.length == 0) {\n            return 0;\n        }\n\n        ArrayList<Integer> tails = new ArrayList<>();\n        for (int num : nums) {\n            // Manual bisect_left\n            int low = 0;\n            int high = tails.size();\n            while (low < high) {\n                int mid = low + (high - low) / 2;\n                if (tails.get(mid) < num) {\n                    low = mid + 1;\n                } else {\n                    high = mid;\n                }\n            }\n            // low is the insertion point\n            int pos = low;\n\n            if (pos == tails.size()) {\n                tails.add(num);\n            } else {\n                tails.set(pos, num);\n            }\n        }\n        return tails.size();\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction lis(nums) {\n    // Your code here\n}',
  E'function lis(nums) {\n    if (!nums || nums.length === 0) {\n        return 0;\n    }\n\n    const tails = [];\n    for (const num of nums) {\n        // Manual bisect_left\n        let low = 0;\n        let high = tails.length;\n        while (low < high) {\n            const mid = Math.floor(low + (high - low) / 2);\n            if (tails[mid] < num) {\n                low = mid + 1;\n            } else {\n                high = mid;\n            }\n        }\n        // low is the insertion point\n        const pos = low;\n\n        if (pos === tails.length) {\n            tails.push(num);\n        } else {\n            tails[pos] = num;\n        }\n    }\n    return tails.length;\n}',
  ARRAY['lcs-pattern', 'strings'],
  ARRAY['generic'],
  'lcs-pattern',
  '[{"input":"lis([4, 2, 3, 6, 10, 1, 12])","expected_output":"5"},{"input":"lis([10, 9, 2, 5, 3, 7, 101, 18])","expected_output":"4"},{"input":"lis([0, 1, 0, 3, 2, 3])","expected_output":"4"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
