INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-max-sum-increasing-subsequence',
  'Maximum Sum Increasing Subsequence',
  'medium',
  'Maximum Sum Increasing Subsequence

Problem Statement

Given an array of integers, find the **maximum sum** of an increasing subsequence.

Examples',
  '',
  '[{"input":"[4, 1, 2, 6, 10, 1, 12]","output":"32","explanation":"[1, 2, 6, 10, 12] → sum = 31? Actually [4, 6, 10, 12] = 32"},{"input":"[3, 4, 5, 1]","output":"12","explanation":"[3, 4, 5] → sum = 12"}]'::jsonb,
  'max_sum_lis',
  E'def max_sum_lis(nums):\n    # TODO: find maximum sum increasing subsequence\n    pass',
  E'def max_sum_lis(nums):\n    n = len(nums)\n    dp = nums[:]  # each element is a subsequence of length 1\n\n    for i in range(1, n):\n        for j in range(i):\n            if nums[j] < nums[i]:\n                dp[i] = max(dp[i], dp[j] + nums[i])\n    return max(dp)',
  E'class Solution {\n    public Object maxSumLis(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // import java.lang.Math; // For Math.max\n    // import java.util.Arrays; // For Arrays.stream, though manual max is used\n    public static int maxSumLis(int[] nums) {\n        int n = nums.length;\n        if (n == 0) {\n            return 0; // Or handle as per problem constraints, e.g., throw exception\n        }\n\n        int[] dp = new int[n];\n        // Copy nums to dp\n        for (int i = 0; i < n; i++) {\n            dp[i] = nums[i];\n        }\n\n        for (int i = 1; i < n; i++) {\n            for (int j = 0; j < i; j++) {\n                if (nums[j] < nums[i]) {\n                    dp[i] = Math.max(dp[i], dp[j] + nums[i]);\n                }\n            }\n        }\n\n        int maxSum = 0;\n        if (n > 0) { // Ensure dp is not empty before finding max\n            maxSum = dp[0];\n            for (int i = 1; i < n; i++) {\n                if (dp[i] > maxSum) {\n                    maxSum = dp[i];\n                }\n            }\n        }\n        return maxSum;\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction maxSumLis(nums) {\n    // Your code here\n}',
  E'function maxSumLis(nums) {\n    const n = nums.length;\n    if (n === 0) {\n        return 0;\n    }\n\n    const dp = [...nums]; // each element is a subsequence of length 1\n\n    for (let i = 1; i < n; i++) {\n        for (let j = 0; j < i; j++) {\n            if (nums[j] < nums[i]) {\n                dp[i] = Math.max(dp[i], dp[j] + nums[i]);\n            }\n        }\n    }\n    return Math.max(...dp);\n}',
  ARRAY['lcs-pattern', 'strings'],
  ARRAY['generic'],
  'lcs-pattern',
  '[{"input":"max_sum_lis([4, 1, 2, 6, 10, 1, 12])","expected_output":"32"},{"input":"max_sum_lis([3, 4, 5, 1])","expected_output":"12"},{"input":"max_sum_lis([-1, 2, 3])","expected_output":"5"}]'::jsonb,
  '[]'::jsonb
