INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-shortest-common-supersequence',
  'Shortest Common Supersequence',
  'medium',
  'Shortest Common Supersequence

Problem Statement

Given two strings `s1` and `s2`, find the length of the **shortest string** that has both `s1` and `s2` as subsequences.

Examples',
  '',
  '[{"input":"s1 = \"abcf\", s2 = \"bdcf\"","output":"5","explanation":"\"abdcf\" contains both as subsequences"},{"input":"s1 = \"dynamic\", s2 = \"programming\"","output":"15"}]'::jsonb,
  'scs_length',
  E'def scs_length(s1, s2):\n    # TODO: find length of shortest common supersequence\n    pass',
  E'def scs_length(s1, s2):\n    n, m = len(s1), len(s2)\n    dp = [[0] * (m + 1) for _ in range(n + 1)]\n\n    for i in range(1, n + 1):\n        for j in range(1, m + 1):\n            if s1[i - 1] == s2[j - 1]:\n                dp[i][j] = 1 + dp[i - 1][j - 1]\n            else:\n                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])\n    lcs_len = dp[n][m]\n    return n + m - lcs_len',
  E'class Solution {\n    public Object scsLength(Object s1, Object s2) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // import java.lang.Math; // For Math.max\n    public static int scsLength(String s1, String s2) {\n        int n = s1.length();\n        int m = s2.length();\n        int[][] dp = new int[n + 1][m + 1];\n\n        for (int i = 1; i <= n; i++) {\n            for (int j = 1; j <= m; j++) {\n                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {\n                    dp[i][j] = 1 + dp[i - 1][j - 1];\n                } else {\n                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);\n                }\n            }\n        }\n        int lcsLen = dp[n][m];\n        return n + m - lcsLen;\n    }\n}',
  E'/**\n * @param {any, any} s1, s2\n * @return {any}\n */\nfunction scsLength(s1, s2) {\n    // Your code here\n}',
  E'function scsLength(s1, s2) {\n    const n = s1.length;\n    const m = s2.length;\n    const dp = Array(n + 1).fill(0).map(() => Array(m + 1).fill(0));\n\n    for (let i = 1; i <= n; i++) {\n        for (let j = 1; j <= m; j++) {\n            if (s1[i - 1] === s2[j - 1]) {\n                dp[i][j] = 1 + dp[i - 1][j - 1];\n            } else {\n                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);\n            }\n        }\n    }\n    const lcsLen = dp[n][m];\n    return n + m - lcsLen;\n}',
  ARRAY['lcs-pattern', 'strings'],
  ARRAY['generic'],
  'lcs-pattern',
  '[{"input":"scs_length(\"abcf\", \"bdcf\")","expected_output":"5"},{"input":"scs_length(\"dynamic\", \"programming\")","expected_output":"15"},{"input":"scs_length(\"abc\", \"abc\")","expected_output":"3"}]'::jsonb,
  '[]'::jsonb
