INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-matrix-chain-multiplication',
  'Matrix Chain Multiplication',
  'easy',
  'Matrix Chain Multiplication

Problem Statement

Given a chain of matrices with dimensions `dims` (where matrix `i` has dimensions `dims[i-1] × dims[i]`), find the **minimum number of scalar multiplications** needed to compute the product.

Examples',
  '',
  '[{"input":"dims = [1, 2, 3, 4]","output":"18","explanation":"(A1×A2)×A3 costs 1*2*3 + 1*3*4 = 6 + 12 = 18"},{"input":"dims = [10, 30, 5, 60]","output":"4500","explanation":"A1×(A2×A3) costs 30*5*60 + 10*30*60 = 9000+18000=27000"}]'::jsonb,
  'mcm',
  E'def mcm(dims):\n    # TODO: find minimum multiplication cost\n    pass',
  E'def mcm(dims):\n    n = len(dims) - 1  # number of matrices\n    dp = [[0] * n for _ in range(n)]\n\n    for length in range(2, n + 1):\n        for i in range(n - length + 1):\n            j = i + length - 1\n            dp[i][j] = float(''inf'')\n            for k in range(i, j):\n                cost = dp[i][k] + dp[k + 1][j] + dims[i] * dims[k + 1] * dims[j + 1]\n                dp[i][j] = min(dp[i][j], cost)\n    return dp[0][n - 1]',
  E'class Solution {\n    public Object mcm(Object dims) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // import java.lang.Math; // For Math.min\n    public static int mcm(int[] dims) {\n        int n = dims.length - 1; // number of matrices\n        int[][] dp = new int[n][n];\n\n        // dp[i][j] stores the minimum scalar multiplications needed to multiply matrices A_i through A_j.\n        // Matrix A_k has dimensions dims[k] x dims[k+1]\n\n        for (int length = 2; length <= n; length++) { // length of subchain\n            for (int i = 0; i <= n - length; i++) { // starting matrix index\n                int j = i + length - 1; // ending matrix index\n                dp[i][j] = Integer.MAX_VALUE; // Initialize with infinity\n                for (int k = i; k < j; k++) { // split point\n                    // Cost to multiply (A_i...A_k) and (A_{k+1}...A_j)\n                    // is dp[i][k] + dp[k+1][j] + (dims[i] * dims[k+1] * dims[j+1])\n                    int cost = dims[i] * dims[k + 1] * dims[j + 1];\n                    dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k + 1][j] + cost);\n                }\n            }\n        }\n        return dp[0][n - 1];\n    }\n}''inf'')\n    //             for k in range(i, j):\n    //                 cost = dp[i][k] + dp[k + 1][j] + dims[i] * dims[k + 1] * dims[j + 1]\n    //                 dp[i][j] = min(dp[i][j], cost)\n    // \n    //     return dp[0][n - 1]\n    // \n    // \n}',
  E'/**\n * @param {any} dims\n * @return {any}\n */\nfunction mcm(dims) {\n    // Your code here\n}',
  E'function mcm(dims) {\n    const n = dims.length - 1; // number of matrices\n    const dp = Array(n).fill(0).map(() => Array(n).fill(0));\n\n    // dp[i][j] stores the minimum scalar multiplications needed to multiply matrices A_i through A_j.\n    // Matrix A_k has dimensions dims[k] x dims[k+1]\n\n    for (let length = 2; length <= n; length++) { // length of subchain\n        for (let i = 0; i <= n - length; i++) { // starting matrix index\n            const j = i + length - 1; // ending matrix index\n            dp[i][j] = Infinity; // Initialize with infinity\n            for (let k = i; k < j; k++) { // split point\n                // Cost to multiply (A_i...A_k) and (A_{k+1}...A_j)\n                // is dp[i][k] + dp[k+1][j] + (dims[i] * dims[k+1] * dims[j+1])\n                const cost = dims[i] * dims[k + 1] * dims[j + 1];\n                dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k + 1][j] + cost);\n            }\n        }\n    }\n    return dp[0][n - 1];\n}',
  ARRAY['mcm-pattern'],
  ARRAY['generic'],
  'mcm-pattern',
  '[{"input":"mcm([1, 2, 3, 4])","expected_output":"18"},{"input":"mcm([10, 30, 5, 60])","expected_output":"4500"},{"input":"mcm([40, 20, 30, 10, 30])","expected_output":"26000"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
