INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-burst-balloons',
  'Burst Balloons',
  'easy',
  'Burst Balloons

Problem Statement

Given `n` balloons with numbers on them, bursting balloon `i` earns `nums[i-1] × nums[i] × nums[i+1]` coins. After bursting, the adjacent balloons become neighbors. Find the **maximum coins** collectible.

Examples',
  '',
  '[{"input":"[3, 1, 5, 8]","output":"167","explanation":"Burst order: 1→5→3→8"}]'::jsonb,
  'max_coins',
  E'def max_coins(nums):\n    # TODO: find maximum coins from bursting balloons\n    pass',
  E'def max_coins(nums):\n    # Pad with 1s\n    balls = [1] + nums + [1]\n    n = len(balls)\n    dp = [[0] * n for _ in range(n)]\n\n    for length in range(2, n):\n        for i in range(n - length):\n            j = i + length\n            for k in range(i + 1, j):\n                coins = balls[i] * balls[k] * balls[j]\n                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + coins)\n    return dp[0][n - 1]',
  E'class Solution {\n    public Object maxCoins(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int maxCoins(int[] nums) {\n        // Pad with 1s\n        int n = nums.length;\n        int[] balls = new int[n + 2];\n        balls[0] = 1;\n        balls[n + 1] = 1;\n        for (int i = 0; i < n; i++) {\n            balls[i + 1] = nums[i];\n        }\n\n        int totalBalls = balls.length;\n        int[][] dp = new int[totalBalls][totalBalls];\n\n        for (int length = 2; length < totalBalls; length++) {\n            for (int i = 0; i < totalBalls - length; i++) {\n                int j = i + length;\n                for (int k = i + 1; k < j; k++) {\n                    int coins = balls[i] * balls[k] * balls[j];\n                    dp[i][j] = Math.max(dp[i][j], dp[i][k] + dp[k][j] + coins);\n                }\n            }\n        }\n        return dp[0][totalBalls - 1];\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction maxCoins(nums) {\n    // Your code here\n}',
  E'function maxCoins(nums) {\n    // Pad with 1s\n    const balls = [1, ...nums, 1];\n    const n = balls.length;\n    const dp = Array(n).fill(0).map(() => Array(n).fill(0));\n\n    for (let length = 2; length < n; length++) {\n        for (let i = 0; i < n - length; i++) {\n            const j = i + length;\n            for (let k = i + 1; k < j; k++) {\n                const coins = balls[i] * balls[k] * balls[j];\n                dp[i][j] = Math.max(dp[i][j], dp[i][k] + dp[k][j] + coins);\n            }\n        }\n    }\n    return dp[0][n - 1];\n}',
  ARRAY['mcm-pattern'],
  ARRAY['generic'],
  'mcm-pattern',
  '[{"input":"max_coins([3, 1, 5, 8])","expected_output":"167"},{"input":"max_coins([1, 5])","expected_output":"10"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
