INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-minimum-cost-merge-stones',
  'Minimum Cost to Merge Stones',
  'medium',
  'Minimum Cost to Merge Stones

Problem Statement

There are `n` piles of stones in a row. Each turn, you merge **2 adjacent piles** into one. The cost of a merge is the **total number of stones** in the two piles. Find the **minimum total cost** to merge all piles into one.

Examples',
  '',
  '[{"input":"[4, 1, 3, 2]","output":"20","explanation":"Merge [1,3] → cost 4, piles = [4, 4, 2]"}]'::jsonb,
  'merge_stones',
  E'def merge_stones(stones):\n    # TODO: find minimum cost to merge all piles\n    pass',
  E'def merge_stones(stones):\n    n = len(stones)\n    if n == 1:\n        return 0\n\n    # Prefix sums for range sum queries\n    prefix = [0] * (n + 1)\n    for i in range(n):\n        prefix[i + 1] = prefix[i] + stones[i]\n    dp = [[0] * n for _ in range(n)]\n    for length in range(2, n + 1):\n        for i in range(n - length + 1):\n            j = i + length - 1\n            dp[i][j] = float(''inf'')\n            range_sum = prefix[j + 1] - prefix[i]\n            for k in range(i, j):\n                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j] + range_sum)\n    return dp[0][n - 1]',
  E'class Solution {\n    public Object mergeStones(Object stones) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int mergeStones(int[] stones) {\n        int n = stones.length;\n        if (n == 1) {\n            return 0;\n        }\n\n        // Prefix sums for range sum queries\n        int[] prefix = new int[n + 1];\n        for (int i = 0; i < n; i++) {\n            prefix[i + 1] = prefix[i] + stones[i];\n        }\n\n        // dp[i][j] stores the minimum cost to merge stones from index i to j\n        int[][] dp = new int[n][n];\n\n        // length is the number of stones in the current subproblem\n        for (int length = 2; length <= n; length++) {\n            // i is the starting index of the subproblem\n            for (int i = 0; i <= n - length; i++) {\n                int j = i + length - 1; // j is the ending index of the subproblem\n\n                dp[i][j] = Integer.MAX_VALUE; // Initialize with infinity\n\n                // k is the split point: merge stones[i...k] and stones[k+1...j]\n                for (int k = i; k < j; k++) {\n                    // Check for overflow before adding, if subproblems are unreachable\n                    // In this problem, all subproblems are reachable, so dp[i][k] and dp[k+1][j]\n                    // will eventually be finite. The check is mainly for preventing sum overflow\n                    // if one of them is MAX_VALUE.\n                    if (dp[i][k] != Integer.MAX_VALUE && dp[k + 1][j] != Integer.MAX_VALUE) {\n                        dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k + 1][j]);\n                    }\n                }\n\n                // Add the cost of merging the current range [i, j]\n                // This cost is the sum of all stones in this range\n                if (dp[i][j] != Integer.MAX_VALUE) { // Only add cost if a valid merge path was found\n                    dp[i][j] += prefix[j + 1] - prefix[i];\n                }\n            }\n        }\n        return dp[0][n - 1];\n    }\n}''inf'')\n    //             range_sum = prefix[j + 1] - prefix[i]\n    //             for k in range(i, j):\n    //                 dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j] + range_sum)\n    // \n    //     return dp[0][n - 1]\n    // \n    // \n}',
  E'/**\n * @param {any} stones\n * @return {any}\n */\nfunction mergeStones(stones) {\n    // Your code here\n}',
  E'function mergeStones(stones) {\n    const n = stones.length;\n    if (n === 1) {\n        return 0;\n    }\n\n    // Prefix sums for range sum queries\n    const prefix = new Array(n + 1).fill(0);\n    for (let i = 0; i < n; i++) {\n        prefix[i + 1] = prefix[i] + stones[i];\n    }\n\n    // dp[i][j] stores the minimum cost to merge stones from index i to j\n    const dp = Array(n).fill(0).map(() => Array(n).fill(0));\n\n    // length is the number of stones in the current subproblem\n    for (let length = 2; length <= n; length++) {\n        // i is the starting index of the subproblem\n        for (let i = 0; i <= n - length; i++) {\n            const j = i + length - 1; // j is the ending index of the subproblem\n\n            dp[i][j] = Infinity; // Initialize with infinity\n\n            // k is the split point: merge stones[i...k] and stones[k+1...j]\n            for (let k = i; k < j; k++) {\n                dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k + 1][j]);\n            }\n\n            // Add the cost of merging the current range [i, j]\n            // This cost is the sum of all stones in this range\n            if (dp[i][j] !== Infinity) { // Only add cost if a valid merge path was found\n                dp[i][j] += prefix[j + 1] - prefix[i];\n            }\n        }\n    }\n    return dp[0][n - 1];\n}',
  ARRAY['mcm-pattern'],
  ARRAY['generic'],
  'mcm-pattern',
  '[{"input":"merge_stones([4, 1, 3, 2])","expected_output":"20"},{"input":"merge_stones([1, 2, 3, 4])","expected_output":"19"},{"input":"merge_stones([3, 5])","expected_output":"8"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
