INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-boolean-parenthesization',
  'Boolean Parenthesization',
  'medium',
  'Boolean Parenthesization

Problem Statement

Given a boolean expression with symbols `T` (True) and `F` (False), and operators `&` (AND), `|` (OR), `^` (XOR), count the number of ways to **parenthesize** the expression so that it evaluates to **True**.

Examples',
  '',
  '[{"input":"symbols = \"TFT\", operators = \"|&\"","output":"1","explanation":"Only (T|F)&T = T"},{"input":"symbols = \"TTFT\", operators = \"|&^\"","output":"4"}]'::jsonb,
  'count_eval',
  E'def count_eval(symbols, operators):\n    # TODO: count ways to parenthesize for True\n    pass',
  E'def count_eval(symbols, operators):\n    n = len(symbols)\n    true_dp = [[0] * n for _ in range(n)]\n    false_dp = [[0] * n for _ in range(n)]\n\n    # Base case: single symbols\n    for i in range(n):\n        true_dp[i][i] = 1 if symbols[i] == ''T'' else 0\n        false_dp[i][i] = 1 if symbols[i] == ''F'' else 0\n    for length in range(2, n + 1):\n        for i in range(n - length + 1):\n            j = i + length - 1\n            for k in range(i, j):\n                op = operators[k]\n                lt, lf = true_dp[i][k], false_dp[i][k]\n                rt, rf = true_dp[k + 1][j], false_dp[k + 1][j]\n                if op == ''&'':\n                    true_dp[i][j] += lt * rt\n                    false_dp[i][j] += lt * rf + lf * rt + lf * rf\n                elif op == ''|'':\n                    true_dp[i][j] += lt * rt + lt * rf + lf * rt\n                    false_dp[i][j] += lf * rf\n                elif op == ''^'':\n                    true_dp[i][j] += lt * rf + lf * rt\n                    false_dp[i][j] += lt * rt + lf * rf\n    return true_dp[0][n - 1]',
  E'class Solution {\n    public Object countEval(Object symbols, Object operators) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports: java.util.* (not strictly needed for this problem, but good practice for general DP)\n    public static int countEval(String symbols, String operators) {\n        int n = symbols.length();\n        int[][] trueDp = new int[n][n];\n        int[][] falseDp = new int[n][n];\n\n        // Base case: single symbols\n        for (int i = 0; i < n; i++) {\n            if (symbols.charAt(i) == \'T\') {\n                trueDp[i][i] = 1;\n            } else {\n                falseDp[i][i] = 1;\n            }\n        }\n\n        // Fill DP tables for lengths from 2 to n\n        for (int length = 2; length <= n; length++) {\n            for (int i = 0; i <= n - length; i++) {\n                int j = i + length - 1;\n                for (int k = i; k < j; k++) { // k is the split point\n                    char op = operators.charAt(k);\n                    // Ways to make left part true/false\n                    int leftTrue = trueDp[i][k];\n                    int leftFalse = falseDp[i][k];\n                    // Ways to make right part true/false\n                    int rightTrue = trueDp[k + 1][j];\n                    int rightFalse = falseDp[k + 1][j];\n\n                    if (op == \'&\') {\n                        trueDp[i][j] += leftTrue * rightTrue;\n                        falseDp[i][j] += leftTrue * rightFalse + leftFalse * rightTrue + leftFalse * rightFalse;\n                    } else if (op == \'|\') {\n                        trueDp[i][j] += leftTrue * rightTrue + leftTrue * rightFalse + leftFalse * rightTrue;\n                        falseDp[i][j] += leftFalse * rightFalse;\n                    } else if (op == \'^\') { // XOR\n                        trueDp[i][j] += leftTrue * rightFalse + leftFalse * rightTrue;\n                        falseDp[i][j] += leftTrue * rightTrue + leftFalse * rightFalse;\n                    }\n                }\n            }\n        }\n        \n        return trueDp[0][n - 1];\n    }\n}''T'' else 0\n    //         false_dp[i][i] = 1 if symbols[i] == ''F'' else 0\n    // \n    //     for length in range(2, n + 1):\n    //         for i in range(n - length + 1):\n    //             j = i + length - 1\n    //             for k in range(i, j):\n    //                 op = operators[k]\n    //                 lt, lf = true_dp[i][k], false_dp[i][k]\n    //                 rt, rf = true_dp[k + 1][j], false_dp[k + 1][j]\n    // \n    //                 if op == ''&'':\n    //                     true_dp[i][j] += lt * rt\n    //                     false_dp[i][j] += lt * rf + lf * rt + lf * rf\n    //                 elif op == ''|'':\n    //                     true_dp[i][j] += lt * rt + lt * rf + lf * rt\n    //                     false_dp[i][j] += lf * rf\n    //                 elif op == ''^'':\n    //                     true_dp[i][j] += lt * rf + lf * rt\n    //                     false_dp[i][j] += lt * rt + lf * rf\n    // \n    //     return true_dp[0][n - 1]\n    // \n    // \n}',
  E'/**\n * @param {any, any} symbols, operators\n * @return {any}\n */\nfunction countEval(symbols, operators) {\n    // Your code here\n}',
  E'function countEval(symbols, operators) {\n    const n = symbols.length;\n    const trueDp = Array(n).fill(0).map(() => Array(n).fill(0));\n    const falseDp = Array(n).fill(0).map(() => Array(n).fill(0));\n\n    // Base case: single symbols\n    for (let i = 0; i < n; i++) {\n        if (symbols[i] === \'T\') {\n            trueDp[i][i] = 1;\n        } else {\n            falseDp[i][i] = 1;\n        }\n    }\n\n    // Fill DP tables for lengths from 2 to n\n    for (let length = 2; length <= n; length++) {\n        for (let i = 0; i <= n - length; i++) {\n            const j = i + length - 1;\n            for (let k = i; k < j; k++) { // k is the split point\n                const op = operators[k];\n                // Ways to make left part true/false\n                const leftTrue = trueDp[i][k];\n                const leftFalse = falseDp[i][k];\n                // Ways to make right part true/false\n                const rightTrue = trueDp[k + 1][j];\n                const rightFalse = falseDp[k + 1][j];\n\n                if (op === \'&\') {\n                    trueDp[i][j] += leftTrue * rightTrue;\n                    falseDp[i][j] += leftTrue * rightFalse + leftFalse * rightTrue + leftFalse * rightFalse;\n                } else if (op === \'|\') {\n                    trueDp[i][j] += leftTrue * rightTrue + leftTrue * rightFalse + leftFalse * rightTrue;\n                    falseDp[i][j] += leftFalse * rightFalse;\n                } else if (op === \'^\') { // XOR\n                    trueDp[i][j] += leftTrue * rightFalse + leftFalse * rightTrue;\n                    falseDp[i][j] += leftTrue * rightTrue + leftFalse * rightFalse;\n                }\n            }\n        }\n    }\n    \n    return trueDp[0][n - 1];\n}',
  ARRAY['mcm-pattern'],
  ARRAY['generic'],
  'mcm-pattern',
  '[{"input":"count_eval(\"TFT\", \"|&\")","expected_output":"1"},{"input":"count_eval(\"TTFT\", \"|&^\")","expected_output":"4"},{"input":"count_eval(\"TF\", \"^\")","expected_output":"1"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
