INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-edit-distance',
  'Edit Distance',
  'easy',
  'Edit Distance (Levenshtein Distance)

Problem Statement

Given two strings `s1` and `s2`, find the **minimum number of operations** (insert, delete, replace) to transform `s1` into `s2`.

Examples',
  '',
  '[{"input":"s1 = \"horse\", s2 = \"ros\"","output":"3","explanation":"horse → rorse (replace h→r) → rose (delete r) → ros (delete e)"},{"input":"s1 = \"intention\", s2 = \"execution\"","output":"5"}]'::jsonb,
  'edit_distance',
  E'def edit_distance(s1, s2):\n    # TODO: find minimum edit distance\n    pass',
  E'def edit_distance(s1, s2):\n    n, m = len(s1), len(s2)\n    dp = [[0] * (m + 1) for _ in range(n + 1)]\n\n    # Base cases\n    for i in range(n + 1):\n        dp[i][0] = i\n    for j in range(m + 1):\n        dp[0][j] = j\n    for i in range(1, n + 1):\n        for j in range(1, m + 1):\n            if s1[i - 1] == s2[j - 1]:\n                dp[i][j] = dp[i - 1][j - 1]\n            else:\n                dp[i][j] = 1 + min(\n                    dp[i - 1][j],      # delete\n                    dp[i][j - 1],      # insert\n                    dp[i - 1][j - 1]   # replace\n                )\n    return dp[n][m]',
  E'class Solution {\n    public Object editDistance(Object s1, Object s2) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int editDistance(String s1, String s2) {\n        int n = s1.length();\n        int m = s2.length();\n        int[][] dp = new int[n + 1][m + 1];\n\n        // Base cases\n        for (int i = 0; i <= n; i++) {\n            dp[i][0] = i;\n        }\n        for (int j = 0; j <= m; j++) {\n            dp[0][j] = j;\n        }\n\n        for (int i = 1; i <= n; i++) {\n            for (int j = 1; j <= m; j++) {\n                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {\n                    dp[i][j] = dp[i - 1][j - 1];\n                } else {\n                    dp[i][j] = 1 + Math.min(\n                        dp[i - 1][j],      // delete\n                        Math.min(dp[i][j - 1],      // insert\n                                 dp[i - 1][j - 1])   // replace\n                    );\n                }\n            }\n        }\n        return dp[n][m];\n    }\n}',
  E'/**\n * @param {any, any} s1, s2\n * @return {any}\n */\nfunction editDistance(s1, s2) {\n    // Your code here\n}',
  E'function editDistance(s1, s2) {\n    const n = s1.length;\n    const m = s2.length;\n    const dp = Array(n + 1).fill(0).map(() => Array(m + 1).fill(0));\n\n    // Base cases\n    for (let i = 0; i <= n; i++) {\n        dp[i][0] = i;\n    }\n    for (let j = 0; j <= m; j++) {\n        dp[0][j] = j;\n    }\n\n    for (let i = 1; i <= n; i++) {\n        for (let j = 1; j <= m; j++) {\n            if (s1[i - 1] === s2[j - 1]) {\n                dp[i][j] = dp[i - 1][j - 1];\n            } else {\n                dp[i][j] = 1 + Math.min(\n                    dp[i - 1][j],      // delete\n                    dp[i][j - 1],      // insert\n                    dp[i - 1][j - 1]   // replace\n                );\n            }\n        }\n    }\n    return dp[n][m];\n}',
  ARRAY['dp-strings-pattern', 'strings', 'dynamic-programming'],
  ARRAY['generic'],
  'dp-strings-pattern',
  '[{"input":"edit_distance(\"horse\", \"ros\")","expected_output":"3"},{"input":"edit_distance(\"intention\", \"execution\")","expected_output":"5"},{"input":"edit_distance(\"\", \"abc\")","expected_output":"3"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
