INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-string-interleaving',
  'String Interleaving',
  'easy',
  'String Interleaving

Problem Statement

Given three strings `s1`, `s2`, and `s3`, determine if `s3` is formed by an **interleaving** of `s1` and `s2`. An interleaving preserves the relative order of characters from each string.

Examples',
  '',
  '[{"input":"s1 = \"aab\", s2 = \"axy\", s3 = \"aaxaby\"","output":"True"},{"input":"s1 = \"aab\", s2 = \"axy\", s3 = \"abaaxy\"","output":"False"}]'::jsonb,
  'is_interleave',
  E'def is_interleave(s1, s2, s3):\n    # TODO: check if s3 is an interleaving of s1 and s2\n    pass',
  E'def is_interleave(s1, s2, s3):\n    n, m = len(s1), len(s2)\n    if n + m != len(s3):\n        return False\n\n    dp = [[False] * (m + 1) for _ in range(n + 1)]\n    dp[0][0] = True\n    # Fill first column (using s1 only)\n    for i in range(1, n + 1):\n        dp[i][0] = dp[i - 1][0] and s1[i - 1] == s3[i - 1]\n    # Fill first row (using s2 only)\n    for j in range(1, m + 1):\n        dp[0][j] = dp[0][j - 1] and s2[j - 1] == s3[j - 1]\n    for i in range(1, n + 1):\n        for j in range(1, m + 1):\n            k = i + j - 1\n            dp[i][j] = (dp[i - 1][j] and s1[i - 1] == s3[k]) or \\\n                        (dp[i][j - 1] and s2[j - 1] == s3[k])\n    return dp[n][m]',
  E'class Solution {\n    public Object isInterleave(Object s1, Object s2, Object s3) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static boolean isInterleave(String s1, String s2, String s3) {\n        int n = s1.length();\n        int m = s2.length();\n        if (n + m != s3.length()) {\n            return false;\n        }\n\n        boolean[][] dp = new boolean[n + 1][m + 1];\n        dp[0][0] = true;\n\n        // Fill first column (using s1 only)\n        for (int i = 1; i <= n; i++) {\n            dp[i][0] = dp[i - 1][0] && (s1.charAt(i - 1) == s3.charAt(i - 1));\n        }\n        // Fill first row (using s2 only)\n        for (int j = 1; j <= m; j++) {\n            dp[0][j] = dp[0][j - 1] && (s2.charAt(j - 1) == s3.charAt(j - 1));\n        }\n\n        for (int i = 1; i <= n; i++) {\n            for (int j = 1; j <= m; j++) {\n                int k = i + j - 1;\n                dp[i][j] = (dp[i - 1][j] && (s1.charAt(i - 1) == s3.charAt(k))) ||\n                           (dp[i][j - 1] && (s2.charAt(j - 1) == s3.charAt(k)));\n            }\n        }\n        return dp[n][m];\n    }\n}',
  E'/**\n * @param {any, any, any} s1, s2, s3\n * @return {any}\n */\nfunction isInterleave(s1, s2, s3) {\n    // Your code here\n}',
  E'function isInterleave(s1, s2, s3) {\n    const n = s1.length;\n    const m = s2.length;\n    if (n + m !== s3.length) {\n        return false;\n    }\n\n    const dp = Array(n + 1).fill(0).map(() => Array(m + 1).fill(false));\n    dp[0][0] = true;\n\n    // Fill first column (using s1 only)\n    for (let i = 1; i <= n; i++) {\n        dp[i][0] = dp[i - 1][0] && (s1[i - 1] === s3[i - 1]);\n    }\n    // Fill first row (using s2 only)\n    for (let j = 1; j <= m; j++) {\n        dp[0][j] = dp[0][j - 1] && (s2[j - 1] === s3[j - 1]);\n    }\n\n    for (let i = 1; i <= n; i++) {\n        for (let j = 1; j <= m; j++) {\n            const k = i + j - 1;\n            dp[i][j] = (dp[i - 1][j] && (s1[i - 1] === s3[k])) ||\n                       (dp[i][j - 1] && (s2[j - 1] === s3[k]));\n        }\n    }\n    return dp[n][m];\n}',
  ARRAY['dp-strings-pattern', 'strings', 'dynamic-programming'],
  ARRAY['generic'],
  'dp-strings-pattern',
  '[{"input":"is_interleave(\"aab\", \"axy\", \"aaxaby\")","expected_output":"True"},{"input":"is_interleave(\"aab\", \"axy\", \"abaaxy\")","expected_output":"False"},{"input":"is_interleave(\"\", \"\", \"\")","expected_output":"True"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
  description = EXCLUDED.description,
  constraints = EXCLUDED.constraints,
  examples = EXCLUDED.examples,
  function_name = EXCLUDED.function_name,
  starter_code_python = EXCLUDED.starter_code_python,
  solution_code_python = EXCLUDED.solution_code_python,
  starter_code_java = EXCLUDED.starter_code_java,
  solution_code_java = EXCLUDED.solution_code_java,
  starter_code_js = EXCLUDED.starter_code_js,
  solution_code_js = EXCLUDED.solution_code_js,
  topics = EXCLUDED.topics,
  company_tags = EXCLUDED.company_tags,
