INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-longest-alternating-subsequence',
  'Longest Alternating Subsequence',
  'medium',
  'Longest Alternating Subsequence

Problem Statement

Given an array of integers, find the length of the **longest alternating subsequence** (LAS). A subsequence is alternating if its elements alternate between increasing and decreasing: `a[0] < a[1] > a[2] < a[3] > ...` or `a[0] > a[1] < a[2] > a[3] < ...`

Examples',
  '',
  '[{"input":"[1, 5, 4]","output":"3","explanation":"[1, 5, 4] — goes up then down"},{"input":"[1, 2, 3, 4]","output":"2","explanation":"[1, 4] or any pair — only one direction change"},{"input":"[3, 5, 6, 2, 5, 4, 19, 5, 6, 7, 12]","output":"7"}]'::jsonb,
  'las',
  E'def las(nums):\n    # TODO: find length of longest alternating subsequence\n    pass',
  E'def las(nums):\n    if len(nums) < 2:\n        return len(nums)\n\n    # Greedy O(n) approach\n    up = 1    # length of LAS ending with an up move\n    down = 1  # length of LAS ending with a down move\n    for i in range(1, len(nums)):\n        if nums[i] > nums[i - 1]:\n            up = down + 1\n        elif nums[i] < nums[i - 1]:\n            down = up + 1\n    return max(up, down)',
  E'class Solution {\n    public Object las(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int las(int[] nums) {\n        if (nums.length < 2) {\n            return nums.length;\n        }\n\n        // Greedy O(n) approach\n        int up = 1;    // length of LAS ending with an up move\n        int down = 1;  // length of LAS ending with a down move\n        for (int i = 1; i < nums.length; i++) {\n            if (nums[i] > nums[i - 1]) {\n                up = down + 1;\n            } else if (nums[i] < nums[i - 1]) {\n                down = up + 1;\n            }\n            // If nums[i] == nums[i-1], both up and down remain unchanged\n        }\n        return Math.max(up, down);\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction las(nums) {\n    // Your code here\n}',
  E'function las(nums) {\n    if (nums.length < 2) {\n        return nums.length;\n    }\n\n    // Greedy O(n) approach\n    let up = 1;    // length of LAS ending with an up move\n    let down = 1;  // length of LAS ending with a down move\n    for (let i = 1; i < nums.length; i++) {\n        if (nums[i] > nums[i - 1]) {\n            up = down + 1;\n        } else if (nums[i] < nums[i - 1]) {\n            down = up + 1;\n        }\n        // If nums[i] === nums[i-1], both up and down remain unchanged\n    }\n    return Math.max(up, down);\n}',
  ARRAY['dp-strings-pattern', 'strings', 'dynamic-programming'],
  ARRAY['generic'],
  'dp-strings-pattern',
  '[{"input":"las([1, 5, 4])","expected_output":"3"},{"input":"las([1, 2, 3, 4])","expected_output":"2"},{"input":"las([3, 5, 6, 2, 5, 4, 19, 5, 6, 7, 12])","expected_output":"7"}]'::jsonb,
  '[]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  difficulty = EXCLUDED.difficulty,
