INSERT INTO interview_problems (slug, title, difficulty, description, constraints, examples, function_name, starter_code_python, solution_code_python, starter_code_java, solution_code_java, starter_code_js, solution_code_js, topics, company_tags, pattern, test_cases_visible, test_cases_hidden) VALUES (
  'dp-patterns-egg-dropping',
  'Egg Dropping Problem',
  'medium',
  'Egg Dropping Problem

Problem Statement

Given `k` eggs and a building with `n` floors, find the **minimum number of trials** needed to determine the **critical floor** (the highest floor from which an egg can be dropped without breaking), in the **worst case**.

Examples',
  '',
  '[{"input":"eggs = 1, floors = 10","output":"10","explanation":"Must try every floor from bottom up"},{"input":"eggs = 2, floors = 10","output":"4","explanation":"Try floors 4, 7, 9, 10 (optimal strategy)"}]'::jsonb,
  'egg_drop',
  E'def egg_drop(eggs, floors):\n    # TODO: find minimum trials in worst case\n    pass',
  E'def egg_drop(eggs, floors):\n    # dp[k][n] = min trials with k eggs and n floors\n    dp = [[0] * (floors + 1) for _ in range(eggs + 1)]\n\n    # Base cases\n    for n in range(1, floors + 1):\n        dp[1][n] = n  # 1 egg: must try every floor\n    for k in range(1, eggs + 1):\n        dp[k][0] = 0  # 0 floors: 0 trials\n        dp[k][1] = 1  # 1 floor: 1 trial\n    for k in range(2, eggs + 1):\n        for n in range(2, floors + 1):\n            dp[k][n] = float(''inf'')\n            # Binary search for optimal floor\n            lo, hi = 1, n\n            while lo <= hi:\n                mid = (lo + hi) // 2\n                breaks = dp[k - 1][mid - 1]\n                survives = dp[k][n - mid]\n                worst = 1 + max(breaks, survives)\n                dp[k][n] = min(dp[k][n], worst)\n                if breaks < survives:\n                    lo = mid + 1\n                elif breaks > survives:\n                    hi = mid - 1\n                else:\n                    break\n    return dp[eggs][floors]',
  E'class Solution {\n    public Object eggDrop(Object eggs, Object floors) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static int eggDrop(int eggs, int floors) {\n        // dp[k][n] = min trials with k eggs and n floors\n        int[][] dp = new int[eggs + 1][floors + 1];\n\n        // Base cases\n        // 1 egg: must try every floor\n        for (int n = 1; n <= floors; n++) {\n            dp[1][n] = n;\n        }\n        // 0 floors: 0 trials\n        // 1 floor: 1 trial\n        for (int k = 1; k <= eggs; k++) {\n            dp[k][0] = 0;\n            dp[k][1] = 1;\n        }\n\n        for (int k = 2; k <= eggs; k++) {\n            for (int n = 2; n <= floors; n++) {\n                dp[k][n] = Integer.MAX_VALUE;\n                // Try dropping from each floor x from 1 to n\n                for (int x = 1; x <= n; x++) {\n                    // If egg breaks at floor x: k-1 eggs, x-1 floors below\n                    // If egg doesn\'t break at floor x: k eggs, n-x floors above\n                    int res = Math.max(dp[k - 1][x - 1], dp[k][n - x]) + 1;\n                    dp[k][n] = Math.min(dp[k][n], res);\n                }\n            }\n        }\n        return dp[eggs][floors];\n    }\n}''inf'')\n    //             # Binary search for optimal floor\n    //             lo, hi = 1, n\n    //             while lo <= hi:\n    //                 mid = (lo + hi) // 2\n    //                 breaks = dp[k - 1][mid - 1]\n    //                 survives = dp[k][n - mid]\n    //                 worst = 1 + max(breaks, survives)\n    //                 dp[k][n] = min(dp[k][n], worst)\n    //                 if breaks < survives:\n    //                     lo = mid + 1\n    //                 elif breaks > survives:\n    //                     hi = mid - 1\n    //                 else:\n    //                     break\n    // \n    //     return dp[eggs][floors]\n    // \n    // \n}',
  E'/**\n * @param {any, any} eggs, floors\n * @return {any}\n */\nfunction eggDrop(eggs, floors) {\n    // Your code here\n}',
  E'function eggDrop(eggs, floors) {\n    // dp[k][n] = min trials with k eggs and n floors\n    const dp = Array.from({ length: eggs + 1 }, () => Array(floors + 1).fill(0));\n\n    // Base cases\n    // 1 egg: must try every floor\n    for (let n = 1; n <= floors; n++) {\n        dp[1][n] = n;\n    }\n    // 0 floors: 0 trials\n    // 1 floor: 1 trial\n    for (let k = 1; k <= eggs; k++) {\n        dp[k][0] = 0;\n        dp[k][1] = 1;\n    }\n\n    for (let k = 2; k <= eggs; k++) {\n        for (let n = 2; n <= floors; n++) {\n            dp[k][n] = Number.POSITIVE_INFINITY;\n            // Try dropping from each floor x from 1 to n\n            for (let x = 1; x <= n; x++) {\n                // If egg breaks at floor x: k-1 eggs, x-1 floors below\n                // If egg doesn\'t break at floor x: k eggs, n-x floors above\n                const res = Math.max(dp[k - 1][x - 1], dp[k][n - x]) + 1;\n                dp[k][n] = Math.min(dp[k][n], res);\n            }\n        }\n    }\n    return dp[eggs][floors];\n}',
  ARRAY['dp-strings-pattern', 'strings', 'dynamic-programming'],
