  'subarray_sum_k',
  E'def subarray_sum_k(nums: list[int], k: int) -> int:\n    """\n    Count the number of contiguous subarrays that sum to k.\n\n    Approach: Prefix sum + hash map.\n    Time: O(n), Space: O(n)\n    """\n    # TODO: Initialize count = 0, running prefix_sum = 0\n    # TODO: Use a dict to track frequency of each prefix_sum seen\n    # TODO: Start with {0: 1} (empty prefix)\n    # TODO: For each num, update prefix_sum\n    # TODO: If (prefix_sum - k) exists in dict, add its count\n    # TODO: Add current prefix_sum to dict\n    pass\ndef range_update(length: int, updates: list[list[int]]) -> list[int]:\n    """\n    Given an array of zeros with given length, apply range updates.\n    Each update is [start, end, value] — add value to all elements\n    from index start to end (inclusive).\n\n    Return the final array after all updates.\n    Approach: Difference array.\n    Time: O(n + u) where u = number of updates\n    """\n    # TODO: Create difference array of zeros\n    # TODO: For each update [l, r, v]: diff[l] += v, diff[r+1] -= v\n    # TODO: Compute prefix sum of diff array to get result\n    pass\n# [-2, 0, 3, 5, 3]',
  E'def subarray_sum_k(nums: list[int], k: int) -> int:\n    """\n    Count the number of contiguous subarrays that sum to k.\n\n    Approach: Prefix sum + hash map.\n    Time: O(n), Space: O(n)\n    """\n    count = 0\n    prefix_sum = 0\n    # Map from prefix_sum value to how many times we''ve seen it\n    seen = {0: 1}  # Empty prefix has sum 0\n    for num in nums:\n        prefix_sum += num\n        # If (prefix_sum - k) was a previous prefix sum,\n        # then the subarray between them sums to k\n        if prefix_sum - k in seen:\n            count += seen[prefix_sum - k]\n        # Record this prefix sum\n        seen[prefix_sum] = seen.get(prefix_sum, 0) + 1\n    return count\ndef range_update(length: int, updates: list[list[int]]) -> list[int]:\n    """\n    Given an array of zeros with given length, apply range updates.\n    Each update is [start, end, value] — add value to all elements\n    from index start to end (inclusive).\n\n    Return the final array after all updates.\n    Approach: Difference array.\n    Time: O(n + u) where u = number of updates\n    """\n    diff = [0] * (length + 1)  # Extra space for boundary\n    for start, end, val in updates:\n        diff[start] += val\n        if end + 1 < len(diff):\n            diff[end + 1] -= val\n    # Compute prefix sum to get final array\n    result = [0] * length\n    running = 0\n    for i in range(length):\n        running += diff[i]\n        result[i] = running\n    return result\n# [-2, 0, 3, 5, 3]',
  E'class Solution {\n    public Object subarraySumK(int[] nums, int k) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.Map;\n    // import java.util.HashMap;\n\n    public static int subarraySumK(int[] nums, int k) {\n        int count = 0;\n        int prefixSum = 0;\n        // Map from prefix_sum value to how many times we\'ve seen it\n        Map<Integer, Integer> prefixSumCounts = new HashMap<>();\n        prefixSumCounts.put(0, 1); // Represents an empty prefix sum before index 0\n\n        for (int num : nums) {\n            prefixSum += num;\n            // If (prefixSum - k) exists, it means there\'s a subarray ending here\n            // that sums to k. Add its frequency to count.\n            if (prefixSumCounts.containsKey(prefixSum - k)) {\n                count += prefixSumCounts.get(prefixSum - k);\n            }\n            // Add current prefixSum to the map\n            prefixSumCounts.put(prefixSum, prefixSumCounts.getOrDefault(prefixSum, 0) + 1);\n        }\n        return count;\n    }\n}''ve seen it\n    //     seen = {0: 1}  # Empty prefix has sum 0\n    // \n    //     for num in nums:\n    //         prefix_sum += num\n    //         # If (prefix_sum - k) was a previous prefix sum,\n    //         # then the subarray between them sums to k\n    //         if prefix_sum - k in seen:\n    //             count += seen[prefix_sum - k]\n    //         # Record this prefix sum\n    //         seen[prefix_sum] = seen.get(prefix_sum, 0) + 1\n    // \n    //     return count\n    // \n    // \n    // def range_update(length: int, updates: list[list[int]]) -> list[int]:\n    //     """\n    //     Given an array of zeros with given length, apply range updates.\n    //     Each update is [start, end, value] — add value to all elements\n    //     from index start to end (inclusive).\n    // \n    //     Return the final array after all updates.\n    // \n    //     Approach: Difference array.\n    //     Time: O(n + u) where u = number of updates\n    //     """\n    //     diff = [0] * (length + 1)  # Extra space for boundary\n    // \n    //     for start, end, val in updates:\n    //         diff[start] += val\n    //         if end + 1 < len(diff):\n    //             diff[end + 1] -= val\n    // \n    //     # Compute prefix sum to get final array\n    //     result = [0] * length\n    //     running = 0\n    //     for i in range(length):\n    //         running += diff[i]\n    //         result[i] = running\n    // \n    //     return result\n    // \n    // \n    // \n    // # [-2, 0, 3, 5, 3]\n    // \n}',
  E'/**\n * @param {any, any} nums, k\n * @return {any}\n */\nfunction subarraySumK(nums, k) {\n    // Your code here\n}',
  E'function subarraySumK(nums, k) {\n    let count = 0;\n    let prefixSum = 0;\n    // Map from prefix_sum value to how many times we\'ve seen it\n    const prefixSumCounts = new Map();\n    prefixSumCounts.set(0, 1); // Represents an empty prefix sum before index 0\n\n    for (const num of nums) {\n        prefixSum += num;\n        // If (prefixSum - k) exists, it means there\'s a subarray ending here\n        // that sums to k. Add its frequency to count.\n        if (prefixSumCounts.has(prefixSum - k)) {\n            count += prefixSumCounts.get(prefixSum - k);\n        }\n        // Add current prefixSum to the map\n        prefixSumCounts.set(prefixSum, (prefixSumCounts.get(prefixSum) || 0) + 1);\n    }\n    return count;\n}',
