  E'class HashMap:\n    """\n    Hash Map implementation using separate chaining.\n    """\n    def __init__(self, capacity: int = 8):\n        """Initialize with given capacity."""\n        # TODO: Set capacity and size\n        # TODO: Create bucket array (list of empty lists)\n        pass\n\n    def _hash(self, key) -> int:\n        """Compute bucket index for a key."""\n        # TODO: Return hash(key) % self.capacity\n        pass\n\n    def put(self, key, value) -> None:\n        """Insert or update a key-value pair."""\n        # TODO: Compute bucket index\n        # TODO: Search bucket for existing key — update if found\n        # TODO: If not found, append new pair and increment size\n        # TODO: Check load factor and resize if needed\n        pass\n\n    def get(self, key, default=None):\n        """Get value by key, return default if not found."""\n        # TODO: Compute bucket index\n        # TODO: Search bucket for key\n        # TODO: Return value if found, default otherwise\n        pass\n\n    def remove(self, key) -> bool:\n        """Remove a key-value pair. Return True if found."""\n        # TODO: Compute bucket index\n        # TODO: Search bucket for key\n        # TODO: Remove pair if found, decrement size, return True\n        # TODO: Return False if not found\n        pass\n\n    def _resize(self) -> None:\n        """Double capacity and rehash all entries."""\n        # TODO: Save old buckets\n        # TODO: Double capacity, reset size, create new buckets\n        # TODO: Re-insert all old pairs using put()\n        pass\n\n    def __len__(self) -> int:\n        return self.size\n\nhm = HashMap()\nhm.put("apple", 1)\nhm.put("banana", 2)\nhm.put("cherry", 3)\nhm.put("banana", 20)         # Update existing\nhm.remove("banana")\nfor i in range(20):\n    hm.put(f"key_{i}", i)',
  E'class HashMap:\n    """\n    Hash Map implementation using separate chaining.\n    """\n    def __init__(self, capacity: int = 8):\n        """Initialize with given capacity."""\n        self.capacity = capacity\n        self.size = 0\n        self.buckets = [[] for _ in range(capacity)]\n\n    def _hash(self, key) -> int:\n        """Compute bucket index for a key."""\n        return hash(key) % self.capacity\n\n    def put(self, key, value) -> None:\n        """Insert or update a key-value pair."""\n        idx = self._hash(key)\n        bucket = self.buckets[idx]\n\n        # Check if key already exists — update value\n        for i, (k, v) in enumerate(bucket):\n            if k == key:\n                bucket[i] = (key, value)\n                return\n        # Key not found — insert new pair\n        bucket.append((key, value))\n        self.size += 1\n        # Resize if load factor exceeds 0.75\n        if self.size / self.capacity > 0.75:\n            self._resize()\n    def get(self, key, default=None):\n        """Get value by key, return default if not found."""\n        idx = self._hash(key)\n        bucket = self.buckets[idx]\n\n        for k, v in bucket:\n            if k == key:\n                return v\n        return default\n    def remove(self, key) -> bool:\n        """Remove a key-value pair. Return True if found."""\n        idx = self._hash(key)\n        bucket = self.buckets[idx]\n\n        for i, (k, v) in enumerate(bucket):\n            if k == key:\n                bucket.pop(i)\n                self.size -= 1\n                return True\n        return False\n    def _resize(self) -> None:\n        """Double capacity and rehash all entries."""\n        old_buckets = self.buckets\n        self.capacity *= 2\n        self.size = 0\n        self.buckets = [[] for _ in range(self.capacity)]\n\n        # Re-insert all pairs from old buckets\n        for bucket in old_buckets:\n            for key, value in bucket:\n                self.put(key, value)\n    def __len__(self) -> int:\n        return self.size\n\nhm = HashMap()\nhm.put("apple", 1)\nhm.put("banana", 2)\nhm.put("cherry", 3)\nhm.put("banana", 20)         # Update existing\nhm.remove("banana")\nfor i in range(20):\n    hm.put(f"key_{i}", i)',
  E'class Solution {\n    public Object HashMap(int capacity) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.List;\n    // import java.util.ArrayList;\n    // import java.util.AbstractMap; // For SimpleEntry\n\n    public static class HashMap<K, V> {\n        private int capacity;\n        private int size;\n        private List<List<AbstractMap.SimpleEntry<K, V>>> buckets;\n\n        public HashMap() {\n            this(8);\n        }\n\n        public HashMap(int capacity) {\n            this.capacity = capacity;\n            this.size = 0;\n            this.buckets = new ArrayList<>(capacity);\n            for (int i = 0; i < capacity; i++) {\n                this.buckets.add(new ArrayList<>());\n            }\n        }\n\n        private int _hash(K key) {\n            return Math.abs(key.hashCode()) % this.capacity;\n        }\n\n        public void put(K key, V value) {\n            int idx = _hash(key);\n            List<AbstractMap.SimpleEntry<K, V>> bucket = this.buckets.get(idx);\n\n            // Check if key already exists — update value\n            for (int i = 0; i < bucket.size(); i++) {\n                if (bucket.get(i).getKey().equals(key)) {\n                    bucket.set(i, new AbstractMap.SimpleEntry<>(key, value));\n                    return;\n                }\n            }\n            // Key not found — insert new pair\n            bucket.add(new AbstractMap.SimpleEntry<>(key, value));\n            this.size++;\n            // Resize if load factor exceeds 0.75\n            if ((double) this.size / this.capacity > 0.75) {\n                this._resize();\n            }\n        }\n\n        public V get(K key) {\n            return get(key, null);\n        }\n\n        public V get(K key, V defaultValue) {\n            int idx = _hash(key);\n            List<AbstractMap.SimpleEntry<K, V>> bucket = this.buckets.get(idx);\n\n            for (AbstractMap.SimpleEntry<K, V> entry : bucket) {\n                if (entry.getKey().equals(key)) {\n                    return entry.getValue();\n                }\n            }\n            return defaultValue;\n        }\n\n        public boolean remove(K key) {\n            int idx = _hash(key);\n            List<AbstractMap.SimpleEntry<K, V>> bucket = this.buckets.get(idx);\n\n            for (int i = 0; i < bucket.size(); i++) {\n                if (bucket.get(i).getKey().equals(key)) {\n                    bucket.remove(i);\n                    this.size--;\n                    return true;\n                }\n            }\n            return false;\n        }\n\n        private void _resize() {\n            List<List<AbstractMap.SimpleEntry<K, V>>> oldBuckets = this.buckets;\n            this.capacity *= 2;\n            this.size = 0; // Size will be re-calculated during re-insertion\n            this.buckets = new ArrayList<>(this.capacity);\n            for (int i = 0; i < this.capacity; i++) {\n                this.buckets.add(new ArrayList<>());\n            }\n\n            // Re-insert all pairs from old buckets\n            for (List<AbstractMap.SimpleEntry<K, V>> bucket : oldBuckets) {\n                for (AbstractMap.SimpleEntry<K, V> entry : bucket) {\n                    this.put(entry.getKey(), entry.getValue());\n                }\n            }\n        }\n\n        public int size() {\n            return this.size;\n        }\n    }\n}',
  E'/**\n * @param {any} capacity\n * @return {any}\n */\nfunction HashMap(capacity) {\n    // Your code here\n}',
  E'function HashMap(capacity = 8) {\n    this.capacity = capacity;\n    this.size = 0;\n    this.buckets = Array.from({ length: capacity }, () => []);\n\n    this._hash = function(key) {\n        if (typeof key === \'string\') {\n            let hash = 0;\n            for (let i = 0; i < key.length; i++) {\n                hash = (hash << 5) - hash + key.charCodeAt(i);\n                hash |= 0; // Convert to 32bit integer\n            }\n            return Math.abs(hash) % this.capacity;\n        } else if (typeof key === \'number\') {\n            return Math.abs(key) % this.capacity;\n        }\n        // Fallback for other types, could be improved\n        return Math.abs(String(key).charCodeAt(0) || 0) % this.capacity;\n    };\n\n    this.put = function(key, value) {\n        const idx = this._hash(key);\n        const bucket = this.buckets[idx];\n\n        // Check if key already exists — update value\n        for (let i = 0; i < bucket.length; i++) {\n            if (bucket[i][0] === key) {\n                bucket[i][1] = value;\n                return;\n            }\n        }\n        // Key not found — insert new pair\n        bucket.push([key, value]);\n        this.size++;\n        // Resize if load factor exceeds 0.75\n        if (this.size / this.capacity > 0.75) {\n            this._resize();\n        }\n    };\n\n    this.get = function(key, defaultValue = null) {\n        const idx = this._hash(key);\n        const bucket = this.buckets[idx];\n\n        for (const [k, v] of bucket) {\n            if (k === key) {\n                return v;\n            }\n        }\n        return defaultValue;\n    };\n\n    this.remove = function(key) {\n        const idx = this._hash(key);\n        const bucket = this.buckets[idx];\n\n        for (let i = 0; i < bucket.length; i++) {\n            if (bucket[i][0] === key) {\n                bucket.splice(i, 1);\n                this.size--;\n                return true;\n            }\n        }\n        return false;\n    };\n\n    this._resize = function() {\n        const oldBuckets = this.buckets;\n        this.capacity *= 2;\n        this.size = 0; // Size will be re-calculated during re-insertion\n        this.buckets = Array.from({ length: this.capacity }, () => []);\n\n        // Re-insert all pairs from old buckets\n        for (const bucket of oldBuckets) {\n            for (const [key, value] of bucket) {\n                this.put(key, value);\n            }\n        }\n    };\n\n    Object.defineProperty(this, \'length\', {\n        get: function() {\n            return this.size;\n        }\n    });\n}',
