  E'def majority_element(nums: list[int]) -> int:\n    """\n    Find the element appearing more than n/2 times.\n    Guaranteed to exist.\n\n    Boyer-Moore Voting Algorithm.\n    Time: O(n), Space: O(1)\n    """\n    candidate = None\n    count = 0\n    for num in nums:\n        if count == 0:\n            candidate = num\n        if num == candidate:\n            count += 1\n        else:\n            count -= 1\n    return candidate\ndef top_k_frequent(nums: list[int], k: int) -> list[int]:\n    """\n    Return the k most frequent elements.\n\n    Approach: Frequency count + bucket sort.\n    Time: O(n), Space: O(n)\n    """\n    # Step 1: Count frequencies\n    freq = {}\n    for num in nums:\n        freq[num] = freq.get(num, 0) + 1\n    # Step 2: Create buckets (index = frequency)\n    # Maximum frequency is len(nums)\n    buckets = [[] for _ in range(len(nums) + 1)]\n    for num, count in freq.items():\n        buckets[count].append(num)\n    # Step 3: Collect top k from highest frequency down\n    result = []\n    for i in range(len(buckets) - 1, 0, -1):\n        for num in buckets[i]:\n            result.append(num)\n            if len(result) == k:\n                return result\n    return result\ndef longest_consecutive(nums: list[int]) -> int:\n    """\n    Find the length of the longest consecutive sequence.\n    Example: [100, 4, 200, 1, 3, 2] → 4 (sequence: 1,2,3,4)\n\n    Time: O(n), Space: O(n)\n    """\n    num_set = set(nums)\n    max_length = 0\n    for num in num_set:\n        # Only start counting from the beginning of a sequence\n        if num - 1 not in num_set:\n            current = num\n            length = 1\n            while current + 1 in num_set:\n                current += 1\n                length += 1\n            max_length = max(max_length, length)\n    return max_length',
  E'class Solution {\n    public Object majorityElement(int[] nums) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.HashMap;\nimport java.util.HashSet;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\n\nclass Solution {\n    public static int majorityElement(int[] nums) {\n        Integer candidate = null;\n        int count = 0;\n        for (int num : nums) {\n            if (count == 0) {\n                candidate = num;\n            }\n            if (num == candidate) {\n                count++;\n            } else {\n                count--;\n            }\n        }\n        return candidate;\n    }\n\n    public static List<Integer> topKFrequent(int[] nums, int k) {\n        // Step 1: Count frequencies\n        Map<Integer, Integer> freq = new HashMap<>();\n        for (int num : nums) {\n            freq.put(num, freq.getOrDefault(num, 0) + 1);\n        }\n\n        // Step 2: Create buckets (index = frequency)\n        // Maximum frequency is len(nums)\n        List<Integer>[] buckets = new List[nums.length + 1];\n        for (int i = 0; i < buckets.length; i++) {\n            buckets[i] = new ArrayList<>();\n        }\n\n        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {\n            int num = entry.getKey();\n            int count = entry.getValue();\n            buckets[count].add(num);\n        }\n\n        // Step 3: Collect top k from highest frequency down\n        List<Integer> result = new ArrayList<>();\n        for (int i = buckets.length - 1; i >= 0; i--) {\n            for (int num : buckets[i]) {\n                result.add(num);\n                if (result.size() == k) {\n                    return result;\n                }\n            }\n        }\n        return result;\n    }\n\n    public static int longestConsecutive(int[] nums) {\n        if (nums.length == 0) {\n            return 0;\n        }\n\n        Set<Integer> numSet = new HashSet<>();\n        for (int num : nums) {\n            numSet.add(num);\n        }\n\n        int maxLength = 0;\n        for (int num : numSet) {\n            // Only start counting from the beginning of a sequence\n            if (!numSet.contains(num - 1)) {\n                int current = num;\n                int length = 1;\n                while (numSet.contains(current + 1)) {\n                    current++;\n                    length++;\n                }\n                maxLength = Math.max(maxLength, length);\n            }\n        }\n        return maxLength;\n    }\n}',
  E'/**\n * @param {any} nums\n * @return {any}\n */\nfunction majorityElement(nums) {\n    // Your code here\n}',
  E'function majorityElement(nums) {\n    let candidate = null;\n    let count = 0;\n    for (const num of nums) {\n        if (count === 0) {\n            candidate = num;\n        }\n        if (num === candidate) {\n            count++;\n        } else {\n            count--;\n        }\n    }\n    return candidate;\n}\n\nfunction topKFrequent(nums, k) {\n    // Step 1: Count frequencies\n    const freq = new Map();\n    for (const num of nums) {\n        freq.set(num, (freq.get(num) || 0) + 1);\n    }\n\n    // Step 2: Create buckets (index = frequency)\n    // Maximum frequency is nums.length\n    const buckets = Array.from({ length: nums.length + 1 }, () => []);\n\n    for (const [num, count] of freq.entries()) {\n        buckets[count].push(num);\n    }\n\n    // Step 3: Collect top k from highest frequency down\n    const result = [];\n    for (let i = buckets.length - 1; i >= 0; i--) {\n        for (const num of buckets[i]) {\n            result.push(num);\n            if (result.length === k) {\n                return result;\n            }\n        }\n    }\n    return result;\n}\n\nfunction longestConsecutive(nums) {\n    if (nums.length === 0) {\n        return 0;\n    }\n\n    const numSet = new Set(nums);\n    let maxLength = 0;\n\n    for (const num of numSet) {\n        // Only start counting from the beginning of a sequence\n        if (!numSet.has(num - 1)) {\n            let current = num;\n            let length = 1;\n            while (numSet.has(current + 1)) {\n                current++;\n                length++;\n            }\n            maxLength = Math.max(maxLength, length);\n        }\n    }\n    return maxLength;\n}',
