  E'def group_anagrams_sort(strs: list[str]) -> list[list[str]]:\n    """\n    Group anagrams using sorted string as key.\n\n    Time: O(n * k log k), Space: O(n * k)\n    """\n    # TODO: Create a dict mapping sorted_string -> list of original strings\n    # TODO: For each string, sort it and use as key\n    # TODO: Return all groups\n    pass\ndef group_anagrams_count(strs: list[str]) -> list[list[str]]:\n    """\n    Group anagrams using character count tuple as key.\n\n    Time: O(n * k), Space: O(n * k)\n    """\n    # TODO: For each string, create a tuple of 26 character counts\n    # TODO: Use this tuple as the dict key\n    # TODO: Return all groups\n    pass\ndef find_anagrams(s: str, p: str) -> list[int]:\n    """\n    Find all start indices of p''s anagrams in s.\n\n    Example: s = "cbaebabacd", p = "abc" → [0, 6]\n    Approach: Sliding window of size len(p).\n    Time: O(n), Space: O(1)\n    """\n    # TODO: Count chars in p\n    # TODO: Use sliding window of size len(p) over s\n    # TODO: Maintain window char counts\n    # TODO: When counts match, record the start index\n    pass\n# [["eat","tea","ate"], ["tan","nat"], ["bat"]] (order may vary)\n# Same grouping as above',
  E'def group_anagrams_sort(strs: list[str]) -> list[list[str]]:\n    """\n    Group anagrams using sorted string as key.\n\n    Time: O(n * k log k), Space: O(n * k)\n    """\n    groups = {}\n    for s in strs:\n        key = "".join(sorted(s))\n        if key not in groups:\n            groups[key] = []\n        groups[key].append(s)\n    return list(groups.values())\ndef group_anagrams_count(strs: list[str]) -> list[list[str]]:\n    """\n    Group anagrams using character count tuple as key.\n\n    Time: O(n * k), Space: O(n * k)\n    """\n    groups = {}\n    for s in strs:\n        # Create a count of each character (26 lowercase letters)\n        counts = [0] * 26\n        for c in s:\n            counts[ord(c) - ord(''a'')] += 1\n        key = tuple(counts)  # Tuples are hashable\n        if key not in groups:\n            groups[key] = []\n        groups[key].append(s)\n    return list(groups.values())\ndef find_anagrams(s: str, p: str) -> list[int]:\n    """\n    Find all start indices of p''s anagrams in s.\n\n    Example: s = "cbaebabacd", p = "abc" → [0, 6]\n    Approach: Sliding window of size len(p).\n    Time: O(n), Space: O(1)\n    """\n    if len(p) > len(s):\n        return []\n    result = []\n    p_count = [0] * 26\n    w_count = [0] * 26\n    # Count characters in p\n    for c in p:\n        p_count[ord(c) - ord(''a'')] += 1\n    # Initialize window with first len(p) characters\n    for i in range(len(p)):\n        w_count[ord(s[i]) - ord(''a'')] += 1\n    if w_count == p_count:\n        result.append(0)\n    # Slide the window\n    for i in range(len(p), len(s)):\n        # Add new character\n        w_count[ord(s[i]) - ord(''a'')] += 1\n        # Remove old character\n        w_count[ord(s[i - len(p)]) - ord(''a'')] -= 1\n        if w_count == p_count:\n            result.append(i - len(p) + 1)\n    return result\n# [["eat","tea","ate"], ["tan","nat"], ["bat"]] (order may vary)\n# Same grouping as above',
  E'class Solution {\n    public Object groupAnagramsSort(Object strs) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    // Required imports:\n    // import java.util.List;\n    // import java.util.ArrayList;\n    // import java.util.Map;\n    // import java.util.HashMap;\n    // import java.util.Arrays;\n\n    public static List<List<String>> groupAnagramsSort(String[] strs) {\n        Map<String, List<String>> groups = new HashMap<>();\n        for (String s : strs) {\n            char[] charArray = s.toCharArray();\n            Arrays.sort(charArray);\n            String key = new String(charArray);\n\n            groups.computeIfAbsent(key, k -> new ArrayList<>()).add(s);\n        }\n        return new ArrayList<>(groups.values());\n    }\n}''a'')] += 1\n    //         key = tuple(counts)  # Tuples are hashable\n    //         if key not in groups:\n    //             groups[key] = []\n    //         groups[key].append(s)\n    //     return list(groups.values())\n    // \n    // \n    // def find_anagrams(s: str, p: str) -> list[int]:\n    //     """\n    //     Find all start indices of p''s anagrams in s.\n    // \n    //     Example: s = "cbaebabacd", p = "abc" → [0, 6]\n    // \n    //     Approach: Sliding window of size len(p).\n    //     Time: O(n), Space: O(1)\n    //     """\n    //     if len(p) > len(s):\n    //         return []\n    // \n    //     result = []\n    //     p_count = [0] * 26\n    //     w_count = [0] * 26\n    // \n    //     # Count characters in p\n    //     for c in p:\n    //         p_count[ord(c) - ord(''a'')] += 1\n    // \n    //     # Initialize window with first len(p) characters\n    //     for i in range(len(p)):\n    //         w_count[ord(s[i]) - ord(''a'')] += 1\n    // \n    //     if w_count == p_count:\n    //         result.append(0)\n    // \n    //     # Slide the window\n    //     for i in range(len(p), len(s)):\n    //         # Add new character\n    //         w_count[ord(s[i]) - ord(''a'')] += 1\n    //         # Remove old character\n    //         w_count[ord(s[i - len(p)]) - ord(''a'')] -= 1\n    // \n    //         if w_count == p_count:\n    //             result.append(i - len(p) + 1)\n    // \n    //     return result\n    // \n    // \n    // # [["eat","tea","ate"], ["tan","nat"], ["bat"]] (order may vary)\n    // \n    // # Same grouping as above\n    // \n    // \n}',
  E'/**\n * @param {any} strs\n * @return {any}\n */\nfunction groupAnagramsSort(strs) {\n    // Your code here\n}',
