  E'class ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef has_cycle(head: ListNode) -> bool:\n    """\n    Detect if a linked list has a cycle.\n\n    Time: O(n), Space: O(1)\n    """\n    # TODO: Initialize slow and fast to head\n    # TODO: While fast and fast.next exist:\n    #   - Move slow by 1, fast by 2\n    #   - If they meet, return True\n    # TODO: Return False (fast reached end)\n    pass\ndef find_cycle_start(head: ListNode) -> ListNode:\n    """\n    Find the node where a cycle begins. Return None if no cycle.\n\n    Time: O(n), Space: O(1)\n    """\n    # TODO: Detect cycle using slow/fast\n    # TODO: If cycle found, reset one pointer to head\n    # TODO: Move both by 1 step until they meet — that''s the cycle start\n    pass\ndef is_palindrome(head: ListNode) -> bool:\n    """\n    Check if a linked list is a palindrome.\n\n    Approach: Find middle, reverse second half, compare.\n    Time: O(n), Space: O(1)\n    """\n    # TODO: Find middle using slow/fast\n    # TODO: Reverse the second half of the list\n    # TODO: Compare first half with reversed second half\n    # TODO: Return True if all values match\n    pass\n# Helper to create list\ndef make_list(vals):\n    if not vals:\n        return None\n    head = ListNode(vals[0])\n    curr = head\n    for v in vals[1:]:\n        curr.next = ListNode(v)\n        curr = curr.next\n    return head\n\nll = make_list([1, 2, 3, 4])\n# Create a cycle: 4 -> 2\nnode = ll\nwhile node.next:\n    node = node.next\nnode.next = ll.next  # 4 points to 2\nstart = find_cycle_start(ll)',
  E'class ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef has_cycle(head: ListNode) -> bool:\n    """\n    Detect if a linked list has a cycle.\n\n    Time: O(n), Space: O(1)\n    """\n    slow = fast = head\n    while fast and fast.next:\n        slow = slow.next\n        fast = fast.next.next\n        if slow == fast:\n            return True\n    return False\ndef find_cycle_start(head: ListNode) -> ListNode:\n    """\n    Find the node where a cycle begins. Return None if no cycle.\n\n    Time: O(n), Space: O(1)\n    """\n    slow = fast = head\n    # Phase 1: Detect cycle\n    while fast and fast.next:\n        slow = slow.next\n        fast = fast.next.next\n        if slow == fast:\n            break\n    else:\n        return None  # No cycle\n    # Phase 2: Find start of cycle\n    slow = head\n    while slow != fast:\n        slow = slow.next\n        fast = fast.next\n    return slow\ndef is_palindrome(head: ListNode) -> bool:\n    """\n    Check if a linked list is a palindrome.\n\n    Approach: Find middle, reverse second half, compare.\n    Time: O(n), Space: O(1)\n    """\n    if not head or not head.next:\n        return True\n    # Step 1: Find middle\n    slow = fast = head\n    while fast.next and fast.next.next:\n        slow = slow.next\n        fast = fast.next.next\n    # Step 2: Reverse second half (starting from slow.next)\n    prev = None\n    curr = slow.next\n    while curr:\n        nxt = curr.next\n        curr.next = prev\n        prev = curr\n        curr = nxt\n    # prev is now head of reversed second half\n    # Step 3: Compare first half with reversed second half\n    left = head\n    right = prev\n    while right:\n        if left.val != right.val:\n            return False\n        left = left.next\n        right = right.next\n    return True\n# Helper to create list\ndef make_list(vals):\n    if not vals:\n        return None\n    head = ListNode(vals[0])\n    curr = head\n    for v in vals[1:]:\n        curr.next = ListNode(v)\n        curr = curr.next\n    return head\n\nll = make_list([1, 2, 3, 4])\n# Create a cycle: 4 -> 2\nnode = ll\nwhile node.next:\n    node = node.next\nnode.next = ll.next  # 4 points to 2\nstart = find_cycle_start(ll)',
  E'class Solution {\n    public Object hasCycle(Object val, Object next) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n        ListNode(int val, ListNode next) { this.val = val; this.next = next; }\n    }\n\n    public static boolean hasCycle(ListNode head) {\n        ListNode slow = head;\n        ListNode fast = head;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) {\n                return true;\n            }\n        }\n        return false;\n    }\n\n    public static ListNode findCycleStart(ListNode head) {\n        ListNode slow = head;\n        ListNode fast = head;\n        // Phase 1: Detect cycle\n        boolean cycleDetected = false;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) {\n                cycleDetected = true;\n                break;\n            }\n        }\n        if (!cycleDetected) {\n            return null; // No cycle\n        }\n        // Phase 2: Find start of cycle\n        slow = head;\n        while (slow != fast) {\n            slow = slow.next;\n            fast = fast.next;\n        }\n        return slow;\n    }\n\n    public static boolean isPalindrome(ListNode head) {\n        if (head == null || head.next == null) {\n            return true;\n        }\n        // Step 1: Find middle\n        ListNode slow = head;\n        ListNode fast = head;\n        while (fast.next != null && fast.next.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        // Step 2: Reverse second half (starting from slow.next)\n        ListNode prev = null;\n        ListNode curr = slow.next;\n        while (curr != null) {\n            ListNode nxt = curr.next;\n            curr.next = prev;\n            prev = curr;\n            curr = nxt;\n        }\n        // prev is now head of reversed second half\n        // Step 3: Compare first half with reversed second half\n        ListNode left = head;\n        ListNode right = prev;\n        while (right != null) {\n            if (left.val != right.val) {\n                return false;\n            }\n            left = left.next;\n            right = right.next;\n        }\n        return true;\n    }\n\n    // Helper to create list (not part of the problem, but useful for testing)\n    public static ListNode makeList(int[] vals) {\n        if (vals == null || vals.length == 0) {\n            return null;\n        }\n        ListNode head = new ListNode(vals[0]);\n        ListNode curr = head;\n        for (int i = 1; i < vals.length; i++) {\n            curr.next = new ListNode(vals[i]);\n            curr = curr.next;\n        }\n        return head;\n    }\n}',
  E'/**\n * @param {any, any} val, next\n * @return {any}\n */\nfunction hasCycle(val, next) {\n    // Your code here\n}',
  E'class ListNode {\n    constructor(val = 0, next = null) {\n        this.val = val;\n        this.next = next;\n    }\n}\n\nfunction hasCycle(head) {\n    let slow = head;\n    let fast = head;\n    while (fast && fast.next) {\n        slow = slow.next;\n        fast = fast.next.next;\n        if (slow === fast) {\n            return true;\n        }\n    }\n    return false;\n}\n\nfunction findCycleStart(head) {\n    let slow = head;\n    let fast = head;\n    // Phase 1: Detect cycle\n    let cycleDetected = false;\n    while (fast && fast.next) {\n        slow = slow.next;\n        fast = fast.next.next;\n        if (slow === fast) {\n            cycleDetected = true;\n            break;\n        }\n    }\n    if (!cycleDetected) {\n        return null; // No cycle\n    }\n    // Phase 2: Find start of cycle\n    slow = head;\n    while (slow !== fast) {\n        slow = slow.next;\n        fast = fast.next;\n    }\n    return slow;\n}\n\nfunction isPalindrome(head) {\n    if (!head || !head.next) {\n        return true;\n    }\n    // Step 1: Find middle\n    let slow = head;\n    let fast = head;\n    while (fast.next && fast.next.next) {\n        slow = slow.next;\n        fast = fast.next.next;\n    }\n    // Step 2: Reverse second half (starting from slow.next)\n    let prev = null;\n    let curr = slow.next;\n    while (curr) {\n        let nxt = curr.next;\n        curr.next = prev;\n        prev = curr;\n        curr = nxt;\n    }\n    // prev is now head of reversed second half\n    // Step 3: Compare first half with reversed second half\n    let left = head;\n    let right = prev;\n    while (right) {\n        if (left.val !== right.val) {\n            return false;\n        }\n        left = left.next;\n        right = right.next;\n    }\n    return true;\n}\n\n// Helper to create list (not part of the problem, but useful for testing)\nfunction makeList(vals) {\n    if (!vals || vals.length === 0) {\n        return null;\n    }\n    let head = new ListNode(vals[0]);\n    let curr = head;\n    for (let i = 1; i < vals.length; i++) {\n        curr.next = new ListNode(vals[i]);\n        curr = curr.next;\n    }\n    return head;\n}',
