  E'class ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef make_list(vals):\n    if not vals: return None\n    head = ListNode(vals[0])\n    curr = head\n    for v in vals[1:]:\n        curr.next = ListNode(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef reverse_iterative(head: ListNode) -> ListNode:\n    """\n    Reverse a linked list iteratively.\n    Time: O(n), Space: O(1)\n    """\n    prev = None\n    curr = head\n    while curr:\n        nxt = curr.next      # Save next\n        curr.next = prev     # Reverse pointer\n        prev = curr          # Advance prev\n        curr = nxt           # Advance curr\n    return prev  # New head\n\ndef reverse_recursive(head: ListNode) -> ListNode:\n    """\n    Reverse a linked list recursively.\n    Time: O(n), Space: O(n) — call stack\n    """\n    # Base case: empty or single node\n    if not head or not head.next:\n        return head\n\n    # Recursively reverse the rest of the list\n    new_head = reverse_recursive(head.next)\n    # head.next is the last node of the reversed sublist\n    # Make it point back to head\n    head.next.next = head\n    head.next = None  # Head is now the tail\n    return new_head\ndef reverse_between(head: ListNode, left: int, right: int) -> ListNode:\n    """\n    Reverse nodes from position left to right (1-indexed).\n    Example: 1->2->3->4->5, left=2, right=4 → 1->4->3->2->5\n\n    Time: O(n), Space: O(1)\n    """\n    dummy = ListNode(0)\n    dummy.next = head\n    # Step 1: Find the node before the ''left'' position\n    pre = dummy\n    for _ in range(left - 1):\n        pre = pre.next\n    # Step 2: Reverse from left to right\n    # ''start'' is the first node of the sublist to reverse\n    start = pre.next\n    then = start.next\n    for _ in range(right - left):\n        # Move ''then'' to the position right after ''pre''\n        start.next = then.next\n        then.next = pre.next\n        pre.next = then\n        then = start.next\n    return dummy.next\n# [5, 4, 3, 2, 1]\n# [5, 4, 3, 2, 1]\n# [1, 4, 3, 2, 5]\n# [5]',
