  E'class Solution {\n    public static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n        ListNode(int val, ListNode next) { this.val = val; this.next = next; }\n    }\n\n    public static ListNode makeList(int[] vals) {\n        if (vals == null || vals.length == 0) return null;\n        ListNode head = new ListNode(vals[0]);\n        ListNode curr = head;\n        for (int i = 1; i < vals.length; i++) {\n            curr.next = new ListNode(vals[i]);\n            curr = curr.next;\n        }\n        return head;\n    }\n\n    public static java.util.List<Integer> toList(ListNode head) {\n        java.util.List<Integer> result = new java.util.ArrayList<>();\n        while (head != null) {\n            result.add(head.val);\n            head = head.next;\n        }\n        return result;\n    }\n\n    public static ListNode reverseIterative(ListNode head) {\n        ListNode prev = null;\n        ListNode curr = head;\n        while (curr != null) {\n            ListNode nxt = curr.next; // Save next\n            curr.next = prev;          // Reverse pointer\n            prev = curr;               // Advance prev\n            curr = nxt;                // Advance curr\n        }\n        return prev; // New head\n    }\n\n    public static ListNode reverseRecursive(ListNode head) {\n        // Base case: empty or single node\n        if (head == null || head.next == null) {\n            return head;\n        }\n\n        // Recursively reverse the rest of the list\n        ListNode newHead = reverseRecursive(head.next);\n        // head.next is the last node of the reversed sublist\n        // Make it point back to head\n        head.next.next = head;\n        head.next = null; // Head is now the tail\n        return newHead;\n    }\n\n    public static ListNode reverseBetween(ListNode head, int left, int right) {\n        ListNode dummy = new ListNode(0);\n        dummy.next = head;\n\n        // Step 1: Find the node before the \'left\' position\n        ListNode pre = dummy;\n        for (int i = 0; i < left - 1; i++) {\n            pre = pre.next;\n        }\n\n        // \'start\' is the node at the \'left\' position\n        // \'curr\' will be the node whose next pointer we are reversing\n        ListNode curr = pre.next; \n\n        // Step 2: Reverse the sublist from \'left\' to \'right\'\n        // Perform \'right - left\' reversals\n        for (int i = 0; i < right - left; i++) {\n            ListNode nxt = curr.next; // Node to be moved\n            curr.next = nxt.next;     // Detach nxt from its current position\n            nxt.next = pre.next;      // Insert nxt at the beginning of the reversed segment\n            pre.next = nxt;           // Update pre.next to point to nxt\n        }\n\n        return dummy.next;\n    }\n}''left'' position\n    //     pre = dummy\n    //     for _ in range(left - 1):\n    //         pre = pre.next\n    // \n    //     # Step 2: Reverse from left to right\n    //     # ''start'' is the first node of the sublist to reverse\n    //     start = pre.next\n    //     then = start.next\n    // \n    //     for _ in range(right - left):\n    //         # Move ''then'' to the position right after ''pre''\n    //         start.next = then.next\n    //         then.next = pre.next\n    //         pre.next = then\n    //         then = start.next\n    // \n    //     return dummy.next\n    // \n    // \n    // # [5, 4, 3, 2, 1]\n    // \n    // # [5, 4, 3, 2, 1]\n    // \n    // # [1, 4, 3, 2, 5]\n    // \n    // # [5]\n    // \n}',
