  E'class ListNode {\n    constructor(val = 0, next = null) {\n        this.val = val;\n        this.next = next;\n    }\n}\n\nfunction makeList(vals) {\n    if (!vals || vals.length === 0) return null;\n    let head = new ListNode(vals[0]);\n    let curr = head;\n    for (let i = 1; i < vals.length; i++) {\n        curr.next = new ListNode(vals[i]);\n        curr = curr.next;\n    }\n    return head;\n}\n\nfunction toList(head) {\n    let result = [];\n    while (head) {\n        result.push(head.val);\n        head = head.next;\n    }\n    return result;\n}\n\nfunction reverseIterative(head) {\n    let prev = null;\n    let curr = head;\n    while (curr) {\n        let nxt = curr.next; // Save next\n        curr.next = prev;    // Reverse pointer\n        prev = curr;         // Advance prev\n        curr = nxt;          // Advance curr\n    }\n    return prev; // New head\n}\n\nfunction reverseRecursive(head) {\n    // Base case: empty or single node\n    if (!head || !head.next) {\n        return head;\n    }\n\n    // Recursively reverse the rest of the list\n    let newHead = reverseRecursive(head.next);\n    // head.next is the last node of the reversed sublist\n    // Make it point back to head\n    head.next.next = head;\n    head.next = null; // Head is now the tail\n    return newHead;\n}\n\nfunction reverseBetween(head, left, right) {\n    let dummy = new ListNode(0);\n    dummy.next = head;\n\n    // Step 1: Find the node before the \'left\' position\n    let pre = dummy;\n    for (let i = 0; i < left - 1; i++) {\n        pre = pre.next;\n    }\n\n    // \'curr\' will be the node whose next pointer we are reversing\n    let curr = pre.next; \n\n    // Step 2: Reverse the sublist from \'left\' to \'right\'\n    // Perform \'right - left\' reversals\n    for (let i = 0; i < right - left; i++) {\n        let nxt = curr.next; // Node to be moved\n        curr.next = nxt.next;     // Detach nxt from its current position\n        nxt.next = pre.next;      // Insert nxt at the beginning of the reversed segment\n        pre.next = nxt;           // Update pre.next to point to nxt\n    }\n\n    return dummy.next;\n}',
