  E'class ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef make_list(vals):\n    if not vals: return None\n    head = ListNode(vals[0])\n    curr = head\n    for v in vals[1:]:\n        curr.next = ListNode(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef merge_two_sorted(l1: ListNode, l2: ListNode) -> ListNode:\n    """\n    Merge two sorted linked lists into one sorted list.\n    Time: O(n + m), Space: O(1)\n    """\n    # TODO: Create dummy head\n    # TODO: While both lists have nodes, append smaller\n    # TODO: Append remaining nodes from non-empty list\n    # TODO: Return dummy.next\n    pass\n\ndef sort_list(head: ListNode) -> ListNode:\n    """\n    Sort a linked list using merge sort.\n    Time: O(n log n), Space: O(log n)\n    """\n    # TODO: Base case — 0 or 1 nodes\n    # TODO: Find middle with slow/fast pointers\n    # TODO: Split list into two halves\n    # TODO: Recursively sort each half\n    # TODO: Merge the sorted halves\n    pass\n\ndef get_intersection(headA: ListNode, headB: ListNode) -> ListNode:\n    """\n    Find the intersection node of two linked lists.\n    Return None if no intersection.\n\n    Two-pointer approach.\n    Time: O(n + m), Space: O(1)\n    """\n    # TODO: Initialize pointers to each head\n    # TODO: When a pointer reaches end, redirect to other list''s head\n    # TODO: They meet at intersection or both become None\n    pass\n# [1, 2, 3, 4, 5, 6]\n# [1, 2, 3, 4]\n# [1, 2, 4, 5, 8]\nshared = make_list([8, 10])\na = ListNode(3)\na.next = ListNode(7)\na.next.next = shared\nb = ListNode(99)\nb.next = shared\nresult = get_intersection(a, b)',
  E'class ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef make_list(vals):\n    if not vals: return None\n    head = ListNode(vals[0])\n    curr = head\n    for v in vals[1:]:\n        curr.next = ListNode(v)\n        curr = curr.next\n    return head\n\ndef to_list(head):\n    result = []\n    while head:\n        result.append(head.val)\n        head = head.next\n    return result\n\ndef merge_two_sorted(l1: ListNode, l2: ListNode) -> ListNode:\n    """\n    Merge two sorted linked lists into one sorted list.\n    Time: O(n + m), Space: O(1)\n    """\n    dummy = ListNode(0)\n    current = dummy\n\n    while l1 and l2:\n        if l1.val <= l2.val:\n            current.next = l1\n            l1 = l1.next\n        else:\n            current.next = l2\n            l2 = l2.next\n        current = current.next\n    # Append remaining nodes\n    current.next = l1 if l1 else l2\n    return dummy.next\ndef sort_list(head: ListNode) -> ListNode:\n    """\n    Sort a linked list using merge sort.\n    Time: O(n log n), Space: O(log n)\n    """\n    # Base case: 0 or 1 nodes\n    if not head or not head.next:\n        return head\n\n    # Find middle using slow/fast\n    slow, fast = head, head.next\n    while fast and fast.next:\n        slow = slow.next\n        fast = fast.next.next\n    # Split the list into two halves\n    mid = slow.next\n    slow.next = None  # Cut the connection\n    # Recursively sort each half\n    left = sort_list(head)\n    right = sort_list(mid)\n    # Merge sorted halves\n    return merge_two_sorted(left, right)\ndef get_intersection(headA: ListNode, headB: ListNode) -> ListNode:\n    """\n    Find the intersection node of two linked lists.\n    Return None if no intersection.\n\n    Two-pointer approach.\n    Time: O(n + m), Space: O(1)\n    """\n    if not headA or not headB:\n        return None\n    a, b = headA, headB\n    # When one pointer reaches the end, redirect to the other list''s head.\n    # If they intersect, they''ll meet at the intersection.\n    # If not, both become None at the same time.\n    while a != b:\n        a = a.next if a else headB\n        b = b.next if b else headA\n    return a  # Either the intersection node or None\n# [1, 2, 3, 4, 5, 6]\n# [1, 2, 3, 4]\n# [1, 2, 4, 5, 8]\nshared = make_list([8, 10])\na = ListNode(3)\na.next = ListNode(7)\na.next.next = shared\nb = ListNode(99)\nb.next = shared\nresult = get_intersection(a, b)',
  E'class Solution {\n    public Object makeList(Object val, Object next) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n        ListNode(int val, ListNode next) { this.val = val; this.next = next; }\n    }\n\n    public static ListNode makeList(int[] vals) {\n        if (vals == null || vals.length == 0) return null;\n        ListNode head = new ListNode(vals[0]);\n        ListNode curr = head;\n        for (int i = 1; i < vals.length; i++) {\n            curr.next = new ListNode(vals[i]);\n            curr = curr.next;\n        }\n        return head;\n    }\n\n    public static java.util.List<Integer> toList(ListNode head) {\n        java.util.List<Integer> result = new java.util.ArrayList<>();\n        while (head != null) {\n            result.add(head.val);\n            head = head.next;\n        }\n        return result;\n    }\n\n    public static ListNode mergeTwoSorted(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode(0);\n        ListNode current = dummy;\n\n        while (l1 != null && l2 != null) {\n            if (l1.val <= l2.val) {\n                current.next = l1;\n                l1 = l1.next;\n            } else {\n                current.next = l2;\n                l2 = l2.next;\n            }\n            current = current.next;\n        }\n        // Append remaining nodes\n        current.next = (l1 != null) ? l1 : l2;\n        return dummy.next;\n    }\n\n    public static ListNode sortList(ListNode head) {\n        // Base case: 0 or 1 nodes\n        if (head == null || head.next == null) {\n            return head;\n        }\n\n        // Find middle using slow/fast\n        ListNode slow = head;\n        ListNode fast = head.next;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        // Split the list into two halves\n        ListNode mid = slow.next;\n        slow.next = null; // Cut the connection\n        // Recursively sort each half\n        ListNode left = sortList(head);\n        ListNode right = sortList(mid);\n        // Merge sorted halves\n        return mergeTwoSorted(left, right);\n    }\n\n    public static ListNode getIntersection(ListNode headA, ListNode headB) {\n        if (headA == null || headB == null) {\n            return null;\n        }\n        ListNode a = headA;\n        ListNode b = headB;\n        // When one pointer reaches the end, redirect to the other list\n        while (a != b) {\n            a = (a == null) ? headB : a.next;\n            b = (b == null) ? headA : b.next;\n        }\n        return a;\n    }\n}''s head.\n    //     # If they intersect, they''ll meet at the intersection.\n    //     # If not, both become None at the same time.\n    //     while a != b:\n    //         a = a.next if a else headB\n    //         b = b.next if b else headA\n    // \n    //     return a  # Either the intersection node or None\n    // \n    // \n    // # [1, 2, 3, 4, 5, 6]\n    // \n    // # [1, 2, 3, 4]\n    // \n    // # [1, 2, 4, 5, 8]\n    // \n    // shared = make_list([8, 10])\n    // a = ListNode(3)\n    // a.next = ListNode(7)\n    // a.next.next = shared\n    // b = ListNode(99)\n    // b.next = shared\n    // result = get_intersection(a, b)\n    // \n}',
  E'/**\n * @param {any, any} val, next\n * @return {any}\n */\nfunction makeList(val, next) {\n    // Your code here\n}',
  E'class ListNode {\n    constructor(val = 0, next = null) {\n        this.val = val;\n        this.next = next;\n    }\n}\n\nfunction makeList(vals) {\n    if (!vals || vals.length === 0) return null;\n    let head = new ListNode(vals[0]);\n    let curr = head;\n    for (let i = 1; i < vals.length; i++) {\n        curr.next = new ListNode(vals[i]);\n        curr = curr.next;\n    }\n    return head;\n}\n\nfunction toList(head) {\n    let result = [];\n    while (head) {\n        result.push(head.val);\n        head = head.next;\n    }\n    return result;\n}\n\nfunction mergeTwoSorted(l1, l2) {\n    let dummy = new ListNode(0);\n    let current = dummy;\n\n    while (l1 && l2) {\n        if (l1.val <= l2.val) {\n            current.next = l1;\n            l1 = l1.next;\n        } else {\n            current.next = l2;\n            l2 = l2.next;\n        }\n        current = current.next;\n    }\n    // Append remaining nodes\n    current.next = l1 || l2;\n    return dummy.next;\n}\n\nfunction sortList(head) {\n    // Base case: 0 or 1 nodes\n    if (!head || !head.next) {\n        return head;\n    }\n\n    // Find middle using slow/fast\n    let slow = head;\n    let fast = head.next;\n    while (fast && fast.next) {\n        slow = slow.next;\n        fast = fast.next.next;\n    }\n    // Split the list into two halves\n    let mid = slow.next;\n    slow.next = null; // Cut the connection\n    // Recursively sort each half\n    let left = sortList(head);\n    let right = sortList(mid);\n    // Merge sorted halves\n    return mergeTwoSorted(left, right);\n}\n\nfunction getIntersection(headA, headB) {\n    if (!headA || !headB) {\n        return null;\n    }\n    let a = headA;\n    let b = headB;\n    // When one pointer reaches the end, redirect to the other list\n    while (a !== b) {\n        a = a ? a.next : headB;\n        b = b ? b.next : headA;\n    }\n    return a;\n}',
