  E'import java.util.List;\nimport java.util.ArrayList;\nimport java.util.Set;\nimport java.util.HashSet;\n\nclass Solution {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n        ListNode(int val, ListNode next) { this.val = val; this.next = next; }\n    }\n\n    public static ListNode makeList(List<Integer> vals) {\n        if (vals == null || vals.isEmpty()) {\n            return null;\n        }\n        ListNode head = new ListNode(vals.get(0));\n        ListNode curr = head;\n        for (int i = 1; i < vals.size(); i++) {\n            curr.next = new ListNode(vals.get(i));\n            curr = curr.next;\n        }\n        return head;\n    }\n\n    public static List<Integer> toList(ListNode head) {\n        List<Integer> result = new ArrayList<>();\n        Set<ListNode> seen = new HashSet<>();\n        while (head != null && !seen.contains(head)) {\n            seen.add(head);\n            result.add(head.val);\n            head = head.next;\n        }\n        return result;\n    }\n\n    public static boolean detectAndRemoveCycle(ListNode head) {\n        if (head == null || head.next == null) {\n            return false;\n        }\n        ListNode slow = head;\n        ListNode fast = head;\n        // Phase 1: Detect cycle\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) {\n                break;\n            }\n        }\n        if (slow != fast) { // No cycle detected\n            return false;\n        }\n        // Phase 2: Find cycle start and remove cycle\n        slow = head;\n        // Special case: cycle starts at head\n        if (slow == fast) {\n            // Find the last node in the cycle\n            while (fast.next != slow) {\n                fast = fast.next;\n            }\n            fast.next = null;\n            return true;\n        }\n        while (slow.next != fast.next) {\n            slow = slow.next;\n            fast = fast.next;\n        }\n        // fast.next is the cycle start, fast is the last node in the cycle\n        fast.next = null;\n        return true;\n    }\n\n    public static int cycleLength(ListNode head) {\n        ListNode slow = head;\n        ListNode fast = head;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) {\n                // Cycle detected, count length\n                int count = 1;\n                ListNode current = slow.next;\n                while (current != slow) {\n                    count++;\n                    current = current.next;\n                }\n                return count;\n            }\n        }\n        return 0; // No cycle\n    }\n\n    public static int findDuplicate(int[] nums) {\n        // Phase 1: Find meeting point\n        int slow = nums[0];\n        int fast = nums[nums[0]];\n        while (slow != fast) {\n            slow = nums[slow];\n            fast = nums[nums[fast]];\n        }\n        // Phase 2: Find cycle start (the duplicate)\n        slow = 0;\n        while (slow != fast) {\n            slow = nums[slow];\n            fast = nums[fast];\n        }\n        return slow;\n    }\n}',
