  E'from collections import deque\ndef is_valid_parentheses(s: str) -> bool:\n    """\n    Check if a string of brackets is valid.\n    Valid: (), [], {}, ([{}])\n    Invalid: (], ([)], ((\n\n    Time: O(n), Space: O(n)\n    """\n    matching = {'')'': ''('', '']'': ''['', ''}'': ''{''}\n    stack = []\n    for char in s:\n        if char in matching:\n            # Closing bracket — check for match\n            if not stack or stack[-1] != matching[char]:\n                return False\n            stack.pop()\n        else:\n            # Opening bracket — push\n            stack.append(char)\n    return len(stack) == 0\nclass MinStack:\n    """\n    Stack that supports push, pop, top, and getMin in O(1) time.\n    """\n    def __init__(self):\n        self.stack = []\n        self.min_stack = []  # Tracks minimums\n\n    def push(self, val: int) -> None:\n        self.stack.append(val)\n        # Push to min_stack if it''s empty or val is <= current min\n        if not self.min_stack or val <= self.min_stack[-1]:\n            self.min_stack.append(val)\n\n    def pop(self) -> None:\n        val = self.stack.pop()\n        # If popped value is the current min, pop min stack too\n        if val == self.min_stack[-1]:\n            self.min_stack.pop()\n\n    def top(self) -> int:\n        return self.stack[-1]\n\n    def get_min(self) -> int:\n        return self.min_stack[-1]\n\nms = MinStack()\nms.push(-2)\nms.push(0)\nms.push(-3)\nms.pop()',
