  E'def eval_rpn(tokens: list[str]) -> int:\n    """\n    Evaluate a Reverse Polish Notation expression.\n\n    Example: ["2","1","+","3","*"] → 9\n    Time: O(n), Space: O(n)\n    """\n    stack = []\n    operators = {''+'', ''-'', ''*'', ''/''}\n    for token in tokens:\n        if token in operators:\n            b = stack.pop()  # Second operand (popped first)\n            a = stack.pop()  # First operand\n            if token == ''+'':\n                stack.append(a + b)\n            elif token == ''-'':\n                stack.append(a - b)\n            elif token == ''*'':\n                stack.append(a * b)\n            else:  # ''/''\n                # Integer division truncating toward zero\n                stack.append(int(a / b))\n        else:\n            stack.append(int(token))\n    return stack[0]\ndef basic_calculator(s: str) -> int:\n    """\n    Evaluate a string expression with +, -, and parentheses.\n    Examples: "1 + 1" → 2, "(1+(4+5+2)-3)+(6+8)" → 23\n\n    Time: O(n), Space: O(n)\n    """\n    result = 0\n    num = 0\n    sign = 1\n    stack = []\n    for char in s:\n        if char.isdigit():\n            num = num * 10 + int(char)\n        elif char == ''+'':\n            result += sign * num\n            num = 0\n            sign = 1\n        elif char == ''-'':\n            result += sign * num\n            num = 0\n            sign = -1\n        elif char == ''('':\n            # Save current state\n            stack.append(result)\n            stack.append(sign)\n            result = 0\n            sign = 1\n        elif char == '')'':\n            result += sign * num\n            num = 0\n            # Pop sign and previous result\n            result *= stack.pop()  # Sign before parenthesis\n            result += stack.pop()  # Previous result\n    result += sign * num  # Don''t forget the last number\n    return result\ndef calculate(s: str) -> int:\n    """\n    Evaluate expression with +, -, *, / (no parentheses).\n    Integer division truncates toward zero.\n\n    Example: "3+2*2" → 7\n    Time: O(n), Space: O(n)\n    """\n    stack = []\n    num = 0\n    prev_op = ''+''\n    s = s.strip() + ''+''  # Add sentinel to process last number\n    for char in s:\n        if char.isdigit():\n            num = num * 10 + int(char)\n        elif char == '' '':\n            continue\n        else:\n            # Process the previous operator with current num\n            if prev_op == ''+'':\n                stack.append(num)\n            elif prev_op == ''-'':\n                stack.append(-num)\n            elif prev_op == ''*'':\n                stack.append(stack.pop() * num)\n            elif prev_op == ''/'':\n                stack.append(int(stack.pop() / num))\n            prev_op = char\n            num = 0\n    return sum(stack)',
  E'class Solution {\n    public Object evalRpn(Object tokens) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.Stack;\n\nclass Solution {\n    public static int evalRpn(String[] tokens) {\n        Stack<Integer> stack = new Stack<>();\n\n        for (String token : tokens) {\n            switch (token) {\n                case "+":\n                    stack.push(stack.pop() + stack.pop());\n                    break;\n                case "-":\n                    int op2 = stack.pop();\n                    int op1 = stack.pop();\n                    stack.push(op1 - op2);\n                    break;\n                case "*":\n                    stack.push(stack.pop() * stack.pop());\n                    break;\n                case "/":\n                    op2 = stack.pop();\n                    op1 = stack.pop();\n                    stack.push(op1 / op2); // Integer division truncates towards zero\n                    break;\n                default:\n                    stack.push(Integer.parseInt(token));\n                    break;\n            }\n        }\n        return stack.pop();\n    }\n}''+'', ''-'', ''*'', ''/''}\n    // \n    //     for token in tokens:\n    //         if token in operators:\n    //             b = stack.pop()  # Second operand (popped first)\n    //             a = stack.pop()  # First operand\n    //             if token == ''+'':\n    //                 stack.append(a + b)\n    //             elif token == ''-'':\n    //                 stack.append(a - b)\n    //             elif token == ''*'':\n    //                 stack.append(a * b)\n    //             else:  # ''/''\n    //                 # Integer division truncating toward zero\n    //                 stack.append(int(a / b))\n    //         else:\n    //             stack.append(int(token))\n    // \n    //     return stack[0]\n    // \n    // \n    // def basic_calculator(s: str) -> int:\n    //     """\n    //     Evaluate a string expression with +, -, and parentheses.\n    //     Examples: "1 + 1" → 2, "(1+(4+5+2)-3)+(6+8)" → 23\n    // \n    //     