  E'class TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef insert_bst(root: TreeNode, val: int) -> TreeNode:\n    """\n    Insert a value into a BST and return the root.\n    If root is None, create a new node.\n\n    Time: O(h), Space: O(h) for recursion\n    """\n    # TODO: Base case — if root is None, return new TreeNode(val)\n    # TODO: If val < root.val, recurse left\n    # TODO: If val > root.val, recurse right\n    # TODO: Return root\n    pass\ndef tree_height(root: TreeNode) -> int:\n    """\n    Return the height of the tree (edges on longest root-to-leaf path).\n    An empty tree has height -1, a single node has height 0.\n    """\n    # TODO: Base case — None returns -1\n    # TODO: Recursively get left and right heights\n    # TODO: Return 1 + max(left_height, right_height)\n    pass\n\ndef tree_size(root: TreeNode) -> int:\n    """Return the total number of nodes in the tree."""\n    # TODO: Base case — None returns 0\n    # TODO: Return 1 + size(left) + size(right)\n    pass\n\nvalues = [5, 3, 7, 1, 4, 6, 8]\nroot = None\nfor v in values:\n    root = insert_bst(root, v)\n# Unbalanced case\nroot2 = None\nfor v in [1, 2, 3, 4, 5]:\n    root2 = insert_bst(root2, v)',
  E'class TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef insert_bst(root: TreeNode, val: int) -> TreeNode:\n    """\n    Insert a value into a BST and return the root.\n    If root is None, create a new node.\n\n    Time: O(h), Space: O(h) for recursion\n    """\n    if not root:\n        return TreeNode(val)\n    if val < root.val:\n        root.left = insert_bst(root.left, val)\n    elif val > root.val:\n        root.right = insert_bst(root.right, val)\n    return root\ndef tree_height(root: TreeNode) -> int:\n    """\n    Return the height of the tree (edges on longest root-to-leaf path).\n    An empty tree has height -1, a single node has height 0.\n    """\n    if not root:\n        return -1\n    return 1 + max(tree_height(root.left), tree_height(root.right))\n\ndef tree_size(root: TreeNode) -> int:\n    """Return the total number of nodes in the tree."""\n    if not root:\n        return 0\n    return 1 + tree_size(root.left) + tree_size(root.right)\n\nvalues = [5, 3, 7, 1, 4, 6, 8]\nroot = None\nfor v in values:\n    root = insert_bst(root, v)\n# Unbalanced case\nroot2 = None\nfor v in [1, 2, 3, 4, 5]:\n    root2 = insert_bst(root2, v)',
  E'class Solution {\n    public Object insertBst(Object val, Object left, Object right) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode() {}\n        TreeNode(int val) { this.val = val; }\n        TreeNode(int val, TreeNode left, TreeNode right) {\n            this.val = val;\n            this.left = left;\n            this.right = right;\n        }\n    }\n\n    public static TreeNode insertBst(TreeNode root, int val) {\n        if (root == null) {\n            return new TreeNode(val);\n        }\n        if (val < root.val) {\n            root.left = insertBst(root.left, val);\n        } else if (val > root.val) {\n            root.right = insertBst(root.right, val);\n        }\n        return root;\n    }\n}',
