  E'from collections import deque\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef inorder_recursive(root: TreeNode) -> list[int]:\n    """Inorder traversal: Left, Root, Right."""\n    if not root:\n        return []\n    return inorder_recursive(root.left) + [root.val] + inorder_recursive(root.right)\n\ndef inorder_iterative(root: TreeNode) -> list[int]:\n    """Inorder traversal using an explicit stack."""\n    result = []\n    stack = []\n    current = root\n\n    while current or stack:\n        # Push all left children\n        while current:\n            stack.append(current)\n            current = current.left\n        # Pop and process\n        current = stack.pop()\n        result.append(current.val)\n        # Move to right subtree\n        current = current.right\n    return result\ndef preorder_iterative(root: TreeNode) -> list[int]:\n    """Preorder traversal: Root, Left, Right using a stack."""\n    if not root:\n        return []\n    result = []\n    stack = [root]\n\n    while stack:\n        node = stack.pop()\n        result.append(node.val)\n        # Push right first so left is processed first\n        if node.right:\n            stack.append(node.right)\n        if node.left:\n            stack.append(node.left)\n    return result\ndef level_order(root: TreeNode) -> list[list[int]]:\n    """\n    Level-order traversal returning a list of lists,\n    where each inner list contains values at that level.\n    """\n    if not root:\n        return []\n    result = []\n    queue = deque([root])\n\n    while queue:\n        level_size = len(queue)\n        level_vals = []\n        for _ in range(level_size):\n            node = queue.popleft()\n            level_vals.append(node.val)\n            if node.left:\n                queue.append(node.left)\n            if node.right:\n                queue.append(node.right)\n        result.append(level_vals)\n    return result\n# Build test tree:\n#        4\n#       / \\\n#      2   6\n#     / \\ / \\\n#    1  3 5  7\nroot = TreeNode(4)\nroot.left = TreeNode(2, TreeNode(1), TreeNode(3))\nroot.right = TreeNode(6, TreeNode(5), TreeNode(7))',
  E'class Solution {\n    public Object inorderRecursive(Object val, Object left, Object right) {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayList;\nimport java.util.List;\n\nclass Solution {\n    public static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode() {}\n        TreeNode(int val) { this.val = val; }\n        TreeNode(int val, TreeNode left, TreeNode right) {\n            this.val = val;\n            this.left = left;\n            this.right = right;\n        }\n    }\n\n    public static List<Integer> inorderRecursive(TreeNode root) {\n        List<Integer> result = new ArrayList<>();\n        if (root == null) {\n            return result;\n        }\n        result.addAll(inorderRecursive(root.left));\n        result.add(root.val);\n        result.addAll(inorderRecursive(root.right));\n        return result;\n    }\n}',
