  E'class TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef lca_bst(root: TreeNode, p: TreeNode, q: TreeNode) -> TreeNode:\n    """\n    Find LCA in a BST. Both p and q are guaranteed to exist.\n\n    Approach: Use BST property to find the split point.\n    Time: O(h), Space: O(1) iterative\n    """\n    # TODO: Walk down the tree iteratively\n    # TODO: If both values < root, go left\n    # TODO: If both values > root, go right\n    # TODO: Otherwise, current node is LCA\n    pass\ndef lca_binary_tree(root: TreeNode, p: TreeNode, q: TreeNode) -> TreeNode:\n    """\n    Find LCA in a general binary tree. Both p and q exist in the tree.\n\n    Approach: Recursive — find where p and q split.\n    Time: O(n), Space: O(n)\n    """\n    # TODO: Base case — None or current is p or q\n    # TODO: Recurse left and right\n    # TODO: If both return non-None, current is LCA\n    # TODO: Otherwise return whichever is non-None\n    pass\n# Build BST:\n#        6\n#       / \\\n#      2   8\n#     / \\ / \\\n#    0  4 7  9\n#      / \\\n#     3   5\nroot = TreeNode(6)\nroot.left = TreeNode(2, TreeNode(0), TreeNode(4, TreeNode(3), TreeNode(5)))\nroot.right = TreeNode(8, TreeNode(7), TreeNode(9))\np, q = root.left, root.left.right  # nodes 2 and 4\np, q = root.left, root.right       # nodes 2 and 8\n# General binary tree LCA (same tree)\np, q = root.left.right.left, root.left.right.right  # nodes 3 and 5\np, q = root.left.right.left, root.right.right  # nodes 3 and 9',
  E'class TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef lca_bst(root: TreeNode, p: TreeNode, q: TreeNode) -> TreeNode:\n    """\n    Find LCA in a BST. Both p and q are guaranteed to exist.\n\n    Approach: Use BST property to find the split point.\n    Time: O(h), Space: O(1) iterative\n    """\n    current = root\n    while current:\n        if p.val < current.val and q.val < current.val:\n            current = current.left\n        elif p.val > current.val and q.val > current.val:\n            current = current.right\n        else:\n            return current\n    return None\ndef lca_binary_tree(root: TreeNode, p: TreeNode, q: TreeNode) -> TreeNode:\n    """\n    Find LCA in a general binary tree. Both p and q exist in the tree.\n\n    Approach: Recursive — find where p and q split.\n    Time: O(n), Space: O(n)\n    """\n    # Base case\n    if not root or root == p or root == q:\n        return root\n    left = lca_binary_tree(root.left, p, q)\n    right = lca_binary_tree(root.right, p, q)\n    # If both sides found something, current node is LCA\n    if left and right:\n        return root\n    # Otherwise, return whichever side found something\n    return left if left else right\n# Build BST:\n#        6\n#       / \\\n#      2   8\n#     / \\ / \\\n#    0  4 7  9\n#      / \\\n#     3   5\nroot = TreeNode(6)\nroot.left = TreeNode(2, TreeNode(0), TreeNode(4, TreeNode(3), TreeNode(5)))\nroot.right = TreeNode(8, TreeNode(7), TreeNode(9))\np, q = root.left, root.left.right  # nodes 2 and 4\np, q = root.left, root.right       # nodes 2 and 8\n# General binary tree LCA (same tree)\np, q = root.left.right.left, root.left.right.right  # nodes 3 and 5\np, q = root.left.right.left, root.right.right  # nodes 3 and 9',
  E'class Solution {\n    public Object lcaBst(Object val, Object left, Object right) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    public static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n        TreeNode(int val, TreeNode left, TreeNode right) {\n            this.val = val;\n            this.left = left;\n            this.right = right;\n        }\n    }\n\n    public static TreeNode lcaBst(TreeNode root, TreeNode p, TreeNode q) {\n        TreeNode current = root;\n        while (current != null) {\n            if (p.val < current.val && q.val < current.val) {\n                current = current.left;\n            } else if (p.val > current.val && q.val > current.val) {\n                current = current.right;\n            } else {\n                return current;\n            }\n        }\n        return null;\n    }\n\n    public static TreeNode lcaBinaryTree(TreeNode root, TreeNode p, TreeNode q) {\n        // Base case\n        if (root == null || root == p || root == q) {\n            return root;\n        }\n        TreeNode left = lcaBinaryTree(root.left, p, q);\n        TreeNode right = lcaBinaryTree(root.right, p, q);\n        // If both sides found something, current node is LCA\n        if (left != null && right != null) {\n            return root;\n        }\n        // Otherwise, return whichever side found something\n        return (left != null) ? left : right;\n    }\n}',
  E'/**\n * @param {any, any, any} val, left, right\n * @return {any}\n */\nfunction lcaBst(val, left, right) {\n    // Your code here\n}',
  E'class TreeNode {\n    constructor(val = 0, left = null, right = null) {\n        this.val = val;\n        this.left = left;\n        this.right = right;\n    }\n}\n\nfunction lcaBst(root, p, q) {\n    let current = root;\n    while (current) {\n        if (p.val < current.val && q.val < current.val) {\n            current = current.left;\n        } else if (p.val > current.val && q.val > current.val) {\n            current = current.right;\n        } else {\n            return current;\n        }\n    }\n    return null;\n}\n\nfunction lcaBinaryTree(root, p, q) {\n    // Base case\n    if (!root || root === p || root === q) {\n        return root;\n    }\n    let left = lcaBinaryTree(root.left, p, q);\n    let right = lcaBinaryTree(root.right, p, q);\n    // If both sides found something, current node is LCA\n    if (left && right) {\n        return root;\n    }\n    // Otherwise, return whichever side found something\n    return left || right;\n}\n\n// Build BST:\n//        6\n//       / \\\n//      2   8\n//     / \\ / \\\n//    0  4 7  9\n//      / \\\n//     3   5\n// const root = new TreeNode(6);\n// root.left = new TreeNode(2, new TreeNode(0), new TreeNode(4, new TreeNode(3), new TreeNode(5)));\n// root.right = new TreeNode(8, new TreeNode(7), new TreeNode(9));\n// let p, q;\n// p = root.left; q = root.left.right; // nodes 2 and 4\n// p = root.left; q = root.right;       // nodes 2 and 8\n// // General binary tree LCA (same tree)\n// p = root.left.right.left; q = root.left.right.right;  // nodes 3 and 5\n// p = root.left.right.left; q = root.right.right;  // nodes 3 and 9',
