  'MinHeap',
  E'class MinHeap:\n    """\n    A min-heap implementation using an array.\n    The smallest element is always at the root (index 0).\n    """\n    def __init__(self):\n        self.data = []\n\n    def _parent(self, i: int) -> int:\n        return (i - 1) // 2\n\n    def _left(self, i: int) -> int:\n        return 2 * i + 1\n\n    def _right(self, i: int) -> int:\n        return 2 * i + 2\n\n    def _sift_up(self, i: int) -> None:\n        """Move element at index i up until heap property is restored."""\n        # TODO: While i > 0 and data[i] < data[parent(i)]:\n        #   swap data[i] with data[parent(i)]\n        #   move i to parent\n        pass\n\n    def _sift_down(self, i: int) -> None:\n        """Move element at index i down until heap property is restored."""\n        # TODO: Find the smallest among node and its children\n        # TODO: If smallest is not the node, swap and continue\n        # TODO: Handle case where right child may not exist\n        pass\n\n    def insert(self, val: int) -> None:\n        """Insert a value into the heap. Time: O(log n)."""\n        # TODO: Append to end, then sift up\n        pass\n\n    def extract_min(self) -> int:\n        """Remove and return the minimum element. Time: O(log n)."""\n        # TODO: Save root value\n        # TODO: Move last element to root\n        # TODO: Sift down\n        # TODO: Return saved value\n        pass\n\n    def peek(self) -> int:\n        """Return the minimum element without removing. Time: O(1)."""\n        return self.data[0]\n\n    def size(self) -> int:\n        return len(self.data)\n\n    def heapify(self, arr: list[int]) -> None:\n        """Build a heap from an array in O(n) time."""\n        # TODO: Set self.data = arr\n        # TODO: Start from last non-leaf node, sift down each\n        pass\n\nh = MinHeap()\nfor val in [5, 3, 8, 1, 2, 7]:\n    h.insert(val)\nh2 = MinHeap()\nh2.heapify([9, 5, 6, 2, 3])',
  E'class MinHeap:\n    """\n    A min-heap implementation using an array.\n    The smallest element is always at the root (index 0).\n    """\n    def __init__(self):\n        self.data = []\n\n    def _parent(self, i: int) -> int:\n        return (i - 1) // 2\n\n    def _left(self, i: int) -> int:\n        return 2 * i + 1\n\n    def _right(self, i: int) -> int:\n        return 2 * i + 2\n\n    def _sift_up(self, i: int) -> None:\n        """Move element at index i up until heap property is restored."""\n        while i > 0 and self.data[i] < self.data[self._parent(i)]:\n            pi = self._parent(i)\n            self.data[i], self.data[pi] = self.data[pi], self.data[i]\n            i = pi\n\n    def _sift_down(self, i: int) -> None:\n        """Move element at index i down until heap property is restored."""\n        n = len(self.data)\n        while True:\n            smallest = i\n            left = self._left(i)\n            right = self._right(i)\n\n            if left < n and self.data[left] < self.data[smallest]:\n                smallest = left\n            if right < n and self.data[right] < self.data[smallest]:\n                smallest = right\n            if smallest == i:\n                break\n            self.data[i], self.data[smallest] = self.data[smallest], self.data[i]\n            i = smallest\n    def insert(self, val: int) -> None:\n        """Insert a value into the heap. Time: O(log n)."""\n        self.data.append(val)\n        self._sift_up(len(self.data) - 1)\n\n    def extract_min(self) -> int:\n        """Remove and return the minimum element. Time: O(log n)."""\n        if len(self.data) == 1:\n            return self.data.pop()\n        root = self.data[0]\n        self.data[0] = self.data.pop()  # Move last to root\n        self._sift_down(0)\n        return root\n\n    def peek(self) -> int:\n        """Return the minimum element without removing. Time: O(1)."""\n        return self.data[0]\n\n    def size(self) -> int:\n        return len(self.data)\n\n    def heapify(self, arr: list[int]) -> None:\n        """Build a heap from an array in O(n) time."""\n        self.data = arr\n        # Start from last non-leaf node and sift down\n        n = len(self.data)\n        for i in range(n // 2 - 1, -1, -1):\n            self._sift_down(i)\n\nh = MinHeap()\nfor val in [5, 3, 8, 1, 2, 7]:\n    h.insert(val)\nh2 = MinHeap()\nh2.heapify([9, 5, 6, 2, 3])',
  E'class Solution {\n    public Object MinHeap() {\n        // Your code here\n        return null;\n    }\n}',
  E'import java.util.ArrayList;\nimport java.util.List;\nimport java.util.NoSuchElementException;\nimport java.util.Collections;\n\nclass Solution {\n    public static class MinHeap {\n        private List<Integer> data;\n\n        public MinHeap() {\n            this.data = new ArrayList<>();\n        }\n\n        private int _parent(int i) {\n            return (i - 1) / 2;\n        }\n\n        private int _left(int i) {\n            return 2 * i + 1;\n        }\n\n        private int _right(int i) {\n            return 2 * i + 2;\n        }\n\n        private void _siftUp(int i) {\n            while (i > 0 && data.get(i) < data.get(_parent(i))) {\n                int pi = _parent(i);\n                Collections.swap(data, i, pi);\n                i = pi;\n            }\n        }\n\n        private void _siftDown(int i) {\n            int n = data.size();\n            while (true) {\n                int smallest = i;\n                int left = _left(i);\n                int right = _right(i);\n\n                if (left < n && data.get(left) < data.get(smallest)) {\n                    smallest = left;\n                }\n                if (right < n && data.get(right) < data.get(smallest)) {\n                    smallest = right;\n                }\n                if (smallest == i) {\n                    break;\n                }\n                Collections.swap(data, i, smallest);\n                i = smallest;\n            }\n        }\n\n        public void insert(int val) {\n            this.data.add(val);\n            _siftUp(this.data.size() - 1);\n        }\n\n        public int extractMin() {\n            if (this.data.isEmpty()) {\n                throw new NoSuchElementException("Heap is empty");\n            }\n            if (this.data.size() == 1) {\n                return this.data.remove(0);\n            }\n            int root = this.data.get(0);\n            this.data.set(0, this.data.remove(this.data.size() - 1)); // Move last to root\n            _siftDown(0);\n            return root;\n        }\n\n        public int peek() {\n            if (this.data.isEmpty()) {\n                throw new NoSuchElementException("Heap is empty");\n            }\n            return this.data.get(0);\n        }\n\n        public int size() {\n            return this.data.size();\n        }\n\n        public void heapify(List<Integer> arr) {\n            this.data = new ArrayList<>(arr); // Copy the array\n            int n = this.data.size();\n            for (int i = n / 2 - 1; i >= 0; i--) {\n                _siftDown(i);\n            }\n        }\n    }\n}',
  E'/**\n * @param {} \n * @return {any}\n */\nfunction MinHeap() {\n    // Your code here\n}',
  E'class MinHeap {\n    /**\n     * A min-heap implementation using an array.\n     * The smallest element is always at the root (index 0).\n     */\n    constructor() {\n        this.data = [];\n    }\n\n    _parent(i) {\n        return Math.floor((i - 1) / 2);\n    }\n\n    _left(i) {\n        return 2 * i + 1;\n    }\n\n    _right(i) {\n        return 2 * i + 2;\n    }\n\n    _siftUp(i) {\n        /**Move element at index i up until heap property is restored.*/\n        while (i > 0 && this.data[i] < this.data[this._parent(i)]) {\n            const pi = this._parent(i);\n            [this.data[i], this.data[pi]] = [this.data[pi], this.data[i]];\n            i = pi;\n        }\n    }\n\n    _siftDown(i) {\n        /**Move element at index i down until heap property is restored.*/\n        const n = this.data.length;\n        while (true) {\n            let smallest = i;\n            const left = this._left(i);\n            const right = this._right(i);\n\n            if (left < n && this.data[left] < this.data[smallest]) {\n                smallest = left;\n            }\n            if (right < n && this.data[right] < this.data[smallest]) {\n                smallest = right;\n            }\n            if (smallest === i) {\n                break;\n            }\n            [this.data[i], this.data[smallest]] = [this.data[smallest], this.data[i]];\n            i = smallest;\n        }\n    }\n\n    insert(val) {\n        /**Insert a value into the heap. Time: O(log n).*/\n        this.data.push(val);\n        this._siftUp(this.data.length - 1);\n    }\n\n    extractMin() {\n        /**Remove and return the minimum element. Time: O(log n).*/\n        if (this.data.length === 0) {\n            return undefined; // Or throw an error, matching JS array behavior\n        }\n        if (this.data.length === 1) {\n            return this.data.pop();\n        }\n        const root = this.data[0];\n        this.data[0] = this.data.pop(); // Move last to root\n        this._siftDown(0);\n        return root;\n    }\n\n    peek() {\n        /**Return the minimum element without removing. Time: O(1).*/\n        return this.data.length > 0 ? this.data[0] : undefined;\n    }\n\n    size() {\n        return this.data.length;\n    }\n\n    heapify(arr) {\n        /**Build a heap from an array in O(n) time.*/\n        this.data = [...arr]; // Copy the array\n        // Start from last non-leaf node and sift down\n        const n = this.data.length;\n        for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {\n            this._siftDown(i);\n        }\n    }\n}',
