  E'class UnionFind:\n    """\n    Disjoint Set Union (Union-Find) with path compression\n    and union by rank.\n    Time per operation: O(alpha(n)) amortized ~ O(1)\n    Space: O(n)\n    """\n    def __init__(self, n: int):\n        """Initialize n elements (0 to n-1), each in its own set."""\n        # TODO: Initialize parent array where parent[i] = i\n        # TODO: Initialize rank array with all zeros\n        # TODO: Track the number of connected components\n        pass\n\n    def find(self, x: int) -> int:\n        """Find the root representative of x''s set with path compression."""\n        # TODO: If x is not its own parent, recursively find root\n        # TODO: Apply path compression: point x directly to root\n        # TODO: Return root\n        pass\n\n    def union(self, x: int, y: int) -> bool:\n        """\n        Merge the sets containing x and y.\n        Returns True if merge happened, False if already in same set.\n        Uses union by rank to keep trees balanced.\n        """\n        # TODO: Find roots of x and y\n        # TODO: If same root, return False (already connected)\n        # TODO: Attach smaller-rank tree under larger-rank tree\n        # TODO: If ranks equal, increment the new root''s rank\n        # TODO: Decrement component count\n        # TODO: Return True\n        pass\n\n    def connected(self, x: int, y: int) -> bool:\n        """Check if x and y are in the same set."""\n        # TODO: Compare roots\n        pass\n\n    def count(self) -> int:\n        """Return the number of disjoint sets."""\n        # TODO: Return component count\n        pass\n\nuf = UnionFind(7)\nuf.union(0, 1)\nuf.union(1, 2)\nuf.union(3, 4)\nuf.union(5, 6)\nuf.union(2, 4)\n# Cycle detection using Union-Find\ndef has_cycle_undirected(n: int, edges: list[list[int]]) -> bool:\n    """Detect cycle in an undirected graph using Union-Find."""\n    # TODO: Create UnionFind with n nodes\n    # TODO: For each edge, if union returns False, cycle exists\n    pass',
  E'class UnionFind:\n    """\n    Disjoint Set Union (Union-Find) with path compression\n    and union by rank.\n    Time per operation: O(alpha(n)) amortized ~ O(1)\n    Space: O(n)\n    """\n    def __init__(self, n: int):\n        """Initialize n elements (0 to n-1), each in its own set."""\n        self.parent = list(range(n))  # Each node is its own parent\n        self.rank = [0] * n           # Initial rank is 0\n        self.components = n           # Each element starts as its own set\n\n    def find(self, x: int) -> int:\n        """Find the root representative of x''s set with path compression."""\n        if self.parent[x] != x:\n            self.parent[x] = self.find(self.parent[x])  # Path compression\n        return self.parent[x]\n\n    def union(self, x: int, y: int) -> bool:\n        """\n        Merge the sets containing x and y.\n        Returns True if merge happened, False if already in same set.\n        Uses union by rank to keep trees balanced.\n        """\n        root_x = self.find(x)\n        root_y = self.find(y)\n\n        if root_x == root_y:\n            return False  # Already in the same set\n        # Union by rank: attach smaller tree under larger tree\n        if self.rank[root_x] < self.rank[root_y]:\n            root_x, root_y = root_y, root_x  # Ensure root_x has higher rank\n        self.parent[root_y] = root_x\n        if self.rank[root_x] == self.rank[root_y]:\n            self.rank[root_x] += 1\n        self.components -= 1\n        return True\n    def connected(self, x: int, y: int) -> bool:\n        """Check if x and y are in the same set."""\n        return self.find(x) == self.find(y)\n\n    def count(self) -> int:\n        """Return the number of disjoint sets."""\n        return self.components\n\nuf = UnionFind(7)\nuf.union(0, 1)\nuf.union(1, 2)\nuf.union(3, 4)\nuf.union(5, 6)\nuf.union(2, 4)\n# Cycle detection using Union-Find\ndef has_cycle_undirected(n: int, edges: list[list[int]]) -> bool:\n    """Detect cycle in an undirected graph using Union-Find."""\n    uf = UnionFind(n)\n    for u, v in edges:\n        if not uf.union(u, v):\n            return True  # u and v already connected — cycle!\n    return False',
  E'class Solution {\n    public Object hasCycleUndirected(int n) {\n        // Your code here\n        return null;\n    }\n}',
  E'class Solution {\n    static class UnionFind {\n        int[] parent;\n        int[] rank;\n        int components;\n\n        public UnionFind(int n) {\n            parent = new int[n];\n            for (int i = 0; i < n; i++) {\n                parent[i] = i;\n            }\n            rank = new int[n]; // Initial rank is 0\n            components = n;    // Each element starts as its own set\n        }\n\n        public int find(int x) {\n            if (parent[x] == x) {\n                return x;\n            }\n            parent[x] = find(parent[x]); // Path compression\n            return parent[x];\n        }\n\n        public boolean union(int x, int y) {\n            int rootX = find(x);\n            int rootY = find(y);\n\n            if (rootX != rootY) {\n                // Union by rank\n                if (rank[rootX] < rank[rootY]) {\n                    parent[rootX] = rootY;\n                } else if (rank[rootX] > rank[rootY]) {\n                    parent[rootY] = rootX;\n                } else {\n                    parent[rootY] = rootX;\n                    rank[rootX]++;\n                }\n                components--;\n                return true;\n            }\n            return false;\n        }\n    }\n\n    public static boolean hasCycleUndirected(int n, int[][] edges) {\n        UnionFind uf = new UnionFind(n);\n\n        for (int[] edge : edges) {\n            int u = edge[0];\n            int v = edge[1];\n\n            // If u and v are already in the same set, adding this edge creates a cycle\n            if (uf.find(u) == uf.find(v)) {\n                return true;\n            }\n            // Otherwise, union them\n            uf.union(u, v);\n        }\n        return false;\n    }\n}''s set with path compression."""\n    //         if self.parent[x] != x:\n    //             self.parent[x] = self.find(self.parent[x])  # Path compression\n    //         return self.parent[x]\n    // \n    //     def union(self, x: int, y: int) -> bool:\n    //         """\n    //         Merge the sets containing x and y.\n    //         Returns True if merge happened, False if already in same set.\n    //         Uses union by rank to keep trees balanced.\n    //         """\n    //         root_x = self.find(x)\n    //         root_y = self.find(y)\n    // \n    //         if root_x == root_y:\n    //             return False  # Already in the same set\n    // \n    //         # Union by rank: attach smaller tree under larger tree\n    //         if self.rank[root_x] < self.rank[root_y]:\n    //             root_x, root_y = root_y, root_x  # Ensure root_x has higher rank\n    //         self.parent[root_y] = root_x\n    // \n    //         if self.rank[root_x] == self.rank[root_y]:\n    //             self.rank[root_x] += 1\n    // \n    //         self.components -= 1\n    //         return True\n    // \n    //     def connected(self, x: int, y: int) -> bool:\n    //         """Check if x and y are in the same set."""\n    //         return self.find(x) == self.find(y)\n    // \n    //     def count(self) -> int:\n    //         """Return the number of disjoint sets."""\n    //         return self.components\n    // \n    // \n    // uf = UnionFind(7)\n    // \n    // uf.union(0, 1)\n    // uf.union(1, 2)\n    // \n    // uf.union(3, 4)\n    // uf.union(5, 6)\n    // \n    // uf.union(2, 4)\n    // \n    // # Cycle detection using Union-Find\n    // def has_cycle_undirected(n: int, edges: list[list[int]]) -> bool:\n    //     """Detect cycle in an undirected graph using Union-Find."""\n    //     uf = UnionFind(n)\n    //     for u, v in edges:\n    //         if not uf.union(u, v):\n    //             return True  # u and v already connected — cycle!\n    //     return False\n    // \n    // \n}',
  E'/**\n * @param {any} n\n * @return {any}\n */\nfunction hasCycleUndirected(n) {\n    // Your code here\n}',
  E'class UnionFind {\n    constructor(n) {\n        this.parent = Array.from({ length: n }, (_, i) => i); // Each node is its own parent\n        this.rank = new Array(n).fill(0);                     // Initial rank is 0\n        this.components = n;                                  // Each element starts as its own set\n    }\n\n    find(x) {\n        if (this.parent[x] === x) {\n            return x;\n        }\n        this.parent[x] = this.find(this.parent[x]); // Path compression\n        return this.parent[x];\n    }\n\n    union(x, y) {\n        let rootX = this.find(x);\n        let rootY = this.find(y);\n\n        if (rootX !== rootY) {\n            // Union by rank\n            if (this.rank[rootX] < this.rank[rootY]) {\n                this.parent[rootX] = rootY;\n            } else if (this.rank[rootX] > this.rank[rootY]) {\n                this.parent[rootY] = rootX;\n            } else {\n                this.parent[rootY] = rootX;\n                this.rank[rootX]++;\n            }\n            this.components--;\n            return true;\n        }\n        return false;\n    }\n}\n\nfunction hasCycleUndirected(n, edges) {\n    const uf = new UnionFind(n);\n\n    for (const [u, v] of edges) {\n        // If u and v are already in the same set, adding this edge creates a cycle\n        if (uf.find(u) === uf.find(v)) {\n            return true;\n        }\n        // Otherwise, union them\n        uf.union(u, v);\n    }\n    return false;\n}\n\n---',
