  E'class Solution {\n    static class TrieNode {\n        Map<Character, TrieNode> children;\n        boolean isEnd;\n        String word;\n\n        public TrieNode() {\n            children = new HashMap<>();\n            isEnd = false;\n            word = null;\n        }\n    }\n\n    public static class AutoComplete {\n        private TrieNode root;\n\n        public AutoComplete() {\n            this.root = new TrieNode();\n        }\n\n        public void insert(String word) {\n            TrieNode node = this.root;\n            for (char char_ : word.toCharArray()) {\n                node.children.putIfAbsent(char_, new TrieNode());\n                node = node.children.get(char_);\n            }\n            node.isEnd = true;\n            node.word = word;\n        }\n\n        public List<String> suggest(String prefix, int maxResults) {\n            TrieNode node = this.root;\n            for (char char_ : prefix.toCharArray()) {\n                if (!node.children.containsKey(char_)) {\n                    return new ArrayList<>();\n                }\n                node = node.children.get(char_);\n            }\n\n            List<String> results = new ArrayList<>();\n            _dfsCollect(node, results, maxResults);\n            return results;\n        }\n\n        private void _dfsCollect(TrieNode node, List<String> results, int maxResults) {\n            if (results.size() >= maxResults) {\n                return;\n            }\n\n            if (node.isEnd) {\n                results.add(node.word);\n            }\n\n            List<Character> sortedChars = new ArrayList<>(node.children.keySet());\n            Collections.sort(sortedChars);\n\n            for (char char_ : sortedChars) {\n                if (results.size() >= maxResults) {\n                    return;\n                }\n                _dfsCollect(node.children.get(char_), results, maxResults);\n            }\n        }\n    }\n}''app'', ''apple'', ''application'', ''apply'']\n    // \n    // # [''balance'', ''ball'', ''bat'']\n    // \n    // # [''bat'', ''batch'', ''bath'']\n    // \n    // # []\n    // \n    // # [''app'', ''apple'']\n    // \n}',
